INSERT INTO characters (char, data) VALUES ('鞓', '{"9000": "7009.0", "Chữ Trung Quốc": "鞓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 16 | nét | 鞓 | đình | tượng hình | dây lưng, đai da (cổ) | 鞓 thuộc bộ 革 (cách — da thuộc). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng trong Wiktionary; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đình\": bộ 革 (cách — da thuộc) — chiếc đai da \"đình\" đặc, thắt quanh thắt lưng quan lại thời xưa. | Gương Hán-Việt | \"đình\" — âm Hán-Việt ít dùng trong từ thông dụng hiện đại | Mở khoá kiến thức | 鞓 là chữ cổ; bộ 革 kết nối: 靴 (ngoa — giày da), 鞭 (tiên — roi), 鞍 (an — yên ngựa), 靹 (da nhuộm).", "Tự nguyên_Xie": "鞓 thuộc bộ 革 (cách — da thuộc, đồ da). Theo Wiktionary: nghĩa là dây lưng bằng da, đai thắt lưng. Không có dữ liệu glyphOrigin có cấu trúc. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây thắt lưng bằng da, đai da", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 呈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革呈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "呈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞓", "Unihan_Traditional (Chữ Phồn thể)": "鞓", "Pinyin_Xie": "tīng", "Âm Hán Việt_Xie": "thinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Được dùng làm danh từ chỉ bộ phận dây da của đai lưng thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穊', '{"9000": "7010.0", "Chữ Trung Quốc": "穊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 14 | nét | 穊 | cấy | tượng hình | dày đặc, mọc ken dày (cổ) | 穊 thuộc bộ 禾 (hòa — lúa, ngũ cốc). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng trong Wiktionary (chỉ {{rfdef|zh}}); chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cấy\": bộ 禾 (hòa — lúa) — cây lúa \"cấy\" ken dày, hàng hàng sát nhau. | Gương Hán-Việt | \"cấy\" trong nghĩa cấy trồng dày đặc — ít dùng trong từ thông dụng hiện đại | Mở khoá kiến thức | 穊 là chữ cổ hiếm; bộ 禾 kết nối: 稻 (đạo — lúa nước), 稀 (hi — thưa), 稠 (trù — dày đặc), 種 (chủng — giống).", "Tự nguyên_Xie": "穊 thuộc bộ 禾 (hòa — lúa, ngũ cốc). Nghĩa: mọc dày đặc, ken sít nhau (về cây lúa). Không có dữ liệu glyphOrigin có cấu trúc từ Wiktionary. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dày đặc; đông nghịt; đông đúc", "Hạng Tần Suất (Jun Da)": "7010.0", "Tần Suất % (Jun Da)": "99.9970284855", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 既", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾既", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "既", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "穊", "Unihan_Traditional (Chữ Phồn thể)": "穊", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "ký", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Dùng làm tính từ để miêu tả trạng thái cây cối mọc dày hoặc sự vật đông đúc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕡', '{"9000": "7011.0", "Chữ Trung Quốc": "蕡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕡 | phần | tượng hình | hạt gai dầu; sum suê, trĩu quả | 蕡 thuộc bộ 艸/艹 (thảo — cỏ, thực vật). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng trong Wiktionary; chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phần\": bộ 艸 (thảo — cây cỏ) — cây gai dầu \"phần\" phần nặng trĩu hạt, sum suê như trong Kinh Thi. | Gương Hán-Việt | \"phần\" — âm Hán-Việt ít dùng trong từ thông dụng hiện đại | Mở khoá kiến thức | 蕡 xuất hiện trong Kinh Thi; bộ 艸 kết nối: 蔟 (cụm), 蕉 (tiêu — chuối), 藥 (dược).", "Tự nguyên_Xie": "Tiểu triện | 蕡 thuộc bộ 艸 (thảo — thực vật). Theo Wiktionary: nghĩa là hạt cây gai dầu (hemp seeds), hoặc sum suê trĩu quả. Xuất hiện trong Kinh Thi: \"有蕡其實\" = quả trĩu nặng. Không có dữ liệu glyphOrigin có cấu trúc. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây sai quả; hạt gai", "Hạng Tần Suất (Jun Da)": "7011.0", "Tần Suất % (Jun Da)": "99.9970315862", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 賁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹賁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "賁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕡", "Unihan_Traditional (Chữ Phồn thể)": "蕡", "Pinyin_Xie": "fén", "Âm Hán Việt_Xie": "phần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ chỉ cây cối sai quả hoặc danh từ chỉ hạt gai. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鑨', '{"9000": "7012.0", "Chữ Trung Quốc": "鑨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 24 | nét | 鑨 | xuổng | tượng hình | loại cuốc hoặc dụng cụ kim loại dài | 鑨 thuộc bộ 金 (kim — kim loại). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng; không có glyphOrigin. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xuổng\": bộ 金 (kim — kim loại) — dụng cụ kim loại \"xuổng\" dài, dùng đào bới. | Gương Hán-Việt | \"xuổng\" — âm Hán-Việt ít dùng trong từ thông dụng | Mở khoá kiến thức | 鑨 là chữ hiếm; bộ 金 kết nối: 鋤 (cuốc), 钁 (cuốc lớn), 鍬 (xẻng).", "Tự nguyên_Xie": "鑨 thuộc bộ 金 (kim — kim loại). Không có dữ liệu glyphOrigin từ Wiktionary. Nghĩa liên quan đến dụng cụ kim loại. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên người)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 龍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金龍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鑨", "Unihan_Traditional (Chữ Phồn thể)": "鑨", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "lung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong cổ ngữ hoặc dùng làm tên riêng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('楱', '{"9000": "7013.0", "Chữ Trung Quốc": "楱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 楱 | táu | tượng hình | loại cây gỗ (cổ) | 楱 thuộc bộ 木 (mộc — cây gỗ). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng trong Wiktionary (chỉ {{rfdef|zh}}); chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táu\": bộ 木 (mộc — cây gỗ) — cây gỗ \"táu\" cứng chắc, vật liệu quý thời xưa. | Gương Hán-Việt | \"táu\" — âm Hán-Việt ít dùng trong từ thông dụng hiện đại | Mở khoá kiến thức | 楱 là chữ cổ hiếm; bộ 木 kết nối: 松 (tùng), 柏 (bách), 樟 (chương), 楠 (nam — gỗ nam).", "Tự nguyên_Xie": "楱 thuộc bộ 木 (mộc — cây gỗ). Không có dữ liệu glyphOrigin có cấu trúc từ Wiktionary. Nghĩa chưa xác định rõ (rfdef). Dựa vào bộ thủ, chữ liên quan đến cây gỗ. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "táu; như \"gỗ táu\"", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "楱", "Unihan_Traditional (Chữ Phồn thể)": "楱", "Pinyin_Xie": "zòu", "Âm Hán Việt_Xie": "thấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại cây thân gỗ hoặc quả của nó. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靹', '{"9000": "7014.0", "Chữ Trung Quốc": "靹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 13 | nét | 靹 | nạp | tượng hình | da thuộc nhuộm màu (cổ) | 靹 thuộc bộ 革 (cách — da thuộc). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng; không có glyphOrigin. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nạp\": bộ 革 (cách — da thuộc) — tấm da thuộc \"nạp\" màu, chế tác tỉ mỉ. | Gương Hán-Việt | \"nạp\" — âm Hán-Việt ít dùng trong từ thông dụng | Mở khoá kiến thức | 靹 là chữ hiếm; bộ 革 kết nối: 靴 (ngoa — giày da), 鞓 (đình — đai da), 鞭 (tiên — roi), 鞍 (an — yên ngựa).", "Tự nguyên_Xie": "靹 thuộc bộ 革 (cách — da thuộc). Không có dữ liệu glyphOrigin từ Wiktionary. Nghĩa liên quan đến da thuộc hoặc đồ da. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gà lôi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 内", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革内", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "内", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "靹", "Unihan_Traditional (Chữ Phồn thể)": "靹", "Pinyin_Xie": "nà", "Âm Hán Việt_Xie": "nạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loại giày làm bằng da hoặc chất liệu da mềm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鷃', '{"9000": "7015.0", "Chữ Trung Quốc": "鷃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 21 | nét | 鷃 | yến | tượng hình | chim yến nhỏ (cổ) | 鷃 thuộc bộ 鳥 (điểu — chim). Cấu trúc nội bộ không có phân tích rõ ràng; không có glyphOrigin. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yến\": bộ 鳥 (điểu — chim) — chim \"yến\" nhỏ bé cười chê đại bàng trong Trang Tử, đại diện tầm nhìn hạn hẹp. | Gương Hán-Việt | \"yến\" — âm Hán-Việt, liên quan đến chim nhỏ trong văn học cổ | Mở khoá kiến thức | 鷃 nổi tiếng qua Trang Tử; bộ 鳥 kết nối: 鵬 (bằng — chim bằng to lớn), 鷹 (ưng), 燕 (yến — chim én).", "Tự nguyên_Xie": "鷃 thuộc bộ 鳥 (điểu — chim). Không có dữ liệu glyphOrigin từ Wiktionary. Nghĩa: loài chim nhỏ, được nhắc đến trong Trang Tử (Bắc Minh hữu ngư, 鷃嗤笑之). Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim sâu, chim cun cút", "Hạng Tần Suất (Jun Da)": "7015.0", "Tần Suất % (Jun Da)": "99.997043989", "GavinGrover_Once (Chiết tự trực tiếp)": "晏 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰晏鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "晏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鷃", "Unihan_Traditional (Chữ Phồn thể)": "鷃", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "yến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loài chim nhỏ giống chim cút. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼱', '{"9000": "7016.0", "Chữ Trung Quốc": "鼱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼠 | Số nét | 21 | nét | 鼱 | tinh | tượng hình | chuột chù (shrew) | 鼱 thuộc bộ 鼠 (thử — chuột). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng trong Wiktionary; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tinh\": bộ 鼠 (thử — chuột) — con chuột chù \"tinh\" anh bé tí, tinh ranh nhất trong loài gặm nhấm. | Gương Hán-Việt | \"tinh\" — âm Hán-Việt ít dùng trong từ thông dụng | Mở khoá kiến thức | 鼱 thường gặp trong 鼩鼱; bộ 鼠 kết nối: 鼠 (thử — chuột), 鼩 (chuột chù nhỏ).", "Tự nguyên_Xie": "鼱 thuộc bộ 鼠 (thử — chuột). Theo Wiktionary, dùng trong tên ghép 鼩鼱 (chuột chù — shrew). Không có dữ liệu glyphOrigin có cấu trúc. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con cù tinh (một loài chuột xạ, sống ở trong rừng, da rất quý)", "Hạng Tần Suất (Jun Da)": "7016.0", "Tần Suất % (Jun Da)": "99.9970470897", "GavinGrover_Once (Chiết tự trực tiếp)": "鼠 + 青", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鼠青", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "青", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼠", "Unihan_Simplified (Chữ Giản thể)": "鼱", "Unihan_Traditional (Chữ Phồn thể)": "鼱", "Pinyin_Xie": "jīng", "Âm Hán Việt_Xie": "tinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong tổ hợp từ để chỉ loài chuột chù. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眫', '{"9000": "7017.0", "Chữ Trung Quốc": "眫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 10 | nét | 眫 | mị | tượng hình | mắt nhìn lệch hoặc mờ (cổ) | 眫 thuộc bộ 目 (mục — mắt). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng; không có glyphOrigin. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mị\": bộ 目 (mục — mắt) — đôi mắt \"mị\" hoặc, nhìn không thẳng, mơ màng. | Gương Hán-Việt | \"mị\" — âm Hán-Việt ít dùng trong từ thông dụng | Mở khoá kiến thức | 眫 là chữ cổ hiếm; bộ 目 kết nối: 眼 (nhãn — mắt), 看 (xem), 眩 (huyễn — chóng mặt), 眯 (nheo mắt).", "Tự nguyên_Xie": "眫 thuộc bộ 目 (mục — mắt). Không có dữ liệu glyphOrigin từ Wiktionary. Nghĩa liên quan đến trạng thái mắt (nhìn lệch, mờ). Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "竫", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 半", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目半", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "半", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眫", "Unihan_Traditional (Chữ Phồn thể)": "眫", "Pinyin_Xie": "mǐ", "Âm Hán Việt_Xie": "mị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Dùng làm tính từ miêu tả mắt nhỏ hoặc động từ chỉ hành động nhìn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艆', '{"9000": "7018.0", "Chữ Trung Quốc": "艆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 13 | nét | 艆 | lang | tượng hình | thuyền lang (cổ) | 艆 thuộc bộ 舟 (chu — thuyền bè). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng; không có glyphOrigin. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lang\": bộ 舟 (chu — thuyền) — con thuyền \"lang\" thang trên sông, dạt theo dòng. | Gương Hán-Việt | \"lang\" — âm Hán-Việt ít dùng trong từ thông dụng | Mở khoá kiến thức | 艆 là chữ hiếm; bộ 舟 kết nối: 舟 (chu — thuyền), 船 (thuyền), 艞 (diệu — thuyền lớn), 艇 (đình).", "Tự nguyên_Xie": "艆 thuộc bộ 舟 (chu — thuyền). Không có dữ liệu glyphOrigin từ Wiktionary. Nghĩa liên quan đến loại thuyền bè. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "艆", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 良", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟良", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "良", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艆", "Unihan_Traditional (Chữ Phồn thể)": "艆", "Pinyin_Xie": "láng", "Âm Hán Việt_Xie": "lang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại thuyền lớn thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褯', '{"9000": "7019.0", "Chữ Trung Quốc": "褯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 15 | nét | 褯 | tích | tượng hình | tã lót, khăn quấn trẻ em (cổ) | 褯 thuộc bộ 衣 (y — vải vóc, y phục). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng; không có glyphOrigin. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": bộ 衣 (y — vải) — tấm vải \"tích\" nhỏ quấn quanh em bé sơ sinh, tã lót thời xưa. | Gương Hán-Việt | \"tích\" — âm Hán-Việt ít dùng trong từ thông dụng | Mở khoá kiến thức | 褯 là chữ cổ; bộ 衣 kết nối: 被 (bị — chăn), 衫 (sam — áo), 褲 (khố — quần), 袍 (bào — áo dài).", "Tự nguyên_Xie": "褯 thuộc bộ 衣 (y — vải, y phục). Không có dữ liệu glyphOrigin từ Wiktionary. Nghĩa: tã lót, khăn quấn trẻ sơ sinh. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tã lót", "Hạng Tần Suất (Jun Da)": "7019.0", "Tần Suất % (Jun Da)": "99.9970563919", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 席", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤席", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "席", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褯", "Unihan_Traditional (Chữ Phồn thể)": "褯", "Pinyin_Xie": "jiè", "Âm Hán Việt_Xie": "tạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ tấm tã lót cho trẻ sơ sinh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('剞', '{"9000": "7020.0", "Chữ Trung Quốc": "剞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 10 | nét | 剞 | kỳ | tượng hình | dao cong khắc gỗ; cướp đoạt (cổ) | 剞 thuộc bộ 刀/刂 (đao — dao, lưỡi cắt). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng trong Wiktionary; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": bộ 刀 (đao — dao) — chiếc dao cong \"kỳ\" lạ dùng để khắc gỗ in sách thời xưa. | Gương Hán-Việt | \"kỳ\" trong \"kỳ dị\" — nghĩa hình dạng dao cong kỳ lạ; ít dùng trong từ thông dụng | Mở khoá kiến thức | 剞 thường gặp trong 剞劂 (nghề khắc in); bộ 刀 kết nối: 刻 (khắc), 劍 (kiếm), 刊 (khắc/in).", "Tự nguyên_Xie": "Tiểu triện | 剞 thuộc bộ 刀/刂 (đao — dao). Theo Wiktionary: dùng trong tổ hợp 剞劂 (dao khắc gỗ, thợ khắc in), và nghĩa phụ là cướp đoạt. Không có dữ liệu glyphOrigin có cấu trúc. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: kỷ quyết 剞劂)", "Hạng Tần Suất (Jun Da)": "7020.0", "Tần Suất % (Jun Da)": "99.9970594926", "GavinGrover_Once (Chiết tự trực tiếp)": "奇 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰奇刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "剞", "Unihan_Traditional (Chữ Phồn thể)": "剞", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "kỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm danh từ chỉ dao khắc hoặc động từ chỉ việc khắc chữ lên gỗ, chủ yếu dùng trong từ ghép kỳ quyết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔟', '{"9000": "7021.0", "Chữ Trung Quốc": "蔟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 蔟 | thốc | tượng hình | giàn tằm nhả tơ; tên âm luật | 蔟 thuộc bộ 艸/艹 (thảo — cỏ, thực vật). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng trong Wiktionary; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thốc\": bộ 艸 (thảo — cây cỏ) — giàn cỏ \"thốc\" cho con tằm leo lên nhả tơ vàng. | Gương Hán-Việt | \"thốc\" — âm Hán-Việt ít dùng trong từ thông dụng hiện đại | Mở khoá kiến thức | 蔟 nằm trong nhóm từ nghề tằm tơ; bộ 艸 kết nối: 蠶 (tằm), 桑 (tang — cây dâu), 繭 (kiến — tơ kén).", "Tự nguyên_Xie": "Tiểu triện | 蔟 thuộc bộ 艸 (thảo — thực vật). Theo Wiktionary: nghĩa 1 (âm cù) — giàn (frame) để tằm nhả tơ, dùng trong nghề trồng dâu nuôi tằm; nghĩa 2 (âm còu) — tên một âm luật cổ (太蔟/大蔟). Không có dữ liệu glyphOrigin có cấu trúc. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái né tằm", "Hạng Tần Suất (Jun Da)": "7021.0", "Tần Suất % (Jun Da)": "99.9970625933", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 族", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹族", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "族", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔟", "Unihan_Traditional (Chữ Phồn thể)": "蔟", "Pinyin_Xie": "cù", "Âm Hán Việt_Xie": "thấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ ổ tằm hoặc động từ chỉ sự tụ tập, gom lại thành cụm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靿', '{"9000": "7022.0", "Chữ Trung Quốc": "靿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 14 | nét | 靿 | diệu | tượng hình | cổ ống giày, ống tất | 靿 thuộc bộ 革 (cách — da thuộc). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng trong Wiktionary; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diệu\": bộ 革 (cách — da thuộc) — phần ống da \"diệu\" cao của chiếc ủng, bao quanh cổ chân. | Gương Hán-Việt | \"diệu\" — âm Hán-Việt ít dùng trong từ thông dụng | Mở khoá kiến thức | 靿 là bộ phận giày da; bộ 革 kết nối: 靴 (ngoa — ủng), 鞋 (hài — giày), 鞓 (đình — đai lưng), 鞍 (an).", "Tự nguyên_Xie": "靿 thuộc bộ 革 (cách — da thuộc). Theo Wiktionary: nghĩa là ống cổ giày hoặc cổ tất. Dùng trong các từ như 高靿 (cổ cao), 靴靿 (cổ ủng). Không có dữ liệu glyphOrigin có cấu trúc. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỗ mũi giày uốn cong", "Hạng Tần Suất (Jun Da)": "7022.0", "Tần Suất % (Jun Da)": "99.997065694", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 幼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革幼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "靿", "Unihan_Traditional (Chữ Phồn thể)": "靿", "Pinyin_Xie": "yào", "Âm Hán Việt_Xie": "áo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ phần cổ cao hoặc ống của các loại giày ủng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘼', '{"9000": "7023.0", "Chữ Trung Quốc": "瘼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 15 | nét | 瘼 | mạc | tượng hình | bệnh tật; khổ sở (văn học) | 瘼 thuộc bộ 疒 (nạch — bệnh tật). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng trong Wiktionary; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạc\": bộ 疒 (nạch — bệnh) — cái bệnh \"mạc\" vô phương chữa, nỗi khổ đau trong Kinh Thi. | Gương Hán-Việt | \"mạc\" — âm Hán-Việt ít dùng trong từ thông dụng hiện đại | Mở khoá kiến thức | 瘼 xuất hiện trong Kinh Thi; bộ 疒 kết nối: 病 (bệnh), 痛 (thống — đau), 疾 (tật — bệnh), 痘 (đậu).", "Tự nguyên_Xie": "Tiểu triện | 瘼 thuộc bộ 疒 (nạch — bệnh tật). Theo Wiktionary (Thuyết Văn): 瘼，病也 (bệnh tật). Xuất hiện trong Kinh Thi: \"亂離瘼矣，爰其適歸\" = giữa loạn lạc khổ sở, biết nơi đâu về. Nghĩa văn học: khổ sở, đau khổ do tai họa. Chưa có nguồn học thuật về cấu trúc glyph chuyên sâu. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ách nạn, khổ bệnh", "Hạng Tần Suất (Jun Da)": "7023.0", "Tần Suất % (Jun Da)": "99.9970718954", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 莫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒莫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "莫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘼", "Unihan_Traditional (Chữ Phồn thể)": "瘼", "Pinyin_Xie": "mò", "Âm Hán Việt_Xie": "mạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn cổ để chỉ nỗi khổ cực, bệnh tật của nhân dân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酴', '{"9000": "7024.0", "Chữ Trung Quốc": "酴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 14 | nét | 酴 | đồ | tượng hình | men rượu; hoa tường vi trắng (酴醾) | 酴 thuộc bộ 酉 (dậu — rượu, men). Cấu trúc nội bộ không có phân tích hình thanh/hội ý rõ ràng trong Wiktionary; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồ\": bộ 酉 (dậu — rượu) — men rượu \"đồ\" ủ, hoặc hoa tường vi trắng ngát tên \"đồ\" từ xưa. | Gương Hán-Việt | \"đồ\" — âm Hán-Việt ít dùng trong từ thông dụng hiện đại | Mở khoá kiến thức | 酴 thường gặp trong 酴醾 (hoa/rượu); bộ 酉 kết nối: 酒 (tửu — rượu), 醉 (túy — say), 醇 (thuần — rượu ngon).", "Tự nguyên_Xie": "Tiểu triện | 酴 thuộc bộ 酉 (dậu — rượu, men rượu). Theo Wiktionary: dùng trong 酴醾 (tên loài hoa tường vi trắng, tên rượu ngon) và 酴酒 (rượu men). Không có dữ liệu glyphOrigin có cấu trúc. Chưa có nguồn học thuật chuyên sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "men rượu", "Hạng Tần Suất (Jun Da)": "7024.0", "Tần Suất % (Jun Da)": "99.9970749961", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 余", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉余", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "余", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酴", "Unihan_Traditional (Chữ Phồn thể)": "酴", "Pinyin_Xie": "tú", "Âm Hán Việt_Xie": "đồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các từ ghép chỉ tên rượu cổ hoặc các loài hoa liên quan đến rượu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼢', '{"9000": "7025.0", "Chữ Trung Quốc": "鼢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼠 | Số nét | 17 | nét | 鼠 | thử | biểu nghĩa | chuột | 分 | phân | biểu âm | chia | 鼢 = 鼠 (Thử, biểu nghĩa: chuột) + 分 (Phân, biểu âm); chữ hình thanh. Bộ 鼠 cho biết nghĩa liên quan đến loài gặm nhấm; 分 cung cấp âm đọc fén.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"鼢\" (chuột chũi): con chuột (鼠) phân chia (分) đất bằng cách khoét hang — zokor đào đường ngầm dưới ruộng. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 鼢 giúp nhận ra các chữ bộ 鼠 chỉ họ gặm nhấm: 鼹 (chuột chũi), 鼬 (chồn), 鼩 (chuột nhím).", "Tự nguyên_Xie": "Đại triện | Chữ hình thanh: 鼠 (thử) biểu nghĩa chỉ loài gặm nhấm, 分 (phân) biểu âm cho âm fén. 鼢 chỉ loài chuột chũi (zokor) sống dưới đất, đào hang trong đất canh tác. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con chuột cống", "Hạng Tần Suất (Jun Da)": "7025.0", "Tần Suất % (Jun Da)": "99.9970780968", "GavinGrover_Once (Chiết tự trực tiếp)": "鼠 + 分", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鼠分", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼠", "Unihan_Simplified (Chữ Giản thể)": "鼢", "Unihan_Traditional (Chữ Phồn thể)": "鼢", "Pinyin_Xie": "fén", "Âm Hán Việt_Xie": "phẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loài chuột chuyên đào đất hoặc chuột cống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睆', '{"9000": "7026.0", "Chữ Trung Quốc": "睆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 12 | nét | 睆 | 睆 | tượng hình | sáng đẹp, rực rỡ | 睆 là chữ độc thể, bộ thủ là 目 (mục, mắt). Không có dữ liệu phân tích hình thanh hay hội ý từ Wiktionary; chữ có bộ 目 gợi liên quan đến thị giác hoặc vẻ đẹp nhìn thấy được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"睆\": đôi mắt (目) nhìn vào vẻ sáng đẹp — chữ gợi ánh sáng rực rỡ qua con mắt quan sát. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết bộ 目 trong 睆 giúp nhận ra các chữ liên quan đến mắt và thị giác: 眼 (nhãn), 看 (khán), 相 (tương).", "Tự nguyên_Xie": "Wiktionary chỉ ghi nhận âm đọc mà không cung cấp phân tích cấu trúc cho 睆. Chữ mang nghĩa sáng đẹp, rực rỡ. Chưa có nguồn học thuật về nguồn gốc cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tốt đẹp", "Hạng Tần Suất (Jun Da)": "7026.0", "Tần Suất % (Jun Da)": "99.9970811976", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 完", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目完", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "完", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睆", "Unihan_Traditional (Chữ Phồn thể)": "睆", "Pinyin_Xie": "huàn", "Âm Hán Việt_Xie": "hoản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho mắt hoặc vẻ ngoài tròn trịa, tươi sáng trong thơ cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硁', '{"9000": "7027.0", "Chữ Trung Quốc": "硁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 硁 | 硁 | tượng hình | tiếng đá gõ vào nhau | 硁 là chữ độc thể với bộ 石 (thạch, đá). Không có dữ liệu phân tích cấu trúc từ Wiktionary. Bộ 石 gợi liên quan đến chất liệu đá và âm thanh va chạm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"硁\": viên đá (石) kêu leng keng — âm thanh sắc bén phát ra khi đá va chạm nhau. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết bộ 石 trong 硁 kết nối với 硬 (ngạnh, cứng), 碰 (bụng, va chạm), 研 (nghiên, mài nghiền).", "Tự nguyên_Xie": "Tiểu triện | Không có nguồn Wiktionary phân tích cấu trúc cho 硁. Chữ thuộc bộ 石 (thạch), nghĩa là tiếng đá gõ vào nhau. Chữ tạo muộn, chưa thấy phân tích trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng đá", "Hạng Tần Suất (Jun Da)": "7027.0", "Tần Suất % (Jun Da)": "99.9970842983", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "硁", "Unihan_Traditional (Chữ Phồn thể)": "硜", "Pinyin_Xie": "kēng", "Âm Hán Việt_Xie": "khanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Tính từ | 形容词 | Thường dùng làm từ tượng thanh mô tả tiếng đá va chạm hoặc tính từ chỉ sự bướng bỉnh, nông cạn. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秬', '{"9000": "7028.0", "Chữ Trung Quốc": "秬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 9 | nét | 秬 | cự | tượng hình | lúa nếp đen | 秬 là chữ độc thể với bộ 禾 (hòa, lúa). Wiktionary không cung cấp phân tích cấu trúc. Bộ 禾 xác nhận liên quan đến ngũ cốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cự\": bông lúa (禾) màu đen — loại kê đen quý dùng trong nghi lễ cổ đại Trung Quốc. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết bộ 禾 trong 秬 kết nối với 种 (chủng, giống), 稻 (đạo, lúa nước), 秋 (thu, mùa thu).", "Tự nguyên_Xie": "Wiktionary ghi nhận 秬 là loại kê đen (black millet), thuộc họ Cenchrus americanus (pearl millet). Chữ dùng bộ 禾 (hòa) biểu nghĩa lúa cốc. Không có phân tích hình thanh hay hội ý chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lúa nếp đen", "Hạng Tần Suất (Jun Da)": "7028.0", "Tần Suất % (Jun Da)": "99.997087399", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 巨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾巨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秬", "Unihan_Traditional (Chữ Phồn thể)": "秬", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một giống lúa nếp đen dùng để cúng tế thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穪', '{"9000": "7029.0", "Chữ Trung Quốc": "穪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 19 | nét | 穪 | 穪 | tượng hình | ca ngợi, khen ngợi | 穪 là dạng biến thể hỏng của 稱 (xưng) hoặc 𥞻. Bộ 禾 biểu nghĩa liên quan đến ngũ cốc, nhưng chữ này đã bị biến dạng qua lịch sử chép tay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xưng\": chữ 穪 là bản sao méo mó của 稱 (xưng) — như tên gọi (稱) bị viết sai nhưng vẫn được hiểu là \"khen ngợi\". | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 穪 giúp nhận ra mối quan hệ với 稱 (xưng) — chữ chuẩn hiện đại mang nghĩa khen ngợi, gọi tên.", "Tự nguyên_Xie": "Theo Wiktionary, 穪 là dạng hỏng (corrupted form) của 稱 (xưng, khen ngợi) theo nguồn gốc thứ nhất, và hỏng của 𥞻 theo nguồn gốc thứ hai. Chữ không có cấu trúc hình thanh hay hội ý độc lập; nó là một biến thể văn bản của chữ gốc 稱. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "穪", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 爾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾爾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "穪", "Unihan_Traditional (Chữ Phồn thể)": "穪", "Pinyin_Xie": "chēng", "Âm Hán Việt_Xie": "xưng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động cân đo, xưng hô hoặc danh từ chỉ cái cân. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筦', '{"9000": "7030.0", "Chữ Trung Quốc": "筦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 13 | nét | 筦 | 筦 | tượng hình | ống sáo; cai quản | 筦 là chữ độc thể bộ 竹 (trúc, tre). Không có phân tích cấu trúc từ Wiktionary. Bộ 竹 xác nhận liên quan đến đồ vật làm bằng tre hoặc hình ống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"筦\": cây sáo tre (竹) — ống tre dài có thể thổi hoặc dùng làm chìa khóa quản lý. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết bộ 竹 trong 筦 kết nối với 管 (quản, ống/quản lý), 笛 (địch, sáo), 箫 (tiêu, sáo dọc).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary không cung cấp phân tích cấu trúc cho 筦. Chữ bộ 竹 (trúc), mang nghĩa ống sáo tre, ống tròn, cai quản. Dạng chữ tiểu triện còn lưu lại qua hanziyuan. Chữ tạo muộn, chưa có nguồn học thuật phân tích gốc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cai quản, trông nom; cái bút; ống tròn; ống sáo", "Hạng Tần Suất (Jun Da)": "7030.0", "Tần Suất % (Jun Da)": "99.9970936004", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 完", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮完", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "完", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筦", "Unihan_Traditional (Chữ Phồn thể)": "筦", "Pinyin_Xie": "guǎn", "Âm Hán Việt_Xie": "quản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ nhạc cụ ống hoặc động từ chỉ việc quản lý, điều hành công việc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粡', '{"9000": "7031.0", "Chữ Trung Quốc": "粡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 12 | nét | 粡 | đòng | tượng hình | gạo nếp, đòng đòng | 粡 là chữ độc thể bộ 米 (mễ, gạo). Không có phân tích cấu trúc từ Wiktionary. Bộ 米 xác nhận liên quan đến gạo hoặc ngũ cốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đòng\": hạt gạo (米) nếp mịn — từ Hán-Việt \"đòng\" còn dùng trong tiếng Việt như \"đòng đòng\" chỉ gạo nếp trắng. | Gương Hán-Việt | đòng — dùng trong từ cổ \"đòng đòng\" chỉ loại gạo nếp | Mở khoá kiến thức | Biết 粡 (đòng) mở ra bộ 米: 精 (tinh, gạo tinh), 粮 (lương, lương thực), 糯 (nhu, gạo nếp).", "Tự nguyên_Xie": "Không có nguồn Wiktionary phân tích cấu trúc cho 粡. Chữ bộ 米 (mễ), mang nghĩa gạo nếp. Trong tiếng Việt Hán cổ, đọc là \"đòng\" (như \"đòng đòng\"). Chưa có nguồn học thuật về gốc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đòng; như \"đòng đòng\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 同", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米同", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "同", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粡", "Unihan_Traditional (Chữ Phồn thể)": "粡", "Pinyin_Xie": "tóng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ bông lúa non hoặc đòng đòng trong nông nghiệp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粣', '{"9000": "7032.0", "Chữ Trung Quốc": "粣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 11 | nét | 粣 | 粣 | tượng hình | chất liệu từ gạo | 粣 là chữ độc thể bộ 米 (mễ, gạo). Không có dữ liệu phân tích từ Wiktionary. Bộ 米 gợi liên quan đến gạo hoặc thức ăn từ ngũ cốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"粣\": chữ gạo (米) bí ẩn — bộ 米 xác nhận liên quan đến ngũ cốc nhưng nghĩa chính xác đã thất truyền. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết bộ 米 trong 粣 kết nối với các chữ ngũ cốc: 粒 (lạp, hạt), 粉 (phấn, bột), 粗 (thô, thô ráp).", "Tự nguyên_Xie": "Không có nguồn Wiktionary hay dữ liệu cấu trúc cho 粣. Chữ bộ 米 (mễ), âm cè. Nghĩa cụ thể của chữ này không được xác định rõ trong các nguồn tra cứu hiện đại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "粣", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 册", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米册", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "册", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粣", "Unihan_Traditional (Chữ Phồn thể)": "粣", "Pinyin_Xie": "cè", "Âm Hán Việt_Xie": "sách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại bánh làm từ bột gạo nếp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綖', '{"9000": "7033.0", "Chữ Trung Quốc": "綖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 綖 | 綖 | tượng hình | mũ lưỡi trai, mũ quan | 綖 là chữ bộ 糸 (mịch, sợi tơ). Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích cấu trúc chi tiết. Bộ 糸 gợi liên quan đến sợi vải hoặc đồ dệt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"綖\": dải lụa (糸) rủ trước mũ quan — chi tiết trang phục cung đình biểu trưng quyền lực. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết bộ 糸 trong 綖 kết nối với 经 (kinh, sợi dọc), 结 (kết, buộc), 绣 (tú, thêu).", "Tự nguyên_Xie": "Lục thư thông | Wiktionary chỉ đánh dấu {{Han etym}} cho 綖 mà không cung cấp phân tích cụ thể. Chữ bộ 糸 (mịch, sợi tơ), nghĩa là mũ lưỡi trai — dải vải rủ phía trước mũ quan. Chỉ còn dạng Lục thư thông (thời Minh muộn). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mũ lưỡi trai", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 延", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹延", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "延", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "𫄧", "Unihan_Traditional (Chữ Phồn thể)": "綖", "Pinyin_Xie": "yán", "Âm Hán Việt_Xie": "diên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ phần trang trí hoặc dải rủ trên mũ miện thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('刭', '{"9000": "7034.0", "Chữ Trung Quốc": "刭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 7 | nét | 刭 | 경 | tượng hình | cắt cổ bằng dao | 刭 là dạng giản hóa của 剄 (bộ 刀). Wiktionary ghi: {{Han simp|剄|f=巠|t=𢀖}}, tức thay thành phần 巠 bằng 𢀖. Bộ 刀 (đao) biểu nghĩa chỉ hành động dùng dao.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"경\": lưỡi dao (刀) áp vào cổ — chữ này mô tả hành động tự vẫn bằng cách cắt cổ trong văn học cổ điển. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết bộ 刀 trong 刭 kết nối với 剑 (kiếm, gươm), 刺 (thứ, đâm), 切 (thiết, cắt).", "Tự nguyên_Xie": "Tiểu triện | 刭 là dạng giản hóa của 剄 — thay phần 巠 bằng 𢀖. Chữ gốc 剄 có bộ 刀 (đao) biểu nghĩa, mang nghĩa cắt cổ. Dạng tiểu triện còn lưu lại. Chữ dùng trong văn ngữ cổ chỉ hành động tự vẫn bằng dao. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lấy dao cắt cổ", "Hạng Tần Suất (Jun Da)": "7034.0", "Tần Suất % (Jun Da)": "99.997109104", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "刭", "Unihan_Traditional (Chữ Phồn thể)": "剄", "Pinyin_Xie": "jǐng", "Âm Hán Việt_Xie": "hĩnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ trong văn viết cổ để chỉ hành động tự vẫn hoặc hành hình bằng cách cắt cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跼', '{"9000": "7035.0", "Chữ Trung Quốc": "跼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 14 | nét | 跼 | 跼 | tượng hình | co quắp, tù túng | 跼 là chữ độc thể bộ 足 (túc, chân). Wiktionary không cung cấp phân tích cấu trúc cụ thể. Bộ 足 gợi liên quan đến tư thế thân thể, bước đi bị hạn chế.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"跼\": đôi chân (足) bị co rút lại — hình ảnh người khom lưng co chân trong không gian chật hẹp, tù túng. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết bộ 足 trong 跼 kết nối với 路 (lộ, đường), 跑 (bào, chạy), 跳 (khiêu, nhảy).", "Tự nguyên_Xie": "Wiktionary ghi nhận âm đọc và các từ ghép cho 跼 nhưng không phân tích cấu trúc. Chữ bộ 足 (túc, chân), mang nghĩa cúi khom, co quắp, không gian chật hẹp. Thường dùng trong thành ngữ 跼天蹐地 (bị trời đất bao vây, không có chỗ đứng). Chưa có nguồn học thuật về gốc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chật hẹp, tù túng", "Hạng Tần Suất (Jun Da)": "7035.0", "Tần Suất % (Jun Da)": "99.9971122047", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 局", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊局", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "局", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跼", "Unihan_Traditional (Chữ Phồn thể)": "跼", "Pinyin_Xie": "jú", "Âm Hán Việt_Xie": "cục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả trạng thái cơ thể co rúm hoặc không gian chật hẹp, tù túng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒇', '{"9000": "7036.0", "Chữ Trung Quốc": "蒇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 蒇 | 蒇 | tượng hình | hoàn thành, giải quyết xong | 蒇 là chữ độc thể bộ 艹 (thảo, cỏ). Không có dữ liệu phân tích từ Wiktionary. Bộ 艹 thường chỉ thực vật nhưng ở đây nghĩa đã mở rộng sang \"hoàn thành\".", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"蒇\": công việc (艹 gợi sinh trưởng) đã chín muồi xong — như cây cỏ đã phát triển đầy đủ, việc đã hoàn tất. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 蒇 giúp nhận ra từ 蒇事 (chǎn shì, hoàn thành việc) trong văn ngữ cổ.", "Tự nguyên_Xie": "Tiểu triện | Không có nguồn Wiktionary phân tích cấu trúc cho 蒇. Chữ bộ 艹 (thảo), mang nghĩa hoàn thành, giải quyết xong. Dạng tiểu triện còn lưu lại qua hanziyuan. Chưa có nguồn học thuật về gốc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đủ, xong rồi", "Hạng Tần Suất (Jun Da)": "7036.0", "Tần Suất % (Jun Da)": "99.9971153054", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蒇", "Unihan_Traditional (Chữ Phồn thể)": "蕆", "Pinyin_Xie": "chǎn", "Âm Hán Việt_Xie": "xiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết cổ để chỉ việc hoàn thành một công việc hay sự vụ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('挢', '{"9000": "7037.0", "Chữ Trung Quốc": "挢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 9 | nét | 挢 | 挢 | tượng hình | uốn thẳng, nắn lại | 挢 là dạng giản hóa của 撟, bộ 手 (thủ, tay). Wiktionary ghi {{Han etym}} cho dạng cũ 撟. Bộ 手 xác nhận liên quan đến hành động tay: uốn, nắn, duỗi ra.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"挢\": bàn tay (手) uốn nắn — như nghệ nhân dùng tay nắn thẳng vật cong vẹo. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết bộ 手 trong 挢 kết nối với 矫 (kiểu, uốn nắn), 握 (ác, nắm), 推 (thôi, đẩy).", "Tự nguyên_Xie": "Tiểu triện | 挢 là dạng giản lược của 撟 (cùng âm jiǎo). Chữ gốc 撟 bộ 手, nghĩa là uốn cong lên, nắn cho thẳng lại, duỗi ra. Dạng tiểu triện của 撟 còn lưu lại. Chưa có phân tích hình thanh/hội ý chi tiết từ Wiktionary. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "uốn cho cong lên; nắn cho ngay lại; duỗi ra", "Hạng Tần Suất (Jun Da)": "7037.0", "Tần Suất % (Jun Da)": "99.9971184061", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 乔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌乔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "挢", "Unihan_Traditional (Chữ Phồn thể)": "撟", "Pinyin_Xie": "jiǎo", "Âm Hán Việt_Xie": "kiểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động uốn nắn vật thể hoặc sửa chữa sai lầm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邆', '{"9000": "7038.0", "Chữ Trung Quốc": "邆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 15 | nét | 邆 | 邆 | tượng hình | dùng trong địa danh | 邆 là chữ độc thể bộ 辵 (sước, bước đi). Không có dữ liệu từ Wiktionary. Bộ 辵 thường chỉ chuyển động hoặc đường đi, nhưng ở đây chủ yếu dùng cho địa danh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"邆\": con đường (辵) mang tên địa danh — chữ này hầu như chỉ sống trong tên địa lý cổ đại. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết bộ 辵 trong 邆 kết nối với 道 (đạo, con đường), 过 (quá, đi qua), 通 (thông, thông suốt).", "Tự nguyên_Xie": "Không có nguồn Wiktionary hay dữ liệu cấu trúc cho 邆. Chữ bộ 辵 (sước), âm téng, chủ yếu xuất hiện trong địa danh. Nghĩa cụ thể không rõ trong nguồn hiện đại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(được sử dụng trong địa danh)", "Hạng Tần Suất (Jun Da)": "7038.0", "Tần Suất % (Jun Da)": "99.9971215068", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 登", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶登", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "登", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "邆", "Unihan_Traditional (Chữ Phồn thể)": "邆", "Pinyin_Xie": "téng", "Âm Hán Việt_Xie": "đằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng trong địa danh cổ như Đằng Xuyên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('彡', '{"9000": "7039.0", "Chữ Trung Quốc": "彡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彡 | Số nét | 3 | nét | 彡 | san | tượng hình | ba sợi lông, trang sức | 彡 là chữ tượng hình độc lập — ba nét gạch biểu trưng ba sợi lông hoặc tia sáng. Đây chính là bộ thủ Khang Hi số 59. Trong một số chữ, 彡 biểu thị tia nắng (昜) hoặc tia sao (參).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"san\": ba sợi lông (彡) — bộ tự này vẽ ba vạch song song tượng trưng cho lông thú, tia sáng, hoặc trang trí. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt từ 彡 đơn độc | Mở khoá kiến thức | Biết 彡 mở ra các chữ có bộ này: 形 (hình, hình dạng), 影 (ảnh, bóng), 彩 (thải, màu sắc), 须 (tu, râu/cần thiết).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 彡 là chữ tượng hình: ba nét gạch mô phỏng ba sợi lông. Trong ngữ cảnh khác, nó biểu thị ba tia sáng — tia nắng mặt trời trong 昜, tia sao trong 參. Chữ liên quan đến 丯 (vết khắc), 彭 (rung âm trống), 影 (bóng). Đôi khi ba nét chỉ mang tính trang trí như trong 鬱. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "860.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Là hình vẽ ba chiếc lông mao. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Sam là lông (tóc non).", "Nghĩa Tiếng Việt_Xie": "lông dài", "Hạng Tần Suất (Jun Da)": "7039.0", "Tần Suất % (Jun Da)": "99.9971246075", "GavinGrover_Once (Chiết tự trực tiếp)": "㇒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿲ (3 phần hàng ngang)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿲㇒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "彡", "Unihan_Traditional (Chữ Phồn thể)": "彡", "Pinyin_Xie": "shān", "Âm Hán Việt_Xie": "sam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm bộ thủ hoặc danh từ chỉ họa tiết lông dài trang trí. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猃', '{"9000": "7040.0", "Chữ Trung Quốc": "猃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 10 | nét | 猃 | 猃 | tượng hình | chó mõm dài | 猃 là dạng giản hóa của 獫, bộ 犬 (khuyển, chó). Wiktionary ghi nhận dạng cũ 獫 với âm xiǎn. Bộ 犭(犬) xác nhận liên quan đến loài chó.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"猃\": con chó (犭) mõm nhọn dài — chữ này còn gắn với tên bộ tộc 猃允 trong lịch sử Trung Hoa cổ đại. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết bộ 犭 trong 猃 kết nối với 狗 (cẩu, chó), 狼 (lang, sói), 猛 (mãnh, dữ tợn).", "Tự nguyên_Xie": "Tiểu triện | 猃 là dạng giản lược của 獫. Wiktionary mô tả 獫 là con chó có mõm dài, dùng trong từ 獫允 chỉ tên bộ tộc du mục cổ đại (Xiǎnyǔn, người Hung Nô). Chữ thuộc bộ 犬, hiện dùng rất hạn chế. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chó mõm dài", "Hạng Tần Suất (Jun Da)": "7040.0", "Tần Suất % (Jun Da)": "99.9971277082", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 佥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭佥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "佥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猃", "Unihan_Traditional (Chữ Phồn thể)": "獫", "Pinyin_Xie": "xiǎn", "Âm Hán Việt_Xie": "hiểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ giống chó săn mõm dài thời cổ hoặc tên bộ tộc thiểu số. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闉', '{"9000": "7041.0", "Chữ Trung Quốc": "闉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 17 | nét | 闉 | 闉 | tượng hình | tường thành cong; ở trong thành | 闉 là chữ độc thể bộ 門 (môn, cửa/cổng). Không có dữ liệu Wiktionary. Bộ 門 gợi liên quan đến cổng thành, công trình phòng thủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"闉\": cửa thành (門) ẩn khuất sau góc cong — chữ gợi kiến trúc thành lũy với những đoạn tường uốn khúc để phòng thủ. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết bộ 門 trong 闉 kết nối với 闹 (náo, ồn ào), 闭 (bế, đóng cửa), 闻 (văn, nghe/tiếng tăm).", "Tự nguyên_Xie": "Tiểu triện | Không có nguồn Wiktionary phân tích cấu trúc cho 闉. Chữ bộ 門 (môn), mang nghĩa tường thành cong, chỗ khuất khúc trong thành lũy, hoặc vùng nằm bên trong thành. Dạng tiểu triện còn lưu lại qua hanziyuan. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lấp; ở trong thành; khuất khúc, cong queo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "門 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "𬮱", "Unihan_Traditional (Chữ Phồn thể)": "闉", "Pinyin_Xie": "yīn", "Âm Hán Việt_Xie": "nhân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ khu vực cổng thành hoặc động từ chỉ sự bao bọc, lấp đầy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阓', '{"9000": "7042.0", "Chữ Trung Quốc": "阓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 12 | nét | 阓 | 阓 | tượng hình | cửa chợ | 阓 là dạng giản hóa của 闠, bộ 門 (môn, cửa). Wiktionary ghi nhận dạng cũ 闠 với nghĩa cổng thành phố, khu chợ. Bộ 門 xác nhận liên quan đến cổng, lối vào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"阓\": cửa (門) vào khu chợ — bước qua cổng 阓 là bước vào thế giới mua bán tấp nập. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 阓 giúp nhớ từ 闤闠 (huánhuì, khu chợ trong thành) trong văn học cổ điển.", "Tự nguyên_Xie": "阓 là dạng giản lược của 闠. Wiktionary mô tả 闠 là cổng thành phố, từ ghép 闤闠 chỉ khu chợ trong thành. Chữ dùng trong văn ngữ cổ để chỉ cổng ngoài của chợ hoặc khu phố buôn bán trong thành. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cửa ngoài chợ", "Hạng Tần Suất (Jun Da)": "7042.0", "Tần Suất % (Jun Da)": "99.9971339096", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 贵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门贵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阓", "Unihan_Traditional (Chữ Phồn thể)": "闠", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "hội", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ cửa chợ hoặc khu chợ, thường dùng trong văn ngôn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阛', '{"9000": "7043.0", "Chữ Trung Quốc": "阛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 16 | nét | 阛 | 阛 | tượng hình | tường bao quanh chợ | 阛 là dạng giản hóa của 闤, bộ 門 (môn, cửa). Wiktionary ghi {{Han simp|闤|f=門|t=门}}. Bộ 門 xác nhận liên quan đến công trình cổng và tường bao.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"阛\": cổng thành (門) bao quanh khu mua bán — 阛 là bức tường vây quanh chợ, cặp đôi với 阓 (cửa vào chợ). | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 阛 giúp nhớ từ 闤闠 (khu chợ trong thành) và bộ 門 liên kết với kiến trúc đô thị cổ.", "Tự nguyên_Xie": "Tiểu triện | 阛 là dạng giản lược của 闤, thay bộ 門 bằng 门 (giản thể). Wiktionary tra 阛 dẫn sang 闤 — tường bao quanh khu chợ trong thành phố. Từ ghép 闤闠 chỉ toàn bộ khu phố chợ. Dạng tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tường chợ", "Hạng Tần Suất (Jun Da)": "7043.0", "Tần Suất % (Jun Da)": "99.9971370104", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 睘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门睘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "睘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阛", "Unihan_Traditional (Chữ Phồn thể)": "闤", "Pinyin_Xie": "huán", "Âm Hán Việt_Xie": "hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ tường bao quanh chợ, thường kết hợp thành từ ghép như hoàn hội. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靺', '{"9000": "7044.0", "Chữ Trung Quốc": "靺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 14 | nét | 靺 | mạt | tượng hình | vớ, tất; bộ tộc Tungus | 靺 là chữ độc thể bộ 革 (cách, da thuộc). Wiktionary chỉ ghi {{Han etym}} không phân tích cụ thể. Bộ 革 gợi liên quan đến đồ vật làm bằng da như giày dép, tất vớ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạt\": da thuộc (革) bọc bàn chân — 靺 chỉ loại tất da xưa, cũng là tên gọi bộ tộc phương bắc nổi tiếng 靺鞨. | Gương Hán-Việt | mạt — dùng trong \"Mạt Hạt\" (靺鞨, tên bộ tộc Tungus cổ) | Mở khoá kiến thức | Biết 靺 (mạt) mở khóa từ 靺鞨 (Mạt Hạt) — tổ tiên của người Mãn Châu và nước Bột Hải trong lịch sử.", "Tự nguyên_Xie": "Wiktionary chỉ đánh dấu {{Han etym}} cho 靺 mà không cung cấp phân tích. Chữ bộ 革 (cách, da thuộc), có hai nghĩa: (1) vớ, tất chân; (2) dùng trong tên tộc người Tungus cổ (靺鞨, Mạt Hạt). Chưa có nguồn học thuật phân tích cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hạt mạt 鞨靺)", "Hạng Tần Suất (Jun Da)": "7044.0", "Tần Suất % (Jun Da)": "99.9971401111", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 末", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革末", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "末", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "靺", "Unihan_Traditional (Chữ Phồn thể)": "靺", "Pinyin_Xie": "mò", "Âm Hán Việt_Xie": "mạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ trong tên gọi bộ tộc cổ Mạt Hạt hoặc chỉ loại tất da thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞨', '{"9000": "7045.0", "Chữ Trung Quốc": "鞨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 18 | nét | 鞨 | hạt | tượng hình | bộ tộc Tungus | 鞨 là chữ độc thể bộ 革 (cách, da thuộc). Wiktionary chỉ ghi {{Han etym}} không phân tích cụ thể. Bộ 革 gợi liên quan đến đồ vật da thuộc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạt\": da thuộc (革) của tộc người phương bắc — 鞨 hầu như chỉ sống trong từ ghép 靺鞨, chỉ bộ tộc tổ tiên người Mãn Châu. | Gương Hán-Việt | hạt — dùng trong \"Mạt Hạt\" (靺鞨, tên bộ tộc Tungus cổ) | Mở khoá kiến thức | Biết 鞨 (hạt) kết hợp với 靺 (mạt) tạo thành 靺鞨 (Mạt Hạt) — tên bộ tộc quan trọng trong lịch sử Trung Quốc.", "Tự nguyên_Xie": "Wiktionary chỉ đánh dấu {{Han etym}} cho 鞨 mà không phân tích cấu trúc. Chữ bộ 革 (cách), âm hé, chủ yếu dùng trong từ 靺鞨 (Mạt Hạt) — tên bộ tộc Tungus ở đông bắc Trung Quốc thời Đường. Chưa có nguồn học thuật về gốc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hạt mạt 鞨靺)", "Hạng Tần Suất (Jun Da)": "7045.0", "Tần Suất % (Jun Da)": "99.9971432118", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 曷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革曷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞨", "Unihan_Traditional (Chữ Phồn thể)": "鞨", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong tên bộ tộc Mạt Hạt hoặc chỉ một loại giày da thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铥', '{"9000": "7046.0", "Chữ Trung Quốc": "铥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 金 | kim | biểu nghĩa | kim loại | 丢 | đâu | biểu âm | 铥 = 金 (Kim, biểu nghĩa: kim loại) + 丢 (Đâu, biểu âm); chữ hình thanh. Bộ 金 xác nhận đây là nguyên tố kim loại; 丢 cung cấp âm đọc diū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"铥\": kim loại (金) quý hiếm âm đọc như 丢 — nguyên tố Thulium, đất hiếm nhỏ bé nhất họ lanthanide. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết bộ 金 trong 铥 kết nối với hệ thống tên nguyên tố kim loại: 铁 (thiết, sắt), 铜 (đồng, đồng), 银 (ngân, bạc).", "Tự nguyên_Xie": "Chữ hình thanh hiện đại: 金 (kim) biểu nghĩa chỉ kim loại, 丢 (đâu) biểu âm. 铥 là tên Hán tự của nguyên tố Thulium (Tm, số nguyên tử 69), một nguyên tố đất hiếm. Chữ gốc truyền thống là 銩. Tên phiên âm từ \"Thulium\". | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố tuli, Tu", "Hạng Tần Suất (Jun Da)": "7046.0", "Tần Suất % (Jun Da)": "99.9971463125", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 丢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅丢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铥", "Unihan_Traditional (Chữ Phồn thể)": "銩", "Pinyin_Xie": "diū", "Âm Hán Việt_Xie": "đâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố hóa học kim loại hiếm Thulium trong bảng tuần hoàn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘅', '{"9000": "7047.0", "Chữ Trung Quốc": "瘅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 13 | nét | 瘅 | đan | tượng hình | ghét bỏ; kiệt sức; bệnh nhiệt | 瘅 là chữ độc thể bộ 疒 (nạch, bệnh tật). Wiktionary ghi dạng cũ 癉 với {{Han etym}} không phân tích cụ thể. Bộ 疒 xác nhận liên quan đến bệnh tật, suy kiệt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đan\": bệnh tật (疒) thiêu đốt từ bên trong — 瘅 gợi sự căm ghét nội tâm hoặc cơ thể kiệt sức vì nhiệt bệnh. | Gương Hán-Việt | đan — dùng trong \"đan tâm\" chỉ lòng căm ghét sâu sắc (văn cổ) | Mở khoá kiến thức | Biết bộ 疒 trong 瘅 kết nối với 病 (bệnh), 痛 (thống, đau), 疲 (bì, mệt mỏi).", "Tự nguyên_Xie": "瘅 là dạng giản lược của 癉. Wiktionary ghi {{Han etym}} cho 癉 mà không phân tích cấu trúc. Chữ bộ 疒 (nạch), mang nhiều nghĩa: ghét bỏ cay đắng, kiệt sức vì lao lực, bệnh nhiệt. Chưa có nguồn học thuật phân tích gốc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ghét, căm ghét; kiệt sức; bệnh đơn", "Hạng Tần Suất (Jun Da)": "7047.0", "Tần Suất % (Jun Da)": "99.9971494132", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 单", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒单", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "单", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘅", "Unihan_Traditional (Chữ Phồn thể)": "癉", "Pinyin_Xie": "dān", "Âm Hán Việt_Xie": "đản, đan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ bệnh tật hoặc làm động từ thể hiện sự căm ghét trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('騻', '{"9000": "7048.0", "Chữ Trung Quốc": "騻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 21 | nét | 騻 | 騻 | tượng hình | ngựa quý | 騻 là chữ độc thể bộ 馬 (mã, ngựa). Wiktionary xác nhận đây là dạng biến thể (alt form) của 驦. Bộ 馬 xác nhận liên quan đến ngựa quý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"騻\": con ngựa (馬) phi sương — 騻 là loài tuấn mã quý được nhắc đến trong thơ văn cổ điển. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 騻 giúp nhận ra biến thể 驦 và hiểu hệ thống tên ngựa quý trong văn học cổ điển Trung Quốc.", "Tự nguyên_Xie": "Wiktionary ghi 騻 là dạng cũ của 驦 (cùng âm shuāng/shuǎng). Đây là tên một loài ngựa quý. Chữ chỉ xuất hiện trong văn ngữ cổ, hiện rất ít dùng. Không có phân tích hình thanh hay hội ý chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa túc sương", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 爽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬爽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "騻", "Unihan_Traditional (Chữ Phồn thể)": "騻", "Pinyin_Xie": "shuāng", "Âm Hán Việt_Xie": "sương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ giống ngựa chạy nhanh thời cổ, thường xuất hiện trong văn học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箅', '{"9000": "7049.0", "Chữ Trung Quốc": "箅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 箅 | tất | tượng hình | cái vỉ tre để hấp thức ăn | 箅 là chữ độc thể bộ 竹 (trúc, tre). Wiktionary ghi nhận chi tiết nghĩa và cách dùng. Bộ 竹 xác nhận đây là vật dụng làm bằng tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tất\": tấm vỉ tre (竹) để hấp — 箅 là dụng cụ bếp truyền thống, tấm lưới tre đặt trong nồi để hấp xôi hay thức ăn. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 箅 gợi nhớ bộ 竹 với các vật dụng tre: 筷 (khoái, đũa), 篮 (lam, giỏ), 笼 (lung, lồng).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary mô tả 箅 là tấm lưới/vỉ (grate/grid) dùng để hấp thức ăn, truyền thống làm bằng tre. Chữ thuộc bộ 竹 (trúc). Dạng tiểu triện còn lưu lại. Từ ghép 箅子 còn dùng trong tiếng Hán hiện đại chỉ tấm vỉ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái vỉ đan bằng tre", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 畀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮畀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箅", "Unihan_Traditional (Chữ Phồn thể)": "箅", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "ti", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ dụng cụ đan bằng tre dùng để hấp thức ăn hoặc lọc nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箢', '{"9000": "7050.0", "Chữ Trung Quốc": "箢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 箢 | uyển | tượng hình | giỏ tre, làn tre | 箢 là chữ độc thể bộ 竹 (trúc, tre). Không có dữ liệu từ Wiktionary. Bộ 竹 xác nhận đây là vật dụng làm bằng tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uyển\": cái giỏ (竹) uốn tròn — 箢 là giỏ tre đan tròn xinh xắn, hình ảnh quen thuộc trong đời sống nông thôn. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết bộ 竹 trong 箢 kết nối với 篮 (lam, giỏ), 筐 (khuông, sọt), 篓 (lũ, giỏ đựng).", "Tự nguyên_Xie": "Không có nguồn Wiktionary hay dữ liệu cấu trúc cho 箢. Chữ bộ 竹 (trúc), âm yuān, nghĩa là giỏ tre hoặc làn tre. Chưa có nguồn học thuật về gốc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giỏ tre; làn tre", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 宛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮宛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箢", "Unihan_Traditional (Chữ Phồn thể)": "箢", "Pinyin_Xie": "yuān", "Âm Hán Việt_Xie": "uyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại giỏ hoặc thúng làm bằng tre dùng để đựng đồ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觖', '{"9000": "7051.0", "Chữ Trung Quốc": "觖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 角 | Số nét | 11 | nét | 觖 | 觖 | tượng hình | không thỏa mãn, chưa mãn nguyện | 觖 là chữ độc thể bộ 角 (giác, góc/sừng). Wiktionary chỉ ghi {{Han etym}} không phân tích. Bộ 角 gợi liên quan đến cạnh sắc, sự không trơn tru — ẩn dụ cho tâm trạng chưa được thỏa mãn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"觖\": góc sắc (角) chưa được mài tròn — tâm trạng còn cạnh góc, chưa trơn tru vì chưa đạt được điều mong muốn. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết bộ 角 trong 觖 kết nối với 解 (giải, tháo gỡ), 触 (xúc, chạm), 角 (giác, góc/sừng).", "Tự nguyên_Xie": "Wiktionary chỉ đánh dấu {{Han etym}} cho 觖 mà không phân tích cấu trúc. Chữ bộ 角 (giác), mang nghĩa không thỏa lòng, chưa mãn nguyện, khao khát điều gì đó. Chưa có nguồn học thuật về gốc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "không thoả, chưa mãn nguyện", "Hạng Tần Suất (Jun Da)": "7051.0", "Tần Suất % (Jun Da)": "99.9971649168", "GavinGrover_Once (Chiết tự trực tiếp)": "角 + 夬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰角夬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "角", "Unihan_Simplified (Chữ Giản thể)": "觖", "Unihan_Traditional (Chữ Phồn thể)": "觖", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ chỉ trạng thái không vừa lòng hoặc làm động từ biểu thị sự oán trách. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麆', '{"9000": "7052.0", "Chữ Trung Quốc": "麆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 16 | nét | 麆 | trữ | tượng hình | hươu con nhỏ | 麆 là chữ độc thể bộ 鹿 (lộc, hươu). Wiktionary mô tả là hươu nước nhỏ (young water deer). Bộ 鹿 xác nhận liên quan đến loài hươu nai.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trữ\": con hươu nhỏ (鹿) còn non — 麆 chỉ hươu nước non, còn nhỏ chưa trưởng thành. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết bộ 鹿 trong 麆 kết nối với hệ thống tên hươu nai: 麟 (lân, kỳ lân), 麋 (my, nai lớn), 麝 (xạ, hươu xạ).", "Tự nguyên_Xie": "Wiktionary mô tả 麆 là hươu nước non (young water deer), thuộc bộ Cervidae. Chữ bộ 鹿 (lộc), âm chú/zhù. Chỉ dùng trong văn ngữ cổ, hiện rất ít gặp. Không có phân tích hình thanh hay hội ý chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "麆", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麆", "Unihan_Traditional (Chữ Phồn thể)": "麆", "Pinyin_Xie": "zhù", "Âm Hán Việt_Xie": "chú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con hươu nhỏ mới sinh hoặc còn non. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齮', '{"9000": "7053.0", "Chữ Trung Quốc": "齮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 23 | nét | 齮 | nghĩ | tượng hình | cắn, nhai | 齮 là chữ độc thể bộ 齒 (xỉ, răng). Wiktionary ghi nhận nghĩa là cắn. Bộ 齒 xác nhận liên quan đến răng và hành động dùng răng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghĩ\": hàm răng (齒) cắn xuống — 齮 mô tả hành động cắn của loài vật hoặc con người trong văn ngữ cổ. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết bộ 齒 trong 齮 kết nối với 龋 (hủ, sâu răng), 龈 (ngân, nướu răng), 咬 (giảo, cắn).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary mô tả 齮 nghĩa là cắn (to bite), dùng trong từ ghép 齮齕 (cắn gặm). Chữ bộ 齒 (xỉ, răng). Dạng tiểu triện và nhiều dạng Lục thư thông còn lưu lại qua hanziyuan. Không có phân tích hình thanh/hội ý chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cắn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "齒 + 奇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齒奇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齒", "Unihan_Simplified (Chữ Giản thể)": "𬺈", "Unihan_Traditional (Chữ Phồn thể)": "齮", "Pinyin_Xie": "yǐ", "Âm Hán Việt_Xie": "nghĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường dùng trong văn ngôn cổ để chỉ hành động cắn hoặc làm hại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糀', '{"9000": "7054.0", "Chữ Trung Quốc": "糀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 13 | nét | 糀 | hoa | tượng hình | malt gạo, cơm ủ men | 糀 là chữ mượn từ tiếng Nhật (借字). Wiktionary ghi: {{obor|zh|ja|糀}} — mượn từ chữ Nhật 糀 (kōji). Bộ 米 (mễ, gạo) biểu nghĩa liên quan đến gạo và quá trình lên men.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoa\": gạo (米) nở hoa men — 糀 là gạo ủ mốc koji, \"nở hoa\" trắng trên bề mặt như bông hoa nhỏ. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 糀 kết nối với văn hóa ẩm thực Nhật-Trung: gạo lên men làm sake, miso, tương, amazake.", "Tự nguyên_Xie": "Theo Wiktionary, 糀 là chữ mượn từ tiếng Nhật (字義借用), chữ Nhật 糀 (kōji) chỉ cơm gạo ủ với nấm mốc Aspergillus để làm sake, miso, tương. Chữ Trung Quốc mượn lại với âm đọc hua. Bộ 米 biểu nghĩa gạo. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "糀", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 花", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米花", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "花", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "糀", "Unihan_Traditional (Chữ Phồn thể)": "糀", "Pinyin_Xie": "hua", "Âm Hán Việt_Xie": "hoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chủ yếu dùng trong tiếng Nhật để chỉ men gạo hoặc gạo mốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘊', '{"9000": "7055.0", "Chữ Trung Quốc": "瘊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 14 | nét | 瘊 | hầu | tượng hình | mụn cóc, mụn nhọt nhỏ | 瘊 là chữ độc thể bộ 疒 (nạch, bệnh tật). Wiktionary ghi nhận nghĩa là mụn cóc, mụn nhọt nhỏ. Bộ 疒 xác nhận liên quan đến bệnh tật da liễu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hầu\": bệnh tật (疒) mọc hạt nhỏ — 瘊 là mụn cóc nhỏ mọc trên da, cứng như hạt nhỏ. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết bộ 疒 trong 瘊 kết nối với 疣 (ưu, mụn cóc lớn), 疤 (ba, sẹo), 痣 (chí, nốt ruồi).", "Tự nguyên_Xie": "Wiktionary mô tả 瘊 nghĩa là mụn cóc, mụn nhọt nhỏ (warts, pimples). Từ ghép 瘊子 (hóu zi) dùng trong tiếng Hán hiện đại chỉ mụn cóc. Chữ bộ 疒 (nạch). Không có phân tích hình thanh hay hội ý chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bướu nhỏ", "Hạng Tần Suất (Jun Da)": "7055.0", "Tần Suất % (Jun Da)": "99.9971804203", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 侯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒侯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "侯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘊", "Unihan_Traditional (Chữ Phồn thể)": "瘊", "Pinyin_Xie": "hóu", "Âm Hán Việt_Xie": "hầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường kết hợp thành từ ghép để chỉ bệnh mụn cóc ngoài da. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聴', '{"9000": "7056.0", "Chữ Trung Quốc": "聴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 17 | nét | 聴 | thính | tượng hình | nghe, lắng nghe | 聴 là dạng chữ Nhật (shin-jitai) của 聽/听. Không có dữ liệu Wiktionary. Bộ 耳 (nhĩ, tai) xác nhận liên quan đến thính giác.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thính\": đôi tai (耳) lắng nghe — 聴 là dạng Nhật của chữ 听/聽, mang nghĩa nghe, tuân lệnh. | Gương Hán-Việt | thính — dùng trong \"thính giác\" (khả năng nghe), \"thính phòng\" (phòng nghe nhạc) | Mở khoá kiến thức | Biết 聴 (thính) kết nối với 听 (thính, nghe), 聞 (văn, nghe/tiếng tăm), 聪 (thông, thính tai/thông minh).", "Tự nguyên_Xie": "聴 là dạng chữ Nhật hiện đại (shin-jitai) của chữ Hán 聽 (phồn thể) / 听 (giản thể). Không có phân tích Wiktionary riêng cho 聴. Bộ 耳 (nhĩ) biểu nghĩa chỉ tai và hành động nghe. Chữ này thường thấy trong văn bản tiếng Nhật hoặc ký nhạc Hán-Nhật. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "贴", "Hạng Tần Suất (Jun Da)": "7056.0", "Tần Suất % (Jun Da)": "99.9971866217", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "聴", "Unihan_Traditional (Chữ Phồn thể)": "聴", "Pinyin_Xie": "tīng", "Âm Hán Việt_Xie": "thính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện hành động lắng nghe hoặc tuân theo ý kiến của người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讬', '{"9000": "7057.0", "Chữ Trung Quốc": "讬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 5 | nét | 言 | ngôn | biểu nghĩa | lời nói, ngôn ngữ | 乇 | trạch | biểu âm | 讬 = 言 (Ngôn, biểu nghĩa: lời nói) + 乇 (Trạch, biểu âm); chữ hình thanh. Bộ 言 xác nhận nghĩa liên quan đến lời nói, giao phó bằng lời; 乇 cung cấp âm đọc tuō.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thác\": dùng lời nói (言) để giao phó — 讬/託 là hành động nói lời ủy thác, nhờ cậy người khác giữ gìn điều gì. | Gương Hán-Việt | thác — dùng trong \"ký thác\" (gửi gắm), \"tín thác\" (tin tưởng giao phó), \"ủy thác\" (nhờ người làm thay) | Mở khoá kiến thức | Biết 讬 (thác) mở khóa: 托付 (giao phó), 拜托 (nhờ vả), 委托 (ủy thác), 信托 (tín thác).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 言 (ngôn) biểu nghĩa chỉ lời nói, 乇 biểu âm. 讬 là dạng giản lược của 託, nghĩa là giao phó, nhờ vả, ủy thác. Wiktionary cung cấp phân tích đầy đủ cho dạng chuẩn 託. Dạng tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giao phó", "Hạng Tần Suất (Jun Da)": "7057.0", "Tần Suất % (Jun Da)": "99.9971928231", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 乇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠乇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "讬", "Unihan_Traditional (Chữ Phồn thể)": "讬", "Pinyin_Xie": "tuō", "Âm Hán Việt_Xie": "thác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường đi kèm tân ngữ chỉ người hoặc việc được giao phó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('揲', '{"9000": "7058.0", "Chữ Trung Quốc": "揲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 揲 | điệp | tượng hình | đếm cỏ thi bói; gấp lại | 揲 là chữ độc thể bộ 手 (thủ, tay). Wiktionary ghi nhận nhiều âm đọc. Bộ 手 xác nhận liên quan đến hành động tay: đếm, gấp, xếp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệp\": bàn tay (手) đếm từng que cỏ thi — 揲 là hành động phân chia que thi trong nghi thức bói Kinh Dịch. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 揲 kết nối với nghi lễ bói dịch: 筮 (thệ, bói cỏ thi), 卦 (quái, quẻ), 蓍 (thi, cỏ thi).", "Tự nguyên_Xie": "Wiktionary mô tả 揲 có bốn âm đọc và nghĩa: (1) shé — phân chia các que cỏ thi trong bói dịch; (2) dié — gấp lại, đánh đòn; (3) yè — nghĩa không rõ; (4) tiếng Mân Nam — trêu chọc. Chữ bộ 手, liên quan đến hành động tay. Không có phân tích hình thanh. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cầm đếm cỏ thi; xếp gấp", "Hạng Tần Suất (Jun Da)": "7058.0", "Tần Suất % (Jun Da)": "99.9971959239", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 枼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌枼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "枼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "揲", "Unihan_Traditional (Chữ Phồn thể)": "揲", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệp, thiệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ dùng trong ngữ cảnh bói toán thời cổ hoặc hành động xếp nếp. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镮', '{"9000": "7059.0", "Chữ Trung Quốc": "镮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 18 | nét | 镮 | hoàn | tượng hình | vòng kim loại | 镮 là dạng giản hóa của 鐶, bộ 金 (kim, kim loại). Wiktionary ghi {{Han simp|鐶|f=金|t=钅}}. Bộ 金/钅 xác nhận đây là vật dụng bằng kim loại hình vòng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàn\": kim loại (金) đúc thành vòng tròn — 镮 là vòng nhẫn, vòng tay làm bằng kim loại quý. | Gương Hán-Việt | hoàn — dùng trong \"hoàn bội\" (vòng đeo), \"hoàn kim\" (nhẫn vàng) trong văn cổ | Mở khoá kiến thức | Biết 镮 (hoàn) kết nối với 环 (hoàn, vòng tròn), 圈 (quyên, vòng tròn), 铃 (linh, chuông).", "Tự nguyên_Xie": "镮 là dạng giản lược của 鐶 — thay bộ 金 (8 nét) bằng 钅 (5 nét giản thể). Wiktionary tra 镮 dẫn sang 鐶 — vòng kim loại, đơn vị tiền tệ cổ. Chữ cùng âm hoán với 环 (vòng tròn), nhưng nhấn mạnh vật liệu kim loại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái vòng kim loại", "Hạng Tần Suất (Jun Da)": "7059.0", "Tần Suất % (Jun Da)": "99.9971990246", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 睘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅睘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "睘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镮", "Unihan_Traditional (Chữ Phồn thể)": "鐶", "Pinyin_Xie": "huán", "Âm Hán Việt_Xie": "hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ cái vòng hoặc làm lượng từ để đếm số vòng kim loại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钷', '{"9000": "7060.0", "Chữ Trung Quốc": "钷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 金 | kim | biểu nghĩa | kim loại | 叵 | phổ | biểu âm | 钷 = 金 (Kim, biểu nghĩa: kim loại) + 叵 (biểu âm, đọc pǒ gần với phổ); chữ hình thanh. Bộ Kim chỉ bản chất kim loại của nguyên tố, phần 叵 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phổ\" (ít dùng): Kim loại (金) hiếm nhất bảng tuần hoàn — Promethium, nguyên tố phóng xạ nhân tạo duy nhất trong nhóm Lanthanide. | Gương Hán-Việt | phổ — dùng làm tên khoa học nguyên tố Promethium trong tiếng Hán hiện đại | Mở khoá kiến thức | Biết 钷 mở khoá tên các nguyên tố hoá học Hán-Việt trong nhóm kim loại đất hiếm.", "Tự nguyên_Xie": "Chữ hình thanh: 金 (kim loại, biểu nghĩa) + 叵 (biểu âm, âm pǒ). 钷 là tên phiên âm của nguyên tố Promethium (Pm, số nguyên tử 61), một nguyên tố phóng xạ nhân tạo thuộc nhóm Lanthanide. Chữ tạo muộn để đặt tên khoa học, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố prometi, Pm", "Hạng Tần Suất (Jun Da)": "7060.0", "Tần Suất % (Jun Da)": "99.9972021253", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 叵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅叵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钷", "Unihan_Traditional (Chữ Phồn thể)": "鉕", "Pinyin_Xie": "pǒ", "Âm Hán Việt_Xie": "phả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chuyên ngành hóa học để chỉ nguyên tố phóng xạ Prometi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睪', '{"9000": "7061.0", "Chữ Trung Quốc": "睪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 13 | nét | 目 | mục | biểu nghĩa | mắt | 矢 | thỉ | biểu nghĩa | mũi tên | 睪 = 目 (Mục, mắt) + 矢 (Thỉ, mũi tên); chữ hội ý. Một hình thức trong giáp cốt văn ghép mắt và mũi tên để diễn ý nhìn/rình, nhưng nhiều học giả tranh luận về cách đọc chính xác. Hình thức khác trong kim văn là 㚔 (còng tay) + 廾 (hai tay) gợi ý nghĩa thả/phóng thích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dịch\" (ít dùng): Mắt (目) theo dõi như mũi tên (矢) — hình ảnh rình mò, quan sát sắc bén. | Gương Hán-Việt | dịch — bộ thủ 睪 xuất hiện trong các chữ như 擇 (trạch, chọn lựa), 釋 (thích, giải phóng) | Mở khoá kiến thức | Biết 睪 mở khoá bộ thủ trong các chữ 擇, 釋, 澤 — những chữ liên quan đến chọn lựa và phóng thích.", "Tự nguyên_Xie": "Kim văn | Trong giáp cốt văn tồn tại hai hình thức chính của chữ này: (1) mắt (目) + mũi tên (矢) theo kiểu hội ý, có thể nghĩa là ''bắn'' hoặc ''nhìn''; (2) còng tay (㚔) + đôi bàn tay (廾/𠬜), gợi ý nghĩa ''thả ra'' — nay viết là 釋. Trong kim văn đông Chu xuất hiện thêm thành phần mắt 目 để nhấn mạnh hành động chọn lựa bằng mắt. Dạng hiện đại là 目 + 㚔 (mắt + còng tay). Chữ này là thành phần của nhiều chữ phức hợp quan trọng như 擇 (chọn), 釋 (thả). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1362.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mục (091) Hạnh (233)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mục (số 091 - con mắt/viết làm 罒) ở trên chữ Hạnh (số 233 - vui thích/may mắn/ 幸). Mắt nhìn thấy những điều may mắn, tốt lành. Giải thích sự chuyển ý: Đây là chữ Hội ý. Dịch là nhìn, dòm ngó, phân biệt rạch ròi. (Sau được dùng làm thành phần tạo chữ).", "Nghĩa Tiếng Việt_Xie": "rình, dòm", "Hạng Tần Suất (Jun Da)": "7061.0", "Tần Suất % (Jun Da)": "99.997205226", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + 幸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒幸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "睪", "Unihan_Traditional (Chữ Phồn thể)": "睪", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ cổ chỉ hành động rình mò hoặc quan sát kỹ lưỡng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翫', '{"9000": "7062.0", "Chữ Trung Quốc": "翫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 15 | nét | 翫 | ngoạn | tượng hình | chữ cổ chỉ hành động chơi đùa, thưởng thức | 翫 là chữ cổ, bộ Vũ (羽, lông vũ) kết hợp với phần bên, nhưng cấu trúc hội ý không hoàn toàn rõ ràng. Wiktionary không cung cấp phân tích hội ý/hình thanh cụ thể. Đây là dạng cổ của 玩 (chơi, thưởng thức).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngoạn\": Chữ cổ của 玩 — ngoạn mục (翫目), thưởng ngoạn (賞翫) đều dùng chữ này để chỉ việc ngắm nhìn, thưởng thức thong thả. | Gương Hán-Việt | ngoạn — trong tiếng Việt: ''thưởng ngoạn'', ''ngoạn mục'' dùng gốc chữ này | Mở khoá kiến thức | Biết 翫 mở khoá văn ngôn: 賞翫 (thưởng ngoạn), 遊翫 (du ngoạn), 翫弄 (ngoạn lộng — chơi đùa với).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích cấu tạo rõ ràng cho 翫. Đây là dạng cổ, cùng nghĩa với 玩 (chơi đùa, thưởng thức). Trong văn cổ, 翫 mang nghĩa ''lơ đễnh, không chú ý'', hoặc ''thưởng thức, ngắm nghía kỹ lưỡng''. Chưa có nguồn học thuật rõ về hội ý/hình thanh. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "翫", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "習 + 元", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰習元", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "元", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "習", "Unihan_Simplified (Chữ Giản thể)": "翫", "Unihan_Traditional (Chữ Phồn thể)": "翫", "Pinyin_Xie": "wán", "Âm Hán Việt_Xie": "ngoạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ cảnh vật hoặc đồ vật để biểu thị sự thưởng thức. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荅', '{"9000": "7063.0", "Chữ Trung Quốc": "荅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艸 | thảo | biểu nghĩa | cỏ, thực vật | 合 | cáp | biểu âm | 荅 = 艸 (Thảo, biểu nghĩa: cỏ/cây) + 合 (Cáp, biểu âm); chữ hình thanh. Bộ Thảo chỉ đây là loại thực vật (đậu nhỏ), phần 合 cho âm đọc gần với dā.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đáp\": Cây cỏ (艸) hợp lại (合) — hình ảnh những cây đậu nhỏ quấn quýt nhau, cũng là gốc của ''đáp lại'' (trả lời). | Gương Hán-Việt | đáp — trong tiếng Việt: ''trả lời, đáp lại'' — 荅 là dạng cổ của 答 | Mở khoá kiến thức | Biết 荅 nhận ra gốc chữ 答 (đáp, trả lời) và hiểu tại sao đáp án lại có bộ Thảo.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 艸 (cỏ/thực vật, biểu nghĩa) + 合 (biểu âm). 荅 ban đầu chỉ một loại đậu nhỏ. Về sau dùng thay cho 答 (trả lời) trong một số văn bản cổ. Bộ Thảo (艸) xác nhận đây là thực vật. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trả lời; báo đáp", "Hạng Tần Suất (Jun Da)": "7063.0", "Tần Suất % (Jun Da)": "99.9972176288", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 合", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹合", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "合", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荅", "Unihan_Traditional (Chữ Phồn thể)": "荅", "Pinyin_Xie": "dā", "Âm Hán Việt_Xie": "đáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng đầu câu hoặc làm vị ngữ để trả lời câu hỏi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菉', '{"9000": "7064.0", "Chữ Trung Quốc": "菉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艸 | thảo | biểu nghĩa | cỏ | 彔 | lộc | biểu âm | 菉 = 艸 (Thảo, biểu nghĩa: cỏ) + 彔 (Lộc, biểu âm); chữ hình thanh. Bộ Thảo xác nhận đây là thực vật, phần 彔 cho âm đọc (lù).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lục\": Cỏ (艸) màu xanh lục (彔 — gợi âm lục) — hình ảnh bụi tre xanh mướt trong Kinh Thi. | Gương Hán-Việt | lục — 菉 xuất hiện trong văn chương cổ điển, liên quan đến màu xanh và cây cỏ | Mở khoá kiến thức | Biết 菉 nhận ra mối liên hệ với 綠 (lục, màu xanh) và bộ Thảo trong thực vật học Hán tự.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 艸 (cỏ, biểu nghĩa) + 彔 (biểu âm). 菉 chỉ loài tre xanh hoặc cây cỏ xanh mướt, xuất hiện trong Kinh Thi (詩經). Bộ Thảo khẳng định đây là thực vật thuộc họ cỏ/tre. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ lục", "Hạng Tần Suất (Jun Da)": "7064.0", "Tần Suất % (Jun Da)": "99.9972207295", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 录", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹录", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "录", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菉", "Unihan_Traditional (Chữ Phồn thể)": "菉", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ loài cỏ hoặc làm định ngữ bổ nghĩa cho danh từ để chỉ màu sắc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袚', '{"9000": "7065.0", "Chữ Trung Quốc": "袚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袚 | bát | tượng hình | áo/đồ bảo vệ đầu gối, quần cổ đại | 袚 có bộ衣 (衤, quần áo) nhưng Wiktionary không cung cấp phân tích hình thanh hay hội ý chi tiết. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Dựa vào bộ衣, đây là loại trang phục bảo vệ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạt\": Bộ Áo (衣) bọc bảo vệ — 袚 là loại đồ che phủ cổ đại, từng dùng trong lễ nghi và chiến trận. | Gương Hán-Việt | bát — ít dùng trong tiếng Việt hiện đại, chủ yếu gặp trong văn cổ và từ điển chuyên ngành | Mở khoá kiến thức | Biết 袚 mở khoá nhóm từ văn ngôn chỉ trang phục lễ nghi và giáp trụ cổ đại.", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} không có nội dung phân tích. 袚 là loại đồ che chắn (như bao gối hoặc đồ lễ cổ). Bộ衣 (quần áo) cho biết đây liên quan đến trang phục. Chưa có nguồn học thuật rõ ràng về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quả bí ngô; miếng đệm đầu gối", "Hạng Tần Suất (Jun Da)": "7065.0", "Tần Suất % (Jun Da)": "99.9972238303", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 犮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤犮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袚", "Unihan_Traditional (Chữ Phồn thể)": "袚", "Pinyin_Xie": "bō", "Âm Hán Việt_Xie": "phất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ trang phục cổ, đứng sau các động từ mặc hoặc mang. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褋', '{"9000": "7066.0", "Chữ Trung Quốc": "褋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 14 | nét | 褋 | điệp | tượng hình | loại đệm/nệm cổ đại | 褋 có bộ Áo (衣) nhưng Wiktionary không cung cấp phân tích cấu trúc cụ thể. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Bộ Áo xác nhận liên quan đến trang phục hoặc đồ dùng vải.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệp\": Bộ Áo (衣) gợi vải — 褋 là loại nệm/đệm, xếp lớp như cánh bướm (điệp) chồng lên nhau. | Gương Hán-Việt | điệp — liên hệ với âm ''điệp'' trong ''điệp khúc'', ''điệp điệp'' (lớp lớp) | Mở khoá kiến thức | Biết 褋 nhận diện nhóm chữ bộ Áo chỉ đồ dùng vải trong gia đình cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} không có nội dung phân tích, định nghĩa để trống (rfdef). 褋 chỉ loại nệm hoặc đệm cổ đại. Bộ Áo (衣) gợi ý đây là vật dụng làm từ vải. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nệm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 枼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤枼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "枼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褋", "Unihan_Traditional (Chữ Phồn thể)": "褋", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ trang phục, làm tân ngữ cho động từ mặc hoặc cởi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贠', '{"9000": "7067.0", "Chữ Trung Quốc": "贠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 6 | nét | 贠 | viên | tượng hình | thành viên, nhân viên — dạng giản thể của 貟 | 贠 là dạng giản thể của 貟, đơn giản hoá bộ Bối (貝→贝). Wiktionary ghi đây là {{Han simp}} (giản thể hoá). Không có phân tích hội ý/hình thanh độc lập.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"viên\": Dạng giản thể của 員/貟 — ''nhân viên'', ''thành viên'', ''giáo viên'' đều dùng gốc viên này. | Gương Hán-Việt | viên — trong tiếng Việt: ''nhân viên'', ''giáo viên'', ''thành viên'', ''quan viên'' đều dùng âm Hán-Việt này | Mở khoá kiến thức | Biết 贠 (dạng giản thể) mở khoá toàn bộ nhóm từ ''-viên'' trong tiếng Việt gốc Hán.", "Tự nguyên_Xie": "贠 là dạng giản thể của 貟 (viên — thành viên, nhân viên), trong đó 貝 (bối, tiền/báu vật) được thay bằng 贝 (giản thể). Xem 貟 để hiểu nguồn gốc đầy đủ. Bộ Bối trong 貟 gợi giá trị, vai trò có giá trong xã hội. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "người, kẻ, gã", "Hạng Tần Suất (Jun Da)": "7067.0", "Tần Suất % (Jun Da)": "99.9972300317", "GavinGrover_Once (Chiết tự trực tiếp)": "厶 + 贝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱厶贝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厶", "Unihan_Simplified (Chữ Giản thể)": "贠", "Unihan_Traditional (Chữ Phồn thể)": "貟", "Pinyin_Xie": "yuán", "Âm Hán Việt_Xie": "viên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ người hoặc làm họ trong tên riêng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踦', '{"9000": "7068.0", "Chữ Trung Quốc": "踦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 15 | nét | 踦 | kỳ | tượng hình | bàn chân, chân thọt | 踦 có bộ Túc (足, bàn chân) nhưng Wiktionary không cung cấp phân tích hình thanh hay hội ý chi tiết. Chữ tạo muộn, bộ Túc xác nhận liên quan đến chân/bước đi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": Bộ Chân (足) với dáng đi kỳ lạ — 踦 gợi hình ảnh bước chân không đều, một chân cao một chân thấp. | Gương Hán-Việt | kỳ — liên hệ với ''kỳ lạ'' nhưng dùng riêng cho chữ này trong nghĩa chân không bình thường | Mở khoá kiến thức | Biết 踦 nhận diện nhóm chữ bộ Túc chỉ các trạng thái chuyển động bất thường của chân.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi {{Han etym}} không có nội dung phân tích. 踦 chỉ bắp chân, hoặc hành động chạm/xuyên qua, hoặc đi cà thọt. Bộ Túc (足) xác nhận liên quan đến chân. Chưa có nguồn học thuật rõ ràng về cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chân; bàn chân; thọt; cà thọt; què", "Hạng Tần Suất (Jun Da)": "7068.0", "Tần Suất % (Jun Da)": "99.9972362331", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 奇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊奇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踦", "Unihan_Traditional (Chữ Phồn thể)": "踦", "Pinyin_Xie": "yǐ", "Âm Hán Việt_Xie": "khi, kỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho danh từ chỉ người hoặc làm động từ miêu tả tư thế đứng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遯', '{"9000": "7069.0", "Chữ Trung Quốc": "遯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 14 | nét | 辶 | sước | biểu nghĩa | đi, chuyển động | 豚 | đồn | biểu âm | 遯 = 辶 (Sước, biểu nghĩa: đi/chuyển động) + 豚 (Đồn, biểu âm); chữ hình thanh. Bộ Sước chỉ hành động di chuyển/trốn chạy, phần 豚 cho âm đọc. Chủ yếu dùng cho quẻ Độn (卦 thứ 33) trong Kinh Dịch.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"rộn\": Chân bước (辶) nhanh như lợn con (豚) sợ hãi — hình ảnh trốn chạy, rút lui khéo léo như trong quẻ Độn của Kinh Dịch. | Gương Hán-Việt | độn — trong tiếng Việt: ''độn thổ'' (trốn vào đất), ''ẩn độn'' (ẩn trốn) | Mở khoá kiến thức | Biết 遯 mở khoá quẻ Độn trong Kinh Dịch và nhóm từ chỉ sự rút lui, lẩn trốn trong văn ngôn.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 辵/辶 (đi bộ, biểu nghĩa) + 豚 (biểu âm). 遯 là biến thể của 遁 (trốn, lẩn trốn). Chữ này đặc biệt gắn với quẻ thứ 33 của Kinh Dịch (䷠), tên quẻ Độn, biểu trưng cho sự rút lui, ẩn náu đúng thời điểm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bỏ trốn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 豚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶豚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遯", "Unihan_Traditional (Chữ Phồn thể)": "遯", "Pinyin_Xie": "dùn", "Âm Hán Việt_Xie": "độn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ nơi chốn để biểu thị việc đi ẩn dật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鎌', '{"9000": "7070.0", "Chữ Trung Quốc": "鎌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 18 | nét | 金 | kim | biểu nghĩa | kim loại | 兼 | kiêm | biểu âm | 鎌 = 金 (Kim, biểu nghĩa: kim loại) + 兼 (Kiêm, biểu âm); chữ hình thanh. Bộ Kim xác nhận đây là dụng cụ bằng kim loại, phần 兼 cho âm đọc lián.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêm\" (dạng phổ biến: 廉): Kim loại (金) kiêm nhiệm (兼) nhiều việc — lưỡi liềm cắt lúa, một nhát gặt nhiều bông. | Gương Hán-Việt | liêm — trong tiếng Việt: ''liêm khiết'', ''liêm sỉ'' dùng chữ 廉 khác; 鎌 riêng cho lưỡi liềm nông cụ | Mở khoá kiến thức | Biết 鎌 nhận diện dụng cụ nông nghiệp Hán cổ và liên kết với bộ Kim trong công cụ kim loại.", "Tự nguyên_Xie": "Chữ hình thanh: 金 (kim loại, biểu nghĩa) + 兼 (biểu âm). 鎌 chỉ lưỡi liềm — dụng cụ thu hoạch lúa bằng kim loại. Bộ Kim xác nhận chất liệu sắt/thép, phần 兼 (kiêm, gánh vác nhiều) gợi ý cán liềm dài cắt được nhiều lúa một lúc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "liềm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 兼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金兼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鎌", "Unihan_Traditional (Chữ Phồn thể)": "鎌", "Pinyin_Xie": "lián", "Âm Hán Việt_Xie": "gươm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cái liềm, thường dùng trong văn bản cổ hoặc kết hợp thành từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靉', '{"9000": "7071.0", "Chữ Trung Quốc": "靉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 25 | nét | 雲 | vân | biểu nghĩa | mây | 愛 | ái | biểu âm | 靉 = 雲 (Vân, biểu nghĩa: mây) + 愛 (Ái, biểu âm); chữ hình thanh. Bộ Vân chỉ trạng thái mây trời u ám, phần 愛 cho âm đọc ài.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ái\": Mây (雲) dày như tình yêu (愛) bao phủ — 靉靆 là hình ảnh bầu trời u ám mây mù che khuất tầm nhìn. | Gương Hán-Việt | ái — 靉 chủ yếu xuất hiện trong từ ghép 靉靆 chỉ trời u ám; ''ái'' trong tiếng Việt thường gặp ở nghĩa yêu (愛) | Mở khoá kiến thức | Biết 靉 nhận diện nhóm chữ bộ Vũ/Mây miêu tả thời tiết u ám trong văn học cổ điển.", "Tự nguyên_Xie": "Chữ hình thanh: 雲 (mây, biểu nghĩa) + 愛 (biểu âm). 靉 dùng chủ yếu trong từ ghép 靉靆 (ái đãi) chỉ bầu trời u ám, mây mù dày đặc. Chữ hiếm, chỉ xuất hiện trong văn chương cổ điển khi miêu tả thời tiết âm u. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "円", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "雲 + 愛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰雲愛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "愛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雲", "Unihan_Simplified (Chữ Giản thể)": "叆", "Unihan_Traditional (Chữ Phồn thể)": "靉", "Pinyin_Xie": "ài", "Âm Hán Việt_Xie": "ái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ mô tả trạng thái mây che mù mịt, thường xuất hiện trong từ ghép ái đãi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韲', '{"9000": "7072.0", "Chữ Trung Quốc": "韲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 韭 | Số nét | 19 | nét | 韲 | tề | tượng hình | nghiền nát, làm vụn | 韲 có bộ Hẹ (韭, cây hẹ) nhưng Wiktionary không cung cấp nguồn gốc. Cấu trúc không rõ hình thanh hay hội ý. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": Hẹ (韭) bị nghiền vụn — 韲 gợi hành động xay nát, băm nhỏ thực phẩm như rau hẹ thái mịn. | Gương Hán-Việt | tề — ít dùng trong tiếng Việt hiện đại, chủ yếu gặp trong văn cổ | Mở khoá kiến thức | Biết 韲 nhận diện nhóm chữ bộ Hẹ liên quan đến thực phẩm và gia vị trong văn ngôn cổ.", "Tự nguyên_Xie": "Wiktionary không có mục từ nguồn gốc cho 韲 (usedForm: null). 韲 mang nghĩa ''nghiền nát, xay nhỏ thành mảnh vụn''. Bộ Hẹ (韭) xuất hiện trong cấu trúc nhưng vai trò không rõ. Chưa có nguồn học thuật xác nhận. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鲲", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 韭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱韭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "韲", "Unihan_Traditional (Chữ Phồn thể)": "韲", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ món rau muối hoặc làm động từ với nghĩa giã nhỏ thức ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('餖', '{"9000": "7073.0", "Chữ Trung Quốc": "餖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 15 | nét | 餖 | đậu | tượng hình | thức ăn bày trưng, đồ ăn trang trí | 餖 có bộ Thực (食, thức ăn) nhưng Wiktionary không cung cấp phân tích cấu trúc chi tiết. Bộ Thực xác nhận liên quan đến thực phẩm. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đậu\": Bộ Thực (食) + đậu — 飣餖 là thức ăn bày đẹp trên bàn tiệc, trông ngon nhưng chỉ để trang trí. | Gương Hán-Việt | đậu — ít dùng riêng lẻ trong tiếng Việt; 飣餖 gợi từ ''hoa lá cành'' — bề ngoài đẹp nhưng không có thực chất | Mở khoá kiến thức | Biết 餖 mở khoá thành ngữ 飣餖 và nhóm từ cổ chỉ sự phô trương hình thức trong văn ngôn.", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} không có nội dung phân tích. 餖 chủ yếu dùng trong từ ghép 飣餖 (đinh đậu) chỉ thức ăn bày trưng, đặt để cho đẹp mà không ăn, hoặc ẩn dụ những thứ vụn vặt không quan trọng. Bộ Thực (食) xác nhận liên quan đến thức ăn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "饾", "Hạng Tần Suất (Jun Da)": "6505.0", "Tần Suất % (Jun Da)": "99.9931329591", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 豆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠豆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "飠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豆", "Unihan_Simplified (Chữ Giản thể)": "饾", "Unihan_Traditional (Chữ Phồn thể)": "餖", "Pinyin_Xie": "dòu", "Âm Hán Việt_Xie": "đậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ việc bày biện thức ăn hoặc sắp đặt câu chữ trong văn chương. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麕', '{"9000": "7074.0", "Chữ Trung Quốc": "麕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 19 | nét | 麕 | quân | tượng hình | hươu nhỏ không sừng, hoẵng | 麕 có bộ Lộc (鹿, hươu) nhưng Wiktionary không cung cấp phân tích hình thanh chi tiết. Bộ Lộc xác nhận đây là loài hươu nai. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quân\": Bộ Lộc (鹿) — 麕 là loài hoẵng nhỏ không sừng, tụ tập thành đàn đông như quân lính. | Gương Hán-Việt | quân — ít dùng trong tiếng Việt hiện đại; liên hệ ''quần tụ'' (tụ tập đông đàn) | Mở khoá kiến thức | Biết 麕 nhận diện nhóm chữ bộ Lộc chỉ các loài hươu nai trong văn học cổ điển.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Wiktionary ghi đây là biến thể của 麇 (quân — hươu nhỏ/hoẵng). Bộ Lộc (鹿) xác nhận đây là loài hươu nhỏ không sừng (muntjac deer). Không có phân tích hình thanh/hội ý chi tiết. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tụ tập thành đàn", "Hạng Tần Suất (Jun Da)": "7074.0", "Tần Suất % (Jun Da)": "99.9972610388", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 囷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿囷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "囷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麕", "Unihan_Traditional (Chữ Phồn thể)": "麕", "Pinyin_Xie": "jūn", "Âm Hán Việt_Xie": "quân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ loài hoẵng hoặc làm động từ với nghĩa tụ tập đông đúc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菵', '{"9000": "7075.0", "Chữ Trung Quốc": "菵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菵 | võng | tượng hình | loài cỏ mọc nơi ẩm ướt | 菵 có bộ Thảo (艸, cỏ) nhưng Wiktionary không cung cấp phân tích hình thanh chi tiết. Bộ Thảo xác nhận đây là thực vật. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"võng\": Bộ Cỏ (艸) ở vùng ẩm — 菵草 là cỏ mọc xum xuê như màng lưới (võng) ven bờ ao. | Gương Hán-Việt | võng — ít dùng trong tiếng Việt; liên hệ ''võng lưới'' (mạng lưới, phủ rộng) | Mở khoá kiến thức | Biết 菵 nhận diện nhóm chữ bộ Thảo chỉ cỏ dại đặc thù trong văn học thực vật cổ.", "Tự nguyên_Xie": "Wiktionary ghi 菵 chỉ dùng trong từ ghép 菵草 — loại cỏ mọc gần bờ nước, nơi ẩm ướt, dùng làm thức ăn gia súc. Bộ Thảo (艸) xác nhận đây là thực vật. Không có phân tích hình thanh/hội ý. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loại cỏ, ra hoa vào mùa hè và mùa thu, sống gần bờ nước, chỗ ẩm ướt, làm thức ăn gia súc.", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 罔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹罔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "罔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菵", "Unihan_Traditional (Chữ Phồn thể)": "菵", "Pinyin_Xie": "wǎng", "Âm Hán Việt_Xie": "võng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cỏ hoang dã mọc ở nơi ẩm ướt dùng làm thức ăn gia súc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟭', '{"9000": "7076.0", "Chữ Trung Quốc": "蟭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 18 | nét | 蟭 | tiêu | tượng hình | loài côn trùng rất nhỏ | 蟭 có bộ Trùng (虫, côn trùng) nhưng Wiktionary không cung cấp phân tích cấu trúc chi tiết. Bộ Trùng xác nhận đây là loài côn trùng. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": Bộ Trùng (虫) — 蟭 là loài côn trùng cực nhỏ, nhỏ như hạt tiêu (tiêu) khó thấy bằng mắt thường. | Gương Hán-Việt | tiêu — ít dùng trong tiếng Việt; liên hệ ''tiêu điều'' (nhỏ bé, tan tác) | Mở khoá kiến thức | Biết 蟭 nhận diện nhóm chữ bộ Trùng chỉ côn trùng nhỏ bé trong văn học tự nhiên cổ đại.", "Tự nguyên_Xie": "Wiktionary để định nghĩa trống (rfdef). 蟭 chỉ loài côn trùng rất nhỏ. Bộ Trùng (虫) xác nhận đây là côn trùng. Không có phân tích hình thanh/hội ý. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trứng bọ ngựa", "Hạng Tần Suất (Jun Da)": "7076.0", "Tần Suất % (Jun Da)": "99.9972703409", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 焦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫焦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "焦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟭", "Unihan_Traditional (Chữ Phồn thể)": "蟭", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "giao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ tổ trứng của con bọ ngựa, thường dùng trong y học cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('錏', '{"9000": "7077.0", "Chữ Trung Quốc": "錏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 金 | kim | biểu nghĩa | kim loại | 亞 | á | biểu âm | 錏 = 金 (Kim, biểu nghĩa: kim loại) + 亞 (Á, biểu âm); chữ hình thanh. Bộ Kim chỉ chất liệu kim loại, phần 亞 cho âm đọc yā.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"á\": Kim loại (金) đứng thứ hai (亞 — á, thứ hai) — 錏 là thép phụ, mềm hơn thép chính. | Gương Hán-Việt | á — trong tiếng Việt ''á'' thường chỉ thứ hạng thứ hai: á quân, á hậu | Mở khoá kiến thức | Biết 錏 nhận diện nhóm chữ bộ Kim chỉ hợp kim và chất liệu kim loại đặc thù trong hoá học cổ đại.", "Tự nguyên_Xie": "Chữ hình thanh: 金 (kim loại, biểu nghĩa) + 亞 (biểu âm). 錏 chỉ loại thép mềm hoặc dùng trong tên hoá học ammonium (錏). Bộ Kim xác nhận chất liệu kim loại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "铔", "Hạng Tần Suất (Jun Da)": "7333.0", "Tần Suất % (Jun Da)": "99.998131305", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 亞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金亞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "铔", "Unihan_Traditional (Chữ Phồn thể)": "錏", "Pinyin_Xie": "yā", "Âm Hán Việt_Xie": "á", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ miếng sắt bảo vệ cổ trên áo giáp thời xưa hoặc dùng phiên âm hóa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稖', '{"9000": "7078.0", "Chữ Trung Quốc": "稖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 13 | nét | 稖 | bổng | tượng hình | cây ngô, bắp ngô | 稖 có bộ Hoà (禾, lúa/ngũ cốc) nhưng Wiktionary không cung cấp nguồn gốc (usedForm: null). Bộ Hoà xác nhận đây là loại cây lương thực. Chữ tạo muộn, dùng trong tiếng Hán phương ngữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bổng\": Bộ Lúa (禾) với cây thân to như gậy (bổng) — 稖 là ngô bắp, cây lương thực có thân cứng vươn cao. | Gương Hán-Việt | bổng — ít dùng trong tiếng Việt; liên hệ ''bổng'' nghĩa gậy/vũ khí do hình dạng thân cây ngô | Mở khoá kiến thức | Biết 稖 nhận diện nhóm chữ bộ Hoà chỉ các loại ngũ cốc và cây lương thực phương ngữ.", "Tự nguyên_Xie": "Wiktionary không có mục từ nguồn gốc cho 稖 (usedForm: null). 稖 chỉ cây ngô/bắp (玉米), đặc biệt dùng trong phương ngữ một số vùng Trung Quốc. Bộ Hoà (禾) xác nhận đây là cây lương thực ngũ cốc. Chưa có nguồn học thuật. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngô, bắp", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 咅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾咅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稖", "Unihan_Traditional (Chữ Phồn thể)": "稖", "Pinyin_Xie": "bàng", "Âm Hán Việt_Xie": "bang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ ghép trong khẩu ngữ để chỉ cây ngô hoặc bắp ngô. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笇', '{"9000": "7079.0", "Chữ Trung Quốc": "笇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 10 | nét | 笇 | toán | tượng hình | que tính, tính toán | 笇 có bộ Trúc (竹, tre) nhưng Wiktionary không cung cấp phân tích cấu trúc chi tiết. Đây là dạng biến thể của 筭 (toán — que tính). Bộ Trúc gợi que tính làm bằng tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toán\": Que tre (竹) dùng để tính toán — 笇 là dạng cổ của 算 (toán học), gợi hình ảnh que tính tre ngày xưa. | Gương Hán-Việt | toán — trong tiếng Việt: ''toán học'', ''tính toán'' đều từ gốc Hán-Việt này | Mở khoá kiến thức | Biết 笇 nhận ra gốc chữ tính toán trong văn hoá Hán cổ và liên kết với 算 (tính), 筭 (que tính).", "Tự nguyên_Xie": "Wiktionary ghi 笇 là biến thể của 筭 (toán). Bộ Trúc (竹) gợi que tính làm bằng tre — công cụ toán học cổ đại. Trong thời cổ, người Hán dùng những que tre nhỏ để tính toán. Không có phân tích hình thanh/hội ý riêng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "笇", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 卞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮卞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笇", "Unihan_Traditional (Chữ Phồn thể)": "笇", "Pinyin_Xie": "suàn", "Âm Hán Việt_Xie": "toán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Là chữ cổ, chủ yếu làm danh từ chỉ dụng cụ bằng tre hoặc dùng như chữ toán trong tính toán. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篂', '{"9000": "7080.0", "Chữ Trung Quốc": "篂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 15 | nét | 竹 | trúc | biểu nghĩa | tre | 星 | tinh | biểu âm | 篂 = 竹 (Trúc, biểu nghĩa: tre) + 星 (Tinh, biểu âm); chữ hình thanh. Bộ Trúc xác nhận đây là vật dụng hoặc đặc tính của cây tre, phần 星 cho âm đọc xīng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tinh\": Tre (竹) sáng như sao (星 — tinh tú) — 篂 là loại dụng cụ tre đặc biệt, có thể là ống tre hoặc lạt tre. | Gương Hán-Việt | tinh — ít dùng trong tiếng Việt với nghĩa này; liên hệ ''tinh tú'' (sao sáng) | Mở khoá kiến thức | Biết 篂 nhận diện nhóm chữ bộ Trúc chỉ dụng cụ tre trong văn hoá Hán cổ.", "Tự nguyên_Xie": "Chữ hình thanh: 竹 (tre, biểu nghĩa) + 星 (biểu âm). Wiktionary cung cấp cấu trúc rõ ràng nhưng không có định nghĩa chi tiết cho 篂. Bộ Trúc xác nhận liên quan đến tre hoặc dụng cụ bằng tre. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "炂", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 星", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮星", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "星", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篂", "Unihan_Traditional (Chữ Phồn thể)": "篂", "Pinyin_Xie": "xīng", "Âm Hán Việt_Xie": "tinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là chữ hiếm gặp, chủ yếu làm danh từ trong văn bản cổ để chỉ các vật dụng làm từ tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('緛', '{"9000": "7081.0", "Chữ Trung Quốc": "緛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 15 | nét | 緛 | nhuận | tượng hình | rút ngắn, co lại | 緛 có bộ Mịch (糸, sợi tơ/chỉ) nhưng Wiktionary không cung cấp phân tích hình thanh chi tiết. Bộ Mịch xác nhận liên quan đến sợi, vải, hoặc tính co giãn. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhuyễn\": Bộ Sợi (糸) co rút — 緛 là hành động rút ngắn như sợi vải khi co lại; ''nhuận'' gợi liên tưởng mềm mại, dẻo dai. | Gương Hán-Việt | nhuận — ít dùng trong tiếng Việt với nghĩa này; liên hệ ''nhuần nhị'' (mềm mại, trơn tru) | Mở khoá kiến thức | Biết 緛 nhận diện nhóm chữ bộ Mịch chỉ các trạng thái co giãn của sợi vải.", "Tự nguyên_Xie": "Wiktionary để định nghĩa trống (rfdef). 緛 mang nghĩa rút ngắn, co lại. Bộ Mịch (糸, sợi chỉ) gợi ý sợi dây co rút lại. Không có phân tích hình thanh/hội ý. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rút ngắn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 耎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹耎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "緛", "Unihan_Traditional (Chữ Phồn thể)": "緛", "Pinyin_Xie": "ruǎn", "Âm Hán Việt_Xie": "nhuyễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ chỉ sự co rút hoặc tính từ chỉ tính chất mềm yếu của tơ lụa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('縿', '{"9000": "7082.0", "Chữ Trung Quốc": "縿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 17 | nét | 糸 | mịch | biểu nghĩa | sợi tơ, vải | 彡 | sam | biểu nghĩa | tua rủ, nét sóng | 縿 gồm bộ 糸 (Mịch, biểu nghĩa: sợi tơ, vải) và 彡 (Sam, biểu nghĩa: nét tua, rủ xuống); chữ hội ý — kết hợp tơ lụa và tua rủ để chỉ dải lụa trang trí. Chưa xác định rõ cấu trúc hình thanh hay hội ý do thiếu nguồn anchor Wiktionary cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sam\": hình ảnh dải lụa (糸) với những tua rủ (彡) trang trí — chiếc biểu ngữ sang trọng treo trước cổng đền. | Gương Hán-Việt | 縿 chưa phổ biến trong từ Hán-Việt thông dụng tiếng Việt. | Mở khoá kiến thức | Biết 縿 giúp nhận ra các từ chỉ đồ trang trí vải lụa trong văn học cổ.", "Tự nguyên_Xie": "Tiểu triện | 縿(shān): chưa có nguồn Wiktionary chi tiết. Từ cấu trúc chữ, 縿 thuộc bộ 糸 (sợi tơ), chỉ dải lụa trang trí, rìa vải, biểu ngữ. Có thể là chữ hình thanh hoặc hội ý ghép từ các thành tố liên quan đến vải lụa. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rìa; biểu ngữ trang trí", "Hạng Tần Suất (Jun Da)": "7082.0", "Tần Suất % (Jun Da)": "99.9973261537", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 參", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹參", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "參", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "縿", "Unihan_Traditional (Chữ Phồn thể)": "縿", "Pinyin_Xie": "shān", "Âm Hán Việt_Xie": "san", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ phần tua rua hoặc dải lụa trang trí trên cán cờ thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕚', '{"9000": "7083.0", "Chữ Trung Quốc": "蕚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕚 | ngạc | tượng hình | đài hoa, lá bao quanh hoa | 蕚 là chữ tượng hình/hội ý chỉ đài hoa (phần lá xanh bao quanh hoa). Không có nguồn Wiktionary rõ ràng về cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạc\": phần đài hoa (蕚) giữ chặt cánh hoa như người anh giữ người em — nghĩa cổ \"em trai\" xuất phát từ hình ảnh hỗ trợ, nâng đỡ. | Gương Hán-Việt | 蕚 ít gặp trong từ Hán-Việt thông dụng; liên quan đến 萼 (ngạc — đài hoa). | Mở khoá kiến thức | Biết 蕚 giúp nhận ra các thuật ngữ thực vật học cổ điển trong thơ văn chữ Hán.", "Tự nguyên_Xie": "蕚 (è): chưa có nguồn Wiktionary chi tiết. Chữ chỉ đài hoa (calyx) — phần lá xanh bao quanh cánh hoa, bảo vệ nụ hoa. Cũng có nghĩa \"em trai\" trong văn học cổ. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蕚", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蕚", "Unihan_Traditional (Chữ Phồn thể)": "蕚", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ngạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong sinh học để chỉ bộ phận nâng đỡ cánh hoa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝿', '{"9000": "7084.0", "Chữ Trung Quốc": "蝿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 蝿 | anh | tượng hình | con ruồi | 蝿 là chữ tượng hình/hội ý chỉ con ruồi (flies). Không có dữ liệu Wiktionary cụ thể về cấu trúc hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"anh\": dù cùng âm với 英 (anh — xuất sắc), 蝿 lại chỉ con ruồi — nhắc nhở rằng chữ Hán cùng âm có thể mang nghĩa hoàn toàn trái ngược. | Gương Hán-Việt | 蝿 ít dùng; dạng phổ biến hơn là 蠅 (anh — con ruồi). | Mở khoá kiến thức | Biết 蝿 giúp nhận dạng các chữ chỉ côn trùng có bộ 虫 trong văn học và y học cổ.", "Tự nguyên_Xie": "蝿 (yíng): chưa có nguồn Wiktionary chi tiết về cấu trúc cụ thể. Chữ chỉ con ruồi. Đây có thể là dạng biến thể của 蠅 (anh — con ruồi). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ ba lá", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蝿", "Unihan_Traditional (Chữ Phồn thể)": "蝿", "Pinyin_Xie": "yíng", "Âm Hán Việt_Xie": "anh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loài côn trùng bay bẩn thỉu trong đời sống hàng ngày. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袃', '{"9000": "7085.0", "Chữ Trung Quốc": "袃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袃 | sài | tượng hình | (nghĩa không rõ) | 袃 là chữ hiếm gặp, thuộc bộ 衣 (y — áo). Không có dữ liệu Wiktionary hay CHISE về cấu trúc cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sài\": chữ thuộc bộ Áo (衣) — nhớ đây là thứ gì đó liên quan đến trang phục trong tiếng Hán cổ. | Gương Hán-Việt | 袃 không xuất hiện trong từ Hán-Việt thông dụng tiếng Việt. | Mở khoá kiến thức | 袃 là chữ hiếm, chủ yếu gặp trong văn bản cổ hoặc tự điển chuyên khảo.", "Tự nguyên_Xie": "袃 (chài): chưa có nguồn Wiktionary chi tiết. Thuộc bộ 衣 liên quan đến trang phục. Nghĩa và cấu trúc cụ thể chưa được học thuật ghi chép rõ ràng. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "袃", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "切 + 衣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱切衣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "切", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "袃", "Unihan_Traditional (Chữ Phồn thể)": "袃", "Pinyin_Xie": "chài", "Âm Hán Việt_Xie": "sài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn bản cổ để chỉ phần vạt áo hoặc nếp gấp của trang phục. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軅', '{"9000": "7086.0", "Chữ Trung Quốc": "軅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 身 | Số nét | 19 | nét | 軅 | yểm | tượng hình | (dáng người cong, cúi) | 軅 là chữ hiếm, thuộc bộ 身 (thân — thân thể). Không có nguồn Wiktionary chi tiết về cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yểm\": thuộc bộ Thân (身) — chữ cổ liên quan đến dáng thân thể hoặc vật phẩm trang phục quý tộc. | Gương Hán-Việt | 軅 không có trong từ Hán-Việt thông dụng tiếng Việt. | Mở khoá kiến thức | 軅 là chữ hiếm, chủ yếu xuất hiện trong tự điển chuyên khảo.", "Tự nguyên_Xie": "軅 (yǎn/yan): chưa có nguồn Wiktionary chi tiết. Thuộc bộ 身 (thân thể). Nghĩa trong từ điển là 绅 (dây đai quý tộc). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "绅", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "身 + 雁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰身雁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "身", "Unihan_Simplified (Chữ Giản thể)": "軅", "Unihan_Traditional (Chữ Phồn thể)": "軅", "Pinyin_Xie": "yan", "Âm Hán Việt_Xie": "yểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ cổ ít dùng, chủ yếu làm danh từ chỉ trang phục hoặc bộ phận cơ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軓', '{"9000": "7087.0", "Chữ Trung Quốc": "軓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 10 | nét | 軓 | phạm | tượng hình | phần dưới của xe cổ | 軓 thuộc bộ 車 (xa — xe). Không có dữ liệu CHISE về cấu trúc hình thanh hay hội ý. Chỉ một bộ phận của xe cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phạm\": bộ Xa (車) chỉ xe — 軓 là bộ phận cụ thể của chiếc xe ngựa thời cổ đại, như thanh ngang giữ đáy xe. | Gương Hán-Việt | 軓 không xuất hiện trong từ Hán-Việt thông dụng tiếng Việt. | Mở khoá kiến thức | 軅 là chữ chuyên ngành kỹ thuật xe ngựa cổ đại, chủ yếu gặp trong khảo cổ học.", "Tự nguyên_Xie": "Tiểu triện | 軓 (fàn): thuộc bộ 車 (xe). Nghĩa trong các tự điển là một bộ phận của xe ngựa cổ đại (phần đáy hay thanh ngang dưới). Nguồn Wiktionary chỉ có thông tin phát âm, thiếu giải thích cấu trúc. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "軓", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 凡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車凡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "凡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "軓", "Unihan_Traditional (Chữ Phồn thể)": "軓", "Pinyin_Xie": "fàn", "Âm Hán Việt_Xie": "phạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ bộ phận của xe ngựa cổ trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鉄', '{"9000": "7088.0", "Chữ Trung Quốc": "鉄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 金 | kim | biểu nghĩa | kim loại | 失 | thất | biểu âm | mất đi | 鉄 = 金 (Kim, biểu nghĩa: kim loại) + 失 (Thất, biểu âm); chữ hình thanh (psc). Đây là dạng biến thể/cổ của chữ 鐵 (sắt), được dùng trong tiếng Nhật và một số văn bản cổ Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiết\": Kim (金) + thất (失) — sắt là kim loại bị \"mất\" đi vẻ sáng bóng (gỉ sét), nhưng lại vô cùng kiên cứng. | Gương Hán-Việt | thiết trong \"thiết lộ\" (đường sắt), \"bạch thiết\" (sắt trắng), liên quan đến 鐵 phồn thể. | Mở khoá kiến thức | Biết 鉄/thiết mở khoá: 鉄道 (thiết đạo — đường sắt), 鉄路 (thiết lộ), các từ về kim loại cứng.", "Tự nguyên_Xie": "鉄 (zhí/tiě): dạng rút gọn/biến thể của 鐵 (sắt). Gồm bộ 金 (kim loại, biểu nghĩa) và 失 (Thất, biểu âm). Trong tiếng Nhật, 鉄 là dạng chuẩn cho 鉄道 (đường sắt). Nghĩa: sắt (nguyên tố Fe), cứng rắn, kiên định. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sắt, Fe", "Hạng Tần Suất (Jun Da)": "7088.0", "Tần Suất % (Jun Da)": "99.9973757651", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 失", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金失", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "失", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鉄", "Unihan_Traditional (Chữ Phồn thể)": "鉄", "Pinyin_Xie": "zhí", "Âm Hán Việt_Xie": "thiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ kim loại hoặc làm định ngữ bổ nghĩa cho danh từ khác để chỉ tính chất cứng rắn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鯕', '{"9000": "7089.0", "Chữ Trung Quốc": "鯕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 19 | nét | 魚 | ngư | biểu nghĩa | cá | 其 | kỳ | biểu âm | 鯕 thuộc bộ 魚 (Ngư — cá), chỉ một loài cá. Có thể là hình thanh với phần âm là 其 (kỳ), dù CHISE không xác nhận cấu trúc rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": bộ Ngư (魚 — cá) với âm kỳ — loài cá kỳ lạ dưới đáy biển sâu, không thường gặp trong ngữ vựng thông thường. | Gương Hán-Việt | 鯕 không xuất hiện trong từ Hán-Việt thông dụng; chủ yếu là thuật ngữ ngư học. | Mở khoá kiến thức | Biết 鯕 giúp đọc tài liệu sinh học, ngư học trong văn bản chữ Hán cổ và khoa học.", "Tự nguyên_Xie": "Tiểu triện | 鯕 (qí): thuộc bộ 魚 (cá). Chỉ một số loài cá: cá tráp, cá chép trắng (Cyprinus carpio), cá Larimichthys polyactis. Tiểu triện ghi nhận dạng chữ. Chữ dùng để chỉ các loài cá cụ thể trong tự nhiên. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá tráp", "Hạng Tần Suất (Jun Da)": "7095.0", "Tần Suất % (Jun Da)": "99.9974036715", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 其", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚其", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "其", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鲯", "Unihan_Traditional (Chữ Phồn thể)": "鯕", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng đầu trong tên gọi các loài cá biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶕', '{"9000": "7090.0", "Chữ Trung Quốc": "鶕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 20 | nét | 鶕 | am | tượng hình | loài chim cút (biến thể cũ của 鵪) | 鶕 là biến thể cũ của 鵪 (chim cút), thuộc bộ 鳥 (điểu — chim). Không có dữ liệu cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"am\": bộ Điểu (鳥 — chim) với âm am — con chim cút nhỏ bé, ẩm mình trong bóng tối (am) của đồng cỏ. | Gương Hán-Việt | 鶕 là biến thể cổ; dạng thông dụng hơn là 鵪 trong 鵪鶉 (am thuần — chim cút). | Mở khoá kiến thức | Biết 鶕 giúp nhận ra các biến thể chữ chim trong văn bản cổ và từ điển chuyên khảo.", "Tự nguyên_Xie": "鶕 (ān): biến thể cổ của 鵪 (chim cút, ān). Thuộc bộ 鳥 (chim). Chim cút (quail) là loài chim nhỏ thường gặp trong nông nghiệp và ẩm thực. chưa có nguồn học thuật đầy đủ về nguồn gốc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "biến thể cũ của 鵪", "Hạng Tần Suất (Jun Da)": "7090.0", "Tần Suất % (Jun Da)": "99.9973881679", "GavinGrover_Once (Chiết tự trực tiếp)": "音 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰音鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鳥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "音", "Unihan_Simplified (Chữ Giản thể)": "鶕", "Unihan_Traditional (Chữ Phồn thể)": "鶕", "Pinyin_Xie": "ān", "Âm Hán Việt_Xie": "am", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loài chim, xuất hiện chủ yếu trong các văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麨', '{"9000": "7091.0", "Chữ Trung Quốc": "麨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 麥 | Số nét | 15 | nét | 麥 | mạch | biểu nghĩa | lúa mì, ngũ cốc | 炒 | sao | biểu âm | rang, xào | 麨 thuộc bộ 麥 (Mạch — lúa mì, ngũ cốc). Có thể là hình thanh với âm liên quan đến 炒 (rang). Chỉ bột gạo/ngũ cốc đã rang xong rồi xay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sao\": bộ Mạch (麥 — ngũ cốc) + âm sao — bột ngũ cốc đã \"sao\" (rang) thơm lừng, dạng thực phẩm cổ đại. | Gương Hán-Việt | sao trong nghĩa rang xay ngũ cốc; 麨 là thuật ngữ ẩm thực cổ điển. | Mở khoá kiến thức | Biết 麨 giúp đọc các bản tả về thực phẩm truyền thống trong văn bản y học và ẩm thực cổ Trung Hoa.", "Tự nguyên_Xie": "麨 (chǎo): thuộc bộ 麥 (lúa mì/ngũ cốc, biểu nghĩa). Chỉ loại bột làm từ gạo hoặc ngũ cốc rang xong rồi xay — một dạng thực phẩm chế biến cổ đại. Âm đọc gợi liên tưởng đến 炒 (rang/xào). Có tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bột gạo rang", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "麥 + 少", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰麥少", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "少", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "麥", "Unihan_Simplified (Chữ Giản thể)": "麨", "Unihan_Traditional (Chữ Phồn thể)": "麨", "Pinyin_Xie": "chǎo", "Âm Hán Việt_Xie": "xiểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ món ăn làm từ bột ngũ cốc rang chín. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脭', '{"9000": "7094.0", "Chữ Trung Quốc": "脭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 脭 | thừa | tượng hình | thịt mềm, béo | 脭 thuộc bộ 肉/月 (nhục — thịt). Không có dữ liệu Wiktionary hay CHISE về cấu trúc cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thừa\": bộ Nhục (月/肉 — thịt) — miếng thịt mềm mại, béo ngon, \"thừa\" mỡ trong bữa tiệc cổ đại. | Gương Hán-Việt | 脭 không xuất hiện trong từ Hán-Việt thông dụng tiếng Việt. | Mở khoá kiến thức | 脭 là chữ hiếm, chủ yếu gặp trong tự điển chuyên khảo ẩm thực cổ đại.", "Tự nguyên_Xie": "脭 (chéng): chưa có nguồn Wiktionary chi tiết. Thuộc bộ 肉 (thịt). Nghĩa là thịt mềm, béo ngậy. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thịt mềm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 呈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月呈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "呈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脭", "Unihan_Traditional (Chữ Phồn thể)": "脭", "Pinyin_Xie": "chéng", "Âm Hán Việt_Xie": "trình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này dùng làm danh từ chỉ phần thịt mềm hoặc tính từ miêu tả trạng thái thịt béo mềm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲯', '{"9000": "7095.0", "Chữ Trung Quốc": "鲯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 鱼 | ngư | biểu nghĩa | cá | 其 | kỳ | biểu âm | 鲯 thuộc bộ 鱼 (Ngư — cá), là dạng giản thể của 鯕. Chỉ một số loài cá: cá tráp, cá chép trắng, cá dorado.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": bộ Ngư (鱼 — cá) với âm kỳ — loài cá kỳ đặc, màu sắc rực rỡ như cá dorado ngoài biển khơi. | Gương Hán-Việt | kỳ trong 鲯鲭科 (họ cá dorado); tên ngư học chuyên ngành. | Mở khoá kiến thức | Biết 鲯 giúp đọc tài liệu ngư học và phân loại sinh vật biển trong chữ Hán hiện đại.", "Tự nguyên_Xie": "Tiểu triện | 鲯 (qí): dạng giản thể của 鯕 (cá kỳ), thuộc bộ 鱼 (cá). Chỉ loài cá dorado (Coryphaena hippurus), cá chép trắng, hoặc một số loài cá khác. Tiểu triện ghi nhận dạng chữ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá kỳ thu; kì; như \"kì thu (cá dorado)\" (gdhn)", "Hạng Tần Suất (Jun Da)": "7095.0", "Tần Suất % (Jun Da)": "99.9974036715", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 其", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼其", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "其", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲯", "Unihan_Traditional (Chữ Phồn thể)": "鯕", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường kết hợp với chữ khác để tạo thành danh từ chỉ loài cá kỳ thu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鐏', '{"9000": "7096.0", "Chữ Trung Quốc": "鐏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 20 | nét | 金 | kim | biểu nghĩa | kim loại | 尊 | tôn | biểu âm | tôn trọng, bình rượu | 鐏 = 金 (Kim, biểu nghĩa: kim loại) + 尊 (Tôn, biểu âm); chữ hình thanh (psc). Chỉ một đầu kim loại hình nón ở cuối vũ khí kích để cắm xuống đất, hoặc loại công cụ nông nghiệp đầu kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tôn\": Kim (金) + tôn (尊) — phần kim loại \"tôn\" quý ở đuôi cán vũ khí, giúp chiếc kích đứng vững trên đất. | Gương Hán-Việt | tôn trong 鐏臼 (tôn cữu — đầu kích và hốc đất); thuật ngữ vũ khí cổ đại. | Mở khoá kiến thức | Biết 鐏 giúp đọc các mô tả vũ khí và đồ dùng nghi lễ trong văn bản khảo cổ học.", "Tự nguyên_Xie": "Tiểu triện | 鐏 (zūn): chữ hình thanh, gồm 金 (kim loại, biểu nghĩa) và 尊 (Tôn, biểu âm). Nghĩa lịch sử: đầu kim loại hình nón ở đuôi vũ khí kích (dagger-axe) cho phép cắm xuống đất; cũng là một loại công cụ nông nghiệp đầu kim loại. Dạng 鐏 còn là biến thể của 尊 (bình rượu). Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鐏", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 尊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金尊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "𨱔", "Unihan_Traditional (Chữ Phồn thể)": "鐏", "Pinyin_Xie": "zūn", "Âm Hán Việt_Xie": "tôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ phần bọc kim loại ở đuôi cán giáo hoặc thương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魾', '{"9000": "7097.0", "Chữ Trung Quốc": "魾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 魾 | phi | tượng hình | loài cá (dwarf goonch) | 魾 thuộc bộ 魚 (Ngư — cá), chỉ loài cá dwarf goonch (Bagarius bagarius). Không có dữ liệu CHISE về cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phi\": bộ Ngư (魚 — cá) với âm phi — loài cá dữ \"phi\" (bay) nhanh như tên trong dòng nước, ăn thịt hung hãn. | Gương Hán-Việt | phi trong ngữ nghĩa cá phi/phi ngư — không thông dụng trong từ Hán-Việt. | Mở khoá kiến thức | Biết 魾 giúp đọc tài liệu sinh học ngư học về các loài cá ít gặp.", "Tự nguyên_Xie": "魾 (pī/pí): thuộc bộ 魚 (cá). Chỉ loài cá dwarf goonch (Bagarius bagarius), loài cá dữ sinh sống ở sông ngòi Nam Á. Tiểu triện ghi nhận dạng chữ. chưa có nguồn học thuật chi tiết về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại cá)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 丕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚丕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "魾", "Unihan_Traditional (Chữ Phồn thể)": "魾", "Pinyin_Xie": "pī", "Âm Hán Việt_Xie": "phi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ một loài cá nước ngọt trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眎', '{"9000": "7098.0", "Chữ Trung Quốc": "眎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 10 | nét | 目 | mục | biểu nghĩa | mắt | 示 | thị | biểu âm | chỉ ra, thể hiện | 眎 gồm bộ 目 (Mục, biểu nghĩa: mắt) và phần âm 示 (Thị). Đây là dạng biến thể cổ của 視 (nhìn, xem). Bộ mắt (目) kết hợp với thị (示 — chỉ ra) gợi hành động nhìn thấy, quan sát.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thị\": Mục (目 — mắt) + thị (示 — chỉ ra) — mắt nhìn thấy (thị), quan sát mọi thứ xung quanh. | Gương Hán-Việt | thị trong \"thị giác\" (thị lực), \"thị sát\" (kiểm tra), \"điện thị\" (truyền hình). | Mở khoá kiến thức | Biết 眎/thị mở khoá: 視力 (thị lực — thị lực), 視察 (thị sát — kiểm tra), 視野 (thị dã — tầm nhìn).", "Tự nguyên_Xie": "眎 (shì): dạng biến thể của 視 (nhìn, quan sát). Theo Wiktionary, đây là hình thức thay thế của 視. Bộ 目 (mắt, biểu nghĩa) kết hợp với âm từ 示. Tiểu triện ghi nhận dạng chữ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhìn kỹ", "Hạng Tần Suất (Jun Da)": "438.0", "Tần Suất % (Jun Da)": "72.9831852897", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 示", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目示", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "示", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "视", "Unihan_Traditional (Chữ Phồn thể)": "眎", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này dùng làm động từ chỉ hành vi nhìn hoặc xem xét sự vật, tương tự như chữ thị. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窋', '{"9000": "7099.0", "Chữ Trung Quốc": "窋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 10 | nét | 穴 | huyệt | biểu nghĩa | hang, hốc | 出 | xuất | biểu âm | ra ngoài | 窋 thuộc bộ 穴 (Huyệt — hang, lỗ hốc). Có thể là hình thanh với âm liên quan đến 出 (xuất) hay 朮. Nghĩa: trong một lỗ hốc, trốn trong hang.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"truật\": bộ Huyệt (穴 — hang hốc) — ẩn mình trong cái hang tối, co rút lại như trong lỗ huyệt. | Gương Hán-Việt | truật ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 窋 giúp đọc các chữ liên quan đến hang, hốc, ẩn náu trong văn học cổ.", "Tự nguyên_Xie": "窋 (zhú): thuộc bộ 穴 (hang, hốc). Nghĩa là ở trong hốc/hang; liên quan đến việc trốn hoặc ẩn náu. Tiểu triện ghi nhận dạng chữ. chưa có nguồn học thuật chi tiết về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trong một cái lỗ", "Hạng Tần Suất (Jun Da)": "7099.0", "Tần Suất % (Jun Da)": "99.9974176247", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 出", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴出", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "出", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窋", "Unihan_Traditional (Chữ Phồn thể)": "窋", "Pinyin_Xie": "zhú", "Âm Hán Việt_Xie": "quật, truật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này dùng làm danh từ chỉ không gian trong hang hoặc động từ chỉ hành động chui từ trong hang ra. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('縡', '{"9000": "7100.0", "Chữ Trung Quốc": "縡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 16 | nét | 縡 | tải | tượng hình | công việc, sự vụ | 縡 thuộc bộ 糸 (Mịch — tơ, sợi). Không có dữ liệu Wiktionary hay CHISE chi tiết về cấu trúc cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tải\": bộ Mịch (糸 — sợi tơ) — công việc sắp xếp, quản lý như người thợ dệt sắp xếp từng sợi tơ một cách cẩn thận. | Gương Hán-Việt | tải ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | 縡 là chữ hiếm, chủ yếu gặp trong tự điển chuyên khảo và văn bản hành chính cổ.", "Tự nguyên_Xie": "縡 (zài): thuộc bộ 糸 (tơ, sợi). Nghĩa là công việc, sự vụ, vấn đề. Có thể liên quan đến việc quản lý, tổ chức (như sắp xếp sợi). chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "công việc; Vân đê", "Hạng Tần Suất (Jun Da)": "7100.0", "Tần Suất % (Jun Da)": "99.9974253765", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 宰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹宰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "縡", "Unihan_Traditional (Chữ Phồn thể)": "縡", "Pinyin_Xie": "zài", "Âm Hán Việt_Xie": "tể", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ trong văn ngôn để chỉ các công việc hoặc sự vụ cần xử lý. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鉏', '{"9000": "7101.0", "Chữ Trung Quốc": "鉏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 金 | kim | biểu nghĩa | kim loại | 且 | thả | biểu âm | vả lại | 鉏 thuộc bộ 金 (Kim — kim loại). Có thể là hình thanh với thành phần âm là 且 (thả). Chỉ cái cuốc, dụng cụ nông nghiệp bằng kim loại để xới đất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thừ\": bộ Kim (金 — kim loại) — cái cuốc bằng sắt, dùng để nhổ (thừ — nhổ bứng) cỏ dại trên ruộng. | Gương Hán-Việt | thừ/thư ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 鉏 giúp đọc các tài liệu nông nghiệp và ẩn dụ về loại bỏ điều xấu trong văn học cổ.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 鉏 (chú): thuộc bộ 金 (kim loại). Chỉ cái cuốc (hoe) — dụng cụ nông nghiệp bằng sắt để xới đất, nhổ cỏ. Cũng có nghĩa chuyển: loại bỏ, thanh trừ. Wiktionary chỉ có thông tin phát âm cơ bản; đại triện và tiểu triện ghi nhận. chưa có nguồn học thuật chi tiết về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cuốc; Ghi chú: 另见jǔ", "Hạng Tần Suất (Jun Da)": "7101.0", "Tần Suất % (Jun Da)": "99.9974331282", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鉏", "Unihan_Traditional (Chữ Phồn thể)": "鉏", "Pinyin_Xie": "chú", "Âm Hán Việt_Xie": "sừ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ nông cụ hoặc động từ chỉ hoạt động làm cỏ, xới đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('謦', '{"9000": "7102.0", "Chữ Trung Quốc": "謦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 18 | nét | 言 | ngôn | biểu nghĩa | lời nói | 殸 | khánh | biểu âm | tiếng vang | 謦 thuộc bộ 言 (Ngôn — lời nói). Không có dữ liệu Wiktionary chi tiết. Chỉ tiếng ho nhẹ để thu hút sự chú ý, hoặc nói khẽ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khánh\": bộ Ngôn (言 — nói) với âm khánh — tiếng ho khánh khách, nói khẽ trong không gian yên tĩnh, thân mật. | Gương Hán-Việt | khánh trong 謦欬 (khánh khải — tiếng ho khẽ, tiếng nói thân mật). | Mở khoá kiến thức | Biết 謦 giúp đọc thành ngữ 謦欬之間 và các mô tả về giao tiếp thân mật trong thơ văn cổ.", "Tự nguyên_Xie": "謦 (qìng): thuộc bộ 言 (lời nói). Nghĩa là ho khẽ để thu hút sự chú ý; tiếng nói khẽ, thì thầm. Trong 謦欬 (thì thầm/ho nhẹ) gặp trong thành ngữ \"謦欬之間\" (trong vòng tiếng thì thầm — rất gần gũi thân mật). chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ho khẽ", "Hạng Tần Suất (Jun Da)": "7102.0", "Tần Suất % (Jun Da)": "99.9974357122", "GavinGrover_Once (Chiết tự trực tiếp)": "殸 + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱殸言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "殸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "謦", "Unihan_Traditional (Chữ Phồn thể)": "謦", "Pinyin_Xie": "qìng", "Âm Hán Việt_Xie": "khánh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn cổ để chỉ tiếng ho nhẹ hoặc đàm thoại nhỏ nhẹ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麹', '{"9000": "7103.0", "Chữ Trung Quốc": "麹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 麥 | Số nét | 15 | nét | 麥 | mạch | biểu nghĩa | lúa mì, ngũ cốc | 匊 | cúc | biểu âm | 麹 = 麥 (Mạch, biểu nghĩa: lúa mì/ngũ cốc) + 匊 (Cúc, biểu âm); chữ hình thanh (psc). Bộ 麥 chỉ ngũ cốc, 匊 cho âm. Chỉ men rượu (yeast) dùng trong ủ rượu từ ngũ cốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khúc\": Mạch (麥 — lúa mì) + cúc (匊) — ngũ cốc lên men \"khúc\" khuỷu qua quá trình phát tán men, tạo ra rượu thơm. | Gương Hán-Việt | khúc trong 麹糵 (khúc nghê — men rượu), 麹蘗 (men ngũ cốc). | Mở khoá kiến thức | Biết 麹/khúc giúp đọc các công thức ủ rượu cổ truyền và tài liệu ẩm thực/y học về men vi sinh.", "Tự nguyên_Xie": "麹 (qū): chữ hình thanh, gồm 麥 (lúa mì/ngũ cốc, biểu nghĩa) và 匊 (Cúc, biểu âm). Chỉ men rượu (yeast, leaven) — ngũ cốc (麥) lên men để tạo ra rượu. Tiểu triện ghi nhận dạng chữ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "men rượu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "麦 + 匊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰麦匊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "麦", "Unihan_Simplified (Chữ Giản thể)": "麹", "Unihan_Traditional (Chữ Phồn thể)": "麹", "Pinyin_Xie": "qū", "Âm Hán Việt_Xie": "khúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loại men dùng trong chế biến rượu hoặc thực phẩm lên men. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繐', '{"9000": "7104.0", "Chữ Trung Quốc": "繐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 18 | nét | 糸 | mịch | biểu nghĩa | sợi tơ, vải | 惠 | huệ | biểu âm | ơn huệ | 繐 = 糸 (Mịch, biểu nghĩa: sợi tơ/vải) + 惠 (Huệ, biểu âm); chữ hình thanh. Bộ 糸 cho biết liên quan đến vải sợi; 惠 gợi âm đọc suì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuy\" (vải mịn): sợi tơ (糸) mềm mại như lòng người ân huệ (惠) — vải tang lễ nhẹ tựa hơi sương. | Gương Hán-Việt | tuy — ít dùng độc lập trong tiếng Việt Hán, thấy trong văn cổ chỉ loại vải mịn mỏng dùng trong tang lễ. | Mở khoá kiến thức | Biết 繐 (tuy) giúp nhận diện từ ghép cổ điển như 繐帳 (màn vải mỏng trong tang lễ) và hiểu bộ 糸 (mịch) liên quan tơ lụa.", "Tự nguyên_Xie": "Theo Wiktionary, 繐 là chữ hình thanh: 糸 (biểu nghĩa: vải/sợi) + 惠 (biểu âm, gợi âm suì). Chỉ loại vải mịn mỏng dùng trong tang lễ thời cổ, cũng là dạng thay thế của 穗 (tua rủ). Không tìm thấy giáp cốt hay kim văn; chữ xuất hiện rõ từ thời tiểu triện. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vải mịn và lỏng lẻo; tua", "Hạng Tần Suất (Jun Da)": "7104.0", "Tần Suất % (Jun Da)": "99.9974434639", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 惠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹惠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "惠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "繐", "Unihan_Traditional (Chữ Phồn thể)": "繐", "Pinyin_Xie": "suì", "Âm Hán Việt_Xie": "huệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn cổ để chỉ loại vải thưa mịn hoặc tua trang trí trên áo mũ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粺', '{"9000": "7105.0", "Chữ Trung Quốc": "粺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 14 | nét | 粺 | bãi | tượng hình | gạo/kê đã giã trắng | 粺 thuộc bộ 米 (gạo), chỉ loại gạo hay kê đã được giã, xay trắng tinh. Wiktionary không cung cấp phân tích hình-thanh rõ ràng. Chữ độc thể trong ngữ cảnh hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bãi\": hạt gạo (米) được giã trắng tinh — từ thô thành tinh, bãi là tinh hoa của hạt lúa. | Gương Hán-Việt | bãi — ít dùng trong tiếng Việt Hán hiện đại; văn cổ chỉ gạo/kê tinh chế. | Mở khoá kiến thức | Biết 粺 (bãi) giúp hiểu bộ 米 (mịch) và phân biệt các loại ngũ cốc trong văn ngữ cổ điển Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi {{Han etym}} mà không có phân tích cấu trúc. 粺 thuộc bộ 米 (gạo), chỉ gạo hoặc kê đã xay giã trắng, được dùng trong văn cổ để phân biệt lương thực tinh chế với lương thực thô. Có hình tiểu triện. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "粺", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粺", "Unihan_Traditional (Chữ Phồn thể)": "粺", "Pinyin_Xie": "bài", "Âm Hán Việt_Xie": "bãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong cổ văn để chỉ loại gạo đã được xay xát kỹ và trắng sạch. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缊', '{"9000": "7106.0", "Chữ Trung Quốc": "缊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 缊 | uẩn | tượng hình | tơ rối, bông gai vụn | 缊 thuộc bộ 糸 (tơ/sợi), chỉ tơ rối lẫn lộn hoặc bông gai vụn. Wiktionary ghi dạng phồn thể là 縕, nhưng không phân tích cấu trúc hình-thanh rõ ràng. Chữ gợi ý sự lẫn lộn, tạp nhạp của sợi vải.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uẩn\": sợi tơ (糸) rối bời — như lòng người ẩn uất, mọi thứ lẫn lộn, không phân minh. | Gương Hán-Việt | uẩn — thấy trong từ 蘊含 (uẩn hàm: chứa đựng bên trong); chữ 缊 gợi sự ẩn chứa, lẫn lộn. | Mở khoá kiến thức | Biết 缊 (uẩn) và bộ 糸 giúp nhận ra các chữ liên quan tơ lụa; âm uẩn kết nối với 蘊 (tích trữ bên trong).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 縕 (dạng phồn thể của 缊) với các nghĩa: sợi vải cũ rối, lẫn lộn, màu cam (cổ). Cũng gặp trong từ ghép 絪縕 chỉ khí âm dương hòa quyện. Không có phân tích glyph chi tiết. Chưa có nguồn học thuật rõ về cấu trúc. Chưa có nguồn học thuật chính thức. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bông tơ tạp, gai; đay vụn; tạp nhạp, lẫn lộn", "Hạng Tần Suất (Jun Da)": "7106.0", "Tần Suất % (Jun Da)": "99.9974512157", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 昷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟昷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缊", "Unihan_Traditional (Chữ Phồn thể)": "縕", "Pinyin_Xie": "yūn", "Âm Hán Việt_Xie": "uẩn, uân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ tơ đay vụn hoặc làm tính từ chỉ trạng thái hỗn độn, mập mờ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艈', '{"9000": "7107.0", "Chữ Trung Quốc": "艈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 13 | nét | 艈 | dục | tượng hình | thuyền; phần đuôi thuyền | 艈 thuộc bộ 舟 (thuyền), chỉ phần nghiêm túc/cứng nhắc của thuyền hoặc một loại thuyền nhỏ. Wiktionary không có phân tích cấu trúc. Chữ độc thể trong ngữ cảnh hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dục\": bộ thuyền (舟) với dáng vẻ nghiêm túc — con thuyền cứng cáp, không lung lay trên sóng. | Gương Hán-Việt | dục — hiếm trong tiếng Việt Hán hiện đại; liên quan đến thuyền bè trong văn ngữ cổ. | Mở khoá kiến thức | Biết 艈 (dục) và bộ 舟 giúp nhận ra các chữ liên quan đến thuyền bè: 船 (thuyền), 舰 (hạm thuyền), 艇 (đỉnh thuyền nhỏ).", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary cho 艈. Chữ thuộc bộ 舟 (thuyền), âm đọc yù, nghĩa là nghiêm khắc hoặc liên quan đến thuyền bè. Chưa có nguồn học thuật chính thức về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghiêm khắc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 㐬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟㐬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艈", "Unihan_Traditional (Chữ Phồn thể)": "艈", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "dục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ trong văn cổ để tả dáng vẻ của thuyền bè hoặc tính cách nghiêm nghị. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓇', '{"9000": "7108.0", "Chữ Trung Quốc": "蓇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 蓇 | cốt | tượng hình | nang quả thực vật | 蓇 thuộc bộ 艸 (cỏ/thực vật), chỉ loại nang quả (follicle) của thực vật. Wiktionary chỉ ghi {{Han etym}} không chi tiết. Chỉ gặp trong từ ghép 蓇葖 (nang quả đơn lá).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cốt\": cây cỏ (艸) với nang quả cứng như cốt — 蓇葖 là cái túi quả thực vật chứa hạt giống. | Gương Hán-Việt | cốt đột — từ ghép 蓇葖 (cốt đột) chỉ loại quả nang trong thực vật học. | Mở khoá kiến thức | Biết 蓇 (cốt) giúp nhận ra thuật ngữ thực vật học 蓇葖果 (quả nang đơn lá), thấy trong sách sinh học.", "Tự nguyên_Xie": "Wiktionary không phân tích cấu trúc glyph cho 蓇. Chữ thuộc bộ 艸 (thực vật), âm gǔ/gū, nghĩa chỉ dùng trong từ ghép 蓇葖 — một loại nang quả đơn lá mở theo một đường. Không có giáp cốt hay kim văn. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: cốt đột 蓇葖)", "Hạng Tần Suất (Jun Da)": "7108.0", "Tần Suất % (Jun Da)": "99.9974563836", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 骨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹骨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "骨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓇", "Unihan_Traditional (Chữ Phồn thể)": "蓇", "Pinyin_Xie": "gǔ", "Âm Hán Việt_Xie": "cốt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong thuật ngữ thực vật học để chỉ loại quả tự nứt khi chín. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛣', '{"9000": "7109.0", "Chữ Trung Quốc": "蛣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 蛣 | kiết | tượng hình | loại bọ cánh cứng | 蛣 thuộc bộ 虫 (sâu bọ), chỉ loài bọ phân (dung beetle) hoặc loài côn trùng. Wiktionary không có anchor. Chỉ dùng trong từ ghép như 蛣蜣 (kiết khương) và 蛣蟩 (kiết quyết).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiết\": bộ sâu bọ (虫) — con kiết là loài bọ nhỏ, di chuyển nhanh nhẹn trong đất. | Gương Hán-Việt | kiết — gặp trong từ ghép cổ: 蛣蜣 (kiết khương, bọ hung), 蛣蟩 (kiết quyết, một loài bọ). | Mở khoá kiến thức | Biết 蛣 (kiết) và bộ 虫 giúp nhận ra các chữ chỉ côn trùng trong văn cổ.", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary cho 蛣. Chữ thuộc bộ 虫 (côn trùng), âm qī, chỉ loài bọ cánh cứng. Chỉ xuất hiện trong từ ghép cổ điển. Chưa có nguồn học thuật chi tiết về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: kiết khương 蛣蜣); (xem: kiết quyết 蛣蟩)", "Hạng Tần Suất (Jun Da)": "7109.0", "Tần Suất % (Jun Da)": "99.9974589675", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 吉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫吉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛣", "Unihan_Traditional (Chữ Phồn thể)": "蛣", "Pinyin_Xie": "qī", "Âm Hán Việt_Xie": "cật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong các từ ghép cổ để chỉ tên loài côn trùng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹾', '{"9000": "7110.0", "Chữ Trung Quốc": "蹾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 19 | nét | 蹾 | đốn | tượng hình | dộng mạnh xuống đất; ngồi xổm | 蹾 thuộc bộ 足 (chân), chỉ hành động dộng mạnh chân xuống hoặc ngồi thụp xuống. Wiktionary không có anchor. Chữ độc thể trong ngữ cảnh hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đốn\": chân (足) dộng mạnh xuống đất — tiếng thình thịch khi bước mạnh. | Gương Hán-Việt | đốn — ít dùng độc lập; trong văn bản hiện đại chủ yếu thấy trong ngữ cảnh phương ngữ hoặc cổ điển. | Mở khoá kiến thức | Biết 蹾 (đốn) và bộ 足 giúp nhận ra hành động liên quan chân: 蹲 (đốn, ngồi xổm), 踩 (đạp), 踏 (giẫm).", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary cho 蹾. Chữ thuộc bộ 足 (chân), âm dūn, nghĩa là dộng mạnh xuống hoặc ngồi xổm. Có liên hệ âm với 蹲 (dūn, ngồi xổm). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dộng mạch xuống", "Hạng Tần Suất (Jun Da)": "7110.0", "Tần Suất % (Jun Da)": "99.9974615514", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 敦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊敦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹾", "Unihan_Traditional (Chữ Phồn thể)": "蹾", "Pinyin_Xie": "dūn", "Âm Hán Việt_Xie": "đôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị hành động đặt mạnh hoặc dộng một vật xuống đất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掎', '{"9000": "7111.0", "Chữ Trung Quốc": "掎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 掎 | ỷ | tượng hình | giữ lấy, dẫn dắt, lôi kéo | 掎 thuộc bộ 扌(手, tay), chỉ hành động giữ lấy hoặc lôi kéo bằng tay. Wiktionary chỉ ghi {{Han etym}} không có chi tiết. Chữ liên quan đến hành động nắm bắt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ỷ\": tay (扌) nắm chặt, kéo lại — như người giữ con hươu bằng một tay trong thành ngữ cổ. | Gương Hán-Việt | ỷ — gặp trong thành ngữ 掎角之勢 (ỷ giác chi thế): thế chân vạc, giữ nhau từ nhiều phía. | Mở khoá kiến thức | Biết 掎 (ỷ) giúp đọc thành ngữ quân sự 掎角之勢 — thế trận kẹp gọng kìm từ nhiều góc.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không phân tích cấu trúc chi tiết cho 掎. Chữ thuộc bộ 扌 (tay), âm jǐ, nghĩa là nắm giữ, dẫn dắt, lôi kéo. Có hình tiểu triện từ nguồn hanziyuan. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giữ lấy; dẫn dắt; lôi kéo", "Hạng Tần Suất (Jun Da)": "7111.0", "Tần Suất % (Jun Da)": "99.9974641353", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 奇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌奇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "掎", "Unihan_Traditional (Chữ Phồn thể)": "掎", "Pinyin_Xie": "jǐ", "Âm Hán Việt_Xie": "kỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường dùng trong văn ngôn để chỉ hành động kéo giữ hoặc khống chế. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哜', '{"9000": "7112.0", "Chữ Trung Quốc": "哜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 哜 | tế | tượng hình | nếm, húp nhỏ | 哜 thuộc bộ 口 (miệng), chỉ hành động nếm thức ăn hoặc húp nhỏ. Wiktionary ghi anchor là dạng phồn 嚌, không có phân tích cấu trúc. Liên quan đến hành động miệng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tế\": miệng (口) nếm thử từng chút — như người thử đồ ăn tế lễ, cẩn thận từng ngụm nhỏ. | Gương Hán-Việt | tế — ít dùng trong tiếng Việt Hán hiện đại; văn cổ chỉ hành động nếm lễ vật. | Mở khoá kiến thức | Biết 哜 (tế) và bộ 口 giúp nhận ra các chữ liên quan đến ăn uống và khẩu vị trong văn ngữ cổ.", "Tự nguyên_Xie": "Wiktionary ghi dạng phồn thể 嚌 với âm jì, không có phân tích glyph. Chữ thuộc bộ 口 (miệng), chỉ hành động nếm nhỏ hoặc húp thức ăn. Dùng chủ yếu trong văn bản cổ điển. Chưa có nguồn học thuật chi tiết về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nếm thức ăn; ăn, húp", "Hạng Tần Suất (Jun Da)": "7112.0", "Tần Suất % (Jun Da)": "99.9974667193", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 齐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口齐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "齐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哜", "Unihan_Traditional (Chữ Phồn thể)": "嚌", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "tễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động nếm hoặc ăn uống một cách nhẹ nhàng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄦', '{"9000": "7113.0", "Chữ Trung Quốc": "鄦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 14 | nét | 鄦 | hứa | tượng hình | nước Hứa, họ Hứa | 鄦 thuộc bộ 邑 (ấp, đất đai), chỉ tên đất hoặc họ Hứa. Wiktionary không phân tích cấu trúc chi tiết. Là dạng cổ của 許/许. Có hình tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hứa\": đất ấp (邑) mang tên họ Hứa — nước Hứa thời Chu, tổ của dòng họ Hứa tại Trung Nguyên. | Gương Hán-Việt | hứa — họ Hứa (許) phổ biến trong tiếng Việt; 鄦 là dạng cổ, gặp trong văn bản lịch sử. | Mở khoá kiến thức | Biết 鄦 (hứa) giúp truy nguyên họ 許 (Hứa) — một trong trăm họ phổ biến ở Trung Quốc và Việt Nam.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 鄦 với âm xǔ, là dạng cổ của 許 (hứa). Bộ 邑 cho biết liên quan đến đất đai, địa danh. Chỉ tên nước chư hầu thời Chu (Hứa quốc) và họ tên. Có hình tiểu triện từ Wikimedia. Chưa có nguồn học thuật chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Hứa", "Hạng Tần Suất (Jun Da)": "7113.0", "Tần Suất % (Jun Da)": "99.9974693032", "GavinGrover_Once (Chiết tự trực tiếp)": "無 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰無阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "無", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄦", "Unihan_Traditional (Chữ Phồn thể)": "鄦", "Pinyin_Xie": "xǔ", "Âm Hán Việt_Xie": "hứa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ riêng dùng làm tên một quốc gia chư hầu thời Chu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韰', '{"9000": "7114.0", "Chữ Trung Quốc": "韰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 韭 | Số nét | 16 | nét | 韰 | giải | tượng hình | liên quan đến hẹ, rau gia vị | 韰 thuộc bộ 韭 (hẹ, rau hẹ), chỉ một loại rau hoặc trạng thái. Wiktionary chỉ ghi âm và gặp trong 韰惈 (韰惈). Không phân tích glyph.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giải\": bộ hẹ (韭) — loại rau gia vị sắc sảo, như vị cay nồng của hẹ trong bữa ăn truyền thống. | Gương Hán-Việt | giải — hiếm trong tiếng Việt Hán; bộ 韭 gợi rau hẹ, gia vị truyền thống. | Mở khoá kiến thức | Biết 韰 (giải) và bộ 韭 giúp nhận biết chữ liên quan đến rau hẹ và gia vị trong văn ngữ cổ.", "Tự nguyên_Xie": "Wiktionary ghi 韰 với âm xiè, chỉ dùng trong từ ghép 韰惈. Bộ 韭 cho biết liên quan đến hẹ/rau gia vị. Chưa có nguồn học thuật về cấu trúc. Chưa có nguồn học thuật chính thức. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "韰", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "𣦼 + 韭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𣦼韭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𣦼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "韭", "Unihan_Simplified (Chữ Giản thể)": "韰", "Unihan_Traditional (Chữ Phồn thể)": "韰", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "giải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ mô tả tính chất nhỏ hẹp hoặc tâm tính nóng nảy. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飖', '{"9000": "7115.0", "Chữ Trung Quốc": "飖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 風 | Số nét | 14 | nét | 飖 | diêu | tượng hình | bay lơ lửng, cuốn theo gió | 飖 thuộc bộ 風 (gió), là dạng giản thể của 颻. Chỉ trạng thái bay bổng, cuốn theo gió. Wiktionary ghi {{Han simp|颻|f=風|t=风}}.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diêu\": bộ gió (風/风) — lá bay cuốn theo cơn gió, phiêu diêu không định hướng. | Gương Hán-Việt | diêu — gặp trong từ phiêu diêu (飄颻): bay bổng, không định hướng như mây gió. | Mở khoá kiến thức | Biết 飖 (diêu) giúp nhận từ ghép 飘飖 (phiêu diêu) và bộ 風/风 liên quan đến gió.", "Tự nguyên_Xie": "Theo Wiktionary, 飖 là dạng giản thể của 颻 (thay 風 bằng 风). Chỉ trạng thái bay bổng, cuốn theo gió. Gặp trong từ ghép 飄颻/飘飖 (phiêu diêu, bay lơ lửng). Không có phân tích glyph cổ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phiêu diêu 飄颻,飘飖)", "Hạng Tần Suất (Jun Da)": "7115.0", "Tần Suất % (Jun Da)": "99.997477055", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 风", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰风", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "飖", "Unihan_Traditional (Chữ Phồn thể)": "颻", "Pinyin_Xie": "yáo", "Âm Hán Việt_Xie": "diêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ hoặc tính từ trong văn thơ để tả cảnh bay lượn trước gió. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镲', '{"9000": "7116.0", "Chữ Trung Quốc": "镲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 19 | nét | 镲 | xoa | tượng hình | chũm chọe, nhạc cụ gõ | 镲 thuộc bộ 金 (kim loại), chỉ nhạc cụ gõ là chũm chọe (hai đĩa đồng va vào nhau). Wiktionary không có anchor. Chữ thuần mô tả nhạc khí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xoa\": kim loại (金) va chạm — tiếng chũm chọe chách chách vang lên trong đội nhạc lễ. | Gương Hán-Việt | xoa — ít dùng trong tiếng Việt Hán; nhạc khí chũm chọe thường gọi trực tiếp trong văn cảnh nhạc dân gian. | Mở khoá kiến thức | Biết 镲 (xoa) giúp nhận loại nhạc cụ gõ kim loại trong đội nhạc dân gian Trung Quốc, thấy trong tên các bài nhạc truyền thống.", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary cho 镲. Chữ thuộc bộ 金 (kim loại), âm chǎ, chỉ loại nhạc cụ gõ bằng kim loại — chũm chọe (cymbal). Đây là chữ tương đối hiện đại, mô tả âm thanh clang của hai đĩa đồng. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chũm choẹ", "Hạng Tần Suất (Jun Da)": "7116.0", "Tần Suất % (Jun Da)": "99.9974796389", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 察", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅察", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "察", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镲", "Unihan_Traditional (Chữ Phồn thể)": "鑔", "Pinyin_Xie": "chǎ", "Âm Hán Việt_Xie": "sát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại nhạc cụ gõ bằng đồng trong âm nhạc cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麃', '{"9000": "7117.0", "Chữ Trung Quốc": "麃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 15 | nét | 麃 | bào | tượng hình | cày ruộng; con nai | 麃 thuộc bộ 鹿 (hươu nai), có thể chỉ con nai hoặc hành động cày đất. Wiktionary ghi âm biāo, nghĩa cày đất. Có hình từ kim văn đến tiểu triện và lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bào\": bộ nai (鹿) kéo cày trên đồng ruộng — hươu mạnh mẽ dùng để ví sức lao động nông nghiệp. | Gương Hán-Việt | bào — ít dùng trong tiếng Việt Hán hiện đại; văn cổ chỉ hành động cày đất, làm cỏ ruộng. | Mở khoá kiến thức | Biết 麃 (bào) và bộ 鹿 giúp nhận ra các chữ liên quan đến hươu nai trong văn ngữ cổ Trung Quốc.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 麃 âm biāo (không phải páo), nghĩa là cày đất, dọn cỏ ruộng. Bộ 鹿 cho thấy liên quan đến hươu nai hoặc sức kéo trong nông nghiệp. Có hình kim văn và tiểu triện. Từ ghép 麃麃 mô tả ngoại hình mạnh mẽ. Chưa có nguồn học thuật chi tiết về cấu trúc. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con nai", "Hạng Tần Suất (Jun Da)": "7117.0", "Tần Suất % (Jun Da)": "99.9974822228", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 灬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱鹿灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "灬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麃", "Unihan_Traditional (Chữ Phồn thể)": "麃", "Pinyin_Xie": "páo", "Âm Hán Việt_Xie": "biều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ một loài hươu nhỏ hoặc làm động từ chỉ dáng chạy nhanh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筰', '{"9000": "7118.0", "Chữ Trung Quốc": "筰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 13 | nét | 筰 | tạc | tượng hình | dây làm bằng tre, dây thừng tre | 筰 thuộc bộ 竹 (tre), chỉ loại dây thừng đan bằng sợi tre. Wiktionary không phân tích cấu trúc glyph chi tiết. Chữ gắn với tre và dây thừng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tạc\": bộ tre (竹) đan thành dây — sợi tre được bện chặt thành dây thừng chắc bền. | Gương Hán-Việt | tạc — ít dùng trong tiếng Việt Hán; 筰 chỉ loại dây đặc trưng vùng sơn cước Trung Quốc. | Mở khoá kiến thức | Biết 筰 (tạc) và bộ 竹 giúp nhận ra các vật dụng làm từ tre: 筋 (gân/dây), 笼 (lồng), 篮 (rổ tre).", "Tự nguyên_Xie": "Wiktionary ghi 筰 âm zuó, nghĩa là dây làm từ sọc tre. Bộ 竹 xác nhận liên quan đến tre. Cũng có nghĩa thứ cấp trong phương ngữ Trương Châu là tát tai. Chưa có nguồn học thuật chi tiết về cấu trúc glyph. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây tre", "Hạng Tần Suất (Jun Da)": "7118.0", "Tần Suất % (Jun Da)": "99.9974873907", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 作", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮作", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "作", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筰", "Unihan_Traditional (Chữ Phồn thể)": "筰", "Pinyin_Xie": "zuó", "Âm Hán Việt_Xie": "tạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại dây thừng hoặc dây cáp bện bằng tre thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聠', '{"9000": "7119.0", "Chữ Trung Quốc": "聠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 12 | nét | 聠 | bính | tượng hình | không rõ nghĩa; liên quan đến tai | 聠 thuộc bộ 耳 (tai), chỉ một đặc điểm hoặc hành động liên quan đến tai. Wiktionary không có anchor. Nghĩa cụ thể không rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bính\": bộ tai (耳) — như tiếng ping vang lên trong tai, một âm thanh trong sáng, rõ ràng. | Gương Hán-Việt | bính — hiếm trong tiếng Việt Hán; gặp trong văn cổ không rõ nghĩa cụ thể. | Mở khoá kiến thức | Biết 聠 (bính) và bộ 耳 giúp nhận ra các chữ liên quan đến tai và thính giác: 聪 (thông minh), 聊 (chuyện gẫu), 听 (nghe).", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary cho 聠. Chữ thuộc bộ 耳 (tai), âm pīng. Nghĩa cụ thể không còn ghi nhận rõ trong từ điển hiện đại. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "聠", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 并", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳并", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "并", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聠", "Unihan_Traditional (Chữ Phồn thể)": "聠", "Pinyin_Xie": "pīng", "Âm Hán Việt_Xie": "bính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này dùng làm danh từ chỉ chứng ù tai hoặc động từ chỉ trạng thái tai bị ù. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茷', '{"9000": "7120.0", "Chữ Trung Quốc": "茷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 茷 | phạt | tượng hình | lá cỏ dày rậm; lay động | 茷 thuộc bộ 艸 (cỏ/thực vật), chỉ trạng thái lá cỏ dày rậm hoặc bay phần phật. Wiktionary không có phân tích chi tiết. Âm fá/fát.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phạt\": bộ cỏ (艸) lay động phật phật — cỏ cây rậm rạp vẫy trong gió như cờ chiến. | Gương Hán-Việt | phạt — ít dùng trong tiếng Việt Hán; liên hệ xa với 伐 (phạt: đánh cây, chinh phạt) nhưng hoàn toàn khác nghĩa. | Mở khoá kiến thức | Biết 茷 (phạt) và bộ 艸 giúp nhận ra các chữ miêu tả cỏ cây trong văn ngữ cổ điển.", "Tự nguyên_Xie": "Wiktionary không phân tích cấu trúc chi tiết cho 茷. Chữ thuộc bộ 艸 (thực vật), âm fá, nghĩa là mật độ lá cỏ hoặc lá bay phất phới. Dùng rất ít trong tiếng Hán hiện đại. Chưa có nguồn học thuật chính thức. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mật độ lá cỏ", "Hạng Tần Suất (Jun Da)": "7120.0", "Tần Suất % (Jun Da)": "99.9974925585", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 伐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹伐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "伐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茷", "Unihan_Traditional (Chữ Phồn thể)": "茷", "Pinyin_Xie": "fá", "Âm Hán Việt_Xie": "phệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ đứng trước danh từ hoặc làm vị ngữ để miêu tả cây cỏ tốt tươi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螀', '{"9000": "7121.0", "Chữ Trung Quốc": "螀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 螀 | tương | tượng hình | loài ve sầu | 螀 thuộc bộ 虫 (côn trùng), chỉ một loài ve sầu. Wiktionary ghi anchor là dạng phồn 螿, không phân tích cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tương\": bộ sâu bọ (虫) — ve sầu kêu râm ran như tiếng đàn vi tính mùa hạ. | Gương Hán-Việt | tương — ít dùng độc lập; liên hệ âm với 将 (tương, sắp/tướng) nhưng khác nghĩa hoàn toàn. | Mở khoá kiến thức | Biết 螀 (tương) và bộ 虫 giúp nhận ra các loài côn trùng kêu theo mùa trong văn thơ cổ điển.", "Tự nguyên_Xie": "Wiktionary ghi anchor 螿 không có phân tích glyph chi tiết. Bộ 虫 xác nhận liên quan đến côn trùng. Âm jiāng, chỉ loại ve sầu (cicada). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ve sầu", "Hạng Tần Suất (Jun Da)": "7121.0", "Tần Suất % (Jun Da)": "99.9974951425", "GavinGrover_Once (Chiết tự trực tiếp)": "将 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱将虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "将", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螀", "Unihan_Traditional (Chữ Phồn thể)": "螿", "Pinyin_Xie": "jiāng", "Âm Hán Việt_Xie": "tương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ đứng độc lập hoặc làm thành phần trong tên gọi các loài ve. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褧', '{"9000": "7122.0", "Chữ Trung Quốc": "褧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 16 | nét | 褧 | quýnh | tượng hình | áo đơn mỏng, áo khoác nhẹ | 褧 thuộc bộ 衣 (quần áo), chỉ loại áo khoác đơn, không có lót. Wiktionary không phân tích cấu trúc chi tiết. Chỉ loại áo nhẹ mặc bên ngoài.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quýnh\": bộ áo (衣) mỏng manh — chiếc áo khoác mỏng phất phơ trong gió, không có lót ấm. | Gương Hán-Việt | quýnh — ít dùng trong tiếng Việt Hán; gặp trong văn cổ mô tả trang phục phụ nữ. | Mở khoá kiến thức | Biết 褧 (quýnh) và bộ 衣 giúp nhận các loại trang phục truyền thống: 袍 (bào: áo dài), 衫 (sam: áo ngắn), 裙 (quần: váy).", "Tự nguyên_Xie": "Wiktionary ghi 褧 âm jiǒng, chỉ áo đơn không lót, áo khoác nhẹ mặc bên ngoài. Bộ 衣 xác nhận liên quan đến trang phục. Chưa có nguồn học thuật chi tiết về cấu trúc. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo đơn", "Hạng Tần Suất (Jun Da)": "7122.0", "Tần Suất % (Jun Da)": "99.9975003103", "GavinGrover_Once (Chiết tự trực tiếp)": "耿 + 衣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱耿衣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "褧", "Unihan_Traditional (Chữ Phồn thể)": "褧", "Pinyin_Xie": "jiǒng", "Âm Hán Việt_Xie": "quýnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ loại áo đơn mỏng mặc ngoài để che bụi cho trang phục gấm vóc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('賮', '{"9000": "7123.0", "Chữ Trung Quốc": "賮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 16 | nét | 賮 | tấn | tượng hình | đồ cống, quà tiễn biệt | 賮 thuộc bộ 貝 (tiền bạc, tài vật), chỉ đồ vật dùng để tặng hoặc cống nạp. Wiktionary không có anchor. Liên quan đến tài vật và lễ vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tấn\": bộ tài vật (貝) dâng lên — đồ cống tấn, vật phẩm dâng nộp theo nghi thức. | Gương Hán-Việt | tấn — ít dùng trong tiếng Việt Hán hiện đại; liên hệ với 進 (tấn: tiến, nộp). | Mở khoá kiến thức | Biết 賮 (tấn) và bộ 貝 giúp nhận các chữ liên quan tài vật và cống phẩm trong văn cổ điển.", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary cho 賮. Chữ thuộc bộ 貝 (tiền bạc/tài vật), âm jìn, nghĩa là đồ cống nạp hoặc quà tiễn biệt. Liên hệ với âm 进 (tiến, đi lên/nộp). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ cống", "Hạng Tần Suất (Jun Da)": "7123.0", "Tần Suất % (Jun Da)": "99.9975028942", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 貝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "賮", "Unihan_Traditional (Chữ Phồn thể)": "賮", "Pinyin_Xie": "jìn", "Âm Hán Việt_Xie": "tẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ tiền của đem tặng người đi xa hoặc đồ vật dâng cống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赗', '{"9000": "7124.0", "Chữ Trung Quốc": "赗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 13 | nét | 赗 | phúng | tượng hình | đồ tặng cho đám tang, phúng viếng | 赗 thuộc bộ 貝 (tài vật), chỉ đồ vật tặng cho người quá cố hoặc gia đình tang chủ trong đám tang. Wiktionary ghi anchor là dạng phồn 賵, không phân tích cấu trúc chi tiết. Có hình đại triện và tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phúng\": tài vật (貝) gửi tiễn người quá cố — đồ phúng điếu, gửi tình nghĩa theo người đã khuất. | Gương Hán-Việt | phúng — dùng trong từ Hán-Việt: phúng điếu (赗弔), đồ phúng viếng. Liên hệ với 奉 (phụng) về âm. | Mở khoá kiến thức | Biết 赗 (phúng) giúp nhận từ phúng điếu và hiểu phong tục tang lễ cổ đại Trung Hoa.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 賵 (dạng phồn của 赗) âm fèng, nghĩa là đồ tặng để giúp lo đám tang, thường là xe ngựa hay tơ lụa. Bộ 貝 xác nhận liên quan đến tài vật. Có hình đại triện và tiểu triện từ Wikimedia. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ tặng người chết", "Hạng Tần Suất (Jun Da)": "7124.0", "Tần Suất % (Jun Da)": "99.9975054782", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 冒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝冒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赗", "Unihan_Traditional (Chữ Phồn thể)": "賵", "Pinyin_Xie": "fèng", "Âm Hán Việt_Xie": "phúng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ xe ngựa hoặc tiền của đem giúp đỡ gia đình có tang sự. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踡', '{"9000": "7125.0", "Chữ Trung Quốc": "踡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 15 | nét | 踡 | quyển | tượng hình | co quắp, cuộn tròn | 踡 thuộc bộ 足 (chân), chỉ trạng thái chân co quắp lại hoặc thân người cuộn tròn. Wiktionary không phân tích cấu trúc chi tiết. Chỉ tư thế co rúm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyển\": chân (足) co lại như cuộn tròn — tư thế nằm co quắp như một cuộn sách (quyển). | Gương Hán-Việt | quyển — liên hệ âm với 卷 (quyển: cuộn, tập sách); 踡 là tư thế thân người cuộn lại. | Mở khoá kiến thức | Biết 踡 (quyển) giúp nhận từ 踡伏 (co rúm nằm xuống) và hiểu bộ 足 chỉ hành động chân/thân thể.", "Tự nguyên_Xie": "Wiktionary ghi 踡 âm quán, nghĩa là cuộn tròn, co lại. Bộ 足 xác nhận liên quan đến chân/tư thế thân người. Gặp trong từ ghép 踡伏 (nằm co), 踡跼 (co rúm). Chưa có nguồn học thuật chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "co quắp", "Hạng Tần Suất (Jun Da)": "7125.0", "Tần Suất % (Jun Da)": "99.9975080621", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 卷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊卷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踡", "Unihan_Traditional (Chữ Phồn thể)": "踡", "Pinyin_Xie": "quán", "Âm Hán Việt_Xie": "quyền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ hoặc tính từ miêu tả tư thế co người lại do lạnh hoặc đau đớn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('揞', '{"9000": "7126.0", "Chữ Trung Quốc": "揞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 扌 | thủ | biểu nghĩa | tay | 音 | âm | biểu âm | âm thanh | 揞 = 扌 (Thủ, biểu nghĩa: tay) + 音 (Âm, biểu âm, gợi âm ǎn); chữ hình thanh. Tay dùng để che phủ hoặc rắc lên; 音 gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ẵm\": tay (扌) ôm che — như ẵm con nhỏ vào lòng, che chắn bằng bàn tay ấm áp. | Gương Hán-Việt | ẵm — liên hệ ngữ âm thú vị với tiếng Việt \"ẵm\" (bế trẻ); 揞 là hành động che bằng tay. | Mở khoá kiến thức | Biết 揞 (ẵm) và bộ 扌 giúp nhận các động từ liên quan hành động tay: 捂 (che), 捧 (bưng), 掩 (che đậy).", "Tự nguyên_Xie": "Theo Wiktionary, 揞 là chữ hình thanh: 手/扌 (biểu nghĩa: tay) + 音 (biểu âm). Nghĩa là dùng tay che phủ hoặc rắc/rải (thuốc bột, muối...) lên vết thương. Chưa có nguồn học thuật chi tiết về glyph cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rắc, rải", "Hạng Tần Suất (Jun Da)": "7126.0", "Tần Suất % (Jun Da)": "99.997510646", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 音", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌音", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "音", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "揞", "Unihan_Traditional (Chữ Phồn thể)": "揞", "Pinyin_Xie": "ǎn", "Âm Hán Việt_Xie": "yêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ hành động áp tay lên hoặc đắp thuốc bột vào vết thương. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遝', '{"9000": "7127.0", "Chữ Trung Quốc": "遝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 13 | nét | 辶 | sước | biểu nghĩa | đi lại, chuyển động | 眔 | đạt | biểu âm | 遝 = 辶 (Sước, biểu nghĩa: đi lại) + 眔 (Đạt, biểu âm, gợi âm tà); chữ hình thanh. Bộ 辶 cho biết liên quan đến di chuyển; 眔 gợi âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tập\": bộ đi (辶) với mắt nhìn (眔) — đuổi theo kịp, hòa vào đám đông hỗn độn. | Gương Hán-Việt | tập — gặp trong từ 雜遝 (tạp tập: đông đúc hỗn loạn); liên hệ âm với 達 (đạt: đến nơi). | Mở khoá kiến thức | Biết 遝 (tập) giúp đọc thành ngữ 駢肩雜遝 (chen vai xô đẩy đông đúc) trong văn học cổ.", "Tự nguyên_Xie": "Theo Wiktionary, 遝 là chữ hình thanh: 辵/辶 (biểu nghĩa: đi lại) + 眔 (biểu âm). Nghĩa cổ là đuổi kịp, đạt đến; cũng dùng trong từ ghép 雜遝 (tạp tập: đông đúc, hỗn độn). Chưa có nguồn học thuật chi tiết về glyph cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lẫn lộn; kịp", "Hạng Tần Suất (Jun Da)": "7127.0", "Tần Suất % (Jun Da)": "99.9975132299", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 眔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶眔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "眔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遝", "Unihan_Traditional (Chữ Phồn thể)": "遝", "Pinyin_Xie": "tà", "Âm Hán Việt_Xie": "đạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả sự đông đúc, dồn dập hoặc động từ chỉ sự gặp gỡ, hội tụ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酂', '{"9000": "7128.0", "Chữ Trung Quốc": "酂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 18 | nét | 贊 | tán | biểu âm | 邑 | ấp | biểu nghĩa | vùng đất, ấp | 酂 = 贊 (Tán, biểu âm) + 邑 (Ấp, biểu nghĩa: vùng đất); chữ hình thanh. Bộ 邑 cho biết liên quan đến địa danh/đơn vị hành chính; 贊 gợi âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tán\": đất ấp (邑) của một trăm nhà — đơn vị làng xã nhỏ nhất thời Chu, gọi là tán. | Gương Hán-Việt | tán — ít dùng trong tiếng Việt Hán thường ngày; là đơn vị địa lý hành chính cổ đại Trung Hoa. | Mở khoá kiến thức | Biết 酂 (tán) giúp hiểu hệ thống hành chính thời Chu và bộ 邑 chỉ đơn vị lãnh thổ.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary (qua anchor 酇), 酂 là chữ hình thanh: 贊 (biểu âm) + 邑 (biểu nghĩa: đất đai). Hai âm: zàn/zuǎn chỉ đơn vị hành chính 100 nhà thời Chu; cuó/cuán chỉ địa danh (Tán Thành, Tán Dương). Có hình tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tán (tên đất cổ, ở huyện Quang Hoá, tỉnh Hồ Bắc, Trung Quốc.)", "Hạng Tần Suất (Jun Da)": "7128.0", "Tần Suất % (Jun Da)": "99.9975158139", "GavinGrover_Once (Chiết tự trực tiếp)": "赞 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰赞阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "赞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "酂", "Unihan_Traditional (Chữ Phồn thể)": "酇", "Pinyin_Xie": "cuó", "Âm Hán Việt_Xie": "tán, toản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng chỉ địa danh cổ ở Trung Quốc hoặc dùng làm họ người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酇', '{"9000": "7129.0", "Chữ Trung Quốc": "酇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 21 | nét | 贊 | tán | biểu âm | 邑 | ấp | biểu nghĩa | vùng đất, ấp | 酇 = 贊 (Tán, biểu âm) + 邑 (Ấp, biểu nghĩa: vùng đất); chữ hình thanh, dạng phồn thể của 酂. Bộ 邑 cho biết liên quan đến địa danh/đơn vị hành chính.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tán\": đất ấp (邑) đầy đủ — dạng phồn thể của 酂 với đầy đủ nét, uy nghi hơn như văn bản trang trọng. | Gương Hán-Việt | tán — ít dùng trong tiếng Việt Hán; dạng phồn thể của 酂 (tán), cùng nghĩa đơn vị hành chính cổ. | Mở khoá kiến thức | Biết 酇 (tán) giúp nhận dạng phồn-giản của cùng một chữ: 酇↔酂, và hiểu bộ 邑 trong địa danh.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 酇 là chữ hình thanh phồn thể: 贊 (biểu âm) + 邑 (biểu nghĩa: đất đai). Cùng nghĩa với 酂, chỉ đơn vị hành chính 100 nhà thời Chu và địa danh. Có hình tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "酂", "Hạng Tần Suất (Jun Da)": "7128.0", "Tần Suất % (Jun Da)": "99.9975158139", "GavinGrover_Once (Chiết tự trực tiếp)": "贊 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贊阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "酂", "Unihan_Traditional (Chữ Phồn thể)": "酇", "Pinyin_Xie": "zàn", "Âm Hán Việt_Xie": "tán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ đơn vị hành chính gồm một trăm hộ thời xưa hoặc động từ tụ tập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('檑', '{"9000": "7130.0", "Chữ Trung Quốc": "檑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 17 | nét | 檑 | lôi | tượng hình | khúc gỗ lớn dùng thủ thành | 檑 thuộc bộ 木 (gỗ/cây), chỉ khúc gỗ lớn được lăn xuống từ thành để chống giặc. Wiktionary không có anchor. Liên quan đến chiến thuật phòng thủ thành lũy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lôi\": bộ gỗ (木) ầm vang như sấm (雷) — khúc gỗ khổng lồ lăn xuống thành như tiếng sấm, nghiền nát quân địch. | Gương Hán-Việt | lôi — liên hệ âm với 雷 (lôi: sấm); 檑 là vũ khí gỗ thủ thành, ít dùng trong tiếng Việt Hán hiện đại. | Mở khoá kiến thức | Biết 檑 (lôi) và bộ 木 giúp nhận các vật dụng/vũ khí bằng gỗ trong văn chương quân sự cổ điển.", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary cho 檑. Chữ thuộc bộ 木 (gỗ), âm léi, chỉ khúc gỗ nặng thả lăn xuống từ tường thành để chống địch. Liên hệ âm với 雷 (lôi: sấm) — tiếng gỗ lăn ầm như sấm. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khúc gỗ lớn để thủ thành (cho lăn vào địch từ từ trên cao xuống)", "Hạng Tần Suất (Jun Da)": "7130.0", "Tần Suất % (Jun Da)": "99.9975235656", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 雷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木雷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "檑", "Unihan_Traditional (Chữ Phồn thể)": "檑", "Pinyin_Xie": "léi", "Âm Hán Việt_Xie": "lôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ vũ khí thủ thành thời cổ hoặc làm động từ với nghĩa lăn gỗ đá xuống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雮', '{"9000": "7131.0", "Chữ Trung Quốc": "雮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 12 | nét | 雮 | mộc | tượng hình | sương mù, khói mù | 雮 thuộc bộ 雨 (mưa), chỉ sương mù hoặc khói mù. Wiktionary không có anchor. Nghĩa cụ thể không còn ghi nhận rõ trong từ điển hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mộc\": bộ mưa (雨) che phủ — như sương mù buổi sáng sau cơn mưa, mờ mịt không thấy rõ. | Gương Hán-Việt | mộc — hiếm trong tiếng Việt Hán; gặp trong văn cổ mô tả hiện tượng thời tiết mờ mịt. | Mở khoá kiến thức | Biết 雮 (mộc) và bộ 雨 giúp nhận ra các chữ thời tiết: 雾 (vụ: sương mù), 霾 (mai: bụi mù), 霭 (ải: khói mỏng).", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary cho 雮. Chữ thuộc bộ 雨 (mưa/thời tiết), âm mù. Nghĩa không rõ, có thể liên quan đến sương mù hoặc hiện tượng thời tiết. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "雮", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 毛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨毛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "雮", "Unihan_Traditional (Chữ Phồn thể)": "雮", "Pinyin_Xie": "mù", "Âm Hán Việt_Xie": "mộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong thư tịch cổ hoặc dùng trong địa danh cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氍', '{"9000": "7132.0", "Chữ Trung Quốc": "氍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 毛 | Số nét | 22 | nét | 氍 | cừ | tượng hình | vải len mịn, thảm len thờ | 氍 thuộc bộ 毛 (lông/tơ), chỉ loại vải len mịn hoặc tấm thảm lễ nghi của hoàng đế. Wiktionary không phân tích cấu trúc chi tiết. Chỉ dùng trong từ ghép 氍毹.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cừ\": bộ lông (毛) mịn óng — tấm thảm 氍毹 trải dưới chân vua hoặc diễn viên, mềm mại như lông thú quý. | Gương Hán-Việt | cừ — ít dùng độc lập; gặp trong từ 氍毹 (cừ thư: thảm len mịn) trong văn ngữ cổ điển và từ điển chuyên ngành. | Mở khoá kiến thức | Biết 氍 (cừ) giúp nhận từ 氍毹 — loại thảm cổ đại, và bộ 毛 liên quan vật liệu lông/len.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 氍 âm qú, chỉ dùng trong từ ghép 氍毹 — loại thảm len mịn dùng trong cung đình hoặc sân khấu. Bộ 毛 xác nhận liên quan đến lông/sợi mịn. Có hình tiểu triện. Chưa có nguồn học thuật chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đệm bằng lông", "Hạng Tần Suất (Jun Da)": "7132.0", "Tần Suất % (Jun Da)": "99.9975287335", "GavinGrover_Once (Chiết tự trực tiếp)": "瞿 + 毛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰瞿毛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瞿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "毛", "Unihan_Simplified (Chữ Giản thể)": "氍", "Unihan_Traditional (Chữ Phồn thể)": "氍", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "cù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp thành từ ghép cừ du để chỉ tấm thảm lông trải nền nhà hoặc sân khấu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腙', '{"9000": "7133.0", "Chữ Trung Quốc": "腙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 腙 | tung | tượng hình | hợp chất hydrazone trong hóa học | 腙 thuộc bộ 肉/月 (thịt/cơ thể), nhưng đây là chữ hóa học hiện đại chỉ hợp chất hydrazone (C=N-NH-). Wiktionary không có anchor. Chữ khoa học kỹ thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tung\": bộ thịt/cơ thể (月) ứng với hợp chất hữu cơ — hydrazone (腙) là phân tử hữu cơ, tương tự bộ phận cơ thể sinh học. | Gương Hán-Việt | tung — thuật ngữ hóa học; 腙 là tên gọi Hán tự của hợp chất hydrazone. | Mở khoá kiến thức | Biết 腙 (tung) giúp nhận thuật ngữ hóa học Hán tự: 腙 (hydrazone), 肼 (hydrazine), 酮 (ketone).", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary cho 腙. Chữ thuộc bộ 肉 (月), âm zōng, là thuật ngữ hóa học hiện đại chỉ hợp chất hydrazone — sản phẩm phản ứng giữa aldehyde/ketone với hydrazine. Chữ tạo muộn trong thời kỳ hiện đại hóa thuật ngữ khoa học Trung Quốc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hợp chất Hy-đra-dôn", "Hạng Tần Suất (Jun Da)": "7133.0", "Tần Suất % (Jun Da)": "99.9975313174", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 宗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月宗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腙", "Unihan_Traditional (Chữ Phồn thể)": "腙", "Pinyin_Xie": "zōng", "Âm Hán Việt_Xie": "tông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chuyên ngành hóa học để chỉ một loại hợp chất hữu cơ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痖', '{"9000": "7134.0", "Chữ Trung Quốc": "痖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 11 | nét | 痖 | á | tượng hình | câm, khàn tiếng | 痖 thuộc bộ 疒 (bệnh tật), chỉ tình trạng câm hoặc khàn tiếng. Wiktionary ghi anchor là dạng phồn 瘂, là biến thể của 啞 (câm). Chữ bệnh lý liên quan đến giọng nói.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"á\": bộ bệnh (疒) mất tiếng — người câm (á) bị tật không nói được, tiếng tắt như ngọn đèn tắt lửa. | Gương Hán-Việt | á — gặp trong từ Hán-Việt: điếc câm (聾啞), câm á (啞); 痖 là biến thể của 啞 trong văn cổ. | Mở khoá kiến thức | Biết 痖 (á) giúp nhận bộ 疒 (bệnh) trong các chữ chỉ tật bệnh: 癔 (hysteria), 癫 (điên), 病 (bệnh).", "Tự nguyên_Xie": "Theo Wiktionary, 瘂 (dạng phồn của 痖) là dạng thay thế của 啞 — câm, khàn tiếng. Bộ 疒 xác nhận đây là bệnh tật liên quan đến giọng nói. Chưa có nguồn học thuật chi tiết về cấu trúc glyph. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "câm; khàn, khản", "Hạng Tần Suất (Jun Da)": "7134.0", "Tần Suất % (Jun Da)": "99.9975364853", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 亚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒亚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痖", "Unihan_Traditional (Chữ Phồn thể)": "瘂", "Pinyin_Xie": "yǎ", "Âm Hán Việt_Xie": "á", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm vị ngữ hoặc bổ ngữ để miêu tả trạng thái giọng nói bị khàn hoặc mất tiếng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髣', '{"9000": "7135.0", "Chữ Trung Quốc": "髣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 14 | nét | 髣 | phảng | tượng hình | thoáng giống, mơ hồ tương tự | 髣 thuộc bộ 髟 (tóc), chỉ trạng thái mơ hồ, phảng phất giống như. Wiktionary ghi 髣 là dạng thay thế của 彷 (phảng phất). Chỉ dùng trong từ ghép 髣髴.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phảng\": mái tóc (髟) lung linh — 髣髴 là hình ảnh thoáng qua, phảng phất như tóc xõa trong gió. | Gương Hán-Việt | phảng — gặp trong từ phảng phất (髣髴): mơ hồ tương tự, nhìn thoáng qua trông giống. | Mở khoá kiến thức | Biết 髣 (phảng) giúp đọc từ 髣髴 (phảng phất) và hiểu bộ 髟 trong các chữ liên quan tóc/lông.", "Tự nguyên_Xie": "Theo Wiktionary, 髣 là dạng thay thế của 彷, chỉ dùng trong từ ghép 髣髴 — phảng phất, mơ hồ trông giống. Bộ 髟 (tóc, lông) ở đây chỉ mang tính tượng hình. Chưa có nguồn học thuật chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phảng phất 髣髴)", "Hạng Tần Suất (Jun Da)": "7135.0", "Tần Suất % (Jun Da)": "99.9975390692", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 方", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "方", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "髣", "Unihan_Traditional (Chữ Phồn thể)": "髣", "Pinyin_Xie": "fǎng", "Âm Hán Việt_Xie": "phảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Thường kết hợp với phất để tạo thành phó từ liên kết biểu thị sự tương đồng hoặc mơ hồ. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髳', '{"9000": "7136.0", "Chữ Trung Quốc": "髳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 15 | nét | 髳 | mâu | tượng hình | kiểu tóc cổ; nước Mâu thời Chu | 髳 thuộc bộ 髟 (tóc), chỉ một kiểu tóc cổ đại hoặc tên nước Mâu thời Chu. Wiktionary không phân tích cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mâu\": mái tóc (髟) um tùm rậm — như rừng cây âm u (覭髳), tóc xõa dày như lá cây rậm. | Gương Hán-Việt | mâu — ít dùng trong tiếng Việt Hán; gặp trong văn cổ chỉ kiểu tóc hoặc tên nước cổ đại Trung Hoa. | Mở khoá kiến thức | Biết 髳 (mâu) và bộ 髟 giúp nhận các chữ liên quan tóc: 鬓 (bin: tóc mai), 髯 (nhiêm: râu), 髦 (mao: tóc dài).", "Tự nguyên_Xie": "Wiktionary ghi 髳 âm máo/méng, các nghĩa: kiểu tóc cổ đại, tên nước/dân tộc thời cổ, gặp trong từ ghép 覭髳 (um tùm). Bộ 髟 xác nhận liên quan đến tóc. Chưa có nguồn học thuật chi tiết về cấu trúc. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Mâu (một quốc gia thời nhà Chu, Trung Quốc)", "Hạng Tần Suất (Jun Da)": "7136.0", "Tần Suất % (Jun Da)": "99.9975416531", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 矛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟矛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "髳", "Unihan_Traditional (Chữ Phồn thể)": "髳", "Pinyin_Xie": "máo", "Âm Hán Việt_Xie": "mâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chủ yếu dùng trong văn ngôn để chỉ kiểu tóc rủ trước trán hoặc tên một bộ tộc thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酎', '{"9000": "7137.0", "Chữ Trung Quốc": "酎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 10 | nét | 酉 | dậu | biểu nghĩa | bình rượu, rượu | 肘 | trửu | biểu âm | khuỷu tay | 酎 = 酉 (Dậu, biểu nghĩa: rượu) + 肘 (viết tắt bỏ phần 月, Trửu, biểu âm, gợi âm zhòu); chữ hình thanh. Bộ 酉 xác nhận loại rượu; 肘 gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trửu\": rượu (酉) lên men dày như khuỷu tay (肘) cứng chắc — rượu 酎 là rượu nặng, ủ nhiều lần, chắc như gân cốt. | Gương Hán-Việt | trửu — ít dùng trong tiếng Việt Hán; gặp trong văn bản lịch sử thời Hán về thuế rượu 酎金. | Mở khoá kiến thức | Biết 酎 (trửu) và bộ 酉 giúp nhận các chữ liên quan đến rượu: 酒 (tửu), 醒 (tỉnh rượu), 醉 (say rượu), 醇 (rượu nguyên chất).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary (Đoạn Ngọc Tài chú), 酎 là chữ hình thanh: 酉 (biểu nghĩa: rượu) + 肘 rút gọn (biểu âm). Chỉ loại rượu mạnh đã lên men nhiều lần — rượu cố thủy thứ thiệt. Gặp trong từ ghép 酎金 (thuế rượu thời Hán). Có hình tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rượu ngon, rượu nặng", "Hạng Tần Suất (Jun Da)": "7137.0", "Tần Suất % (Jun Da)": "99.997544237", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 寸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉寸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酎", "Unihan_Traditional (Chữ Phồn thể)": "酎", "Pinyin_Xie": "zhòu", "Âm Hán Việt_Xie": "trữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp với các từ chỉ rượu để chỉ loại rượu mạnh chất lượng cao. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲒', '{"9000": "7138.0", "Chữ Trung Quốc": "鲒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 14 | nét | 鲒 | kết | tượng hình | con hàu, ốc biển | 鲒 là chữ chỉ loài nhuyễn thể biển (dạng cổ 鮚). Gồm bộ 魚 (ngư, biểu nghĩa: thuỷ sinh) và phần biểu âm; cấu trúc hình thanh. Wiktionary không có phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kết\": con hàu 鲒 khép chặt vỏ như một mối \"kết\" buộc dưới đáy biển — bộ 魚 cho thấy đây là sinh vật biển. | Gương Hán-Việt | kết trong \"kết hợp\" — âm kết của 鲒 gợi vỏ hàu khép chặt. | Mở khoá kiến thức | Biết 鲒 giúp nhận diện nhóm chữ thuỷ sản mang bộ 魚 trong văn cổ và địa danh (Kết Kỳ đình 鲒埼亭).", "Tự nguyên_Xie": "Tiểu triện | Chữ 鲒 (dạng cổ 鮚) chỉ loài hàu/ốc biển, thuộc nhóm chữ thuỷ sinh với bộ 魚. Wiktionary ghi nhận âm đọc nhưng không có giải thích ngữ nguyên (rfdef). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ốc mượn hồn", "Hạng Tần Suất (Jun Da)": "7138.0", "Tần Suất % (Jun Da)": "99.997546821", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 吉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼吉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲒", "Unihan_Traditional (Chữ Phồn thể)": "鮚", "Pinyin_Xie": "jié", "Âm Hán Việt_Xie": "cát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ các loài động vật thân mềm có vỏ hoặc dùng trong địa danh cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲪', '{"9000": "7139.0", "Chữ Trung Quốc": "鲪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 鲪 | quân | tượng hình | cá scorpion sống ở rạn đá biển | 鲪 (dạng cổ 鮶) gồm bộ 魚 (ngư, biểu nghĩa: cá) và phần biểu âm. Cấu trúc hình thanh; Wiktionary không phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quân\": cá 鲪 như \"quân\" sĩ ẩn trong khe đá, mình xám tro, đứng yên phục kích — bộ 魚 xác nhận đây là loài cá. | Gương Hán-Việt | quân trong \"quân sự\" — âm quân của 鲪 gợi đội cá ẩn trong rạn đá như quân phục kích. | Mở khoá kiến thức | Biết 鲪 mở rộng vốn từ về thuỷ sinh vật biển sâu trong văn khoa học và ngư nghiệp cổ.", "Tự nguyên_Xie": "Chữ 鲪 chỉ loài cá Sebastolobus (thornyhead) sống ở rạn đá gần biển. Wiktionary ghi nhận phát âm và định nghĩa nhưng không có giải thích ngữ nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá thờn bơn (cá thân dài và dẹt, màu xám tro, có những vằn đen tùy tiện, miệng to và méo, sống ở giữa những đá ngầm gần biển, đẻ thai trứng)", "Hạng Tần Suất (Jun Da)": "7139.0", "Tần Suất % (Jun Da)": "99.9975494049", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 君", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼君", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "君", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲪", "Unihan_Traditional (Chữ Phồn thể)": "鮶", "Pinyin_Xie": "jūn", "Âm Hán Việt_Xie": "quân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong ngành ngư nghiệp để chỉ một họ cá biển sống ở rạn đá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹯', '{"9000": "7140.0", "Chữ Trung Quốc": "鹯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 18 | nét | 鹯 | chiên | tượng hình | loài chim dữ tương tự diều hâu | 鹯 (dạng cổ 鸇) gồm bộ 鳥 (điểu, biểu nghĩa: chim) và phần biểu âm. Cấu trúc hình thanh; Wiktionary không phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiên\": chim 鹯 sải cánh như chảo \"chiên\" rộng trên bầu trời, mắt sắc nhìn xuống mồi — bộ 鳥 xác nhận là loài chim. | Gương Hán-Việt | chiên trong tên chim cổ — âm chiên của 鹯 gắn với hình ảnh chim dữ trong thơ văn cổ điển. | Mở khoá kiến thức | Biết 鹯 giúp đọc hiểu thơ văn cổ và thành ngữ miêu tả người hung ác (鸇視狼顧).", "Tự nguyên_Xie": "Tiểu triện | Chữ 鹯 chỉ loài chim săn mồi giống diều hâu, được nhắc trong thành ngữ 鸇視狼顧 (mắt diều nhìn, đầu sói ngoái). Wiktionary ghi nhận âm và nghĩa nhưng không có ngữ nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một giống chim dữ)", "Hạng Tần Suất (Jun Da)": "7140.0", "Tần Suất % (Jun Da)": "99.9975519888", "GavinGrover_Once (Chiết tự trực tiếp)": "亶 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亶鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹯", "Unihan_Traditional (Chữ Phồn thể)": "鸇", "Pinyin_Xie": "zhān", "Âm Hán Việt_Xie": "chiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim dữ thuộc họ ưng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麜', '{"9000": "7141.0", "Chữ Trung Quốc": "麜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 21 | nét | 麜 | lệ | tượng hình | hươu xạ Siberia giống cái | 麜 gồm bộ 鹿 (lộc, biểu nghĩa: hươu nai) và phần biểu âm. Cấu trúc hình thanh; Wiktionary không phân tích ngữ nguyên chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lệ\": con hươu xạ cái 麜 mang vẻ \"lệ\" (đẹp, thanh mảnh) trong rừng taiga — bộ 鹿 xác nhận là loài hươu nai. | Gương Hán-Việt | lệ trong \"mỹ lệ\" — âm lệ gợi vẻ duyên dáng của hươu cái so với hươu đực mạnh mẽ. | Mở khoá kiến thức | Biết 麜 mở ra nhóm chữ phân biệt giới tính trong động vật học cổ Trung Quốc.", "Tự nguyên_Xie": "Chữ 麜 chỉ con hươu xạ Siberia (Moschus moschiferus) giống cái. Wiktionary ghi nhận âm lì và nghĩa female Siberian musk deer nhưng không có phân tích ngữ nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Lin", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 栗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿栗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "栗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麜", "Unihan_Traditional (Chữ Phồn thể)": "麜", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài thú cổ thuộc họ hươu nai. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齸', '{"9000": "7142.0", "Chữ Trung Quốc": "齸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 25 | nét | 齸 | ức | tượng hình | chữ thuộc bộ 齒, nghĩa chưa xác định | 齸 thuộc bộ 齒 (xỉ, răng). Cấu trúc nội bộ chưa được ghi nhận; không rõ hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ức\": chữ 齸 mang bộ 齒 (răng) — hình ảnh hàm răng \"ức\" nén chặt, âm ức gợi sức ép của hàm. | Gương Hán-Việt | ức trong \"ức chế\" — âm ức liên tưởng đến sức nén của hàm răng khép lại. | Mở khoá kiến thức | Biết 齸 giúp nhận diện nhóm chữ hiếm thuộc bộ 齒 trong từ điển văn ngôn cổ.", "Tự nguyên_Xie": "Chữ 齸 thuộc bộ 齒 (xỉ), âm đọc yì. Wiktionary không có định nghĩa cụ thể (rfdef). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鸸", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "齒 + 益", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齒益", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "益", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齒", "Unihan_Simplified (Chữ Giản thể)": "齸", "Unihan_Traditional (Chữ Phồn thể)": "齸", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ bộ phận hầu họng hoặc động từ chỉ hành động nuốt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齻', '{"9000": "7143.0", "Chữ Trung Quốc": "齻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 25 | nét | 齒 | xỉ | biểu nghĩa | răng | 真 | chân | biểu âm | 齻 = 齒 (Xỉ, biểu nghĩa: răng) + 真 (Chân, biểu âm); chữ hình thanh. Phần 齒 chỉ nghĩa liên quan đến răng; phần 真 cho âm đọc gần diān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điên\": chữ 齻 = răng (齒) + chân thật (真) — chiếc răng \"điên\" lệch mọc sai vị trí nhưng vẫn là răng thật chính hiệu. | Gương Hán-Việt | điên trong \"điên đảo\" — âm điên của 齻 gợi chiếc răng mọc lệch. | Mở khoá kiến thức | Biết 齻 giúp nhận cấu trúc hình thanh với bộ 齒 trong y thư cổ về bệnh lý răng miệng.", "Tự nguyên_Xie": "Theo Wiktionary, 齻 là chữ hình thanh: 齒 (xỉ) biểu nghĩa \"răng\", 真 (chân) biểu âm. Chữ chưa có định nghĩa riêng trong Wiktionary (ghi 黻 như tham chiếu), nghĩa liên quan đến bộ phận răng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "黻", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "齒 + 真", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齒真", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "真", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齒", "Unihan_Simplified (Chữ Giản thể)": "齻", "Unihan_Traditional (Chữ Phồn thể)": "齻", "Pinyin_Xie": "diān", "Âm Hán Việt_Xie": "điên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ chiếc răng hàm mọc muộn nhất ở trong cùng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粩', '{"9000": "7144.0", "Chữ Trung Quốc": "粩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 12 | nét | 粩 | lão | tượng hình | loại bánh ngọt truyền thống Mân Nam/Đài Loan | 粩 gồm bộ 米 (mễ, biểu nghĩa: gạo, ngũ cốc) và phần biểu âm bên phải. Cấu trúc hình thanh; Wiktionary không có dữ liệu ngữ nguyên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lão\": bánh 粩 mang bộ 米 (gạo) — loại bánh \"lão\" làng của người Mân Nam, lâu đời giòn thơm như người già bền chắc. | Gương Hán-Việt | lão trong \"lão thực\" — âm lão của 粩 gợi vị bánh dân dã lâu đời của người Mân Nam. | Mở khoá kiến thức | Biết 粩 mở ra nhóm chữ chỉ thực phẩm chế biến từ gạo trong ẩm thực Mân Nam và Đài Loan.", "Tự nguyên_Xie": "Chữ 粩 không có dữ liệu Wiktionary. Bộ 米 (mễ) cho thấy liên quan đến gạo — phù hợp với nghĩa là loại bánh làm từ gạo chiên phủ mạch nha và mè, đặc sản Mân Nam và Đài Loan. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Đài Loan [lao3]; một loại bánh ngọt truyền thống của Đài Loan và Phúc Kiến được chiên, sau đó phủ maltose và cuộn trong hạt mè hoặc đậu phộng băm nhỏ, v.v.", "Hạng Tần Suất (Jun Da)": "7144.0", "Tần Suất % (Jun Da)": "99.9975623245", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 老", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米老", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "老", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粩", "Unihan_Traditional (Chữ Phồn thể)": "粩", "Pinyin_Xie": "lao", "Âm Hán Việt_Xie": "lao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại bánh ngọt chiên phủ mè của vùng Phúc Kiến và Đài Loan. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簰', '{"9000": "7145.0", "Chữ Trung Quốc": "簰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 18 | nét | 簰 | bài | tượng hình | bè tre dùng vận chuyển trên sông | 簰 gồm bộ 竹 (trúc, biểu nghĩa: tre) và phần biểu âm bên dưới. Cấu trúc hình thanh; Wiktionary không có dữ liệu ngữ nguyên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bài\": chữ 簰 mang bộ 竹 (tre) — từng cây tre \"bài\" xếp ngang thành bè, thả trôi sông như bài vị sắp hàng. | Gương Hán-Việt | bài trong \"bài trí\" — âm bài gợi hình ảnh tre được sắp bày thành bè. | Mở khoá kiến thức | Biết 簰 mở ra nhóm chữ chỉ phương tiện vận chuyển trên sông bằng tre trong văn cổ Trung Quốc.", "Tự nguyên_Xie": "Chữ 簰 không có dữ liệu Wiktionary. Bộ 竹 (trúc) cho thấy liên quan đến tre — phù hợp với nghĩa bè tre (mảng tre ghép dùng vận chuyển trên sông). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bè bằng tre", "Hạng Tần Suất (Jun Da)": "7145.0", "Tần Suất % (Jun Da)": "99.9975700763", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 牌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮牌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "牌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簰", "Unihan_Traditional (Chữ Phồn thể)": "簰", "Pinyin_Xie": "pái", "Âm Hán Việt_Xie": "bài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phương tiện giao thông đường thủy kết bằng tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒾', '{"9000": "7146.0", "Chữ Trung Quốc": "蒾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 蒾 | mê | tượng hình | cây thực vật thuộc bộ 艸, nghĩa chưa xác định rõ | 蒾 gồm bộ 艸 (thảo, biểu nghĩa: cỏ cây) và phần biểu âm. Cấu trúc hình thanh; Wiktionary không có dữ liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mê\": cây 蒾 mang bộ 艸 (cỏ) — loại cây bụi \"mê\" hoặc, lan tràn khó nhận dạng như mê lộ xanh. | Gương Hán-Việt | mê trong \"mê muội\" — âm mê gợi loại cây rậm rạp khó phân biệt. | Mở khoá kiến thức | Biết 蒾 giúp nhận diện nhóm chữ thực vật hiếm thuộc bộ 艸 trong thực vật học cổ.", "Tự nguyên_Xie": "Chữ 蒾 không có dữ liệu Wiktionary. Bộ 艸 (thảo) cho thấy là loại cây cỏ. Nghĩa cụ thể không rõ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "达", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 迷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹迷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "迷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒾", "Unihan_Traditional (Chữ Phồn thể)": "蒾", "Pinyin_Xie": "mí", "Âm Hán Việt_Xie": "mê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong tên gọi của một số loài thực vật thân thảo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓏', '{"9000": "7147.0", "Chữ Trung Quốc": "蓏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蓏 | lỏa | tượng hình | quả của cây cỏ, dưa lê | 蓏 gồm bộ 艸 (thảo, biểu nghĩa: cỏ cây) và phần biểu âm. Cấu trúc hình thanh; Wiktionary không có dữ liệu ngữ nguyên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lỏa\": chữ 蓏 mang bộ 艸 (cỏ) — quả \"lỏa\" trần của cây cỏ nằm sát đất như dưa lê lăn lộn trên ruộng. | Gương Hán-Việt | lỏa trong \"lỏa thể\" — âm lỏa của 蓏 gợi quả cây cỏ phơi trần trên mặt đất. | Mở khoá kiến thức | Biết 蓏 giúp hiểu phân loại quả trong nông học cổ Trung Quốc: 蓏 (quả cây cỏ) đối lập với 果 (quả cây gỗ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 蓏 không có dữ liệu Wiktionary. Bộ 艸 (thảo) phù hợp với nghĩa là quả cây cỏ thân mềm (phân biệt với 果 là quả cây thân gỗ). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quả của cây cỏ", "Hạng Tần Suất (Jun Da)": "7147.0", "Tần Suất % (Jun Da)": "99.9975752441", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 㼌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹㼌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㼌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓏", "Unihan_Traditional (Chữ Phồn thể)": "蓏", "Pinyin_Xie": "luǒ", "Âm Hán Việt_Xie": "loả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại quả mọc từ cây thân cỏ như dưa, cà. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薳', '{"9000": "7148.0", "Chữ Trung Quốc": "薳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 薳 | vĩ | tượng hình | tên cỏ, họ Vĩ | 薳 gồm bộ 艸 (thảo, biểu nghĩa: cỏ cây) và phần biểu âm. Cấu trúc hình thanh; Wiktionary không phân tích ngữ nguyên chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vĩ\": chữ 薳 mang bộ 艸 (cỏ) — họ \"Vĩ\" mang hình ảnh người gắn bó với thảo mộc, cây thuốc trong rừng. | Gương Hán-Việt | vĩ trong \"vĩ đại\" — âm vĩ của 薳 dùng làm họ người trong sử Trung Quốc cổ. | Mở khoá kiến thức | Biết 薳 giúp đọc tên nhân vật và địa danh trong sử sách thời Xuân Thu Chiến Quốc.", "Tự nguyên_Xie": "Tiểu triện | Chữ 薳 có hai âm đọc: wěi (họ người) và yuǎn (dùng trong 薳志, dạng khác của 遠志 — tên cây thuốc). Wiktionary ghi nhận là họ tên (surname) và dùng trong các tên ghép thực vật. Chưa có phân tích ngữ nguyên riêng. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ; họ Vĩ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 遠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹遠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "遠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "䓕", "Unihan_Traditional (Chữ Phồn thể)": "薳", "Pinyin_Xie": "wěi", "Âm Hán Việt_Xie": "vĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cỏ hoặc dùng làm họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藛', '{"9000": "7149.0", "Chữ Trung Quốc": "藛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 藛 | tả | tượng hình | cỏ thuộc bộ 艸, dùng trong tên ghép 澤藛 | 藛 gồm bộ 艸 (thảo, biểu nghĩa: cỏ cây) và phần biểu âm. Cấu trúc hình thanh; Wiktionary ghi nhận chữ này chỉ dùng trong tổ hợp 澤藛.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tả\": cỏ 藛 mang bộ 艸 (cỏ) — loại cỏ đầm lầy \"tả\" ra nước quanh vùng 澤, như chữ tả nghĩa là chảy ra bên trái. | Gương Hán-Việt | tả trong \"tả hữu\" — âm tả của 藛 gợi hình ảnh cỏ đầm lầy lan ra hai bên. | Mở khoá kiến thức | Biết 藛 giúp đọc tên thực vật đầm lầy cổ trong bản thảo và địa lý học Trung Quốc.", "Tự nguyên_Xie": "Chữ 藛 âm đọc xiě, chỉ dùng trong tổ hợp 澤藛 (tên một loại cỏ đầm lầy). Wiktionary ghi nhận âm và hạn chế dùng ({{zh-only|澤藛}}) nhưng không có phân tích ngữ nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "藛", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 寫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹寫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藛", "Unihan_Traditional (Chữ Phồn thể)": "藛", "Pinyin_Xie": "xiě", "Âm Hán Việt_Xie": "tả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài thực vật thân thảo mọc hoang. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚢', '{"9000": "7150.0", "Chữ Trung Quốc": "蚢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 蚢 | hàng | tượng hình | tằm dại ăn lá ngải; vỏ ốc lớn | 蚢 gồm bộ 虫 (trùng, biểu nghĩa: sâu bọ/côn trùng) và phần biểu âm. Cấu trúc hình thanh; Wiktionary không phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàng\": con 蚢 mang bộ 虫 (sâu bọ) — con tằm \"hàng\" xóm hoang dã ăn lá ngải, khác tằm nhà hiền lành ăn lá dâu. | Gương Hán-Việt | hàng trong \"hàng hải\" — âm hàng của 蚢 gợi con vật sống hoang dại ven biển. | Mở khoá kiến thức | Biết 蚢 mở ra nhóm chữ chỉ sâu bọ và động vật biển cổ thuộc bộ 虫 trong bản thảo học.", "Tự nguyên_Xie": "Chữ 蚢 có hai nghĩa cổ: (1) con tằm dại ăn lá ngải, (2) vỏ ốc biển lớn. Wiktionary ghi nhận âm háng và cả hai nghĩa (obs-std). Không có phân tích ngữ nguyên chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "châu chấu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 亢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫亢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚢", "Unihan_Traditional (Chữ Phồn thể)": "蚢", "Pinyin_Xie": "háng", "Âm Hán Việt_Xie": "hàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại côn trùng giống như châu chấu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓠', '{"9000": "7151.0", "Chữ Trung Quốc": "蓠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蓠 | ly | tượng hình | tên cây cỏ thơm cổ (Angelica dahurica), bờ rào | 蓠 (dạng cổ 蘺) gồm bộ 艸 (thảo, biểu nghĩa: cỏ cây) và phần biểu âm. Cấu trúc hình thanh; Wiktionary không phân tích cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ly\": cây 蓠 mang bộ 艸 (cỏ) — loại cây thơm \"ly\" kỳ trong thơ Khuất Nguyên, mọc bờ sông như bờ \"ly\" (hàng rào). | Gương Hán-Việt | ly trong \"ly biệt\" — cây 蓠 mọc ở bờ sông, gợi cảnh chia ly trong thơ Sở từ. | Mở khoá kiến thức | Biết 蓠 giúp đọc thơ Khuất Nguyên (Sở từ) và nhận diện tên thực vật cổ điển trong văn học Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Chữ 蓠 (dạng cổ 蘺) được Thuyết Văn ghi: 楚謂之蘺 (người Sở gọi là 蘺). Chỉ cây Angelica dahurica (bạch chỉ) hoặc dùng trong 江蘺 (tên loài tảo biển). Wiktionary ghi nhận nghĩa cổ và dẫn văn Thuyết Văn. Chưa có phân tích ngữ nguyên hình học. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: giang ly 江蘺,江蓠); bờ rào (như: ly 籬,篱)", "Hạng Tần Suất (Jun Da)": "7151.0", "Tần Suất % (Jun Da)": "99.9975855799", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 离", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹离", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "离", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓠", "Unihan_Traditional (Chữ Phồn thể)": "蘺", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong tên gọi các loại thực vật hoặc chỉ bờ rào. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓰', '{"9000": "7152.0", "Chữ Trung Quốc": "蓰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 蓰 | tỉ | tượng hình | gấp năm lần, năm lần | 蓰 gồm bộ 艸 (thảo, biểu nghĩa: cỏ cây) và phần biểu âm. Cấu trúc hình thanh; Wiktionary ghi nhận nghĩa five-fold.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỉ\": chữ 蓰 mang bộ 艸 — như cây cỏ 倍蓰 sinh sôi \"tỉ\" lệ năm lần, cứ năm năm lại nhân lên gấp bội. | Gương Hán-Việt | tỉ trong \"tỉ lệ\" — âm tỉ của 蓰 gợi tỉ lệ nhân năm lần trong thương mại cổ. | Mở khoá kiến thức | Biết 蓰 giúp đọc văn kinh tế cổ: 倍蓰 (gấp bội, từ hai đến năm lần lợi nhuận).", "Tự nguyên_Xie": "Chữ 蓰 nghĩa là gấp năm lần (five-fold), thường dùng trong tổ hợp 倍蓰 (gấp bội đến năm lần). Wiktionary ghi nhận âm xǐ và nghĩa. Không có phân tích ngữ nguyên chi tiết về bộ 艸. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "năm lần; gấp năm", "Hạng Tần Suất (Jun Da)": "7152.0", "Tần Suất % (Jun Da)": "99.9975881638", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 徙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹徙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "徙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓰", "Unihan_Traditional (Chữ Phồn thể)": "蓰", "Pinyin_Xie": "xǐ", "Âm Hán Việt_Xie": "tỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Số từ | 数词 | Tính từ | 形容词 | Dùng làm số từ hoặc tính từ để biểu thị số lượng gấp năm lần. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遡', '{"9000": "7153.0", "Chữ Trung Quốc": "遡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 13 | nét | 氵 | biểu nghĩa | nước | 㡿 | biểu âm | 遡 là chữ hình thanh hai lớp: dạng gốc 㴑 = 氵(nước, biểu nghĩa) + 㡿 (biểu âm). Dạng thông dụng hiện đại dùng 辶 (sước, biểu nghĩa: di chuyển) + 朔 (biểu âm). Cả hai đều là hình thanh, nghĩa cốt lõi là ngược dòng/truy nguyên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tố\": chữ 遡 mang 辶 (di chuyển) + 朔 (sóc — mồng một) — ngược dòng về mùng một, \"tố\" hành trình truy nguyên về điểm khởi đầu. | Gương Hán-Việt | tố trong \"tố tụng\" — âm tố của 遡 gợi hành động truy ngược về gốc rễ sự việc. | Mở khoá kiến thức | Biết 遡 giúp đọc văn ngôn cổ; chữ thông dụng hiện đại là 溯 (tố) trong 追溯 (truy tố, truy nguyên).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, chữ gốc là 㴑: 氵(nước) + 㡿 (biểu âm), nghĩa là đi ngược dòng nước. Dạng 遡 dùng 辶 (di chuyển) + 朔 (biểu âm, sóc). Chữ thông dụng hiện đại là 溯 (tra 溯). Nguồn: Digital Shinjigen 2017. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bỏ trốn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 朔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶朔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遡", "Unihan_Traditional (Chữ Phồn thể)": "遡", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "tố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ đứng trước tân ngữ để chỉ hành động đi ngược dòng nước hoặc truy tìm nguồn gốc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郋', '{"9000": "7154.0", "Chữ Trung Quốc": "郋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 8 | nét | 郋 | hề | tượng hình | tên đất cổ thuộc nước Hề, bộ 邑 | 郋 gồm bộ 邑 (ấp, biểu nghĩa: thành ấp, địa danh) và phần biểu âm. Cấu trúc hình thanh; Wiktionary không có dữ liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hề\": chữ 郋 mang bộ 邑 (thành ấp) — tên \"hề\" một vùng đất cổ, như hề trong tuồng cổ đứng một chỗ hát tên quê. | Gương Hán-Việt | hề trong \"hề chèo\" — âm hề của 郋 gợi tên đất cổ nghe lạ tai như nhân vật hề trong kịch. | Mở khoá kiến thức | Biết 郋 giúp nhận diện nhóm địa danh cổ mang bộ 邑 trong địa lý học và sử học Trung Quốc.", "Tự nguyên_Xie": "Chữ 郋 không có dữ liệu Wiktionary. Bộ 邑 (ấp) cho biết đây là địa danh — tên đất cổ nước Hề ở Trung Quốc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Hề (tên đất cổ thuộc Trung Quốc)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "自 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰自阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "自", "Unihan_Simplified (Chữ Giản thể)": "郋", "Unihan_Traditional (Chữ Phồn thể)": "郋", "Pinyin_Xie": "xí", "Âm Hán Việt_Xie": "hà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng để chỉ địa danh cổ ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄜', '{"9000": "7155.0", "Chữ Trung Quốc": "鄜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 13 | nét | 麃 | biểu âm | 邑 | ấp | biểu nghĩa | thành ấp | 鄜 = 麃 (biểu âm) + 邑 (Ấp, biểu nghĩa: thành ấp); chữ hình thanh. Wiktionary ghi 鄜 là dạng giản hoá của 𨞻, trong đó 麃 được thay bằng 鹿.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phù\": chữ 鄜 = ấp (邑) + biểu âm 麃 — thành \"phù\" ở Thiểm Tây, nơi Đỗ Phủ nhớ nhà khi bị giam giữ, viết bài Nguyệt Dạ. | Gương Hán-Việt | phù trong \"phù trợ\" — âm phù của 鄜 gắn với địa danh Lư châu/Phú huyện Thiểm Tây trong thơ Đỗ Phủ. | Mở khoá kiến thức | Biết 鄜 giúp đọc thơ Đỗ Phủ (Nguyệt Dạ — nhớ gia quyến ở 鄜州) và địa danh học Thiểm Tây.", "Tự nguyên_Xie": "Theo Wiktionary, 鄜 là chữ hình thanh: 邑 (ấp) biểu nghĩa thành ấp, 麃 biểu âm. Đây là tên huyện ở tỉnh Thiểm Tây (Lư huyện 鄜县, nay là Phú huyện 富县). Xuất hiện trong thơ Đỗ Phủ (Nguyệt Dạ nhớ gia quyến ở Lư châu). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "7155.0", "Tần Suất % (Jun Da)": "99.9975959156", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鹿阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "鄜", "Unihan_Traditional (Chữ Phồn thể)": "鄜", "Pinyin_Xie": "fū", "Âm Hán Việt_Xie": "phu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng để chỉ địa danh cổ hoặc tên huyện ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('錞', '{"9000": "7156.0", "Chữ Trung Quốc": "錞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 錞 | thuần | tượng hình | nhạc khí đồng thanh hình trụ; đầu sắt dưới cán giáo | 錞 gồm bộ 金 (kim, biểu nghĩa: kim loại) và phần biểu âm. Cấu trúc hình thanh; Wiktionary không phân tích ngữ nguyên cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuần\": nhạc khí 錞 mang bộ 金 (đồng) — cái chuông đồng \"thuần\" khiết, tiếng vang \"thuần\" gọi quân ra trận khi gõ cùng trống. | Gương Hán-Việt | thuần trong \"thuần khiết\" — âm thuần của 錞 gợi âm thanh trong trẻo của chuông đồng chiến trận. | Mở khoá kiến thức | Biết 錞 giúp đọc văn mô tả nhạc lễ và chiến trận cổ đại: 錞于 (chuông đồng trận), 金錞 (chuông vàng).", "Tự nguyên_Xie": "Kim văn | Lục thư thông | Chữ 錞 có hai âm: chún (nhạc khí 錞于 — chuông đồng hình trụ đầu hổ, đánh cùng trống trong chiến trận) và duì (đầu sắt dẹt dưới cán giáo). Wiktionary ghi nhận cả hai nghĩa lịch sử với bộ 金. Không có phân tích ngữ nguyên riêng. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái thuần vu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 享", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金享", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "享", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "𬭚", "Unihan_Traditional (Chữ Phồn thể)": "錞", "Pinyin_Xie": "chún", "Âm Hán Việt_Xie": "thuần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại nhạc khí cổ bằng đồng hoặc phần chuôi của binh khí. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靣', '{"9000": "7157.0", "Chữ Trung Quốc": "靣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 面 | Số nét | 8 | nét | 靣 | diện | tượng hình | mặt người, bề mặt — dạng cổ của 面 | 靣 là dạng cổ tượng hình của 面 (mặt). Không có dữ liệu Wiktionary ngữ nguyên riêng; đây là chính chữ gốc của 面.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diện\": chữ 靣 là dạng cổ tượng hình của mặt người — \"diện\" mạo nhìn thẳng, giáp cốt vẽ rõ mắt và gương mặt. | Gương Hán-Việt | diện trong \"diện mạo\", \"tứ diện\" — 靣 là gốc cổ của 面, cùng đọc diện trong Hán-Việt. | Mở khoá kiến thức | Biết 靣 giúp nhận ra dạng cổ của 面 trong thư pháp và kim văn; cùng HV diện với 面.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Chữ 靣 là dạng cổ/chánh thể của 面 (mặt). Giáp cốt văn vẽ hình mặt người với mắt, mũi. Nghĩa: mặt người, bề mặt. Wiktionary không có dữ liệu riêng cho 靣; mọi ngữ nguyên tra ở 面. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mặt; bề mặt", "Hạng Tần Suất (Jun Da)": "7157.0", "Tần Suất % (Jun Da)": "99.9976010834", "GavinGrover_Once (Chiết tự trực tiếp)": "一 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱一", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "靣", "Unihan_Traditional (Chữ Phồn thể)": "靣", "Pinyin_Xie": "miàn", "Âm Hán Việt_Xie": "diện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Từ chỉ phương vị | 方位词 | Dùng làm danh từ chỉ khuôn mặt, lượng từ cho các vật phẳng hoặc từ chỉ phương hướng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Từ chỉ phương vị | 方位词 | Chỉ vị trí và đứng SAU danh từ — 桌子上, 家里 — chứ không đứng trước như ''trên bàn'', ''trong nhà''. Thường đi cùng 在.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸂', '{"9000": "7158.0", "Chữ Trung Quốc": "鸂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 24 | nét | 溪 | khe | biểu âm | 鳥 | điểu | biểu nghĩa | chim | 鸂 = 溪 (Khe, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim); chữ hình thanh. Phần 鳥 cho biết là loài chim; phần 溪 cho âm đọc xī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khê\": chữ 鸂 = chim (鳥) + khe suối (溪) — loài vịt \"khê\" sắc sặc sỡ sống ven khe suối, chỉ dùng trong tên 鸂鶒. | Gương Hán-Việt | khê trong \"khê suối\" — âm khê của 鸂 trùng với nghĩa khe suối, nơi loài vịt này sinh sống. | Mở khoá kiến thức | Biết 鸂 giúp đọc thơ cổ và danh sách chim trong văn học Trung Quốc: 鸂鶒 (vịt sắc đẹp sống ở suối).", "Tự nguyên_Xie": "Theo Wiktionary, 鸂 là chữ hình thanh: 溪 (khe) biểu âm, 鳥 (điểu) biểu nghĩa. Chỉ dùng trong tổ hợp 鸂鶒 — tên một loài vịt màu sắc đẹp (Mandarin duck area). Đây là loài chim sống ở suối khe. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khê xích 鸂鶒)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 鷄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵鷄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鷄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "㶉", "Unihan_Traditional (Chữ Phồn thể)": "鸂", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "khê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép để chỉ một loài chim nước cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麐', '{"9000": "7159.0", "Chữ Trung Quốc": "麐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 18 | nét | 麐 | lân | tượng hình | kỳ lân cái (con kỳ lân giống cái) | 麐 gồm bộ 鹿 (lộc, biểu nghĩa: hươu nai/kỳ thú) và phần biểu âm. Cấu trúc hình thanh; Wiktionary không có dữ liệu ngữ nguyên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lân\": chữ 麐 mang bộ 鹿 (hươu) — con kỳ \"lân\" cái, linh thú huyền thoại hiền lành báo điềm lành — âm lân trùng với 麟 phổ biến hơn. | Gương Hán-Việt | lân trong \"kỳ lân\" — 麐 là dạng chữ chỉ kỳ lân giống cái, cùng họ với 麟. | Mở khoá kiến thức | Biết 麐 giúp phân biệt kỳ lân đực (麒) và kỳ lân cái (麐) trong thư tịch cổ về điềm lành.", "Tự nguyên_Xie": "Giáp cốt văn | Chữ 麐 chỉ kỳ lân giống cái (female Chinese unicorn), tương tự như 麟 (kỳ lân nói chung). Wiktionary không có dữ liệu. Bộ 鹿 phù hợp với loài thú huyền thoại hình hươu. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con kỳ lân (như: kỳ lân 麒麟)", "Hạng Tần Suất (Jun Da)": "2746.0", "Tần Suất % (Jun Da)": "98.8886204937", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 吝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿吝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麟", "Unihan_Traditional (Chữ Phồn thể)": "麐", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ con kỳ lân cái hoặc linh vật kỳ lân trong truyền thuyết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麚', '{"9000": "7160.0", "Chữ Trung Quốc": "麚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 20 | nét | 鹿 | lộc | biểu nghĩa | hươu | 叚 | biểu âm | 麚 = 鹿 (Lộc, biểu nghĩa: hươu) + 叚 (biểu âm); chữ hình thanh. Phần 鹿 cho biết là loài hươu đực; phần 叚 cho âm đọc gần jiā.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giả\": hươu đực 麚 = 鹿 (hươu) + 叚 (giả) — con hươu đực \"giả\" vờ hiền lành, thực ra sung mãnh; bộ 鹿 xác nhận loài. | Gương Hán-Việt | giả trong \"giả tạo\" — âm giả của 麚 gợi hình ảnh hươu đực trổ bộ oai phong mùa giao phối. | Mở khoá kiến thức | Biết 麚 giúp phân biệt hươu đực (麚) và hươu xạ cái (麜) trong động vật học cổ Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 麚 là chữ hình thanh: 鹿 (lộc) biểu nghĩa hươu, 叚 biểu âm. Nghĩa: con hươu đực (stag). Cấu trúc rõ ràng và đáng tin cậy. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con hươu đực", "Hạng Tần Suất (Jun Da)": "7160.0", "Tần Suất % (Jun Da)": "99.9976088352", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 叚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿叚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麚", "Unihan_Traditional (Chữ Phồn thể)": "麚", "Pinyin_Xie": "jiā", "Âm Hán Việt_Xie": "gia", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ con hươu đực hoặc các loài thú thuộc họ hươu nai giống đực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齧', '{"9000": "7161.0", "Chữ Trung Quốc": "齧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 21 | nét | 齧 | nghệ | tượng hình | cắn, gặm; ăn mòn | 齧 gồm bộ 齒 (xỉ, biểu nghĩa: răng) và phần biểu âm. Cấu trúc hình thanh; Wiktionary chỉ ghi {{Han etym}} không có phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghệ\": chữ 齧 mang bộ 齒 (răng) — cắn \"nghệ\" ngấu, răng 齒 gặm mãi cho đến khi ăn mòn — từ 齧合 nghĩa là khớp răng vào nhau. | Gương Hán-Việt | nghệ trong \"nghệ nhân\" — âm nghệ của 齧 gợi kỹ năng dùng răng gặm nhấm tỉ mỉ của nghệ nhân gỗ. | Mở khoá kiến thức | Biết 齧 giúp đọc văn cổ và thành ngữ: 齧臂 (cắn tay thề), 鯨吞蛟齧 (nuốt tươi).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 齧 nghĩa là cắn, gặm (bite, gnaw); cũng có nghĩa ăn mòn. Bộ 齒 (xỉ, răng) biểu nghĩa rõ ràng. Wiktionary không có phân tích ngữ nguyên chi tiết. Chữ giản thể phổ biến là 啮. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1348.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xỉ (194) Khất (1347)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Khất (số 1347 - khắc chạm/ 㓞 /chỉ âm) ở trên bộ Xỉ (số 194 - răng/ 齒 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Khất chỉ âm, bộ Xỉ chỉ ý. Niết là dùng răng để cắn, gặm. (Chữ Niết có một cách viết khác là thêm bộ Khẩu ở bên trái: 囓).", "Nghĩa Tiếng Việt_Xie": "cắn", "Hạng Tần Suất (Jun Da)": "7161.0", "Tần Suất % (Jun Da)": "99.9976114191", "GavinGrover_Once (Chiết tự trực tiếp)": "㓞 + 齒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱㓞齒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㓞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齒", "Unihan_Simplified (Chữ Giản thể)": "齧", "Unihan_Traditional (Chữ Phồn thể)": "齧", "Pinyin_Xie": "niè", "Âm Hán Việt_Xie": "nghệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ đứng trước danh từ chỉ vật bị cắn hoặc gặm nhấm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睊', '{"9000": "7163.0", "Chữ Trung Quốc": "睊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 12 | nét | 睊 | quyến | tượng hình | liếc nhìn nghiêng, nhìn xéo | 睊 gồm bộ 目 (mục, biểu nghĩa: mắt) và phần biểu âm. Cấu trúc hình thanh; Wiktionary ghi nhận nghĩa squint/look askance.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyến\": chữ 睊 mang bộ 目 (mắt) — ánh mắt \"quyến\" luyến liếc xéo, nhìn nghiêng như không muốn bị biết là đang nhìn. | Gương Hán-Việt | quyến trong \"quyến luyến\" — ánh mắt 睊 liếc xéo đầy quyến luyến bí ẩn. | Mở khoá kiến thức | Biết 睊 giúp đọc văn miêu tả ánh mắt trong tiểu thuyết và thơ cổ Trung Quốc.", "Tự nguyên_Xie": "Chữ 睊 nghĩa là liếc nhìn xéo, nhìn nghiêng (squint, look askance). Bộ 目 (mắt) biểu nghĩa rõ ràng. Wiktionary ghi nhận âm đọc juàn và nghĩa nhưng không phân tích ngữ nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ghé mắt nhìn", "Hạng Tần Suất (Jun Da)": "7163.0", "Tần Suất % (Jun Da)": "99.997616587", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 肙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目肙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睊", "Unihan_Traditional (Chữ Phồn thể)": "睊", "Pinyin_Xie": "juàn", "Âm Hán Việt_Xie": "quyến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ hành động liếc nhìn hoặc nhìn nghiêng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砢', '{"9000": "7164.0", "Chữ Trung Quốc": "砢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 砢 | kha | tượng hình | đống đá, đá chồng chất | 砢 gồm bộ 石 (thạch, biểu nghĩa: đá) và phần biểu âm 可. Cấu trúc hình thanh; Wiktionary không có định nghĩa rõ (rfdef).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kha\": chữ 砢 mang bộ 石 (đá) — những viên đá \"kha\" khá chồng chất lên nhau thành gò, cứng chắc như nghị lực vượt gian khó. | Gương Hán-Việt | kha trong \"kha khá\" — âm kha của 砢 gợi cảm giác vật cứng đá chắc chắn. | Mở khoá kiến thức | Biết 砢 giúp nhận diện nhóm chữ miêu tả đá và địa hình đá trong văn học và địa lý cổ.", "Tự nguyên_Xie": "Chữ 砢 thuộc bộ 石 (đá), âm đọc luǒ hoặc kē. Wiktionary không có định nghĩa cụ thể (rfdef). Nghĩa theo từ điển: đống đá, đá chồng chất. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem \"珂\"", "Hạng Tần Suất (Jun Da)": "7164.0", "Tần Suất % (Jun Da)": "99.9976191709", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 可", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石可", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "可", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砢", "Unihan_Traditional (Chữ Phồn thể)": "砢", "Pinyin_Xie": "kē", "Âm Hán Việt_Xie": "kha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ trong từ ghép để miêu tả vẻ gồ ghề của đá hoặc tài năng lỗi lạc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碻', '{"9000": "7165.0", "Chữ Trung Quốc": "碻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 15 | nét | 碻 | xác | tượng hình | bền vững, chính xác, đúng | 碻 gồm bộ 石 (thạch, biểu nghĩa: đá, bền chắc) và phần biểu âm. Cấu trúc hình thanh; Wiktionary chỉ ghi {{Han etym}}.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xác\": chữ 碻 mang bộ 石 (đá) — cứng \"xác\" như đá, chắc \"xác\" thực như sự thật — gợi tính chính xác không thể lay chuyển. | Gương Hán-Việt | xác trong \"chính xác\" — âm xác của 碻 trùng với nghĩa: chính xác, đúng như đá. | Mở khoá kiến thức | Biết 碻 giúp nhận dạng nhóm chữ miêu tả sự kiên cố, chính xác thuộc bộ 石 trong văn cổ.", "Tự nguyên_Xie": "Chữ 碻 nghĩa là bền lâu, chính xác. Bộ 石 (đá) biểu nghĩa sự cứng chắc, bền vững. Wiktionary không có phân tích ngữ nguyên chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bền lâu; đúng, trúng, chính xác", "Hạng Tần Suất (Jun Da)": "7165.0", "Tần Suất % (Jun Da)": "99.9976217548", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 高", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石高", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "高", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碻", "Unihan_Traditional (Chữ Phồn thể)": "碻", "Pinyin_Xie": "què", "Âm Hán Việt_Xie": "xác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc phó từ đứng trước động từ để khẳng định tính chắc chắn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絃', '{"9000": "7166.0", "Chữ Trung Quốc": "絃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 糸 | biểu nghĩa | tơ lụa, sợi | 玄 | huyền | biểu âm | 絃 = 糸 (biểu nghĩa: tơ sợi) + 玄 (Huyền, biểu âm); chữ hình thanh. Phần 糸 cho biết đây là sợi dây đàn làm từ tơ; phần 玄 cho âm đọc xián.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyền\": chữ 絃 = tơ (糸) + huyền (玄) — dây đàn \"huyền\" diệu làm từ tơ, âm huyền trùng khớp với nghĩa huyền bí của âm nhạc. | Gương Hán-Việt | huyền trong \"huyền cầm\" — 絃 là dạng chánh thể của 弦, cùng chỉ dây đàn trong Hán-Việt. | Mở khoá kiến thức | Biết 絃 mở khoá: 絃歌 (đàn hát), 絃管 (nhạc cụ dây và ống), 和絃 (hợp âm), 絃索 (dây đàn).", "Tự nguyên_Xie": "Theo Wiktionary, 絃 là chữ hình thanh: 糸 (tơ sợi) biểu nghĩa, 玄 (huyền) biểu âm. Là dạng chánh thể của 弦 — dây đàn nhạc cụ. Cũng có âm xuàn là dạng thay thế của 絢 (rực rỡ). Nguồn: Wiktionary Han etyl. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợi dây", "Hạng Tần Suất (Jun Da)": "7166.0", "Tần Suất % (Jun Da)": "99.9976243387", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 玄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹玄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "玄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "絃", "Unihan_Traditional (Chữ Phồn thể)": "絃", "Pinyin_Xie": "xián", "Âm Hán Việt_Xie": "huyền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ làm tân ngữ cho các động từ như gảy, lên dây hoặc làm định ngữ bổ nghĩa cho nhạc cụ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茝', '{"9000": "7167.0", "Chữ Trung Quốc": "茝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 茝 | chỉ | tượng hình | cây bạch chỉ (Angelica dahurica), tên cổ | 茝 gồm bộ 艸 (thảo, biểu nghĩa: cỏ cây) và phần biểu âm. Cấu trúc hình thanh; Wiktionary ghi nhận tên khoa học và nguồn văn Thuyết Văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chỉ\": cây 茝 mang bộ 艸 (cỏ) — loài \"chỉ\" thảo thơm ngát, tên của người Tề gọi cây bạch chỉ, xuất hiện trong thơ Khuất Nguyên bên cạnh 蘺. | Gương Hán-Việt | chỉ trong \"chỉ lan\" — 茝 là tên phương ngữ nước Tề của cây bạch chỉ, cùng họ với 蘺 (蓠). | Mở khoá kiến thức | Biết 茝 giúp đọc thơ Khuất Nguyên (Sở từ) và phân biệt ba tên phương ngữ của cây bạch chỉ: 蘺/茝/虈.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 茝 là tên cổ của cây Angelica dahurica (bạch chỉ). Thuyết Văn ghi: 楚謂之蘺，晉謂之虈，齊謂之茝 (Sở gọi là 蘺, Tấn gọi là 虈, Tề gọi là 茝). Đây là ba tên phương ngữ của cùng một cây thơm. Âm chǎi hoặc zhǐ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: kỳ chỉ 蘄茝,蕲茝)", "Hạng Tần Suất (Jun Da)": "7167.0", "Tần Suất % (Jun Da)": "99.9976269227", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 𦣞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹𦣞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦣞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茝", "Unihan_Traditional (Chữ Phồn thể)": "茝", "Pinyin_Xie": "chǎi", "Âm Hán Việt_Xie": "chỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn học cổ để chỉ các loài cỏ thơm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菴', '{"9000": "7168.0", "Chữ Trung Quốc": "菴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菴 | am | tượng hình | ni viện nhỏ, am thất Phật giáo | 菴 gồm bộ 艸 (thảo, biểu nghĩa: cỏ tranh/mái lá) và phần biểu âm. Cấu trúc hình thanh; Wiktionary chỉ ghi {{Han etym}}.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"am\": chữ 菴 mang bộ 艸 (lá cỏ) — mái \"am\" lá tranh che mưa, nơi ni cô tu hành thanh tịnh — âm am trùng khớp hoàn toàn với tiếng Việt. | Gương Hán-Việt | am trong \"ni am\" — 菴 là dạng cổ/dị thể của 庵, cùng đọc am trong tiếng Việt. | Mở khoá kiến thức | Biết 菴 giúp nhận ra dạng cổ của 庵 trong thư tịch Phật giáo; am trùng hoàn toàn với tiếng Việt.", "Tự nguyên_Xie": "Chữ 菴 nghĩa là am thất nhỏ, ni viện Phật giáo. Bộ 艸 (cỏ/lá) gợi mái tranh của am nhỏ. Wiktionary không có phân tích ngữ nguyên chi tiết. Chữ thông dụng hơn là 庵. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ni viện", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 奄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹奄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菴", "Unihan_Traditional (Chữ Phồn thể)": "菴", "Pinyin_Xie": "ān", "Âm Hán Việt_Xie": "am", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ nơi tu hành nhỏ hoặc am cỏ của ẩn sĩ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袥', '{"9000": "7169.0", "Chữ Trung Quốc": "袥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袥 | thác | tượng hình | y phục, áo (nghĩa chưa xác định rõ) | 袥 gồm bộ 衣 (y, biểu nghĩa: quần áo) và phần biểu âm 石/宅. Cấu trúc hình thanh; Wiktionary không có định nghĩa (rfdef).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thác\": chữ 袥 mang bộ 衣 (áo) — chiếc áo \"thác\" nhờ người khác mặc, giao phó lại như ủy thác — bộ 衣 xác nhận liên quan đến y phục. | Gương Hán-Việt | thác trong \"ủy thác\" — âm thác của 袥 gợi hình ảnh áo khoác được truyền giao lại. | Mở khoá kiến thức | Biết 袥 giúp nhận diện nhóm chữ y phục cổ thuộc bộ 衣 trong văn hiến trang phục Trung Quốc.", "Tự nguyên_Xie": "Chữ 袥 thuộc bộ 衣 (y, quần áo), âm đọc tuō. Wiktionary không có định nghĩa cụ thể (rfdef). Nghĩa không rõ ràng. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "奥", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "石", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袥", "Unihan_Traditional (Chữ Phồn thể)": "袥", "Pinyin_Xie": "tuō", "Âm Hán Việt_Xie": "thác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ vạt áo hoặc động từ chỉ hành động đo đạc, mở rộng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('襍', '{"9000": "7170.0", "Chữ Trung Quốc": "襍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 17 | nét | 襍 | tạp | tượng hình | lẫn lộn, tạp loạn — dạng cổ của 雜 | 襍 là dạng cổ của 雜 (tạp). Gồm bộ 衣 (y, áo) và các phần biểu âm/nghĩa khác. Wiktionary không có dữ liệu ngữ nguyên riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tạp\": chữ 襍 mang bộ 衣 (áo) — nhiều loại áo \"tạp\" nhạp trộn lẫn, như 雜 (tạp) là dạng thông dụng hơn của cùng chữ này. | Gương Hán-Việt | tạp trong \"tạp chí\", \"tạp nham\" — 襍 là dạng cổ của 雜, cùng đọc tạp trong Hán-Việt. | Mở khoá kiến thức | Biết 襍 giúp nhận ra dạng cổ của 雜 trong văn bản lịch sử và thư pháp cổ đại.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 襍 là dạng cổ của 雜 (tạp — lẫn lộn, hỗn tạp). Wiktionary không có dữ liệu riêng cho 襍. Bộ 衣 (áo) trong 襍 gợi hình ảnh nhiều loại vải/màu sắc áo trộn lẫn nhau. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tạp; như \"tạp phẩm\" \nNguyên là chữ tạp 雜.", "Hạng Tần Suất (Jun Da)": "851.0", "Tần Suất % (Jun Da)": "86.4381710151", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 集", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤集", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "集", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "杂", "Unihan_Traditional (Chữ Phồn thể)": "襍", "Pinyin_Xie": "zá", "Âm Hán Việt_Xie": "tập", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ đứng trước danh từ để chỉ sự hỗn tạp, nhiều thành phần khác nhau. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('覗', '{"9000": "7171.0", "Chữ Trung Quốc": "覗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 見 | Số nét | 12 | nét | 覗 | tứ | tượng hình | nhìn trộm, nhìn lén | 覗 gồm bộ 見 (kiến, biểu nghĩa: nhìn thấy) và phần biểu âm 司/思. Cấu trúc hình thanh; Wiktionary ghi nhận nghĩa peek.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tứ\": chữ 覗 mang bộ 見 (nhìn) — ánh mắt \"tứ\" phía lén nhòm, nhìn trộm từ bốn phương không dám nhìn thẳng. | Gương Hán-Việt | tứ trong \"tứ phía\" — ánh mắt 覗 nhìn trộm từ tứ phía bốn góc như do thám. | Mở khoá kiến thức | Biết 覗 giúp đọc văn học cận đại Trung Quốc, đặc biệt trong văn Lỗ Tấn về hành động nhìn lén.", "Tự nguyên_Xie": "Chữ 覗 nghĩa là nhìn trộm (peek). Bộ 見 (kiến, nhìn) biểu nghĩa rõ ràng. Wiktionary ghi nhận âm sì và ví dụ từ văn Lỗ Tấn (1934). Ít dùng; thay thế bằng 窥 hoặc 偷看 trong hiện đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhìn trộm", "Hạng Tần Suất (Jun Da)": "7171.0", "Tần Suất % (Jun Da)": "99.9976372584", "GavinGrover_Once (Chiết tự trực tiếp)": "司 + 見", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰司見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "司", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "見", "Unihan_Simplified (Chữ Giản thể)": "覗", "Unihan_Traditional (Chữ Phồn thể)": "覗", "Pinyin_Xie": "sì", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ đối tượng bị rình rập hoặc nhìn trộm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('諥', '{"9000": "7172.0", "Chữ Trung Quốc": "諥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 16 | nét | 諥 | trọng | tượng hình | chữ thuộc bộ 言, nghĩa chưa xác định | 諥 gồm bộ 言 (ngôn, biểu nghĩa: lời nói) và phần biểu âm 重. Cấu trúc hình thanh; Wiktionary không có định nghĩa cụ thể (rfdef).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trọng\": chữ 諥 mang bộ 言 (lời) — lời nói \"trọng\" đại, nặng cân — bộ 言 xác nhận đây là chữ liên quan đến ngôn từ. | Gương Hán-Việt | trọng trong \"trọng đại\" — âm trọng của 諥 gợi lời nói có trọng lượng, uy tín. | Mở khoá kiến thức | Biết 諥 giúp nhận diện nhóm chữ hiếm thuộc bộ 言 trong từ điển văn ngôn cổ.", "Tự nguyên_Xie": "Chữ 諥 thuộc bộ 言 (ngôn), âm đọc zhòng. Wiktionary không có định nghĩa (rfdef). Nghĩa không rõ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "襥", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 重", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言重", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "重", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "諥", "Unihan_Traditional (Chữ Phồn thể)": "諥", "Pinyin_Xie": "zhòng", "Âm Hán Việt_Xie": "trọng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ việc nói lặp đi lặp lại hoặc tính từ miêu tả lời nói rườm rà. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跂', '{"9000": "7173.0", "Chữ Trung Quốc": "跂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 11 | nét | 跂 | kỳ | tượng hình | ngón chân thừa; dáng bò lê; đứng nhón gót | 跂 gồm bộ 足 (túc, biểu nghĩa: chân) và phần biểu âm 支/氏. Cấu trúc hình thanh; Wiktionary chỉ ghi {{Han etym}}.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": chữ 跂 mang bộ 足 (chân) — ngón chân \"kỳ\" lạ thừa ra, hoặc dáng đứng nhón \"kỳ\" kỳ trên đầu ngón — bộ 足 xác nhận liên quan đến chân. | Gương Hán-Việt | kỳ trong \"kỳ lạ\" — âm kỳ của 跂 gợi ngón chân thừa kỳ lạ hoặc dáng đứng bất thường. | Mở khoá kiến thức | Biết 跂 giúp đọc văn cổ miêu tả dáng đi và bộ phận chân trong y học và thơ văn.", "Tự nguyên_Xie": "Chữ 跂 thuộc bộ 足 (túc, chân), âm đọc qí (ngón chân thừa) hoặc qǐ (đứng nhón gót). Bộ 足 phù hợp với nghĩa liên quan đến chân và dáng đi. Wiktionary không có phân tích chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1714.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Túc (157) Chi (065)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Túc (số 157 - cái chân/ 足 /chỉ ý) ở bên trái chữ Chi (số 065 - cành cây/ 支 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Chi chỉ âm, bộ Túc chỉ ý. Kỳ là dùng một chân để làm trụ tựa đứng, nhón gót (kỳ vọng). Cũng có nghĩa là kiễng chân dùng sức để chống trả.", "Nghĩa Tiếng Việt_Xie": "ngón chân thừa; dáng sâu bò; kiểu sâu bò", "Hạng Tần Suất (Jun Da)": "7173.0", "Tần Suất % (Jun Da)": "99.9976450101", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 支", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊支", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "支", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跂", "Unihan_Traditional (Chữ Phồn thể)": "跂", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ hành động kiễng chân hoặc làm danh từ chỉ ngón chân thừa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辵', '{"9000": "7174.0", "Chữ Trung Quốc": "辵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 7 | nét | 彳 | biểu ý | đi bước nhỏ | 止 | chỉ | biểu ý | bàn chân, dừng lại | 辵 = 彳 (đi bước nhỏ, biểu ý) + 止 (Chỉ, biểu ý: bàn chân/dừng lại); chữ hội ý. Kết hợp hai thành phần hành động di chuyển tạo ra nghĩa đi-dừng xen kẽ. Phần dưới nay biến thành 龰 trong các chữ phái sinh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sước\": chữ 辵 = bước đi (彳) + dừng chân (止) — \"sước\" nghĩa là đi rồi dừng, dừng rồi đi, như người do dự trên đường; bộ sước này tạo ra 辶 trong 道, 过, 进, 还. | Gương Hán-Việt | sước trong \"bộ sước\" — 辵 chính là bộ thủ gốc của 辶 (sước), xuất hiện trong hàng trăm chữ di chuyển. | Mở khoá kiến thức | Biết 辵 mở khoá toàn bộ chữ dùng 辶: 道 (đạo), 过 (quá), 进 (tiến), 还 (hoàn), 通 (thông), 这 (giá).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 辵 là chữ hội ý: 彳 (đi bước nhỏ) + 止 (bàn chân hoặc dừng lại) = đi một lúc rồi dừng, đi-dừng xen kẽ. Dạng bảo thủ hơn là 𣥆. Phần dưới trong các chữ phái sinh nay biến dạng thành 龰. 辵 là bộ thủ 162 (Khang Hy). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "644.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Sam (150) Chỉ (553)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Sam (số 150 - ba nét phẩy / tóc/lông mi) ở trên chữ Chỉ (số 553 - bàn chân/dừng lại). Đi bước một lại phải dừng một nhịp. Giải thích sự chuyển ý: Đây là chữ Hội ý. Sự kết hợp của bước chân đi và sự dừng lại. Xước là bước đi ngắn, đi chậm, lúc đi lúc nghỉ (thường dùng làm bộ thủ 辶).", "Nghĩa Tiếng Việt_Xie": "bộ sước", "Hạng Tần Suất (Jun Da)": "7174.0", "Tần Suất % (Jun Da)": "99.9976475941", "GavinGrover_Once (Chiết tự trực tiếp)": "彡 + 龰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱彡龰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彡", "Unihan_Simplified (Chữ Giản thể)": "辵", "Unihan_Traditional (Chữ Phồn thể)": "辵", "Pinyin_Xie": "chuò", "Âm Hán Việt_Xie": "sước", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này chủ yếu dùng làm bộ thủ trong cấu tạo chữ Hán hoặc làm động từ chỉ dáng đi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邅', '{"9000": "7175.0", "Chữ Trung Quốc": "邅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 16 | nét | 邅 | chênh | tượng hình | đi khó khăn, do dự | 邅 không có cây thành phần rõ ràng trong dữ liệu CHISE. Chữ thuộc bộ 辵 (xước — đi bộ), gợi ý hành động di chuyển khó khăn. Chưa xác định rõ hình thanh hay hội ý; confidence thấp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chênh\": bộ 辵 (đường đi) gợi bước chân chênh vênh, khốn đốn, không tiến được. | Gương Hán-Việt | chênh — ít dùng trong tiếng Việt hiện đại; gặp trong văn ngôn: \"truân chuyên\" (gian khó). | Mở khoá kiến thức | Biết 邅 mở khoá cụm văn ngôn 邅迍 / 迍邅 — dùng trong thơ chữ Hán chỉ cảnh khốn cùng.", "Tự nguyên_Xie": "邅 nghĩa gốc là đổi hướng, đi khó; cũng chỉ trạng thái gian nan, khốn đốn. Wiktionary ghi nhận có hợp âm trung cổ (mc=y, oc=y) nhưng không có sơ đồ cấu tạo rõ ràng. Chữ thuộc bộ 辵 (đi bộ). Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "truân chiên; khốn đốn", "Hạng Tần Suất (Jun Da)": "7175.0", "Tần Suất % (Jun Da)": "99.997650178", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 亶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶亶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "邅", "Unihan_Traditional (Chữ Phồn thể)": "邅", "Pinyin_Xie": "zhān", "Âm Hán Việt_Xie": "triên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ mô tả hoàn cảnh khó khăn, trắc trở hoặc động từ chỉ sự xoay vần. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醨', '{"9000": "7176.0", "Chữ Trung Quốc": "醨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 17 | nét | 醨 | lê | tượng hình | rượu nhạt, cặn rượu | 醨 thuộc bộ 酉 (dậu — rượu/bình rượu), chỉ loại rượu nhạt, lạt. Dữ liệu CHISE không cung cấp cây thành phần chi tiết. Chưa xác định rõ hình thanh hay hội ý từ anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lê\": bộ 酉 (rượu) + chữ nhẹ — rượu LÊ thê, nhạt lạt như nước lã. | Gương Hán-Việt | lê — ít xuất hiện trong từ vựng Hán-Việt thông dụng; dùng trong trích dẫn văn học cổ. | Mở khoá kiến thức | Biết 醨 mở khoá cụm 醇醨 — đối lập giữa rượu nồng (醇) và rượu nhạt (醨), thường gặp trong thành ngữ chỉ sự khác biệt chất lượng.", "Tự nguyên_Xie": "Triện thư | Lục thư thông | 醨 nghĩa là rượu nhạt (thin wine) hoặc nhạt nhẽo, vô vị — dùng theo nghĩa bóng. Chữ thuộc bộ 酉 (rượu). Wiktionary ghi \"literary: thin wine; light, insipid\". Seal script có trong chuỗi ảnh etymology. Cấu tạo chi tiết chưa được Wiktionary phân tích đầy đủ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rượu lạt, rượu nhạt", "Hạng Tần Suất (Jun Da)": "7176.0", "Tần Suất % (Jun Da)": "99.9976527619", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 离", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉离", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "离", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醨", "Unihan_Traditional (Chữ Phồn thể)": "醨", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ loại rượu nhẹ hoặc làm tính từ bổ nghĩa cho đồ uống ít cồn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('頍', '{"9000": "7177.0", "Chữ Trung Quốc": "頍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 13 | nét | 頍 | khôi | tượng hình | ngẩng đầu; dải đầu | 頍 thuộc bộ 頁 (hiệt — đầu người), chỉ hành động ngẩng đầu hoặc loại băng/dải đội đầu. Dữ liệu CHISE không cung cấp cây thành phần chi tiết. Chưa xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khôi\": bộ 頁 (đầu) — đầu ngẩng lên KHÔI ngô, hoặc dải băng trên đầu. | Gương Hán-Việt | khôi — ít dùng trong tiếng Việt; \"khôi ngô\" (tuấn tú) dùng chữ 魁 khác. | Mở khoá kiến thức | Biết 頍 mở khoá cụm cổ ngữ 頍弁 — chỉ loại mũ đội trong lễ nghi thời Chu.", "Tự nguyên_Xie": "Triện thư | 頍 có hai nghĩa cổ: (1) ngẩng đầu lên (to raise one''s head), (2) dải đầu/khăn đội đầu (hairband). Thuộc bộ 頁 (đầu người). Gặp trong cụm 頍弁 — chỉ mũ đội đầu kiểu cổ. Wiktionary ghi nhận âm mc/oc nhưng không có phân tích cấu tạo. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鍍", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "支 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰支頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "頁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "支", "Unihan_Simplified (Chữ Giản thể)": "𫠆", "Unihan_Traditional (Chữ Phồn thể)": "頍", "Pinyin_Xie": "kuǐ", "Âm Hán Việt_Xie": "khôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ chỉ hành động ngẩng đầu hoặc tính từ miêu tả dáng mũ đội ngay ngắn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疰', '{"9000": "7178.0", "Chữ Trung Quốc": "疰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 10 | nét | 疰 | chú | tượng hình | bệnh trẻ em mùa hè | 疰 thuộc bộ 疒 (nạch — bệnh tật), chỉ loại bệnh đặc thù. Dữ liệu CHISE không cung cấp cây thành phần chi tiết. Chưa xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chú\": bộ 疒 (bệnh) + nghĩa chú giải — bệnh CHÚ ý đặc biệt khi hè đến, hay quật ngã trẻ em. | Gương Hán-Việt | chú — không phổ biến trong tiếng Việt hiện đại; dùng trong Đông y, văn ngôn. | Mở khoá kiến thức | Biết 疰 mở khoá các cụm Đông y: 疰夏 (hội chứng mùa hè), 鬼疰 (bệnh tà ma), 疰車/疰船 (say xe/say tàu).", "Tự nguyên_Xie": "疰 là thuật ngữ y học cổ chỉ chứng bệnh mà trẻ em hay mắc vào mùa hè (疰夏 — bệnh mùa hạ). Cũng dùng trong 鬼疰, 屍疰 — chỉ bệnh do tà khí. Wiktionary ghi rfdef (chưa định nghĩa đầy đủ). Thuộc bộ 疒. Chưa có nguồn học thuật đầy đủ về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trẻ con đến mùa hè hay ốm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 主", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒主", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "主", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "疰", "Unihan_Traditional (Chữ Phồn thể)": "疰", "Pinyin_Xie": "zhù", "Âm Hán Việt_Xie": "chú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm danh từ trong y học cổ truyền để chỉ chứng bệnh mệt mỏi do thời tiết mùa hè. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觜', '{"9000": "7179.0", "Chữ Trung Quốc": "觜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 角 | Số nét | 13 | nét | 此 | thử | biểu âm | this | 角 | giác | biểu nghĩa | sừng, góc | 觜 = 此 (Thử, biểu âm) + 角 (Giác, biểu nghĩa: sừng/mỏ nhọn). Chữ hình thanh (ls=psc): 角 cho nghĩa (mỏ nhọn như sừng), 此 cho âm. Chỉ sao Chủy (một trong Nhị thập bát tú) hoặc lông mỏ con cú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chủy\": bộ 角 (sừng nhọn) — CHỦY là mỏ nhọn như sừng, cũng là tên ngôi sao nhọn trên bầu trời. | Gương Hán-Việt | chủy — dùng trong thiên văn cổ: sao Chủy (觜宿) trong Nhị thập bát tú. | Mở khoá kiến thức | Biết 觜 mở khoá hệ thống Nhị thập bát tú — 28 chòm sao cổ đại Trung Hoa dùng trong lịch pháp và chiêm tinh.", "Tự nguyên_Xie": "Triện thư | 觜 là chữ hình thanh: 角 (giác — sừng, mỏ nhọn) biểu nghĩa, 此 (thử) biểu âm. Nghĩa gốc chỉ mỏ nhọn của chim cú (lông quanh mỏ). Sau dùng làm tên sao Chủy — một trong Nhị thập bát tú (二十八宿), vị trí trên bầu trời phương Tây. Wiktionary xác nhận cấu tạo psc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1169.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thử (1159) Giác (080)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thử (số 1159 - chỗ này/chỉ âm) ở trên chữ Giác (số 080 - cái sừng/chỉ ý - mỏ chim cứng như sừng). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thử chỉ âm, bộ Giác chỉ ý. Chủy là cái mỏ của con chim.", "Nghĩa Tiếng Việt_Xie": "sao Tuy (một trong Nhị thập bát tú); lông mỏ con cú", "Hạng Tần Suất (Jun Da)": "7179.0", "Tần Suất % (Jun Da)": "99.9976605137", "GavinGrover_Once (Chiết tự trực tiếp)": "此 + 角", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱此角", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "此", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "角", "Unihan_Simplified (Chữ Giản thể)": "觜", "Unihan_Traditional (Chữ Phồn thể)": "觜", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tuỷ, tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ chỉ bộ phận của chim hoặc tên một chòm sao trong nhị thập bát tú. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笭', '{"9000": "7180.0", "Chữ Trung Quốc": "笭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 笭 | linh | tượng hình | đồ bằng tre, giỏ cá | 笭 thuộc bộ 竹 (trúc — tre), chỉ đồ vật làm bằng tre. Dữ liệu CHISE không cung cấp cây thành phần chi tiết. Chưa xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\": bộ 竹 (tre) — LINH hoạt như tre, đan thành giỏ câu nhẹ nhàng. | Gương Hán-Việt | linh — không phổ biến trong tiếng Việt; dùng trong văn bản chuyên ngành ngư cụ cổ. | Mở khoá kiến thức | Biết 笭 mở khoá cụm 笭箵 — giỏ câu cá bằng tre, dụng cụ đánh bắt truyền thống.", "Tự nguyên_Xie": "Triện thư | 笭 là chữ thuộc bộ 竹 (tre), chỉ loại giỏ/lồng/rổ bằng tre. Gặp trong cụm 笭箵 (giỏ câu cá), 笭床 (giường tre). Wiktionary ghi rfdef nhưng âm mc/oc đầy đủ. Chưa có phân tích cấu tạo từ Wiktionary. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: linh tinh 笭箐)", "Hạng Tần Suất (Jun Da)": "7180.0", "Tần Suất % (Jun Da)": "99.9976656815", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笭", "Unihan_Traditional (Chữ Phồn thể)": "笭", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các vật dụng đan bằng tre nứa hoặc dùng trong từ ghép mô tả sự vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糷', '{"9000": "7181.0", "Chữ Trung Quốc": "糷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 26 | nét | 糷 | lạn | tượng hình | gạo nấu chín, cơm | 糷 thuộc bộ 米 (mễ — gạo), chỉ gạo nếp hoặc cơm đã nấu chín. Dữ liệu CHISE không cung cấp cây thành phần chi tiết. Chưa xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạn\": bộ 米 (gạo) — cơm LẠN nhừ, chín mềm đến mức nát. | Gương Hán-Việt | lạn — không phổ biến trong tiếng Việt; \"lạn\" gợi cái gì nhừ nát (giống 爛 lạn = thối rữa). | Mở khoá kiến thức | Biết 糷 mở khoá nhóm chữ bộ 米 chỉ các dạng lương thực chế biến trong văn ngôn.", "Tự nguyên_Xie": "糷 (obs-std) nghĩa là cơm đã nấu chín (cooked rice). Thuộc bộ 米 (gạo). Wiktionary ghi \"literary/obsolete: cooked rice\". Âm mc/oc đầy đủ. Chưa có phân tích cấu tạo. Chữ cổ, nay ít dùng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gạo nếp", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 蘭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米蘭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蘭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "糷", "Unihan_Traditional (Chữ Phồn thể)": "糷", "Pinyin_Xie": "làn", "Âm Hán Việt_Xie": "lạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ loại cơm nấu nát hoặc tính từ mô tả trạng thái nhão của lương thực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翉', '{"9000": "7182.0", "Chữ Trung Quốc": "翉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 11 | nét | 翉 | bổn | tượng hình | chưa rõ nghĩa; thuộc bộ 羽 | 翉 thuộc bộ 羽 (vũ — lông vũ). Dữ liệu CHISE không cung cấp cây thành phần. Wiktionary ghi rfdef (chưa định nghĩa). Chưa xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bổn\": bộ 羽 (lông vũ) — BỔN gốc của lông vũ, chưa rõ nghĩa chính xác. | Gương Hán-Việt | bổn — không xuất hiện trong từ điển Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 翉 giúp nhận dạng nhóm chữ bộ 羽 — các chữ liên quan đến lông vũ, cánh.", "Tự nguyên_Xie": "翉 thuộc bộ 羽 (lông vũ). Nghĩa cụ thể chưa được Wiktionary xác nhận (rfdef). Âm Quan Thoại pěn/běn, Quảng Đông pun2. Chưa có nguồn học thuật phân tích cấu tạo. Chữ cực hiếm. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hình ảnh", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "本 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰本羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "本", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翉", "Unihan_Traditional (Chữ Phồn thể)": "翉", "Pinyin_Xie": "běn", "Âm Hán Việt_Xie": "bổn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ chỉ hành động bay lên hoặc tính từ miêu tả tư thế bay của loài chim. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胵', '{"9000": "7183.0", "Chữ Trung Quốc": "胵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 胵 | xí | tượng hình | dạ dày loài chim | 胵 thuộc bộ 肉/⺼ (nhục — thịt/cơ thể), chỉ bộ phận nội tạng của loài chim. Dữ liệu CHISE không cung cấp cây thành phần. Chưa xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xí\": bộ ⺼ (thịt/nội tạng) — XÍ quách là phần trong cùng của bụng chim, tức mề. | Gương Hán-Việt | xí — không phổ biến trong tiếng Việt; \"mề\" là từ thuần Việt tương đương. | Mở khoá kiến thức | Biết 胵 mở khoá nhóm thuật ngữ giải phẫu cổ điển liên quan đến nội tạng gia cầm.", "Tự nguyên_Xie": "胵 là thuật ngữ cổ chỉ mề (gizzard) — dạ dày của loài chim. Thuộc bộ ⺼/肉 (thịt). Không có dữ liệu glyphOrigin từ Wiktionary. Chữ cực hiếm, dùng chủ yếu trong y học cổ và văn bản thú y. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dạ dày loài chim", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 至", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月至", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "至", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胵", "Unihan_Traditional (Chữ Phồn thể)": "胵", "Pinyin_Xie": "chī", "Âm Hán Việt_Xie": "si", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận tiêu hóa của loài chim và ít khi đứng độc lập trong văn nói. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芖', '{"9000": "7184.0", "Chữ Trung Quốc": "芖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 6 | nét | 芖 | chí | tượng hình | loài thực vật; chưa rõ nghĩa cụ thể | 芖 thuộc bộ 艸/⺿ (thảo — cỏ cây), chỉ một loài thực vật. Dữ liệu CHISE không cung cấp cây thành phần. Chưa xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chí\": bộ 艸 (cỏ) — cây CHÍ ẩn, ẩn mình trong cỏ, hiếm gặp. | Gương Hán-Việt | chí — không phổ biến trong từ vựng Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 芖 giúp nhận dạng nhóm chữ bộ 艸 — hàng nghìn tên cây cỏ trong Hán tự.", "Tự nguyên_Xie": "芖 thuộc bộ 艸 (cỏ), chỉ một loài thực vật không rõ. Wiktionary không có glyphOrigin. Chữ cực hiếm, nghĩa không được xác định rõ trong các tự điển chính thống. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "芖", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 大", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹大", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "大", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芖", "Unihan_Traditional (Chữ Phồn thể)": "芖", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "chí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là cổ tự của chữ chi, dùng làm danh từ chỉ loài cỏ thơm hoặc nấm quý. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛚', '{"9000": "7185.0", "Chữ Trung Quốc": "蛚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 蛚 | liệt | tượng hình | loài côn trùng; dế mèn | 蛚 thuộc bộ 虫 (trùng — côn trùng/sâu bọ). Dữ liệu CHISE không cung cấp cây thành phần chi tiết. Chỉ dùng trong cụm 蜻蛚 (dế mèn/ve sầu nhỏ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liệt\": bộ 虫 (sâu bọ) — côn trùng LIỆT oanh, kêu ran trong cụm 蜻蛚. | Gương Hán-Việt | liệt — không phổ biến trong tiếng Việt thông dụng. | Mở khoá kiến thức | Biết 蛚 mở khoá cụm 蜻蛚 — tên côn trùng cổ trong văn học Hán.", "Tự nguyên_Xie": "蛚 chỉ dùng trong cụm 蜻蛚 — tên một loài côn trùng (dế hoặc ve nhỏ). Thuộc bộ 虫 (côn trùng). Wiktionary ghi \"zh-only 蜻蛚\". Âm mc/oc đầy đủ. Không có phân tích cấu tạo. Chữ hiếm. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Cyrtoxiphus ritsemae", "Hạng Tần Suất (Jun Da)": "7185.0", "Tần Suất % (Jun Da)": "99.997686353", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蛚", "Unihan_Traditional (Chữ Phồn thể)": "蛚", "Pinyin_Xie": "liè", "Âm Hán Việt_Xie": "liệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn học cổ để chỉ một loài dế nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛯', '{"9000": "7186.0", "Chữ Trung Quốc": "蛯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 蛯 | lão | tượng hình | loài giáp xác; tôm (tiếng Nhật) | 蛯 thuộc bộ 虫 (trùng — côn trùng/sinh vật nhỏ). Dữ liệu CHISE không cung cấp cây thành phần. Chủ yếu dùng trong tiếng Nhật chỉ tôm (ebi). Không có glyphOrigin.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lão\": bộ 虫 (sinh vật nhỏ) — LÃO là con tôm già, cứng như giáp, ẩn dưới nước. | Gương Hán-Việt | lão — không dùng trong từ vựng Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 蛯 giúp nhận dạng chữ tôm trong văn bản Nhật-Hán (kanji ẩm thực).", "Tự nguyên_Xie": "蛯 là chữ dùng chủ yếu trong tiếng Nhật (kanji) chỉ tôm (えび / ebi). Thuộc bộ 虫. Không có glyphOrigin từ Wiktionary. Âm Quan Thoại lao. Rất hiếm trong tiếng Trung tiêu chuẩn. Chưa có nguồn học thuật phân tích cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 老", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫老", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "老", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛯", "Unihan_Traditional (Chữ Phồn thể)": "蛯", "Pinyin_Xie": "lao", "Âm Hán Việt_Xie": "lão", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Đây là chữ Hán do người Nhật tạo ra, dùng làm danh từ chỉ con tôm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜏', '{"9000": "7187.0", "Chữ Trung Quốc": "蜏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 蜏 | hữu | tượng hình | loài côn trùng; chỉ dùng trong cụm 朝蜏 | 蜏 thuộc bộ 虫 (trùng — côn trùng). Dữ liệu CHISE không cung cấp cây thành phần chi tiết. Chỉ dùng trong cụm 朝蜏.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hữu\": bộ 虫 (sâu bọ) — côn trùng HỮU bạn, sống thành đàn trong cụm 朝蜏. | Gương Hán-Việt | hữu — không phổ biến trong tiếng Việt. | Mở khoá kiến thức | Biết 蜏 giúp đọc cụm 朝蜏 trong văn bản cổ về côn trùng học.", "Tự nguyên_Xie": "蜏 chỉ dùng trong cụm 朝蜏 — tên một loài côn trùng cổ đại. Thuộc bộ 虫. Wiktionary ghi \"zh-only 朝蜏\". Âm yǒu có mc/oc đầy đủ. Không có phân tích cấu tạo. Chữ cực hiếm. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蜏", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 秀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫秀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜏", "Unihan_Traditional (Chữ Phồn thể)": "蜏", "Pinyin_Xie": "yǒu", "Âm Hán Việt_Xie": "hữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường xuất hiện trong các từ ghép cổ để chỉ các loài nhuyễn thể nhỏ ở biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('賲', '{"9000": "7188.0", "Chữ Trung Quốc": "賲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 16 | nét | 賲 | bảo | tượng hình | cảm giác ăn gạo sống; thuộc bộ 貝 | 賲 thuộc bộ 貝 (bối — vỏ sò/tiền tệ). Dữ liệu CHISE không cung cấp cây thành phần chi tiết. Chưa xác định hình thanh hay hội ý. Nghĩa rất đặc thù trong tiếng Mân Nam (Chương Châu).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bảo\": bộ 貝 (vỏ cứng) — BẢO tồn cái cứng; cơm chưa chín còn cứng lổn nhổn như vỏ sò. | Gương Hán-Việt | bảo — không phổ biến trong tiếng Việt; đây là từ phương ngữ Mân Nam. | Mở khoá kiến thức | Biết 賲 mở ra phương ngữ học Mân Nam — hệ thống chữ viết phương ngữ riêng của vùng Phúc Kiến, Đài Loan.", "Tự nguyên_Xie": "賲 là từ phương ngữ (Chương Châu Mân Nam/Hokkien) chỉ cảm giác khi ăn gạo nấu chưa chín hẳn — cảm giác lổn nhổn, sần sật. Wiktionary ghi cụ thể: \"having the feeling of eating half-cooked cereal\". Thuộc bộ 貝. Chưa có phân tích cấu tạo đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "賲", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "保 + 貝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱保貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "保", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "賲", "Unihan_Traditional (Chữ Phồn thể)": "賲", "Pinyin_Xie": "bǎo", "Âm Hán Việt_Xie": "bảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Dùng làm tính từ chỉ sự giàu có hoặc động từ chỉ việc tích lũy của cải. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钃', '{"9000": "7189.0", "Chữ Trung Quốc": "钃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 29 | nét | 钃 | chúc | tượng hình | cái cuốc, cái xẻng | 钃 thuộc bộ 钅/金 (kim — kim loại), chỉ dụng cụ kim loại. Dữ liệu CHISE không cung cấp cây thành phần chi tiết. Chưa xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chúc\": bộ 金 (kim loại) — CHÚC mừng mùa vụ bằng cái cuốc kim loại, xới đất trồng trọt. | Gương Hán-Việt | chúc — không phổ biến trong tiếng Việt; \"cuốc\" là từ thuần Việt tương đương. | Mở khoá kiến thức | Biết 钃 mở khoá nhóm dụng cụ nông nghiệp trong chữ Hán — nhóm chữ bộ 金 chỉ công cụ lao động.", "Tự nguyên_Xie": "钃 nghĩa là cái cuốc (hoe) — dụng cụ nông nghiệp bằng kim loại. Thuộc bộ 钅/金 (kim loại). Wiktionary xác nhận nghĩa \"hoe\" với âm zhú/shǔ. Chưa có phân tích cấu tạo đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kim khí", "Hạng Tần Suất (Jun Da)": "7189.0", "Tần Suất % (Jun Da)": "99.9976992726", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 屬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金屬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "钃", "Unihan_Traditional (Chữ Phồn thể)": "钃", "Pinyin_Xie": "shǔ", "Âm Hán Việt_Xie": "chúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ chung các loại dụng cụ bằng kim loại thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('餈', '{"9000": "7190.0", "Chữ Trung Quốc": "餈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 15 | nét | 餈 | tì | tượng hình | bánh gạo nếp; bánh chưng | 餈 thuộc bộ 食 (thực — thức ăn), chỉ loại bánh làm từ gạo nếp. Dữ liệu CHISE không cung cấp cây thành phần chi tiết. Seal script có trong dữ liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tì\": bộ 食 (ăn) — bánh TÌ tì bằng gạo nếp, dẻo thơm ĂN mãi không chán. | Gương Hán-Việt | tì — ít dùng trong tiếng Việt; \"bánh giày\", \"bánh nếp\" là tương đương. | Mở khoá kiến thức | Biết 餈 mở khoá nhóm thực phẩm Hán văn làm từ gạo nếp: 餈粑 (bánh nếp nướng phương Nam).", "Tự nguyên_Xie": "Triện thư | 餈 chỉ bánh làm từ gạo nếp giã (rice cake, mochi-style). Thuộc bộ 食 (thức ăn). Seal script có trong dữ liệu etymology. Wiktionary không có glyphOrigin nhưng chữ có âm cí với mc/oc. Tương đương từ thuần Việt \"bánh giày\" hoặc \"bánh nếp\". | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Ci", "Hạng Tần Suất (Jun Da)": "7190.0", "Tần Suất % (Jun Da)": "99.9977018565", "GavinGrover_Once (Chiết tự trực tiếp)": "次 + 食", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱次食", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "次", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "食", "Unihan_Simplified (Chữ Giản thể)": "餈", "Unihan_Traditional (Chữ Phồn thể)": "餈", "Pinyin_Xie": "cí", "Âm Hán Việt_Xie": "tì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ các loại bánh làm từ bột gạo nếp giã nhuyễn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馧', '{"9000": "7191.0", "Chữ Trung Quốc": "馧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 香 | Số nét | 18 | nét | 馧 | uẩn | tượng hình | hương thơm; thuộc bộ 香 | 馧 thuộc bộ 香 (hương — hương thơm), chỉ mùi hương. Dữ liệu CHISE không cung cấp cây thành phần. Wiktionary ghi rfdef. Chưa xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uẩn\": bộ 香 (hương) — UẨN chứa hương, hương thơm UẨN tích trong không gian. | Gương Hán-Việt | uẩn — không phổ biến trong tiếng Việt; \"uẩn\" thường gặp trong 含蓄 (hàm uẩn — ẩn chứa). | Mở khoá kiến thức | Biết 馧 giúp nhận dạng nhóm chữ bộ 香 — các chữ chỉ mùi hương trong Hán tự.", "Tự nguyên_Xie": "馧 thuộc bộ 香 (hương thơm). Wiktionary ghi rfdef, âm yūn/wò. Nghĩa liên quan đến hương thơm nhưng chưa được xác định rõ. Chưa có nguồn học thuật phân tích cấu tạo. Chữ cực hiếm. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Ngon", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "香 + 昷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰香昷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "香", "Unihan_Simplified (Chữ Giản thể)": "馧", "Unihan_Traditional (Chữ Phồn thể)": "馧", "Pinyin_Xie": "yūn", "Âm Hán Việt_Xie": "uẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ hoặc tính từ trong văn thơ để tả hương thơm đậm đà. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麤', '{"9000": "7192.0", "Chữ Trung Quốc": "麤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 33 | nét | 鹿 | lộc | tượng hình | con nai/hươu | 鹿 | lộc | tượng hình | con nai/hươu | 鹿 | lộc | tượng hình | con nai/hươu | 麤 = 鹿 × 3 (Lộc — hươu/nai). Hội ý (zh-etym-triple): ba con hươu chạy nhanh = sự vội vã, thô kệch, mạnh bạo. Nghĩa gốc là \"chạy nhanh\"; sau chuyển sang \"thô\", \"thô lỗ\", \"lớn thô\". Đây là cách viết cổ của 粗 (thô).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thô\": ba con 鹿 (hươu) cùng chạy loạn — đàn nai THÔ kệch xô nhau, không tinh tế. | Gương Hán-Việt | thô — dùng trong văn ngôn Hán-Việt: \"thô lỗ\" (麤鹵), \"thô thiển\" (麤淺). | Mở khoá kiến thức | Biết 麤 mở khoá từ gốc chữ 粗 (thô) — hiểu tại sao 粗 nghĩa là thô qua hình ảnh ba con hươu chạy loạn.", "Tự nguyên_Xie": "Giáp cốt văn | 麤 là chữ hội ý gồm ba chữ 鹿 (lộc — hươu): ba con hươu cùng chạy gợi ý sự hỗn loạn, vội vã, thô bạo. Nghĩa gốc là \"chạy nhanh\" (to move fast); sau phát triển thành \"thô\" (coarse, rough). Là cách viết cổ của 粗 (thô). Oracle bone script có trong dữ liệu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dày", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱鹿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "麤", "Unihan_Traditional (Chữ Phồn thể)": "麤", "Pinyin_Xie": "cū", "Âm Hán Việt_Xie": "thô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ đứng trước danh từ để miêu tả tính chất thô sơ hoặc không mịn màng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼶', '{"9000": "7193.0", "Chữ Trung Quốc": "鼶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼠 | Số nét | 23 | nét | 鼶 | tư | tượng hình | chuột đồng lớn; chồn xiberia | 鼶 thuộc bộ 鼠 (thử — chuột), chỉ loài gặm nhấm hoặc động vật nhỏ. Dữ liệu CHISE không cung cấp cây thành phần chi tiết. Chưa xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": bộ 鼠 (chuột) — TƯ là con chuột đồng to lớn, tư thế hiên ngang. | Gương Hán-Việt | tư — không phổ biến trong tiếng Việt; \"chồn\" hay \"chuột đồng\" là tương đương. | Mở khoá kiến thức | Biết 鼶 giúp đọc các bộ sách cổ về động vật học và sách thuốc Đông y dùng động vật.", "Tự nguyên_Xie": "鼶 là tên cổ chỉ hai loài: (1) chuột đồng lớn (large field mouse), (2) chồn Siberia (Siberian weasel). Thuộc bộ 鼠 (chuột). Wiktionary ghi obs-std. Âm sī hoặc tí, mc/oc đầy đủ. Chưa có phân tích cấu tạo. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bạn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鼠 + 虒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鼠虒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼠", "Unihan_Simplified (Chữ Giản thể)": "鼶", "Unihan_Traditional (Chữ Phồn thể)": "鼶", "Pinyin_Xie": "sī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài gặm nhấm cổ, thường làm chủ ngữ hoặc tân ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臓', '{"9000": "7194.0", "Chữ Trung Quốc": "臓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 18 | nét | ⺼ | nhục | biểu nghĩa | thịt, cơ thể | 蔵 | tàng | biểu âm | cất giữ (dạng Nhật) | 臓 = ⺼ (Nhục, biểu nghĩa: thịt/cơ thể) + 蔵 (dạng Nhật của 藏, biểu âm). Chữ hình thanh (ls=psc), là dạng shinjitai Nhật Bản của 臟. Chỉ nội tạng — bộ phận bên trong cơ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tạng\": ⺼ (thịt) + 蔵 (cất giữ) — TẠNG phủ là thứ được CẤT GIỮ bên trong thịt cơ thể. | Gương Hán-Việt | tạng — dùng trong Hán-Việt: 五臟 (ngũ tạng), 臟腑 (tạng phủ), 心臟 (tâm tạng — tim). | Mở khoá kiến thức | Biết 臓 (và 臟) mở khoá hệ thuật ngữ Đông y: 五臟 (ngũ tạng: tâm can tỳ phế thận), 六腑 (lục phủ).", "Tự nguyên_Xie": "臓 là shinjitai (tân tự thể) Nhật Bản của 臟 (tạng — nội tạng). Cấu tạo: ⺼ (nhục — thịt/cơ thể) biểu nghĩa + 蔵 (dạng Nhật của 藏) biểu âm. Nghĩa: nội tạng (entrails, internal organs). Wiktionary ghi rõ nguồn gốc Nhật: \"Japanese shinjitai\". Dùng trong 心臓 (tim), 内臓 (nội tạng). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem \"脏\"", "Hạng Tần Suất (Jun Da)": "7194.0", "Tần Suất % (Jun Da)": "99.9977147761", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 蔵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月蔵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蔵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臓", "Unihan_Traditional (Chữ Phồn thể)": "臓", "Pinyin_Xie": "zàng", "Âm Hán Việt_Xie": "tạng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ bộ phận cơ thể để cấu tạo nên tên gọi các cơ quan nội tạng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螣', '{"9000": "7195.0", "Chữ Trung Quốc": "螣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 螣 | đằng | tượng hình | rắn bay; con rồng bay (cổ ngữ) | 螣 thuộc bộ 虫 (trùng — côn trùng/sinh vật), chỉ loài vật thần thoại. Dữ liệu CHISE không cung cấp cây thành phần. Chỉ dùng trong cụm 螣蛇 (đằng xà — rắn bay).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đằng\": bộ 虫 (sinh vật) — rắn ĐẰNG vân, bay trên mây như rồng trong cụm 螣蛇. | Gương Hán-Việt | đằng — trong văn học cổ điển Hán-Việt: 螣蛇 (đằng xà) thường đối với 龍 (rồng) trong văn thơ. | Mở khoá kiến thức | Biết 螣 mở khoá cụm 螣蛇 — hình ảnh thần thoại trong thơ Tào Tháo và văn học cổ điển.", "Tự nguyên_Xie": "螣 chỉ dùng trong cụm 螣蛇 (đằng xà) — một loài rắn thần thoại có thể bay. Thuộc bộ 虫. Wiktionary ghi {{Han etym}} nhưng không có phân tích chi tiết. Chữ cực hiếm ngoài cụm này. Gặp trong thơ Tào Tháo: \"螣蛇乘霧，終為土灰\". | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đằng xà 螣蛇)", "Hạng Tần Suất (Jun Da)": "7195.0", "Tần Suất % (Jun Da)": "99.9977276958", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 䖭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月䖭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䖭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "螣", "Unihan_Traditional (Chữ Phồn thể)": "螣", "Pinyin_Xie": "tè", "Âm Hán Việt_Xie": "đằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu làm danh từ trong cụm từ cố định chỉ loài rắn thần huyền thoại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铽', '{"9000": "7196.0", "Chữ Trung Quốc": "铽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 金 | kim | biểu nghĩa | kim loại | 忒 | thắc | biểu âm | quá, thái quá | 铽 = 金 (Kim, biểu nghĩa: kim loại) + 忒 (Thắc, biểu âm). Chữ hình thanh (ls=psc): 金 cho nghĩa (nguyên tố kim loại), 忒 cho âm. Tên phiên dịch của nguyên tố Terbium (Tb, số 65).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thắc\": 金 (kim loại) + 忒 (thắc — thái quá) — đất hiếm THẮC mắc, quý hiếm đến mức bí ẩn. | Gương Hán-Việt | thắc — ít dùng trong tiếng Việt; trong hóa học Việt Nam gọi là \"Terbium\" hoặc \"Tb\". | Mở khoá kiến thức | Biết 铽 mở khoá nhóm tên nguyên tố đất hiếm trong Hán tự — tất cả đều dùng bộ 金.", "Tự nguyên_Xie": "铽 là chữ tạo ra để phiên dịch tên nguyên tố Terbium (Tb, số nguyên tử 65) sang tiếng Trung. Chữ hình thanh: 金 (kim loại) biểu nghĩa, 忒 (thắc) biểu âm. Terbium được đặt tên theo làng Ytterby, Thuỵ Điển. Là đất hiếm (rare earth element). Wiktionary xác nhận cấu tạo psc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố tecbi, Tb", "Hạng Tần Suất (Jun Da)": "7196.0", "Tần Suất % (Jun Da)": "99.9977302797", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 忒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅忒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "忒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铽", "Unihan_Traditional (Chữ Phồn thể)": "鋱", "Pinyin_Xie": "tè", "Âm Hán Việt_Xie": "thắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ nguyên tố hóa học, thường đứng độc lập hoặc trong các thuật ngữ khoa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('竝', '{"9000": "7197.0", "Chữ Trung Quốc": "竝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 立 | Số nét | 10 | nét | 立 | lập | tượng hình | đứng, người đứng | 立 | lập | tượng hình | đứng, người đứng | 竝 = 立 × 2 (Lập — người đứng). Hội ý (zh-etym-double): hai người đứng cạnh nhau = song song, cùng nhau. Là cách viết cổ của 並 (tịnh). Bronze script, seal script đều có trong dữ liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tịnh\": hai 立 (người đứng) sát nhau — TỊNH như hai người đứng CẠNH TỊNH vai, song hành. | Gương Hán-Việt | tịnh — dùng trong Hán-Việt: 並列 (tịnh liệt — song song), 並行 (tịnh hành — song hành), 並排 (sắp hàng cạnh nhau). | Mở khoá kiến thức | Biết 竝 (và 並) mở khoá: 並列 (song song), 並行 (đồng thời), 並排 (sát cạnh), 並非 (chẳng phải).", "Tự nguyên_Xie": "Kim văn | Triện thư | Lục thư thông | 竝 là chữ hội ý gồm hai chữ 立 (lập — đứng): hai người đứng cạnh nhau = song song, bên cạnh nhau. Là cách viết cổ/biến thể của 並 (tịnh/bính — song song, cùng, thêm nữa). Bronze script và seal script có trong dữ liệu. Wiktionary xác nhận cấu tạo. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bằng nhau, ngang nhau, đều", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "立", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴立", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "竝", "Unihan_Traditional (Chữ Phồn thể)": "竝", "Pinyin_Xie": "bìng", "Âm Hán Việt_Xie": "tịnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Động từ | 动词 | Liên từ | 连词 | Thường làm phó từ đứng trước động từ để chỉ hai hành động diễn ra song song hoặc cùng lúc. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Liên từ | 连词 | Nối từ, cụm từ hoặc mệnh đề: 和, 但是, 因为…所以…. Lưu ý 和 chỉ nối danh từ, không nối hai câu như ''và'' tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粊', '{"9000": "7198.0", "Chữ Trung Quốc": "粊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 10 | nét | 粊 | bí | tượng hình | gạo xấu, gạo vỡ | 粊 thuộc bộ 米 (mễ — gạo), chỉ loại gạo kém chất lượng. Dữ liệu CHISE không cung cấp cây thành phần chi tiết. Chưa xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": bộ 米 (gạo) — gạo BÍ hỏng, vỡ vụn, không dùng được. | Gương Hán-Việt | bí — không phổ biến trong tiếng Việt; \"gạo xấu\" là tương đương. | Mở khoá kiến thức | Biết 粊 giúp đọc văn bản cổ về lương thực và địa danh Sơn Đông thời Xuân Thu.", "Tự nguyên_Xie": "粊 có hai nghĩa: (1) gạo xấu/gạo vỡ (bad rice), (2) tên địa danh cổ thời Xuân Thu ở Khúc Phụ, Sơn Đông. Thuộc bộ 米 (gạo). Wiktionary xác nhận cả hai nghĩa. Chưa có phân tích cấu tạo chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "粊", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "比 + 米", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱比米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "米", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "比", "Unihan_Simplified (Chữ Giản thể)": "粊", "Unihan_Traditional (Chữ Phồn thể)": "粊", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ loại lương thực kém chất lượng, thường xuất hiện trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絺', '{"9000": "7199.0", "Chữ Trung Quốc": "絺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 絺 | si | tượng hình | vải lanh mịn | 絺 thuộc bộ 糸 (mịch — tơ sợi), chỉ loại vải lanh mịn. Seal script có trong dữ liệu. Dữ liệu CHISE không cung cấp cây thành phần chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"si\": bộ 糸 (tơ) — vải SI lanh mịn mà mát, che thân ngày hè nóng bức. | Gương Hán-Việt | si — không phổ biến trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 絺 mở khoá cụm 絺綌 — từ đôi chỉ vải lanh (絺 = mịn, 綌 = thô) trong kinh sách cổ.", "Tự nguyên_Xie": "Triện thư | 絺 là loại vải lanh mịn (fine linen cloth) — quý giá, dùng làm trang phục mùa hè của giới quý tộc. Thuộc bộ 糸 (tơ). Seal script có trong dữ liệu. Wiktionary không có glyphOrigin chi tiết nhưng có âm mc/oc đầy đủ. Gặp trong cụm 絺綌 — chỉ hai loại vải lanh (mịn và thô). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lanh", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 希", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹希", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "希", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "𫄨", "Unihan_Traditional (Chữ Phồn thể)": "絺", "Pinyin_Xie": "chī", "Âm Hán Việt_Xie": "hi, hy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn cổ để chỉ loại vải thô mịn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絿', '{"9000": "7200.0", "Chữ Trung Quốc": "絿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 糸 | mịch | biểu nghĩa | tơ sợi, siết chặt | 求 | cầu | biểu âm | cầu xin, tìm kiếm | 絿 = 糸 (Mịch, biểu nghĩa: tơ sợi) + 求 (Cầu, biểu âm). Chữ hình thanh (ls=psc): 糸 gợi sự siết chặt, gấp gáp; 求 cho âm. Nghĩa: gấp gáp, bức bách.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cầu\": 糸 (siết chặt) + 求 (cầu khẩn) — CẦU như sợi dây siết chặt, gấp gáp bức bách. | Gương Hán-Việt | cầu — không phổ biến theo nghĩa này; 求 (cầu — tìm kiếm) phổ biến hơn. | Mở khoá kiến thức | Biết 絿 giúp đọc văn bản cổ điển mô tả tính cách gấp gáp, nóng vội.", "Tự nguyên_Xie": "絿 là chữ hình thanh: 糸 (mịch — sợi tơ) biểu nghĩa, 求 (cầu) biểu âm. Nghĩa: gấp gáp, vội vã, bức bách. Wiktionary ghi rfdef nhưng xác nhận cấu tạo psc. Âm mc/oc đầy đủ. Chữ hiếm dùng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gấp gáp; con, nhỏ, bé", "Hạng Tần Suất (Jun Da)": "7200.0", "Tần Suất % (Jun Da)": "99.9977457832", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 求", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹求", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "求", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "絿", "Unihan_Traditional (Chữ Phồn thể)": "絿", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "cầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Dùng làm tính từ bổ nghĩa cho hành động hoặc trạng thái khẩn trương. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脦', '{"9000": "7201.0", "Chữ Trung Quốc": "脦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 脦 | đức | tượng hình | bẩn thỉu, lôi thôi | 脦 thuộc bộ 肉/⺼ (nhục — thịt/cơ thể). Không có dữ liệu glyphOrigin. Chủ yếu dùng trong phương ngữ Quan Thoại (âm nhẹ \"de\") để mô tả trạng thái quần áo lôi thôi, bẩn thỉu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đức\": bộ ⺼ (cơ thể) — người ĐỨC hạnh nhìn vào thấy ngay: quần áo lôi thôi, cơ thể bẩn thỉu. | Gương Hán-Việt | đức — không dùng theo nghĩa này trong tiếng Việt; âm đức thường liên quan đến 德 (đức hạnh). | Mở khoá kiến thức | Biết 脦 giúp đọc mô tả nhân vật trong văn học và hội thoại phương ngữ Bắc Kinh.", "Tự nguyên_Xie": "脦 là từ phương ngữ Bắc Kinh/Quan Thoại mô tả người ăn mặc lôi thôi, bẩn thỉu (slovenly, unkempt). Âm \"de\" — trung tính. Thuộc bộ ⺼ (thịt). Không có glyphOrigin trong Wiktionary. Chưa có nguồn học thuật phân tích cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bẩn thỉu; lôi thôi lếch thếch (quần áo)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 忒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月忒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "忒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脦", "Unihan_Traditional (Chữ Phồn thể)": "脦", "Pinyin_Xie": "de", "Âm Hán Việt_Xie": "đế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng trong khẩu ngữ kết hợp thành từ láy đức thế để tả vẻ ngoài luộm thuộm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臇', '{"9000": "7202.0", "Chữ Trung Quốc": "臇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 16 | nét | 臇 | quyển | tượng hình | chữ độc thể bộ 肉; nghĩa béo mập hoặc món hầm cá | 臇 là chữ độc thể thuộc bộ 肉 (nhục, thịt). Wiktionary chỉ ghi {{Han etym}} không có phân tích cụ thể. Chưa xác định được cấu trúc hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyển\": chữ bộ 肉 (thịt) — hình dung miếng thịt cuộn tròn béo mập. | Gương Hán-Việt | quyển trong nghĩa béo mập, dùng trong văn ngôn cổ | Mở khoá kiến thức | Biết 臇 mở khoá nhóm chữ bộ 肉 chỉ sắc thái béo tốt trong văn ngôn Hán cổ.", "Tự nguyên_Xie": "臇 thuộc bộ 肉 (nhục, thịt), mang nghĩa béo tốt hoặc món hầm cá. Wiktionary không có phân tích nguyên tự cụ thể. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "béo, mập", "Hạng Tần Suất (Jun Da)": "7202.0", "Tần Suất % (Jun Da)": "99.997753535", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 雋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月雋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臇", "Unihan_Traditional (Chữ Phồn thể)": "臇", "Pinyin_Xie": "juǎn", "Âm Hán Việt_Xie": "tuyến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Dùng làm danh từ chỉ món canh bổ dưỡng hoặc tính từ tả vị béo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臋', '{"9000": "7203.0", "Chữ Trung Quốc": "臋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 19 | nét | 臋 | đồn | tượng hình | chữ độc thể bộ 肉; nghĩa gần với 臀 (mông), chỉ có trong chữ cổ | 臋 là chữ độc thể thuộc bộ 肉 (nhục, thịt). Wiktionary không có phân tích nguyên tự. Chỉ còn dạng Lục thư thông (明 đại), chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồn\": bộ 肉 (thịt) — liên tưởng tới phần thịt mông (臀/đồn) trong văn ngôn cổ; hình dạng và âm gần giống 臀. | Gương Hán-Việt | đồn trong nghĩa mông, so sánh với 臀 (cũng đọc đồn) | Mở khoá kiến thức | Biết 臋 giúp nhận diện nhóm chữ bộ 肉 chỉ bộ phận cơ thể trong văn bản cổ.", "Tự nguyên_Xie": "Lục thư thông | 臋 không có phân tích nguyên tự từ Wiktionary. Chỉ có dạng Lục thư thông (明 đại) lưu lại — chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "苋", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "殿 + 肉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱殿肉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "殿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "肉", "Unihan_Simplified (Chữ Giản thể)": "臋", "Unihan_Traditional (Chữ Phồn thể)": "臋", "Pinyin_Xie": "tún", "Âm Hán Việt_Xie": "đồn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là biến thể của chữ đồn thường làm danh từ chỉ bộ phận cơ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葍', '{"9000": "7204.0", "Chữ Trung Quốc": "葍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葍 | phức | tượng hình | chữ độc thể bộ 艸; chỉ loài cỏ đồng ruộng ăn được | 葍 là chữ độc thể thuộc bộ 艸 (thảo, cỏ). Wiktionary không có phân tích cấu trúc hình thanh hay hội ý. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phức\": bộ 艸 (cỏ) — hình dung loài cỏ phục dưới đất, nhổ lên ăn được, nghe âm \"fú\" như chữ 伏 (phục/nằm xuống). | Gương Hán-Việt | phức trong nghĩa loài cỏ ăn được trong văn ngôn | Mở khoá kiến thức | Biết 葍 mở khoá nhóm chữ bộ 艸 chỉ các loài thực vật đồng ruộng trong văn ngôn Hán cổ.", "Tự nguyên_Xie": "葍 thuộc bộ 艸 (thảo, cỏ), chỉ loài cỏ mọc nhiều ở đồng ruộng, phần thân dưới đất có thể hấp làm thức ăn, vị ngọt. Wiktionary không có phân tích nguyên tự. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại cỏ, mọc nhiều ở đồng ruộng, phần thân dưới mặt đất có thể hấp làm thức ăn, có vị ngọt)", "Hạng Tần Suất (Jun Da)": "7204.0", "Tần Suất % (Jun Da)": "99.9977587029", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 畐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹畐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葍", "Unihan_Traditional (Chữ Phồn thể)": "葍", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong văn học cổ để chỉ một loài thực vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葞', '{"9000": "7205.0", "Chữ Trung Quốc": "葞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葞 | mễ | tượng hình | chữ độc thể bộ 艸; nghĩa ngăn xếp hoặc một loại thực vật | 葞 là chữ độc thể thuộc bộ 艸 (thảo, cỏ). Wiktionary ghi {{Han etym}} nhưng không có phân tích hình thanh hay hội ý cụ thể. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mễ\": bộ 艸 (cỏ) — liên tưởng cỏ xếp chồng như hạt gạo (米/mễ) phơi khô trên sân. | Gương Hán-Việt | mễ trong nghĩa gạo (米), nhưng 葞 là chữ thực vật riêng biệt | Mở khoá kiến thức | Biết 葞 giúp nhận diện nhóm chữ bộ 艸 chỉ thực vật hiếm trong cổ văn.", "Tự nguyên_Xie": "葞 thuộc bộ 艸 (thảo, cỏ), nghĩa ngăn xếp hoặc chỉ một loại thực vật. Wiktionary không có phân tích nguyên tự. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngăn xếp", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 弭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹弭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葞", "Unihan_Traditional (Chữ Phồn thể)": "葞", "Pinyin_Xie": "mǐ", "Âm Hán Việt_Xie": "mễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong các tài liệu y học cổ truyền để chỉ tên cây thuốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葻', '{"9000": "7206.0", "Chữ Trung Quốc": "葻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葻 | bông | tượng hình | chữ độc thể bộ 艸; nghĩa chưa xác định rõ trong văn ngôn | 葻 là chữ độc thể thuộc bộ 艸 (thảo, cỏ). Wiktionary ghi {{Han etym}} nhưng không có phân tích hình thanh hay hội ý. Chưa có nguồn học thuật về cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bông\": bộ 艸 (cỏ) — loài cỏ nhẹ bông bay, âm \"lán\" gợi sóng nước (澜/lan) giữa đồng cỏ. | Gương Hán-Việt | bông trong nghĩa bông hoa, lông bông, bông đùa trong tiếng Việt | Mở khoá kiến thức | Biết 葻 giúp nhận diện nhóm chữ bộ 艸 trong từ điển Hán-Việt cổ.", "Tự nguyên_Xie": "葻 thuộc bộ 艸 (thảo, cỏ), đọc lán trong tiếng Quan Thoại. Wiktionary không có phân tích nguyên tự cụ thể. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bông; như \"bông hoa; lông bông; bông đùa\" (vhn) boong; như \"tiếng chuông boong boong\" (btcn) buông; như \"buông lời; buông thả; buông tuồng\" (btcn) bung; như \"nổ bung; bung ngô\" (gdhn) von; như \"chon von\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 風", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹風", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "風", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葻", "Unihan_Traditional (Chữ Phồn thể)": "葻", "Pinyin_Xie": "lán", "Âm Hán Việt_Xie": "lam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ hoặc tính từ trong thơ ca cổ để tả cảnh cỏ cây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藙', '{"9000": "7207.0", "Chữ Trung Quốc": "藙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 藙 | nghị | tượng hình | chữ độc thể bộ 艸; chỉ loài cây Zanthoxylum ailanthoides (sơn tiêu) | 藙 là chữ độc thể thuộc bộ 艸 (thảo, cỏ). Wiktionary ghi {{Han etym}} nhưng không có phân tích hình thanh hay hội ý. Chỉ dùng để chỉ loài cây Zanthoxylum ailanthoides.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghị\": bộ 艸 (cỏ) — loài cây có gai như con kiến (蟻/nghị) bò trên cành, dùng làm gia vị. | Gương Hán-Việt | nghị trong nghĩa loài cây gia vị cổ, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 藙 giúp nhận diện nhóm chữ bộ 艸 chỉ cây gia vị và dược liệu trong bản thảo Hán cổ.", "Tự nguyên_Xie": "藙 thuộc bộ 艸 (thảo, cỏ), chỉ loài cây Zanthoxylum ailanthoides (một loài sơn tiêu). Wiktionary không có phân tích nguyên tự cụ thể. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Zanthoxylum ailanthoides", "Hạng Tần Suất (Jun Da)": "7207.0", "Tần Suất % (Jun Da)": "99.9977690386", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 毅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹毅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藙", "Unihan_Traditional (Chữ Phồn thể)": "藙", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "bội", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ chỉ một loài cây thuộc họ cam quýt, thường dùng trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜔', '{"9000": "7208.0", "Chữ Trung Quốc": "蜔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 虫 | trùng | biểu nghĩa | côn trùng, sinh vật nhỏ | 甸 | điện | biểu âm | 蜔 = 虫 (Trùng, biểu nghĩa: côn trùng/sinh vật nhỏ) + 甸 (Điện, biểu âm); chữ hình thanh. Phần 虫 cho biết liên quan tới loài vật nhỏ, phần 甸 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điện\": 虫 (sinh vật) + 甸 (điện, âm) — con ốc sáng lấp lánh như đèn điện khảm trên đồ vật. | Gương Hán-Việt | điện trong 螺蜔 (ốc khảm), ít dùng riêng lẻ trong tiếng Việt | Mở khoá kiến thức | Biết 蜔 mở khoá thuật ngữ nghề thủ công khảm ốc xà cừ trong văn ngôn Hán cổ.", "Tự nguyên_Xie": "蜔 là chữ hình thanh: 虫 (trùng, biểu nghĩa côn trùng) + 甸 (điện, biểu âm). Chỉ dùng trong 螺蜔, tên một loài ốc hoặc vật trang trí khảm ốc. Wiktionary xác nhận cấu trúc psc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Thục", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 甸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫甸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜔", "Unihan_Traditional (Chữ Phồn thể)": "蜔", "Pinyin_Xie": "diàn", "Âm Hán Việt_Xie": "điện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ vỏ ốc dùng để khảm hoặc đồ vật được khảm xà cừ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螕', '{"9000": "7209.0", "Chữ Trung Quốc": "螕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 螕 | bí | tượng hình | chữ độc thể bộ 虫; chỉ con ve, bọ ký sinh | 螕 là chữ độc thể thuộc bộ 虫 (trùng, côn trùng). Wiktionary ghi {{Han etym}} nhưng không có phân tích cấu trúc rõ ràng. Chưa có nguồn học thuật về cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": bộ 虫 (côn trùng) — con bọ bí ẩn bám chặt trên da trâu bò như bí mật không rời. | Gương Hán-Việt | bí trong nghĩa con ve bọ ký sinh, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 螕 giúp nhận diện nhóm chữ bộ 虫 chỉ côn trùng ký sinh trong văn bản nông nghiệp cổ.", "Tự nguyên_Xie": "螕 thuộc bộ 虫 (trùng, côn trùng), chỉ con ve hoặc bọ ký sinh trên gia súc. Wiktionary không có phân tích nguyên tự cụ thể. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蕕", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "螕", "Unihan_Traditional (Chữ Phồn thể)": "螕", "Pinyin_Xie": "bī", "Âm Hán Việt_Xie": "bí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ chỉ các loài ký sinh trùng nhỏ như ve hoặc bét. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觼', '{"9000": "7210.0", "Chữ Trung Quốc": "觼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 角 | Số nét | 21 | nét | 觼 | quyết | tượng hình | chữ độc thể bộ 角; chỉ móc khóa có lưỡi gà hoặc ổ khóa hòm rương | 觼 là chữ độc thể thuộc bộ 角 (giác, sừng). Wiktionary ghi {{Han etym}} nhưng không có phân tích hình thanh hay hội ý. Chưa có nguồn học thuật về cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyết\": bộ 角 (sừng) — chiếc móc khóa làm từ sừng, quyết định đóng mở hòm rương. | Gương Hán-Việt | quyết trong nghĩa chiếc khóa sừng, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 觼 mở khoá nhóm từ đồ vật cổ đại làm từ sừng hoặc ngà trong văn ngôn Hán.", "Tự nguyên_Xie": "觼 thuộc bộ 角 (giác, sừng), chỉ móc khóa có lưỡi gà hoặc ổ khóa hòm rương. Xưa làm bằng sừng hoặc ngà. Wiktionary không có phân tích nguyên tự cụ thể. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái vòng khoá có lưỡi gà; ổ khóa hòm, rương", "Hạng Tần Suất (Jun Da)": "7210.0", "Tần Suất % (Jun Da)": "99.9977819582", "GavinGrover_Once (Chiết tự trực tiếp)": "角 + 夐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰角夐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "角", "Unihan_Simplified (Chữ Giản thể)": "觼", "Unihan_Traditional (Chữ Phồn thể)": "觼", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cái khóa thắt lưng hoặc khóa quai mũ thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觿', '{"9000": "7211.0", "Chữ Trung Quốc": "觿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 角 | Số nét | 25 | nét | 角 | giác | biểu nghĩa | sừng | 巂 | biểu âm | 觿 = 角 (Giác, biểu nghĩa: sừng) + 巂 (biểu âm, không có Hán-Việt thông dụng); chữ hình thanh. Phần 角 cho biết vật dụng làm từ sừng/ngà, phần 巂 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huề\": 角 (sừng) + 巂 (âm) — chiếc dùi sừng nhọn dùng gỡ nút thắt, huề nhau không ai thắng ai. | Gương Hán-Việt | huề trong 觿年 (tuổi thơ, lúc còn đeo 觿), ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 觿 mở khoá nhóm từ đồ vật nghi lễ và trang sức ngọc trong văn học Hán cổ điển.", "Tự nguyên_Xie": "Tiểu triện | 觿 là chữ hình thanh: 角 (giác, biểu nghĩa sừng) + 巂 (biểu âm). Chỉ dụng cụ gỡ nút (fid/bodkin) ban đầu làm bằng xương hoặc ngà dùng để gỡ dây thắt, về sau làm bằng ngọc dùng làm đồ trang sức đeo người. Wiktionary xác nhận cấu trúc psc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái rẽ tóc bằng ngà voi", "Hạng Tần Suất (Jun Da)": "7211.0", "Tần Suất % (Jun Da)": "99.9977845421", "GavinGrover_Once (Chiết tự trực tiếp)": "角 + 巂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰角巂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "角", "Unihan_Simplified (Chữ Giản thể)": "觿", "Unihan_Traditional (Chữ Phồn thể)": "觿", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "huề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ dụng cụ bằng sừng hoặc ngà dùng để cởi nút thắt thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('諝', '{"9000": "7212.0", "Chữ Trung Quốc": "諝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 16 | nét | 諝 | tư | tượng hình | chữ độc thể bộ 言; nghĩa trí tuệ, năng lực phán đoán | 諝 là chữ thuộc bộ 言 (ngôn, lời nói). Wiktionary ghi {{Han etym}} nhưng không có phân tích hình thanh hay hội ý cụ thể. Chưa có nguồn học thuật về cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": bộ 言 (lời nói) — lời nói thể hiện tư lực thông minh, mưu lược của người có chí khí. | Gương Hán-Việt | tư trong 才諝 (tài trí), 智諝 (trí tuệ sáng suốt), ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 諝 mở khoá nhóm từ ca ngợi tài trí mưu lược trong văn học và sử liệu cổ.", "Tự nguyên_Xie": "Tiểu triện | 諝 thuộc bộ 言 (ngôn, lời nói), nghĩa tri thức, tài năng phán đoán, hoặc mưu mô. Wiktionary không có phân tích nguyên tự cụ thể. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "谞", "Hạng Tần Suất (Jun Da)": "6522.0", "Tần Suất % (Jun Da)": "99.9933345053", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 胥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言胥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "谞", "Unihan_Traditional (Chữ Phồn thể)": "諝", "Pinyin_Xie": "xū", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ tài trí hoặc tính từ chỉ sự khôn khéo, mưu mẹo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趧', '{"9000": "7213.0", "Chữ Trung Quốc": "趧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 16 | nét | 趧 | đề | tượng hình | chữ độc thể bộ 走; nghĩa chưa rõ, có thể liên quan tới dáng đi | 趧 là chữ độc thể thuộc bộ 走 (tẩu, chạy/đi). Wiktionary ghi {{Han etym}} nhưng không có phân tích cụ thể. Chưa có nguồn học thuật về cấu tạo hay nghĩa chính xác.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đề\": bộ 走 (đi/chạy) — bước đi đề nhẹ như chân đề lên đất, âm tí giống chữ 踢 (đá). | Gương Hán-Việt | đề trong nghĩa bước đi nhẹ nhàng, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 趧 giúp nhận diện nhóm chữ bộ 走 chỉ dáng đi đặc biệt trong cổ văn.", "Tự nguyên_Xie": "趧 thuộc bộ 走 (tẩu, chạy), nghĩa chưa được giải thích rõ trong các tự điển. Wiktionary không có phân tích nguyên tự. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "觧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 是", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走是", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "是", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趧", "Unihan_Traditional (Chữ Phồn thể)": "趧", "Pinyin_Xie": "tí", "Âm Hán Việt_Xie": "đề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động đi nhanh hoặc đuổi theo trong tiếng Trung cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跉', '{"9000": "7214.0", "Chữ Trung Quốc": "跉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 12 | nét | 跉 | linh | tượng hình | chữ độc thể bộ 足; nghĩa loạng choạng, bước đi không vững | 跉 là chữ độc thể thuộc bộ 足 (túc, chân). Wiktionary không có phân tích cấu trúc. Chưa có nguồn học thuật về cấu tạo hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\": bộ 足 (chân) — đôi chân linh đinh loạng choạng, như người say đi không vững. | Gương Hán-Việt | linh trong nghĩa bước đi loạng choạng, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 跉 giúp nhận diện nhóm chữ bộ 足 chỉ dáng đi không vững trong cổ văn.", "Tự nguyên_Xie": "跉 thuộc bộ 足 (túc, chân), mang nghĩa bước đi loạng choạng không vững. Wiktionary không có phân tích nguyên tự. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "loạng choạng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跉", "Unihan_Traditional (Chữ Phồn thể)": "跉", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả dáng đi lảo đảo hoặc kết hợp thành từ láy. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邉', '{"9000": "7215.0", "Chữ Trung Quốc": "邉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 17 | nét | 邉 | biên | tượng hình | chữ độc thể bộ 辵; biến thể cổ của 邊, nghĩa cạnh, bên, biên giới | 邉 là biến thể cổ của 邊 (biên), thuộc bộ 辵 (xước, đi bộ). Wiktionary không có phân tích nguyên tự riêng cho dạng này. Chưa có nguồn học thuật riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biên\": bộ 辵 (đi bộ) — đi đến tận biên giới, cạnh bên lề đất nước. | Gương Hán-Việt | biên trong 邊界 (biên giới), 邊疆 (biên cương), 旁邊 (bên cạnh) | Mở khoá kiến thức | Biết 邉/邊 mở khoá nhóm từ 邊界, 邊疆, 旁邊, 身邊 trong tiếng Trung và tiếng Việt.", "Tự nguyên_Xie": "邉 là dạng viết cổ của 邊 (biên, biểu nghĩa cạnh/biên giới), thuộc bộ 辵 (xước, đi bộ). Nghĩa: bên, phía, bờ, biên giới, giới hạn. Wiktionary không có phân tích nguyên tự riêng. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bên, phía; bờ, rịa, ven, mép, vệ, viền, cạnh; biên giới; giới hạn, chừng mực; ở gần, bên cạnh", "Hạng Tần Suất (Jun Da)": "7215.0", "Tần Suất % (Jun Da)": "99.9978103814", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "邉", "Unihan_Traditional (Chữ Phồn thể)": "邉", "Pinyin_Xie": "biān", "Âm Hán Việt_Xie": "biên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ chỉ phương vị | 方位词 | Thường làm danh từ chỉ biên giới hoặc kết hợp làm từ chỉ phương vị để xác định vị trí. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ chỉ phương vị | 方位词 | Chỉ vị trí và đứng SAU danh từ — 桌子上, 家里 — chứ không đứng trước như ''trên bàn'', ''trong nhà''. Thường đi cùng 在.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酁', '{"9000": "7216.0", "Chữ Trung Quốc": "酁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 19 | nét | 酁 | sàm | tượng hình | chữ độc thể bộ 邑; chỉ tên đất, địa danh cổ | 酁 là chữ độc thể thuộc bộ 邑 (ấp, địa danh). Wiktionary ghi {{Han etym}} nhưng không có phân tích cụ thể. Chỉ dùng trong tên đất (地名).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sàm\": bộ 邑 (ấp/địa danh) — ấp Sàm, một vùng đất xa xôi chỉ tồn tại trong địa chí cổ. | Gương Hán-Việt | sàm trong nghĩa địa danh cổ, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 酁 giúp nhận diện nhóm chữ bộ 邑 chỉ địa danh hành chính trong văn bản lịch sử cổ.", "Tự nguyên_Xie": "酁 thuộc bộ 邑 (ấp), chỉ một địa danh cổ. Wiktionary ghi 酁 chỉ dùng làm tên đất (地名用字). Không có phân tích nguyên tự. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "酁", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "毚 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰毚阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "酁", "Unihan_Traditional (Chữ Phồn thể)": "酁", "Pinyin_Xie": "chán", "Âm Hán Việt_Xie": "sàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng để chỉ địa danh cổ trong lịch sử Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鍊', '{"9000": "7217.0", "Chữ Trung Quốc": "鍊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 金 | kim | biểu nghĩa | kim loại | 柬 | giản | biểu âm | 鍊 = 金 (Kim, biểu nghĩa: kim loại) + 柬 (Giản, biểu âm); chữ hình thanh. Phần 金 cho biết liên quan tới kim loại, phần 柬 cho âm đọc. Nghĩa gốc là nung chảy và tinh luyện kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"luyện\": 金 (kim loại) + 柬 (giản, âm) — luyện kim giống luyện người: qua lửa mới thành thép, qua khổ mới thành tài. | Gương Hán-Việt | luyện trong 鍊鋼 (luyện thép), 修鍊 (tu luyện), 鍛鍊 (rèn luyện), 鍊金術 (giả kim thuật) | Mở khoá kiến thức | Biết 鍊 mở khoá nhóm từ 鍛鍊, 修鍊, 鍊鋼, 鍊金術 trong tiếng Trung và tiếng Việt.", "Tự nguyên_Xie": "Tiểu triện | 鍊 là chữ hình thanh: 金 (kim, biểu nghĩa kim loại) + 柬 (giản, biểu âm). Nghĩa gốc là đúc và tinh luyện kim loại bằng nhiệt. Mở rộng thành: rèn luyện, tu dưỡng. Dạng tiểu triện lưu lại. Wiktionary xác nhận cấu trúc psc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "luyện, đúc (làm nóng chảy kim loại rồi để đông lại)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 柬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金柬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "柬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鍊", "Unihan_Traditional (Chữ Phồn thể)": "鍊", "Pinyin_Xie": "liàn", "Âm Hán Việt_Xie": "luyện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ quá trình tinh chế kim loại hoặc rèn luyện bản thân. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闀', '{"9000": "7218.0", "Chữ Trung Quốc": "闀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 17 | nét | 闀 | hướng | tượng hình | chữ độc thể bộ 門; nghĩa không rõ, không có trong tự điển thông dụng | 闀 là chữ độc thể thuộc bộ 門 (môn, cửa). Wiktionary không có phân tích nguyên tự. Chưa có nguồn học thuật về cấu tạo hay nghĩa cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hướng\": bộ 門 (cửa) — cửa hướng về một phía, như từ 向 (hướng) bên trong khuôn cửa. | Gương Hán-Việt | hướng trong nghĩa cửa quay theo hướng nhất định, ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 闀 giúp nhận diện nhóm chữ bộ 門 chỉ cửa và kết cấu kiến trúc trong cổ văn.", "Tự nguyên_Xie": "闀 thuộc bộ 門 (môn, cửa), âm xiàng. Wiktionary không có phân tích nguyên tự và không có định nghĩa rõ ràng. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "闀", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "門 + 巷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門巷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "闀", "Unihan_Traditional (Chữ Phồn thể)": "闀", "Pinyin_Xie": "xiàng", "Âm Hán Việt_Xie": "hướng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ ngõ hẻm hoặc âm thanh huyên náo nơi phố chợ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闄', '{"9000": "7219.0", "Chữ Trung Quốc": "闄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 17 | nét | 闄 | yểu | tượng hình | chữ độc thể bộ 門; nghĩa không rõ, không có trong tự điển thông dụng | 闄 là chữ độc thể thuộc bộ 門 (môn, cửa). Wiktionary không có phân tích nguyên tự và không có định nghĩa cụ thể. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yểu\": bộ 門 (cửa) — cánh cửa sâu yểu trong bóng tối, như hẻm sâu (窈窕/yểu điệu) khuất sau cổng. | Gương Hán-Việt | yểu trong nghĩa cửa sâu tối, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 闄 giúp nhận diện nhóm chữ bộ 門 trong tự thư cổ đại Trung Hoa.", "Tự nguyên_Xie": "闄 thuộc bộ 門 (môn, cửa), âm yǎo. Wiktionary không có phân tích nguyên tự và không có định nghĩa rõ ràng. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "闄", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "門 + 要", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門要", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "要", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "闄", "Unihan_Traditional (Chữ Phồn thể)": "闄", "Pinyin_Xie": "yǎo", "Âm Hán Việt_Xie": "yểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ để tả cảnh sâu thẳm hoặc yên tĩnh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腽', '{"9000": "7220.0", "Chữ Trung Quốc": "腽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 13 | nét | 腽 | oát | tượng hình | chữ độc thể bộ 肉; nghĩa con hải cẩu, dùng trong 腽肭 (hải cẩu, chó biển) | 腽 là chữ thuộc bộ 肉 (nhục, thịt). Wiktionary ghi 腽 là biến thể của 膃 (膃肭). Chưa có phân tích hình thanh hay hội ý độc lập. Chỉ dùng trong 腽肭 (hải cẩu).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oát\": bộ 肉 (thịt) — con hải cẩu béo mập (oát), thịt mỡ trơn như da bóng mướt dưới nước. | Gương Hán-Việt | oát trong 腽肭 (hải cẩu), dùng trong y học cổ truyền Trung Hoa | Mở khoá kiến thức | Biết 腽 mở khoá thuật ngữ dược liệu động vật biển trong y học cổ truyền Trung Hoa.", "Tự nguyên_Xie": "腽 thuộc bộ 肉 (nhục), là biến thể cũ của 膃, chỉ dùng trong 腽肭 — tên loài hải cẩu (chó biển). Wiktionary ghi 腽 xem 膃. Chưa có phân tích nguyên tự riêng. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con hải cẩu, chó biển", "Hạng Tần Suất (Jun Da)": "7220.0", "Tần Suất % (Jun Da)": "99.9978336367", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 昷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月昷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腽", "Unihan_Traditional (Chữ Phồn thể)": "膃", "Pinyin_Xie": "wà", "Âm Hán Việt_Xie": "ột", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ tả vẻ mập mạp hoặc kết hợp thành danh từ chỉ con hải cẩu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髿', '{"9000": "7221.0", "Chữ Trung Quốc": "髿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 17 | nét | 髿 | ta | tượng hình | chữ độc thể bộ 髟; dùng trong 髿鬖 miêu tả tóc rũ xuống lòa xòa | 髿 là chữ độc thể thuộc bộ 髟 (biêu, tóc dài). Wiktionary ghi {{Han etym}} nhưng không có phân tích cụ thể. Chỉ dùng trong các từ ghép mô tả tóc rối lòa xòa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ta\": bộ 髟 (tóc dài) — mái tóc ta-tả rũ xuống, lòa xòa như cành liễu trước gió. | Gương Hán-Việt | ta trong 髿鬖 (tóc lòa xòa rối tung), ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 髿 giúp nhận diện nhóm chữ bộ 髟 chỉ vẻ ngoài tóc trong văn học cổ điển Hán.", "Tự nguyên_Xie": "髿 thuộc bộ 髟 (biêu, tóc dài), dùng trong 髿鬖 và 鬖髿 chỉ tóc rũ xuống lòa xòa không gọn gàng. Wiktionary không có phân tích nguyên tự. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "髿", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 沙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟沙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "沙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "髿", "Unihan_Traditional (Chữ Phồn thể)": "髿", "Pinyin_Xie": "suō", "Âm Hán Việt_Xie": "ta", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ miêu tả trạng thái tóc tai xõa xượi hoặc rối bời. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶝', '{"9000": "7222.0", "Chữ Trung Quốc": "鶝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 20 | nét | 鶝 | phục | tượng hình | chim đầu rìu (chim hoopoe), chữ tự thân | 鶝 là chữ chỉ loài chim (bộ 鳥), cấu trúc nội bộ không rõ phân tách theo nguồn CHISE. Cấu tạo theo hội ý hoặc hình thanh không xác định được từ nguồn hiện có; xem như tượng hình chỉ loài chim đầu rìu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phục\": chim (鳥) mang vũ điệu phục sắc — liên tưởng con chim đầu rìu sặc sỡ đang ''phục kích'' trong bụi cây. | Gương Hán-Việt | Chữ này ít dùng trong tiếng Việt Hán-Việt hiện đại; nghĩa gốc là loài chim hoopoe (chim đầu rìu). | Mở khoá kiến thức | Biết 鶝 giúp nhận diện một số chữ chim cổ hiếm gặp trong văn bản Hán cổ điển.", "Tự nguyên_Xie": "Wiktionary ghi nhận 鶝 có hai âm đọc: fú (MC fuk1) và bì (MC bik1). Âm fú dùng trong từ ghép 鶝鶔 (fúróu). Nghĩa cổ: chim hoopoe (chim đầu rìu, 戴勝). Chưa có nguồn khảo cứu chi tiết về cấu tạo tự hình. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lụt", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "畐 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰畐鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鶝", "Unihan_Traditional (Chữ Phồn thể)": "鶝", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loài chim nước cổ hoặc chim lặn trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鷣', '{"9000": "7223.0", "Chữ Trung Quốc": "鷣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 23 | nét | 鷣 | nhân | tượng hình | chim ưng nhỏ (sparrow hawk), chữ tự thân | 鷣 thuộc bộ 鳥, là chữ chỉ loài chim. Cấu trúc nội bộ không phân tách rõ trong nguồn CHISE; xem như hình thanh hoặc tượng hình chỉ loài chim ưng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhân\": chim ưng (bộ 鳥) mang âm \"nhân\" — nhớ con diều hâu nhỏ lặng lẽ như người (nhân) ẩn mình rình mồi. | Gương Hán-Việt | Chữ 鷣 ít xuất hiện trong từ Hán-Việt thông dụng; chỉ gặp trong văn bản điểu học cổ. | Mở khoá kiến thức | Biết 鷣 giúp đọc hiểu các đoạn văn cổ mô tả loài chim săn mồi.", "Tự nguyên_Xie": "Wiktionary ghi 鷣 (MC yín, OC y) nghĩa là ''diều hâu nhỏ'' (sparrow hawk), dùng theo nghĩa cổ. Chưa có phân tích tự hình chi tiết. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "飷", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "覃 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰覃鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "覃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鷣", "Unihan_Traditional (Chữ Phồn thể)": "鷣", "Pinyin_Xie": "yín", "Âm Hán Việt_Xie": "nhân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loài chim săn mồi nhỏ thuộc họ cắt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鋊', '{"9000": "7224.0", "Chữ Trung Quốc": "鋊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 鋊 | dục | tượng hình | mạt đồng, cái que thông than — chữ tự thân | 鋊 thuộc bộ 金, chỉ đồ kim loại. Cấu trúc nội bộ không phân tách rõ; có thể hình thanh nhưng nguồn CHISE không xác nhận. Bộ 金 chỉ nghĩa liên quan kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dục\": kim loại (金) bị dũa đến ''dục'' (mài mòn) — hình ảnh mạt đồng rơi khi dũa dao. | Gương Hán-Việt | Chữ 鋊 hầu như không xuất hiện trong từ Hán-Việt thông dụng; chỉ gặp trong từ điển chữ Hán cổ. | Mở khoá kiến thức | Biết bộ 金 trong 鋊 giúp nhận ra nhóm chữ chỉ kim loại và dụng cụ kim loại cổ.", "Tự nguyên_Xie": "Wiktionary ghi 鋊 (MC juk6, OC y) có ba nghĩa cổ: mạt đồng (copper filings), mài cùn lưỡi dao bằng cách mài, và cái que thông than. Dùng theo nghĩa cổ, không còn phổ biến. Chưa có nguồn học thuật về tự hình. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một bài xì phé; mạt đồng; nộp", "Hạng Tần Suất (Jun Da)": "7224.0", "Tần Suất % (Jun Da)": "99.9978646438", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 谷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金谷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "谷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鋊", "Unihan_Traditional (Chữ Phồn thể)": "鋊", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "dục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này chủ yếu làm danh từ chỉ mạt kim loại hoặc động từ chỉ việc mài giũa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隤', '{"9000": "7225.0", "Chữ Trung Quốc": "隤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 14 | nét | 隤 | đồi | tượng hình | sụp đổ, lở — chữ tự thân; dị thể của 頹 | 隤 thuộc bộ 阜 (đồi/gò đất), chỉ sự sụp lở của đất. Wiktionary ghi đây là dạng cổ của 頹 (đồi — sụp đổ, suy tàn). Cấu trúc nội bộ không phân tách rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồi\": gò đất (bộ 阜) ''đồi'' dần rồi sụp xuống — ''đồi bại'' bắt đầu từ hình ảnh đất lở. | Gương Hán-Việt | \"đồi\" trong \"đồi bại\" (suy đồi, hư hỏng), \"đồi tàn\" — dùng cùng nghĩa với 頹 (đồi). | Mở khoá kiến thức | Biết 隤/頹 mở khoá nhóm từ suy đồi: 頹廢 (đồi phế), 頹喪 (đồi táng), 崩頹 (băng đồi).", "Tự nguyên_Xie": "Wiktionary xác nhận 隤 là dị thể của 頹 (tuí), nghĩa là sụp đổ thành tro tàn, suy đồi. Cũng dùng trong từ ghép cổ 虺隤. Bộ 阜 (gò, đất cao) gợi ý nghĩa liên quan sụt lở đất đai. Chưa có nguồn học thuật chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sụt, lở; suy đồi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 貴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝貴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "𬯎", "Unihan_Traditional (Chữ Phồn thể)": "隤", "Pinyin_Xie": "tuí", "Âm Hán Việt_Xie": "đồi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ sự sụp đổ của đất đá hoặc tính từ chỉ sự suy đồi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('譟', '{"9000": "7226.0", "Chữ Trung Quốc": "譟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 20 | nét | 言 | ngôn | biểu nghĩa | lời nói, tiếng nói | 喿 | táo | biểu âm | tiếng chim kêu ầm ĩ — cho âm và gợi nghĩa | 譟 = 言 (Ngôn, biểu nghĩa: lời nói) + 喿 (Táo, biểu âm và gợi nghĩa: tiếng kêu ồn ào). Chữ hình thanh: 言 chỉ hoạt động nói/kêu, 喿 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táo\": lời nói (言) ồn như bầy chim (喿) kêu táo tác — ''táo tác'' chính là tiếng ồn ào hỗn độn. | Gương Hán-Việt | \"táo\" trong \"ồn táo\" (tiếng ồn), liên hệ với 噪 (táo) trong \"táo tác\" (ồn ào, kêu la). | Mở khoá kiến thức | Biết 譟 giúp nhận ra nhóm chữ chỉ tiếng ồn: 噪音 (táo âm), 鼓譟 (cổ táo — la ó, hò reo).", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} không chi tiết cho 譟. Theo cấu trúc, 譟 gồm 言 (ngôn — lời nói) + 喿 (táo — tiếng chim kêu ầm ĩ), là chữ hình thanh chỉ tiếng ồn ào, la hét. Đây là dạng dị thể của 噪 (zào — ồn ào). Chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ồn ào", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 喿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言喿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "譟", "Unihan_Traditional (Chữ Phồn thể)": "譟", "Pinyin_Xie": "zào", "Âm Hán Việt_Xie": "táo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ sự làm loạn, huyên náo hoặc tính từ miêu tả âm thanh ồn ào. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒉', '{"9000": "7227.0", "Chữ Trung Quốc": "蒉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 蒉 | quỹ | tượng hình | cái sọt đựng đất, rau dền — dạng giản của 蕢 | 蒉 là dạng giản thể của 蕢 (quỹ), thuộc bộ 艸 (thảo — cỏ cây). Wiktionary ghi đây là dạng giản của 蕢, chỉ cái sọt đựng đất hoặc rau dền ăn được (edible amaranth). Cấu trúc gồm 艸 (biểu nghĩa: thực vật) + 貴/贵 (biểu âm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỹ\": cây cỏ (艸) quý giá đựng trong sọt — cái sọt tre dùng gánh đất trên công trình cổ xưa. | Gương Hán-Việt | \"quỹ\" ít dùng trong tiếng Việt hiện đại; gặp trong văn học Hán cổ khi nhắc đến người gánh đất (荷蒉). | Mở khoá kiến thức | Biết 蒉/蕢 giúp đọc hiểu Luận ngữ và các văn bản Nho gia nhắc đến việc tay lấm đất.", "Tự nguyên_Xie": "Wiktionary xác nhận 蒉 là dạng giản thể của 蕢 (kuì). 蕢 gồm 艸 (thảo — cỏ) + 貴 (quý/quỹ — cho âm). Nghĩa: cái sọt đựng đất (straw basket), hoặc rau dền ăn được (edible amaranth). Từ điển Luận ngữ dùng 蒉 chỉ người gánh sọt đất. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái sọt đựng đất", "Hạng Tần Suất (Jun Da)": "7227.0", "Tần Suất % (Jun Da)": "99.9978749795", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 贵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹贵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒉", "Unihan_Traditional (Chữ Phồn thể)": "蕢", "Pinyin_Xie": "kuì", "Âm Hán Việt_Xie": "quỹ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm tân ngữ trong văn ngôn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磜', '{"9000": "7228.0", "Chữ Trung Quốc": "磜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 16 | nét | 石 | thạch | biểu nghĩa | đá | 契 | khế | biểu âm | khế ước — cho âm | 磜 thuộc bộ 石 (thạch — đá) + có thể 契 (khế) làm thành phần âm. Là địa danh tại Giang Tây, Trung Quốc. Nguồn CHISE không có phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khế\": đá (石) ký ''khế ước'' — địa danh đá ở Giang Tây gắn với vùng đất cứng rắn như đá. | Gương Hán-Việt | Chữ 磜 hầu như không xuất hiện trong từ Hán-Việt thông dụng; chỉ dùng trong địa danh học. | Mở khoá kiến thức | Biết bộ 石 trong 磜 giúp nhận ra nhóm chữ địa danh liên quan đá và địa hình.", "Tự nguyên_Xie": "磜 là địa danh tại tỉnh Giang Tây (Tiểu Thế), Trung Quốc. Bộ 石 (thạch) gợi ý địa hình đá. Không có phân tích tự hình học thuật. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tiểu Thế (tên đất, ở tỉnh Giang Tây, Trung Quốc)", "Hạng Tần Suất (Jun Da)": "7228.0", "Tần Suất % (Jun Da)": "99.9978775635", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 祭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石祭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "祭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磜", "Unihan_Traditional (Chữ Phồn thể)": "磜", "Pinyin_Xie": "qì", "Âm Hán Việt_Xie": "thế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong địa danh hoặc chỉ các bậc đá ở vùng núi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綼', '{"9000": "7229.0", "Chữ Trung Quốc": "綼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 14 | nét | 糸 | mịch | biểu nghĩa | sợi tơ, vải | 必 | tất | biểu âm | chắc chắn — cho âm gần | 綼 thuộc bộ 糸 (mịch — sợi tơ), chỉ loại vải có viền trang trí. Có thể gồm 糸 (biểu nghĩa) + thành phần cho âm. Nguồn CHISE không phân tách rõ; hình thanh khả năng cao.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bích\": tơ (糸) viền ''bích'' sắc xanh — hình ảnh đường viền trang trí màu xanh ngọc trên tấm vải quý. | Gương Hán-Việt | Chữ 綼 hầu như không xuất hiện trong từ Hán-Việt thông dụng; chỉ gặp trong từ điển cổ về vải vóc. | Mở khoá kiến thức | Biết bộ 糸 trong 綼 giúp nhận ra nhóm chữ liên quan tơ lụa và dệt may cổ: 綿, 綼, 絲.", "Tự nguyên_Xie": "Wiktionary ghi 綼 (MC bik1, OC y) nghĩa là viền trang trí của vải (decorated margin of cloth). Bộ 糸 chỉ nghĩa liên quan vải/tơ. Dùng theo nghĩa cổ, không còn phổ biến. Chưa có nguồn học thuật chi tiết về tự hình. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Fou", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "綼", "Unihan_Traditional (Chữ Phồn thể)": "綼", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các chi tiết trang trí trên trang phục cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輋', '{"9000": "7230.0", "Chữ Trung Quốc": "輋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 13 | nét | 車 | xa | biểu nghĩa | xe | 者 | giả | biểu âm | người/kẻ — cho âm gần | 輋 thuộc bộ 車 (xa — xe), kết hợp với 者 (giả) làm thành phần âm. Là địa danh Hồng Kông (沙田禾輋) và chỉ nhóm người Hakka sống trên núi. Hình thanh khả năng cao.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xa\": xe (車) của người (者) ở vùng cao — địa danh 輋 gắn với cộng đồng người Hakka trên núi Hồng Kông. | Gương Hán-Việt | Chữ 輋 hầu như không dùng trong tiếng Việt; chỉ xuất hiện trong địa danh học Hồng Kông và nghiên cứu tiếng Hakka. | Mở khoá kiến thức | Biết 輋 giúp đọc hiểu địa danh Hồng Kông và văn hóa người Hakka trong tài liệu lịch sử.", "Tự nguyên_Xie": "輋 là chữ địa danh/phương ngữ, xuất hiện trong địa danh Hồng Kông như 禾輋 (Wo Che). Bộ 車 (xa — xe) và 者 (giả). Ý nghĩa ban đầu liên quan người Hakka sống trên núi hoặc vùng đất cao. Không có phân tích tự hình học thuật đầy đủ. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chế", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "𪨶", "Unihan_Traditional (Chữ Phồn thể)": "輋", "Pinyin_Xie": "shē", "Âm Hán Việt_Xie": "xa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong địa danh hoặc chỉ tộc người Xa ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('頨', '{"9000": "7231.0", "Chữ Trung Quốc": "頨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 15 | nét | 頁 | hiệt | biểu nghĩa | đầu, mặt | 羽 | vũ | biểu âm | lông vũ — cho âm | 頨 thuộc bộ 頁 (hiệt — đầu/mặt). Theo cấu trúc, có thể gồm 頁 (biểu nghĩa: đầu) + 羽 (vũ — lông, cho âm). Nghĩa chưa được xác định rõ ràng trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vũ\": đầu (頁) có lông ''vũ'' — hình ảnh chiếc mũ lông vũ trên đầu trong lễ hội cổ xưa. | Gương Hán-Việt | Chữ 頨 hầu như không dùng trong tiếng Việt Hán-Việt; nghĩa chưa rõ theo nguồn hiện có. | Mở khoá kiến thức | Biết bộ 頁 trong 頨 giúp nhận ra nhóm chữ liên quan đầu, mặt: 頭, 顏, 頸.", "Tự nguyên_Xie": "Wiktionary ghi 頨 (MC piān / jyu5, OC y) là chữ chưa có định nghĩa rõ ràng (rfdef). Bộ 頁 chỉ nghĩa liên quan đầu/mặt. Chưa có nguồn học thuật đầy đủ về nghĩa và tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "頨", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "羽 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰羽頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "頁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "頨", "Unihan_Traditional (Chữ Phồn thể)": "頨", "Pinyin_Xie": "yǔ", "Âm Hán Việt_Xie": "vũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ bộ phận khuôn mặt hoặc tính từ miêu tả hình dáng mặt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('閗', '{"9000": "7232.0", "Chữ Trung Quốc": "閗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 12 | nét | 門 | môn | biểu nghĩa | cửa, cổng | 鬥 | đấu | biểu âm | đánh nhau — cho âm và gợi nghĩa | 閗 thuộc bộ 門 (môn — cửa). Theo cấu trúc, có vẻ liên quan đến 鬥 (đấu — tranh đấu). Là dị thể của 鬥 hoặc 闗. Hội ý hoặc hình thanh chưa xác định rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đấu\": hai người tranh ''đấu'' ngay tại cổng (門) — hình ảnh cuộc chiến bùng phát trước cổng thành. | Gương Hán-Việt | \"đấu\" trong \"chiến đấu\" (chiến đấu), \"đấu tranh\" (tranh đấu), cùng nhóm âm với 鬥 (đấu). | Mở khoá kiến thức | Biết 閗 giúp nhận ra nhóm chữ tranh đấu trong văn bản cổ: 鬥, 闘, 閗.", "Tự nguyên_Xie": "閗 là dị thể cổ liên quan đến tranh đấu (dòu). Bộ 門 (môn) kết hợp gợi hình ảnh hai bên đối mặt qua cửa. Wiktionary không có phân tích chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tranh đấu", "Hạng Tần Suất (Jun Da)": "7232.0", "Tần Suất % (Jun Da)": "99.9978878992", "GavinGrover_Once (Chiết tự trực tiếp)": "門 + 斗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門斗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "閗", "Unihan_Traditional (Chữ Phồn thể)": "閗", "Pinyin_Xie": "dòu", "Âm Hán Việt_Xie": "đấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng trước tân ngữ để chỉ hành vi tranh chấp hoặc thi đấu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲹', '{"9000": "7233.0", "Chữ Trung Quốc": "鲹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 鱼 | ngư | biểu nghĩa | cá (giản thể) | 参 | sâm | biểu âm | sâm — cho âm | 鲹 = 鱼 (Ngư giản thể, biểu nghĩa: cá) + 参 (Sâm, biểu âm). Chữ giản thể hình thanh chỉ cá nục (horse mackerel/scad).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sâm\": cá (鱼) có âm ''sâm'' — con cá nục đi thành đàn như sao sâm trên trời. | Gương Hán-Việt | Chữ 鲹 chủ yếu dùng trong văn bản khoa học thủy sản; cá nục thường gọi bằng tiếng Việt trực tiếp. | Mở khoá kiến thức | Biết 鲹 giúp đọc danh mục hải sản và tài liệu thủy sản Trung Quốc hiện đại.", "Tự nguyên_Xie": "鲹 là chữ giản thể chỉ cá nục (horse mackerel/scad, Caranx). Bộ 鱼 (ngư — cá) cho nghĩa, 参 (sâm) cho âm shēn. Chữ truyền thống tương ứng: 鰺. Đây là chữ hình thanh điển hình. Chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá nục", "Hạng Tần Suất (Jun Da)": "7233.0", "Tần Suất % (Jun Da)": "99.9978956509", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 参", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼参", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "参", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲹", "Unihan_Traditional (Chữ Phồn thể)": "鰺", "Pinyin_Xie": "shēn", "Âm Hán Việt_Xie": "sâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng để chỉ các loài cá thuộc họ cá khế hoặc cá nục. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禣', '{"9000": "7234.0", "Chữ Trung Quốc": "禣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 14 | nét | 示 | thị | biểu nghĩa | thần linh, thờ phụng | 婦 | phụ | biểu âm | phụ nữ — cho âm gần | 禣 thuộc bộ 示 (thị — thần linh, lễ nghi). Cấu trúc nội bộ không rõ trong nguồn CHISE. Nghĩa chưa được xác định trong nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phụ\": nghi lễ (示) phụ trợ — hình ảnh nghi thức nhỏ phụ thêm trong tế lễ cổ xưa. | Gương Hán-Việt | Chữ 禣 hầu như không xuất hiện trong từ Hán-Việt thông dụng; nghĩa chưa xác định rõ. | Mở khoá kiến thức | Biết bộ 示 trong 禣 giúp nhận ra nhóm chữ lễ nghi: 神, 祭, 禮, 示.", "Tự nguyên_Xie": "禣 có bộ 示 (thị — thần linh, thờ phụng), gợi ý liên quan đến lễ nghi hoặc tín ngưỡng. Nghĩa cụ thể chưa được ghi rõ trong nguồn Wiktionary. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ý chưa rõ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 尃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻尃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禣", "Unihan_Traditional (Chữ Phồn thể)": "禣", "Pinyin_Xie": "fu", "Âm Hán Việt_Xie": "phú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này chủ yếu làm động từ chỉ việc vá áo hoặc danh từ chỉ mảnh vải vá. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粏', '{"9000": "7235.0", "Chữ Trung Quốc": "粏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 10 | nét | 米 | mễ | biểu nghĩa | gạo, hạt gạo | 太 | thái | biểu âm | thái — cho âm | 粏 thuộc bộ 米 (mễ — gạo). Cấu trúc có thể là 米 (biểu nghĩa: gạo) + 太 (thái — cho âm). Nghĩa không được ghi rõ trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thái\": gạo (米) ''thái'' nhỏ — hình ảnh hạt gạo được xay hoặc chế biến thành bột. | Gương Hán-Việt | Chữ 粏 hầu như không xuất hiện trong từ Hán-Việt thông dụng; nghĩa chưa xác định rõ. | Mở khoá kiến thức | Biết bộ 米 trong 粏 giúp nhận ra nhóm chữ lương thực: 粥, 粉, 粒, 糧.", "Tự nguyên_Xie": "粏 thuộc bộ 米 (mễ — gạo, hạt ngũ cốc), gợi ý liên quan thực phẩm hoặc chế biến gạo. Nghĩa cụ thể chưa có trong nguồn học thuật hiện có. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "珺", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 太", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米太", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "太", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粏", "Unihan_Traditional (Chữ Phồn thể)": "粏", "Pinyin_Xie": "tai", "Âm Hán Việt_Xie": "thái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ mô tả trạng thái thô ráp hoặc danh từ chỉ gạo chưa giã kỹ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臐', '{"9000": "7236.0", "Chữ Trung Quốc": "臐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 18 | nét | 肉 | nhục | biểu nghĩa | thịt | 熏 | huân | biểu âm | xông khói — cho âm | 臐 thuộc bộ 肉 (nhục — thịt). Theo cấu trúc, có thể gồm 肉 (biểu nghĩa: thịt) + thành phần cho âm xūn. Chỉ món súp thịt cừu đặc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huân\": thịt (肉) được ''huân'' (xông thơm) trong nồi súp — nồi canh cừu nghi ngút khói thơm phức. | Gương Hán-Việt | \"huân\" liên hệ với 熏 (huân — xông khói, hun); 臐 ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 臐 giúp đọc hiểu các đoạn văn về ẩm thực lễ nghi trong sách lễ (禮記) Trung Quốc cổ.", "Tự nguyên_Xie": "Wiktionary ghi 臐 (MC fan1, xūn) nghĩa là súp cừu đặc (thick lamb soup). Bộ 肉 (nhục — thịt) cho nghĩa. Đây là từ cổ dùng trong văn bản lễ nghi ẩm thực Trung Quốc cổ đại. Chưa có nguồn học thuật chi tiết hơn về tự hình. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "súp thịt cừu", "Hạng Tần Suất (Jun Da)": "7236.0", "Tần Suất % (Jun Da)": "99.9979039195", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 熏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月熏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "熏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臐", "Unihan_Traditional (Chữ Phồn thể)": "臐", "Pinyin_Xie": "xūn", "Âm Hán Việt_Xie": "huân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại canh thịt hầm nóng thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迏', '{"9000": "7237.0", "Chữ Trung Quốc": "迏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 7 | nét | 辶 | xước | biểu nghĩa | bước đi, di chuyển (bộ 辵) | 大 | đại | biểu âm | lớn — cho âm gần | 迏 thuộc bộ 辵 (xước — di chuyển, bước đi). Cấu trúc 辶 + 大 hoặc thành phần khác chưa rõ. Nghĩa: bay lên, soar. Chữ hiếm, hội ý hoặc hình thanh chưa xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạt\": bước chân (辶) ''đạt'' tới đích — con đường vươn lên cao, bay vút như chim. | Gương Hán-Việt | \"đạt\" liên hệ với 達 (đạt — đạt được, thông suốt); 迏 là dạng cổ/biến thể ít gặp. | Mở khoá kiến thức | Biết bộ 辵 trong 迏 giúp nhận ra nhóm chữ chuyển động: 達, 道, 迅, 迫.", "Tự nguyên_Xie": "迏 thuộc bộ 辵 (辶 — di chuyển, đi), chỉ sự bay lên hay tiến tới. Nghĩa ''soar'' (bay lên) gợi ý hành động di chuyển mạnh mẽ lên trên. Không có phân tích tự hình chi tiết trong nguồn học thuật. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Bay lên", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 太", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶太", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "太", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迏", "Unihan_Traditional (Chữ Phồn thể)": "迏", "Pinyin_Xie": "tì", "Âm Hán Việt_Xie": "đạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động bay lên hoặc đạt đến một vị trí, trạng thái. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鋾', '{"9000": "7238.0", "Chữ Trung Quốc": "鋾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 金 | kim | biểu nghĩa | kim loại | 匋 | đào | biểu âm | gốm sứ, đào — cho âm | 鋾 thuộc bộ 金 (kim — kim loại). Theo cấu trúc có thể là 金 (biểu nghĩa: kim loại) + 匋/舀 (cho âm táo). Là công cụ kim loại, liên quan đào bới hay gia công kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đào\": kim loại (金) dùng để ''đào'' bới — công cụ sắt của người thợ đào cổ xưa. | Gương Hán-Việt | \"đào\" liên hệ với 淘 (đào — đãi vàng), 挑 (đào — múc, khơi); 鋾 ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết bộ 金 trong 鋾 giúp nhận ra nhóm chữ dụng cụ kim loại cổ cùng chunk.", "Tự nguyên_Xie": "鋾 (táo) thuộc bộ 金 (kim — kim loại), nghĩa liên quan đến việc đào hoặc dụng cụ kim loại. Nghĩa ghi ''carious'' (liên quan mòn/hỏng) có thể là lỗi dịch; thực chất liên quan dụng cụ kim loại. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đào; như \"đào bới; đào mỏ\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 匋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金匋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鋾", "Unihan_Traditional (Chữ Phồn thể)": "鋾", "Pinyin_Xie": "táo", "Âm Hán Việt_Xie": "điêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động đào bới, khai thác hoặc danh từ chỉ một loại quặng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鐇', '{"9000": "7239.0", "Chữ Trung Quốc": "鐇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 20 | nét | 金 | kim | biểu nghĩa | kim loại | 凡 | phàm | biểu âm | thường, phàm — cho âm | 鐇 thuộc bộ 金 (kim — kim loại) + 凡 (phàm — cho âm). Chữ hình thanh chỉ vanadium hoặc một loại dụng cụ kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phàm\": kim loại (金) rất ''phàm'' tục — vanadium là nguyên tố kim loại phổ biến trong công nghiệp hiện đại. | Gương Hán-Việt | \"phàm\" trong \"phàm tục\" (tầm thường), \"phàm nhân\" (người thường); 鐇 ít dùng trong từ Hán-Việt thông thường. | Mở khoá kiến thức | Biết 鐇 giúp đọc bảng nguyên tố hóa học Trung Quốc và văn bản hóa học/luyện kim cổ.", "Tự nguyên_Xie": "鐇 (fán) gồm 金 (kim — kim loại) + 凡 (phàm — cho âm). Wiktionary ghi nghĩa là ''vanadium'' (nguyên tố V) hoặc công cụ kim loại cổ. Đây là chữ hình thanh điển hình. Chưa có phân tích tự hình chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鐇", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 番", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金番", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "番", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "𫔍", "Unihan_Traditional (Chữ Phồn thể)": "鐇", "Pinyin_Xie": "fán", "Âm Hán Việt_Xie": "phàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại rìu lớn dùng trong thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铻', '{"9000": "7240.0", "Chữ Trung Quốc": "铻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 金 | kim | biểu nghĩa | kim loại | 吾 | ngô | biểu âm | ta, tôi — cho âm | 铻 = 金 (Kim, biểu nghĩa: kim loại) + 吾 (Ngô, biểu âm). Chữ hình thanh: 金 chỉ vật kim loại, 吾 cho âm wú/ngô. Nghĩa: không khớp, bất hòa; nhạc cụ; cái cuốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngô\": kim loại (金) ''ngô'' nghê không vừa khớp — cái cuốc sắt cứng nhắc, không thuận tay. | Gương Hán-Việt | \"ngô\" trong 鉏鋙/鉏铻 (trở ngô — không ăn ý, không khớp); liên hệ với 吾 (ngô — ta, tôi). | Mở khoá kiến thức | Biết 铻 giúp đọc hiểu từ 鉏鋙 trong văn học cổ điển chỉ sự không hòa hợp.", "Tự nguyên_Xie": "Wiktionary xác nhận 铻 là chữ hình thanh (psc): 金 (kim — kim loại) cho nghĩa, 吾 (ngô) cho âm. Nghĩa: không khớp, bất hòa (misfit, discordant); cũng chỉ nhạc cụ hoặc cái cuốc/hoe. Dùng trong từ cổ 鉏鋙 (trở ngữ — không ăn ý). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: trở ngữ 鉏鋙)", "Hạng Tần Suất (Jun Da)": "7240.0", "Tần Suất % (Jun Da)": "99.9979121881", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 吾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅吾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铻", "Unihan_Traditional (Chữ Phồn thể)": "鋙", "Pinyin_Xie": "wú", "Âm Hán Việt_Xie": "ngữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường dùng trong từ ghép để chỉ sự không ăn khớp, bất đồng ý kiến. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鮼', '{"9000": "7241.0", "Chữ Trung Quốc": "鮼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 18 | nét | 魚 | ngư | biểu nghĩa | cá | 深 | thâm | biểu âm | sâu — cho âm gần | 鮼 thuộc bộ 魚 (ngư — cá). Cấu trúc nội bộ không rõ trong nguồn CHISE. Nghĩa chưa được xác định trong nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thâm\": cá (魚) ở chỗ nước ''thâm'' (sâu) — loài cá sống nơi nước sâu tối. | Gương Hán-Việt | Chữ 鮼 hầu như không xuất hiện trong từ Hán-Việt thông dụng; nghĩa chưa xác định rõ. | Mở khoá kiến thức | Biết bộ 魚 trong 鮼 giúp nhận ra nhóm chữ chỉ các loài cá hiếm trong văn bản cổ.", "Tự nguyên_Xie": "鮼 có bộ 魚 (ngư — cá), gợi ý là loại cá. Nghĩa cụ thể chưa có trong nguồn Wiktionary hay CHISE. Chưa có nguồn học thuật đầy đủ về chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鮼", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鮼", "Unihan_Traditional (Chữ Phồn thể)": "鮼", "Pinyin_Xie": "qīn", "Âm Hán Việt_Xie": "thâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cá biển theo ghi chép trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼈', '{"9000": "7242.0", "Chữ Trung Quốc": "鼈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黽 | Số nét | 24 | nét | 敝 | tệ | biểu âm | rách nát — cho âm | 黽 | mãnh | biểu nghĩa | ếch, bò sát có mai | 鼈 = 敝 (Tệ, biểu âm) + 黽 (Mãnh, biểu nghĩa: ếch/bò sát mai cứng). Chữ hình thanh: 黽 chỉ loài bò sát sống dưới nước, 敝 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miết\": bò sát (黽) mai ''miết'' phẳng — con ba ba mai mềm luồn ''miết'' dưới bùn. | Gương Hán-Việt | \"miết\" trong \"ba ba\" (con ba ba, 鱉/鼈) — dùng trong y học cổ truyền Việt Nam và Trung Quốc. | Mở khoá kiến thức | Biết 鼈 mở khoá: 甲魚 (giáp ngư — ba ba), 鼈甲 (miết giáp — mai ba ba dùng làm thuốc), 鼈裙 (váy ba ba, phần mềm quanh mai).", "Tự nguyên_Xie": "Wiktionary xác nhận 鼈 (biē) là chữ hình thanh (psc): 敝 (tệ) cho âm, 黽 (mãnh — ếch, bò sát) cho nghĩa. Nghĩa: ba ba, rùa nước ngọt mai mềm (Trionyx sinensis). Dị thể thông dụng: 鱉. Ba ba là loài đặc trưng trong ẩm thực và y học cổ truyền Trung Quốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con rùa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "敝 + 黽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敝黽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黽", "Unihan_Simplified (Chữ Giản thể)": "鼈", "Unihan_Traditional (Chữ Phồn thể)": "鼈", "Pinyin_Xie": "biē", "Âm Hán Việt_Xie": "miết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con ba ba hoặc các loài rùa mai mềm sống ở nước ngọt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('込', '{"9000": "7243.0", "Chữ Trung Quốc": "込", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 5 | nét | 辶 | xước | biểu nghĩa | bước đi, di chuyển | 入 | nhập | biểu nghĩa | vào, đi vào | 込 = 辶 (Xước, biểu nghĩa: bước đi) + 入 (Nhập, biểu nghĩa: vào). Chữ hội ý (ic) do Nhật Bản sáng tạo (kokuji): bước chân vào → đông đúc, chen chúc. Không dùng trong tiếng Trung.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhập\": bước chân (辶) ''nhập'' vào (入) — hình ảnh người chen nhau bước vào tàu điện giờ cao điểm Tokyo. | Gương Hán-Việt | 込 không có từ Hán-Việt; chỉ dùng trong tiếng Nhật với nghĩa đông đúc, chen chúc (込む). | Mở khoá kiến thức | Biết 込 giúp đọc tiếng Nhật: 込む (đông), 混み合う (chen chúc), 申し込み (đăng ký/nộp đơn).", "Tự nguyên_Xie": "込 là chữ kokuji (quốc tự Nhật Bản), không có nguồn gốc Hán ngữ cổ. Wiktionary xác nhận là hội ý (ic): 辶 (đi) + 入 (vào/nhập) → ý nghĩa ''chen vào, đông đúc''. Chỉ dùng trong tiếng Nhật: 込む (komu — đông, chen chúc), 込める (komeru — nạp vào, đưa vào). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(Tiếng Nhật kokuji) đông đúc; đi vào", "Hạng Tần Suất (Jun Da)": "7243.0", "Tần Suất % (Jun Da)": "99.9979183895", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 人", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶人", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "人", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "込", "Unihan_Traditional (Chữ Phồn thể)": "込", "Pinyin_Xie": "ru", "Âm Hán Việt_Xie": "vu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường dùng làm động từ chỉ hành động đi vào hoặc thu nạp trong các văn bản chịu ảnh hưởng chữ Nôm hoặc tiếng Nhật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篰', '{"9000": "7244.0", "Chữ Trung Quốc": "篰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 部 | bộ | biểu âm | bộ phận — cho âm | 篰 thuộc bộ 竹 (trúc — tre). Cấu trúc: 竹 (biểu nghĩa: tre) + 部 (bộ — cho âm). Chữ hình thanh chỉ đồ vật làm bằng tre: cái giỏ, thẻ tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bộ\": tre (竹) đan thành ''bộ'' giỏ — cái giỏ tre đựng đồ ăn của người xưa. | Gương Hán-Việt | \"bộ\" liên hệ với 簿 (bộ — sổ sách, thẻ tre); 篰 ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết bộ 竹 trong 篰 giúp nhận ra nhóm chữ đồ dùng bằng tre: 筊, 篰, 籃, 篆.", "Tự nguyên_Xie": "Wiktionary ghi 篰 (bù) có ba nghĩa: thẻ tre (bamboo slip — trong sách sử), giỏ tre (bamboo basket — phương ngữ), và đơn vị đếm thực phẩm (cổ). Bộ 竹 (trúc) cho nghĩa, phần còn lại cho âm. Chưa có phân tích tự hình chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái giỏ tre", "Hạng Tần Suất (Jun Da)": "7244.0", "Tần Suất % (Jun Da)": "99.9979204566", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 部", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮部", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "部", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篰", "Unihan_Traditional (Chữ Phồn thể)": "篰", "Pinyin_Xie": "bù", "Âm Hán Việt_Xie": "bộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ một loại giỏ hoặc sọt đan bằng tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痄', '{"9000": "7245.0", "Chữ Trung Quốc": "痄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 10 | nét | 疒 | nạch | biểu nghĩa | bệnh tật (bộ bệnh) | 乍 | sạ | biểu âm | đột ngột — cho âm gần | 痄 thuộc bộ 疒 (nạch — bệnh tật). Theo cấu trúc: 疒 (biểu nghĩa: bệnh) + 乍 (sạ — đột ngột, cho âm zhà). Chữ hình thanh chỉ bệnh quai bị hoặc tuyến lao (scrofula).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trá\": bệnh (疒) đến ''trá hình'' — quai bị khiến má sưng vù, trông như bị trá hình. | Gương Hán-Việt | \"trá\" liên hệ với 詐 (trá — giả dối, lừa dối); 痄 ít dùng trong tiếng Việt hiện đại — bệnh quai bị thường gọi thẳng. | Mở khoá kiến thức | Biết 痄 giúp đọc văn bản y học cổ truyền Trung Quốc về bệnh tuyến và viêm nhiễm.", "Tự nguyên_Xie": "Wiktionary ghi 痄 (MC zaa3, zhà) nghĩa là quai bị (mumps) hoặc tuyến lao (scrofulous swellings). Bộ 疒 (nạch — bệnh) cho nghĩa, 乍 (sạ) cho âm. Từ ghép: 痄腮 (quai bị — viêm tuyến mang tai). Hình thanh điển hình. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh quai bị", "Hạng Tần Suất (Jun Da)": "7245.0", "Tần Suất % (Jun Da)": "99.9979225238", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 乍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒乍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痄", "Unihan_Traditional (Chữ Phồn thể)": "痄", "Pinyin_Xie": "zhà", "Âm Hán Việt_Xie": "chá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong y học cổ truyền để chỉ chứng bệnh sưng quai bị. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睄', '{"9000": "7246.0", "Chữ Trung Quốc": "睄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 12 | nét | 目 | mục | biểu nghĩa | mắt | 肖 | tiêu | biểu âm | giống, nhỏ — cho âm gần | 睄 thuộc bộ 目 (mục — mắt). Theo cấu trúc: 目 (biểu nghĩa: mắt) + 肖 (tiêu/thiếu — cho âm shào). Chữ hình thanh chỉ nhìn liếc qua, nhìn thoáng (Cantonese).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiếu\": mắt (目) ''thiếu'' tập trung — liếc nhìn vội vã, chỉ nhìn thoáng qua. | Gương Hán-Việt | Chữ 睄 ít dùng trong tiếng Việt Hán-Việt; gặp chủ yếu trong văn bản tiếng Quảng Đông. | Mở khoá kiến thức | Biết 睄 giúp đọc văn bản tiếng Quảng Đông và phương ngữ miền Nam Trung Quốc.", "Tự nguyên_Xie": "Wiktionary ghi 睄 là chữ phương ngữ Quảng Đông, nghĩa là nhìn liếc qua (to glance). Bộ 目 (mục — mắt) cho nghĩa, thành phần còn lại cho âm shào. Chỉ dùng trong tiếng Quảng Đông, không phổ biến trong tiếng Trung phổ thông. Chưa có phân tích tự hình chi tiết. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "liếc nhìn; nhìn thoáng qua", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睄", "Unihan_Traditional (Chữ Phồn thể)": "睄", "Pinyin_Xie": "shào", "Âm Hán Việt_Xie": "sảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để diễn tả hành động nhìn nhanh hoặc liếc mắt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磡', '{"9000": "7247.0", "Chữ Trung Quốc": "磡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 16 | nét | 石 | thạch | biểu nghĩa | đá | 勘 | khám | biểu âm | xem xét, thẩm — cho âm | 磡 thuộc bộ 石 (thạch — đá). Theo cấu trúc: 石 (biểu nghĩa: đá) + 勘 (khám — cho âm kàn). Chữ hình thanh chỉ vách đá, bờ dốc. Phổ biến trong địa danh Hồng Kông (Hung Hom/紅磡).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khám\": đá (石) được ''khám'' xét — vách đá dốc đứng như bức tường thiên nhiên cần thám hiểm. | Gương Hán-Việt | \"khám\" liên hệ với 勘 (khám — xem xét); 磡 gặp trong địa danh Hồng Kông (紅磡 — Hung Hom). | Mở khoá kiến thức | Biết 磡 giúp đọc địa danh Hồng Kông: 紅磡 (Hung Hom), 牛頭磡 và các địa danh địa hình đá.", "Tự nguyên_Xie": "磡 (kàn) thuộc bộ 石 (thạch — đá), chỉ vách đá dốc đứng, mỏm đá nhô ra. Wiktionary chỉ ghi {{Han etym}} không chi tiết. Chữ nổi tiếng qua địa danh 紅磡 (Hung Hom) ở Hồng Kông. Chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vách núi", "Hạng Tần Suất (Jun Da)": "7247.0", "Tần Suất % (Jun Da)": "99.997926658", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 勘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石勘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磡", "Unihan_Traditional (Chữ Phồn thể)": "磡", "Pinyin_Xie": "kàn", "Âm Hán Việt_Xie": "khám", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ để chỉ các địa hình dốc đứng như vách đá hoặc bờ đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窔', '{"9000": "7248.0", "Chữ Trung Quốc": "窔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 11 | nét | 穴 | huyệt | biểu nghĩa | hang, lỗ hổng | 幺 | yêu | biểu âm | nhỏ — cho âm gần | 窔 thuộc bộ 穴 (huyệt — hang, lỗ hổng). Theo cấu trúc: 穴 (biểu nghĩa: không gian kín, hang) + thành phần cho âm yào. Chỉ góc đông nam của phòng, hoặc chỗ sâu kín.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"áo\": hang (穴) ''áo'' sâu tối — góc phòng đông nam khuất kín, sâu như hang huyệt. | Gương Hán-Việt | \"áo\" liên hệ với 奧 (áo — sâu kín, bí ẩn) trong \"áo bí\" (bí ẩn), \"áo diệu\" (huyền diệu). | Mở khoá kiến thức | Biết 窔 giúp đọc văn bản lễ nghi cổ Trung Quốc mô tả bố cục không gian phòng thờ.", "Tự nguyên_Xie": "Wiktionary ghi 窔 (yào) có hai nghĩa cổ: (1) góc đông nam của phòng (southeastern corner of a room), (2) sâu, kín đáo (deep, secluded). Bộ 穴 (huyệt — hang, lỗ hổng) cho nghĩa không gian kín. Dùng trong từ cổ 奧窔 (góc khuất). Chưa có nguồn học thuật chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gió đông nam", "Hạng Tần Suất (Jun Da)": "7248.0", "Tần Suất % (Jun Da)": "99.9979287252", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 交", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴交", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "交", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窔", "Unihan_Traditional (Chữ Phồn thể)": "窔", "Pinyin_Xie": "yào", "Âm Hán Việt_Xie": "yểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ góc khuất trong nhà hoặc tính từ chỉ sự sâu thẳm, tối tăm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筊', '{"9000": "7249.0", "Chữ Trung Quốc": "筊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 12 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 交 | giao | biểu âm | giao nhau — cho âm | 筊 = 竹 (Trúc, biểu nghĩa: tre) + 交 (Giao, biểu âm). Chữ hình thanh: 竹 chỉ vật liệu tre, 交 cho âm xiáo/giao. Nghĩa: dây bện bằng tre; ống sáo nhỏ; hoặc con bói (筊杯 — cặp đĩa tre/gỗ dùng trong nghi lễ bói toán).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giao\": tre (竹) ''giao'' nhau — cặp đĩa tre 筊 giao nhau khi tung lên hỏi ý thần linh. | Gương Hán-Việt | \"giao\" trong 筊杯 (giao bôi — con bói, đĩa bói bằng tre hoặc gỗ dùng ở đền miếu). | Mở khoá kiến thức | Biết 筊 giúp hiểu nghi lễ 筊杯 (xin keo/tung bói) tại đền miếu Việt Nam, Đài Loan và Phúc Kiến.", "Tự nguyên_Xie": "Wiktionary xác nhận 筊 là chữ hình thanh (psc): 竹 (trúc — tre) cho nghĩa, 交 (giao) cho âm xiáo. Nghĩa: dây tre bện, ống sáo nhỏ bằng tre, hoặc con bói 筊杯 (cặp đĩa bán nguyệt dùng hỏi thần linh trong đền miếu Đài Loan/Việt Nam). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây bện bằng tre; ống sáo nhỏ", "Hạng Tần Suất (Jun Da)": "7249.0", "Tần Suất % (Jun Da)": "99.9979307923", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 交", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮交", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "交", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筊", "Unihan_Traditional (Chữ Phồn thể)": "筊", "Pinyin_Xie": "xiáo", "Âm Hán Việt_Xie": "giảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loại dây bện bằng tre hoặc dụng cụ dùng để xin quẻ âm dương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羺', '{"9000": "7250.0", "Chữ Trung Quốc": "羺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 20 | nét | 羊 | dương | biểu nghĩa | dê, cừu | 奴 | nô | biểu âm | nô lệ — cho âm gần | 羺 thuộc bộ 羊 (dương — dê/cừu). Theo cấu trúc: 羊 (biểu nghĩa: dê/cừu) + thành phần cho âm nóu. Chữ hình thanh chỉ loài dê lạ (strange goat). Nghĩa ''cứu tế'' trong từ điển có thể là lỗi tra cứu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nâu\": dê (羊) lông màu ''nâu'' lạ — con dê dị thường mang lông màu nâu đặc biệt. | Gương Hán-Việt | Chữ 羺 hầu như không xuất hiện trong từ Hán-Việt thông dụng; chỉ gặp trong từ điển chữ Hán cổ. | Mở khoá kiến thức | Biết bộ 羊 trong 羺 giúp nhận ra nhóm chữ chỉ loài dê/cừu: 羊, 羔, 羝, 羯.", "Tự nguyên_Xie": "Wiktionary ghi 羺 (MC nóu) là loài dê lạ (strange goat), dùng theo nghĩa cổ và hiếm gặp. Bộ 羊 (dương — cừu/dê) cho nghĩa. Không có phân tích tự hình chi tiết. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sự cứu tế", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺶ + 需", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⺶需", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "需", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺶", "Unihan_Simplified (Chữ Giản thể)": "羺", "Unihan_Traditional (Chữ Phồn thể)": "羺", "Pinyin_Xie": "nóu", "Âm Hán Việt_Xie": "nâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ loài dê đực hoặc dê hoang dã trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腪', '{"9000": "7251.0", "Chữ Trung Quốc": "腪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 13 | nét | 肉 | nhục | biểu nghĩa | thịt, thân thể | 員 | viên | biểu âm | thành viên — cho âm gần | 腪 thuộc bộ 肉 (nhục — thịt, thân thể). Cấu trúc nội bộ không rõ trong nguồn CHISE. Nghĩa chưa được xác định trong nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vận\": thịt (肉) vận chuyển — hình ảnh thân thể chuyển động, trao đổi chất. | Gương Hán-Việt | Chữ 腪 hầu như không xuất hiện trong từ Hán-Việt thông dụng; nghĩa chưa xác định rõ. | Mở khoá kiến thức | Biết bộ 肉 trong 腪 giúp nhận ra nhóm chữ liên quan thân thể và nội tạng.", "Tự nguyên_Xie": "腪 có bộ 肉 (nhục — thịt, thân thể), gợi ý liên quan đến thân thể hoặc nội tạng. Nghĩa cụ thể chưa có trong nguồn học thuật. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "說", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 軍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月軍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "軍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腪", "Unihan_Traditional (Chữ Phồn thể)": "腪", "Pinyin_Xie": "yùn", "Âm Hán Việt_Xie": "vận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ thịt bị hỏng hoặc tính từ miêu tả trạng thái ôi thiu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荄', '{"9000": "7252.0", "Chữ Trung Quốc": "荄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艸 | thảo | biểu nghĩa | cỏ, thực vật | 亥 | hợi | biểu âm | giờ Hợi — cho âm gần | 荄 thuộc bộ 艸 (thảo — cỏ). Theo cấu trúc: 艸 (biểu nghĩa: cỏ/thực vật) + 亥 (hợi — cho âm gāi). Chữ hình thanh chỉ rễ cỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"gai\": cỏ (艸) có ''gai'' nhọn như rễ — rễ cỏ bám sâu xuống đất như gai cắm chặt. | Gương Hán-Việt | \"gai\" trong tiếng Việt Hán-Việt ít thấy; chữ 荄 gặp chủ yếu trong thơ cổ điển mô tả thiên nhiên. | Mở khoá kiến thức | Biết 荄 giúp đọc thơ cổ điển Trung Quốc và văn bản thực vật học cổ.", "Tự nguyên_Xie": "荄 (gāi) gồm bộ 艸 (thảo — cỏ) cho nghĩa và 亥 (hợi) cho âm. Nghĩa: rễ cỏ (roots of grass). Wiktionary chỉ ghi {{Han etym}}, không có chi tiết thêm. Chưa có nguồn học thuật đầy đủ về tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rễ cỏ", "Hạng Tần Suất (Jun Da)": "7252.0", "Tần Suất % (Jun Da)": "99.9979390609", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 亥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹亥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荄", "Unihan_Traditional (Chữ Phồn thể)": "荄", "Pinyin_Xie": "gāi", "Âm Hán Việt_Xie": "cai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn học cổ để chỉ phần rễ của các loài cỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓡', '{"9000": "7253.0", "Chữ Trung Quốc": "蓡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 艸 | thảo | biểu nghĩa | cỏ, thực vật | 參 | sâm | biểu âm | sâm, sao Sâm — cho âm | 蓡 thuộc bộ 艸 (thảo — cỏ/thực vật). Theo cấu trúc: 艸 (biểu nghĩa: thực vật) + 參 (sâm — cho âm shēn). Chữ hình thanh chỉ cây nhân sâm (ginseng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sâm\": cỏ (艸) quý như sao ''sâm'' — cây nhân sâm có rễ hình người, quý như ngôi sao trên trời. | Gương Hán-Việt | \"sâm\" trong \"nhân sâm\" (人參/蓡 — nhân sâm), \"sâm nhung\" (nhân sâm và nhung hươu — bổ dưỡng). | Mở khoá kiến thức | Biết 蓡 mở khoá: 人蓡/人參 (nhân sâm), 西洋參 (sâm Mỹ), 黨參 (đảng sâm), 丹參 (đan sâm).", "Tự nguyên_Xie": "蓡 gồm 艸 (thảo — thực vật) + 參 (sâm) cho âm shēn. Nghĩa: cây sâm (nhân sâm, ginseng — Panax ginseng) hoặc sao Sâm (Orion) trong Nhị thập bát tú. Đây là dị thể cổ của 參 trong nghĩa thực vật. Nhân sâm là dược liệu quý trong đông y. Chưa có phân tích tự hình chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ sâm (thứ cỏ quý, lá như bàn tay, hoa trắng, dùng làm thuốc); sao Sâm (một trong Nhị thập bát tú)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 浸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹浸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "浸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓡", "Unihan_Traditional (Chữ Phồn thể)": "蓡", "Pinyin_Xie": "shēn", "Âm Hán Việt_Xie": "sâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ vị thuốc nhân sâm hoặc tên một chòm sao trong nhị thập bát tú. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝀', '{"9000": "7254.0", "Chữ Trung Quốc": "蝀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng | 東 | đông | biểu âm | đông — cho âm | 蝀 = 虫 (Trùng, biểu nghĩa: sâu bọ) + 東 (Đông, biểu âm). Chữ hình thanh: 虫 chỉ loại sinh vật nhỏ (người xưa xem cầu vồng là rồng/sâu khổng lồ), 東 cho âm dōng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đống\": con sâu (虫) khổng lồ từ phương ''đông'' — người xưa hình dung cầu vồng như con rồng uống nước từ phía đông. | Gương Hán-Việt | \"đống\" liên hệ với 東 (đông — phương đông); 蝀 chỉ gặp trong từ cổ 螮蝀 (cầu vồng). | Mở khoá kiến thức | Biết 蝀 giúp đọc thơ cổ điển Trung Quốc dùng 螮蝀 để chỉ cầu vồng, như Kinh Thi (詩經).", "Tự nguyên_Xie": "Wiktionary xác nhận 蝀 là chữ hình thanh (psc): 虫 (trùng — sâu bọ/rồng nhỏ) cho nghĩa, 東 (đông) cho âm. Nghĩa: cầu vồng (rainbow), dùng trong từ cổ 螮蝀 (đế đống — cầu vồng). Trong quan niệm cổ Trung Hoa, cầu vồng được xem như loài sâu rồng khổng lồ uống nước. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đế đông 螮蝀)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 東", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫東", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "東", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "𬟽", "Unihan_Traditional (Chữ Phồn thể)": "蝀", "Pinyin_Xie": "dōng", "Âm Hán Việt_Xie": "đông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường xuất hiện trong từ ghép cổ để chỉ cầu vồng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詥', '{"9000": "7255.0", "Chữ Trung Quốc": "詥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 13 | nét | 言 | ngôn | biểu nghĩa | lời nói, tiếng nói | 合 | hợp | biểu âm | hợp lại, kết hợp — cho âm | 詥 = 言 (Ngôn, biểu nghĩa: lời nói) + 合 (Hợp, biểu âm). Chữ hình thanh: 言 chỉ hoạt động ngôn ngữ, 合 cho âm hé/hợp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hợp\": lời nói (言) ''hợp'' lại — hình ảnh mọi người cùng lên tiếng đồng thuận trong một cuộc họp. | Gương Hán-Việt | \"hợp\" trong \"hợp tác\" (協力), \"hợp nhất\" (thống nhất); 詥 liên quan lời nói hòa hợp. | Mở khoá kiến thức | Biết 詥 giúp nhận ra cấu trúc hình thanh với 言 (ngôn) trong nhiều chữ chỉ hoạt động ngôn ngữ.", "Tự nguyên_Xie": "Wiktionary xác nhận 詥 là chữ hình thanh (psc): 言 (ngôn — lời nói) cho nghĩa, 合 (hợp) cho âm hé. Nghĩa chưa được định nghĩa rõ trong nguồn hiện có. Cấu trúc gợi ý nghĩa liên quan đến hội tụ lời nói, đồng thuận, hoặc nói chuyện hòa hợp. Chưa có nguồn học thuật chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "襥", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 合", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言合", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "合", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "詥", "Unihan_Traditional (Chữ Phồn thể)": "詥", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hợp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ, biểu thị sự đồng thuận hoặc hòa hợp trong giao tiếp. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豀', '{"9000": "7256.0", "Chữ Trung Quốc": "豀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 谷 | Số nét | 17 | nét | 豀 | khê | tượng hình | khe suối hẹp giữa núi đồi | 豀 là chữ độc thể mang bộ 谷 (cốc – khe, thung lũng). Không có phân tích hình thanh/hội ý từ Wiktionary. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Khê\": bộ 谷 (khe suối) – 豀 là khe suối nhỏ chảy giữa núi đồi. | Gương Hán-Việt | khê trong \"khê giản\" (suối khe) | Mở khoá kiến thức | Biết 豀 mở khoá từ vựng địa hình khe suối trong văn bản cổ.", "Tự nguyên_Xie": "豀 không có glyph-origin từ Wiktionary. Bộ 谷 (cốc – thung lũng, khe) gợi liên quan đến địa hình khe suối. Chưa có nguồn học thuật xác nhận cấu trúc cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "豱", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "谷 + 奚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰谷奚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "谷", "Unihan_Simplified (Chữ Giản thể)": "豀", "Unihan_Traditional (Chữ Phồn thể)": "豀", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hề, khê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, chỉ địa hình khe suối hoặc thung lũng nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苠', '{"9000": "7257.0", "Chữ Trung Quốc": "苠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 苠 | mân | tượng hình | loài cây nông nghiệp dài ngày | 苠 mang bộ 艸 (thảo – cây cỏ) ở trên. Wiktionary ghi nhận chữ nhưng không cung cấp phân tích hình thanh/hội ý cụ thể. Đây là tên loài thực vật trong điển tịch nông nghiệp cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Mân\": bộ 艸 (cây cỏ) – 苠 là loài cỏ mân, cây nông nghiệp dài ngày trong điển tịch cổ Trung Hoa. | Gương Hán-Việt | mân trong tên thực vật cổ Hán | Mở khoá kiến thức | Biết 苠 mở khoá tên các loài thực vật nông nghiệp trong điển tịch cổ.", "Tự nguyên_Xie": "苠 xuất hiện trong Wiktionary nhưng không có glyph-origin chi tiết. Bộ 艸 (thảo – cây cỏ) xác định đây là tên thực vật. Chưa có nguồn học thuật xác nhận cấu trúc nội tại. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây nông nghiệp dài ngày", "Hạng Tần Suất (Jun Da)": "7257.0", "Tần Suất % (Jun Da)": "99.9979493966", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 民", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹民", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "民", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苠", "Unihan_Traditional (Chữ Phồn thể)": "苠", "Pinyin_Xie": "mín", "Âm Hán Việt_Xie": "mân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, chỉ lớp vỏ ngoài của tre hoặc một loại cây nông nghiệp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郞', '{"9000": "7258.0", "Chữ Trung Quốc": "郞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 9 | nét | 郞 | lang | tượng hình | chàng trai, chức quan lang | 郞 (dạng cổ của 郎) mang bộ 邑 (ấp – thành thị) ở phải. Wiktionary không cung cấp phân tích hình thanh cụ thể. Chữ liên quan đến chức quan và địa danh thành ấp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Lang\": bộ 邑 (thành ấp) – 郞 là \"lang quân\", chàng trai cao quý sống trong đô ấp hoặc chức quan lang triều đình. | Gương Hán-Việt | lang trong \"lang quân\" (chồng, phu quân), \"công lang\" (con trai quan) | Mở khoá kiến thức | Biết 郞/郎 mở khoá hàng loạt từ xưng hô và chức vị trong văn học cổ Việt-Hán.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 郞 là dạng cổ của 郎. Không có glyph-origin từ Wiktionary. Bộ 邑 (ấp) gợi người thuộc đô ấp hoặc chức vụ trong triều đình. Chữ xuất hiện qua tiểu triện và lục thư thông. Chưa có nguồn học thuật phân tích cấu trúc nội tại. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chàng trai; một chức quan", "Hạng Tần Suất (Jun Da)": "7258.0", "Tần Suất % (Jun Da)": "99.9979514637", "GavinGrover_Once (Chiết tự trực tiếp)": "良 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰良阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "良", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郞", "Unihan_Traditional (Chữ Phồn thể)": "郞", "Pinyin_Xie": "láng", "Âm Hán Việt_Xie": "lang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, dùng để xưng hô với nam giới hoặc chỉ chức quan thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骒', '{"9000": "7259.0", "Chữ Trung Quốc": "骒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 11 | nét | 骒 | khỏa | tượng hình | ngựa cái trưởng thành | 骒 mang bộ 馬 (mã – ngựa) là thành phần nghĩa. Wiktionary không cung cấp phân tích hình thanh/hội ý. Chữ tạo muộn chỉ ngựa cái.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Khỏa\": bộ 馬 (ngựa) – 骒 là ngựa khỏa (ngựa cái mạnh mẽ), con ngựa cái dùng nhân giống trong trại ngựa. | Gương Hán-Việt | khỏa mã trong văn bản cổ chỉ ngựa cái | Mở khoá kiến thức | Biết 骒 mở khoá từ vựng phân loại ngựa theo giới tính trong điển tịch cổ.", "Tự nguyên_Xie": "骒 không có glyph-origin từ Wiktionary. Bộ 馬 (mã – ngựa) xác định loài vật. Nghĩa \"ngựa cái\" cho thấy đây là chữ phân biệt giới tính trong văn bản cổ. Chưa có nguồn học thuật phân tích cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa cái", "Hạng Tần Suất (Jun Da)": "7259.0", "Tần Suất % (Jun Da)": "99.9979535309", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骒", "Unihan_Traditional (Chữ Phồn thể)": "騍", "Pinyin_Xie": "kè", "Âm Hán Việt_Xie": "khoả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ ngựa cái hoặc làm tính từ bổ nghĩa cho giống cái của loài ngựa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戤', '{"9000": "7260.0", "Chữ Trung Quốc": "戤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戈 | Số nét | 13 | nét | 戤 | cái | tượng hình | giả mạo thương hiệu; cầm cố tài sản | 戤 mang bộ 戈 (qua – vũ khí) là thành phần. Wiktionary không cung cấp phân tích cấu trúc. Đây là thuật ngữ thương mại-pháp lý trong phương ngữ Giang Nam chỉ việc giả mạo nhãn hiệu hoặc cầm đồ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Cái\": bộ 戈 (vũ khí) – 戤 là kẻ cầm vũ khí tựa vào vật người khác (dựa nghiêng/cái) để trục lợi, như giả mạo thương hiệu. | Gương Hán-Việt | cái trong ngữ cảnh thương mại cổ Giang Nam | Mở khoá kiến thức | Biết 戤 mở khoá từ vựng pháp lý thương mại trong văn bản cận đại Trung Quốc.", "Tự nguyên_Xie": "戤 không có glyph-origin từ Wiktionary. Bộ 戈 (qua – giáo mác) gợi tính chất cưỡng chiếm. Nghĩa chính là giả mạo nhãn hiệu hoặc cầm đồ lấy tiền, dùng trong phương ngữ Thượng Hải và Giang Nam. Chưa có nguồn học thuật phân tích cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giả mạo; giả mạo để trục lợi; dựa nghiêng; dựa vào", "Hạng Tần Suất (Jun Da)": "7260.0", "Tần Suất % (Jun Da)": "99.997955598", "GavinGrover_Once (Chiết tự trực tiếp)": "盈 + 戈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰盈戈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "盈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "戈", "Unihan_Simplified (Chữ Giản thể)": "戤", "Unihan_Traditional (Chữ Phồn thể)": "戤", "Pinyin_Xie": "gài", "Âm Hán Việt_Xie": "cái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ, thường dùng trong khẩu ngữ để chỉ hành vi dựa dẫm hoặc làm giả. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铞', '{"9000": "7261.0", "Chữ Trung Quốc": "铞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铞 | điêu | tượng hình | móc cài kim loại nhỏ trong cụm 钌铞儿 | 铞 mang bộ 金 (kim – kim loại) ở trái. Wiktionary không cung cấp phân tích hình thanh/hội ý. Chữ chỉ tồn tại trong cụm 钌铞儿 chỉ móc cài kim loại nhỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Điêu\": bộ 金 (kim loại) – 铞 là móc điêu (móc nhỏ bằng kim loại), phần trong cụm 钌铞儿. | Gương Hán-Việt | điêu trong từ ghép 钌铞 (móc cài kim loại) | Mở khoá kiến thức | Biết 铞 mở khoá tên chi tiết kim loại nhỏ trong từ điển phương ngữ Bắc Kinh.", "Tự nguyên_Xie": "铞 không có glyph-origin từ Wiktionary. Bộ 金 (kim – kim loại) xác định vật liệu. Chữ chỉ xuất hiện trong cụm 钌铞儿 (liào diào r), tên gọi dân gian cho móc cài kim loại nhỏ trên quần áo. Chưa có nguồn học thuật phân tích cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: liễu điếu 釕銱,钌铞)", "Hạng Tần Suất (Jun Da)": "7261.0", "Tần Suất % (Jun Da)": "99.9979576651", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 吊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅吊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铞", "Unihan_Traditional (Chữ Phồn thể)": "銱", "Pinyin_Xie": "diào", "Âm Hán Việt_Xie": "điếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, chỉ các vật dụng có quai treo hoặc móc khóa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耢', '{"9000": "7262.0", "Chữ Trung Quốc": "耢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耒 | Số nét | 13 | nét | 耒 | lồi | biểu nghĩa | cán cày, nông cụ | 勞 | lao | biểu âm | lao động | 耢 là chữ hình thanh: 耒 (Lồi, biểu nghĩa – cán cày) + 勞 (Lao, biểu âm). Wiktionary xác nhận: {{Han compound|耒|勞|ls=psc|c1=s|c2=p}}. Chữ chỉ cái bừa gai dùng san phẳng đất sau khi cày.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Lao\": bộ 耒 (cán cày) + 勞 (lao động) – chiếc bừa 耢 đòi hỏi lao động nặng nhọc để san phẳng đất ruộng. | Gương Hán-Việt | lao trong \"lao nông\" (nông dân lao động) | Mở khoá kiến thức | Biết 耢 mở khoá tên nông cụ cổ trong điển tịch nông nghiệp Trung Hoa.", "Tự nguyên_Xie": "Theo Wiktionary, 耢 (dạng thông dụng 耮) là chữ hình thanh: bộ 耒 (lồi – cán cày) cho nghĩa nông cụ, phần 勞 (lao) cho âm. Chỉ cái bừa gai – nông cụ cổ dùng san phẳng và vỡ nhỏ đất, công dụng mạnh hơn bừa thường. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bừa gai (nông cụ làm bằng những cành gai để làm cho đất nát nhỏ ra, có công dụng như cái bừa nhưng có thể tán đất nhỏ và phẳng hơn bừa); làm phẳng đất bằng cái bừa gai", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "耒 + 劳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耒劳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "劳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耒", "Unihan_Simplified (Chữ Giản thể)": "耢", "Unihan_Traditional (Chữ Phồn thể)": "耢", "Pinyin_Xie": "lào", "Âm Hán Việt_Xie": "lạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này vừa làm danh từ chỉ nông cụ vừa làm động từ chỉ hoạt động bừa đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麯', '{"9000": "7263.0", "Chữ Trung Quốc": "麯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 麥 | Số nét | 17 | nét | 麥 | mạch | biểu nghĩa | lúa mạch | 曲 | khúc | biểu âm | cong; khúc nhạc | 麯 là chữ hình thanh: 麥 (Mạch, biểu nghĩa – lúa mạch) + 曲 (Khúc, biểu âm). Wiktionary xác nhận: {{Han compound|麥|曲|ls=psc|c1=s|c2=p}}. Chữ là dạng cổ của 麴, chỉ men rượu làm từ ngũ cốc lên men.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Khúc\": 麥 (lúa mạch) + 曲 (khúc) – men rượu 麯 là lúa mạch uốn cong bởi nấm, lên men tạo ra rượu ngon. | Gương Hán-Việt | khúc trong \"tửu khúc\" (men rượu), \"khúc tương\" (tương lên men) | Mở khoá kiến thức | Biết 麯/麴 mở khoá từ vựng ủ rượu và lên men trong văn bản ẩm thực và y dược cổ.", "Tự nguyên_Xie": "Theo Wiktionary, 麯 là chữ hình thanh: bộ 麥 (mạch – lúa mạch) cho nghĩa ngũ cốc lên men, phần 曲 (khúc) cho âm. Là dạng cổ của 麴, chỉ men rượu hoặc nấm lên men từ gạo và lúa mạch, dùng trong ủ rượu và làm tương. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bài hát", "Hạng Tần Suất (Jun Da)": "7263.0", "Tần Suất % (Jun Da)": "99.9979617994", "GavinGrover_Once (Chiết tự trực tiếp)": "麥 + 曲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰麥曲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "麥", "Unihan_Simplified (Chữ Giản thể)": "麯", "Unihan_Traditional (Chữ Phồn thể)": "麯", "Pinyin_Xie": "qū", "Âm Hán Việt_Xie": "khúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, chỉ chất men dùng để ủ rượu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秱', '{"9000": "7264.0", "Chữ Trung Quốc": "秱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 11 | nét | 秱 | đồng | tượng hình | cây cao lương; đòng lúa mới nhú | 秱 mang bộ 禾 (hòa – lúa) ở trái. Wiktionary không cung cấp phân tích cấu trúc. Chữ chỉ cây cao lương hoặc đòng lúa mới nhú trong nông nghiệp cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Đồng\": bộ 禾 (lúa) – 秱 là đòng lúa mới nhú (đồng), hình ảnh cánh đồng lúa khi bông nhú ra xanh mướt. | Gương Hán-Việt | đồng trong \"đòng lúa\" (tiếng Việt Hán cổ) | Mở khoá kiến thức | Biết 秱 mở khoá từ vựng nông nghiệp lúa gạo trong điển tịch Hán cổ.", "Tự nguyên_Xie": "秱 không có glyph-origin từ Wiktionary. Bộ 禾 (hòa – lúa, ngũ cốc) xác định cây lương thực. Nghĩa chính là cao lương (sorghum) hoặc đòng lúa. Trong tiếng Việt Hán cổ còn dùng từ \"đòng đòng\" để chỉ lúa đang trổ bông. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đòng; như \"đòng đòng\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 同", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾同", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "同", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秱", "Unihan_Traditional (Chữ Phồn thể)": "秱", "Pinyin_Xie": "tóng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, chỉ phần bông lúa non còn nằm trong bẹ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筼', '{"9000": "7265.0", "Chữ Trung Quốc": "筼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 13 | nét | 筼 | vân | tượng hình | loài tre cao lớn | 筼 mang bộ 竹 (trúc – tre) ở trên. Wiktionary ghi 筼 chỉ tồn tại trong cụm 篔簹 (筼筜), chỉ loài tre to cao. Không có phân tích hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Vân\": bộ 竹 (tre) – 筼 là loài tre vân đương, thân cao vút như mây (vân), dùng làm nhạc cụ và đồ dùng. | Gương Hán-Việt | vân trong \"vân đương\" (筼筜 – loài tre to) | Mở khoá kiến thức | Biết 筼 mở khoá từ ghép 筼筜 và từ vựng về các loài tre trong thơ văn cổ.", "Tự nguyên_Xie": "Theo Wiktionary, 筼 (dạng thông dụng 篔) chỉ tồn tại trong cụm 篔簹 (筼筜), chỉ loài tre cao lớn. Bộ 竹 (trúc – tre) xác nhận đây là tên tre. Chưa có phân tích glyph-origin cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: vân đương 篔簹,筼筜)", "Hạng Tần Suất (Jun Da)": "7265.0", "Tần Suất % (Jun Da)": "99.9979659337", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 员", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮员", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "员", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筼", "Unihan_Traditional (Chữ Phồn thể)": "篔", "Pinyin_Xie": "yún", "Âm Hán Việt_Xie": "vân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, chủ yếu dùng trong từ ghép để chỉ một giống tre thân lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脧', '{"9000": "7266.0", "Chữ Trung Quốc": "脧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 肉 | nhục | biểu nghĩa | thịt, cơ thể | 夋 | tuấn | biểu âm | 脧 là chữ hình thanh: 肉 (Nhục, biểu nghĩa – thịt) + 夋 (biểu âm). Wiktionary xác nhận: {{Han compound|肉|夋|ls=psc|c1=s|c2=p|t1=flesh; meat}}. Chỉ việc giảm bớt, bóc lột hoặc cơ quan sinh dục của trẻ sơ sinh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Quyên\": bộ 肉 (thịt người) + 夋 (biểu âm) – 脧 chỉ sự giảm bớt từng phần (quyên bớt) từ cơ thể, như bị bóc lột từng phần. | Gương Hán-Việt | quyên trong \"thu quyên\" (giảm bớt, bóc lột) trong văn bản cổ | Mở khoá kiến thức | Biết 脧 mở khoá từ vựng cơ thể và bóc lột trong văn bản pháp lý Hán cổ.", "Tự nguyên_Xie": "Theo Wiktionary, 脧 là chữ hình thanh: bộ 肉 (nhục – thịt) cho nghĩa liên quan đến cơ thể, phần 夋 cho âm đọc. Nghĩa gốc là giảm bớt, rút bớt và bóc lột; cũng dùng chỉ cơ quan sinh dục của trẻ sơ sinh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giảm bớt, rút bớt", "Hạng Tần Suất (Jun Da)": "7266.0", "Tần Suất % (Jun Da)": "99.9979721351", "GavinGrover_Once (Chiết tự trực tiếp)": "⺼ + 夋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⺼夋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺼", "Unihan_Simplified (Chữ Giản thể)": "脧", "Unihan_Traditional (Chữ Phồn thể)": "脧", "Pinyin_Xie": "juān", "Âm Hán Việt_Xie": "tuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường dùng trong văn viết cổ để chỉ sự bóc lột hoặc hao hụt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茣', '{"9000": "7267.0", "Chữ Trung Quốc": "茣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 茣 | ngô | tượng hình | chiếu cói; loài cỏ đan chiếu | 茣 mang bộ 艸 (thảo – cây cỏ) ở trên. Wiktionary không cung cấp phân tích hình thanh/hội ý. Nghĩa chiếu gợi đây là loài cỏ dùng đan chiếu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Ngô\": bộ 艸 (cây cỏ) – 茣 là loài cỏ ngô, dùng đan chiếu trải sàn trong nhà người xưa. | Gương Hán-Việt | ngô trong các từ điển Hán-Nôm cổ | Mở khoá kiến thức | Biết 茣 mở khoá tên các loài thực vật thủ công nghiệp trong điển tịch cổ.", "Tự nguyên_Xie": "茣 không có glyph-origin từ Wiktionary. Bộ 艸 (thảo – cây cỏ) xác định thực vật. Nghĩa chiếu (mat, matting) cho thấy đây là loài cỏ dùng đan chiếu trải. Trong một số từ điển Hán-Nôm còn ghi nghĩa vội vã. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vội; như \"vội vàng; vội vã\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 吴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹吴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茣", "Unihan_Traditional (Chữ Phồn thể)": "茣", "Pinyin_Xie": "wú", "Âm Hán Việt_Xie": "vô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này chủ yếu dùng trong tên thảo dược hoặc làm tính từ mô tả trạng thái vội vã. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菒', '{"9000": "7268.0", "Chữ Trung Quốc": "菒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菒 | cảo | tượng hình | tên loài thực vật cổ chưa xác định | 菒 mang bộ 艸 (thảo – cây cỏ) ở trên. Wiktionary ghi nhận chữ nhưng định nghĩa chưa được điền đầy đủ (rfdef). Đây là tên loài thực vật trong điển tịch cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Cảo\": bộ 艸 (cây cỏ) – 菒 là loài cỏ cảo trong điển tịch cổ, tên thực vật chưa xác định rõ trong thực vật học hiện đại. | Gương Hán-Việt | cảo trong tên thực vật cổ Hán | Mở khoá kiến thức | Biết 菒 mở khoá tên các loài thực vật chưa xác định trong điển tịch cổ Trung Hoa.", "Tự nguyên_Xie": "Theo Wiktionary, 菒 là tên thực vật nhưng định nghĩa chưa đầy đủ (rfdef). Bộ 艸 (thảo – cây cỏ) xác định thực vật. Chưa có phân tích glyph-origin hay cấu trúc nội tại từ bất kỳ nguồn học thuật nào. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蒒", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 杲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹杲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "杲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菒", "Unihan_Traditional (Chữ Phồn thể)": "菒", "Pinyin_Xie": "gǎo", "Âm Hán Việt_Xie": "cảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng để chỉ một loại cỏ tranh thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕝', '{"9000": "7269.0", "Chữ Trung Quốc": "蕝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕝 | tuyệt | tượng hình | nắm cỏ đánh dấu thứ bậc trong lễ nghi triều đình | 蕝 mang bộ 艸 (thảo – cây cỏ) ở trên. Wiktionary không cung cấp định nghĩa rõ ràng (rfdef). Đây là nắm cỏ dùng trong nghi lễ triều đình để đánh dấu vị trí đứng theo thứ bậc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tuyệt\": bộ 艸 (cây cỏ) – 蕝 là nắm cỏ tuyệt (tuyệt – phân chia dứt khoát), mỗi nắm đánh dấu một bậc thứ trong triều đình. | Gương Hán-Việt | tuyệt trong ngữ cảnh lễ nghi phong kiến cổ | Mở khoá kiến thức | Biết 蕝 mở khoá từ vựng lễ nghi và thứ bậc trong điển lễ cổ Trung Hoa.", "Tự nguyên_Xie": "Theo Wiktionary, 蕝 không có định nghĩa đầy đủ (rfdef). Bộ 艸 (thảo – cây cỏ) xác định liên quan đến cây cỏ. Nghĩa truyền thống là nắm cỏ dùng trong lễ nghi triều đình để đánh dấu thứ bậc. Chưa có nguồn học thuật phân tích cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ thô được sử dụng để thể hiện thứ hạng", "Hạng Tần Suất (Jun Da)": "7269.0", "Tần Suất % (Jun Da)": "99.9979804037", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 絶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹絶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "絶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕝", "Unihan_Traditional (Chữ Phồn thể)": "蕝", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "toát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bó cỏ dùng làm cột mốc trong các nghi lễ triều đình xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詝', '{"9000": "7270.0", "Chữ Trung Quốc": "詝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 12 | nét | 詝 | chử | tượng hình | trí tuệ, thông minh | 詝 mang bộ 言 (ngôn – lời nói) ở trái. Wiktionary xác nhận nghĩa trí tuệ và thông minh nhưng không cung cấp phân tích hình thanh/hội ý nội tại. Chữ mang tính văn học cao.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Chử\": bộ 言 (lời nói) – 詝 là trí tuệ chử (chử – trí biết chọn lời), người có 詝 dùng lời đúng lúc đúng chỗ như người thông tuệ. | Gương Hán-Việt | chử trong \"chử tuệ\" (trí tuệ, sự thông minh) trong văn học cổ | Mở khoá kiến thức | Biết 詝 mở khoá từ vựng ca ngợi trí tuệ trong thơ văn cổ điển.", "Tự nguyên_Xie": "Theo Wiktionary, 詝 là chữ văn học chỉ trí tuệ, thông minh (wisdom, intelligence). Bộ 言 (ngôn – lời nói) gợi ý trí tuệ thể hiện qua ngôn ngữ. Chữ cổ ít dùng trong văn bản hiện đại. Chưa có phân tích glyph-origin. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trí tuệ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 宁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言宁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "𬣞", "Unihan_Traditional (Chữ Phồn thể)": "詝", "Pinyin_Xie": "zhǔ", "Âm Hán Việt_Xie": "thích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường dùng trong văn cổ để chỉ tri thức hoặc tài năng tiềm ẩn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('謱', '{"9000": "7271.0", "Chữ Trung Quốc": "謱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 18 | nét | 謱 | lâu | tượng hình | nói dài dòng, lặp đi lặp lại | 謱 mang bộ 言 (ngôn – lời nói) ở trái. Wiktionary chỉ ghi {{Han etym}} không cung cấp phân tích cấu trúc. Chữ cổ chỉ cách nói dài dòng không cần thiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Lâu\": bộ 言 (lời nói) – 謱 là kiểu nói lâu la (lâu dài), dài dòng lặp đi lặp lại không biết dừng. | Gương Hán-Việt | lâu trong nghĩa dài dòng trong văn học cổ | Mở khoá kiến thức | Biết 謱 mở khoá từ vựng miêu tả cách nói tiêu cực trong văn bản cổ.", "Tự nguyên_Xie": "謱 chỉ có {{Han etym}} trong Wiktionary, không có glyph-origin cụ thể. Bộ 言 (ngôn – lời nói) gợi liên quan đến cách nói năng. Nghĩa chính là nói dài dòng, lặp lại. Chưa có nguồn học thuật phân tích cấu trúc nội tại. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "豱", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 婁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言婁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "婁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "謱", "Unihan_Traditional (Chữ Phồn thể)": "謱", "Pinyin_Xie": "lóu", "Âm Hán Việt_Xie": "lâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ mô tả hành vi nói liên tục không ngừng trong văn ngôn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冁', '{"9000": "7272.0", "Chữ Trung Quốc": "冁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 八 | Số nét | 18 | nét | 冁 | sản | tượng hình | nụ cười nhẹ thoáng qua | 冁 mang bộ 八 (bát) là bộ thủ hình thức. Wiktionary không cung cấp phân tích cấu trúc. Chữ chỉ nụ cười nhẹ thoáng qua. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Sản\": 冁 chỉ nụ cười sản sinh thoáng qua khóe miệng, như bông hoa vừa nở trong khoảnh khắc ngắn ngủi. | Gương Hán-Việt | sản trong nghĩa biểu cảm nụ cười trong thơ từ cổ | Mở khoá kiến thức | Biết 冁 mở khoá từ vựng miêu tả biểu cảm khuôn mặt trong thơ từ cổ điển.", "Tự nguyên_Xie": "冁 không có glyph-origin từ Wiktionary. Bộ 八 (bát) có thể là bộ hình thức. Nghĩa nhoẻn miệng cười cho thấy đây là từ miêu tả biểu cảm tinh tế – nụ cười nhẹ thoáng qua. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhoẻn miệng cười", "Hạng Tần Suất (Jun Da)": "7272.0", "Tần Suất % (Jun Da)": "99.9979866051", "GavinGrover_Once (Chiết tự trực tiếp)": "单 + 展", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰单展", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "展", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "单", "Unihan_Simplified (Chữ Giản thể)": "冁", "Unihan_Traditional (Chữ Phồn thể)": "囅", "Pinyin_Xie": "chǎn", "Âm Hán Việt_Xie": "sản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường đi kèm với từ chỉ nụ cười để tả trạng thái vui vẻ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踧', '{"9000": "7273.0", "Chữ Trung Quốc": "踧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 15 | nét | 踧 | xúc | tượng hình | bước đi bất an, lo lắng; mặt đất bằng phẳng | 踧 mang bộ 足 (túc – bàn chân) ở trái. Wiktionary xác nhận chữ có hai âm đọc: cù (cùng 蹙, 蹴) trong cụm 踧踖 chỉ sự bất an; dí trong 踧踧 chỉ đất bằng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Xúc\": bộ 足 (bàn chân) – 踧 là bước chân xúc động (xúc – bất an), như bề tôi run rẩy bước từng bước nhỏ trước mặt vua. | Gương Hán-Việt | xúc trong \"cục xúc\" (跼踧 – gò bó, bất an) | Mở khoá kiến thức | Biết 踧 mở khoá cụm 踧踖 và từ vựng bất an lễ nghi trong điển tịch cổ.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 踧 có hai âm: cù – dùng trong cụm 踧踖 chỉ bất an lo lắng, dị thể của 蹙 và 蹴; dí – dùng trong 踧踧 chỉ mặt đất bằng phẳng. Bộ 足 (túc – bàn chân) xác nhận liên quan đến bước đi. Tiểu triện còn lưu trong wikimedia. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bằng phẳng, rộng rãi thênh thang", "Hạng Tần Suất (Jun Da)": "7273.0", "Tần Suất % (Jun Da)": "99.9979886723", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 叔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊叔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踧", "Unihan_Traditional (Chữ Phồn thể)": "踧", "Pinyin_Xie": "cù", "Âm Hán Việt_Xie": "túc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ mô tả dáng vẻ cung kính, bồn chồn hoặc mặt đất bằng phẳng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茚', '{"9000": "7274.0", "Chữ Trung Quốc": "茚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 茚 | ấn | tượng hình | hợp chất hữu cơ inden (C9H8) | 茚 mang bộ 艸 (thảo – cây cỏ) ở trên. Đây là chữ tạo hiện đại để phiên âm từ \"inden\" (C9H8). Bộ 艸 được chọn vì liên tưởng đến nguồn gốc hữu cơ của hợp chất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Ấn\": bộ 艸 (cây cỏ) – 茚 là inden (ấn-đen), hợp chất hữu cơ từ nhựa than đá, đặt tên theo âm phiên. | Gương Hán-Việt | ấn trong \"ấn-đen\" (茚 – inden, hợp chất hóa học) | Mở khoá kiến thức | Biết 茚 mở khoá từ vựng hóa học hữu cơ trong ngữ cảnh tên hợp chất phiên âm.", "Tự nguyên_Xie": "茚 không có glyph-origin từ Wiktionary. Đây là chữ tạo hiện đại phiên âm từ \"inden\" (C9H8), hợp chất hydrocarbon thơm chiết xuất từ nhựa than đá. Bộ 艸 gợi nguồn gốc hữu cơ. Chưa có phân tích học thuật về cấu trúc nội tại. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "in-đen (hợp chất hoá học C9H8 lấy từ nhựa than đá.)", "Hạng Tần Suất (Jun Da)": "7274.0", "Tần Suất % (Jun Da)": "99.9979907394", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 印", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹印", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "印", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茚", "Unihan_Traditional (Chữ Phồn thể)": "茚", "Pinyin_Xie": "yìn", "Âm Hán Việt_Xie": "ấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chuyên ngành hóa học để chỉ hợp chất hữu cơ indene. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辌', '{"9000": "7275.0", "Chữ Trung Quốc": "辌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 12 | nét | 辌 | lương | tượng hình | xe nằm, xe tang có màn che | 辌 mang bộ 車 (xa – xe) ở trái. Wiktionary xác nhận nghĩa qua cụm 轀輬 (xe tang có mui). Tiểu triện còn lưu trong wikimedia.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Lương\": bộ 車 (xe) – 辌 là xe lương (xe có lương phủ che), loại xe có màn che dành cho quý tộc hoặc làm xe tang. | Gương Hán-Việt | lương trong \"ôn lương\" (轀輬 – xe tang) trong văn bản lịch sử | Mở khoá kiến thức | Biết 辌 mở khoá cụm 轀輬 và từ vựng phương tiện giao thông cổ.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 辌 (dạng chính thức 輬) là xe phủ màn che, dùng như xe tang hoặc xe cho người bệnh nằm. Xuất hiện trong cụm 轀輬, 軒輬. Bộ 車 (xa – xe) xác nhận loại phương tiện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xe nằm", "Hạng Tần Suất (Jun Da)": "7275.0", "Tần Suất % (Jun Da)": "99.9979928065", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 京", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车京", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "京", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "辌", "Unihan_Traditional (Chữ Phồn thể)": "輬", "Pinyin_Xie": "liáng", "Âm Hán Việt_Xie": "lương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ để chỉ loại xe nằm hoặc xe tang thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辒', '{"9000": "7276.0", "Chữ Trung Quốc": "辒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 13 | nét | 辒 | ôn | tượng hình | xe có thể nằm ngủ; xe tang có mui | 辒 mang bộ 車 (xa – xe) ở trái. Wiktionary xác nhận hai nghĩa: xe ngủ (sleeping carriage) và xe tang (hearse). Cụm 轀輬 hay 轒轀 là xe tang lịch sử nổi tiếng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Ôn\": bộ 車 (xe) – 辒 là xe ôn (xe ấm cúng có mui che), dùng để ngủ khi di chuyển xa hoặc làm xe tang trong lịch sử. | Gương Hán-Việt | ôn trong \"ôn lương\" (轀輬 – xe tang lịch sử) | Mở khoá kiến thức | Biết 辒 mở khoá điển tích xe tang Tần Thủy Hoàng và từ vựng xe cộ hoàng gia.", "Tự nguyên_Xie": "Theo Wiktionary, 辒 (dạng chính thức 轀) là xe cổ dùng để ngủ hoặc làm xe tang. Nổi tiếng: Tần Thủy Hoàng mất trên đường tuần du, thi thể vận chuyển trong xe 轀輬. Bộ 車 (xa – xe) xác nhận loại phương tiện. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xe có màn che có thể nằm được; (xem: phần uân 轒轀)", "Hạng Tần Suất (Jun Da)": "7276.0", "Tần Suất % (Jun Da)": "99.9979948737", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 昷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车昷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "辒", "Unihan_Traditional (Chữ Phồn thể)": "轀", "Pinyin_Xie": "wēn", "Âm Hán Việt_Xie": "ôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường kết hợp với chữ khác tạo thành từ ghép chỉ loại xe kín thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郪', '{"9000": "7277.0", "Chữ Trung Quốc": "郪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 10 | nét | 妻 | thê | biểu âm | vợ | 邑 | ấp | biểu nghĩa | thành ấp, địa danh | 郪 là chữ hình thanh: 妻 (Thê, biểu âm) + 邑 (Ấp, biểu nghĩa – thành ấp). Wiktionary xác nhận: {{Han compound|妻|邑|ls=psc|c1=p|c2=s|t2=city}}. Chữ là tên địa danh cổ – sông Qi và huyện Qi ở Tứ Xuyên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Thê\": 妻 (thê – vợ, biểu âm) + 邑 (ấp – thành) – 郪 là địa danh Thê Giang, sông ở Tứ Xuyên đặt tên theo âm chữ thê. | Gương Hán-Việt | thê trong \"Thê Giang\" (郪江 – sông Qi ở Tứ Xuyên) | Mở khoá kiến thức | Biết 郪 mở khoá địa danh lịch sử Tứ Xuyên và An Huy trong điển tịch địa lý cổ.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 郪 là chữ hình thanh: 妻 (thê) cho âm qī, 邑 (ấp) cho nghĩa địa danh. Chỉ địa danh lịch sử: nước Qi cổ (nay thuộc An Huy), sông Qi và huyện Qi ở Tứ Xuyên. Tiểu triện còn lưu trong hanziyuan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Thê (ở tỉnh Tứ Xuyên của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "7277.0", "Tần Suất % (Jun Da)": "99.9979969408", "GavinGrover_Once (Chiết tự trực tiếp)": "妻 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰妻阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "妻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郪", "Unihan_Traditional (Chữ Phồn thể)": "郪", "Pinyin_Xie": "qī", "Âm Hán Việt_Xie": "thê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ địa danh hoặc tên sông cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄘', '{"9000": "7278.0", "Chữ Trung Quốc": "鄘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 13 | nét | 鄘 | dong | tượng hình | tên nước Dong thời Chu | 鄘 mang bộ 邑 (ấp – thành thị) là thành phần. Chữ là tên nước Dong thời Tây Chu, nay thuộc Hà Nam. Có kim văn và tiểu triện lưu lại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Dong\": bộ 邑 (thành ấp) – 鄘 là nước Dong (dong – dung hòa), một trong các nước nhỏ thời Chu được nhắc đến trong Kinh Thi. | Gương Hán-Việt | dong trong \"Dong Phong\" (鄘風 – phần Kinh Thi về nước Dong) | Mở khoá kiến thức | Biết 鄘 mở khoá 鄘風 trong Kinh Thi và địa danh lịch sử Hà Nam cổ.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 鄘 là địa danh lịch sử: tên nước Dong thời Tây Chu, nay thuộc vùng Hà Nam. Xuất hiện trong Kinh Thi (鄘風). Bộ 邑 (ấp) xác nhận là địa danh. Chưa có phân tích cấu trúc nội tại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Dong, nước Dung đời Chu (nay ở phía bắc huyện Cấp, tỉnh Hà Nam của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "7278.0", "Tần Suất % (Jun Da)": "99.997999008", "GavinGrover_Once (Chiết tự trực tiếp)": "庸 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰庸阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "庸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄘", "Unihan_Traditional (Chữ Phồn thể)": "鄘", "Pinyin_Xie": "yōng", "Âm Hán Việt_Xie": "dong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ riêng để chỉ một nước chư hầu thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄠', '{"9000": "7279.0", "Chữ Trung Quốc": "鄠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 13 | nét | 鄠 | hộ | tượng hình | tên huyện cổ ở Thiểm Tây | 鄠 mang bộ 邑 (ấp – thành thị) là thành phần. Wiktionary xác nhận đây là tên huyện lịch sử Hu (鄠縣) ở Thiểm Tây, đổi thành 戶縣 năm 1964, rồi thành 鄠邑 năm 2016. Tiểu triện lưu trong hanziyuan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Hộ\": bộ 邑 (thành ấp) – 鄠 là huyện Hộ (hộ – cửa), tên địa danh cổ ở Thiểm Tây, nay gọi là 鄠邑 thuộc Tây An. | Gương Hán-Việt | hộ trong \"Hộ Ấp\" (鄠邑 – tên quận mới ở Tây An) | Mở khoá kiến thức | Biết 鄠 mở khoá lịch sử địa danh vùng Quan Trung (Thiểm Tây) trong điển tịch địa lý.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 鄠 là tên huyện lịch sử Hu tại Thiểm Tây (gần Tây An). Đổi từ 鄠縣 → 戶縣 (1964) → 鄠邑 (2016). Xuất hiện trong cụm 郿鄠 (hai địa danh lân cận). Bộ 邑 (ấp) xác nhận là địa danh hành chính. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "7279.0", "Tần Suất % (Jun Da)": "99.9980010751", "GavinGrover_Once (Chiết tự trực tiếp)": "雩 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰雩阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄠", "Unihan_Traditional (Chữ Phồn thể)": "鄠", "Pinyin_Xie": "hù", "Âm Hán Việt_Xie": "hộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ riêng để chỉ địa danh hành chính thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('帱', '{"9000": "7280.0", "Chữ Trung Quốc": "帱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 10 | nét | 帱 | trù | tượng hình | màn xe, vải che phủ | 帱 mang bộ 巾 (cân – khăn vải) là thành phần. Wiktionary chỉ ghi {{Han etym}} không cung cấp phân tích nội tại. Tiểu triện lưu trong wikimedia. Nghĩa chính là màn che trên xe hoặc vải che phủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Trù\": bộ 巾 (vải khăn) – 帱 là tấm vải trù (che trùm), dùng làm màn xe hoặc che phủ vật quý trong cung đình. | Gương Hán-Việt | trù trong \"trù màn\" (màn che xe) trong văn bản cổ | Mở khoá kiến thức | Biết 帱 mở khoá từ vựng đồ vải vóc trên xe và trong nội thất cung đình cổ.", "Tự nguyên_Xie": "Tiểu triện | 帱 (dạng chính thức 幬) chỉ có {{Han etym}} trong Wiktionary, không có glyph-origin cụ thể. Bộ 巾 (cân – vải, khăn) xác nhận đây là vật dụng bằng vải: màn che, vải trùm. Tiểu triện lưu trong wikimedia. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màn xe; che chùm", "Hạng Tần Suất (Jun Da)": "7280.0", "Tần Suất % (Jun Da)": "99.9980031422", "GavinGrover_Once (Chiết tự trực tiếp)": "巾 + 寿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巾寿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "帱", "Unihan_Traditional (Chữ Phồn thể)": "幬", "Pinyin_Xie": "chóu", "Âm Hán Việt_Xie": "trù, đào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường dùng làm danh từ chỉ cái màn hoặc động từ với nghĩa che phủ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鈇', '{"9000": "7281.0", "Chữ Trung Quốc": "鈇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 鈇 | phủ | tượng hình | cái rìu, búa chặt bằng kim loại | 鈇 mang bộ 金 (kim – kim loại) là thành phần. Wiktionary chỉ ghi {{Han etym}} không cung cấp phân tích nội tại. Tiểu triện và lục thư thông lưu trong hanziyuan. Nghĩa chính là rìu, búa chặt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Phủ\": bộ 金 (kim loại) – 鈇 là chiếc rìu phủ (phủ việt), biểu tượng quyền hành hình phạt trong cụm 鈇鉞. | Gương Hán-Việt | phủ trong \"phủ việt\" (鈇鉞 – rìu lớn và rìu nhỏ, biểu tượng quyền lực) | Mở khoá kiến thức | Biết 鈇 mở khoá cụm 鈇鉞 (phủ việt – biểu tượng quyền hành hình phạt) trong văn bản cổ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 鈇 có {{Han etym}} trong Wiktionary nhưng không có glyph-origin chi tiết. Bộ 金 (kim – kim loại) xác nhận công cụ kim loại. Nghĩa rìu, búa chặt cho thấy đây là công cụ hoặc vũ khí. Tiểu triện và lục thư thông còn lưu trong hanziyuan. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鈇", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 夫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金夫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "𫓧", "Unihan_Traditional (Chữ Phồn thể)": "鈇", "Pinyin_Xie": "fū", "Âm Hán Việt_Xie": "phu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ một loại công cụ hoặc vũ khí thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缲', '{"9000": "7282.0", "Chữ Trung Quốc": "缲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 16 | nét | 糸 | mịch | biểu nghĩa | sợi tơ, chỉ | 喿 | táo | biểu âm | 缲 là chữ hình thanh: 糸 (Mịch, biểu nghĩa – sợi tơ) + 喿 (Táo, biểu âm). Wiktionary xác nhận: {{Han compound|糸|喿|ls=psc|c1=s|c2=p|t1=thread}}. Chỉ lụa xanh đậm, ươm tơ từ kén, hoặc khâu giấu đường chỉ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tảo\": 糸 (sợi tơ) + 喿 (biểu âm) – 缲 là ươm tơ tảo (tảo tơ từ kén), hình ảnh người phụ nữ dùng nước nóng kéo sợi tơ từ kén tằm. | Gương Hán-Việt | tảo trong \"tảo ty\" (缲絲 – ươm tơ, kéo tơ từ kén) | Mở khoá kiến thức | Biết 缲 mở khoá từ vựng ngành dệt lụa cổ đại và kỹ thuật khâu giấu đường chỉ.", "Tự nguyên_Xie": "Bạch thư | Tiểu triện | Theo Wiktionary (dạng chính thức 繰), 缲 là hình thanh: 糸 (mịch – sợi tơ) cho nghĩa, 喿 cho âm. Nghĩa gốc là lụa màu xanh đậm, mở rộng thành cuộn/xoắn sợi tơ và ươm tơ từ kén. Ở âm qiāo có nghĩa khâu giấu đường chỉ. Bạch thư và tiểu triện còn lưu trong wikimedia. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ươm tơ (kéo tơ ở kén ra)", "Hạng Tần Suất (Jun Da)": "7282.0", "Tần Suất % (Jun Da)": "99.9980072765", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 喿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟喿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缲", "Unihan_Traditional (Chữ Phồn thể)": "繰", "Pinyin_Xie": "qiāo", "Âm Hán Việt_Xie": "sào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này dùng làm động từ để chỉ hoạt động kéo sợi tơ từ kén tằm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雚', '{"9000": "7283.0", "Chữ Trung Quốc": "雚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 隹 | Số nét | 17 | nét | 雚 | quán | tượng hình | con cò; tượng hình chim cò cổ đại | 雚 là chữ tượng hình cổ: hình ảnh con chim cò. Wiktionary xác nhận (liushu=p – tượng hình): hình con cò, sau thêm 吅 từ thời Thương. Học giả Lý Học Cần (2012) cho phần âm là 雈, Thuyết Văn coi là 吅. Nay viết là 鸛. Có giáp cốt, kim văn, đại triện, tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Quán\": 雚 là hình ảnh con cò quán (quán – nhìn ngắm), đứng im bất động nhìn xuống mặt nước tìm cá – chữ tượng hình cổ đẹp nhất về loài chim. | Gương Hán-Việt | quán trong \"quán tước\" (cò và chim sẻ – ẩn dụ văn học cổ) | Mở khoá kiến thức | Biết 雚 mở khoá chữ 鸛 (quán – con cò) và từ vựng loài chim trong Kinh Thi.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 雚 là chữ tượng hình hình con cò. Ban đầu là cùng chữ với 雈, sau thêm 吅 từ thời Thương. Lý Học Cần (2012) cho phần âm là 雈; Thuyết Văn Giải Tự coi là 吅. Chữ hiện đại tương đương là 鸛 (con cò). Giáp cốt, kim văn, đại triện, tiểu triện đều còn lưu trong wikimedia. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1133.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (028) Huyên (1131) Truy (202)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Huyên (số 1131 - hai miệng) nằm ở giữa chữ Chuy (số 1132 - cỏ/chim đuôi ngắn). Hình ảnh con chim giấu mình trong đám cỏ cây, phát ra tiếng kêu râm ran. Giải thích sự chuyển ý: Đây là chữ Hội ý. Quán là tên một loài chim nhỏ. Sau mượn làm âm chỉ sự quan sát, xem xét.", "Nghĩa Tiếng Việt_Xie": "(cổ) cò; diệc", "Hạng Tần Suất (Jun Da)": "7283.0", "Tần Suất % (Jun Da)": "99.9980093437", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 𨾴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹𨾴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𨾴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "雚", "Unihan_Traditional (Chữ Phồn thể)": "雚", "Pinyin_Xie": "guàn", "Âm Hán Việt_Xie": "quán, hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ một loài chim nước hoặc loại cỏ hoang. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雟', '{"9000": "7284.0", "Chữ Trung Quốc": "雟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 隹 | Số nét | 18 | nét | 雟 | quê | tượng hình | địa danh cổ; chim sẻ; xoay quanh | 雟 mang bộ 隹 (chuy – chim đuôi ngắn) là thành phần. Wiktionary chỉ ghi {{Han etym}} không cung cấp phân tích nội tại. Chữ có ba nghĩa: địa danh, chim sẻ, và xoay quanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Quê\": bộ 隹 (chim) – 雟 là chim quê (chim sẻ nhỏ bé bay quanh quê hương), cũng là tên đất quê cổ. | Gương Hán-Việt | quê trong tên địa danh cổ có bộ 隹 | Mở khoá kiến thức | Biết 雟 mở khoá tên địa danh và chim trong văn bản địa lý cổ Trung Hoa.", "Tự nguyên_Xie": "雟 chỉ có {{Han etym}} trong Wiktionary. Bộ 隹 (chuy – chim đuôi ngắn) gợi liên quan đến loài chim. Chữ đa nghĩa: tên địa danh, loài chim sẻ, và hành động xoay quanh. Đây là chữ cổ ít dùng, chưa có nguồn học thuật phân tích cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên địa điểm; xoay quanh; chim sẻ", "Hạng Tần Suất (Jun Da)": "7284.0", "Tần Suất % (Jun Da)": "99.9980114108", "GavinGrover_Once (Chiết tự trực tiếp)": "屮 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱屮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "雟", "Unihan_Traditional (Chữ Phồn thể)": "雟", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "huề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này dùng làm danh từ chỉ loài chim hoặc địa danh, hoặc làm động từ chỉ sự xoay chuyển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韺', '{"9000": "7285.0", "Chữ Trung Quốc": "韺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 音 | Số nét | 17 | nét | 韺 | anh | tượng hình | nhạc lễ của hoàng đế huyền thoại Cốc | 韺 mang bộ 音 (âm – âm nhạc) là thành phần. Wiktionary không cung cấp định nghĩa đầy đủ (rfdef) nhưng ghi nhận 韶韺 là tên âm nhạc của hai hoàng đế cổ đại. Đây là chữ dùng trong điển cố âm nhạc cung đình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Anh\": bộ 音 (âm nhạc) – 韺 là bản nhạc anh (anh – xuân, hoa nở), âm nhạc của hoàng đế Cốc, thanh âm rực rỡ như mùa xuân. | Gương Hán-Việt | anh trong \"Thiều Anh\" (韶韺 – nhạc của đế Thuấn và đế Cốc) | Mở khoá kiến thức | Biết 韺 mở khoá điển cố âm nhạc cung đình cổ và tên nhạc của các hoàng đế huyền thoại.", "Tự nguyên_Xie": "Theo Wiktionary, 韺 là tên nhạc của hoàng đế Cốc (高辛氏) trong truyền thuyết. Xuất hiện trong cụm 韶韺 (nhạc của đế Thuấn và đế Cốc). Bộ 音 (âm) xác nhận liên quan đến âm nhạc lễ nghi. Chưa có phân tích glyph-origin. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "âm nhạc của hoàng đế huyền thoại Gu", "Hạng Tần Suất (Jun Da)": "7285.0", "Tần Suất % (Jun Da)": "99.9980134779", "GavinGrover_Once (Chiết tự trực tiếp)": "音 + 英", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰音英", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "英", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "音", "Unihan_Simplified (Chữ Giản thể)": "韺", "Unihan_Traditional (Chữ Phồn thể)": "韺", "Pinyin_Xie": "yīng", "Âm Hán Việt_Xie": "anh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ một khúc nhạc cổ của hoàng đế huyền thoại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('頵', '{"9000": "7286.0", "Chữ Trung Quốc": "頵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 16 | nét | 頵 | quân | tượng hình | đầu to; đặc điểm đầu lớn | 頵 mang bộ 頁 (hiệt – đầu người) ở phải. Wiktionary xác nhận: âm yūn chỉ đầu to (big head) dùng trong phương ngữ Quảng Đông; âm jūn chưa định nghĩa rõ. Tiểu triện lưu trong wikimedia.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Quân\": bộ 頁 (đầu người) – 頵 chỉ cái đầu quân (quân – tròn đều), to tròn như đầu người có kích thước lớn hơn thường. | Gương Hán-Việt | quân trong mô tả đầu to trong phương ngữ Quảng Đông | Mở khoá kiến thức | Biết 頵 mở khoá từ vựng miêu tả ngoại hình trong văn học phương ngữ Quảng Đông.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 頵 có hai âm: yūn chỉ đầu to (cụm 大頭頵 trong phương ngữ Quảng Đông); jūn chưa có định nghĩa rõ. Bộ 頁 (hiệt – đầu người) xác nhận liên quan đến đầu. Tiểu triện lưu trong wikimedia. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鵵", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "君 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰君頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "君", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "頵", "Unihan_Traditional (Chữ Phồn thể)": "頵", "Pinyin_Xie": "yūn", "Âm Hán Việt_Xie": "quân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này dùng làm tính từ để miêu tả đặc điểm đầu to của người hoặc vật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('顝', '{"9000": "7287.0", "Chữ Trung Quốc": "顝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 18 | nét | 顝 | khôi | tượng hình | chữ Hán cổ nghĩa chưa xác định | 顝 mang bộ 頁 (hiệt – đầu người) ở phải. Wiktionary không cung cấp định nghĩa (rfdef). Đây là chữ cổ hiếm, nghĩa chưa xác định trong học thuật hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Khôi\": bộ 頁 (đầu người) – 顝 gợi đến khôi ngô (đầu to, đẹp), có thể liên quan đến đặc điểm đầu hoặc khuôn mặt trong văn bản cổ. | Gương Hán-Việt | khôi trong ngữ cảnh miêu tả ngoại hình trong điển tịch cổ | Mở khoá kiến thức | Biết 顝 mở khoá nhóm chữ mô tả ngoại hình đầu/mặt trong điển tịch cổ Trung Hoa.", "Tự nguyên_Xie": "顝 không có định nghĩa đầy đủ trong Wiktionary (rfdef). Bộ 頁 (hiệt – đầu người) cho thấy liên quan đến đầu hoặc mặt người. Không có nguồn học thuật nào phân tích cấu trúc hay xác định nghĩa chính xác. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "靝", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "頁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "顝", "Unihan_Traditional (Chữ Phồn thể)": "顝", "Pinyin_Xie": "kuī", "Âm Hán Việt_Xie": "khôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ xương sọ hoặc đầu lâu trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镘', '{"9000": "7288.0", "Chữ Trung Quốc": "镘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 金 | kim | biểu nghĩa | kim loại, vàng | 曼 | mạn | biểu âm | dài, rộng | 镘 là chữ hình thanh: 金 (Kim, biểu nghĩa – kim loại) + 曼 (Mạn, biểu âm). Wiktionary xác nhận: {{Han compound|金|曼|ls=psc|c1=s|c2=p|t1=gold}}. Chữ chỉ cái bay (trowel) bằng kim loại dùng trát vữa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Mạn\": 金 (kim loại) + 曼 (biểu âm) – 镘 là cái bay mạn (lưỡi rộng phẳng bằng kim loại), dùng trát vữa lên tường. | Gương Hán-Việt | mạn trong \"mạn đao\" (镘刀 – cái bay, dụng cụ xây dựng) | Mở khoá kiến thức | Biết 镘 mở khoá từ vựng công cụ xây dựng trong điển tịch kỹ thuật cổ.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary (dạng chính thức 鏝), 镘 là hình thanh: 金 (kim – kim loại) cho nghĩa công cụ kim loại, 曼 (mạn) cho âm. Nghĩa là cái bay (trowel) dùng trát vữa hay xi măng lên tường. Tiểu triện còn lưu trong hanziyuan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bay để trát vữa", "Hạng Tần Suất (Jun Da)": "7288.0", "Tần Suất % (Jun Da)": "99.9980196794", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 曼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅曼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镘", "Unihan_Traditional (Chữ Phồn thể)": "鏝", "Pinyin_Xie": "màn", "Âm Hán Việt_Xie": "man", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ cái bay của thợ nề hoặc động từ chỉ việc trát phẳng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬋', '{"9000": "7289.0", "Chữ Trung Quốc": "鬋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 19 | nét | 鬋 | tiễn | tượng hình | tóc mai rũ xuống, tóc thả dài | 鬋 mang bộ 髟 (bưu – tóc dài) là thành phần. Wiktionary xác nhận nghĩa tóc rủ xuống (hanging down) là nghĩa văn học. Xuất hiện trong cụm 盛鬋 và 曼鬋. Không có phân tích hình thanh/hội ý nội tại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tiễn\": bộ 髟 (tóc dài) – 鬋 là tóc tiễn (tiễn – cắt dài), tóc mai rũ xuống hai bên thái dương như sợi tơ được thả dài. | Gương Hán-Việt | tiễn trong \"mạn tiễn\" (曼鬋 – tóc dài mềm mượt) trong thơ từ cổ | Mở khoá kiến thức | Biết 鬋 mở khoá từ vựng miêu tả tóc và vẻ đẹp giai nhân trong thơ từ cổ điển.", "Tự nguyên_Xie": "Theo Wiktionary, 鬋 là tính từ văn học chỉ tóc rủ xuống. Xuất hiện trong cụm 盛鬋 (tóc dày rủ xuống) và 曼鬋 (tóc mềm mượt rủ dài). Bộ 髟 (bưu – tóc dài) xác nhận liên quan đến tóc. Âm đọc jiān/jiǎn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tóc mai rũ xuống; thuỳ; cắt tóc; cạo râu", "Hạng Tần Suất (Jun Da)": "7289.0", "Tần Suất % (Jun Da)": "99.9980217465", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 前", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟前", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "前", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "鬋", "Unihan_Traditional (Chữ Phồn thể)": "鬋", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "tiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả tóc mai rủ xuống hoặc động từ chỉ việc cắt tóc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酾', '{"9000": "7290.0", "Chữ Trung Quốc": "酾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 14 | nét | 酾 | ti | tượng hình | lọc rượu; rót rượu; đào kênh phân nhánh | 酾 mang bộ 酉 (dậu – rượu, bình rượu) là thành phần. Wiktionary xác nhận ba nghĩa: lọc rượu, rót rượu, và đào kênh. Tiểu triện và lục thư thông lưu trong hanziyuan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Ti\": bộ 酉 (bình rượu) – 酾 là lọc ti (ti – lọc mịn qua rây), dùng rây mịn lọc bã rượu để giữ lại phần nước trong sáng. | Gương Hán-Việt | ti trong \"ti tửu\" (酾酒 – lọc rượu, rót rượu) | Mở khoá kiến thức | Biết 酾 mở khoá từ vựng ủ rượu và điển cố Xích Bích Phú trong văn học cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary (dạng chính thức 釃), 酾 có nghĩa văn học: lọc rượu (filter alcohol), rót rượu vào chén (pour alcohol), và đào kênh phân nhánh (dredge river). Bộ 酉 (dậu – bình rượu) xác nhận nghĩa rượu là gốc. Tiểu triện và lục thư thông lưu trong hanziyuan. Xuất hiện trong cụm 釃酒 (rót rượu) nổi tiếng qua Xích Bích Phú. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lấy cái rây lọc rượu", "Hạng Tần Suất (Jun Da)": "7290.0", "Tần Suất % (Jun Da)": "99.9980238136", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 丽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉丽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酾", "Unihan_Traditional (Chữ Phồn thể)": "釃", "Pinyin_Xie": "shāi", "Âm Hán Việt_Xie": "si", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ rượu để diễn tả hành động lọc hoặc rót. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳣', '{"9000": "7291.0", "Chữ Trung Quốc": "鳣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 21 | nét | 魚 | ngư | biểu nghĩa | cá | 亶 | đản | biểu âm | 鳣 là chữ hình thanh: 魚 (Ngư, biểu nghĩa – cá) + 亶 (Đản, biểu âm). Wiktionary xác nhận: {{Han compound|魚|亶|ls=psc|c1=s|c2=p|t1=fish}}. Chỉ loài cá tầm (sturgeon), cụ thể Acipenser mikadoi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Chiên\": 魚 (cá) + 亶 (biểu âm) – 鳣 là cá chiên (cá tầm quý), loài cá lớn sống ở nước sâu, thịt đặc và ngon. | Gương Hán-Việt | chiên trong \"chiên ngư\" (鳣魚 – cá tầm, loài cá quý trong điển tịch) | Mở khoá kiến thức | Biết 鳣 mở khoá từ vựng loài cá quý và ẩm thực cung đình trong điển tịch Trung Hoa.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary (dạng chính thức 鱣), 鳣 là hình thanh: 魚 (ngư – cá) cho nghĩa loài cá, 亶 cho âm zhān. Chỉ loài cá tầm (sturgeon), cụ thể Acipenser mikadoi (cá chiên Nhật Bản). Xuất hiện trong Kinh Thi. Đại triện và tiểu triện lưu trong wikimedia. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con lươn; cá chiên (một loại cá tầm, tên khoa học: acipenser mikadoi)", "Hạng Tần Suất (Jun Da)": "7291.0", "Tần Suất % (Jun Da)": "99.9980258808", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 亶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼亶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳣", "Unihan_Traditional (Chữ Phồn thể)": "鱣", "Pinyin_Xie": "zhān", "Âm Hán Việt_Xie": "chiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ loài cá tầm hoặc cá chiên trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麀', '{"9000": "7292.0", "Chữ Trung Quốc": "麀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 13 | nét | 鹿 | lộc | biểu nghĩa | hươu | 牝 | tẫn | biểu nghĩa | con cái (thú) | 麀 là chữ hội ý (ic): 鹿 (Lộc, biểu nghĩa: hươu) + 牝 (Tẫn, viết tắt, biểu nghĩa: giống cái). Hai thành tố kết hợp nghĩa tạo ra chữ chỉ hươu cái.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ưu\": hươu (鹿) mang dấu hiệu cái (牝) — con hươu cái nằm yên dưới bóng cây. | Gương Hán-Việt | ưu — dùng trong văn ngữ cổ chỉ hươu cái | Mở khoá kiến thức | Biết 麀 mở khoá từ cổ văn: 麀鹿 (hươu cái và hươu đực), 聚麀 (cha con dùng chung thú cái — ẩn dụ loạn luân trong Lễ Ký).", "Tự nguyên_Xie": "Bạch thư | Đại triện | Tiểu triện | Theo Wiktionary, 麀 là chữ hội ý ghép từ 鹿 (hươu) và 牝 (con cái, viết tắt). Chữ chỉ con hươu cái, có dạng tiểu triện được xác nhận qua bạch thư và đại triện. Mở rộng nghĩa chỉ con cái của bất kỳ loài thú bốn chân nào. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con hươu cái", "Hạng Tần Suất (Jun Da)": "7292.0", "Tần Suất % (Jun Da)": "99.9980300151", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 匕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿匕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麀", "Unihan_Traditional (Chữ Phồn thể)": "麀", "Pinyin_Xie": "yōu", "Âm Hán Việt_Xie": "ưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ con hươu cái trong văn ngôn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麉', '{"9000": "7293.0", "Chữ Trung Quốc": "麉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 17 | nét | 麉 | kiên | tượng hình | loài hươu mạnh nhất | 麉 là chữ độc thể, không rõ cấu trúc phân tích được từ nguồn hiện có. Wiktionary chỉ ghi nhận phiên âm và nghĩa, không cung cấp phân tích thành tố.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiên\": hươu (bộ 鹿) kiên cường nhất trong đàn — chữ cổ hiếm, gặp trong thư tịch văn ngôn. | Gương Hán-Việt | kiên — xuất hiện trong thư tịch cổ chỉ loài hươu đặc biệt | Mở khoá kiến thức | Biết 麉 giúp nhận ra các chữ hiếm thuộc bộ 鹿 trong văn ngữ cổ điển Trung Hoa.", "Tự nguyên_Xie": "Wiktionary chỉ ghi phiên âm jiān và nghĩa ''con hươu mạnh nhất''. Không có phân tích glyph rõ ràng. Chữ thuộc nhóm cổ văn liên quan bộ 鹿. Chưa có nguồn học thuật chi tiết về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鉉", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 鹿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱鹿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "麉", "Unihan_Traditional (Chữ Phồn thể)": "麉", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "kiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ loài hươu nhỏ trong các thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麊', '{"9000": "7294.0", "Chữ Trung Quốc": "麊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 17 | nét | 麊 | mi | tượng hình | dị thể của 麋 (nai sừng tấm) | 麊 là dị thể (異體) của 麋, không có phân tích thành tố riêng. Wiktionary xác nhận đây là hình thức thay thế của 麋 (nai sừng tấm, bộ 鹿).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mi\": dị thể của 麋 — nai sừng tấm trong rừng; nhớ bộ 鹿 (hươu) là chìa khoá nhận dạng. | Gương Hán-Việt | mi — trong từ 麋鹿 (nai sừng tấm) | Mở khoá kiến thức | Biết 麊/麋 mở khoá từ 麋鹿 (mí lù — nai sừng tấm) và hiểu nhóm chữ bộ 鹿 chỉ các loài hươu nai.", "Tự nguyên_Xie": "Theo Wiktionary, 麊 là dạng cổ thay thế của 麋. 麋 (mi) chỉ nai sừng tấm (elk/moose). Chữ 麊 thuộc nhóm biến thể chữ viết, không có lịch sử glyph độc lập được ghi lại. Chưa có nguồn học thuật phân tích cấu trúc riêng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "銊", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 鹿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱米鹿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鹿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "麊", "Unihan_Traditional (Chữ Phồn thể)": "麊", "Pinyin_Xie": "mí", "Âm Hán Việt_Xie": "mi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ con nai nhỏ hoặc hươu con trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麣', '{"9000": "7295.0", "Chữ Trung Quốc": "麣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 30 | nét | 麣 | nghiễm | tượng hình | dê núi (cổ văn) | 麣 là chữ độc thể hiếm, không có phân tích thành tố từ nguồn hiện có. Wiktionary chỉ ghi nhận nghĩa ''dê núi'' và phiên âm yán, không cung cấp phân tích glyph. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghiễm\": chữ cổ chỉ dê núi — hình thú bốn chân leo vách đá, gần với nhóm bộ 鹿. | Gương Hán-Việt | nghiễm — xuất hiện trong từ điển cổ chỉ dê núi | Mở khoá kiến thức | Biết 麣 giúp nhận ra nhóm chữ hiếm chỉ các loài thú hoang dã trong cổ văn Hán.", "Tự nguyên_Xie": "Theo Wiktionary, 麣 chỉ loài dê núi trong cổ ngữ. Không có phân tích cấu trúc glyph từ nguồn học thuật hiện có. Chữ cổ hiếm, gặp trong một số từ điển văn ngôn. Chưa có nguồn học thuật chi tiết về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dê (cổ xưa)", "Hạng Tần Suất (Jun Da)": "7295.0", "Tần Suất % (Jun Da)": "99.9980362165", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 嚴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鹿嚴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "嚴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麣", "Unihan_Traditional (Chữ Phồn thể)": "麣", "Pinyin_Xie": "yán", "Âm Hán Việt_Xie": "diêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loài dê núi trong các tài liệu cổ tịch. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藬', '{"9000": "7296.0", "Chữ Trung Quốc": "藬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 17 | nét | 藬 | đồi | tượng hình | một loại cỏ (cổ văn) | 藬 là chữ độc thể hiếm. Wiktionary chỉ ghi phiên âm tuī và nghĩa ''một loại cỏ'', không cung cấp phân tích thành tố. Không có nguồn học thuật phân tích cấu trúc riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồi\": chữ cổ bộ 艹 chỉ một loại cỏ dại — nay đã bỏ dùng trong văn viết hiện đại. | Gương Hán-Việt | đồi — trong từ cổ chỉ thực vật | Mở khoá kiến thức | Biết 藬 giúp nhận ra nhóm chữ thực vật hiếm thuộc bộ 艹 trong văn ngữ cổ.", "Tự nguyên_Xie": "Theo Wiktionary, 藬 chỉ một loại cỏ trong cổ ngữ (obs-std). Phiên âm Trung cổ và thượng cổ được ghi nhận, nhưng không có phân tích glyph chi tiết. Chữ cổ hiếm dùng. Chưa có nguồn học thuật chi tiết về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "藬", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 隤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹隤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藬", "Unihan_Traditional (Chữ Phồn thể)": "藬", "Pinyin_Xie": "tuī", "Âm Hán Việt_Xie": "đồi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ một loại cây thảo dược trong đông y cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞚', '{"9000": "7297.0", "Chữ Trung Quốc": "鞚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 17 | nét | 鞚 | khống | tượng hình | dây cương ngựa; điều khiển ngựa | 鞚 thuộc bộ 革 (da thuộc). Wiktionary không cung cấp phân tích thành tố chi tiết. Cấu trúc gợi ý chữ hình thanh với 革 biểu nghĩa (da, đồ da) và phần còn lại biểu âm. Chưa có nguồn học thuật phân tích cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khống\": 革 (da) + âm ''không/khống'' — dây da để khống chế đầu ngựa, giữ con vật trong tầm kiểm soát. | Gương Hán-Việt | khống — trong văn ngôn chỉ dây cương, ngựa | Mở khoá kiến thức | Biết 鞚 mở khoá từ ngựa cổ văn: 飛鞚 (cưỡi ngựa phi nhanh), 嚲鞚 (lơi dây cương).", "Tự nguyên_Xie": "鞚 thuộc bộ 革 (da thuộc), chỉ phần dây cương (headstall) gắn quanh đầu ngựa, dùng để điều khiển. Wiktionary ghi nhận nghĩa văn ngôn: dây cương, ngựa, và động từ cưỡi/điều khiển ngựa. Chưa có phân tích glyph chi tiết từ nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dàm ngựa (bộ đồ da đóng đầu ngựa)", "Hạng Tần Suất (Jun Da)": "7297.0", "Tần Suất % (Jun Da)": "99.9980424179", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 空", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革空", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "空", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞚", "Unihan_Traditional (Chữ Phồn thể)": "鞚", "Pinyin_Xie": "kòng", "Âm Hán Việt_Xie": "khống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ dây cương hoặc động từ với nghĩa gò cương ngựa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飔', '{"9000": "7298.0", "Chữ Trung Quốc": "飔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 風 | Số nét | 13 | nét | 飔 | ti | tượng hình | gió mát (giản thể của 颸) | 飔 là giản thể của 颸, ghép từ 风 (gió, giản thể của 風) và phần biểu âm. Wiktionary xác nhận đây là dạng giản hoá của 颸 (ti — gió mát thu).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ti\": 风 (gió) mang theo hơi lạnh ''ti'' của mùa thu — làn gió mát dịu cuối hè. | Gương Hán-Việt | ti — trong từ 颸飔 (gió mát, cổ văn) | Mở khoá kiến thức | Biết 飔/颸 mở khoá từ thơ văn cổ điển mô tả gió mát thu.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 飔 là dạng giản thể của 颸, trong đó 風 được viết tắt thành 风. 颸 chỉ làn gió mát mẻ, thường gắn với gió thu. Tiểu triện của chữ này đã được ghi nhận. Chữ giản hoá trong hệ thống chữ Trung Quốc giản thể hiện đại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gió mát; gió lạnh", "Hạng Tần Suất (Jun Da)": "7298.0", "Tần Suất % (Jun Da)": "99.9980444851", "GavinGrover_Once (Chiết tự trực tiếp)": "风 + 思", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴风思", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "思", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "风", "Unihan_Simplified (Chữ Giản thể)": "飔", "Unihan_Traditional (Chữ Phồn thể)": "颸", "Pinyin_Xie": "sī", "Âm Hán Việt_Xie": "ti", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn học cổ để chỉ làn gió mát. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴃', '{"9000": "7299.0", "Chữ Trung Quốc": "鴃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 15 | nét | 鴃 | quyết | tượng hình | chim bách thanh (shrike) | 鴃 thuộc bộ 鳥 (chim). Wiktionary dẫn nguồn từ 鴂 (dạng liên quan). Không có phân tích thành tố chi tiết từ Wiktionary cho chữ này. Cấu trúc gợi ý hình thanh với 鳥 biểu nghĩa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyết\": bộ 鳥 (chim) + âm ''quyết'' — chim bách thanh kêu tiếng sắc bén như dao cắt đứt không khí. | Gương Hán-Việt | quyết — trong từ 鴃舌 (tiếng man di, nghĩa mở rộng) | Mở khoá kiến thức | Biết 鴃 mở khoá từ cổ văn: 南蠻鴃舌 (tiếng man di phương Nam, ẩn dụ ngôn ngữ khó hiểu trong Mạnh Tử).", "Tự nguyên_Xie": "Theo Wiktionary, 鴃 chỉ chim bách thanh (shrike, họ Laniidae), tên khoa học ghi nhận từ văn ngôn. Wiktionary dẫn nguồn từ 鴂. Chữ cũng dùng trong từ 鶗鴃 (tên loài chim cổ văn). Không có phân tích glyph chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim bách thiệt (kêu được trăm thứ tiếng)", "Hạng Tần Suất (Jun Da)": "7299.0", "Tần Suất % (Jun Da)": "99.9980465522", "GavinGrover_Once (Chiết tự trực tiếp)": "鳥 + 夬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鳥夬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鴃", "Unihan_Traditional (Chữ Phồn thể)": "鴃", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ đứng độc lập để chỉ một loài chim nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醲', '{"9000": "7300.0", "Chữ Trung Quốc": "醲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 20 | nét | 酉 | dậu | biểu nghĩa | bình rượu (bộ rượu) | 農 | nông | biểu âm | nông nghiệp (biểu âm) | 醲 là chữ hình thanh (psc): 酉 (Dậu, biểu nghĩa: bình rượu, bộ chỉ rượu) + 農 (Nông, biểu âm, đọc nóng). Chữ chỉ rượu đặc/nồng, chưa pha loãng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nùng\": 酉 (rượu) + Nông (nồng) — chum rượu nồng đặc sánh như mật, chưa pha nước. | Gương Hán-Việt | nùng — trong từ 醲郁 (nồng nàn), 醇醲 (rượu nguyên chất đậm đặc) | Mở khoá kiến thức | Biết 醲 mở khoá từ rượu văn học: 醇醲 (thuần nùng — rượu nguyên chất), 醲郁 (hương nồng đậm).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 醲 ghép 酉 (biểu nghĩa: rượu) + 農 (biểu âm). Chữ chỉ rượu đặc, nồng, chưa pha. Cũng dùng nghĩa mở rộng: đậm đặc, nồng nàn. Tiểu triện và lục thư thông được ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rượu đặc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 農", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉農", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "農", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "𬪩", "Unihan_Traditional (Chữ Phồn thể)": "醲", "Pinyin_Xie": "nóng", "Âm Hán Việt_Xie": "nùng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ bổ nghĩa cho rượu hoặc tình cảm đậm đà. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('毳', '{"9000": "7301.0", "Chữ Trung Quốc": "毳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 毛 | Số nét | 12 | nét | 毳 | xúy | tượng hình | ba chữ 毛 chồng lên — lông tơ mịn | 毳 là chữ hội ý tạo bởi ba chữ 毛 (lông) xếp chồng ({{zh-etym-triple|毛|hair}}). Ba lớp lông tượng trưng cho lông tơ mịn màng trên thú vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xúy\": ba lớp 毛毛毛 — lông tơ dày mịn của thú vật miền lạnh, dùng may áo quý phái. | Gương Hán-Việt | xúy — trong từ 毳衣 (áo lông tơ), 毳幕 (lều lông thú) | Mở khoá kiến thức | Biết 毳 mở khoá từ văn hoá du mục: 毳帳/毳幕 (lều lông thú của người du mục), 毳衣 (áo bằng lông tơ thú), 毳冕 (mũ miện thời cổ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 毳 được tạo từ ba chữ 毛 (lông) chồng lên nhau, chỉ lông tơ mịn của thú vật. Tiểu triện được ghi nhận. Cũng dùng nghĩa cổ thay thế cho 脆 (mềm yếu). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lông mao", "Hạng Tần Suất (Jun Da)": "7301.0", "Tần Suất % (Jun Da)": "99.9980568879", "GavinGrover_Once (Chiết tự trực tiếp)": "毛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "品 (Kiến trúc tam giác)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴毛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "毳", "Unihan_Traditional (Chữ Phồn thể)": "毳", "Pinyin_Xie": "cuì", "Âm Hán Việt_Xie": "thúy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ lớp lông mềm mại của động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絫', '{"9000": "7302.0", "Chữ Trung Quốc": "絫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 絫 | luy | tượng hình | đơn vị đo lường cổ (bội số của 黍) | 絫 là chữ độc thể thuộc bộ 糸 (tơ, sợi). Không có phân tích thành tố hay etymology từ nguồn Wiktionary. Chữ là đơn vị đo trọng lượng cổ của Trung Hoa. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"luy\": bộ 糸 (tơ) — đơn vị đo nhỏ như sợi tơ, dùng trong hệ thống đo lường cổ Trung Hoa. | Gương Hán-Việt | luy — đơn vị đo lường cổ, ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 絫 giúp hiểu hệ thống đo lường cổ Trung Hoa: 黍→絫→銖→兩→斤.", "Tự nguyên_Xie": "絫 không có etymology glyph từ nguồn hiện có. Theo các từ điển cổ, 絫 là đơn vị trọng lượng nhỏ trong hệ thống đo lường cổ Trung Hoa (bằng 10 黍). Chữ thuộc bộ 糸, gợi ý liên quan đến sợi/tơ. Chưa có nguồn học thuật chi tiết về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xếp nhiều, chồng chất; tích luỹ, tích trữ; nhiều lần", "Hạng Tần Suất (Jun Da)": "7302.0", "Tần Suất % (Jun Da)": "99.9980610222", "GavinGrover_Once (Chiết tự trực tiếp)": "厽 + 糸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱厽糸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糸", "Unihan_Simplified (Chữ Giản thể)": "絫", "Unihan_Traditional (Chữ Phồn thể)": "絫", "Pinyin_Xie": "lěi", "Âm Hán Việt_Xie": "luỹ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ sự tích lũy hoặc xếp chồng lên nhau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脺', '{"9000": "7303.0", "Chữ Trung Quốc": "脺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 脺 | tụy | tượng hình | tụy tạng (pancreas) hoặc chất béo mềm | 脺 thuộc bộ 肉/月 (thịt, cơ thể). Không có etymology glyph từ nguồn hiện có. Chữ liên quan đến tụy tạng hoặc chất béo mềm trong cơ thể. Chưa có nguồn học thuật chi tiết về cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tụy\": bộ 月/肉 (thịt) + âm gần 脆 (cuì) — phần nội tạng mềm trong cơ thể, như tụy tạng. | Gương Hán-Việt | tụy — gợi liên tưởng tụy tạng trong y học | Mở khoá kiến thức | Biết 脺 giúp nhận ra nhóm chữ bộ 月/肉 chỉ các bộ phận cơ thể trong y học cổ.", "Tự nguyên_Xie": "脺 không có etymology glyph từ nguồn hiện có. Thuộc bộ 肉 (thịt), liên quan đến giải phẫu cơ thể. Chữ gần với 脆 (giòn, yếu) về âm cuì. Không có phân tích thành tố từ Wiktionary. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nốt; như \"nốt ruồi\" tuỵ; như \"tuỵ (lá lách)\" \n (Danh) Tụy dịch 脺液 chất lỏng tiết ra trong lá lách giúp tiêu hóa. (Danh) Lá lách ngày xưa gọi là tụy tạng 膵臟.", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 卒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月卒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脺", "Unihan_Traditional (Chữ Phồn thể)": "脺", "Pinyin_Xie": "cuì", "Âm Hán Việt_Xie": "tụy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ trong y học để chỉ tuyến tụy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚘', '{"9000": "7304.0", "Chữ Trung Quốc": "蚘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 蚘 | hồi | tượng hình | dị thể của 蛔 (giun đũa) | 蚘 là dị thể (異體) của 蛔, cùng chỉ giun đũa (roundworm). Thuộc bộ 虫 (sâu bọ). Không có phân tích thành tố độc lập so với 蛔.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồi\": bộ 虫 (sâu) + âm ''hồi'' (vòng) — con giun đũa uốn khúc vòng tròn trong ruột. | Gương Hán-Việt | hồi — trong từ 蛔蟲/蚘蟲 (giun đũa) | Mở khoá kiến thức | Biết 蚘/蛔 mở khoá từ y học: 蛔蟲 (hồi trùng — giun đũa), 驅蛔 (khu hồi — thuốc tẩy giun).", "Tự nguyên_Xie": "Theo Wiktionary, 蚘 là dị thể cổ của 蛔 (huí). 蛔 ghép 虫 (sâu bọ, biểu nghĩa) + 回 (hồi, biểu âm). Giun đũa (Ascaris) uốn lượn như ký hiệu 回 (vòng). Chữ 蚘 ghi nhận dạng cổ của cùng ký tự. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hồi (gdhn)\nTục dùng như chữ hồi 蛔.", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 尤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫尤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚘", "Unihan_Traditional (Chữ Phồn thể)": "蚘", "Pinyin_Xie": "huí", "Âm Hán Việt_Xie": "hồi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ chỉ ký sinh trùng trong ruột, thường dùng trong y học cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝺', '{"9000": "7305.0", "Chữ Trung Quốc": "蝺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 蝺 | cự | tượng hình | cao lớn (tính từ cổ dùng cho côn trùng/thú) | 蝺 thuộc bộ 虫 (sâu bọ, sinh vật). Wiktionary ghi nhận hai âm jǔ/qǔ và nghĩa ''cao lớn''. Không có phân tích thành tố chi tiết từ nguồn học thuật. Chữ cổ hiếm dùng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cự\": bộ 虫 + âm ''cự'' (to lớn) — sinh vật to lớn đồ sộ, chữ cổ hiếm gặp. | Gương Hán-Việt | cự — cổ văn, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 蝺 giúp nhận ra nhóm chữ cổ bộ 虫 với nghĩa đặc biệt trong văn ngôn.", "Tự nguyên_Xie": "Theo Wiktionary, 蝺 là chữ cổ (obs-std) mang nghĩa ''cao và to, đồ sộ''. Có hai âm đọc jǔ và qǔ. Trung cổ âm và thượng cổ âm được ghi nhận. Không có phân tích glyph chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Anaconda", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 禹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫禹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝺", "Unihan_Traditional (Chữ Phồn thể)": "蝺", "Pinyin_Xie": "qǔ", "Âm Hán Việt_Xie": "cự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài bò sát lớn, ít dùng trong văn bản hiện đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裀', '{"9000": "7306.0", "Chữ Trung Quốc": "裀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 11 | nét | 裀 | nhân | tượng hình | áo nhiều lớp; tấm thảm (cổ văn) | 裀 thuộc bộ 衣 (quần áo). Wiktionary không cung cấp phân tích thành tố chi tiết. Cấu trúc gợi ý hình thanh với 衣 biểu nghĩa. Trung cổ âm và thượng cổ âm được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhân\": bộ 衣 (áo) — nhiều lớp vải chồng lên như tấm đệm sang trọng, dùng trong xe ngựa quý tộc. | Gương Hán-Việt | nhân — trong từ 重裀 (nhiều lớp đệm), 車裀 (đệm xe) | Mở khoá kiến thức | Biết 裀 mở khoá từ cổ văn: 重裀疊褥 (nhung/nhân trùng — nhiều lớp đệm, ẩn dụ cuộc sống xa hoa), 列鼎重裀 (bày đỉnh đồng trải đệm dày — tiệc tùng quý tộc).", "Tự nguyên_Xie": "Theo Wiktionary, 裀 chỉ áo nhiều lớp hoặc dùng thay 茵 (tấm đệm/thảm). Thuộc bộ 衣. Gặp trong các từ như 車裀 (đệm xe), 重裀疊褥 (nhiều lớp đệm và chăn — ẩn dụ giàu sang). Chưa có phân tích glyph chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo lót mình; cái chiếu, cái đệm", "Hạng Tần Suất (Jun Da)": "7306.0", "Tần Suất % (Jun Da)": "99.998073425", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 因", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤因", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "因", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裀", "Unihan_Traditional (Chữ Phồn thể)": "裀", "Pinyin_Xie": "yīn", "Âm Hán Việt_Xie": "nhân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ đồ dùng để lót hoặc trải giường nằm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詧', '{"9000": "7307.0", "Chữ Trung Quốc": "詧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 13 | nét | 詧 | sát | tượng hình | xem xét, quan sát (cổ văn) | 詧 thuộc bộ 言 (lời, ngôn ngữ). Không có etymology glyph từ nguồn hiện có. Tiểu triện được ghi nhận qua hình ảnh. Cấu trúc gợi ý hình thanh với 言 biểu nghĩa. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sát\": bộ 言 (lời) — xem xét qua lời nói, tra khảo để hiểu rõ sự thật; gần nghĩa 察 (sát — xét). | Gương Hán-Việt | sát — gần với 察 (xem xét, quan sát) | Mở khoá kiến thức | Biết 詧 giúp nhận ra nhóm chữ bộ 言 chỉ hành động ngôn ngữ và quan sát trong cổ văn.", "Tự nguyên_Xie": "Tiểu triện | 詧 không có etymology glyph từ nguồn Wiktionary. Thuộc bộ 言 (lời/ngôn). Tiểu triện được ghi nhận qua hình ảnh từ hanziyuan. Nghĩa liên quan đến xem xét, quan sát, tra xét. Chưa có nguồn học thuật chi tiết về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem kỹ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "詧", "Unihan_Traditional (Chữ Phồn thể)": "詧", "Pinyin_Xie": "chá", "Âm Hán Việt_Xie": "sát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động quan sát kỹ lưỡng, đồng nghĩa với chữ sát 察. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踘', '{"9000": "7308.0", "Chữ Trung Quốc": "踘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 15 | nét | 踘 | guốc | tượng hình | dị thể của 鞠 (quả cầu da; đá cầu) | 踘 là dị thể (異體) của 鞠, thuộc bộ 足 (chân). Wiktionary xác nhận đây là dạng thay thế của 鞠 (guốc). Trong từ 蹴踘, chỉ trò chơi đá cầu cổ đại — tiền thân của bóng đá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"guốc\": bộ 足 (chân) + âm guốc — dùng chân đá quả cầu da, trò 蹴踘 tiền thân bóng đá Trung Hoa. | Gương Hán-Việt | guốc — trong từ 蹴踘 (đá cầu cổ) | Mở khoá kiến thức | Biết 踘 mở khoá từ thể thao cổ: 蹴踘 (guốc guốc — đá cầu da thời Hán/Đường), trò chơi của binh sĩ và quý tộc.", "Tự nguyên_Xie": "Theo Wiktionary, 踘 là dị thể của 鞠. 蹴踘 (cúc guốc) là trò chơi đá cầu da thời Hán — được xem là tiền thân của bóng đá. Bộ 足 (chân) gợi ý chữ liên quan đến hoạt động dùng chân. Trung cổ âm được ghi nhận. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quả bóng da", "Hạng Tần Suất (Jun Da)": "7308.0", "Tần Suất % (Jun Da)": "99.9980796264", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 匊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊匊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踘", "Unihan_Traditional (Chữ Phồn thể)": "踘", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "cúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ quả bóng da thời cổ, thường dùng trong trò chơi đá cầu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹷', '{"9000": "7309.0", "Chữ Trung Quốc": "蹷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 19 | nét | 蹷 | quyết | tượng hình | dị thể của 蹶 (vấp ngã; kiệt sức) | 蹷 là dị thể của 蹶, thuộc bộ 足 (chân). Wiktionary xác nhận đây là dạng thay thế của 蹶 (jué/qiào). Không có phân tích thành tố độc lập.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyết\": bộ 足 (chân) — chân vấp ngã gục xuống đất, kiệt sức không đứng dậy được. | Gương Hán-Việt | quyết — gần với 蹶 (ngã, kiệt sức) | Mở khoá kiến thức | Biết 蹷/蹶 mở khoá từ: 一蹶不振 (nhất quyết bất chấn — ngã một lần không gượng dậy được — bi quan).", "Tự nguyên_Xie": "Theo Wiktionary, 蹷 là dạng thay thế của 蹶 (quyết/qiào). 蹶 chỉ hành động vấp ngã, ngã sấp, hoặc kiệt sức. Bộ 足 (chân) gợi ý liên quan đến di chuyển. Trung cổ âm và thượng cổ âm được ghi nhận. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quệ; như \"kiệt quệ\" què; như \"què chân\" \n (Động) Ngã; té. \n§ Cũng như quyết 蹶.", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "厥 + 足", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厥足", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "足", "Unihan_Simplified (Chữ Giản thể)": "蹷", "Unihan_Traditional (Chữ Phồn thể)": "蹷", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ hành động vấp ngã hoặc tính từ chỉ trạng thái kiệt quệ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟓', '{"9000": "7310.0", "Chữ Trung Quốc": "蟓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 17 | nét | 蟓 | tượng | tượng hình | tằm hoặc sâu bướm (cổ văn) | 蟓 thuộc bộ 虫 (sâu bọ). Wiktionary ghi nhận nghĩa cổ là tằm (silkworm). Không có phân tích thành tố chi tiết từ nguồn học thuật. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tượng\": bộ 虫 (sâu) + âm ''tượng'' — con sâu lớn như voi (象), ám chỉ con tằm to béo nhả tơ. | Gương Hán-Việt | tượng — cổ văn chỉ tằm, hiếm dùng trong tiếng Việt | Mở khoá kiến thức | Biết 蟓 giúp nhận ra nhóm chữ bộ 虫 chỉ tằm và sâu bướm trong văn ngôn cổ.", "Tự nguyên_Xie": "Theo Wiktionary, 蟓 là chữ cổ (obs-std) chỉ con tằm (silkworm). Phiên âm xiàng, trung cổ và thượng cổ âm được ghi nhận. Không có phân tích glyph chi tiết. Chữ rất hiếm trong tiếng Hán hiện đại. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tằm; con tằm", "Hạng Tần Suất (Jun Da)": "7310.0", "Tần Suất % (Jun Da)": "99.9980837607", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 象", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫象", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "象", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟓", "Unihan_Traditional (Chữ Phồn thể)": "蟓", "Pinyin_Xie": "xiàng", "Âm Hán Việt_Xie": "tượng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại côn trùng giống tằm ăn lá cây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盦', '{"9000": "7311.0", "Chữ Trung Quốc": "盦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 16 | nét | 盦 | am | tượng hình | vật đựng hình vòm; am tu (hội ý) | 盦 thuộc bộ 皿 (bát đĩa, đồ đựng). Giáp cốt văn và tiểu triện được ghi nhận — chữ có lịch sử glyph dài. Cấu trúc gợi ý hội ý: vật đựng hình vòm dùng để che phủ hoặc chôn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"am\": bộ 皿 (đồ đựng) hình vòm — cái nắp bát úp xuống, giống mái vòm của am thờ nhỏ. | Gương Hán-Việt | am — trong nghĩa 庵 (am tu, cái am); dùng trong văn ngôn | Mở khoá kiến thức | Biết 盦 mở khoá từ cổ văn: dùng thay 庵 (am — chùa nhỏ hình tròn), và hiểu nhóm từ đồ đựng cổ.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Theo Wiktionary, 盦 thuộc bộ 皿 (đồ đựng). Giáp cốt văn (nguồn hanziyuan) và tiểu triện được ghi nhận — đây là chữ có lịch sử rất cổ. Nghĩa gồm: vật đựng hình vòm, dạng thay thế của 庵 (am tu hình tròn), che phủ, và chôn vùi (trong từ điển cổ). Chữ cổ hiếm. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái ang", "Hạng Tần Suất (Jun Da)": "7311.0", "Tần Suất % (Jun Da)": "99.9980858279", "GavinGrover_Once (Chiết tự trực tiếp)": "酓 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱酓皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "酓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盦", "Unihan_Traditional (Chữ Phồn thể)": "盦", "Pinyin_Xie": "ān", "Âm Hán Việt_Xie": "am", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ đồ đựng hoặc động từ chỉ hành động úp, đậy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞆', '{"9000": "7312.0", "Chữ Trung Quốc": "瞆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 14 | nét | 瞆 | quỹ | tượng hình | mắt mờ (cổ văn) | 瞆 thuộc bộ 目 (mắt). Không có etymology glyph từ nguồn hiện có. Cấu trúc gợi ý hình thanh với 目 biểu nghĩa (mắt) và phần còn lại biểu âm. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỹ\": bộ 目 (mắt) + âm ''quỹ'' — đôi mắt mờ tối, không nhìn thấy rõ ràng. | Gương Hán-Việt | quỹ — cổ văn chỉ mắt mờ, hiếm dùng | Mở khoá kiến thức | Biết 瞆 giúp nhận ra nhóm chữ bộ 目 chỉ tình trạng thị lực trong y học và văn ngôn cổ.", "Tự nguyên_Xie": "瞆 không có etymology glyph từ nguồn Wiktionary. Thuộc bộ 目 (mắt), chỉ trạng thái mắt mờ, mắt tối. Không có phân tích thành tố chi tiết. Chưa có nguồn học thuật chi tiết về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mắt không có con ngươi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 贵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目贵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞆", "Unihan_Traditional (Chữ Phồn thể)": "瞆", "Pinyin_Xie": "kuì", "Âm Hán Việt_Xie": "quý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả trạng thái mắt bị mờ hoặc mù lòa. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矰', '{"9000": "7313.0", "Chữ Trung Quốc": "矰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 矢 | Số nét | 17 | nét | 矢 | thỉ | biểu nghĩa | mũi tên | 曾 | tằng | biểu âm | (biểu âm) | 矰 là chữ hình thanh (psc): 矢 (Thỉ, biểu nghĩa: mũi tên) + 曾 (Tằng, biểu âm). Chữ chỉ loại mũi tên cổ dùng để bắn chim, có dây lụa buộc vào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tăng\": 矢 (tên) + Tằng (âm) — mũi tên có dây lụa buộc, bắn chim trên không rồi kéo về. | Gương Hán-Việt | tăng — trong từ 矰繳 (mũi tên và dây bắt chim) | Mở khoá kiến thức | Biết 矰 mở khoá từ săn bắn cổ: 矰弋 (tăng dặc — vũ khí bắt chim bay), 矰繳 (mũi tên có dây), ẩn dụ bẫy và cạm bẫy trong văn học.", "Tự nguyên_Xie": "Bạch thư | Đại triện | Tiểu triện | Theo Wiktionary, 矰 ghép 矢 (mũi tên, biểu nghĩa) + 曾 (biểu âm). Bạch thư, đại triện và tiểu triện đều ghi nhận. Chữ chỉ loại mũi tên cổ (zēng) có buộc dây lụa để thu hồi sau khi bắn chim. Dùng trong từ 矰繳 (dây và mũi tên bắt chim). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mũi tên có tua bằng tơ", "Hạng Tần Suất (Jun Da)": "7313.0", "Tần Suất % (Jun Da)": "99.9980899621", "GavinGrover_Once (Chiết tự trực tiếp)": "矢 + 曾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰矢曾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "矢", "Unihan_Simplified (Chữ Giản thể)": "矰", "Unihan_Traditional (Chữ Phồn thể)": "矰", "Pinyin_Xie": "zēng", "Âm Hán Việt_Xie": "tăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại tên cổ dùng để bắn chim rồi thu dây lại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磥', '{"9000": "7314.0", "Chữ Trung Quốc": "磥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 16 | nét | 磥 | luy | tượng hình | đá chồng chất (cổ văn) | 磥 thuộc bộ 石 (đá). Wiktionary chỉ ghi nhận etymology template, không có phân tích chi tiết. Cấu trúc bộ 石 gợi ý liên quan đến đá hoặc núi đá. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"luy\": bộ 石 (đá) + âm luy — tảng đá chồng chất lên nhau như thành lũy, vững chắc và nặng nề. | Gương Hán-Việt | luy — gần với 磊 (lěi — nhiều đá), 壘 (luy — chồng lên) | Mở khoá kiến thức | Biết 磥 giúp nhận ra nhóm âm lěi chỉ sự chồng chất: 磊磊 (nhiều đá), 壘 (thành lũy), 累 (tích lũy).", "Tự nguyên_Xie": "磥 thuộc bộ 石 (đá), chỉ đá chồng chất, tảng đá lớn. Wiktionary ghi nhận {{Han etym}} nhưng không có phân tích glyph chi tiết. Cùng âm lěi với 壘 (chồng lên), 磊 (nhiều đá), gợi ý nhóm chữ âm lěi chỉ sự chồng chất. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một đống đá; đá cuội", "Hạng Tần Suất (Jun Da)": "7314.0", "Tần Suất % (Jun Da)": "99.9980920293", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 累", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石累", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "累", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磥", "Unihan_Traditional (Chữ Phồn thể)": "磥", "Pinyin_Xie": "lěi", "Âm Hán Việt_Xie": "lỗi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ để chỉ đống đá hoặc đá cuội trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祮', '{"9000": "7315.0", "Chữ Trung Quốc": "祮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 10 | nét | 祮 | cáo | tượng hình | lễ tế cáo tri (cổ văn) | 祮 thuộc bộ 示 (thần linh, tế lễ). Không có etymology glyph từ nguồn hiện có. Cấu trúc bộ 示 gợi ý liên quan đến nghi lễ tôn giáo. Cùng âm gào với 誥 (cáo — thông báo). Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cáo\": bộ 示 (tế lễ) + âm ''cáo'' — lễ cáo tri thần linh, báo với trời đất về sự kiện quan trọng. | Gương Hán-Việt | cáo — cổ văn nghi lễ, ít dùng | Mở khoá kiến thức | Biết 祮 giúp nhận ra nhóm chữ bộ 示 liên quan đến lễ tế và nghi lễ cổ đại trong văn ngôn.", "Tự nguyên_Xie": "祮 không có etymology glyph từ nguồn Wiktionary. Thuộc bộ 示 (tế lễ, thần linh), cùng âm gào với 誥, gợi ý nghĩa cáo tri thần linh trong lễ tế. Không có phân tích thành tố chi tiết. Chưa có nguồn học thuật chi tiết về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "祮", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 吉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻吉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祮", "Unihan_Traditional (Chữ Phồn thể)": "祮", "Pinyin_Xie": "gào", "Âm Hán Việt_Xie": "cáo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này chủ yếu dùng làm động từ trong các văn bản cổ chỉ hành động quét dọn hoặc tế lễ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稛', '{"9000": "7316.0", "Chữ Trung Quốc": "稛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 13 | nét | 稛 | khổn | tượng hình | bó lúa chất đầy (cổ văn) | 稛 thuộc bộ 禾 (cây lúa). Không có etymology glyph từ nguồn hiện có. Cấu trúc bộ 禾 gợi ý liên quan đến ngũ cốc, lúa má. Cùng âm kǔn với 捆 (bó lại). Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khổn\": bộ 禾 (lúa) + âm khổn (bó) — bó lúa chất đầy kho sau mùa gặt. | Gương Hán-Việt | khổn — cổ văn ngũ cốc, ít dùng | Mở khoá kiến thức | Biết 稛 giúp nhận ra nhóm chữ bộ 禾 chỉ thu hoạch và bảo quản lúa trong nông nghiệp cổ.", "Tự nguyên_Xie": "稛 không có etymology glyph từ nguồn Wiktionary. Thuộc bộ 禾 (lúa), cùng âm kǔn với 捆 (bó), gợi ý nghĩa bó lúa hoặc chất đống lúa. Không có phân tích thành tố chi tiết. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đầy", "Hạng Tần Suất (Jun Da)": "7316.0", "Tần Suất % (Jun Da)": "99.9980961636", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 囷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾囷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "囷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稛", "Unihan_Traditional (Chữ Phồn thể)": "稛", "Pinyin_Xie": "kǔn", "Âm Hán Việt_Xie": "khổn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ chỉ sự đầy đủ hoặc động từ với nghĩa bó buộc, thu gom. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箾', '{"9000": "7317.0", "Chữ Trung Quốc": "箾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 15 | nét | 箾 | thước | tượng hình | sáo trúc cổ; cây gậy | 箾 thuộc bộ 竹 (tre, trúc). Không có etymology glyph từ nguồn hiện có. Cấu trúc bộ 竹 gợi ý liên quan đến nhạc cụ làm từ tre hoặc vật dụng bằng trúc. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thước\": bộ 竹 (trúc) + âm thước — sáo trúc cổ hoặc cây gậy trúc, âm thanh vút cao như tiếng chim thước. | Gương Hán-Việt | thước — cổ văn nhạc cụ trúc, ít dùng | Mở khoá kiến thức | Biết 箾 giúp nhận ra nhóm chữ bộ 竹 chỉ nhạc cụ và vật dụng bằng trúc trong văn ngôn cổ.", "Tự nguyên_Xie": "箾 không có etymology glyph từ nguồn Wiktionary. Thuộc bộ 竹 (tre), gợi ý liên quan đến nhạc cụ hoặc vật dụng từ trúc. Âm shuò tương ứng với một số chữ cùng âm. Không có phân tích thành tố chi tiết. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tiêu thiều 箾韶)", "Hạng Tần Suất (Jun Da)": "7317.0", "Tần Suất % (Jun Da)": "99.9980982307", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 削", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮削", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "削", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箾", "Unihan_Traditional (Chữ Phồn thể)": "箾", "Pinyin_Xie": "shuò", "Âm Hán Việt_Xie": "sóc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ một loại nhạc cụ bằng tre thời cổ hoặc động từ chỉ hành động gõ, đánh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翂', '{"9000": "7318.0", "Chữ Trung Quốc": "翂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 10 | nét | 羽 | vũ | biểu nghĩa | lông vũ, cánh | 分 | phân | biểu âm | chia, phân (biểu âm) | 翂 là chữ hình thanh (psc): 羽 (Vũ, biểu nghĩa: lông vũ/cánh) + 分 (Phân, biểu âm). Chữ chỉ chim bay nhẹ nhàng hoặc lông vũ phất phơ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phân\": 羽 (lông vũ) + Phân (âm) — những cánh lông vũ phất phơ phân tán trong gió khi chim bay lên. | Gương Hán-Việt | phân — trong từ cổ chỉ chim bay | Mở khoá kiến thức | Biết 翂 giúp nhận ra nhóm chữ bộ 羽 chỉ chim bay và lông vũ trong thơ văn cổ.", "Tự nguyên_Xie": "Theo Wiktionary, 翂 ghép 羽 (lông vũ/cánh, biểu nghĩa) + 分 (biểu âm). Không có hình ảnh glyph cổ từ nguồn hiện có. Chữ chỉ chim bay hay lông vũ phất phơ. Chưa có phân tích chi tiết hơn từ nguồn học thuật. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "羽 + 分", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰羽分", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翂", "Unihan_Traditional (Chữ Phồn thể)": "翂", "Pinyin_Xie": "fēn", "Âm Hán Việt_Xie": "phân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ dưới dạng từ láy để miêu tả dáng bay lượn của loài chim. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胊', '{"9000": "7319.0", "Chữ Trung Quốc": "胊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 9 | nét | 胊 | cúc | tượng hình | phần thịt ở khuỷu tay (cổ văn) | 胊 thuộc bộ 月/肉 (thịt, cơ thể). Không có etymology glyph từ nguồn hiện có. Cấu trúc bộ 肉 gợi ý liên quan đến bộ phận cơ thể. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cúc\": bộ 月/肉 (thịt) + âm ''cúc'' — phần thịt gồ lên ở khớp khuỷu tay, như bông cúc tròn. | Gương Hán-Việt | cúc — cổ văn giải phẫu, ít dùng | Mở khoá kiến thức | Biết 胊 giúp nhận ra nhóm chữ bộ 肉 chỉ các bộ phận cơ thể trong y học và văn ngôn cổ.", "Tự nguyên_Xie": "胊 không có etymology glyph từ nguồn Wiktionary. Thuộc bộ 月/肉 (thịt, cơ thể), chỉ phần thịt ở khuỷu tay hoặc một bộ phận cơ thể. Không có phân tích thành tố chi tiết. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ách", "Hạng Tần Suất (Jun Da)": "7319.0", "Tần Suất % (Jun Da)": "99.998102365", "GavinGrover_Once (Chiết tự trực tiếp)": "⺼ + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⺼句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺼", "Unihan_Simplified (Chữ Giản thể)": "胊", "Unihan_Traditional (Chữ Phồn thể)": "胊", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "cù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ miếng thịt khô còn xương hoặc bộ phận cái ách trâu bò. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓺', '{"9000": "7320.0", "Chữ Trung Quốc": "蓺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 埶 | nghệ | biểu âm | trồng trọt (biểu âm) | 蓺 là chữ hình thanh (psc): 艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 埶 (Nghệ, biểu âm). Chữ chỉ hành động trồng trọt, gieo trồng. Gần nghĩa và âm với 藝 (nghệ — nghề, nghệ thuật).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghệ\": 艹 (cây) + Nghệ (âm) — bàn tay khéo léo trồng cây, từ đó mở rộng sang 藝 (nghệ thuật, kỹ năng). | Gương Hán-Việt | nghệ — liên hệ với 藝 (kỹ nghệ, nghệ thuật) | Mở khoá kiến thức | Biết 蓺 mở khoá từ: 藝 (nghệ — nghệ thuật, kỹ năng), 農藝 (nông nghệ — kỹ thuật nông nghiệp), 才藝 (tài nghệ).", "Tự nguyên_Xie": "Theo Wiktionary, 蓺 ghép 艹 (cỏ/thực vật, biểu nghĩa) + 埶 (biểu âm, đọc yì). Nghĩa gốc là gieo trồng (thực vật). Liên hệ với 藝 (nghệ — kỹ năng/nghề, từ nghĩa trồng trọt mở rộng sang nghệ thuật). Chưa có hình ảnh glyph từ nguồn hiện có. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trồng cây; tài năng", "Hạng Tần Suất (Jun Da)": "7320.0", "Tần Suất % (Jun Da)": "99.9981044321", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 埶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹埶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "埶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓺", "Unihan_Traditional (Chữ Phồn thể)": "蓺", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "nghệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc trồng trọt hoặc danh từ chỉ tài năng, nghệ thuật trong văn cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薾', '{"9000": "7321.0", "Chữ Trung Quốc": "薾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 17 | nét | 薾 | nhi | tượng hình | cây cỏ xum xuê tươi tốt (cổ văn) | 薾 thuộc bộ 艹 (cỏ, thực vật). Wiktionary ghi nhận phiên âm ěr và nghĩa ''xum xuê, tươi tốt''. Không có phân tích thành tố chi tiết. Trung cổ âm và thượng cổ âm được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhi\": bộ 艹 (cỏ) + âm ''nhi'' — cỏ cây nhi nhúc xum xuê, tươi tốt mùa xuân. | Gương Hán-Việt | nhi — cổ văn chỉ cây cỏ tươi tốt | Mở khoá kiến thức | Biết 薾 giúp nhận ra nhóm chữ bộ 艹 chỉ trạng thái thực vật trong thơ văn cổ điển.", "Tự nguyên_Xie": "Theo Wiktionary, 薾 là tính từ cổ (obsolete) chỉ cây cỏ xum xuê, tươi tốt. Phiên âm ěr, trung cổ âm và thượng cổ âm được ghi nhận đầy đủ. Không có phân tích glyph chi tiết từ nguồn học thuật. Chữ cổ hiếm dùng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoa cỏ rậm rạp tốt tươi; yếu ớt", "Hạng Tần Suất (Jun Da)": "7321.0", "Tần Suất % (Jun Da)": "99.9981064993", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 爾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹爾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薾", "Unihan_Traditional (Chữ Phồn thể)": "薾", "Pinyin_Xie": "ěr", "Âm Hán Việt_Xie": "nhĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Dùng làm tính từ để miêu tả trạng thái hoa lá sum suê hoặc vẻ mềm yếu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('襱', '{"9000": "7322.0", "Chữ Trung Quốc": "襱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 21 | nét | 襱 | lung | tượng hình | quần (cổ văn); cạp quần | 襱 thuộc bộ 衣 (quần áo). Wiktionary ghi nhận nghĩa văn ngôn: quần, cạp quần, váy. Không có phân tích thành tố chi tiết. Trung cổ âm và thượng cổ âm được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lung\": bộ 衣 (áo) + âm lung — phần áo che kín như ống long — cạp quần hoặc phần bẹn. | Gương Hán-Việt | lung — cổ văn trang phục, ít dùng | Mở khoá kiến thức | Biết 襱 giúp nhận ra nhóm chữ bộ 衣 chỉ các bộ phận quần áo trong văn ngôn cổ.", "Tự nguyên_Xie": "Theo Wiktionary, 襱 là chữ văn ngôn (obs-std) bộ 衣, chỉ quần, phần cạp/bẹn của quần, và váy. Trung cổ âm và thượng cổ âm được ghi nhận. Không có phân tích glyph chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "豱", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 龍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤龍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "襱", "Unihan_Traditional (Chữ Phồn thể)": "襱", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "lung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại ống quần hoặc trang phục thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('覅', '{"9000": "7323.0", "Chữ Trung Quốc": "覅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 襾 | Số nét | 13 | nét | 覅 | phiếu | tượng hình | đừng (phương ngữ Ngô/Thượng Hải) | 覅 là chữ tạo muộn (後起字) đặc trưng phương ngữ Ngô (Wu Chinese/Shanghai). Wiktionary không có phân tích thành tố. Âm fiào đặc trưng của tiếng Thượng Hải. Chữ này là dạng viết riêng cho từ ''đừng'' trong phương ngữ Ngô.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiếu\": chữ tạo muộn riêng cho phương ngữ Thượng Hải — ''fiào'' nghĩa là ''đừng!'' khi nói chuyện hằng ngày ở Thượng Hải. | Gương Hán-Việt | phiếu — phương ngữ Ngô, không có từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 覅 giúp nhận ra đặc trưng tiếng Thượng Hải: 覅 (fiào) = ''đừng'' — từ này chỉ tồn tại trong văn viết phương ngữ Ngô.", "Tự nguyên_Xie": "覅 không có etymology glyph từ nguồn Wiktionary. Đây là chữ phương ngữ Ngô (Thượng Hải) chỉ nghĩa ''đừng'' (phủ định mệnh lệnh). Âm fiào là đặc trưng của tiếng Thượng Hải. Chữ tạo muộn, không có lịch sử glyph cổ. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sự co lại của 勿 要; không được; làm ơn đừng", "Hạng Tần Suất (Jun Da)": "7323.0", "Tần Suất % (Jun Da)": "99.9981106335", "GavinGrover_Once (Chiết tự trực tiếp)": "要 + 勿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰要勿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "要", "Unihan_Simplified (Chữ Giản thể)": "覅", "Unihan_Traditional (Chữ Phồn thể)": "覅", "Pinyin_Xie": "fiào", "Âm Hán Việt_Xie": "vật, yếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Thường đứng trước động từ làm phó từ phủ định trong khẩu ngữ phương ngôn để khuyên ngăn. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讏', '{"9000": "7324.0", "Chữ Trung Quốc": "讏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 23 | nét | 讏 | tượng hình | chữ độc lập, bộ 言 (ngôn) chỉ lời nói ngông xằng | 讏 là chữ hiếm, cấu tạo chưa có phân tích lục thư rõ ràng. Bộ 言 (Ngôn) gợi liên quan đến lời nói. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vị\": chữ 讏 mang bộ 言 (lời nói) — hình ảnh miệng nói những lời ngông xằng, xằng bậy không ai nghe được. | Gương Hán-Việt | \"vị\" — đọc Hán-Việt của 讏, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 讏 mở khoá nhóm chữ bộ 言 chỉ lời nói sai lệch, ngông cuồng", "Tự nguyên_Xie": "Chưa có nguồn glyph-origin từ Wiktionary. Căn cứ vào bộ thủ 言 (ngôn, lời nói) và nghĩa ''ngông xằng, xằng bậy'', chữ này liên quan đến lời nói sai trái, ngông cuồng. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngông xằng; xằng bậy", "Hạng Tần Suất (Jun Da)": "7324.0", "Tần Suất % (Jun Da)": "99.9981127007", "GavinGrover_Once (Chiết tự trực tiếp)": "衞 + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱衞言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "衞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "讏", "Unihan_Traditional (Chữ Phồn thể)": "讏", "Pinyin_Xie": "wèi", "Âm Hán Việt_Xie": "vệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Dùng làm danh từ chỉ lời nói dối hoặc tính từ chỉ sự xằng bậy, không chân thật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跅', '{"9000": "7325.0", "Chữ Trung Quốc": "跅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 12 | nét | 跅 | tượng hình | chữ hiếm, bộ 足 (túc) chỉ chân/hành động đi lại phóng túng | 跅 là chữ hiếm, bộ 足 (Túc, chân) gợi liên quan đến hành động di chuyển hoặc lối sống phóng túng. Chưa có phân tích lục thư từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thác\": chữ 跅 bộ 足 (chân) — hình ảnh đôi chân bước tự do không theo khuôn phép, tượng trưng cho lối sống phóng túng. | Gương Hán-Việt | \"thác\" — đọc Hán-Việt của 跅, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 跅 mở khoá nhóm chữ bộ 足 chỉ hành vi, lối đi phóng túng", "Tự nguyên_Xie": "Không có glyph-origin từ Wiktionary. Bộ 足 (túc, chân) gợi ý hành vi đi lại tự do, không bị ràng buộc. Nghĩa ''phóng túng, không chịu giữ mình'' phù hợp với hình tượng chân bước không theo lề lối. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phóng túng, không chịu giữ mình", "Hạng Tần Suất (Jun Da)": "7325.0", "Tần Suất % (Jun Da)": "99.9981147678", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 斥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊斥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跅", "Unihan_Traditional (Chữ Phồn thể)": "跅", "Pinyin_Xie": "tuò", "Âm Hán Việt_Xie": "thác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho hành vi, tính cách phóng khoáng, không tuân theo quy củ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踆', '{"9000": "7326.0", "Chữ Trung Quốc": "踆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 14 | nét | 踆 | tượng hình | chữ bộ 足, có nhiều âm đọc: đá (cūn), lui (qūn), ngồi xổm (dūn) | 踆 là chữ bộ 足 (Túc, chân), mang nhiều nghĩa theo âm đọc khác nhau. Wiktionary ghi nhận ba âm đọc nhưng không phân tích rõ cấu trúc lục thư. Chưa rõ hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tồn\": chữ 踆 bộ 足 (chân) — một chân đá ra (cūn), hoặc chân bước lùi (qūn), hoặc khom xuống ngồi xổm (dūn). | Gương Hán-Việt | \"tồn\" — đọc Hán-Việt của 踆, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 踆 mở khoá nhóm chữ bộ 足 chỉ hành động chân: đá, lui, ngồi xổm", "Tự nguyên_Xie": "Wiktionary ghi nhận ba cách đọc: cūn/cún (đá), qūn (lui, rút lui), dūn (dạng khác của 蹲, ngồi xổm). Bộ 足 (chân) là chỉ hành động liên quan đến chân. Chưa có nguồn học thuật xác nhận cấu trúc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá; đuổi; tống cổ; lui; dừng; hoãn; lùi; rút lui", "Hạng Tần Suất (Jun Da)": "7326.0", "Tần Suất % (Jun Da)": "99.998116835", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 夋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊夋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踆", "Unihan_Traditional (Chữ Phồn thể)": "踆", "Pinyin_Xie": "cūn", "Âm Hán Việt_Xie": "tồn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ chỉ hành động lùi bước hoặc ngồi xổm trong văn ngôn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹔', '{"9000": "7327.0", "Chữ Trung Quốc": "蹔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 18 | nét | 蹔 | tượng hình | chữ bộ 足, nghĩa tạm thời, chốc lát | 蹔 là chữ bộ 足 (Túc, chân), gợi hành động ngắn ngủi thoáng qua. Wiktionary chỉ ghi {{Han etym}} không có phân tích chi tiết. Nghĩa ''tạm thời'' có thể liên hệ với hành động dừng chân nhất thời. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tạm\": chữ 蹔 bộ 足 (chân) — hình ảnh chân dừng lại tạm thời, chỉ một chốc rồi lại tiếp tục bước. | Gương Hán-Việt | \"tạm\" — đọc Hán-Việt của 蹔, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 蹔 mở khoá nhóm chữ chỉ tính chất tạm thời, ngắn ngủi trong văn ngôn", "Tự nguyên_Xie": "Đại triện | Wiktionary chỉ ghi nhận {{Han etym}} không có gloss cụ thể. Bộ 足 (chân) kết hợp với nghĩa ''tạm thời, chốc lát'' gợi hình tượng bước chân dừng lại một lúc rồi tiếp tục. Có hình đại triện. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tạm thời", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "斬 + 足", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱斬足", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "足", "Unihan_Simplified (Chữ Giản thể)": "蹔", "Unihan_Traditional (Chữ Phồn thể)": "蹔", "Pinyin_Xie": "zàn", "Âm Hán Việt_Xie": "tạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Chữ này thường làm phó từ đứng trước động từ để chỉ hành động diễn ra trong thời gian ngắn. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軐', '{"9000": "7328.0", "Chữ Trung Quốc": "軐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 10 | nét | 軐 | tượng hình | chữ bộ 車, nghĩa không rõ | 軐 là chữ bộ 車 (Xa, xe), gợi liên quan đến xe cộ. Wiktionary chỉ ghi {{Han etym}}, không có phân tích chi tiết. Nghĩa cụ thể không rõ. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tín\": chữ 軐 bộ 車 (xe) — một bộ phận hoặc đặc tính nào đó của xe, nghĩa cụ thể chưa rõ. | Gương Hán-Việt | \"tín\" — đọc Hán-Việt của 軐, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 軐 mở khoá nhóm chữ bộ 車 chỉ xe và bộ phận xe trong văn ngôn", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} không có gloss. Bộ 車 (xa, xe) gợi liên quan đến xe hoặc bộ phận xe. Nghĩa 萻 trong dữ liệu là ký hiệu không rõ. Chữ tạo muộn, chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "萻", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 卂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車卂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "軐", "Unihan_Traditional (Chữ Phồn thể)": "軐", "Pinyin_Xie": "xìn", "Âm Hán Việt_Xie": "tín", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một bộ phận của xe ngựa cổ trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轪', '{"9000": "7329.0", "Chữ Trung Quốc": "轪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 7 | nét | 轪 | tượng hình | chữ bộ 車 (xe), nghĩa nắp moay, bánh xe, dùng trong địa danh | 轪 là chữ bộ 車 (Xa, xe), theo Wiktionary (dạng truyền thống 軑) nghĩa là nắp moay xe (hubcap) hoặc bánh xe, cũng dùng trong địa danh. Cấu trúc lục thư không được phân tích rõ. Có hình tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đại\": chữ 轪 bộ 車 (xe) — hình ảnh nắp moay bánh xe, bộ phận bảo vệ trục giữa bánh xe. | Gương Hán-Việt | \"đại\" — đọc Hán-Việt của 轪, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 轪 mở khoá nhóm chữ bộ 車 chỉ bộ phận xe cộ trong văn ngôn và địa danh cổ", "Tự nguyên_Xie": "Tiểu triện | Wiktionary (dạng 軑) ghi nhận: nghĩa là nắp moay xe (hubcap), bánh xe, và dùng trong địa danh. Bộ 車 (xa, xe) là thành phần biểu nghĩa. Có tiểu triện. Chưa có phân tích hình thanh/hội ý cụ thể. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bánh xe; đại", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 大", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车大", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "大", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "轪", "Unihan_Traditional (Chữ Phồn thể)": "轪", "Pinyin_Xie": "dài", "Âm Hán Việt_Xie": "đại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cái bao trục bánh xe thời cổ hoặc dùng trong tên đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄤', '{"9000": "7330.0", "Chữ Trung Quốc": "鄤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 13 | nét | 鄤 | tượng hình | chữ bộ 邑, tên địa điểm ở Hà Nam | 鄤 là chữ bộ 邑 (Ấp, làng/vùng đất), chỉ một địa danh ở tỉnh Hà Nam, Trung Quốc. Không có phân tích lục thư từ Wiktionary. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạn\": chữ 鄤 bộ 邑 (ấp, làng) — một địa danh cổ ở tỉnh Hà Nam, Trung Quốc, nay ít ai nhắc đến. | Gương Hán-Việt | \"mạn\" — đọc Hán-Việt của 鄤, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 鄤 mở khoá nhóm chữ bộ 邑 chỉ địa danh cổ vùng Hà Nam", "Tự nguyên_Xie": "Không có glyph-origin từ Wiktionary. Bộ 邑 (ấp) chỉ địa danh, cách dùng phổ biến cho các chữ chỉ tên đất cổ ở Trung Quốc. 鄤 chỉ một địa điểm ở Hà Nam. Chữ tạo muộn, chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên địa điểm", "Hạng Tần Suất (Jun Da)": "7330.0", "Tần Suất % (Jun Da)": "99.9981251035", "GavinGrover_Once (Chiết tự trực tiếp)": "曼 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰曼阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄤", "Unihan_Traditional (Chữ Phồn thể)": "鄤", "Pinyin_Xie": "màn", "Âm Hán Việt_Xie": "mạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ riêng chỉ địa danh cổ hoặc họ người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醰', '{"9000": "7331.0", "Chữ Trung Quốc": "醰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 19 | nét | 醰 | tượng hình | chữ bộ 酉, chỉ vị đắng trong rượu, rượu đậm vị | 醰 là chữ bộ 酉 (Dậu, rượu), chỉ vị đắng hoặc vị đậm đà trong rượu. Wiktionary ghi nhận âm đọc nhưng không phân tích cấu trúc lục thư. Có hình tiểu triện. Chưa rõ hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đàm\": chữ 醰 bộ 酉 (rượu) — hình ảnh chén rượu đậm vị, hậu vị đắng nồng, uống vào thấy đầy đủ hương. | Gương Hán-Việt | \"đàm\" — đọc Hán-Việt của 醰, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 醰 mở khoá nhóm chữ bộ 酉 chỉ tính chất, vị của rượu trong văn ngôn", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận âm tán/taam4, nghĩa ''vị đắng trong rượu, rượu đậm vị''. Bộ 酉 (dậu, rượu) là thành phần biểu nghĩa rõ ràng. Có tiểu triện. Chưa có phân tích hình thanh/hội ý cụ thể từ nguồn học thuật. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rượu đắng", "Hạng Tần Suất (Jun Da)": "7331.0", "Tần Suất % (Jun Da)": "99.9981271707", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 覃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉覃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "覃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醰", "Unihan_Traditional (Chữ Phồn thể)": "醰", "Pinyin_Xie": "tán", "Âm Hán Việt_Xie": "đàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ bổ nghĩa cho rượu hoặc đồ uống có hương vị đậm đà. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鑟', '{"9000": "7332.0", "Chữ Trung Quốc": "鑟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 23 | nét | 金 | kim | biểu nghĩa | kim loại | 𧸇 | biểu âm | thành phần biểu âm | 鑟 = 金 (Kim, biểu nghĩa: kim loại) + 𧸇 (biểu âm, cho âm dú); chữ hình thanh. Bộ 金 cho biết nghĩa liên quan đến kim loại, phần 𧸇 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"độc\": chữ 鑟 hình thanh — bộ 金 (kim loại) + 𧸇 (âm dú); hình ảnh chiếc hộp kim loại đựng ấn triện của quan lại. | Gương Hán-Việt | \"độc\" — đọc Hán-Việt của 鑟, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 鑟 mở khoá nhóm chữ bộ 金 chỉ đồ vật kim loại dùng trong nghi lễ, triều đình cổ", "Tự nguyên_Xie": "Wiktionary phân tích: hình thanh tự (psc) — 金 (kim, kim loại) là thành phần biểu nghĩa, 𧸇 là thành phần biểu âm. Nghĩa là hộp đựng ấn triện (seal box), một đồ vật làm bằng kim loại dùng để đựng con dấu. Chữ chuyên dụng, ít gặp ngoài văn cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đục; như \"dùi đục; đục đẽo; đục khoét\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 賣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金賣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "賣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鑟", "Unihan_Traditional (Chữ Phồn thể)": "鑟", "Pinyin_Xie": "dú", "Âm Hán Việt_Xie": "đốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ dụng cụ đục hoặc làm động từ chỉ hành động đục đẽo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铔', '{"9000": "7333.0", "Chữ Trung Quốc": "铔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铔 | tượng hình | dạng giản thể của 錏, chỉ amoni trong hoá học | 铔 là dạng giản thể của 錏 (釒→钅, 亞→亚). Theo Wiktionary, 铔 tra về 錏. Bộ 钅 (kim loại) + 亚 (biểu âm/nghĩa). Nghĩa hiện đại: amoni (NH₄⁺) trong hoá học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"á\": chữ 铔 dạng giản thể của 錏, bộ 钅 (kim) + 亚 — hình ảnh ký hiệu hoá học NH₄⁺ mà người Trung Quốc gọi là 铔 (amoni). | Gương Hán-Việt | \"á\" — đọc Hán-Việt của 铔, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 铔 mở khoá nhóm chữ bộ 钅 dùng trong thuật ngữ hoá học hiện đại", "Tự nguyên_Xie": "Wiktionary ghi 铔 là dạng giản hoá của 錏 (釒→钅, 亞→亚). 錏 theo truyền thống chỉ thép mềm; trong tiếng Trung hiện đại, 铔 được dùng để phiên âm ''amoni'' (ammonium) trong hoá học. Bộ 钅 (kim loại) là thành phần gốc. Đây là chữ tạo mới để phục vụ thuật ngữ khoa học hiện đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên gọi cũ của amoni (hoá học)", "Hạng Tần Suất (Jun Da)": "7333.0", "Tần Suất % (Jun Da)": "99.998131305", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 亚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅亚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铔", "Unihan_Traditional (Chữ Phồn thể)": "錏", "Pinyin_Xie": "yà", "Âm Hán Việt_Xie": "a", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong thuật ngữ hóa học cổ để chỉ hợp chất amoni. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('閛', '{"9000": "7334.0", "Chữ Trung Quốc": "閛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 13 | nét | 閛 | tượng hình | chữ bộ 門, chỉ tiếng đóng cửa cót két | 閛 là chữ bộ 門 (Môn, cửa), mô phỏng âm thanh tiếng đóng cửa cót két (pēng). Wiktionary ghi nhận âm đọc nhưng không phân tích cấu trúc lục thư. Chưa rõ hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bành\": chữ 閛 bộ 門 (cửa) — âm pēng gợi ngay tiếng cửa đóng sầm, cót két. | Gương Hán-Việt | \"bành\" — đọc Hán-Việt của 閛, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 閛 mở khoá nhóm chữ bộ 門 chỉ âm thanh cửa, trạng thái cửa trong văn ngôn", "Tự nguyên_Xie": "Wiktionary ghi nhận âm pēng/pèng, nghĩa không rõ (rfdef). Bộ 門 (môn, cửa) gợi liên quan đến cửa. Nghĩa dân gian ''tiếng đóng cửa cót két'' phù hợp với bộ thủ. Có âm đọc trung cổ. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng đóng cửa cót két", "Hạng Tần Suất (Jun Da)": "7334.0", "Tần Suất % (Jun Da)": "99.9981333721", "GavinGrover_Once (Chiết tự trực tiếp)": "門 + 平", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門平", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "平", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "閛", "Unihan_Traditional (Chữ Phồn thể)": "閛", "Pinyin_Xie": "pēng", "Âm Hán Việt_Xie": "phanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Danh từ | 名词 | Chữ này làm từ tượng thanh mô phỏng âm thanh lớn khi đóng cửa. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陙', '{"9000": "7335.0", "Chữ Trung Quốc": "陙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 9 | nét | 陙 | tượng hình | chữ bộ 阜, nghĩa cao | 陙 là chữ bộ 阜 (Phụ, gò đất cao), gợi nghĩa cao. Wiktionary ghi nhận âm đọc nhưng không có gloss hay phân tích cấu trúc. Chưa rõ hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuần\": chữ 陙 bộ 阜 (gò đất) — hình ảnh gò đất cao vút, mô tả địa hình cao ráo. | Gương Hán-Việt | \"thuần\" — đọc Hán-Việt của 陙, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 陙 mở khoá nhóm chữ bộ 阜 chỉ địa hình cao trong văn ngôn", "Tự nguyên_Xie": "Wiktionary ghi nhận âm chún/dé, nghĩa không rõ (rfdef). Bộ 阜 (phụ, gò cao) phù hợp với nghĩa ''cao''. Chữ có âm đọc trung cổ, nghĩa không được giải thích chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cao", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 辰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝辰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陙", "Unihan_Traditional (Chữ Phồn thể)": "陙", "Pinyin_Xie": "chún", "Âm Hán Việt_Xie": "thuần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ miêu tả địa hình cao ráo hoặc làm danh từ chỉ bờ đất cao. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霳', '{"9000": "7336.0", "Chữ Trung Quốc": "霳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 19 | nét | 霳 | tượng hình | chữ bộ 雨, nghĩa không rõ, dùng trong từ 靊霳 | 霳 là chữ bộ 雨 (Vũ, mưa), Wiktionary ghi nhận âm lóng nhưng không có nghĩa cụ thể (rfdef). Chỉ xuất hiện trong từ ghép 靊霳. Chưa có phân tích lục thư.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"long\": chữ 霳 bộ 雨 (mưa) — hình ảnh tiếng sấm sét vang rền trong cơn mưa, xuất hiện trong từ 靊霳. | Gương Hán-Việt | \"long\" — đọc Hán-Việt của 霳, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 霳 mở khoá từ ghép 靊霳 chỉ tiếng sấm hay hiện tượng khí quyển trong văn ngôn", "Tự nguyên_Xie": "Wiktionary ghi nhận âm lóng, nghĩa không rõ (rfdef), dùng trong từ 靊霳. Bộ 雨 (vũ, mưa) gợi liên quan đến thời tiết hoặc hiện tượng khí quyển. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "霳", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 隆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨隆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霳", "Unihan_Traditional (Chữ Phồn thể)": "霳", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "long", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Danh từ | 名词 | Chữ này thường kết hợp đúp thành từ tượng thanh mô tả tiếng sấm vang rền. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('顑', '{"9000": "7337.0", "Chữ Trung Quốc": "顑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 18 | nét | 顑 | tượng hình | chữ bộ 頁, liên quan đến vùng mặt/đầu | 顑 là chữ bộ 頁 (Hiệt, đầu/mặt), Wiktionary chỉ ghi {{Han etym}} không có phân tích. Dùng trong từ 顑頷 (kham hạm) chỉ trạng thái gầy gò, xanh xao ở mặt. Chưa rõ cấu trúc lục thư.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khảm\": chữ 顑 bộ 頁 (đầu/mặt) — hình ảnh khuôn mặt gầy gò, xanh xao trong từ 顑頷. | Gương Hán-Việt | \"khảm\" — đọc Hán-Việt của 顑, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 顑 mở khoá từ ghép 顑頷 chỉ trạng thái gầy gò xanh xao trong văn ngôn", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} không có gloss cụ thể. Bộ 頁 (hiệt, đầu/mặt) phù hợp với nghĩa trong từ 顑頷 chỉ nét mặt gầy gò, xanh xao. Chữ dùng chủ yếu trong từ ghép văn ngôn. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem: kham hạm 顑頷", "Hạng Tần Suất (Jun Da)": "7337.0", "Tần Suất % (Jun Da)": "99.9981395735", "GavinGrover_Once (Chiết tự trực tiếp)": "咸 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰咸頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "顑", "Unihan_Traditional (Chữ Phồn thể)": "顑", "Pinyin_Xie": "kǎn", "Âm Hán Việt_Xie": "kham", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả sắc mặt tiều tụy, vàng võ do thiếu ăn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镤', '{"9000": "7338.0", "Chữ Trung Quốc": "镤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 金 | kim | biểu nghĩa | kim loại | 菐 | biểu âm | thành phần biểu âm cho âm pú | 镤 = 金 (Kim, biểu nghĩa: kim loại) + 菐 (biểu âm, cho âm pú); chữ hình thanh. Bộ 金 cho biết đây là kim loại, phần 菐 cho âm đọc. Dạng truyền thống là 鏷.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phác\": chữ 镤 hình thanh — 金 (kim loại) + 菐 (âm pú); hình ảnh nguyên tố protactinium Pa91 trong bảng tuần hoàn, một kim loại phóng xạ hiếm. | Gương Hán-Việt | \"phác\" — đọc Hán-Việt của 镤, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 镤 mở khoá nhóm chữ bộ 钅 dùng cho tên nguyên tố hoá học phóng xạ", "Tự nguyên_Xie": "Wiktionary phân tích 鏷 (dạng truyền thống): hình thanh tự (psc) — 金 (kim, kim loại) là biểu nghĩa, 菐 là biểu âm. Nghĩa hiện đại: nguyên tố protactinium (Pa, số nguyên tử 91), một nguyên tố phóng xạ. Chữ tạo mới để phiên âm tên nguyên tố hoá học. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố protactini, Pa", "Hạng Tần Suất (Jun Da)": "7338.0", "Tần Suất % (Jun Da)": "99.9981416407", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 菐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅菐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "菐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镤", "Unihan_Traditional (Chữ Phồn thể)": "鏷", "Pinyin_Xie": "pú", "Âm Hán Việt_Xie": "bộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ nguyên tố hóa học phóng xạ protactini. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('竚', '{"9000": "7339.0", "Chữ Trung Quốc": "竚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 立 | Số nét | 10 | nét | 竚 | tượng hình | chữ bộ 立, dạng khác của 佇, nghĩa đứng đợi lâu | 竚 là dạng khác của 佇 (đứng đợi lâu), bộ 立 (Lập, đứng). Wiktionary ghi 竚 tra về 佇. Bộ 立 phù hợp với nghĩa đứng chờ đợi. Chữ tạo muộn, ít gặp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trú\": chữ 竚 bộ 立 (đứng) — hình ảnh người đứng chờ lâu, không rời chỗ, mong ngóng. | Gương Hán-Việt | \"trú\" — đọc Hán-Việt của 竚, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 竚 mở khoá 佇 (dạng thông dụng hơn, đứng đợi mong mỏi) trong thơ ca cổ điển", "Tự nguyên_Xie": "Wiktionary ghi 竚 là dạng khác của 佇, nghĩa là đứng đợi lâu, mong ngóng. Bộ 立 (lập, đứng) là thành phần biểu nghĩa. 佇 thường dùng hơn trong văn ngôn với nghĩa đứng đợi mong mỏi. Chữ tạo muộn, ít có nguồn học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mong đợi, đứng lâu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "立 + 宁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰立宁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "立", "Unihan_Simplified (Chữ Giản thể)": "竚", "Unihan_Traditional (Chữ Phồn thể)": "竚", "Pinyin_Xie": "zhù", "Âm Hán Việt_Xie": "trữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện hành động đứng yên một chỗ để ngóng trông ai đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('紩', '{"9000": "7340.0", "Chữ Trung Quốc": "紩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 糸 | mịch | biểu nghĩa | sợi tơ, chỉ việc khâu vá | 失 | thất | biểu âm | thành phần biểu âm cho âm zhì | 紩 = 糸 (Mịch, biểu nghĩa: sợi tơ/chỉ khâu) + 失 (Thất, biểu âm); chữ hình thanh. Bộ 糸 cho biết liên quan đến vải/chỉ, phần 失 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dệt\": 紩 = 糸 (sợi tơ) + 失 (thất, biểu âm) — hình ảnh bàn tay dệt may, từng mũi kim khâu qua vải. | Gương Hán-Việt | \"dệt\" trong 紩縫 (may khâu), gợi việc dùng chỉ tơ khâu vải | Mở khoá kiến thức | Biết 紩 (dệt) mở khoá nhóm chữ bộ 糸 chỉ việc may vá, dệt nối trong văn ngôn", "Tự nguyên_Xie": "Wiktionary phân tích: hình thanh tự (psc) — 糸 (mịch, sợi tơ) là biểu nghĩa, 失 (thất) là biểu âm. Nghĩa là may, khâu (dùng chỉ tơ để khâu vải). Phù hợp với bộ 糸 chỉ mọi thứ liên quan đến sợi, vải. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "may, khâu", "Hạng Tần Suất (Jun Da)": "7340.0", "Tần Suất % (Jun Da)": "99.9981478421", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 失", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹失", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "失", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "紩", "Unihan_Traditional (Chữ Phồn thể)": "紩", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "trật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động khâu vá quần áo hoặc may nối các mảnh vải. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聦', '{"9000": "7341.0", "Chữ Trung Quốc": "聦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 15 | nét | 聦 | tượng hình | dạng khác của 聰, nghĩa thông minh, tinh tường | 聦 là dạng khác của 聰 (thông minh, tinh tường), bộ 耳 (Nhĩ, tai). Wiktionary ghi 聦 tra về 聰. Bộ 耳 phù hợp với nghĩa nghe nhanh, thông minh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thông\": chữ 聦 bộ 耳 (tai) — hình ảnh đôi tai thính nhạy, nghe được mọi thứ, tượng trưng cho sự thông minh. | Gương Hán-Việt | \"thông\" — đọc Hán-Việt của 聦, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 聦 mở khoá 聰 (thông minh) và nhóm chữ bộ 耳 chỉ khả năng nghe, thính giác", "Tự nguyên_Xie": "Wiktionary ghi 聦 là dạng khác của 聰, nghĩa là thông minh, nhanh nhạy, có khả năng nghe tốt. Bộ 耳 (nhĩ, tai) là thành phần biểu nghĩa chính. 聰 thông dụng hơn 聦 trong văn hiện đại. Chữ tạo muộn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "覦", "Hạng Tần Suất (Jun Da)": "7341.0", "Tần Suất % (Jun Da)": "99.9981499092", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 怱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳怱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "怱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聦", "Unihan_Traditional (Chữ Phồn thể)": "聦", "Pinyin_Xie": "cōng", "Âm Hán Việt_Xie": "thông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ để miêu tả sự thông minh, nhạy bén của con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶄', '{"9000": "7342.0", "Chữ Trung Quốc": "鶄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 19 | nét | 鶄 | tượng hình | chữ bộ 鳥, tên loài chim, dùng trong 鵁鶄 | 鶄 là chữ bộ 鳥 (Điểu, chim), chỉ một loài chim, chủ yếu dùng trong từ ghép 鵁鶄. Wiktionary ghi nhận âm đọc nhưng không phân tích cấu trúc lục thư. Đây là dạng truyền thống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tinh\": chữ 鶄 bộ 鳥 (chim) — một loài chim nước xuất hiện trong từ ghép 鵁鶄, ít gặp ngoài văn ngôn. | Gương Hán-Việt | \"tinh\" — đọc Hán-Việt của 鶄, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 鶄 mở khoá từ ghép 鵁鶄 chỉ loài chim nước trong thơ ca cổ điển", "Tự nguyên_Xie": "Wiktionary ghi nhận âm jīng, dùng trong 鵁鶄 (một loài chim nước). Bộ 鳥 (điểu, chim) là thành phần biểu nghĩa. Chưa có phân tích hình thanh hay hội ý. Chữ chuyên dùng trong tên loài chim. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鄄", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "青 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰青鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鳥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "青", "Unihan_Simplified (Chữ Giản thể)": "鶄", "Unihan_Traditional (Chữ Phồn thể)": "鶄", "Pinyin_Xie": "jīng", "Âm Hán Việt_Xie": "tinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong tên gọi của một số loài chim lội nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簷', '{"9000": "7343.0", "Chữ Trung Quốc": "簷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 19 | nét | 簷 | tượng hình | dạng khác của 檐, mái hiên, vành mũ | 簷 là dạng khác của 檐 (mái hiên), bộ 竹 (Trúc, tre). Wiktionary ghi 簷 tra về 檐. Bộ 竹 gợi vật liệu tre dùng làm mái. Đây là dạng truyền thống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không rõ (Hán-Việt: \"thiềm\"): 簷 bộ 竹 (tre) — hình ảnh mái hiên nhà lợp bằng tre, phần nhô ra ngoài che mưa nắng. | Gương Hán-Việt | \"thiềm\" — đọc Hán-Việt của 簷, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 簷 mở khoá 屋簷 (mái hiên), 帽簷 (vành mũ), 簷下 (dưới mái hiên)", "Tự nguyên_Xie": "Wiktionary ghi 簷 là dạng khác của 檐, nghĩa là mái hiên, vành mũ, diềm mũ. Bộ 竹 (trúc, tre) gợi vật liệu làm mái. 檐 thông dụng hơn, bộ 木 (mộc, gỗ). 簷 dùng bộ 竹 phản ánh truyền thống dùng tre làm mái. Chữ truyền thống. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mái hiên, mái nhà; vành mũ, diềm mũ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 詹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮詹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "詹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簷", "Unihan_Traditional (Chữ Phồn thể)": "簷", "Pinyin_Xie": "yán", "Âm Hán Việt_Xie": "thiềm, diêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần mái hiên nhô ra của ngôi nhà. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糵', '{"9000": "7344.0", "Chữ Trung Quốc": "糵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 22 | nét | 糵 | tượng hình | dạng khác của 糱, mầm lúa, cây mạ | 糵 là dạng khác của 糱 (mầm lúa, cây mạ), bộ 米 (Mễ, gạo). Wiktionary ghi 糵 tra về 糱. Bộ 米 phù hợp với nghĩa liên quan đến lúa gạo, mầm cây.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không rõ (Hán-Việt: \"nghiệt\"): 糵 bộ 米 (gạo) — hình ảnh hạt gạo nảy mầm, mầm lúa non mới nhú. | Gương Hán-Việt | \"nghiệt\" — đọc Hán-Việt của 糵, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 糵 mở khoá thuật ngữ y học cổ truyền về mầm ngũ cốc, mạch nha", "Tự nguyên_Xie": "Wiktionary ghi 糵 là dạng khác của 糱, nghĩa là mầm lúa, cây mạ, hạt nảy mầm. Bộ 米 (mễ, gạo) là thành phần biểu nghĩa. 糱 dùng để chỉ mạch nha (malt) hoặc mầm ngũ cốc trong y học cổ truyền và nghề ủ rượu. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mầm, cây mạ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "糵", "Unihan_Traditional (Chữ Phồn thể)": "糵", "Pinyin_Xie": "niè", "Âm Hán Việt_Xie": "nghiệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ mầm ngũ cốc dùng làm men ủ rượu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('紖', '{"9000": "7345.0", "Chữ Trung Quốc": "紖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 10 | nét | 紖 | tượng hình | chữ bộ 糸, dây dắt trâu bò qua mũi | 紖 là chữ bộ 糸 (Mịch, sợi/dây), Wiktionary ghi nhận nghĩa là dây dắt trâu bò qua mũi, hoặc dây kéo xe tang. Chưa có phân tích cấu trúc lục thư chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chấn\": chữ 紖 bộ 糸 (dây) — hình ảnh sợi dây xỏ qua mũi trâu, dẫn dắt gia súc đi theo ý người. | Gương Hán-Việt | \"chấn\" — đọc Hán-Việt của 紖, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 紖 mở khoá nhóm chữ bộ 糸 chỉ dây thừng, dây dắt trong văn ngôn", "Tự nguyên_Xie": "Wiktionary ghi nhận: nghĩa văn ngôn là dây dắt trâu/bò qua mũi (nose rope for livestock), hoặc dây kéo xe tang. Bộ 糸 (mịch, sợi/dây) là biểu nghĩa. Có âm đọc trung cổ. Chữ văn ngôn, ít dùng hiện đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "疴", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 引", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹引", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "引", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "紖", "Unihan_Traditional (Chữ Phồn thể)": "紖", "Pinyin_Xie": "zhèn", "Âm Hán Việt_Xie": "chấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ sợi dây thừng dùng để dắt trâu bò. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趦', '{"9000": "7346.0", "Chữ Trung Quốc": "趦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 16 | nét | 趦 | tượng hình | chữ bộ 走, dùng trong 趑趄/趦趄, nghĩa do dự chần chừ | 趦 là chữ bộ 走 (Tẩu, đi/chạy), dùng trong từ ghép 趦趄/趑趄 chỉ bước đi do dự, chần chừ không quyết. Không có glyph-origin từ Wiktionary. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": chữ 趦 bộ 走 (đi) — hình ảnh đôi chân bước tới rồi dừng lại, do dự không quyết trong 趦趄. | Gương Hán-Việt | \"tư\" — đọc Hán-Việt của 趦, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 趦 mở khoá từ ghép 趦趄 chỉ sự do dự, chần chừ không quyết trong văn ngôn", "Tự nguyên_Xie": "Không có glyph-origin từ Wiktionary. Bộ 走 (tẩu, đi/chạy) kết hợp với nghĩa ''do dự, bước chần chừ'' gợi hình tượng chân bước rồi dừng, không quyết định được. Dùng trong từ 趦趄/趑趄 chỉ sự do dự. Chữ tạo muộn, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tư thư 趑趄,趦趄)", "Hạng Tần Suất (Jun Da)": "7346.0", "Tần Suất % (Jun Da)": "99.9981685135", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 咨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走咨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趦", "Unihan_Traditional (Chữ Phồn thể)": "趦", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này chủ yếu dùng trong từ ghép tư thư để miêu tả trạng thái do dự, không dám tiến lên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禠', '{"9000": "7347.0", "Chữ Trung Quốc": "禠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 14 | nét | 禠 | tượng hình | chữ bộ 示, nghĩa phước lành | 禠 là chữ bộ 示 (Thị, thần linh/lễ nghi), gợi liên quan đến phước lành, lễ nghi thiêng liêng. Wiktionary ghi nhận nghĩa là phước lành (blessing). Chưa có phân tích cấu trúc lục thư chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": chữ 禠 bộ 示 (thần linh) — hình ảnh điều phước lành được ban xuống từ trời, bộ 示 chỉ lễ nghi và ân huệ thần thánh. | Gương Hán-Việt | \"tư\" — đọc Hán-Việt của 禠, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 禠 mở khoá nhóm chữ bộ 示 chỉ phước lành, lễ nghi thiêng liêng trong văn ngôn", "Tự nguyên_Xie": "Wiktionary ghi nhận nghĩa là phước lành (blessing). Bộ 示 (thị, thần linh/lễ nghi) là thành phần biểu nghĩa, phù hợp với nghĩa phước lành từ thần linh. Chữ văn ngôn, ít gặp hiện đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phước lành; trọng tội", "Hạng Tần Suất (Jun Da)": "7347.0", "Tần Suất % (Jun Da)": "99.9981726478", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 虒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻虒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禠", "Unihan_Traditional (Chữ Phồn thể)": "禠", "Pinyin_Xie": "sī", "Âm Hán Việt_Xie": "tư, ti", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ cổ dùng để chỉ phúc khí hoặc điềm lành từ thần linh ban cho. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籓', '{"9000": "7348.0", "Chữ Trung Quốc": "籓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 21 | nét | 籓 | tượng hình | chữ bộ 竹, giỏ sàng lớn, cũng là phên giậu | 籓 là chữ bộ 竹 (Trúc, tre), chỉ giỏ sàng lớn làm bằng tre, hoặc hàng rào/phên giậu (tương tự 藩). Wiktionary ghi nhận nghĩa giỏ sàng. Chưa có phân tích lục thư chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không rõ (Hán-Việt: \"phiên\"): 籓 bộ 竹 (tre) — hình ảnh chiếc giỏ sàng lớn bện bằng tre, dùng để sàng gạo, thóc. | Gương Hán-Việt | \"phiên\" — đọc Hán-Việt của 籓, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 籓 mở khoá nhóm chữ bộ 竹 chỉ đồ vật tre, cũng liên hệ với 藩 (phên giậu, phiên thần)", "Tự nguyên_Xie": "Wiktionary ghi nhận nghĩa ''giỏ sàng lớn'' (winnowing basket). Bộ 竹 (trúc, tre) là biểu nghĩa, phù hợp với đồ vật làm từ tre. 籓 cũng gần với 藩 (phên giậu, phiên thần). Chữ văn ngôn, ít gặp hiện đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giỏ winnow lớn", "Hạng Tần Suất (Jun Da)": "7348.0", "Tần Suất % (Jun Da)": "99.9981747149", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 潘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮潘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "潘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "籓", "Unihan_Traditional (Chữ Phồn thể)": "籓", "Pinyin_Xie": "fān", "Âm Hán Việt_Xie": "phan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò là danh từ chỉ một loại dụng cụ làm bằng tre dùng trong nông nghiệp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镥', '{"9000": "7349.0", "Chữ Trung Quốc": "镥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 镥 | tượng hình | dạng giản thể của 鑥, nguyên tố lutetium Lu | 镥 là dạng giản thể của 鑥 (釒→钅). Theo Wiktionary, 镥 tra về 鑥. Bộ 钅 (kim loại) là biểu nghĩa, chỉ đây là một nguyên tố kim loại. Nghĩa: nguyên tố lutetium (Lu, số nguyên tử 71).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lỗ\": chữ 镥 bộ 钅 (kim loại) — nguyên tố lutetium Lu71, kim loại đất hiếm được đặt theo tên thành phố Paris (Lutetia trong tiếng Latin). | Gương Hán-Việt | \"lỗ\" — đọc Hán-Việt của 镥, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 镥 mở khoá nhóm chữ bộ 钅 dùng cho tên nguyên tố đất hiếm trong bảng tuần hoàn", "Tự nguyên_Xie": "Wiktionary ghi 镥 là dạng giản hoá của 鑥 (釒→钅). Đây là chữ tạo mới để phiên âm tên nguyên tố lutetium (Lu, số nguyên tử 71), một kim loại đất hiếm. Bộ 钅 (kim loại) là biểu nghĩa. Tên nguyên tố bắt nguồn từ Lutetia (tên Latin của Paris). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố lutexi, Lu", "Hạng Tần Suất (Jun Da)": "7349.0", "Tần Suất % (Jun Da)": "99.998176782", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 鲁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅鲁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鲁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镥", "Unihan_Traditional (Chữ Phồn thể)": "鑥", "Pinyin_Xie": "lǔ", "Âm Hán Việt_Xie": "lỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ chuyên ngành hóa học dùng để chỉ nguyên tố kim loại chuyển tiếp luteti. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矝', '{"9000": "7350.0", "Chữ Trung Quốc": "矝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 矛 | Số nét | 10 | nét | 矝 | tượng hình | chữ bộ 矛, nghĩa trang nghiêm, đứng đắn | 矝 là chữ bộ 矛 (Mâu, cây giáo), gợi hình ảnh người đứng thẳng cầm vũ khí một cách trang nghiêm. Không có glyph-origin từ Wiktionary. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lẫm\": chữ 矝 bộ 矛 (giáo) — hình ảnh người lính đứng nghiêm cầm cây giáo, tư thế uy nghi, trang nghiêm. | Gương Hán-Việt | \"lẫm\" — đọc Hán-Việt của 矝, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 矝 mở khoá nhóm chữ bộ 矛 chỉ thái độ uy nghiêm, đứng đắn trong văn ngôn", "Tự nguyên_Xie": "Không có glyph-origin từ Wiktionary. Bộ 矛 (mâu, cây giáo) gợi hình ảnh người lính đứng trang nghiêm với vũ khí. Nghĩa ''trang nghiêm, đứng đắn'' phù hợp với tư thế uy nghiêm của người cầm giáo. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trang nghiêm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "矛 + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰矛令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "矛", "Unihan_Simplified (Chữ Giản thể)": "矝", "Unihan_Traditional (Chữ Phồn thể)": "矝", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lẫm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ thể hiện thái độ nghiêm túc, kính cẩn hoặc thận trọng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笖', '{"9000": "7351.0", "Chữ Trung Quốc": "笖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 10 | nét | 笖 | tượng hình | chữ bộ 竹, nghĩa không rõ | 笖 là chữ bộ 竹 (Trúc, tre), Wiktionary ghi nhận âm đọc nhưng không có nghĩa cụ thể (rfdef). Có âm đọc trung cổ. Chưa rõ cấu trúc hay nghĩa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ỷ\": chữ 笖 bộ 竹 (tre) — một vật dụng hoặc khái niệm nào đó liên quan đến tre, nghĩa cụ thể chưa được ghi chép đầy đủ. | Gương Hán-Việt | \"ỷ\" — đọc Hán-Việt của 笖, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 笖 mở khoá nhóm chữ bộ 竹 chỉ đồ vật tre trong văn ngôn", "Tự nguyên_Xie": "Wiktionary ghi nhận âm yǐ, nghĩa không rõ. Bộ 竹 (trúc, tre) gợi liên quan đến đồ vật tre. Có âm đọc trung cổ. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "笖", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 以", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮以", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "以", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笖", "Unihan_Traditional (Chữ Phồn thể)": "笖", "Pinyin_Xie": "yǐ", "Âm Hán Việt_Xie": "ỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ cổ dùng để chỉ một giống tre hoặc măng tre cụ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笧', '{"9000": "7352.0", "Chữ Trung Quốc": "笧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 笧 | tượng hình | chữ bộ 竹, nghĩa không rõ | 笧 là chữ bộ 竹 (Trúc, tre). Wiktionary ghi {{Han etym}} không có nghĩa cụ thể. Chưa rõ cấu trúc hay nghĩa. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sách\": chữ 笧 bộ 竹 (tre) — một đồ vật tre không rõ tên, nằm trong kho chữ Hán hiếm dùng. | Gương Hán-Việt | \"sách\" — đọc Hán-Việt của 笧, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 笧 mở khoá nhóm chữ bộ 竹 hiếm trong văn ngôn", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} không có gloss. Bộ 竹 (trúc, tre) gợi liên quan đến đồ vật tre. Chữ tạo muộn, chưa có nguồn học thuật xác nhận nghĩa hay cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "笧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 册", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮册", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "册", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笧", "Unihan_Traditional (Chữ Phồn thể)": "笧", "Pinyin_Xie": "cè", "Âm Hán Việt_Xie": "sách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò là danh từ chỉ các vật dụng làm bằng tre như roi hoặc thẻ tre viết chữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簢', '{"9000": "7353.0", "Chữ Trung Quốc": "簢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 18 | nét | 竹 | trúc | biểu nghĩa | tre | 閔 | biểu âm | thành phần biểu âm cho âm mǐn | 簢 = 竹 (Trúc, biểu nghĩa: tre) + 閔 (biểu âm, cho âm mǐn); chữ hình thanh. Bộ 竹 cho biết đây là loại tre, phần 閔 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mẫn\": chữ 簢 hình thanh — 竹 (tre) + 閔 (biểu âm mǐn); hình ảnh những cây tre mảnh dùng để đan chiếu, thảm. | Gương Hán-Việt | \"mẫn\" — đọc Hán-Việt của 簢, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 簢 mở khoá nhóm chữ bộ 竹 chỉ các loại tre cụ thể trong văn ngôn", "Tự nguyên_Xie": "Wiktionary phân tích: hình thanh tự (psc) — 竹 (trúc, tre) là biểu nghĩa, 閔 là biểu âm. Nghĩa là một loại tre có thể dùng để đan chiếu. Chữ văn ngôn hiếm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "簢", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 閔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮閔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "閔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簢", "Unihan_Traditional (Chữ Phồn thể)": "簢", "Pinyin_Xie": "mǐn", "Âm Hán Việt_Xie": "mẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ chỉ một loại tre có đặc điểm cật dày và thớ thịt khít. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簻', '{"9000": "7354.0", "Chữ Trung Quốc": "簻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 17 | nét | 簻 | tượng hình | chữ bộ 竹, roi ngựa hoặc ống nhạc | 簻 là chữ bộ 竹 (Trúc, tre), có nghĩa roi ngựa (gậy) hoặc ống trong nhạc khí. Wiktionary ghi {{Han etym}} không có phân tích chi tiết. Chưa rõ cấu trúc lục thư.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trảo\": chữ 簻 bộ 竹 (tre) — hình ảnh cây roi ngựa bằng tre, hoặc ống tre dùng trong nhạc khí cổ. | Gương Hán-Việt | \"trảo\" — đọc Hán-Việt của 簻, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 簻 mở khoá nhóm chữ bộ 竹 chỉ dụng cụ tre trong kỵ binh và nhạc cụ cổ", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} không có gloss cụ thể. Bộ 竹 (trúc, tre) phù hợp với cả hai nghĩa: roi ngựa (làm từ tre) và ống nhạc (nhạc khí làm từ tre). Chữ văn ngôn, ít gặp hiện đại. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "roi ngựa, gậy; cái ống trong nhạc khí", "Hạng Tần Suất (Jun Da)": "7354.0", "Tần Suất % (Jun Da)": "99.9981891849", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 過", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮過", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "過", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簻", "Unihan_Traditional (Chữ Phồn thể)": "簻", "Pinyin_Xie": "zhuā", "Âm Hán Việt_Xie": "qua", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ roi đánh ngựa hoặc một bộ phận dạng ống trong nhạc cụ cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粍', '{"9000": "7355.0", "Chữ Trung Quốc": "粍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 10 | nét | 粍 | tượng hình | chữ bộ 米, nghĩa cơm hoặc đơn vị đo | 粍 là chữ bộ 米 (Mễ, gạo/cơm). Không có glyph-origin từ Wiktionary. Nghĩa trong dữ liệu là ''cơm''. Chữ ít gặp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiết\": chữ 粍 bộ 米 (gạo/cơm) — hình ảnh bát cơm đơn giản, đại diện cho lương thực cơ bản. | Gương Hán-Việt | \"chiết\" — đọc Hán-Việt của 粍, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 粍 mở khoá nhóm chữ bộ 米 chỉ thực phẩm làm từ gạo", "Tự nguyên_Xie": "Không có glyph-origin từ Wiktionary. Bộ 米 (mễ, gạo) gợi liên quan đến gạo, lương thực. Nghĩa ''cơm'' phù hợp với bộ 米. Chữ tạo muộn, chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Cơm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 毛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米毛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粍", "Unihan_Traditional (Chữ Phồn thể)": "粍", "Pinyin_Xie": "zhé", "Âm Hán Việt_Xie": "chiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường dùng làm danh từ chỉ các loại lương thực dạng hạt hoặc làm lượng từ đo độ dài trong văn bản kỹ thuật cũ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綍', '{"9000": "7356.0", "Chữ Trung Quốc": "綍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 綍 | phất | tượng hình | dây thừng lớn dùng kéo quan tài | 綍 là ký tự độc lập, không có dữ liệu phân tích thành phần từ CHISE. Theo Wiktionary, đây là dạng biến thể của 紼 (fú) — dây thừng lớn dùng trong tang lễ. Chữ tạo muộn, chưa thấy phân tích hình thanh rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phất\": 綍 là dây thừng thiêng liêng trong tang lễ — to và chắc để \"phất\" (kéo) linh cữu về nơi an nghỉ. | Gương Hán-Việt | Chữ 綍 ít xuất hiện trong từ Hán-Việt thông dụng hiện đại. | Mở khoá kiến thức | Biết 綍 giúp đọc hiểu văn bản Hán Nôm về tang lễ và nghi lễ cung đình cổ.", "Tự nguyên_Xie": "綍 là dạng thay thế của 紼, nghĩa là dây thừng lớn dùng để kéo quan tài trong tang lễ. Cũng mang nghĩa cổ là chiếu chỉ hoàng đế. Chưa có nguồn học thuật phân tích cấu trúc cụ thể. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái dây lớn", "Hạng Tần Suất (Jun Da)": "7356.0", "Tần Suất % (Jun Da)": "99.9981953863", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 孛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹孛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "綍", "Unihan_Traditional (Chữ Phồn thể)": "綍", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu làm danh từ chỉ sợi dây thừng lớn dùng trong nghi lễ mai táng thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('縕', '{"9000": "7357.0", "Chữ Trung Quốc": "縕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 16 | nét | 縕 | uẩn | tượng hình | sợi vải cũ rối, màu cam | 縕 không có dữ liệu phân tích thành phần từ CHISE. Đây là chữ chỉ sợi vải cũ, đay vụn lẫn lộn; cũng dùng chỉ màu cam. Cấu trúc nội bộ chưa được phân tích rõ trong nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uẩn\": 縕 như cuộn vải \"uẩn khúc\" — sợi tơ cũ rối bời, ẩn chứa bên trong áo bào mùa đông. | Gương Hán-Việt | \"uẩn\" trong \"uẩn khúc\" (nỗi niềm chứa chất bên trong), phản ánh nghĩa rối ren, ẩn chứa. | Mở khoá kiến thức | Biết 縕 giúp hiểu các từ cổ văn chỉ sự hỗn độn, ẩn khuất (uẩn khúc, u uẩn) và vải cũ tạp.", "Tự nguyên_Xie": "Tiểu triện | 縕 (cổ văn) chỉ những sợi vải cũ, đay hoặc tơ tạp đã rối bời. Cũng mang nghĩa lộn xộn, rối ren. Một nghĩa cổ khác là màu cam. Dùng trong thành ngữ 絪縕 (mờ ảo, hòa quyện). Chưa có nguồn học thuật xác định cấu trúc hình thành. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bông tơ tạp, gai; đay vụn; tạp nhạp, lẫn lộn", "Hạng Tần Suất (Jun Da)": "7106.0", "Tần Suất % (Jun Da)": "99.9974512157", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 𥁕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹𥁕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𥁕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "缊", "Unihan_Traditional (Chữ Phồn thể)": "縕", "Pinyin_Xie": "yūn", "Âm Hán Việt_Xie": "uẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ xơ gai vụn hoặc làm tính từ mô tả trạng thái hỗn độn, mập mờ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罋', '{"9000": "7358.0", "Chữ Trung Quốc": "罋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 缶 | Số nét | 19 | nét | 罋 | ủng | tượng hình | cái vò, vại lớn đựng rượu hay nước | 罋 là dạng biến thể của 甕 (ủng/wèng) — cái vò đất lớn. Không có dữ liệu phân tích thành phần từ CHISE; cấu trúc chưa được phân tích rõ trong học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ủng\": 罋 là cái vò đất \"ủng\" — to tròn, dùng đựng rượu hay lương thực trong nhà cổ xưa. | Gương Hán-Việt | \"ủng\" ít dùng trong tiếng Việt hiện đại; chủ yếu gặp trong văn bản Hán Nôm. | Mở khoá kiến thức | Biết 罋/甕 giúp đọc hiểu văn bản cổ về đồ gốm, dụng cụ nhà bếp và bảo quản thực phẩm.", "Tự nguyên_Xie": "罋 là dạng cổ/biến thể của 甕, chỉ cái vại lớn bằng đất nung dùng đựng rượu, nước, hoặc ngũ cốc. Chưa có nguồn học thuật xác định cấu trúc hình thành chữ này. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bình đựng tro cốt", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "雍 + 缶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雍缶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "缶", "Unihan_Simplified (Chữ Giản thể)": "罋", "Unihan_Traditional (Chữ Phồn thể)": "罋", "Pinyin_Xie": "wèng", "Âm Hán Việt_Xie": "ủng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ vật dụng đựng nước hoặc tro cốt bằng đất nung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翜', '{"9000": "7359.0", "Chữ Trung Quốc": "翜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 13 | nét | 翜 | táp | tượng hình | nhanh nhẹn, mau lẹ | 翜 không có dữ liệu phân tích thành phần từ CHISE. Đây là chữ cổ, chuẩn đã lỗi thời, mang nghĩa nhanh, mau. Cấu trúc nội bộ chưa được phân tích rõ trong học thuật hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táp\": 翜 gợi hình ảnh đôi cánh (羽) vỗ \"táp táp\" thật nhanh — nghĩa là mau lẹ, thoắt cái đã bay đi. | Gương Hán-Việt | \"táp\" ít dùng trong tiếng Việt hiện đại; chủ yếu gặp trong cổ văn chữ Hán. | Mở khoá kiến thức | Biết 翜 giúp nhận diện chữ cổ chỉ tốc độ trong văn bản cổ điển.", "Tự nguyên_Xie": "翜 là chữ cổ đã lỗi thời (obs-std), mang nghĩa nhanh, mau lẹ. Không có phân tích cấu trúc từ học thuật. Chưa có nguồn học thuật xác định nguồn gốc hình thành. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "眜", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "羽 + 夾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羽夾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翜", "Unihan_Traditional (Chữ Phồn thể)": "翜", "Pinyin_Xie": "shà", "Âm Hán Việt_Xie": "táp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ chỉ các loại quạt lông vũ hoặc vật trang trí trong nghi lễ cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膰', '{"9000": "7360.0", "Chữ Trung Quốc": "膰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 16 | nét | 膰 | phiên | tượng hình | thịt nướng dùng trong tế lễ | 膰 không có dữ liệu phân tích thành phần từ CHISE. Theo hình thức, chữ có bộ 月/肉 (thịt), gợi liên quan đến thịt. Đây là chữ cổ chỉ thịt nướng dùng trong tế lễ. Cấu trúc chưa được phân tích học thuật rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiên\": 膰 là thịt (月/肉) nướng \"phiên\" — dùng để dâng lên thần linh trong nghi lễ tế tự. | Gương Hán-Việt | \"phiên\" ít dùng riêng lẻ trong tiếng Việt; chủ yếu gặp trong văn bản lễ nghi cổ. | Mở khoá kiến thức | Biết 膰 giúp đọc hiểu văn bản cổ về nghi lễ tế tự và đồ cúng tế.", "Tự nguyên_Xie": "膰 (cổ văn) chỉ thịt nướng dùng trong các nghi lễ tế tự. Bộ 月/肉 gợi nguồn gốc liên quan đến thịt. Chưa có nguồn Wiktionary phân tích cấu trúc đầy đủ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thịt cúng; thịt luộc (dùng để cúng tế thời xưa)", "Hạng Tần Suất (Jun Da)": "7360.0", "Tần Suất % (Jun Da)": "99.998205722", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 番", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月番", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "番", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膰", "Unihan_Traditional (Chữ Phồn thể)": "膰", "Pinyin_Xie": "fán", "Âm Hán Việt_Xie": "phần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ phần thịt luộc chín dùng để dâng cúng trong các buổi tế lễ thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膲', '{"9000": "7361.0", "Chữ Trung Quốc": "膲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 16 | nét | 膲 | tiêu | tượng hình | tiêu — ba tiêu (tam tiêu trong y học cổ truyền) | 膲 không có dữ liệu phân tích thành phần từ CHISE. Bộ 月/肉 gợi liên quan đến cơ thể. Đây là dạng biến thể của 焦, dùng trong y học cổ truyền để chỉ \"tam tiêu\" — ba vùng chức năng của cơ thể. Cấu trúc chưa được phân tích học thuật rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": 膲 = thân thể (月/肉) bị \"tiêu\" (đốt nóng) — hình ảnh tam tiêu trong y học cổ truyền, ba lò nhiệt trong cơ thể. | Gương Hán-Việt | \"tiêu\" trong \"tam tiêu\" (三膲) — ba vùng chức năng trong đông y. | Mở khoá kiến thức | Biết 膲 giúp đọc tài liệu đông y cổ về tam tiêu và lý luận khí hóa.", "Tự nguyên_Xie": "膲 là dạng biến thể của 焦, dùng trong y học cổ truyền Trung Hoa để chỉ \"tam tiêu\" (三膲/三焦) — ba vùng chức năng của cơ thể gồm thượng tiêu, trung tiêu và hạ tiêu. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật xác định cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem 三 膲 [san1 jiao1]", "Hạng Tần Suất (Jun Da)": "7361.0", "Tần Suất % (Jun Da)": "99.9982077892", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 焦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月焦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "焦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膲", "Unihan_Traditional (Chữ Phồn thể)": "膲", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "tiều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong y học cổ truyền để chỉ ba phần khoang cơ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菂', '{"9000": "7362.0", "Chữ Trung Quốc": "菂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艹 | biểu nghĩa | cỏ, thực vật | 的 | đích | biểu âm | 菂 là chữ hình thanh (psc): 艹 (bộ cỏ, biểu nghĩa: thực vật) + 的 (Đích, biểu âm). Bộ cỏ chỉ rõ đây là bộ phận của thực vật; 的 cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đích\": 菂 = cỏ (艹) + 的 (đích) — hạt sen nhỏ xinh \"đích\" thực là viên ngọc của bông sen. | Gương Hán-Việt | \"đích\" ít xuất hiện trong từ Hán-Việt thông dụng; chủ yếu trong thi ca cổ. | Mở khoá kiến thức | Biết 菂 giúp đọc thi ca cổ điển về hoa sen và các hình tượng thiên nhiên trong văn học Trung-Việt.", "Tự nguyên_Xie": "菂 (hình thanh): 艹 (cỏ, biểu nghĩa: thực vật) + 的 (biểu âm). Chỉ hạt sen — phần bên trong đài sen sau khi hoa tàn. Dùng trong văn học cổ điển để chỉ hạt sen (莲子) một cách thi vị. Tiểu triện chưa được ghi nhận. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hạt sen", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 的", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹的", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "的", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菂", "Unihan_Traditional (Chữ Phồn thể)": "菂", "Pinyin_Xie": "dì", "Âm Hán Việt_Xie": "đích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ hạt của cây sen trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薢', '{"9000": "7363.0", "Chữ Trung Quốc": "薢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 薢 | giải | tượng hình | tên một loại thực vật (củ mài rừng) | 薢 không có dữ liệu phân tích thành phần từ CHISE. Từ hình dáng, chữ có bộ 艹 (cỏ) gợi liên quan đến thực vật. Đây là tên một loài cây họ Dioscorea — củ mài rừng. Cấu trúc chi tiết chưa được phân tích học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giải\": 薢 = cỏ (艹) + \"giải\" — loài cây \"giải\" dùng trong y học cổ truyền, rễ củ \"giải\" độc. | Gương Hán-Việt | \"giải\" ít dùng riêng lẻ; chủ yếu trong danh mục thảo dược cổ. | Mở khoá kiến thức | Biết 薢 giúp đọc hiểu danh mục thảo dược Trung-Việt và các bài thuốc đông y cổ.", "Tự nguyên_Xie": "Tiểu triện | 薢 (cổ văn) chỉ một loài thực vật thuộc họ Dioscorea, tức củ mài rừng hay bí mài. Bộ 艹 gợi nguồn gốc thực vật. Không có phân tích Wiktionary đầy đủ. Hình ảnh tiểu triện còn lưu trong hanziyuan.net. Chưa có nguồn học thuật xác định cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tỳ giải 萆薢)", "Hạng Tần Suất (Jun Da)": "7363.0", "Tần Suất % (Jun Da)": "99.9982139906", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 解", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹解", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "解", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薢", "Unihan_Traditional (Chữ Phồn thể)": "薢", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "giải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ ghép trong tên vị thuốc đông y tỳ giải để trị bệnh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藷', '{"9000": "7364.0", "Chữ Trung Quốc": "藷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 藷 | chư | tượng hình | củ khoai, khoai lang, khoai mì | 藷 không có dữ liệu phân tích thành phần từ CHISE. Từ hình dáng, chữ có bộ 艹 (cỏ) gợi thực vật. Đây là chữ cổ chỉ các loại củ như khoai lang, khoai mì, hoặc khoai môn. Tiểu triện và lục thư thông còn lưu trong hanziyuan.net.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chư\": 藷 = cỏ (艹) + \"chư\" — củ khoai \"chư\" (lang/mì) mọc dưới đất, dân dã và bổ dưỡng. | Gương Hán-Việt | \"chư\" ít dùng riêng lẻ; \"thự\" (薯) phổ biến hơn trong từ Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 藷 giúp đọc hiểu văn bản nông nghiệp cổ và các tên gọi cổ của khoai lang, khoai mì.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 藷 (cổ văn) chỉ các loại cây có củ ăn được như khoai lang (甘藷), khoai mì, hoặc khoai nước. Bộ 艹 gợi nguồn gốc thực vật. Nay thường viết là 薯. Tiểu triện và lục thư thông còn lưu. Chưa có nguồn học thuật xác định cấu trúc đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khoai tây", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 諸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹諸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "諸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藷", "Unihan_Traditional (Chữ Phồn thể)": "藷", "Pinyin_Xie": "shǔ", "Âm Hán Việt_Xie": "chư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loại củ chứa tinh bột. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袀', '{"9000": "7365.0", "Chữ Trung Quốc": "袀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 9 | nét | 袀 | quân | tượng hình | đồng phục, màu sắc đồng nhất | 袀 không có dữ liệu phân tích thành phần từ CHISE. Chữ có bộ 衣 (áo quần) gợi liên quan đến trang phục. Nghĩa là đồng phục, kiểu mẫu thống nhất, hoặc thuần nhất. Cấu trúc chi tiết chưa được phân tích học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quân\": 袀 = áo (衣) + \"quân\" — trang phục \"quân\" (đồng đều) như đồng phục quân đội, tất cả mặc giống nhau. | Gương Hán-Việt | \"quân\" ít dùng riêng lẻ; chủ yếu trong từ cổ 袀服 (đồng phục). | Mở khoá kiến thức | Biết 袀 giúp đọc hiểu văn bản cổ về trang phục và nghi lễ cung đình.", "Tự nguyên_Xie": "袀 (cổ văn) chỉ kiểu mẫu/màu sắc đồng nhất của trang phục (袀服). Cũng có nghĩa là thuần nhất, đồng nhất. Bộ 衣 gợi nguồn gốc liên quan đến áo quần. Chưa có nguồn học thuật xác định cấu trúc đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "袀", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 匀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤匀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袀", "Unihan_Traditional (Chữ Phồn thể)": "袀", "Pinyin_Xie": "jūn", "Âm Hán Việt_Xie": "quân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ trang phục đồng màu của binh lính thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袐', '{"9000": "7366.0", "Chữ Trung Quốc": "袐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袐 | bí | tượng hình | bí mật, ẩn khuất | 袐 không có dữ liệu phân tích thành phần hay Wiktionary. Chữ có hình dạng gần 秘 (bí mật). Đây có thể là dạng biến thể cổ của 秘. Cấu trúc chi tiết chưa được phân tích học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": 袐 gợi lên điều \"bí\" ẩn — như một bí mật được giấu kín, không ai hay biết. | Gương Hán-Việt | \"bí\" trong \"bí mật\" (秘密) — điều không được tiết lộ. | Mở khoá kiến thức | Biết 袐 giúp nhận diện dạng biến thể cổ trong văn bản Hán Nôm chỉ sự bí ẩn.", "Tự nguyên_Xie": "袐 có thể là dạng biến thể cổ của 秘 (bí mật). Không có dữ liệu Wiktionary hay CHISE. Chữ tạo muộn hoặc ít dùng. Chưa có nguồn học thuật xác định cấu trúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Yi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 必", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤必", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "必", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袐", "Unihan_Traditional (Chữ Phồn thể)": "袐", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ chỉ sự kín đáo hoặc danh từ chỉ áo lót. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('覍', '{"9000": "7367.0", "Chữ Trung Quốc": "覍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 見 | Số nét | 10 | nét | 覍 | biện | tượng hình | mũ đội đầu, vương miện | 覍 không có dữ liệu phân tích thành phần từ CHISE hay Wiktionary. Nhìn hình dáng, chữ có bộ 見 (kiến — nhìn thấy) hoặc gần bộ 冠 (mũ). Đây là chữ ít dùng, có thể liên quan đến mũ đội đầu hoặc vương miện. Cấu trúc chi tiết chưa được phân tích học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biện\": 覍 gợi chiếc mũ \"biện\" (弁) trong nghi lễ cung đình — người đội mũ được nhìn nhận (見) là có địa vị. | Gương Hán-Việt | \"biện\" ít dùng riêng lẻ; liên quan đến 弁 (mũ lễ) trong từ cổ. | Mở khoá kiến thức | Biết 覍 giúp nhận diện chữ cổ liên quan đến trang phục và nghi lễ trong văn bản Hán Nôm.", "Tự nguyên_Xie": "覍 là chữ ít dùng, không có dữ liệu Wiktionary hay CHISE. Phiên âm biàn gần với 弁 (biàn — mũ lễ) — một loại mũ đội trong nghi lễ cổ đại Trung Hoa. Chưa có nguồn học thuật xác định cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "覍", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "小 + 見", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱小見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "見", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "小", "Unihan_Simplified (Chữ Giản thể)": "覍", "Unihan_Traditional (Chữ Phồn thể)": "覍", "Pinyin_Xie": "biàn", "Âm Hán Việt_Xie": "biện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ một loại mũ đội đầu của nam giới thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('賹', '{"9000": "7368.0", "Chữ Trung Quốc": "賹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 17 | nét | 賹 | ích | tượng hình | đơn vị tiền tệ cổ | 賹 không có dữ liệu phân tích thành phần từ CHISE. Từ hình dáng, chữ có bộ 貝 (tiền bạc) gợi liên quan đến tiền tệ. Đây là chữ ít dùng, chưa có định nghĩa rõ ràng trong Wiktionary. Cấu trúc chi tiết chưa được phân tích học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ích\": 賹 = tiền (貝) mang lại \"ích\" lợi — chữ cổ liên quan đến tiền bạc và giá trị vật chất. | Gương Hán-Việt | \"ích\" ít dùng riêng lẻ với chữ 賹; \"ích lợi\" thường viết 益利. | Mở khoá kiến thức | Biết 賹 giúp nhận diện chữ cổ liên quan đến tiền tệ trong văn bản Hán Nôm.", "Tự nguyên_Xie": "賹 là chữ ít dùng với bộ 貝 (tiền bạc). Wiktionary chỉ ghi nhận phiên âm mà không có định nghĩa cụ thể (rfdef). Có thể là tên một đơn vị tiền tệ hoặc vật phẩm quý giá thời cổ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "賹", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "貝 + 益", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰貝益", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "益", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "賹", "Unihan_Traditional (Chữ Phồn thể)": "賹", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ cổ ít dùng, chủ yếu làm danh từ chỉ tiền của hoặc tính từ chỉ sự tham lam. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('釛', '{"9000": "7369.0", "Chữ Trung Quốc": "釛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 釛 | ba | tượng hình | dụng cụ kim loại cổ | 釛 không có dữ liệu phân tích thành phần từ CHISE hay Wiktionary. Từ hình dáng, chữ có bộ 金 (kim loại) gợi liên quan đến dụng cụ kim loại. Chữ rất hiếm gặp, cấu trúc chưa được phân tích học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ba\": 釛 = kim loại (金) + \"ba\" — dụng cụ sắt/kim loại cổ xưa, tên gọi đã thất truyền. | Gương Hán-Việt | \"ba\" ít dùng riêng lẻ với chữ 釛. | Mở khoá kiến thức | Biết 釛 giúp nhận diện chữ cổ về dụng cụ kim loại trong văn bản khảo cổ.", "Tự nguyên_Xie": "釛 là chữ rất hiếm gặp, bộ 金 gợi đây là tên một loại dụng cụ hoặc vật liệu kim loại. Không có dữ liệu Wiktionary hay CHISE. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "雛", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 力", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "力", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "釛", "Unihan_Traditional (Chữ Phồn thể)": "釛", "Pinyin_Xie": "bā", "Âm Hán Việt_Xie": "ba", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ cổ hiếm gặp, chủ yếu dùng làm danh từ chỉ công cụ kim loại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鈱', '{"9000": "7370.0", "Chữ Trung Quốc": "鈱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 鈱 | mân | tượng hình | tên một loại kim loại cổ | 鈱 không có dữ liệu phân tích thành phần từ CHISE hay Wiktionary. Bộ 金 gợi đây là tên một loại kim loại. Đây là chữ rất hiếm gặp, cấu trúc chưa được phân tích học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mân\": 鈱 = kim loại (金) + \"mân\" — một loại kim loại cổ mang tên \"mân\", nay đã ít dùng. | Gương Hán-Việt | \"mân\" ít dùng riêng lẻ với chữ 鈱. | Mở khoá kiến thức | Biết 鈱 giúp nhận diện chữ cổ về kim loại trong văn bản khảo cổ.", "Tự nguyên_Xie": "鈱 là chữ rất hiếm gặp, bộ 金 gợi đây là tên một loại kim loại. Wiktionary chỉ ghi nhận phiên âm mà không có định nghĩa (rfdef). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鈱", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 民", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金民", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "民", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鈱", "Unihan_Traditional (Chữ Phồn thể)": "鈱", "Pinyin_Xie": "mín", "Âm Hán Việt_Xie": "mân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ cổ hiếm dùng, chủ yếu đóng vai trò danh từ chỉ đồ kim khí. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鈶', '{"9000": "7371.0", "Chữ Trung Quốc": "鈶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 鈶 | tứ | tượng hình | tên một loại kim loại cổ | 鈶 không có dữ liệu phân tích thành phần từ CHISE hay Wiktionary. Bộ 金 gợi đây là tên một loại kim loại. Đây là chữ rất hiếm gặp, cấu trúc chưa được phân tích học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tứ\": 鈶 = kim loại (金) + \"tứ\" — một loại kim loại cổ mang tên \"tứ\", dùng trong đúc đồ vật thời xưa. | Gương Hán-Việt | \"tứ\" ít dùng riêng lẻ với chữ 鈶. | Mở khoá kiến thức | Biết 鈶 giúp nhận diện chữ cổ về kim loại trong văn bản khảo cổ.", "Tự nguyên_Xie": "鈶 là chữ rất hiếm gặp, bộ 金 gợi đây là tên một loại kim loại. Wiktionary chỉ ghi nhận phiên âm mà không có định nghĩa (rfdef). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": ":", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 台", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金台", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "台", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鈶", "Unihan_Traditional (Chữ Phồn thể)": "鈶", "Pinyin_Xie": "sì", "Âm Hán Việt_Xie": "tứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ cổ dùng làm danh từ chỉ nông cụ thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鍦', '{"9000": "7372.0", "Chữ Trung Quốc": "鍦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 鍦 | ti | tượng hình | một loại giáo mác cổ | 鍦 không có dữ liệu phân tích thành phần từ CHISE. Từ hình dáng, chữ có bộ 金 (kim loại) gợi đây là vũ khí bằng kim loại. Đây là chữ cổ, lỗi thời (obsolete), chỉ loại giáo mác. Cấu trúc chi tiết chưa được phân tích học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ti\": 鍦 = kim loại (金) + \"ti\" — giáo \"ti\" (dài và nhọn bằng kim loại), vũ khí đặc trưng của kỵ binh cổ đại. | Gương Hán-Việt | \"ti\" ít dùng riêng lẻ với chữ 鍦. | Mở khoá kiến thức | Biết 鍦 giúp đọc hiểu văn bản cổ về vũ khí và chiến tranh.", "Tự nguyên_Xie": "鍦 (cổ văn) chỉ một loại giáo mác. Bộ 金 gợi đây là vũ khí bằng kim loại. Chữ đã lỗi thời, không còn dùng trong tiếng Trung hiện đại. Chưa có nguồn học thuật xác định cấu trúc đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Mì", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 施", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金施", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "施", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鍦", "Unihan_Traditional (Chữ Phồn thể)": "鍦", "Pinyin_Xie": "shī", "Âm Hán Việt_Xie": "ti", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ cổ dùng làm danh từ chỉ một loại binh khí dài thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('閯', '{"9000": "7373.0", "Chữ Trung Quốc": "閯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 15 | nét | 閯 | sáp | tượng hình | cửa gài, cổng đóng | 閯 không có dữ liệu phân tích thành phần từ CHISE hay Wiktionary. Từ hình dáng, chữ có bộ 門 (cửa) gợi liên quan đến cửa/cổng. Đây là chữ rất hiếm gặp. Cấu trúc chi tiết chưa được phân tích học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sáp\": 閯 = cửa (門) + \"sáp\" — cánh cửa được \"sáp\" (cài, chốt) lại, kín đáo và bí ẩn. | Gương Hán-Việt | \"sáp\" ít dùng riêng lẻ với chữ 閯. | Mở khoá kiến thức | Biết 閯 giúp nhận diện chữ cổ liên quan đến cửa và cổng trong văn bản Hán Nôm.", "Tự nguyên_Xie": "閯 là chữ rất hiếm gặp, không có dữ liệu Wiktionary hay CHISE. Bộ 門 gợi liên quan đến cửa hoặc cổng. Chưa có nguồn học thuật xác định cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鯯", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "門 + 沙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門沙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "沙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "閯", "Unihan_Traditional (Chữ Phồn thể)": "閯", "Pinyin_Xie": "shà", "Âm Hán Việt_Xie": "sáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ cổ dùng làm danh từ chỉ cửa nhỏ hoặc động từ chỉ hành động đóng cửa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('閺', '{"9000": "7374.0", "Chữ Trung Quốc": "閺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 16 | nét | 閺 | vân | tượng hình | cửa, cổng cổ | 閺 không có dữ liệu phân tích thành phần từ CHISE hay Wiktionary. Từ hình dáng, chữ có bộ 門 (cửa) gợi liên quan đến cửa/cổng. Đây là chữ rất hiếm gặp. Cấu trúc chi tiết chưa được phân tích học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vân\": 閺 = cửa (門) + \"vân\" — cánh cửa cổ xưa \"vân\" vút lên (trang trí hoa văn mây), kiểu dáng cổ kính. | Gương Hán-Việt | \"vân\" ít dùng riêng lẻ với chữ 閺. | Mở khoá kiến thức | Biết 閺 giúp nhận diện chữ cổ liên quan đến cửa trong văn bản Hán Nôm.", "Tự nguyên_Xie": "閺 là chữ rất hiếm gặp, không có dữ liệu Wiktionary hay CHISE. Bộ 門 gợi liên quan đến cửa hoặc cổng. Chưa có nguồn học thuật xác định cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "7374.0", "Tần Suất % (Jun Da)": "99.9982636019", "GavinGrover_Once (Chiết tự trực tiếp)": "門 + 旻", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門旻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "閺", "Unihan_Traditional (Chữ Phồn thể)": "閺", "Pinyin_Xie": "wén", "Âm Hán Việt_Xie": "văn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ cổ dùng làm danh từ riêng chỉ địa danh hoặc động từ chỉ hành vi nhìn xuống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隂', '{"9000": "7375.0", "Chữ Trung Quốc": "隂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 11 | nét | 隂 | âm | tượng hình | âm (mặt tối, bóng mát); biến thể của 陰 | 隂 không có dữ liệu phân tích thành phần từ CHISE hay Wiktionary. Đây là dạng biến thể/cổ thể của 陰 (âm — mặt tối, bóng mát, âm dương). Kim văn, tiểu triện và lục thư thông còn lưu nhiều dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"âm\": 隂 là dạng cổ của 陰 — phía \"âm\" tối mát, đối lập với dương sáng ấm, nền tảng của triết học âm dương. | Gương Hán-Việt | \"âm\" trong \"âm dương\" (陰陽), \"âm mưu\" (陰謀), \"âm lịch\" (âm lịch). | Mở khoá kiến thức | Biết 隂/陰 mở khoá: âm dương (陰陽), âm mưu (陰謀), âm lịch, âm thanh (nhưng 音 khác chữ).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 隂 là dạng biến thể cổ của 陰, chỉ phía tối (bóng mát), mặt trăng, âm khí trong âm dương. Kim văn còn lưu nhiều dạng khác nhau, cho thấy chữ có quá trình hình thành phức tạp. Tiểu triện và lục thư thông cũng còn lưu. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bóng mát; mặt trái, mặt sau; số âm; ngầm, bí mật", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "隂", "Unihan_Traditional (Chữ Phồn thể)": "隂", "Pinyin_Xie": "yīn", "Âm Hán Việt_Xie": "âm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Phó từ | 副词 | Thường làm danh từ chỉ bóng râm hoặc tính từ chỉ tính chất ngầm, kín đáo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('顪', '{"9000": "7376.0", "Chữ Trung Quốc": "顪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 22 | nét | 顪 | hối | tượng hình | cằm, phần dưới khuôn mặt | 顪 không có dữ liệu phân tích thành phần từ CHISE hay Wiktionary. Từ hình dáng, chữ có bộ 頁 (đầu/mặt) gợi liên quan đến bộ phận khuôn mặt. Có thể liên quan đến cằm hoặc vùng râu. Cấu trúc chi tiết chưa được phân tích học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hối\": 顪 = mặt (頁) + \"hối\" — bộ phận dưới khuôn mặt, vùng cằm \"hối\" (ám muội, tối) — nơi râu mọc. | Gương Hán-Việt | \"hối\" ít dùng riêng lẻ với chữ 顪. | Mở khoá kiến thức | Biết 顪 giúp nhận diện chữ cổ về giải phẫu khuôn mặt trong văn bản y học hoặc nhân tướng cổ.", "Tự nguyên_Xie": "顪 là chữ ít dùng, có bộ 頁 (đầu/mặt). Wiktionary chỉ ghi nhận phiên âm mà không có định nghĩa (rfdef). Có thể chỉ vùng cằm hoặc râu. Chưa có nguồn học thuật xác định cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "TÔI", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "歲 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰歲頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "歲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "顪", "Unihan_Traditional (Chữ Phồn thể)": "顪", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "hối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn ngôn để chỉ phần râu dưới cằm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驌', '{"9000": "7377.0", "Chữ Trung Quốc": "驌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 23 | nét | 驌 | túc | tượng hình | tên danh mã trong điển tích 驌驦 | 驌 là chữ chuyên dùng trong tên 驌驦 (Túc Sương — danh mã). Cấu trúc thành phần không được Wiktionary phân tích rõ. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"túc\": chữ chỉ dùng trong tên danh mã 驌驦 (Túc Sương) — hình ảnh con ngựa quý trong điển cố. | Gương Hán-Việt | túc (驌) — chỉ gặp trong tên 驌驦 | Mở khoá kiến thức | Biết 驌 giúp nhận ra điển tích 驌驦 trong Hán văn cổ.", "Tự nguyên_Xie": "Chữ 驌 không có phân tích hình thanh hay hội ý từ Wiktionary. Chỉ xuất hiện trong 驌驦 — tên của một con ngựa huyền thoại trong văn học cổ Trung Hoa. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Sou", "Hạng Tần Suất (Jun Da)": "6788.0", "Tần Suất % (Jun Da)": "99.9957711472", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 肅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬肅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "骕", "Unihan_Traditional (Chữ Phồn thể)": "驌", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "túc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn học cổ để chỉ loài ngựa quý chạy nhanh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驘', '{"9000": "7378.0", "Chữ Trung Quốc": "驘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 23 | nét | 驘 | loa | tượng hình | con la (mule) — dị thể của 騾 | 驘 là dị thể của 騾 (con la). Cấu trúc không được phân tích riêng; theo Wiktionary, 驘 xem tại 騾. Tiểu triện ghi lại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"loa\": dị thể của 騾 (loa) — con LOA (la), loài lai giữa ngựa và lừa. | Gương Hán-Việt | loa (驘/騾) — trong 騾馬 (loa mã: con la) | Mở khoá kiến thức | Biết 驘/騾 giúp đọc văn bản cổ về phương tiện vận tải truyền thống.", "Tự nguyên_Xie": "Tiểu triện | 驘 là dị thể của 騾 (con la — mule). 騾 là chữ hình thanh: 馬 (mã) biểu nghĩa, phần trên biểu âm. Con la là loài lai giữa ngựa và lừa. Tiểu triện ghi lại dạng 驘. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "loa; như \"loa (con la)\" \nNguyên là chữ loa 騾.", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "𣎆 + 馬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𣎆馬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𣎆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "驘", "Unihan_Traditional (Chữ Phồn thể)": "驘", "Pinyin_Xie": "luó", "Âm Hán Việt_Xie": "loa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ con la dùng để thồ hàng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鰠', '{"9000": "7379.0", "Chữ Trung Quốc": "鰠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 20 | nét | 魚 | ngư | biểu nghĩa | cá | 騷 | tao | biểu âm | phần biểu âm | 鰠 là chữ hình thanh: 魚 (Ngư, biểu nghĩa: cá) + thành phần biểu âm. Chỉ một loài cá cổ đại giống cá tầm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tao\": bộ 魚 (cá) — loài cá cổ xưa mang tên tao. | Gương Hán-Việt | tao — dùng trong tên cá cổ | Mở khoá kiến thức | Biết 鰠 giúp nhận ra các chữ chỉ loài cá cổ đại trong thư tịch Hán.", "Tự nguyên_Xie": "Chữ hình thanh, bộ 魚 chỉ loài cá. Chỉ một loài cá cổ đại tương tự cá tầm; chữ ít dùng, chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鰠", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 蚤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚蚤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蚤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鰠", "Unihan_Traditional (Chữ Phồn thể)": "鰠", "Pinyin_Xie": "sāo", "Âm Hán Việt_Xie": "tao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong cổ văn để chỉ một loài cá nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲗', '{"9000": "7380.0", "Chữ Trung Quốc": "鲗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 14 | nét | 魚 | ngư | biểu nghĩa | cá/sinh vật biển | 則 | tắc | biểu âm | phần biểu âm | 鲗 là chữ hình thanh (giản thể của 鰂): 魚 (Ngư, biểu nghĩa: sinh vật biển) + 則 (Tắc, biểu âm). Chỉ mực nang (cuttlefish).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tặc\": 魚 (sinh vật biển) + 則 — mực nang tặc tinh vi ẩn nấp dưới đáy biển. | Gương Hán-Việt | tặc — trong 烏鲗 (ô tặc, mực nang) | Mở khoá kiến thức | Biết 鲗 giúp đọc được 烏鲗 (mực nang) trong văn bản y học và ẩm thực cổ điển.", "Tự nguyên_Xie": "Hình thanh tự: bộ 魚 biểu nghĩa, 則 biểu âm. Dùng trong 烏鲗 (ô tặc) — mực nang. Phồn thể là 鰂. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ô tặc 烏鰂,乌鲗)", "Hạng Tần Suất (Jun Da)": "7380.0", "Tần Suất % (Jun Da)": "99.9982925419", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鲗", "Unihan_Traditional (Chữ Phồn thể)": "鰂", "Pinyin_Xie": "zéi", "Âm Hán Việt_Xie": "tặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường dùng trong từ ghép để chỉ loài cá mực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶒', '{"9000": "7381.0", "Chữ Trung Quốc": "鶒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 20 | nét | 勅 | sắc | biểu âm | phần biểu âm | 鳥 | điểu | biểu nghĩa | chim | 鶒 là chữ hình thanh: 勅 (Sắc, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim). Chỉ loài chim trong tên ghép 鸂鶒.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sắc\": 鳥 (chim) + 勅 — loài chim sắc đẹp rực rỡ trong thi ca cổ điển. | Gương Hán-Việt | sắc — trong 鸂鶒 (khê sắc, loài vịt đẹp) | Mở khoá kiến thức | Biết 鶒 giúp đọc 鸂鶒 (khê sắc) thường xuất hiện trong thơ Đường Tống.", "Tự nguyên_Xie": "Hình thanh tự: bộ 鳥 biểu nghĩa (chim), 勅 biểu âm (đọc sắc/chì). Chỉ dùng trong tên ghép 鸂鶒 — một loài vịt đẹp trong thơ văn cổ điển. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khê xích 鸂鶒)", "Hạng Tần Suất (Jun Da)": "7381.0", "Tần Suất % (Jun Da)": "99.9982946091", "GavinGrover_Once (Chiết tự trực tiếp)": "束 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰束", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鶒", "Unihan_Traditional (Chữ Phồn thể)": "鶒", "Pinyin_Xie": "chì", "Âm Hán Việt_Xie": "xích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và hầu như chỉ xuất hiện trong tên loài chim khê sắc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶗', '{"9000": "7382.0", "Chữ Trung Quốc": "鶗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 20 | nét | 鶗 | đề | tượng hình | loài chim kêu tiếng đề | 鶗 là chữ chỉ loài chim, dùng trong tên ghép 鶗鴂 (đề quyết — chim đỗ quyên/tử quy). Cấu trúc chưa được phân tích rõ trong thư tịch hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đề\": chim đề quyết cất tiếng kêu thảm thiết báo hè về. | Gương Hán-Việt | đề — trong 鶗鴂 (đề quyết, đỗ quyên) | Mở khoá kiến thức | Biết 鶗 giúp đọc 鶗鴂 (đỗ quyên) trong thơ văn Sở Từ và thơ Đường.", "Tự nguyên_Xie": "Chỉ dùng trong tên ghép 鶗鴂 (đề quyết), chỉ loài chim đỗ quyên kêu vào mùa hè. Nguồn gốc chữ chưa có học thuật chi tiết; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim đỗ quyên; chim cuốc", "Hạng Tần Suất (Jun Da)": "7382.0", "Tần Suất % (Jun Da)": "99.9982966762", "GavinGrover_Once (Chiết tự trực tiếp)": "是 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴是鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "是", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鶗", "Unihan_Traditional (Chữ Phồn thể)": "鶗", "Pinyin_Xie": "tí", "Âm Hán Việt_Xie": "đề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ chim đỗ quyên hoặc chim cuốc trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硙', '{"9000": "7383.0", "Chữ Trung Quốc": "硙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 硙 | ngại | tượng hình | cối xay đá | 硙 là chữ chỉ cối xay đá (millstone). Bộ 石 liên quan đến đá. Cấu trúc chi tiết chưa được phân tích đầy đủ trong thư tịch hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngại\": hòn đá ngại ngùng cứng chắc nghiền hạt trong cối xay. | Gương Hán-Việt | ngại — cối xay đá trong nông cụ cổ | Mở khoá kiến thức | Biết 硙 giúp đọc các mô tả nông cụ truyền thống trong thư tịch Hán.", "Tự nguyên_Xie": "Chỉ cối xay bằng đá (stone mill/grinder). Chữ ít dùng, chủ yếu xuất hiện trong thư tịch cổ và từ điển kỹ thuật nông cụ. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cối tán, cái bàn tán; bền chắc, vững vàng", "Hạng Tần Suất (Jun Da)": "7383.0", "Tần Suất % (Jun Da)": "99.9983049448", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 岂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石岂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "岂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硙", "Unihan_Traditional (Chữ Phồn thể)": "磑", "Pinyin_Xie": "wéi", "Âm Hán Việt_Xie": "cai, ngại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ dụng cụ xay nghiền hoặc làm tính từ chỉ sự vững chắc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禜', '{"9000": "7384.0", "Chữ Trung Quốc": "禜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 15 | nét | 榮 | vinh | biểu âm | vinh quang, phần biểu âm | 示 | thị | biểu nghĩa | tế lễ, thần linh | 禜 là chữ hình thanh: 榮 (Vinh, biểu âm, rút gọn) + 示 (Thị, biểu nghĩa: tế lễ). Chỉ nghi lễ cầu đảo tại bờ sông để trừ tai họa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vĩnh\": 示 (tế lễ) + 榮 (vinh) — lễ tế vĩnh cầu để trừ tai họa vĩnh viễn. | Gương Hán-Việt | vĩnh — lễ cầu đảo trong điển chế Chu Lễ | Mở khoá kiến thức | Biết 禜 giúp đọc các đoạn mô tả nghi lễ trong Chu Lễ và thư tịch cổ điển.", "Tự nguyên_Xie": "Hình thanh tự: bộ 示 biểu nghĩa (lễ tế, thần linh), 榮 biểu âm (rút gọn). Chỉ lễ tế cầu mưa hoặc trừ tai họa tại bờ sông. Âm đọc vĩnh/vinh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "như chữ 榮", "Hạng Tần Suất (Jun Da)": "7384.0", "Tần Suất % (Jun Da)": "99.9983070119", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 示", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱示", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "禜", "Unihan_Traditional (Chữ Phồn thể)": "禜", "Pinyin_Xie": "yǒng", "Âm Hán Việt_Xie": "vinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ nghi thức cúng tế thần sông núi thời cổ đại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糢', '{"9000": "7385.0", "Chữ Trung Quốc": "糢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 16 | nét | 米 | mễ | biểu nghĩa | gạo, lương thực | 莫 | mạc | biểu âm | phần biểu âm | 糢 là chữ hình thanh: 米 (Mễ, biểu nghĩa: gạo) + 莫 (Mạc, biểu âm). Chỉ khuôn bánh hoặc bánh nếp; cũng dùng thay 模 trong 糢糊.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mô\": 米 (gạo) + 莫 — khuôn bánh gạo mô phỏng hình dáng, đường nét mờ mô hồ. | Gương Hán-Việt | mô — trong 糢糊 (mô hồ, không rõ ràng) | Mở khoá kiến thức | Biết 糢 giúp đọc 糢糊 (mô hồ) — biến thể của 模糊 trong văn bản cũ.", "Tự nguyên_Xie": "Hình thanh tự: bộ 米 biểu nghĩa (gạo, lương thực), 莫 biểu âm. Nghĩa gốc là bánh nếp hoặc khuôn bánh. Dùng trong 糢糊 (mô hồ — không rõ ràng). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái khuôn bằng gỗ; mô phỏng; gương mẫu; mơ hồ, mập mờ", "Hạng Tần Suất (Jun Da)": "7385.0", "Tần Suất % (Jun Da)": "99.998309079", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 莫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米莫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "莫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "糢", "Unihan_Traditional (Chữ Phồn thể)": "糢", "Pinyin_Xie": "mó", "Âm Hán Việt_Xie": "mô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ biểu thị trạng thái không rõ ràng hoặc làm danh từ chỉ khuôn mẫu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藠', '{"9000": "7386.0", "Chữ Trung Quốc": "藠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 艹 | thảo | biểu nghĩa | cỏ cây, thực vật | 皛 | hiệu | biểu âm | phần biểu âm | 藠 là chữ hình thanh: 艹 (Thảo, biểu nghĩa: thực vật) + 皛 (Hiệu, biểu âm). Chỉ củ kiệu (rakkyo/Chinese shallot), cây gia vị phổ biến ở Nam Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiệu\": 艹 (cây) + 皛 — củ kiệu mọc thành chùm, thơm nồng trong dưa chua. | Gương Hán-Việt | kiệu — củ kiệu, giống hành trong ẩm thực | Mở khoá kiến thức | Biết 藠 giúp nhận ra 藠头 (kiệu đầu — củ kiệu) trong thực đơn và thư tịch ẩm thực Nam Trung Quốc.", "Tự nguyên_Xie": "Hình thanh tự: bộ 艹 biểu nghĩa (thực vật), 皛 biểu âm. Chỉ cây kiệu (藠头 — củ kiệu), một loại rau gia vị trong họ hành. Phổ biến ở phương ngữ Hẹ và các tỉnh Nam Trung Quốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây kiệu", "Hạng Tần Suất (Jun Da)": "7386.0", "Tần Suất % (Jun Da)": "99.9983111462", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 皛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹皛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藠", "Unihan_Traditional (Chữ Phồn thể)": "藠", "Pinyin_Xie": "jiào", "Âm Hán Việt_Xie": "hiểu, khiếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cây thân thảo có củ dùng làm thức ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镦', '{"9000": "7387.0", "Chữ Trung Quốc": "镦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 镦 | đối | tượng hình | vật kim loại đầu mút, chốt kim loại | 镦 là chữ chỉ đầu mút kim loại (butt cap) gắn vào cuối cán giáo, hoặc kỹ thuật rèn ép (upsetting). Bộ 金 liên quan đến kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đối\": chốt kim loại đối xứng ở hai đầu cán vũ khí, chắc chắn như đá. | Gương Hán-Việt | đối — trong thuật ngữ rèn đúc và vũ khí cổ | Mở khoá kiến thức | Biết 镦 giúp đọc các tài liệu về vũ khí cổ và kỹ thuật rèn trong thư tịch Hán.", "Tự nguyên_Xie": "Bộ 金 biểu nghĩa (kim loại). Nghĩa 1: đầu mút kim loại gắn vào cán vũ khí (靶镦). Nghĩa 2: kỹ thuật rèn ép kim loại. Dùng trong cả văn bản lịch sử lẫn kỹ thuật. Chưa có nguồn học thuật chi tiết về glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phần chuôi giáo mác bịt đồng cho bằng; thiến", "Hạng Tần Suất (Jun Da)": "7387.0", "Tần Suất % (Jun Da)": "99.9983132133", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 敦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅敦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镦", "Unihan_Traditional (Chữ Phồn thể)": "鐓", "Pinyin_Xie": "duì", "Âm Hán Việt_Xie": "đôn, đối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ bộ phận kim loại bọc đuôi vũ khí hoặc làm động từ chỉ việc thiến gia súc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕂', '{"9000": "7388.0", "Chữ Trung Quốc": "蕂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 艹 | thảo | biểu nghĩa | cỏ cây, thực vật | 勝 | thắng | biểu âm | phần biểu âm | 蕂 là chữ hình thanh: 艹 (Thảo, biểu nghĩa: thực vật) + phần biểu âm. Chỉ dùng trong tên cây 苣蕂.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thắng\": 艹 (cây cỏ) — cây thắng trong thảo dược cổ điển. | Gương Hán-Việt | thắng — trong 苣蕂 (cự thắng, tên cây cổ) | Mở khoá kiến thức | Biết 蕂 giúp đọc 苣蕂 trong từ điển thảo dược cổ điển.", "Tự nguyên_Xie": "Bộ 艹 biểu nghĩa (thực vật). Chỉ dùng trong 苣蕂 — tên một loại cây cỏ trong thư tịch y học cổ điển. Chưa có nguồn học thuật chi tiết; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "肂", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 勝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹勝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕂", "Unihan_Traditional (Chữ Phồn thể)": "蕂", "Pinyin_Xie": "shèng", "Âm Hán Việt_Xie": "thắng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này chủ yếu dùng làm danh từ chỉ loại cỏ hoặc động từ liên quan đến việc chôn cất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霮', '{"9000": "7389.0", "Chữ Trung Quốc": "霮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 20 | nét | 雨 | vũ | biểu nghĩa | mưa, thời tiết | 覃 | đàm | biểu âm | phần biểu âm | 霮 là chữ hình thanh: 雨 (Vũ, biểu nghĩa: mưa/thời tiết) + 覃 (Đàm, biểu âm). Chỉ bầu trời nhiều mây, u ám.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đam\": 雨 (mưa trời) + 覃 — trời đam mây đen đặc, ảm đạm trước cơn mưa. | Gương Hán-Việt | đam — trời âm u, ảm đạm trong thơ cổ | Mở khoá kiến thức | Biết 霮 giúp đọc miêu tả thời tiết trong thơ văn cổ điển.", "Tự nguyên_Xie": "Hình thanh tự: bộ 雨 biểu nghĩa (mưa, trời), 覃 biểu âm (đọc đàm). Chỉ trạng thái trời nhiều mây ảm đạm. Chữ ít dùng trong thơ cổ điển. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mật độ mây", "Hạng Tần Suất (Jun Da)": "7389.0", "Tần Suất % (Jun Da)": "99.9983173476", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 湛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨湛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "湛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霮", "Unihan_Traditional (Chữ Phồn thể)": "霮", "Pinyin_Xie": "dàn", "Âm Hán Việt_Xie": "đạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường dùng làm tính từ để miêu tả trạng thái mây mù dày đặc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沩', '{"9000": "7390.0", "Chữ Trung Quốc": "沩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 氵 | thuỷ | biểu nghĩa | nước, sông | 爲 | vi | biểu âm | phần biểu âm | 沩 là chữ hình thanh: 氵 (Thuỷ, biểu nghĩa: nước/sông) + 爲 (Vi, biểu âm). Là tên sông Quy/Vi tại Hồ Nam, Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vi\": 氵 (sông) + 爲 (vi) — dòng sông Vi chảy qua đất Quy Dương. | Gương Hán-Việt | vi — tên sông 沩水 ở Hồ Nam | Mở khoá kiến thức | Biết 沩 giúp đọc địa danh và tên thiền phái 沩仰宗 (Quy Ngưỡng tông) trong Phật học.", "Tự nguyên_Xie": "Hình thanh tự: bộ 氵 biểu nghĩa (nước, sông), 爲 biểu âm (đọc vi/wéi). Tên sông Quy (沩水) ở Hồ Nam. Chữ Nôm đọc là ''vơi'' hoặc ''vời''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Vi (ở tỉnh Hồ Nam của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "7390.0", "Tần Suất % (Jun Da)": "99.9983194147", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 为", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵为", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "为", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沩", "Unihan_Traditional (Chữ Phồn thể)": "溈", "Pinyin_Xie": "wéi", "Âm Hán Việt_Xie": "duy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ tên sông hoặc địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禬', '{"9000": "7391.0", "Chữ Trung Quốc": "禬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 17 | nét | 示 | thị | biểu nghĩa | tế lễ, thần linh | 會 | hội | biểu âm | phần biểu âm | 禬 là chữ hình thanh: 示 (Thị, biểu nghĩa: tế lễ) + 會 (Hội, biểu âm). Chỉ lễ tế trừ tai, dùng trong 禬禳.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quái\": 示 (tế lễ) + 會 — lễ tế hội tụ quái dị để trừ tai họa. | Gương Hán-Việt | quái — trong 禬禳 (quái nhương, lễ trừ tai) | Mở khoá kiến thức | Biết 禬 giúp đọc các mô tả nghi lễ trừ tai trong Chu Lễ và thư tịch cổ điển.", "Tự nguyên_Xie": "Hình thanh tự: bộ 示 biểu nghĩa (tế lễ), 會 biểu âm. Chỉ lễ cầu đảo trừ tai họa (禬禳 — quái nhương). Âm đọc quái/guì. Chữ chỉ dùng trong thuật ngữ nghi lễ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "禬", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 會", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻會", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "會", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禬", "Unihan_Traditional (Chữ Phồn thể)": "禬", "Pinyin_Xie": "guì", "Âm Hán Việt_Xie": "quái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này dùng làm danh từ chỉ nghi lễ cúng tế hoặc động từ thực hiện tế lễ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴪', '{"9000": "7392.0", "Chữ Trung Quốc": "鴪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 16 | nét | 鴪 | dục | tượng hình | chim bay nhanh | 鴪 là biến thể của 鴥 — chỉ chim bay nhanh, vụt qua. Cấu trúc chưa được phân tích đầy đủ; bộ 鳥 liên quan đến chim.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dục\": chim vút lên dục dặc, bay nhanh như tên bắn. | Gương Hán-Việt | dục — trong nghĩa chim bay nhanh (biến thể 鴥) | Mở khoá kiến thức | Biết 鴪 giúp đọc các thư tịch cổ có dùng biến thể chữ tả loài chim.", "Tự nguyên_Xie": "Biến thể cổ của 鴥 (yù). Nghĩa: chim bay nhanh, vụt bay. Dùng trong thơ Kinh Thi và thư tịch cổ. Chưa có nguồn học thuật chi tiết về glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem \"鴥\"", "Hạng Tần Suất (Jun Da)": "7392.0", "Tần Suất % (Jun Da)": "99.9983256162", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰穴鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鳥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "鴪", "Unihan_Traditional (Chữ Phồn thể)": "鴪", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "duật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm tính từ miêu tả dáng bay nhanh của loài chim. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鮨', '{"9000": "7393.0", "Chữ Trung Quốc": "鮨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 魚 | ngư | biểu nghĩa | cá, sinh vật biển | 旨 | chỉ | biểu âm | phần biểu âm | 鮨 là chữ hình thanh: 魚 (Ngư, biểu nghĩa: cá) + 旨 (Chỉ, biểu âm). Nghĩa 1: mắm cá (fish paste). Nghĩa 2: cá mú (grouper).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": 魚 (cá) + 旨 (ngon) — mắm cá kỳ diệu ngon lạ, tiền thân của sushi. | Gương Hán-Việt | kỳ — mắm cá trong thư tịch ẩm thực cổ | Mở khoá kiến thức | Biết 鮨 giúp đọc nguồn gốc lịch sử của sushi và mắm cá trong thư tịch Hán.", "Tự nguyên_Xie": "Hình thanh tự: bộ 魚 biểu nghĩa, 旨 biểu âm. Nghĩa gốc là mắm cá (fish paste/sushi nền). Âm đọc kỳ (qí) chỉ mắm cá; âm ký (yì) chỉ loài cá mú. Liên quan đến nguồn gốc của chữ 鮨 trong ẩm thực Nhật Bản (sushi cổ). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá song; cá nghệ (một loại cá, mình dẹt, màu hồng hoặc màu nâu xám, có vằn, miệng to, răng nhỏ nhưng nhọn. Phần lớn sống ở biển)", "Hạng Tần Suất (Jun Da)": "7393.0", "Tần Suất % (Jun Da)": "99.9983276833", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 旨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚旨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鮨", "Unihan_Traditional (Chữ Phồn thể)": "鮨", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "nghễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ các loại cá biển hoặc món ăn từ cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鱣', '{"9000": "7394.0", "Chữ Trung Quốc": "鱣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 24 | nét | 魚 | ngư | biểu nghĩa | cá | 亶 | đản | biểu âm | phần biểu âm | 鱣 là chữ hình thanh: 魚 (Ngư, biểu nghĩa: cá) + 亶 (Đản, biểu âm). Chỉ cá tầm lớn (sturgeon) — loài cá quý thường nhắc đến trong kinh điển.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiên\": 魚 (cá) + 亶 — cá tầm chiên vàng đã là món quý từ thời Kinh Thi. | Gương Hán-Việt | chiên — cá tầm lớn trong Kinh Thi và địa lý cổ | Mở khoá kiến thức | Biết 鱣 giúp đọc Kinh Thi và các tài liệu địa lý, lịch sử nhắc đến loài cá tầm quý.", "Tự nguyên_Xie": "Hình thanh tự: bộ 魚 biểu nghĩa, 亶 biểu âm (đọc chiên/zhān). Chỉ loài cá tầm lớn sống ở sông lớn Trung Hoa cổ đại. Xuất hiện trong Kinh Thi và thư tịch địa lý. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Rắn", "Hạng Tần Suất (Jun Da)": "7291.0", "Tần Suất % (Jun Da)": "99.9980258808", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 亶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚亶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鳣", "Unihan_Traditional (Chữ Phồn thể)": "鱣", "Pinyin_Xie": "zhān", "Âm Hán Việt_Xie": "chiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ loài cá tầm hoặc loài rắn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盝', '{"9000": "7395.0", "Chữ Trung Quốc": "盝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 13 | nét | 盝 | lộc | tượng hình | hộp đựng đồ, bàn phấn nhỏ | 盝 là chữ có bộ 皿 liên quan đến đồ vật đựng. Chỉ bàn trang điểm nhỏ hoặc nghĩa ''nhỏ giọt''. Cấu trúc chi tiết chưa được phân tích đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lộc\": chiếc bàn phấn nhỏ xinh như lộc non, đồ vật trong phòng khuê. | Gương Hán-Việt | lộc — bàn trang điểm nhỏ trong thư tịch đồ vật cổ | Mở khoá kiến thức | Biết 盝 giúp đọc mô tả đồ vật cổ trong thư tịch văn hóa vật chất Trung Hoa.", "Tự nguyên_Xie": "Nghĩa 1: nhỏ giọt (drip). Nghĩa 2: bàn trang điểm nhỏ (small dressing table). Bộ 皿 liên quan đến đồ vật chứa đựng. Chữ ít dùng trong thư tịch cổ. Chưa có nguồn học thuật chi tiết; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lọc; khô cạn", "Hạng Tần Suất (Jun Da)": "7395.0", "Tần Suất % (Jun Da)": "99.9983313008", "GavinGrover_Once (Chiết tự trực tiếp)": "录 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱录皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "录", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盝", "Unihan_Traditional (Chữ Phồn thể)": "盝", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường dùng làm động từ chỉ hành động lọc nước hoặc làm cạn nước. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眹', '{"9000": "7396.0", "Chữ Trung Quốc": "眹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 11 | nét | 目 | mục | biểu nghĩa | mắt | 朕 | trẫm | biểu âm | phần biểu âm, cũng mang nghĩa điềm báo | 眹 là chữ hình thanh: 目 (Mục, biểu nghĩa: mắt) + 朕 (Trẫm, biểu âm, cũng gợi nghĩa điềm báo). Chỉ con ngươi mắt hoặc điềm ứng của mắt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trẫm\": 目 (mắt) + 朕 — con mắt trẫm thấy điềm báo trước vận mệnh. | Gương Hán-Việt | trẫm — con ngươi mắt hoặc điềm báo qua mắt | Mở khoá kiến thức | Biết 眹 giúp đọc thuật ngữ y học cổ và thiên văn học về điềm ứng.", "Tự nguyên_Xie": "Hình thanh tự: bộ 目 biểu nghĩa (mắt), 朕 biểu âm (đọc trẫm). Nghĩa: con ngươi mắt, hoặc điềm báo thấy qua mắt. Kết hợp giữa mắt (目) và 朕 (triệu chứng, điềm báo). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ngươi; trẫm triệu, điềm báo trước; hiện tượng", "Hạng Tần Suất (Jun Da)": "7396.0", "Tần Suất % (Jun Da)": "99.9983328512", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 关", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目关", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "关", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眹", "Unihan_Traditional (Chữ Phồn thể)": "眹", "Pinyin_Xie": "zhèn", "Âm Hán Việt_Xie": "trẫm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con ngươi hoặc dấu hiệu dự báo điềm lành dữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睖', '{"9000": "7397.0", "Chữ Trung Quốc": "睖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 13 | nét | 目 | mục | biểu nghĩa | mắt | 夌 | lăng | biểu âm | phần biểu âm | 睖 là chữ hình thanh: 目 (Mục, biểu nghĩa: mắt) + 夌 (Lăng, biểu âm). Chỉ trạng thái nhìn chằm chằm hoặc nhìn trống rỗng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lăng\": 目 (mắt) — đôi mắt lăng ngăng nhìn chằm chằm không chớp. | Gương Hán-Việt | lăng — nhìn trừng trừng trong văn học cổ | Mở khoá kiến thức | Biết 睖 giúp đọc miêu tả biểu cảm khuôn mặt trong văn học cổ điển.", "Tự nguyên_Xie": "Hình thanh tự: bộ 目 biểu nghĩa (mắt), 夌 biểu âm (đọc lăng/lèng). Nghĩa: nhìn trừng trừng, hoặc nhìn ngây người. Dùng trong mô tả biểu cảm khuôn mặt. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lăng tranh 睖睜)", "Hạng Tần Suất (Jun Da)": "7397.0", "Tần Suất % (Jun Da)": "99.9983344015", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 夌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目夌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睖", "Unihan_Traditional (Chữ Phồn thể)": "睖", "Pinyin_Xie": "lèng", "Âm Hán Việt_Xie": "lăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường dùng làm động từ thể hiện hành động nhìn chằm chằm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磫', '{"9000": "7398.0", "Chữ Trung Quốc": "磫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 16 | nét | 石 | thạch | biểu nghĩa | đá | 宗 | tông | biểu âm | phần biểu âm | 磫 là chữ hình thanh: 石 (Thạch, biểu nghĩa: đá) + 宗 (Tông, biểu âm). Chỉ đá mài nhẵn hoặc lối đi bằng đá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tông\": 石 (đá) + 宗 — viên đá tông tổ, nhẵn mịn dùng mài dao. | Gương Hán-Việt | tông — đá mài nhẵn trong thư tịch kỹ thuật cổ | Mở khoá kiến thức | Biết 磫 giúp đọc mô tả công cụ và vật liệu xây dựng trong thư tịch kỹ thuật cổ.", "Tự nguyên_Xie": "Hình thanh tự: bộ 石 biểu nghĩa (đá), 宗 biểu âm (đọc tông/zōng). Nghĩa 1: đá mài nhẵn mịn. Nghĩa 2: lối đi lát đá. Chữ ít dùng trong thư tịch kiến trúc và nông cụ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Đinh", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 從", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石從", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "從", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磫", "Unihan_Traditional (Chữ Phồn thể)": "磫", "Pinyin_Xie": "zōng", "Âm Hán Việt_Xie": "tông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ chỉ các loại đá nhọn hoặc tính từ miêu tả sự gồ ghề. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禫', '{"9000": "7399.0", "Chữ Trung Quốc": "禫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 16 | nét | 禫 | đệm | tượng hình | lễ trừ tang phục | 禫 là chữ có bộ 示 liên quan đến tế lễ. Chỉ lễ trừ tang phục — nghi lễ kết thúc thời tang chế sau 27 tháng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đệm\": lễ đệm cuối của tang chế, cởi áo tang bước vào cuộc đời mới. | Gương Hán-Việt | đệm — lễ trừ tang trong Lễ Ký | Mở khoá kiến thức | Biết 禫 giúp đọc Lễ Ký và các tài liệu tang lễ trong điển chế Nho giáo.", "Tự nguyên_Xie": "Bộ 示 biểu nghĩa (lễ tế). Chỉ lễ đàm — nghi lễ cởi bỏ tang phục sau kỳ tang ba năm (thực tế 27 tháng), đánh dấu kết thúc thời kỳ chịu tang. Có trong Lễ Ký. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tế trừ phục", "Hạng Tần Suất (Jun Da)": "7399.0", "Tần Suất % (Jun Da)": "99.9983375022", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 覃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻覃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "覃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禫", "Unihan_Traditional (Chữ Phồn thể)": "禫", "Pinyin_Xie": "dàn", "Âm Hán Việt_Xie": "đạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường dùng làm danh từ chỉ nghi lễ cúng tế sau khi hết tang hai mươi bảy tháng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繨', '{"9000": "7400.0", "Chữ Trung Quốc": "繨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 18 | nét | 糸 | mịch | biểu nghĩa | chỉ, sợi | 它 | tha | biểu âm | phần biểu âm | 繨 là chữ hình thanh: 糸 (Mịch, biểu nghĩa: chỉ/sợi) + 它 (Tha, biểu âm). Chỉ loại dây thừng hoặc sợi dệt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\": 糸 (sợi chỉ) + 它 — cuộn sợi đà dai dẳng uốn lượn như rắn. | Gương Hán-Việt | đà — dây sợi trong thư tịch dệt vải cổ | Mở khoá kiến thức | Biết 繨 giúp đọc thuật ngữ nghề dệt trong thư tịch công nghệ cổ điển.", "Tự nguyên_Xie": "Hình thanh tự: bộ 糸 biểu nghĩa (chỉ, sợi dệt), 它 biểu âm (đọc đà/tuó). Chỉ loại dây thừng hoặc vải dệt. Chữ ít dùng, chưa có nguồn học thuật chi tiết; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nút dây, gút dây", "Hạng Tần Suất (Jun Da)": "7400.0", "Tần Suất % (Jun Da)": "99.9983390526", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 達", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹達", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "達", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "繨", "Unihan_Traditional (Chữ Phồn thể)": "繨", "Pinyin_Xie": "da", "Âm Hán Việt_Xie": "đáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ để chỉ các nút thắt hoặc mối buộc trên dây thừng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褱', '{"9000": "7401.0", "Chữ Trung Quốc": "褱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 16 | nét | 衣 | y | biểu nghĩa | áo, quần áo | 眔 | đạt | biểu âm | phần biểu âm | 褱 là chữ hình thanh: 衣 (Y, biểu nghĩa: áo/quần áo) + 眔 (Đạt, biểu âm). Nghĩa gốc là ''nhớ nhung'', sự buồn bã khi nhớ ai liên quan đến chiếc áo còn lại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoài\": 衣 (áo) + 眔 — ôm chiếc áo hoài niệm nhớ người thân đã xa. | Gương Hán-Việt | hoài — trong 懷念 (hoài niệm), biến thể của 懷 | Mở khoá kiến thức | Biết 褱 giúp đọc văn bản cổ dùng biến thể của 懷 trong thơ và thư tịch cổ điển.", "Tự nguyên_Xie": "Hình thanh tự: bộ 衣 biểu nghĩa (quần áo), 眔 biểu âm. Nghĩa gốc: nhớ nhung (to miss). Nỗi buồn nhớ được truyền tải qua hình ảnh áo — như ôm chiếc áo để nhớ người. Biến thể của 懷. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "885.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Y (145) Đạp (884)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Đạp (số 884 - giọt nước mắt) nằm giấu ở trong chữ Y (số 145 - cái áo/được chẻ làm hai phần). Hình những giọt nước mắt giấu ở trong lòng (áo). Giải thích sự chuyển ý: Đây là chữ Hội ý. Hoài là nhớ nhung, giấu kín ở trong lòng.", "Nghĩa Tiếng Việt_Xie": "nhớ nhung; ôm", "Hạng Tần Suất (Jun Da)": "7401.0", "Tần Suất % (Jun Da)": "99.9983421533", "GavinGrover_Once (Chiết tự trực tiếp)": "衣 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴衣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "褱", "Unihan_Traditional (Chữ Phồn thể)": "褱", "Pinyin_Xie": "huái", "Âm Hán Việt_Xie": "hoài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ thể hiện tâm trạng nhớ nhung hoặc ôm ấp hoài bão trong lòng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鏏', '{"9000": "7402.0", "Chữ Trung Quốc": "鏏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 19 | nét | 金 | kim | biểu nghĩa | kim loại | 衛 | vệ | biểu âm | phần biểu âm | 鏏 là chữ hình thanh: 金 (Kim, biểu nghĩa: kim loại) + 衛 (Vệ, biểu âm). Chỉ loại đỉnh (ding) cổ có chân và nắp, hoặc mũ đầu mút vũ khí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vị\": 金 (kim loại) + 衛 — chiếc đỉnh vị phòng vệ giữ hơi ấm thức ăn tế lễ. | Gương Hán-Việt | vị — đỉnh đồng cổ trong khảo cổ học | Mở khoá kiến thức | Biết 鏏 giúp đọc mô tả đồ đồng cổ trong tài liệu khảo cổ và bảo tàng.", "Tự nguyên_Xie": "Hình thanh tự: bộ 金 biểu nghĩa (kim loại), 衛 biểu âm (đọc vị/wèi). Chỉ một loại đỉnh đồng cổ đại có chân và nắp (a kind of ding with legs and lid). Chữ ít gặp ngoài khảo cổ học. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鏏", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 彗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金彗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鏏", "Unihan_Traditional (Chữ Phồn thể)": "鏏", "Pinyin_Xie": "wèi", "Âm Hán Việt_Xie": "vị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ cổ chỉ một loại đỉnh ba chân cỡ nhỏ dùng để đun nấu thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹓', '{"9000": "7403.0", "Chữ Trung Quốc": "鹓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 13 | nét | 鹓 | uyên | tượng hình | chim phượng loại | 鹓 là tên một loài chim huyền thoại giống phượng hoàng trong Trang Tử. Dùng trong tên ghép 鵷雛 (uyên sồ) — chim phượng non. Cấu trúc chi tiết chưa phân tích đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uyên\": chim uyên sồ cao quý trong Trang Tử, chỉ đậu trên ngô đồng, chỉ uống suối trong. | Gương Hán-Việt | uyên — trong 鹓雏 (uyên sồ, chim phượng non trong Trang Tử) | Mở khoá kiến thức | Biết 鹓 giúp đọc điển tích Trang Tử và nhận ra biểu tượng quân tử cao quý.", "Tự nguyên_Xie": "Tên loài chim huyền thoại (鵷雛 hoặc 鵷鶵) xuất hiện trong Trang Tử, thiên Tue Nam — loài chim cao quý như phượng hoàng, không đậu ngoài cây ngô đồng, không ăn gì ngoài trái luyện. Giản thể là 鹓. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con vịt đực", "Hạng Tần Suất (Jun Da)": "7403.0", "Tần Suất % (Jun Da)": "99.9983468044", "GavinGrover_Once (Chiết tự trực tiếp)": "宛 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰宛鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹓", "Unihan_Traditional (Chữ Phồn thể)": "鵷", "Pinyin_Xie": "yuān", "Âm Hán Việt_Xie": "uyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn học cổ để chỉ loài chim quý, tượng trưng cho người hiền tài. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繟', '{"9000": "7404.0", "Chữ Trung Quốc": "繟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 18 | nét | 糸 | mịch | biểu nghĩa | sợi, chỉ | 單 | đơn | biểu âm | phần biểu âm | 繟 là chữ hình thanh: 糸 (Mịch, biểu nghĩa: sợi) + 單 (Đơn, biểu âm). Chỉ trạng thái sợi lỏng lẻo, chùng xuống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiện\": 糸 (sợi) + 單 — sợi dây thiện hảo bỗng chùng xuống lỏng lẻo. | Gương Hán-Việt | thiện — dây/sợi chùng trong thư tịch cổ | Mở khoá kiến thức | Biết 繟 giúp đọc mô tả trạng thái vải/dây trong thư tịch kỹ thuật và thơ cổ.", "Tự nguyên_Xie": "Hình thanh tự: bộ 糸 biểu nghĩa (sợi, chỉ), 單 biểu âm (đọc thiện/chǎn). Nghĩa: lỏng lẻo, chùng (như dây không căng). Chữ ít dùng, chưa có nguồn học thuật chi tiết; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rộng rãi; thoáng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 單", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹單", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "單", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "繟", "Unihan_Traditional (Chữ Phồn thể)": "繟", "Pinyin_Xie": "chǎn", "Âm Hán Việt_Xie": "sán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ để miêu tả trạng thái rộng rãi của trang phục hoặc thái độ thong dong. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繺', '{"9000": "7405.0", "Chữ Trung Quốc": "繺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 19 | nét | 糸 | mịch | biểu nghĩa | sợi, vải | 賽 | tái | biểu âm | phần biểu âm | 繺 là chữ hình thanh: 糸 (Mịch, biểu nghĩa: sợi/vải) + 賽 (Tái, biểu âm). Chỉ loại vải hoặc sợi đặc biệt trong dệt vải cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sải\": 糸 (vải) + 賽 — tay sải dài dệt tấm vải mỏng nhẹ. | Gương Hán-Việt | sải — loại vải mỏng trong thư tịch dệt cổ | Mở khoá kiến thức | Biết 繺 giúp đọc thuật ngữ nghề dệt trong thư tịch kỹ thuật cổ.", "Tự nguyên_Xie": "Hình thanh tự: bộ 糸 biểu nghĩa (sợi, vải dệt), 賽 biểu âm (đọc sải/sǎi). Chỉ loại vải mỏng nhẹ hoặc sợi đặc biệt. Chữ ít dùng, chủ yếu trong thư tịch dệt vải cổ điển. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Yao", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 煞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹煞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "煞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "繺", "Unihan_Traditional (Chữ Phồn thể)": "繺", "Pinyin_Xie": "shǎi", "Âm Hán Việt_Xie": "sải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong văn cổ để miêu tả vẻ đẹp rực rỡ, nhiều màu sắc đan xen. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沲', '{"9000": "7406.0", "Chữ Trung Quốc": "沲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 氵 | thuỷ | biểu nghĩa | nước, sông | 它 | tha | biểu âm | phần biểu âm | 沲 là chữ hình thanh: 氵 (Thuỷ, biểu nghĩa: nước/sông) + 它 (Tha, biểu âm). Tên sông hoặc chỉ dòng nước chảy chậm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\": 氵 (sông) + 它 — dòng sông đà chảy chậm uốn lượn như con rắn. | Gương Hán-Việt | đà — tên sông/dòng nước trong địa danh cổ | Mở khoá kiến thức | Biết 沲 giúp đọc địa danh sông ngòi và thư tịch địa lý cổ.", "Tự nguyên_Xie": "Hình thanh tự: bộ 氵 biểu nghĩa (nước, sông), 它 biểu âm (đọc đà/duò). Tên sông Đà hoặc chỉ dòng nước. Chữ ít dùng, chủ yếu trong địa danh. Chưa có nguồn học thuật chi tiết; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông nhánh", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 㐌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵㐌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沲", "Unihan_Traditional (Chữ Phồn thể)": "沲", "Pinyin_Xie": "tuó", "Âm Hán Việt_Xie": "đà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ trong địa danh hoặc động từ miêu tả dòng nước chảy quanh co. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('餦', '{"9000": "7407.0", "Chữ Trung Quốc": "餦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 16 | nét | 餦 | trương | tượng hình | đường mạch nha khô, chữ hiếm | 餦 là chữ hiếm, không phân tích được thành phần rõ ràng qua CHISE; cấu trúc gốc chưa được xác định trong dữ liệu hiện có. Chữ thuộc bộ 食 (thực).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trương\": bộ 食 (thực – ăn) gợi đây là loại thực phẩm ngọt ngào, mạch nha dẻo dính được \"trương\" ra khi kéo. | Gương Hán-Việt | trương — ít dùng trong tiếng Việt hiện đại; xuất hiện trong từ cổ chỉ loại kẹo. | Mở khoá kiến thức | Biết 餦 giúp nhận ra từ 餦餭 trong thơ Sở từ cổ điển Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 餦 chỉ xuất hiện trong tổ hợp 餦餭 (zhānghuáng), chỉ một loại kẹo mạch nha ngọt trong thơ Sở từ cổ đại: 《粔籹蜜餌，有餦餭兮》. Chưa có nguồn glyph-origin chi tiết. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đường mạch nha khô; bánh rán (một loại bánh làm bằng bột mì)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 長", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠長", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "飠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "長", "Unihan_Simplified (Chữ Giản thể)": "餦", "Unihan_Traditional (Chữ Phồn thể)": "餦", "Pinyin_Xie": "zhāng", "Âm Hán Việt_Xie": "trương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ các loại bánh bột mì hoặc đồ ăn ngọt dạng khô thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踺', '{"9000": "7408.0", "Chữ Trung Quốc": "踺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 15 | nét | 踺 | tiện | tượng hình | nhảy qua, bước nhảy lớn | 踺 là chữ hiếm thuộc bộ 足 (túc – chân). Không có dữ liệu cấu trúc CHISE chi tiết. Dựa vào bộ thủ 足 (chân, bước đi) có thể hiểu chữ liên quan đến cử động chân. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiện\": bộ 足 (túc – chân) gợi động tác chân mạnh; \"tiện\" một bước nhảy qua vật cản. | Gương Hán-Việt | tiện — ít xuất hiện trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 踺 giúp nhận ra các chữ hiếm bộ 足 liên quan đến cử động chân đặc biệt.", "Tự nguyên_Xie": "Không có glyph-origin từ Wiktionary cho 踺. Chữ thuộc bộ 足 (túc – chân). Từ cấu trúc bộ thủ, có thể suy đây là chữ chỉ động tác chân (nhảy qua, bước mạnh). Chưa có nguồn học thuật, confidence thấp. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "động tác lật người", "Hạng Tần Suất (Jun Da)": "7408.0", "Tần Suất % (Jun Da)": "99.9983561065", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 建", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊建", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "建", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踺", "Unihan_Traditional (Chữ Phồn thể)": "踺", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "kiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ trong thuật ngữ thể dục dụng cụ hoặc động từ chỉ động tác nhảy lộn vòng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祦', '{"9000": "7409.0", "Chữ Trung Quốc": "祦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 11 | nét | 祦 | ngô | tượng hình | chữ cổ bộ 示, nghĩa chưa rõ | 祦 thuộc bộ 示 (kỳ/thị – thần linh, lễ nghi). Không có dữ liệu cấu trúc CHISE. Wiktionary ghi rfdef (chưa có định nghĩa rõ). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngô\": bộ 示 (thị – thần linh) gợi một nghi lễ tế tự cổ xưa mang âm \"ngô\" chưa được giải mã. | Gương Hán-Việt | ngô — ít dùng trong tiếng Việt. | Mở khoá kiến thức | Biết 祦 giúp nhận diện nhóm chữ hiếm bộ 示 liên quan đến lễ nghi cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi 祦 (âm wú) thuộc bộ 示, không có định nghĩa rõ ràng (rfdef). Không có glyph-origin. Đây là chữ hiếm chưa được giải nghĩa đầy đủ trong học thuật hiện đại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sung sướng; được sử dụng trong các tên lịch sử", "Hạng Tần Suất (Jun Da)": "7409.0", "Tần Suất % (Jun Da)": "99.9983576568", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 吴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻吴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祦", "Unihan_Traditional (Chữ Phồn thể)": "禑", "Pinyin_Xie": "wú", "Âm Hán Việt_Xie": "vô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chủ yếu dùng làm danh từ chỉ phúc lành hoặc tính từ trong tên riêng cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篲', '{"9000": "7410.0", "Chữ Trung Quốc": "篲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 17 | nét | 篲 | tuệ | tượng hình | chổi tre; quét dọn | 篲 thuộc bộ 竹 (trúc – tre). Không có dữ liệu cấu trúc CHISE chi tiết. Wiktionary xác nhận đây là dạng văn ngữ của 彗 (tuệ – chổi). Chữ gợi hình chổi làm từ cây tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuệ\": bộ 竹 (trúc – tre) + âm tuệ → cây chổi tre dùng để \"tuệ\" (quét) sạch đường đi. | Gương Hán-Việt | tuệ — xuất hiện trong 彗星 (tuệ tinh – sao chổi), cùng gốc hình ảnh chổi quét. | Mở khoá kiến thức | Biết 篲 giúp hiểu gốc hình ảnh của 彗星 (sao chổi) — ngôi sao có đuôi như chổi quét qua bầu trời.", "Tự nguyên_Xie": "Theo Wiktionary, 篲 là dạng cổ văn ngữ của 彗, nghĩa là chổi (broomstick) hoặc động từ quét dọn. Có các từ ghép như 篲竹 (cây trúc làm chổi), 擁篲清道 (cầm chổi dọn đường, nghi lễ nghênh đón). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sao chổi; cái chổi; quét", "Hạng Tần Suất (Jun Da)": "7410.0", "Tần Suất % (Jun Da)": "99.9983592072", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 彗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮彗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篲", "Unihan_Traditional (Chữ Phồn thể)": "篲", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "tuệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ cái chổi hoặc động từ chỉ hành động quét dọn trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絙', '{"9000": "7411.0", "Chữ Trung Quốc": "絙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 絙 | hoàn | tượng hình | dây thừng dày; thừng lớn | 絙 thuộc bộ 糸 (mịch – tơ, sợi). Không có dữ liệu CHISE chi tiết. Wiktionary xác nhận là dạng thay thế của 縆 (dây thừng dày). Chữ gợi hình sợi tơ được bện thành dây lớn, chắc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàn\": bộ 糸 (mịch – tơ sợi) gợi nhiều sợi bện \"hoàn\" lại thành dây thừng chắc, vòng quanh. | Gương Hán-Việt | hoàn — ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 絙 giúp nhận diện nhóm chữ bộ 糸 chỉ các loại dây, thừng trong văn cổ.", "Tự nguyên_Xie": "Theo Wiktionary, 絙 là dạng thay thế (alt form) của 縆, nghĩa là dây thừng굵, dây lớn bện từ nhiều sợi. Thuộc bộ 糸 (tơ, sợi). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật rõ ràng về glyph-origin. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "絵", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 亘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹亘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "絙", "Unihan_Traditional (Chữ Phồn thể)": "絙", "Pinyin_Xie": "huán", "Âm Hán Việt_Xie": "hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ sợi dây thừng to hoặc động từ chỉ hành động căng dây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纄', '{"9000": "7412.0", "Chữ Trung Quốc": "纄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 19 | nét | 纄 | bằng | tượng hình | chữ hiếm bộ 糸, nghĩa chưa rõ | 纄 thuộc bộ 糸 (mịch – tơ, sợi). Không có dữ liệu CHISE hay Wiktionary glyph-origin. Đây là chữ cực hiếm chưa được giải nghĩa đầy đủ. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bằng\": bộ 糸 (mịch – tơ sợi) gợi những sợi tơ \"bằng\" nhau, song song, chưa rõ nghĩa cụ thể. | Gương Hán-Việt | bằng — ít dùng trong tiếng Việt. | Mở khoá kiến thức | Biết 纄 giúp nhận diện nhóm chữ hiếm bộ 糸 trong văn bản cổ đại.", "Tự nguyên_Xie": "Không có glyph-origin từ Wiktionary cho 纄. Chữ thuộc bộ 糸 (tơ, sợi), âm péng. Chưa có nguồn học thuật, confidence thấp. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "焄", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "纄", "Unihan_Traditional (Chữ Phồn thể)": "纄", "Pinyin_Xie": "péng", "Âm Hán Việt_Xie": "bằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ dây buộc hoặc động từ chỉ hành động quấn, trói. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脝', '{"9000": "7413.0", "Chữ Trung Quốc": "脝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 脝 | hanh | tượng hình | bụng phình trướng; sưng phồng | 脝 thuộc bộ 肉 (nhục – thịt, thân xác). Không có dữ liệu CHISE chi tiết. Wiktionary xác nhận chỉ dùng trong 膨脝 (pénghēng – phồng to, trướng bụng). Chữ gợi hình thân thể phồng to.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hanh\": bộ 肉 (nhục – thịt) gợi cái bụng \"hanh\" ra, phình trướng như bong bóng. | Gương Hán-Việt | hanh — ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 脝 giúp hiểu từ 膨脝 (phồng trướng) trong y văn cổ Trung Hoa.", "Tự nguyên_Xie": "Theo Wiktionary, 脝 (âm hēng) chỉ xuất hiện trong tổ hợp 膨脝, nghĩa là phình to, trướng lên. Thuộc bộ 肉 (nhục). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn glyph-origin chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bành hanh 膨脝)", "Hạng Tần Suất (Jun Da)": "7413.0", "Tần Suất % (Jun Da)": "99.9983654086", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 亨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月亨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脝", "Unihan_Traditional (Chữ Phồn thể)": "脝", "Pinyin_Xie": "hēng", "Âm Hán Việt_Xie": "hanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường kết hợp thành từ ghép để miêu tả trạng thái bụng phình to. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茊', '{"9000": "7414.0", "Chữ Trung Quốc": "茊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 茊 | tư | tượng hình | cây cỏ cổ hiếm, bộ 艹 | 茊 thuộc bộ 艹 (thảo – cỏ, thực vật). Không có dữ liệu CHISE hay Wiktionary glyph-origin. Đây là chữ hiếm chưa được giải nghĩa đầy đủ. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": bộ 艹 (thảo – cỏ) gợi một loài thực vật mang âm \"tư\", chưa xác định được loài cụ thể. | Gương Hán-Việt | tư — ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 茊 giúp nhận diện nhóm chữ hiếm bộ 艹 trong thực vật học cổ đại.", "Tự nguyên_Xie": "Không có glyph-origin từ Wiktionary cho 茊. Chữ thuộc bộ 艹 (thảo – cỏ), âm zī. Chưa có nguồn học thuật, confidence thấp. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "茊", "Hạng Tần Suất (Jun Da)": "7414.0", "Tần Suất % (Jun Da)": "99.998366959", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 丘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹丘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茊", "Unihan_Traditional (Chữ Phồn thể)": "茊", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại cỏ tranh trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菫', '{"9000": "7415.0", "Chữ Trung Quốc": "菫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菫 | ngẩn | tượng hình | cây hoa tím (violet/aconite); đất sét vàng | 菫 thuộc bộ 艹 (thảo – cỏ, thực vật). Không có dữ liệu CHISE chi tiết hay Wiktionary glyph-origin. Chữ chỉ cây hoa tím (Viola) hoặc cây ô đầu (aconite) trong thực vật học cổ. Slug đã cho: ngan-菫.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngẩn\": bộ 艹 (thảo – cỏ) gợi bông hoa tím nhỏ \"ngẩn ngơ\" mọc dại — hoa violet trong thảo nguyên. | Gương Hán-Việt | ngẩn — ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 菫 giúp nhận ra từ điển thực vật cổ Trung Hoa liên quan loài hoa tím (Viola).", "Tự nguyên_Xie": "Không có glyph-origin chi tiết từ Wiktionary cho 菫. Chữ thuộc bộ 艹 (thảo), âm jǐn. Trong cổ ngữ chỉ loài hoa tím nhỏ (Viola) hoặc cây ô đầu có độc. Slug ngan-菫 xác nhận đọc HV là \"ngẩn\". Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "râu cần cạn", "Hạng Tần Suất (Jun Da)": "7415.0", "Tần Suất % (Jun Da)": "99.9983685093", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "菫", "Unihan_Traditional (Chữ Phồn thể)": "菫", "Pinyin_Xie": "jǐn", "Âm Hán Việt_Xie": "cận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại rau hoặc hoa thân thảo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓞', '{"9000": "7416.0", "Chữ Trung Quốc": "蓞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 蓞 | đạm | tượng hình | cây cỏ cổ hiếm, bộ 艹 | 蓞 thuộc bộ 艹 (thảo – cỏ, thực vật). Không có dữ liệu CHISE hay Wiktionary glyph-origin. Đây là chữ hiếm chưa được giải nghĩa đầy đủ. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạm\": bộ 艹 (thảo – cỏ) gợi loài thực vật \"đạm\" nhạt, ít được biết đến. | Gương Hán-Việt | đạm — ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 蓞 giúp nhận diện nhóm chữ hiếm bộ 艹 trong thực vật học cổ đại.", "Tự nguyên_Xie": "Không có glyph-origin từ Wiktionary cho 蓞. Chữ thuộc bộ 艹 (thảo – cỏ), âm dàn. Chưa có nguồn học thuật, confidence thấp. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nụ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 舀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹舀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓞", "Unihan_Traditional (Chữ Phồn thể)": "蓞", "Pinyin_Xie": "dàn", "Âm Hán Việt_Xie": "đạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn thơ cổ để tả vẻ đẹp của nụ hoa sen. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酦', '{"9000": "7417.0", "Chữ Trung Quốc": "酦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 12 | nét | 酦 | phát | tượng hình | ủ men, lên men lần hai | 酦 thuộc bộ 酉 (dậu – rượu, men rượu). Không có dữ liệu CHISE chi tiết. Wiktionary xác nhận 酦 (dạng giản của 醱) nghĩa là ủ men lần hai, hoặc dùng trong 醱酵 (lên men). Chữ gợi hình quá trình lên men trong chum rượu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phát\": bộ 酉 (dậu – chum rượu) + âm phát → men rượu \"phát\" lên, sôi trào trong chum lên men. | Gương Hán-Việt | phát — liên kết với 發酵 (phát giáo – lên men), cùng âm HV. | Mở khoá kiến thức | Biết 酦 giúp hiểu 醱酵 (lên men) trong hoá học thực phẩm và y học cổ truyền.", "Tự nguyên_Xie": "Theo Wiktionary (qua dạng phồn thể 醱), âm pō/fā. Nghĩa 1: ủ rượu lần hai. Nghĩa 2 (trong 醱酵): lên men, tương đương 發酵. Thuộc bộ 酉 (dậu – chum rượu). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rượu nấu lại", "Hạng Tần Suất (Jun Da)": "7417.0", "Tần Suất % (Jun Da)": "99.99837161", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 发", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉发", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "发", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酦", "Unihan_Traditional (Chữ Phồn thể)": "醱", "Pinyin_Xie": "fā", "Âm Hán Việt_Xie": "phát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ loại rượu cất lại hoặc động từ chỉ quá trình lên men rượu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醾', '{"9000": "7418.0", "Chữ Trung Quốc": "醾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 24 | nét | 醾 | mi | tượng hình | rượu ngọt nồng; mùi thơm ngây ngất | 醾 thuộc bộ 酉 (dậu – rượu, men rượu). Không có dữ liệu CHISE hay Wiktionary glyph-origin. Đây là chữ hiếm chưa được giải nghĩa đầy đủ. Chữ gợi hình loại rượu đặc biệt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mi\": bộ 酉 (dậu – rượu) gợi loại rượu \"mi\" mê, hương thơm ngây ngất không dứt được. | Gương Hán-Việt | mi — ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 醾 giúp nhận diện nhóm chữ hiếm bộ 酉 chỉ các loại rượu đặc biệt trong cổ văn.", "Tự nguyên_Xie": "Không có glyph-origin từ Wiktionary cho 醾. Chữ thuộc bộ 酉 (dậu – rượu), âm mí. Có thể liên quan đến loại rượu ngọt hoặc mùi hương ngây ngất. Chưa có nguồn học thuật, confidence thấp. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ủ rượu lại", "Hạng Tần Suất (Jun Da)": "7418.0", "Tần Suất % (Jun Da)": "99.9983731604", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 糜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉糜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "糜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醾", "Unihan_Traditional (Chữ Phồn thể)": "醾", "Pinyin_Xie": "mí", "Âm Hán Việt_Xie": "mi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ loại rượu ngon được ủ nhiều lần trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锳', '{"9000": "7419.0", "Chữ Trung Quốc": "锳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 锳 | anh | tượng hình | chữ hiếm bộ 金, nghĩa chưa rõ | 锳 thuộc bộ 钅/金 (kim – kim loại). Không có dữ liệu CHISE hay Wiktionary glyph-origin. Đây là chữ hiếm chưa được giải nghĩa đầy đủ. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"anh\": bộ 钅 (kim – kim loại) gợi một loại kim khí sáng bóng mang âm \"anh\", chưa rõ loại cụ thể. | Gương Hán-Việt | anh — ít dùng trong tiếng Việt hiện đại với nghĩa kim loại. | Mở khoá kiến thức | Biết 锳 giúp nhận diện nhóm chữ hiếm bộ 金 chỉ các loại kim loại trong cổ văn.", "Tự nguyên_Xie": "Không có glyph-origin từ Wiktionary cho 锳. Chữ thuộc bộ 钅 (kim – kim loại), âm yīng. Chưa có nguồn học thuật, confidence thấp. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng chuông", "Hạng Tần Suất (Jun Da)": "7419.0", "Tần Suất % (Jun Da)": "99.9983747108", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 英", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅英", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "英", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锳", "Unihan_Traditional (Chữ Phồn thể)": "鍈", "Pinyin_Xie": "yīng", "Âm Hán Việt_Xie": "anh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ trong văn học cổ hoặc dùng trong tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钶', '{"9000": "7420.0", "Chữ Trung Quốc": "钶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 金 | kim | biểu nghĩa | kim loại | 可 | khả | biểu âm | có thể | 钶 = 金 (Kim, biểu nghĩa: kim loại) + 可 (Khả, biểu âm). Chữ hình thanh. Kim loại (金) với âm từ 可 → tên gọi nguyên tố Niobium (Nb) trong hoá học hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kha\": kim loại (金) + âm kha (可) → nguyên tố \"kha\" (Niobium) trong bảng tuần hoàn, kim loại chịu nhiệt dùng trong công nghiệp. | Gương Hán-Việt | kha — ít dùng trong tiếng Việt; xuất hiện trong hoá học: niobium. | Mở khoá kiến thức | Biết 钶 giúp đọc được tên các nguyên tố hoá học trong văn bản khoa học tiếng Trung.", "Tự nguyên_Xie": "Theo Wiktionary (dạng phồn thể 鈳), 钶 là chữ hình thanh gồm 金 (semantic: kim loại) và 可 (phonetic). Dùng để phiên âm nguyên tố Niobium (Nb, nguyên tử số 41) trong bảng tuần hoàn tiếng Trung. Chữ tạo hiện đại phục vụ hoá học. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rìu nhỏ; columbium", "Hạng Tần Suất (Jun Da)": "7420.0", "Tần Suất % (Jun Da)": "99.9983762611", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 可", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅可", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "可", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钶", "Unihan_Traditional (Chữ Phồn thể)": "鈳", "Pinyin_Xie": "ē", "Âm Hán Việt_Xie": "a", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại rìu nhỏ thời cổ hoặc nguyên tố hóa học niobi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲼', '{"9000": "7421.0", "Chữ Trung Quốc": "鲼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 鲼 | phần | tượng hình | cá đuối (stingray/manta ray) | 鲼 là dạng giản thể của 鱝 (cá đuối), thuộc bộ 鱼 (ngư – cá). Wiktionary xác nhận: giản hoá từ 魚→鱼 và 賁→贲. Chữ chỉ loài cá đuối lớn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phần\": bộ 鱼 (ngư – cá) gợi loài cá \"phần\" khác biệt — cá đuối dẹt phẳng bơi như bay dưới nước. | Gương Hán-Việt | phần — ít dùng trong tiếng Việt với nghĩa cá đuối. | Mở khoá kiến thức | Biết 鲼 giúp đọc tên các loài cá biển trong văn bản sinh học tiếng Trung.", "Tự nguyên_Xie": "Theo Wiktionary, 鲼 là dạng giản thể của 鱝 (giản: 魚→鱼, 賁→贲). Chỉ loài cá đuối (stingray, manta ray). Thuộc bộ 鱼 (ngư). Chữ thuần giản thể, không có dạng giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá đuôi ó", "Hạng Tần Suất (Jun Da)": "7421.0", "Tần Suất % (Jun Da)": "99.9983778115", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 贲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼贲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲼", "Unihan_Traditional (Chữ Phồn thể)": "鱝", "Pinyin_Xie": "fèn", "Âm Hán Việt_Xie": "phẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loài cá đuối trong sinh học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齄', '{"9000": "7422.0", "Chữ Trung Quốc": "齄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼻 | Số nét | 23 | nét | 齄 | tra | tượng hình | mụn đỏ trên mũi; trứng cá đỏ | 齄 thuộc bộ 鼻 (tị – mũi). Không có dữ liệu CHISE hay Wiktionary glyph-origin. Đây là chữ hiếm chỉ mụn đỏ, trứng cá xuất hiện trên mũi. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tra\": bộ 鼻 (tị – mũi) gợi những nốt \"tra\" đỏ nổi lên trên mũi — trứng cá, mụn rosacea trên mặt. | Gương Hán-Việt | tra — ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 齄 giúp đọc mô tả triệu chứng da liễu trong y văn cổ Trung Hoa.", "Tự nguyên_Xie": "Không có glyph-origin chi tiết từ Wiktionary cho 齄. Chữ thuộc bộ 鼻 (tị – mũi), âm zhā. Chỉ hiện tượng mụn đỏ, trứng cá trên vùng mũi (rosacea). Chưa có nguồn học thuật, confidence thấp. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鄄", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鼻 + 查", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鼻查", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "查", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼻", "Unihan_Simplified (Chữ Giản thể)": "齄", "Unihan_Traditional (Chữ Phồn thể)": "齄", "Pinyin_Xie": "zhā", "Âm Hán Việt_Xie": "tra", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ chứng mũi đỏ hoặc tính từ miêu tả mũi bị đỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鷧', '{"9000": "7423.0", "Chữ Trung Quốc": "鷧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 23 | nét | 鷧 | ý | tượng hình | loài chim (tên cổ, chưa xác định rõ) | 鷧 thuộc bộ 鳥 (điểu – chim). Không có dữ liệu CHISE chi tiết. Wiktionary ghi rfdef (chưa có định nghĩa rõ). Đây là tên chim cổ chưa được đồng nhất với loài hiện đại. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ý\": bộ 鳥 (điểu – chim) gợi một loài chim mang âm \"ý\" — cánh chim bay theo \"ý\" muốn, tên cổ chưa rõ loài. | Gương Hán-Việt | ý — ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 鷧 giúp nhận diện nhóm chữ hiếm bộ 鳥 trong điểu học cổ đại Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi 鷧 (âm yì) thuộc bộ 鳥, không có định nghĩa rõ ràng (rfdef). Không có glyph-origin. Đây là tên chim cổ hiếm chưa được giải nghĩa đầy đủ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "駧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "壹 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰壹鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "壹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鷧", "Unihan_Traditional (Chữ Phồn thể)": "鷧", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loài chim cốc chuyên bắt cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祋', '{"9000": "7425.0", "Chữ Trung Quốc": "祋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 8 | nét | 祋 | đối | tượng hình | giáo tre; cột treo da dê | 祋 thuộc bộ 示 (kỳ – thần linh, lễ nghi). Không có dữ liệu CHISE chi tiết. Wiktionary xác nhận hai nghĩa: đồng nghĩa 殳 (vũ khí tre), hoặc cột dùng để treo da dê. Cũng là họ người. Có dạng đại triện và tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đối\": bộ 示 (thị – thần linh) + nghĩa cây giáo (殳) → vũ khí dùng trong nghi lễ thờ thần, \"đối\" lập với kẻ thù. | Gương Hán-Việt | đối — ít dùng trong tiếng Việt với nghĩa vũ khí cổ. | Mở khoá kiến thức | Biết 祋 giúp đọc văn bản cổ về vũ khí và nghi lễ thời Chu tại Trung Quốc.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 祋 (âm duì) có hai nghĩa văn ngữ: 1) đồng nghĩa với 殳 (cây giáo/vũ khí làm bằng tre); 2) cột dùng để treo da cừu. Cũng là họ người. Thuộc bộ 示. Có hình đại triện và tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Đoái", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 殳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻殳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "殳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祋", "Unihan_Traditional (Chữ Phồn thể)": "祋", "Pinyin_Xie": "duì", "Âm Hán Việt_Xie": "_", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại vũ khí cổ tựa như cây gậy gỗ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箯', '{"9000": "7426.0", "Chữ Trung Quốc": "箯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 15 | nét | 箯 | biên | tượng hình | cáng tre; kiệu đan bằng tre | 箯 thuộc bộ 竹 (trúc – tre). Không có dữ liệu CHISE chi tiết hay Wiktionary glyph-origin chi tiết. Có hình tiểu triện. Chữ chỉ loại cáng/kiệu đan bằng tre dùng để khiêng người hoặc đồ vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biên\": bộ 竹 (trúc – tre) gợi những nan tre đan \"biên\" lại thành chiếc cáng khiêng người. | Gương Hán-Việt | biên — ít dùng trong tiếng Việt với nghĩa cáng tre. | Mở khoá kiến thức | Biết 箯 giúp đọc mô tả phương tiện di chuyển cổ đại trong văn bản lịch sử Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Không có glyph-origin chi tiết từ Wiktionary cho 箯. Có hình tiểu triện trong kho ảnh. Chữ thuộc bộ 竹 (trúc – tre), âm biān. Có thể chỉ loại cáng tre (palanquin) hoặc đồ đan bằng tre. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tiên dư 箯輿,箯舆)", "Hạng Tần Suất (Jun Da)": "7426.0", "Tần Suất % (Jun Da)": "99.9983871136", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 便", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮便", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "便", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箯", "Unihan_Traditional (Chữ Phồn thể)": "箯", "Pinyin_Xie": "biān", "Âm Hán Việt_Xie": "tiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp thành từ ghép để chỉ loại kiệu làm bằng tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粐', '{"9000": "7427.0", "Chữ Trung Quốc": "粐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 10 | nét | 粐 | hồ | tượng hình | chữ hiếm bộ 米, nghĩa chưa rõ | 粐 thuộc bộ 米 (mễ – gạo, ngũ cốc). Không có dữ liệu CHISE hay Wiktionary glyph-origin. Đây là chữ hiếm chưa được giải nghĩa đầy đủ. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồ\": bộ 米 (mễ – gạo) gợi loại bột gạo \"hồ\" ra thành cháo đặc, nhưng nghĩa cụ thể chưa rõ. | Gương Hán-Việt | hồ — ít dùng trong tiếng Việt với nghĩa gạo cụ thể. | Mở khoá kiến thức | Biết 粐 giúp nhận diện nhóm chữ hiếm bộ 米 trong thực phẩm học cổ đại.", "Tự nguyên_Xie": "Không có glyph-origin từ Wiktionary cho 粐. Chữ thuộc bộ 米 (mễ – gạo), âm hú. Chưa có nguồn học thuật, confidence thấp. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tề", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 户", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米户", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "户", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粐", "Unihan_Traditional (Chữ Phồn thể)": "粐", "Pinyin_Xie": "hu", "Âm Hán Việt_Xie": "hồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ món cháo hoặc thức ăn dạng bột loãng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粦', '{"9000": "7428.0", "Chữ Trung Quốc": "粦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 12 | nét | 炎 | viêm | lửa, ngọn lửa | 舛 | suyễn | hai bàn chân | 粦 nguyên là thành phần âm của 憐 (lân – thương xót). Trong tiểu triện, chữ bị phân tích nhầm thành hội ý 炎 (lửa) + 舛 (chân), nhưng nghiên cứu hiện đại (Trần Tư Bằng 2019) chứng minh đây là sai. Phần trên chính quy tiến hóa thành 米 trong khải thư. Chữ thực sự là phonetic component không mang nghĩa hội ý trực tiếp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lân\": hình ảnh ma trơi — ánh sáng \"lân\" tinh xanh lè nhảy múa trên đồng ruộng đêm khuya. Bộ gốc liên quan lửa và chân không phải nghĩa thật. | Gương Hán-Việt | lân — dùng trong: 燐 (lân – phốt pho, ma trơi), 憐 (lân – thương xót). | Mở khoá kiến thức | Biết 粦 mở khoá: 燐 (lân tinh – ma trơi/phosphorus), 磷 (lân – phốt pho hoá học), 憐憫 (lân mẫn – từ bi thương xót).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Theo Wiktionary, 粦 lần đầu xuất hiện ở dạng thành phần âm của 憐 trong thạch văn. Trong tiểu triện, 舛 tách khỏi 大 với các chấm, rồi bị hiểu thành 炎. Thuyết Văn giải thích nhầm là hội ý 炎+舛. Nghiên cứu đương đại chứng minh đây không phải hội ý. Phần trên tiếp tục biến đổi thành 米 trong khải thư. Nghĩa gốc: ma trơi (will o'' the wisp). Có giáp cốt văn và kim văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "943.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mễ (453) Suyễn (942)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mễ (số 453 - hạt gạo) ở trên chữ Suyễn (số 942 - trái ngược). Kẻ sống ăn lúa gạo, trái ngược với kẻ sống chính là cái chết (là ma trơi). Giải thích sự chuyển ý: Đây là chữ Hội ý. Lân là thứ lửa ma trơi phát ra vào buổi tối (lân tinh).", "Nghĩa Tiếng Việt_Xie": "lân; như \"lân la\" (gdhn) lấn; như \"lấn lướt\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 舛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱米舛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粦", "Unihan_Traditional (Chữ Phồn thể)": "粦", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ ánh sáng lập lòe của ma trơi ở nghĩa cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粭', '{"9000": "7429.0", "Chữ Trung Quốc": "粭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 12 | nét | 粭 | hạp | tượng hình | chữ hiếm bộ 米, nghĩa chưa rõ | 粭 thuộc bộ 米 (mễ – gạo, ngũ cốc). Không có dữ liệu CHISE hay Wiktionary glyph-origin. Đây là chữ hiếm chưa được giải nghĩa đầy đủ. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạp\": bộ 米 (mễ – gạo) gợi loại lương thực \"hạp\" lại, nắm lại — nhưng nghĩa cụ thể chưa rõ. | Gương Hán-Việt | hạp — ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 粭 giúp nhận diện nhóm chữ hiếm bộ 米 trong thực phẩm học cổ đại.", "Tự nguyên_Xie": "Không có glyph-origin từ Wiktionary cho 粭. Chữ thuộc bộ 米 (mễ – gạo), âm hé/hè. Chưa có nguồn học thuật, confidence thấp. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bánh bao gạo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 合", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米合", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "合", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粭", "Unihan_Traditional (Chữ Phồn thể)": "粭", "Pinyin_Xie": "he", "Âm Hán Việt_Xie": "hạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại bánh làm từ bột gạo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('紃', '{"9000": "7430.0", "Chữ Trung Quốc": "紃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 9 | nét | 紃 | tuần | tượng hình | dải lụa; ruy băng tơ lụa | 紃 thuộc bộ 糸 (mịch – tơ, sợi). Không có dữ liệu CHISE chi tiết. Wiktionary xác nhận nghĩa: silk ribbon (dải lụa). Có hình tiểu triện. Chữ gợi hình dải tơ lụa mỏng manh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuần\": bộ 糸 (mịch – tơ sợi) gợi dải lụa \"tuần\" tự cuốn quanh — ruy băng tơ mềm mại quấn quanh trang phục. | Gương Hán-Việt | tuần — ít dùng trong tiếng Việt với nghĩa dải lụa. | Mở khoá kiến thức | Biết 紃 giúp đọc mô tả trang phục và trang sức trong văn bản lịch sử Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 紃 (âm xún) nghĩa là dải lụa, ruy băng tơ. Thuộc bộ 糸 (tơ, sợi). Có hình tiểu triện (hanziyuan). Chữ chỉ loại ruy băng tơ lụa dùng trong trang phục và lễ nghi. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây tơ nhỏ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 川", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹川", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "川", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "𬘓", "Unihan_Traditional (Chữ Phồn thể)": "紃", "Pinyin_Xie": "xún", "Âm Hán Việt_Xie": "xuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường dùng làm danh từ chỉ sợi dây tơ tròn hoặc làm động từ với nghĩa tuân theo trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脰', '{"9000": "7431.0", "Chữ Trung Quốc": "脰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | ⺼ | nhục | biểu nghĩa | thịt, thân thể | 豆 | đậu | biểu âm | hạt đậu | 脰 = ⺼/肉 (Nhục, biểu nghĩa: thịt/thân xác) + 豆 (Đậu, biểu âm). Chữ hình thanh. Phần thịt (⺼) của cổ người, âm từ 豆 (đậu) → cổ họng, cổ người.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đậu\": phần thịt (⺼) mang âm đậu (豆) → cổ họng, nơi hạt \"đậu\" phải đi qua khi nuốt xuống. | Gương Hán-Việt | đậu — ít dùng trong tiếng Việt với nghĩa cổ họng; 豆 (đậu) thường gặp hơn. | Mở khoá kiến thức | Biết 脰 giúp đọc mô tả giải phẫu cổ người trong y văn cổ Trung Hoa.", "Tự nguyên_Xie": "Theo Wiktionary, 脰 là chữ hình thanh gồm 肉 (semantic: thịt/thân xác, viết ⺼) và 豆 (phonetic). Nghĩa: cổ họng, cổ người. Thuộc bộ ⺼ (nhục). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phần cổ dưới cằm", "Hạng Tần Suất (Jun Da)": "7431.0", "Tần Suất % (Jun Da)": "99.9983948654", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 豆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月豆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脰", "Unihan_Traditional (Chữ Phồn thể)": "脰", "Pinyin_Xie": "dòu", "Âm Hán Việt_Xie": "đậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ để chỉ bộ phận cổ của người hoặc động vật trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芃', '{"9000": "7432.0", "Chữ Trung Quốc": "芃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 6 | nét | 艹 | tháo | biểu nghĩa | cỏ, thực vật | 凡 | phàm | biểu âm | tất cả, phàm | 芃 = 艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 凡 (Phàm, gợi âm). Chữ gợi hội ý: cỏ cây sinh trưởng mạnh mẽ, um tùm. Wiktionary mô tả: 艸 (grass) + 凡 – growth of plants.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bông\": bộ 艹 (thảo – cỏ) + phàm (凡) → cây cỏ \"bông\" mọc um tùm, phàm cây nào cũng mọc tốt tươi. | Gương Hán-Việt | bông — liên kết với hình ảnh cây cỏ tươi tốt, mùa xuân. | Mở khoá kiến thức | Biết 芃 giúp đọc thơ Kinh Thi mô tả cảnh vật mùa xuân cây cỏ phát triển.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 芃 gồm 艸 (cỏ) + 凡, chỉ sự sinh trưởng mạnh mẽ của cây cỏ. Có hình đại triện và tiểu triện. Âm péng, HV bông (theo slug bong-芃). Chữ miêu tả cây cỏ mọc um tùm, sung sức. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tốt tươi; đuôi dài thườn thượt", "Hạng Tần Suất (Jun Da)": "7432.0", "Tần Suất % (Jun Da)": "99.9983964157", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 凡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹凡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "凡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芃", "Unihan_Traditional (Chữ Phồn thể)": "芃", "Pinyin_Xie": "péng", "Âm Hán Việt_Xie": "bồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường dùng làm tính từ miêu tả trạng thái cỏ cây mọc xanh tốt, sum suê. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苽', '{"9000": "7433.0", "Chữ Trung Quốc": "苽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 艸 | thảo | biểu nghĩa | cỏ, thực vật | 瓜 | qua | biểu âm | dưa, bầu | 苽 = 艸/艹 (Thảo, biểu nghĩa: thực vật) + 瓜 (Qua, biểu âm: dưa). Chữ hình thanh. Thực vật (艹) với âm từ 瓜 (qua – dưa) → cây thủy thảo (wild rice plant, Zizania latifolia).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"qua\": thực vật (艹) âm giống dưa (瓜) → cây thủy thảo mọc dưới nước như dưa mọc trên ruộng. | Gương Hán-Việt | qua — liên kết với 瓜 (qua – dưa), cùng âm HV. | Mở khoá kiến thức | Biết 苽 giúp đọc mô tả thực vật thủy sinh trong văn bản thực vật học và ẩm thực cổ Trung Hoa.", "Tự nguyên_Xie": "Theo Wiktionary, 苽 là chữ hình thanh gồm 艸 (semantic: cỏ/thực vật) và 瓜 (phonetic: dưa). Chỉ cây lúa dại hoặc cây thủy thảo (Zizania latifolia). Thuộc bộ 艹. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rau cô, lúa cô; cây nấm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 瓜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹瓜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瓜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苽", "Unihan_Traditional (Chữ Phồn thể)": "苽", "Pinyin_Xie": "gū", "Âm Hán Việt_Xie": "cô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ một loại cây thủy sinh có củ ăn được hoặc một loại nấm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莿', '{"9000": "7434.0", "Chữ Trung Quốc": "莿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 莿 | thứ | tượng hình | cây có gai; gai nhọn | 莿 thuộc bộ 艹 (thảo – cỏ, thực vật). Wiktionary tham chiếu từ 刺 (thứ – gai nhọn). Có hình tiểu triện (hanziyuan). Chữ chỉ cây cỏ có gai, gai nhọn của thực vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thứ\": bộ 艹 (thảo – cỏ) gợi loài cây \"thứ\" nhọn — gai sắc của bụi cây, nhắc đến 刺 (thứ – gai). | Gương Hán-Việt | thứ — liên kết với 刺 (thứ – đâm, gai), cùng âm HV. | Mở khoá kiến thức | Biết 莿 giúp đọc tên cây cỏ gai trong thực vật học và thơ ca cổ đại.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 莿 tham chiếu Han etym của 刺 (gai nhọn). Nghĩa: cây có gai. Có từ ghép 莿桐 (cây thông gai). Có hình tiểu triện. Thuộc bộ 艹. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Urtica thunbergiana", "Hạng Tần Suất (Jun Da)": "7434.0", "Tần Suất % (Jun Da)": "99.9983995164", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 刺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹刺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莿", "Unihan_Traditional (Chữ Phồn thể)": "莿", "Pinyin_Xie": "cì", "Âm Hán Việt_Xie": "thích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ chỉ các loại cây có gai hoặc bản thân cái gai nhọn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菆', '{"9000": "7435.0", "Chữ Trung Quốc": "菆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菆 | trâu | tượng hình | bó tên cỏ; mũi tên làm bằng cỏ | 菆 thuộc bộ 艹 (thảo – cỏ, thực vật). Wiktionary chỉ ghi {{Han etym}} không có chi tiết. Đây là chữ hiếm, có thể liên quan đến bó tên (mũi tên làm từ cỏ khô). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trâu\": bộ 艹 (thảo – cỏ) gợi bó cỏ làm \"trâu\" tên — mũi tên thô làm từ thân cây. | Gương Hán-Việt | trâu — ít dùng trong tiếng Việt với nghĩa này. | Mở khoá kiến thức | Biết 菆 giúp nhận diện nhóm chữ hiếm bộ 艹 trong văn bản thực vật học và kỹ thuật cổ đại.", "Tự nguyên_Xie": "Không có glyph-origin chi tiết từ Wiktionary cho 菆 (chỉ có {{Han etym}} trống). Chữ thuộc bộ 艹 (thảo – cỏ), âm zōu. Có thể chỉ bó tên hoặc vật liệu thực vật dùng làm tên. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thân cây đay; mũi tên tốt; chiếc chiếu", "Hạng Tần Suất (Jun Da)": "7435.0", "Tần Suất % (Jun Da)": "99.9984010668", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 取", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹取", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "取", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菆", "Unihan_Traditional (Chữ Phồn thể)": "菆", "Pinyin_Xie": "zōu", "Âm Hán Việt_Xie": "tưu, thoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ trong cổ văn để chỉ loại mũi tên tốt làm bằng tre gỗ hoặc thân cây đay. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藗', '{"9000": "7436.0", "Chữ Trung Quốc": "藗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 17 | nét | 藗 | tốc | tượng hình | cây cỏ cổ hiếm, bộ 艹 | 藗 thuộc bộ 艹 (thảo – cỏ, thực vật). Wiktionary ghi rfdef (chưa có định nghĩa rõ). Đây là chữ hiếm chưa được giải nghĩa đầy đủ. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tốc\": bộ 艹 (thảo – cỏ) gợi loài cây mọc \"tốc\" nhanh, vươn lên bất ngờ — nhưng nghĩa cụ thể chưa rõ. | Gương Hán-Việt | tốc — ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 藗 giúp nhận diện nhóm chữ hiếm bộ 艹 chưa được giải nghĩa trong cổ văn.", "Tự nguyên_Xie": "Wiktionary ghi 藗 (âm sù) không có định nghĩa rõ (rfdef). Thuộc bộ 艹. Chưa có nguồn học thuật, confidence thấp. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "藗", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 遬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹遬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "遬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藗", "Unihan_Traditional (Chữ Phồn thể)": "藗", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "tốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ chỉ một loại cây thân thảo ít phổ biến trong tài liệu cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藧', '{"9000": "7437.0", "Chữ Trung Quốc": "藧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 藧 | hoán | tượng hình | cây cỏ cổ hiếm, bộ 艹 | 藧 thuộc bộ 艹 (thảo – cỏ, thực vật). Không có dữ liệu CHISE hay Wiktionary glyph-origin. Đây là chữ hiếm chưa được giải nghĩa đầy đủ. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoán\": bộ 艹 (thảo – cỏ) gợi loài thực vật \"hoán\" đổi màu sắc theo mùa — nhưng nghĩa cụ thể chưa rõ. | Gương Hán-Việt | hoán — ít dùng trong tiếng Việt hiện đại với nghĩa thực vật. | Mở khoá kiến thức | Biết 藧 giúp nhận diện nhóm chữ hiếm bộ 艹 trong cổ văn thực vật học.", "Tự nguyên_Xie": "Không có glyph-origin từ Wiktionary cho 藧. Chữ thuộc bộ 艹 (thảo – cỏ), âm huàn. Chưa có nguồn học thuật, confidence thấp. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "藧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 緩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹緩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "緩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藧", "Unihan_Traditional (Chữ Phồn thể)": "藧", "Pinyin_Xie": "huàn", "Âm Hán Việt_Xie": "hoán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ một loại cỏ thơm thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袵', '{"9000": "7438.0", "Chữ Trung Quốc": "袵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 11 | nét | 袵 | nhẫm | tượng hình | vạt áo; tà áo trước | 袵 thuộc bộ 衣 (y – quần áo). Không có dữ liệu CHISE hay Wiktionary glyph-origin chi tiết. Đây là chữ hiếm chỉ vạt áo trước, tà áo. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhẫm\": bộ 衣 (y – áo quần) gợi phần vạt \"nhẫm\" vào trong của chiếc áo — tà áo xếp chồng lên nhau. | Gương Hán-Việt | nhẫm — ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 袵 giúp đọc mô tả trang phục cổ điển trong văn bản lịch sử Trung Hoa.", "Tự nguyên_Xie": "Không có glyph-origin từ Wiktionary cho 袵. Chữ thuộc bộ 衣 (y – quần áo), âm rèn. Có thể chỉ vạt áo trước (lapel) hoặc phần tà áo. Chưa có nguồn học thuật chi tiết, confidence thấp. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vạt áo; cái chiếu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 任", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤任", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "任", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袵", "Unihan_Traditional (Chữ Phồn thể)": "袵", "Pinyin_Xie": "rèn", "Âm Hán Việt_Xie": "nhẫm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ chỉ vạt áo trước hoặc tấm chiếu nằm trong tiếng Trung cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裯', '{"9000": "7439.0", "Chữ Trung Quốc": "裯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 13 | nét | 裯 | trù | tượng hình | áo ngủ ngắn; chăn nhỏ | 裯 thuộc bộ 衣 (y – quần áo). Wiktionary chỉ ghi {{Han etym}} trống. Đây là chữ hiếm chỉ loại áo ngủ ngắn hoặc chăn nhỏ. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trù\": bộ 衣 (y – áo quần) gợi chiếc áo \"trù\" ngủ ngắn, ấm áp mặc khi nghỉ ngơi. | Gương Hán-Việt | trù — ít dùng trong tiếng Việt với nghĩa áo ngủ. | Mở khoá kiến thức | Biết 裯 giúp đọc mô tả trang phục ngủ và vải vóc trong văn bản lịch sử Trung Hoa.", "Tự nguyên_Xie": "Không có glyph-origin chi tiết từ Wiktionary cho 裯 (chỉ {{Han etym}} trống). Chữ thuộc bộ 衣 (y – áo), âm chóu. Có thể chỉ áo ngủ ngắn hoặc chăn nhỏ. Chưa có nguồn học thuật, confidence thấp. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chăn đơn; ra giường; mùng; màn trên giường", "Hạng Tần Suất (Jun Da)": "7439.0", "Tần Suất % (Jun Da)": "99.9984072682", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 周", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤周", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "周", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裯", "Unihan_Traditional (Chữ Phồn thể)": "裯", "Pinyin_Xie": "chóu", "Âm Hán Việt_Xie": "chù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ chỉ các loại chăn mỏng hoặc màn che giường thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褵', '{"9000": "7440.0", "Chữ Trung Quốc": "褵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 15 | nét | 褵 | li | tượng hình | dải lụa buộc áo; dây thắt lưng cô dâu | 褵 thuộc bộ 衣 (y – quần áo). Wiktionary xác nhận: dạng thay thế của 縭 (dây thắt lưng cô dâu), và dùng trong 褵褷 (lông vũ ướt, rũ xuống). Chữ liên quan trang phục lễ cưới.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"li\": bộ 衣 (y – áo) gợi dải \"li\" lụa buộc áo — nghi lễ mẹ buộc dải áo cho con gái trước khi về nhà chồng. | Gương Hán-Việt | li — liên kết với từ điển lễ nghi Trung Hoa cổ. | Mở khoá kiến thức | Biết 褵 giúp đọc mô tả nghi lễ hôn lễ và trang phục cô dâu trong cổ văn Trung Hoa.", "Tự nguyên_Xie": "Theo Wiktionary, 褵 (âm lí) là dạng thay thế của 縭. Nghĩa 1: dải lụa buộc áo, dây thắt lưng cô dâu (kết hôn lễ nghi). Nghĩa 2: trong 褵褷 (mô tả lông vũ ướt rũ xuống). Có từ ghép: 施衿結褵 (nghi lễ buộc dây áo cho con gái lấy chồng). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây lưng, khăn giắt; cái khăn tân nhân (khăn đỏ phủ kín mặt khi con gái về nhà chồng); buộc; lưới đánh cá", "Hạng Tần Suất (Jun Da)": "7440.0", "Tần Suất % (Jun Da)": "99.9984088186", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 离", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤离", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "离", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褵", "Unihan_Traditional (Chữ Phồn thể)": "褵", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường dùng làm danh từ chỉ chiếc khăn của cô dâu ngày xưa hoặc động từ với nghĩa buộc, thắt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('襆', '{"9000": "7441.0", "Chữ Trung Quốc": "襆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 17 | nét | 衣 | y | biểu nghĩa | quần áo, vải | 菐 | bộc | biểu âm | 襆 = 衣 (Y, biểu nghĩa: vải/quần áo) + 菐 (Bộc, biểu âm). Chữ hình thanh. Vải (衣) với âm từ 菐 → tấm vải bọc, hoặc mũ đầu của đàn ông. Slug boc-襆 xác nhận HV là \"bọc\".", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bọc\": vải (衣) + âm bộc (菐) → tấm vải \"bọc\" quanh đồ vật, hoặc chiếc mũ bọc đầu quan lại. | Gương Hán-Việt | bọc — liên kết với nghĩa tiếng Việt \"bọc\" (wrap/cover), cùng nghĩa thực dụng. | Mở khoá kiến thức | Biết 襆 mở khoá: 襆頭 (mũ bọc đầu quan lại), 襆被 (túi bọc chăn gối khi đi đường).", "Tự nguyên_Xie": "Theo Wiktionary, 襆 là chữ hình thanh gồm 衣 (semantic: vải/quần áo) và 菐 (phonetic). Hai nghĩa: 1) tấm vải dùng để phủ/bọc đồ vật; 2) mũ đầu truyền thống của đàn ông (hist). Có từ ghép: 襆頭 (mũ bọc đầu), 襆被 (vải bọc chăn). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Đài Loan [pu2]; váy không viền; mui xe; khăn xếp", "Hạng Tần Suất (Jun Da)": "7441.0", "Tần Suất % (Jun Da)": "99.9984103689", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 菐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤菐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "菐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "襆", "Unihan_Traditional (Chữ Phồn thể)": "襆", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "bộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này dùng làm danh từ chỉ khăn trùm đầu, khăn gói đồ hoặc làm động từ với nghĩa bao bọc lại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詤', '{"9000": "7442.0", "Chữ Trung Quốc": "詤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 13 | nét | 詤 | hoảng | tượng hình | nói dối; lời giả dối | 詤 thuộc bộ 言/讠 (ngôn – lời nói). Wiktionary xác nhận: dạng thay thế của 謊 (nói dối). Chữ gợi hình lời nói (言) bịa đặt, hư dối.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoảng\": bộ 言 (ngôn – lời nói) gợi những lời \"hoảng\" loạn, bịa đặt — nói dối làm người nghe \"hoảng\" sợ rồi mới biết là dối. | Gương Hán-Việt | hoảng — liên kết với 謊 (hoảng – nói dối), cùng âm và nghĩa HV. | Mở khoá kiến thức | Biết 詤 giúp nhận ra dạng cổ của 謊 (nói dối) và 說謊 (sói hoảng) trong cổ văn.", "Tự nguyên_Xie": "Theo Wiktionary, 詤 (âm huǎng) là dạng thay thế (alt form) của 謊 — nghĩa là nói dối, lời giả dối. Thuộc bộ 言/讠 (ngôn). Có ghi âm cổ oc=y. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "褤", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 㠩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言㠩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㠩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "詤", "Unihan_Traditional (Chữ Phồn thể)": "詤", "Pinyin_Xie": "huǎng", "Âm Hán Việt_Xie": "hoảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường dùng làm động từ chỉ hành động nói dối hoặc làm danh từ chỉ lời nói không thật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('譓', '{"9000": "7443.0", "Chữ Trung Quốc": "譓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 19 | nét | 譓 | tuệ | tượng hình | phân biệt rõ; phục tùng | 譓 thuộc bộ 言/讠 (ngôn – lời nói). Không có dữ liệu CHISE chi tiết. Wiktionary xác nhận hai nghĩa văn ngữ: 1) phân biệt rõ ràng, nhận thức sáng suốt; 2) phục tùng, tuân theo. Chữ gợi hình lời nói có trí tuệ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuệ\": bộ 言 (ngôn – lời nói) gợi lời nói \"tuệ\" trí, sáng suốt — người tuệ trí biết phân biệt đúng sai và phục tùng lẽ phải. | Gương Hán-Việt | tuệ — liên kết với 慧 (tuệ – trí tuệ), 惠 (tuệ – ân huệ), cùng âm HV. | Mở khoá kiến thức | Biết 譓 giúp đọc văn bản triết học và Nho giáo cổ đại về đức tính phân biệt và phục tùng.", "Tự nguyên_Xie": "Theo Wiktionary, 譓 (âm huì) có hai nghĩa văn ngữ: 1) phân biệt rõ ràng (to distinguish clearly, to discern); 2) phục tùng, vâng lời (to submit to, to obey). Thuộc bộ 言 (ngôn). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蓓", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 惠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言惠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "惠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "譓", "Unihan_Traditional (Chữ Phồn thể)": "譓", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "tuệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ chỉ sự thông thái hoặc làm động từ trong văn ngôn với nghĩa tuân theo. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跊', '{"9000": "7444.0", "Chữ Trung Quốc": "跊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 12 | nét | 跊 | muội | tượng hình | bộ chân (足), nghĩa không rõ | 跊 mang bộ 足 (túc, chân), nhưng cấu trúc chi tiết không rõ trong nguồn hiện có. Chữ rất hiếm, ý nghĩa gốc chưa được khảo chứng đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"muội\": bộ 足 (chân) gợi hành động chân bước, nhưng chữ này cực hiếm trong văn bản cổ. | Gương Hán-Việt | Chữ 跊 không xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 跊 giúp nhận ra bộ 足 trong các chữ chỉ chân/bước đi như 跑, 跳, 路.", "Tự nguyên_Xie": "跊 thuộc bộ 足 (túc, chân). Không có nguồn Wiktionary hay giáp cốt/kim văn cho chữ này. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chí", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 未", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊未", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "未", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跊", "Unihan_Traditional (Chữ Phồn thể)": "跊", "Pinyin_Xie": "mèi", "Âm Hán Việt_Xie": "muội", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ hành động đặt chân hoặc dẫm lên vật gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軈', '{"9000": "7445.0", "Chữ Trung Quốc": "軈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 身 | Số nét | 24 | nét | 軈 | anh | tượng hình | chữ Nhật thuần tuý (kokuji), bộ 身 | 軈 là chữ kokuji — chữ Hán do người Nhật tự tạo, không có trong hệ thống chữ Hán Trung Quốc truyền thống. Bộ thủ 身 (thân, thân thể) nhưng cấu trúc phân tích không có trong nguồn Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"anh\": chữ kokuji Nhật Bản, bộ 身 (thân thể) — hình dung thân người sắp bước sang giai đoạn tiếp theo, tức ''chẳng bao lâu''. | Gương Hán-Việt | Chữ 軈 không có trong từ Hán-Việt thông dụng tiếng Việt vì là chữ kokuji. | Mở khoá kiến thức | Biết 軈 giúp nhận ra đặc điểm của chữ kokuji trong bộ 身.", "Tự nguyên_Xie": "軈 là chữ kokuji (国字) — chữ tạo riêng tại Nhật Bản, không phải chữ Hán gốc Trung Quốc. Wiktionary ghi rõ ''{{ja-etym-kokuji}}'', nghĩa là không có nguồn giáp cốt hay kim văn. Âm Nhật: やがて (yagate), nghĩa ''chẳng bao lâu sau, sắp sửa''. Chưa có nguồn học thuật Hán-Việt. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "興", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "身 + 應", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰身應", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "應", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "身", "Unihan_Simplified (Chữ Giản thể)": "軈", "Unihan_Traditional (Chữ Phồn thể)": "軈", "Pinyin_Xie": "ying", "Âm Hán Việt_Xie": "anh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn ngôn để chỉ sự bắt đầu hoặc trỗi dậy của một sự việc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苘', '{"9000": "7446.0", "Chữ Trung Quốc": "苘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 苘 | khoảnh | tượng hình | bộ 艸 (thảo, cỏ), dị thể của 檾 | 苘 là dị thể (variant) của chữ 檾, thuộc bộ 艸 (thảo). Wiktionary ghi ''{{zh-see|檾|v}}'' — tức 苘 chỉ là dạng viết khác, không phân tích thêm cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoảnh\": bộ 艸 (cỏ) — hình dung mảnh đất (khoảnh) trồng đầy cây đay, loài cỏ dùng làm sợi dệt vải. | Gương Hán-Việt | Chữ 苘 ít xuất hiện trong từ Hán-Việt thông dụng; liên quan đến tên thực vật. | Mở khoá kiến thức | Biết 苘 giúp nhận ra nhóm chữ chỉ thực vật sợi thuộc bộ 艸 như 苎 (gai).", "Tự nguyên_Xie": "苘 là dị thể của 檾, chỉ cây đay (Indian mallow, Abutilon theophrasti). Wiktionary chỉ redirect về 檾 mà không có phân tích cấu trúc riêng. Bộ 艸 (thảo) xác định đây là thực vật. Chưa có nguồn học thuật sâu hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loài cỏ còn có tên cỏ bạch mã", "Hạng Tần Suất (Jun Da)": "7446.0", "Tần Suất % (Jun Da)": "99.9984181207", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 冋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹冋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苘", "Unihan_Traditional (Chữ Phồn thể)": "苘", "Pinyin_Xie": "qǐng", "Âm Hán Việt_Xie": "khoảnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ đứng độc lập hoặc làm thành phần trong tên gọi các loại cây lấy sợi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迺', '{"9000": "7447.0", "Chữ Trung Quốc": "迺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 9 | nét | 迺 | nãi | tượng hình | bộ 辵 (sước), dạng cổ của 乃 | 迺 thuộc bộ 辵 (sước, đi), là dạng cổ/dị thể của 乃 (nãi). Wiktionary ghi ''{{Han etym}}'' nhưng không phân tích rõ cấu trúc nội bộ. Đây là chữ hội ý, kết hợp ý đi (辵) với ý 乃 (trợ từ/liên từ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nãi\": bộ 辵 (đi bước) + ý 乃 (bèn, rồi thì) — hình dung sau khi bước qua ngưỡng cửa, rồi mới làm điều tiếp theo. | Gương Hán-Việt | 迺 xuất hiện trong cổ văn với nghĩa ''bèn, rồi'' tương đương 乃 trong tiếng Hán-Việt. | Mở khoá kiến thức | Biết 迺 giúp đọc cổ văn Hán dùng dạng chữ 辵 cho các liên từ/trợ từ.", "Tự nguyên_Xie": "Đại triện | 迺 là dạng cổ của 乃 (nãi), thuộc bộ 辵 (sước, đi). Nghĩa: bèn, thì, rồi mới (trợ từ cổ văn). Có dạng đại triện (bigseal) còn lưu. Wiktionary chỉ ghi ''{{Han etym}}'' không có phân tích chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bèn (trợ từ)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 西", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶西", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "西", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迺", "Unihan_Traditional (Chữ Phồn thể)": "迺", "Pinyin_Xie": "nǎi", "Âm Hán Việt_Xie": "nãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Liên từ | 连词 | Đại từ | 代词 | Trợ từ | 助词 | Thường dùng làm liên từ nối các vế câu biểu thị quan hệ tiếp nối hoặc nhân quả trong văn ngôn. | Liên từ | 连词 | Nối từ, cụm từ hoặc mệnh đề: 和, 但是, 因为…所以…. Lưu ý 和 chỉ nối danh từ, không nối hai câu như ''và'' tiếng Việt. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掭', '{"9000": "7448.0", "Chữ Trung Quốc": "掭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 掭 | thiêm | tượng hình | bộ 手 (thủ, tay), hành động chấm bút | 掭 mang bộ 手 (thủ, tay), chỉ hành động dùng tay thao tác — cụ thể là chấm bút lông vào nghiên mực hoặc khêu bấc đèn. Không có dữ liệu cấu trúc chi tiết trong nguồn hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiêm\": bộ 手 (tay) — hình dung tay nghiêng (thiêm) nhẹ chấm ngọn bút vào nghiên mực trước khi viết. | Gương Hán-Việt | Chữ 掭 ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 掭 giúp hiểu nhóm từ chỉ kỹ thuật viết thư pháp cổ điển.", "Tự nguyên_Xie": "掭 thuộc bộ 手 (thủ, tay). Nghĩa: chấm bút lông vào nghiên mực; khêu ngọn đèn. Không có nguồn Wiktionary hay giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chấm bút lông vào nghiên mực; khêu ngọn đèn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 忝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌忝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "忝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "掭", "Unihan_Traditional (Chữ Phồn thể)": "掭", "Pinyin_Xie": "tiàn", "Âm Hán Việt_Xie": "thiệm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ đi kèm tân ngữ chỉ bút lông hoặc ngọn đèn để tả động tác nhẹ nhàng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邘', '{"9000": "7449.0", "Chữ Trung Quốc": "邘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 5 | nét | 邘 | vu | tượng hình | bộ 邑 (ấp, đất/nước), tên nước cổ | 邘 thuộc bộ 邑 (ấp), chỉ tên địa danh/nước cổ ở vùng Hà Nam. Wiktionary ghi ''{{Han etym}}'' — có hình tiểu triện — nhưng không phân tích cấu trúc nội bộ riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vu\": bộ 邑 (ấp, đất) — đất (vu) đó là nước Vu cổ đại ở Hà Nam, một địa danh xuất hiện trong Kinh Thi. | Gương Hán-Việt | 邘 xuất hiện trong sử liệu cổ với tên 邘國 (nước Vu), con dòng vua Trụ nhà Thương. | Mở khoá kiến thức | Biết 邘 giúp nhận diện nhóm chữ bộ 邑 chỉ địa danh cổ đại Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | 邘 là tên nước cổ (邘國) tại vùng Hà Nam, Trung Quốc. Bộ 邑 (ấp) xác định đây là địa danh. Tiểu triện còn lưu qua hanziyuan. Wiktionary chỉ ghi là ''proper noun'' dùng trong địa danh. Chưa có nguồn học thuật phân tích sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Vu", "Hạng Tần Suất (Jun Da)": "7449.0", "Tần Suất % (Jun Da)": "99.9984243221", "GavinGrover_Once (Chiết tự trực tiếp)": "于 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰于阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "于", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邘", "Unihan_Traditional (Chữ Phồn thể)": "邘", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "vu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng chỉ tên nước cổ hoặc họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄳', '{"9000": "7450.0", "Chữ Trung Quốc": "鄳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 15 | nét | 鄳 | mang | tượng hình | bộ 邑 (ấp), tên đất cổ ở Hà Nam | 鄳 thuộc bộ 邑 (ấp), chỉ tên đất cổ tại vùng Lạc Sơn (Luoshan), Hà Nam. Wiktionary ghi ''{{Han etym}}'' có hình tiểu triện nhưng không phân tích cấu trúc nội bộ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mang\": bộ 邑 (đất, ấp) — vùng đất (mang) bên sông cổ đại ở Hà Nam, tên chỉ xuất hiện trong địa lý cổ. | Gương Hán-Việt | 鄳 không xuất hiện trong từ Hán-Việt thông dụng; chỉ là tên đất cổ. | Mở khoá kiến thức | Biết 鄳 giúp nhận diện nhóm chữ bộ 邑 chỉ địa danh cổ đại.", "Tự nguyên_Xie": "Tiểu triện | 鄳 là tên địa danh cổ tại vùng Lạc Sơn (Luoshan), tỉnh Hà Nam. Bộ 邑 (ấp) xác nhận đây là địa danh. Tiểu triện còn lưu qua hanziyuan. Wiktionary không có phân tích cấu trúc chi tiết. Chưa có nguồn học thuật sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鄄", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "黽 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰黽阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黽", "Unihan_Simplified (Chữ Giản thể)": "鄳", "Unihan_Traditional (Chữ Phồn thể)": "鄳", "Pinyin_Xie": "méng", "Âm Hán Việt_Xie": "mang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng trong địa danh lịch sử Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猸', '{"9000": "7451.0", "Chữ Trung Quốc": "猸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 12 | nét | 犭 | khuyển | biểu nghĩa | thú, con vật | 眉 | mi | biểu âm | lông mày (cho âm) | 猸 = 犭(Khuyển, biểu nghĩa: thú vật) + 眉 (Mi, biểu âm). Chữ hình thanh: 犭 chỉ đây là loài thú, 眉 cho âm đọc méi. Cấu trúc rõ từ Wiktionary: ''{{Han compound|犬|眉|alt1=犭|ls=psc|c1=s|c2=p}}''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mi\": 犭 (thú) + 眉 (lông mày) — con thú có \"lông mày\" nổi bật, hình dung con mòng cua với đặc điểm mặt mũi đặc trưng. | Gương Hán-Việt | Chữ 猸 ít xuất hiện trong từ Hán-Việt thông dụng; chủ yếu dùng trong văn bản động vật học cổ. | Mở khoá kiến thức | Biết 猸 giúp nhận ra cấu trúc hình thanh điển hình: bộ 犭 + âm phù.", "Tự nguyên_Xie": "猸 là chữ hình thanh (psc): 犭 (khuyển, thú vật — biểu nghĩa) + 眉 (mi, lông mày — biểu âm, cho âm méi). Wiktionary ghi rõ cấu trúc này. Chỉ một loài thú, có thể là cầy hương hoặc con mòng cua. Không có hình giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con mòng cua", "Hạng Tần Suất (Jun Da)": "7451.0", "Tần Suất % (Jun Da)": "99.9984274228", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 眉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭眉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "眉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猸", "Unihan_Traditional (Chữ Phồn thể)": "猸", "Pinyin_Xie": "méi", "Âm Hán Việt_Xie": "mi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ một loài động vật có vú nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艴', '{"9000": "7452.0", "Chữ Trung Quốc": "艴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 色 | Số nét | 11 | nét | 艴 | phất | tượng hình | bộ 色 (sắc, màu/sắc mặt), vẻ giận dữ | 艴 thuộc bộ 色 (sắc, màu sắc/sắc mặt). Wiktionary ghi ''{{Han etym}}'' có hình tiểu triện nhưng không phân tích cấu trúc nội bộ. Nghĩa là vẻ mặt hằm hằm, giận dữ — bộ 色 hàm ý biến sắc mặt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phất\": bộ 色 (sắc mặt) — khi phất (giận bừng lên), sắc mặt biến đổi tức thì, mặt đỏ ửng hay tái xanh. | Gương Hán-Việt | 艴 xuất hiện trong thành ngữ cổ \"艴然\" (phất nhiên) = nét mặt đột nhiên biến sắc vì giận. | Mở khoá kiến thức | Biết 艴 giúp đọc cổ văn mô tả cảm xúc qua sắc mặt, đặc biệt thành ngữ 艴然.", "Tự nguyên_Xie": "Tiểu triện | 艴 thuộc bộ 色 (sắc, màu sắc mặt). Nghĩa: nét mặt biến sắc, hằm hằm giận dữ (văn ngôn). Tiểu triện còn lưu qua hanziyuan. Wiktionary không phân tích cấu trúc nội bộ. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giận giữ, hằm hằm", "Hạng Tần Suất (Jun Da)": "7452.0", "Tần Suất % (Jun Da)": "99.9984289732", "GavinGrover_Once (Chiết tự trực tiếp)": "弗 + 色", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰弗色", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "色", "Unihan_Simplified (Chữ Giản thể)": "艴", "Unihan_Traditional (Chữ Phồn thể)": "艴", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ miêu tả thần thái, sắc mặt tức giận của con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鑕', '{"9000": "7453.0", "Chữ Trung Quốc": "鑕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 23 | nét | 鑕 | chặt | tượng hình | bộ 金 (kim, kim loại), bệ hành quyết bằng kim loại | 鑕 thuộc bộ 金 (kim, kim loại). Wiktionary ghi ''{{Han etym}}'' nhưng không phân tích cấu trúc nội bộ. Nghĩa: bệ hành quyết bằng kim loại (đặt người bị chặt đôi lên), hoặc động từ: chặt đầu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chặt\": bộ 金 (kim loại) — khối kim loại (鑕) dùng để chặt — đúng nghĩa đen và cũng là âm Hán-Việt của chữ. | Gương Hán-Việt | 鑕 xuất hiện trong cổ ngữ với thành ngữ 砧鑕 (thớt và bệ chặt), hình ảnh hành quyết cổ đại. | Mở khoá kiến thức | Biết 鑕 giúp đọc cổ văn mô tả hình phạt và dụng cụ kim loại thời cổ đại.", "Tự nguyên_Xie": "鑕 thuộc bộ 金 (kim, kim loại). Nghĩa cổ: bệ (khối kim loại) dùng trong hình phạt chặt đôi người thời cổ đại; hoặc động từ ''chặt đầu, xử trảm''. Xuất hiện trong thành ngữ 砧鑕 (bệ chặt) và 斧鑕 (rìu và bệ). Wiktionary không phân tích cấu trúc. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "锧", "Hạng Tần Suất (Jun Da)": "8497.0", "Tần Suất % (Jun Da)": "99.99968011", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 質", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金質", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "質", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "锧", "Unihan_Traditional (Chữ Phồn thể)": "鑕", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "chặt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cái thớt dùng để kê chém đầu thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('柃', '{"9000": "7454.0", "Chữ Trung Quốc": "柃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 柃 | rành | tượng hình | bộ 木 (mộc, cây), loài cây Eurya japonica | 柃 thuộc bộ 木 (mộc, cây gỗ). Wiktionary ghi ''{{Han etym}}'' có hình tiểu triện nhưng không phân tích cấu trúc nội bộ. Nghĩa: loài cây bụi Eurya japonica, lá và cành dùng làm thuốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"rành\": bộ 木 (cây) — cây rành (柃) là bụi cây thuốc quen thuộc với những ai rành về thảo dược. | Gương Hán-Việt | Chữ 柃 ít xuất hiện trong từ Hán-Việt thông dụng; chủ yếu dùng trong tên thực vật học. | Mở khoá kiến thức | Biết 柃 giúp nhận ra nhóm chữ bộ 木 chỉ cây bụi/cây thuốc trong thực vật học cổ.", "Tự nguyên_Xie": "Tiểu triện | 柃 thuộc bộ 木 (mộc). Chỉ loài cây bụi Eurya japonica — cây rành (theo Hán-Việt), lá và cành có thể làm thuốc, quả làm nhiên liệu. Tiểu triện còn lưu qua Wikimedia. Wiktionary không phân tích cấu trúc chi tiết. Chưa có nguồn học thuật sâu. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại thực vật, lá và cành có thể làm thuốc, quả làm nhiên liệu)", "Hạng Tần Suất (Jun Da)": "7454.0", "Tần Suất % (Jun Da)": "99.9984320739", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "柃", "Unihan_Traditional (Chữ Phồn thể)": "柃", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cây bụi nhỏ dùng trong y học cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闒', '{"9000": "7455.0", "Chữ Trung Quốc": "闒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 18 | nét | 闒 | thạp | tượng hình | bộ 門 (môn, cửa), cửa nhỏ tầng trên | 闒 thuộc bộ 門 (môn, cửa). Wiktionary ghi ''{{Han etym}}'' có hình tiểu triện nhưng không phân tích cấu trúc nội bộ. Nghĩa: cửa nhỏ ở tầng trên của ngôi nhà cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thạp\": bộ 門 (cửa) — cửa thạp (nhỏ, thấp) ở tầng trên nhà cổ, người cúi đầu mới qua được. | Gương Hán-Việt | 闒 xuất hiện trong thành ngữ cổ 闒茸 (thạp nhung) = hèn mọn, tầm thường. | Mở khoá kiến thức | Biết 闒 giúp đọc cổ văn có thành ngữ 闒茸 và nhóm chữ bộ 門 chỉ loại cửa.", "Tự nguyên_Xie": "Tiểu triện | 闒 thuộc bộ 門 (môn, cửa). Nghĩa: cửa nhỏ đặt ở tầng trên (thượng tầng) trong kiến trúc cổ. Xuất hiện trong từ ghép 闒茸 (thạp nhung) = hèn mọn, tầm thường (chuyển nghĩa từ ''cửa nhỏ thấp''). Tiểu triện còn lưu qua hanziyuan. Wiktionary không phân tích nội bộ. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "阘", "Hạng Tần Suất (Jun Da)": "6838.0", "Tần Suất % (Jun Da)": "99.9961163597", "GavinGrover_Once (Chiết tự trực tiếp)": "門 + 𦐇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門𦐇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦐇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "阘", "Unihan_Traditional (Chữ Phồn thể)": "闒", "Pinyin_Xie": "tà", "Âm Hán Việt_Xie": "thạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ cửa nhỏ hoặc làm tính từ chỉ sự thấp hèn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('毹', '{"9000": "7456.0", "Chữ Trung Quốc": "毹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 毛 | Số nét | 13 | nét | 毹 | thu | tượng hình | bộ 毛 (mao, lông), thảm trải sàn | 毹 thuộc bộ 毛 (mao, lông/sợi lông). Nghĩa: thảm trải sàn, chăn mền làm từ sợi lông. Wiktionary ghi chỉ dùng trong từ ghép 氍毹 (cụ thu) = tấm thảm trải sân khấu. Bộ 毛 xác nhận chất liệu từ lông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thu\": bộ 毛 (lông) — tấm thảm lông (thu) mềm mại trải trên sàn sân khấu, nơi diễn viên bước đi. | Gương Hán-Việt | 毹 xuất hiện trong từ ghép 氍毹 (cụ thu) = thảm sân khấu trong văn học cổ điển Trung Quốc. | Mở khoá kiến thức | Biết 毹 giúp đọc từ ghép 氍毹 trong văn bản về sân khấu kịch cổ điển.", "Tự nguyên_Xie": "Tiểu triện | 毹 thuộc bộ 毛 (mao, lông). Wiktionary ghi ''{{zh-only|氍毹}}'' — chỉ dùng trong từ ghép 氍毹 (cụ thu), chỉ loại thảm dệt từ lông thú trải trên sàn sân khấu diễn kịch cổ điển. Tiểu triện còn lưu qua Wikimedia. Chưa có nguồn học thuật phân tích nội bộ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thảm trải sàn; chăn, mền", "Hạng Tần Suất (Jun Da)": "7456.0", "Tần Suất % (Jun Da)": "99.9984351746", "GavinGrover_Once (Chiết tự trực tiếp)": "俞 + 毛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰俞毛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "毛", "Unihan_Simplified (Chữ Giản thể)": "毹", "Unihan_Traditional (Chữ Phồn thể)": "毹", "Pinyin_Xie": "shū", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường xuất hiện trong từ ghép để chỉ thảm lông thú. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脶', '{"9000": "7457.0", "Chữ Trung Quốc": "脶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 脶 | loa | tượng hình | bộ 肉/月 (nhục, thịt/da), vân tay | 脶 là giản thể của 腡, thuộc bộ 肉/月 (nhục, thịt/da người). Wiktionary ghi ''{{Han simp|腡|f=咼|t=呙}}'' — giản hoá từ 腡 bằng cách thay 咼 thành 呙. Nghĩa: các đường vân trên ngón tay (vân tay, chỉ văn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"loa\": bộ 月/肉 (da thịt) — vân tay cuộn như vỏ ốc loa (loa螺), các đường nét xoắn đặc trưng trên đầu ngón tay. | Gương Hán-Việt | 脶/腡 dùng trong từ 螺纹 (loa văn) = vân xoắn, và trong thuật ngữ vân tay học. | Mở khoá kiến thức | Biết 脶 giúp nhận ra nhóm chữ bộ 肉 chỉ đặc điểm da/thân thể.", "Tự nguyên_Xie": "脶 là giản thể của 腡 (loa). Wiktionary ghi ''{{Han simp|腡|f=咼|t=呙}}'' — đơn giản hoá 腡 bằng cách thay phần 咼 thành 呙. Bộ 肉/月 (nhục) xác nhận liên quan đến thân thể. Nghĩa: các đường vân da trên ngón tay. Chưa có nguồn học thuật sâu hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vân tay", "Hạng Tần Suất (Jun Da)": "7457.0", "Tần Suất % (Jun Da)": "99.998436725", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 呙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月呙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "呙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脶", "Unihan_Traditional (Chữ Phồn thể)": "腡", "Pinyin_Xie": "luó", "Âm Hán Việt_Xie": "loa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ đường vân lồi hình tròn trên đầu ngón tay. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颋', '{"9000": "7458.0", "Chữ Trung Quốc": "颋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 12 | nét | 颋 | thĩnh | tượng hình | bộ 頁 (hiệt, đầu/trang), đầu ngay thẳng | 颋 thuộc bộ 頁 (hiệt, đầu người). Wiktionary dùng chữ phồn thể 頲 có hình tiểu triện. Nghĩa: đầu ngay thẳng, đứng thẳng — bộ 頁 xác nhận liên quan đến đầu/thân thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thĩnh\": bộ 頁 (đầu) — cái đầu (thĩnh) giữ thẳng, không cúi, biểu trưng cho sự ngay thẳng. | Gương Hán-Việt | Chữ 颋/頲 ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 颋 giúp nhận ra nhóm chữ bộ 頁 chỉ tư thế đầu/cổ trong cổ ngữ.", "Tự nguyên_Xie": "Tiểu triện | 颋 (phồn thể: 頲) thuộc bộ 頁 (hiệt, đầu). Nghĩa văn ngôn: đầu ngay thẳng; nghĩa mở rộng: thẳng thắn, ngay thẳng. Tiểu triện còn lưu qua hanziyuan. Wiktionary không phân tích cấu trúc nội bộ. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngay thẳng", "Hạng Tần Suất (Jun Da)": "7458.0", "Tần Suất % (Jun Da)": "99.9984382753", "GavinGrover_Once (Chiết tự trực tiếp)": "廷 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰廷页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "廷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颋", "Unihan_Traditional (Chữ Phồn thể)": "頲", "Pinyin_Xie": "tǐng", "Âm Hán Việt_Xie": "đĩnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả tính cách ngay thẳng hoặc dáng đứng thẳng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鵀', '{"9000": "7459.0", "Chữ Trung Quốc": "鵀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 17 | nét | 鵀 | nhân | tượng hình | bộ 鳥 (điểu, chim), chim đầu rìu (hoopoe) | 鵀 thuộc bộ 鳥 (điểu, chim). Wiktionary ghi ''{{Han etym}}'' có thông tin phát âm nhưng không phân tích cấu trúc nội bộ. Nghĩa: chim đầu rìu (hoopoe), cũng gọi là 戴勝 (đới thắng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhân\": bộ 鳥 (chim) — con chim (nhân) đội mào xoè ra như bàn tay con người (nhân), tức chim đầu rìu hoopoe. | Gương Hán-Việt | 鵀 ít xuất hiện trong từ Hán-Việt thông dụng; chủ yếu trong thơ ca và tên loài chim. | Mở khoá kiến thức | Biết 鵀 giúp nhận diện nhóm chữ bộ 鳥 chỉ các loài chim đặc trưng trong thi ca cổ.", "Tự nguyên_Xie": "鵀 thuộc bộ 鳥 (điểu, chim). Nghĩa: con chim đầu rìu (hoopoe — Upupa epops), một loài chim có mào đặc trưng. Đồng nghĩa với 戴勝 (đới thắng). Wiktionary không phân tích cấu trúc nội bộ. Không có hình giáp cốt/kim văn. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoopoe", "Hạng Tần Suất (Jun Da)": "7459.0", "Tần Suất % (Jun Da)": "99.9984398257", "GavinGrover_Once (Chiết tự trực tiếp)": "任 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱任鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "任", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鵀", "Unihan_Traditional (Chữ Phồn thể)": "鵀", "Pinyin_Xie": "rén", "Âm Hán Việt_Xie": "nhậm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim có mào lông giống như chiếc rìu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶜', '{"9000": "7460.0", "Chữ Trung Quốc": "鶜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 19 | nét | 鶜 | mao | tượng hình | bộ 鳥 (điểu, chim), loài chim trong từ ghép 鶜鴟 | 鶜 thuộc bộ 鳥 (điểu, chim). Wiktionary ghi chỉ dùng trong từ ghép 鶜鴟. Không có phân tích cấu trúc nội bộ. Chữ rất hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mao\": bộ 鳥 (chim) — con chim (mao) trong cặp tên 鶜鴟, một loài chim hiếm nhắc đến trong cổ thư. | Gương Hán-Việt | Chữ 鶜 chỉ xuất hiện trong từ ghép 鶜鴟 trong cổ thư. | Mở khoá kiến thức | Biết 鶜 giúp nhận diện nhóm chữ bộ 鳥 chỉ loài chim cổ điển rất hiếm.", "Tự nguyên_Xie": "鶜 thuộc bộ 鳥 (điểu, chim). Wiktionary ghi ''{{zh-only|鶜鴟}}'' — chỉ dùng trong tên ghép 鶜鴟 (mao xi), một loài chim cụ thể. Không có hình giáp cốt/kim văn. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鶜", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "茅 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰茅鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "茅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鶜", "Unihan_Traditional (Chữ Phồn thể)": "鶜", "Pinyin_Xie": "máo", "Âm Hán Việt_Xie": "mao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim nước được ghi chép trong sách cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶟', '{"9000": "7461.0", "Chữ Trung Quốc": "鶟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 20 | nét | 鶟 | đồ | tượng hình | bộ 鳥 (điểu, chim), một loài chim | 鶟 thuộc bộ 鳥 (điểu, chim). Wiktionary ghi ''{{Han etym}}'' nhưng không phân tích cấu trúc nội bộ. Chỉ là tên một loài chim cổ điển.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồ\": bộ 鳥 (chim) — loài chim (đồ) trong tên Thiệu/Triệu, gợi sự liên hệ với danh nhân lịch sử. | Gương Hán-Việt | Chữ 鶟 ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 鶟 giúp nhận diện nhóm chữ bộ 鳥 chỉ tên loài chim rất hiếm trong cổ thư.", "Tự nguyên_Xie": "鶟 thuộc bộ 鳥 (điểu, chim). Wiktionary chỉ ghi ''a type of bird'' không có thêm thông tin. Không có hình giáp cốt/kim văn. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Thiệu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "突 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰突鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "突", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鶟", "Unihan_Traditional (Chữ Phồn thể)": "鶟", "Pinyin_Xie": "tú", "Âm Hán Việt_Xie": "đồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim hoang dã thuộc họ trĩ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鷱', '{"9000": "7462.0", "Chữ Trung Quốc": "鷱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 23 | nét | 鷱 | cao | tượng hình | bộ 鳥 (điểu, chim), chỉ dùng trong từ ghép 𪁜鷱 | 鷱 thuộc bộ 鳥 (điểu, chim). Wiktionary ghi ''{{zh-used|𪁜鷱}}'' — chỉ dùng trong tên ghép đặc biệt. Không có phân tích cấu trúc nội bộ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cao\": bộ 鳥 (chim) — con chim bay cao (cao) trong tên ghép cổ điển. | Gương Hán-Việt | 鷱 chỉ xuất hiện trong từ ghép 𪁜鷱 trong cổ thư. | Mở khoá kiến thức | Biết 鷱 giúp nhận diện nhóm chữ bộ 鳥 chỉ tên loài chim rất hiếm.", "Tự nguyên_Xie": "鷱 thuộc bộ 鳥 (điểu, chim). Wiktionary ghi chỉ dùng trong từ ghép 𪁜鷱. Không có hình giáp cốt/kim văn. Không có nguồn học thuật. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鷱", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "臯 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰臯鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鷱", "Unihan_Traditional (Chữ Phồn thể)": "鷱", "Pinyin_Xie": "gāo", "Âm Hán Việt_Xie": "cao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim nước lớn thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹍', '{"9000": "7463.0", "Chữ Trung Quốc": "鹍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 13 | nét | 鹍 | côn | tượng hình | bộ 鳥 (điểu, chim), giống hạc (côn kê) | 鹍 thuộc bộ 鳥 (điểu, chim). Không có dữ liệu cấu trúc nội bộ. Nghĩa: loài chim giống hạc, dùng trong từ ghép 鵾雞/鹍鸡 (côn kê).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"côn\": bộ 鳥 (chim) — con chim côn (鹍) to lớn như côn (棍, gậy), cổ dài thanh mảnh như hạc. | Gương Hán-Việt | 鹍 xuất hiện trong từ ghép 鹍鸡 (côn kê) và trong thơ ca cổ điển. | Mở khoá kiến thức | Biết 鹍 giúp nhận ra từ ghép 鹍鸡 và nhóm chữ bộ 鳥 chỉ loài chim lớn.", "Tự nguyên_Xie": "鹍 thuộc bộ 鳥 (điểu, chim). Nghĩa: loài chim giống hạc (crane-like bird), chủ yếu dùng trong từ ghép 鹍鸡 (côn kê). Không có nguồn Wiktionary hay giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: côn kê 鵾雞,鹍鸡)", "Hạng Tần Suất (Jun Da)": "7463.0", "Tần Suất % (Jun Da)": "99.9984475775", "GavinGrover_Once (Chiết tự trực tiếp)": "昆 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰昆鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹍", "Unihan_Traditional (Chữ Phồn thể)": "鵾", "Pinyin_Xie": "kūn", "Âm Hán Việt_Xie": "côn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường dùng trong từ ghép để chỉ loài chim hạc lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麖', '{"9000": "7464.0", "Chữ Trung Quốc": "麖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 19 | nét | 麖 | kinh | tượng hình | bộ 鹿 (lộc, hươu), loài hươu lớn sambar | 麖 thuộc bộ 鹿 (lộc, hươu). Wiktionary ghi ''{{Han etym}}'' có hình tiểu triện nhưng không phân tích cấu trúc nội bộ. Nghĩa: loài hươu to, có thể là sambar deer — hươu nước (thuỷ lộc), cổ tương đối cao.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kinh\": bộ 鹿 (hươu) — con hươu kinh (to lớn, gây kinh sợ) chạy trong rừng sâu — sambar deer khổng lồ. | Gương Hán-Việt | 麖 xuất hiện trong cổ thư chỉ loài hươu lớn, ít dùng trong Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 麖 giúp nhận ra nhóm chữ bộ 鹿 chỉ các loài hươu nai trong văn bản tự nhiên cổ.", "Tự nguyên_Xie": "Tiểu triện | 麖 thuộc bộ 鹿 (lộc, hươu). Nghĩa văn ngôn: loài hươu lớn, có thể là sambar deer (Rusa unicolor) — hươu có cổ cao. Tiểu triện còn lưu qua Wikimedia. Wiktionary ghi ''{{lb|zh|obs-std}} a kind of large deer, probably sambar deer''. Chưa có nguồn học thuật phân tích cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuỷ lộc (loài hươu cổ tương đối cao)", "Hạng Tần Suất (Jun Da)": "7464.0", "Tần Suất % (Jun Da)": "99.9984491278", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 京", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿京", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "京", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麖", "Unihan_Traditional (Chữ Phồn thể)": "麖", "Pinyin_Xie": "jīng", "Âm Hán Việt_Xie": "kinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài động vật thuộc họ hươu nai. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軎', '{"9000": "7466.0", "Chữ Trung Quốc": "軎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 10 | nét | 軎 | vệ | tượng hình | bộ 車 (xa, xe), phụ kiện đồng trên trục xe cổ đại | 軎 thuộc bộ 車 (xa, xe). Wiktionary ghi ''{{liushu|p}}'' — chữ tượng hình mô tả phần trục xe (cart axle cap). Là chữ tượng hình (pictograph) vẽ hình đầu trục xe.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vệ\": bộ 車 (xe) — chiếc vệ (nắp bọc) bằng đồng gắn đầu trục xe hoàng gia — phụ kiện vệ (bảo vệ) trục xe. | Gương Hán-Việt | 軎 xuất hiện trong cổ thư chỉ phụ kiện xe ngựa cổ điển, ít dùng trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 軎 giúp đọc cổ thư mô tả xe ngựa và phụ kiện chiến xa thời cổ đại.", "Tự nguyên_Xie": "軎 thuộc bộ 車 (xa, xe). Wiktionary ghi ''{{liushu|p}} of a cart axle'' — đây là chữ tượng hình mô tả hình đầu trục xe ngựa cổ đại. Nghĩa: phụ kiện đồng bọc đầu trục xe (brass axle cap). Wiktionary redirect về 轊. Chữ tạo muộn, chưa thấy hình rõ ràng trong giáp cốt văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "绎", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 口", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱車口", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "口", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "軎", "Unihan_Traditional (Chữ Phồn thể)": "軎", "Pinyin_Xie": "wèi", "Âm Hán Việt_Xie": "vệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận kim loại bọc ở đầu trục bánh xe thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稂', '{"9000": "7467.0", "Chữ Trung Quốc": "稂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 12 | nét | 稂 | lang | tượng hình | bộ 禾 (hòa, lúa), cỏ hoang mọc trong ruộng lúa | 稂 thuộc bộ 禾 (hòa, lúa). Wiktionary ghi ''{{Han etym}}'' có hình tiểu triện nhưng không phân tích cấu trúc nội bộ. Nghĩa: cỏ hoang, cỏ dại mọc lẫn trong ruộng lúa — biểu trưng cho thứ vô dụng xen lẫn cái có giá trị.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lang\": bộ 禾 (lúa) — cỏ lang (lang thang) mọc hoang trong ruộng lúa, không ai trồng, không ai cần. | Gương Hán-Việt | 稂 xuất hiện trong thành ngữ 莠稂 hoặc trong Kinh Thi chỉ cỏ dại hại lúa. | Mở khoá kiến thức | Biết 稂 giúp đọc Kinh Thi và nhóm chữ bộ 禾 chỉ cỏ dại nông nghiệp.", "Tự nguyên_Xie": "Tiểu triện | 稂 thuộc bộ 禾 (hòa, lúa). Nghĩa: loài cỏ hoang dại (weeds) mọc trong ruộng lúa mạch. Tiểu triện còn lưu qua Wikimedia. Wiktionary không phân tích cấu trúc nội bộ. Chữ xuất hiện trong Kinh Thi (詩經) với hình ảnh cỏ dại. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ hoang, cỏ đồng", "Hạng Tần Suất (Jun Da)": "7467.0", "Tần Suất % (Jun Da)": "99.9984537789", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 良", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾良", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "良", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稂", "Unihan_Traditional (Chữ Phồn thể)": "稂", "Pinyin_Xie": "láng", "Âm Hán Việt_Xie": "lang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài cỏ dại thường mọc xen lẫn với lúa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佧', '{"9000": "7468.0", "Chữ Trung Quốc": "佧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 7 | nét | 佧 | kha | tượng hình | bộ 人/亻 (nhân, người), dùng trong tên dân tộc 佧佤 | 佧 thuộc bộ 亻 (nhân, người). Wiktionary ghi đây là chữ thay thế cho dạng cũ 𱭶 (chứa bộ 犭 mang tính xúc phạm). Chữ 佧 dùng bộ 亻 (người) để ghi tên dân tộc một cách tôn trọng hơn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kha\": bộ 亻 (người) — chữ 佧 được tạo ra với bộ người (nhân) để thay thế dạng cũ kỳ thị, tôn trọng dân tộc 佧佤. | Gương Hán-Việt | 佧 dùng trong tên 佧佤族 (Kha Oa tộc) — tên cũ của người Wa ở Vân Nam. | Mở khoá kiến thức | Biết 佧 giúp hiểu lịch sử chữ viết tên dân tộc thiểu số Trung Quốc và cải cách ký tự.", "Tự nguyên_Xie": "佧 là chữ thay thế cho 𱭶 (chứa bộ 犭 — biểu trưng thú vật, mang tính kỳ thị). Wiktionary ghi: ''A replacement for 𱭶 containing the derogatory 犭 radical.'' Bộ 亻 (người) được dùng thay để ghi tên dân tộc 佧佤族 (Wa people) một cách trung hoà. Không có nguồn học thuật phân tích cấu trúc. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: kha ngoã 佧佤)", "Hạng Tần Suất (Jun Da)": "7468.0", "Tần Suất % (Jun Da)": "99.9984599803", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 卡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻卡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "佧", "Unihan_Traditional (Chữ Phồn thể)": "佧", "Pinyin_Xie": "kǎ", "Âm Hán Việt_Xie": "kha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng, chủ yếu dùng trong từ ghép chỉ tộc người Wa cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('緌', '{"9000": "7469.0", "Chữ Trung Quốc": "緌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 14 | nét | 糸 | mịch | biểu nghĩa | tơ sợi, dải | 委 | uỷ | biểu âm | uỷ thác (cho âm ruí) | 緌 = 糸 (Mịch, biểu nghĩa: tơ sợi) + 委 (Uỷ, biểu âm). Chữ hình thanh: 糸 xác định đây là vật làm từ sợi/dải; 委 cung cấp âm đọc. Wiktionary: ''{{Han compound|糸|委|ls=psc|c1=s|t1=silk|c2=p}}''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhuỵ\": 糸 (sợi) + 委 (uỷ/rủ xuống) — sợi nhuỵ rủ xuống từ chóp mũ quan, như nhụy hoa rủ mềm mại. | Gương Hán-Việt | 緌 xuất hiện trong cổ văn mô tả trang phục quan lại, biểu trưng địa vị. | Mở khoá kiến thức | Biết 緌 giúp đọc văn bản mô tả lễ phục và trang phục quan lại thời cổ đại.", "Tự nguyên_Xie": "緌 là chữ hình thanh (psc): 糸 (mịch, tơ sợi — biểu nghĩa) + 委 (uỷ — biểu âm). Wiktionary ghi rõ cấu trúc này. Nghĩa: bông gù đính trên chóp mũ quan hoặc đỉnh cán cờ (tassel hanging from a hat). Chữ rất đặc trưng cho trang phục quan lại cổ đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gù bông (đính trên chóp mũ, đỉnh cán cờ)", "Hạng Tần Suất (Jun Da)": "7469.0", "Tần Suất % (Jun Da)": "99.998463081", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 委", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹委", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "委", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "緌", "Unihan_Traditional (Chữ Phồn thể)": "緌", "Pinyin_Xie": "ruí", "Âm Hán Việt_Xie": "nhuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần dây mũ buông xuống hoặc tua trang trí thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠾', '{"9000": "7470.0", "Chữ Trung Quốc": "蠾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 27 | nét | 蠾 | chúc | tượng hình | bộ 虫 (trùng, côn trùng), bọ chét hoặc sâu bướm | 蠾 thuộc bộ 虫 (trùng, côn trùng). Wiktionary ghi ''{{Han etym}}'' nhưng không phân tích cấu trúc nội bộ. Nghĩa cổ: bọ chét; hoặc dùng trong 蠾蝓; hoặc là dị thể của 蠋 (sâu bướm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chúc\": bộ 虫 (trùng) — con chúc (nhỏ li ti) bám vào thân thể, bọ chét hay sâu bướm trong văn bản cổ. | Gương Hán-Việt | Chữ 蠾 ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 蠾 giúp nhận ra nhóm chữ bộ 虫 chỉ các loài côn trùng nhỏ trong cổ thư.", "Tự nguyên_Xie": "蠾 thuộc bộ 虫 (trùng, côn trùng). Nghĩa cổ: bọ chét (flea); hoặc dùng trong tên ghép 蠾蝓; hoặc là dạng thay thế của 蠋 (chúc, sâu bướm caterpillar). Wiktionary không phân tích cấu trúc nội bộ. Chữ rất hiếm, nghĩa không rõ ràng. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thằn lằn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 屬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫屬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠾", "Unihan_Traditional (Chữ Phồn thể)": "蠾", "Pinyin_Xie": "zhú", "Âm Hán Việt_Xie": "chúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại sâu bướm hoặc côn trùng thân mềm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裲', '{"9000": "7471.0", "Chữ Trung Quốc": "裲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 13 | nét | 裲 | lưỡng | tượng hình | bộ 衣 (y, quần áo), áo gile không tay (waistcoat) | 裲 thuộc bộ 衣 (y, quần áo). Không có dữ liệu cấu trúc nội bộ từ Wiktionary hay anchor. Nghĩa: áo gile, áo không tay (waistcoat); dùng trong từ ghép 裲襠 (lưỡng đương) = loại áo bó phần trên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưỡng\": bộ 衣 (y, vải) — chiếc áo gile lưỡng (hai mặt, trước sau) che thân, không có tay áo. | Gương Hán-Việt | 裲 xuất hiện trong từ 裲襠 (lưỡng đương) trong văn bản lịch sử trang phục Trung Quốc. | Mở khoá kiến thức | Biết 裲 giúp nhận ra nhóm từ chỉ trang phục cổ đại Trung Quốc thuộc bộ 衣.", "Tự nguyên_Xie": "裲 thuộc bộ 衣 (y, quần áo). Nghĩa: áo gile không tay (waistcoat), dùng trong từ ghép 裲襠 (lưỡng đương) — loại trang phục che phần trước-sau thân trên. Không có nguồn Wiktionary hay giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lưỡng đương 裲襠)", "Hạng Tần Suất (Jun Da)": "7471.0", "Tần Suất % (Jun Da)": "99.9984661817", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 兩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤兩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裲", "Unihan_Traditional (Chữ Phồn thể)": "裲", "Pinyin_Xie": "liǎng", "Âm Hán Việt_Xie": "lưỡng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, hầu như chỉ dùng trong từ ghép để chỉ một loại áo khoác cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郈', '{"9000": "7472.0", "Chữ Trung Quốc": "郈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 8 | nét | 郈 | hậu | tượng hình | bộ 邑 (ấp), tên đất ở Sơn Đông | 郈 thuộc bộ 邑 (ấp). Không có dữ liệu Wiktionary cụ thể. Nghĩa: tên đất cổ ở Sơn Đông — liên quan đến nước Lỗ thời Xuân Thu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hậu\": bộ 邑 (đất/ấp) — vùng đất hậu (phía sau) thuộc nước Lỗ cổ đại, gắn với Xuân Thu sử ký. | Gương Hán-Việt | 郈 xuất hiện trong Xuân Thu Tả truyện và sử ký thời Chu. | Mở khoá kiến thức | Biết 郈 giúp nhận diện địa danh cổ bộ 邑 trong văn bản Xuân Thu.", "Tự nguyên_Xie": "Tiểu triện | 郈 thuộc bộ 邑 (ấp). Nghĩa: tên đất cổ ở Sơn Đông, thuộc địa bàn nước Lỗ thời Xuân Thu. Tiểu triện còn lưu qua hanziyuan. Không có nguồn Wiktionary phân tích cấu trúc. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "7472.0", "Tần Suất % (Jun Da)": "99.9984677321", "GavinGrover_Once (Chiết tự trực tiếp)": "后 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰后阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "后", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郈", "Unihan_Traditional (Chữ Phồn thể)": "郈", "Pinyin_Xie": "hòu", "Âm Hán Việt_Xie": "hậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ địa danh cổ hoặc họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鋐', '{"9000": "7473.0", "Chữ Trung Quốc": "鋐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 鋐 | hồng | tượng hình | bộ 金 (kim, kim loại), tên riêng | 鋐 thuộc bộ 金 (kim, kim loại). Không có dữ liệu cấu trúc nội bộ từ Wiktionary hay anchor. Nghĩa: tên riêng (proper name), gắn với tên người.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồng\": bộ 金 (kim loại) — âm hồng vang như tiếng kim loại hùng (hồng) vọng — thường dùng trong tên người. | Gương Hán-Việt | 鋐 chủ yếu dùng làm tên riêng, không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 鋐 giúp nhận ra cấu trúc bộ 金 trong tên người Hán-Việt.", "Tự nguyên_Xie": "鋐 thuộc bộ 金 (kim, kim loại). Chủ yếu dùng làm tên riêng (nhân danh). Không có nguồn Wiktionary hay giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Hùng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 宏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金宏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "𬭎", "Unihan_Traditional (Chữ Phồn thể)": "鋐", "Pinyin_Xie": "hóng", "Âm Hán Việt_Xie": "hồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ một loại đỉnh đồng cổ hoặc tính từ mô tả âm thanh lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瓞', '{"9000": "7474.0", "Chữ Trung Quốc": "瓞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 瓜 | Số nét | 10 | nét | 瓜 | qua | biểu nghĩa | quả dưa | 失 | thất | biểu âm | mất (cho âm dié) | 瓞 = 瓜 (Qua, biểu nghĩa: quả dưa) + 失 (Thất, biểu âm). Chữ hình thanh: 瓜 xác định đây là loại dưa; 失 cung cấp âm đọc. Wiktionary: ''{{Han compound|瓜|失|ls=psc|c1=s|t1=melon|c2=p}}''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệt\": 瓜 (dưa) + 失 (rơi/nhỏ) — quả dưa điệt (nhỏ xíu, vừa rơi khỏi hoa), như cháu chắt tiếp nối gia tộc trong thành ngữ 瓜瓞綿綿. | Gương Hán-Việt | 瓞 xuất hiện trong thành ngữ 瓜瓞綿綿 (qua điệt miên miên) = dây dưa lan rộng — chúc con cháu đông đúc. | Mở khoá kiến thức | Biết 瓞 giúp hiểu thành ngữ 瓜瓞綿綿 trong thơ ca chúc mừng và văn hoá truyền thống.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 瓞 là chữ hình thanh (psc): 瓜 (qua, quả dưa — biểu nghĩa) + 失 (thất — biểu âm). Wiktionary ghi rõ cấu trúc này. Nghĩa: dưa non còn nhỏ, quả dưa vừa đậu. Xuất hiện trong thành ngữ nổi tiếng 瓜瓞綿綿 (qua điệt miên miên) = dưa dây lan rộng, biểu trưng con cháu đông đúc. Có hình tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quả dưa non", "Hạng Tần Suất (Jun Da)": "7474.0", "Tần Suất % (Jun Da)": "99.9984723831", "GavinGrover_Once (Chiết tự trực tiếp)": "瓜 + 失", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴瓜失", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "失", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "瓜", "Unihan_Simplified (Chữ Giản thể)": "瓞", "Unihan_Traditional (Chữ Phồn thể)": "瓞", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường xuất hiện trong văn học cổ làm danh từ để ví von sự sinh sôi nảy nở. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驙', '{"9000": "7475.0", "Chữ Trung Quốc": "驙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 23 | nét | 驙 | chiêm | tượng hình | bộ 馬 (mã, ngựa), loài ngựa cổ | 驙 thuộc bộ 馬 (mã, ngựa). Wiktionary ghi ''{{Han etym}}'' nhưng không phân tích cấu trúc nội bộ. Nghĩa: loại ngựa đặc biệt trong văn bản cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiêm\": bộ 馬 (ngựa) — con ngựa chiêm (ngước nhìn/chiêm ngưỡng) bờm dựng đứng, loài ngựa oai vệ trong cổ thư. | Gương Hán-Việt | Chữ 驙 ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 驙 giúp nhận ra nhóm chữ bộ 馬 chỉ các giống ngựa cổ đại.", "Tự nguyên_Xie": "驙 thuộc bộ 馬 (mã, ngựa). Nghĩa: loại ngựa trong cổ thư. Wiktionary chỉ ghi ''{{Han etym}}'' không có phân tích. Chữ rất hiếm, chủ yếu xuất hiện trong tên ngựa hoặc mô tả kỵ binh cổ đại. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(ngựa)", "Hạng Tần Suất (Jun Da)": "7475.0", "Tần Suất % (Jun Da)": "99.9984739335", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 亶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬亶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "驙", "Unihan_Traditional (Chữ Phồn thể)": "驙", "Pinyin_Xie": "zhān", "Âm Hán Việt_Xie": "triền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Dùng làm danh từ chỉ loại ngựa có màu lông đặc biệt hoặc tính từ tả vẻ bất kham. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鯙', '{"9000": "7476.0", "Chữ Trung Quốc": "鯙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 19 | nét | 鯙 | thuần | tượng hình | bộ 魚 (ngư, cá), cá Scomberomorus sinensis | 鯙 thuộc bộ 魚 (ngư, cá). Không có dữ liệu cấu trúc nội bộ từ Wiktionary hay anchor. Nghĩa: loài cá Scomberomorus sinensis (cá thu gió Trung Hoa).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuần\": bộ 魚 (cá) — con cá thuần (nguyên thuần, chỉ một loài) duy nhất mang tên Scomberomorus sinensis trong vùng biển Hoa Nam. | Gương Hán-Việt | Chữ 鯙 ít xuất hiện trong từ Hán-Việt thông dụng; chủ yếu trong tên loài cá học thuật. | Mở khoá kiến thức | Biết 鯙 giúp nhận ra nhóm chữ bộ 魚 chỉ tên loài cá trong ngư học.", "Tự nguyên_Xie": "鯙 thuộc bộ 魚 (ngư, cá). Nghĩa: Scomberomorus sinensis — cá thu gió Trung Hoa. Không có nguồn Wiktionary hay giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Scomberomorus sinensis", "Hạng Tần Suất (Jun Da)": "7476.0", "Tần Suất % (Jun Da)": "99.9984754839", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 享", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚享", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "享", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鯙", "Unihan_Traditional (Chữ Phồn thể)": "鯙", "Pinyin_Xie": "chún", "Âm Hán Việt_Xie": "thuần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong văn bản cổ hoặc tài liệu sinh học để chỉ một loài cá cụ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眆', '{"9000": "7477.0", "Chữ Trung Quốc": "眆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 9 | nét | 眆 | phảng | tượng hình | mắt nhìn mờ ảo | 眆 là chữ độc thể, chưa phân tích được thành phần rõ ràng; dạng tự thể gần với bộ Mục (目, mắt). Cấu tạo chính xác chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phảng\": bộ Mục (目, mắt) gợi liên tưởng cái nhìn phảng phất, mờ ảo — như mắt nhìn mà không thấy rõ. | Gương Hán-Việt | phảng phất — phảng trong ''phảng phất'' (mơ hồ, thoảng qua) | Mở khoá kiến thức | Biết 眆 (phảng) giúp nhận ra họ hàng bộ Mục: 眼 (nhãn), 看 (khan), 省 (tỉnh).", "Tự nguyên_Xie": "眆 (phảng) chưa có nguồn từ nguyên học thuật. Bộ thủ Mục (目) gợi liên quan đến mắt hay thị giác; nghĩa ''mờ ảo, không rõ ràng'' phù hợp với hình ảnh ánh mắt lờ đờ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "熆", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 方", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "方", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眆", "Unihan_Traditional (Chữ Phồn thể)": "眆", "Pinyin_Xie": "fǎng", "Âm Hán Việt_Xie": "phảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ hành động nhìn thoáng qua hoặc tính từ mô tả trạng thái mờ ảo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睠', '{"9000": "7478.0", "Chữ Trung Quốc": "睠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 13 | nét | 目 | mục | biểu nghĩa | mắt | 卷 | quyển | biểu âm | cuộn | 睠 = 目 (Mục, biểu nghĩa: mắt) + 卷 (Quyển, biểu âm); chữ hình thanh. Phần Mục chỉ liên quan đến thị giác/tình cảm nhìn ngóng; phần Quyển cho âm đọc gần với quyến/juàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyến\": mắt (目) cuộn theo (卷) người thương — cái nhìn quyến luyến, không nỡ rời. | Gương Hán-Việt | quyến luyến — quyến trong ''quyến luyến'' (lưu luyến, không rời được) | Mở khoá kiến thức | Biết 睠 (quyến) mở khoá: 眷 (quyến, yêu thương), 眷顾 (quyến cố), 眷恋 (quyến luyến).", "Tự nguyên_Xie": "睠 (quyến) là chữ hình thanh: 目 (mục, mắt) biểu nghĩa + 卷 (quyển) biểu âm. Wiktionary ghi đây là dị thể của 眷 (quyến, yêu thương, nhớ nhung). Nghĩa gốc: nhìn ngóng, thương yêu, nhớ đến người thân. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "người phụ thuộc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 卷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目卷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睠", "Unihan_Traditional (Chữ Phồn thể)": "睠", "Pinyin_Xie": "juàn", "Âm Hán Việt_Xie": "quyến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Dùng làm động từ thể hiện sự quan tâm, chăm sóc hoặc tình cảm hướng về ai đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞫', '{"9000": "7479.0", "Chữ Trung Quốc": "瞫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 17 | nét | 瞫 | thẩm | tượng hình | nhìn sâu vào | 瞫 là chữ độc thể thuộc bộ Mục (目), chưa có phân tích thành phần học thuật rõ ràng. Dựa trên cấu trúc hình thể, có thể gồm Mục (mắt) kết hợp thành phần khác, nhưng nguồn Wiktionary không cung cấp phân tích hình thanh hay hội ý cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thẩm\": bộ Mục (mắt) + hành động thẩm xét — mắt nhìn thẩm thấu, nhìn sâu vào bên trong. | Gương Hán-Việt | thẩm sát — thẩm trong ''thẩm sát'' (xem xét kỹ càng) | Mở khoá kiến thức | Biết 瞫 (thẩm) liên hệ với 審 (thẩm, xét hỏi) — cùng âm, gợi việc nhìn/xét kỹ.", "Tự nguyên_Xie": "Tiểu triện | 瞫 (thẩm) thuộc bộ Mục (目). Wiktionary chưa cung cấp phân tích từ nguyên cụ thể (rfdef). Nghĩa ''nhìn sâu, nhìn chăm chú'' phù hợp với bộ thủ Mục. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhìn sâu vào", "Hạng Tần Suất (Jun Da)": "7479.0", "Tần Suất % (Jun Da)": "99.9984801349", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 覃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目覃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "覃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞫", "Unihan_Traditional (Chữ Phồn thể)": "瞫", "Pinyin_Xie": "shěn", "Âm Hán Việt_Xie": "thẩm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động quan sát kỹ lưỡng hoặc nhìn lén lút. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矅', '{"9000": "7480.0", "Chữ Trung Quốc": "矅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 19 | nét | 矅 | diệu | tượng hình | sáng rực, chiếu sáng | 矅 là chữ độc thể thuộc bộ Mục (目), chưa có phân tích thành phần học thuật. Hình thể phức tạp, nhiều nét, gợi liên tưởng đến ánh sáng chói chang. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diệu\": ánh sáng diệu kỳ chiếu qua mắt (目) — chữ hiếm gặp chỉ ánh sáng rực rỡ. | Gương Hán-Việt | diệu quang — diệu trong ''diệu quang'' (ánh sáng kỳ diệu) | Mở khoá kiến thức | Biết 矅 (diệu) liên hệ với 耀 (diệu, chiếu sáng) — cùng âm, cùng nghĩa sáng rực.", "Tự nguyên_Xie": "矅 (diệu) thuộc bộ Mục (目), không có nguồn từ nguyên học thuật trong Wiktionary. Nghĩa ''sáng rực, ánh sáng chói'' có thể liên quan đến chữ 耀 (diệu) cùng âm. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "diệu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 翟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目翟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "矅", "Unihan_Traditional (Chữ Phồn thể)": "矅", "Pinyin_Xie": "yào", "Âm Hán Việt_Xie": "diệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả vẻ đẹp lấp lánh hoặc động từ chỉ sự chiếu rọi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碃', '{"9000": "7481.0", "Chữ Trung Quốc": "碃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 13 | nét | 碃 | khánh | tượng hình | loại đá | 碃 là chữ độc thể thuộc bộ Thạch (石, đá), chưa có phân tích thành phần học thuật. Bộ thủ Thạch gợi liên quan đến đá hoặc vật chất khoáng. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khánh\": bộ Thạch (石, đá) — khánh là loại đá đặc biệt, như đá khánh trong nhạc cụ cổ. | Gương Hán-Việt | khánh thạch — khánh trong nhạc cụ 磬 (khánh) làm từ đá | Mở khoá kiến thức | Biết 碃 (khánh) liên hệ với 磬 (khánh, đá khánh nhạc cụ) — cùng âm, cùng bộ thủ.", "Tự nguyên_Xie": "碃 (khánh) thuộc bộ Thạch (石), không có nguồn từ nguyên học thuật trong Wiktionary. Là tên một loại đá, có thể liên quan đến 磬 (khánh, nhạc cụ đá) cùng âm. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại đá)", "Hạng Tần Suất (Jun Da)": "7481.0", "Tần Suất % (Jun Da)": "99.9984832356", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 青", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石青", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "青", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碃", "Unihan_Traditional (Chữ Phồn thể)": "碃", "Pinyin_Xie": "qìng", "Âm Hán Việt_Xie": "thanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại đá tự nhiên có màu sắc đẹp dùng trong trang trí. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禃', '{"9000": "7482.0", "Chữ Trung Quốc": "禃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 12 | nét | 礻 | thị | biểu nghĩa | thần linh, lễ nghi | 直 | trực | biểu âm | thẳng | 禃 = 礻 (Thị, biểu nghĩa: thần linh, lễ nghi) + 直 (Trực, biểu âm); chữ hình thanh. Phần 礻 là dạng rút gọn của 示, chỉ lĩnh vực thần thánh; phần 直 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trực\": bộ Thị (礻, thần linh) + Trực (thẳng) — tấm lòng thẳng thắn trước thần minh, một lòng không thay đổi. | Gương Hán-Việt | trực tâm — trực trong ''trực tâm'' (lòng ngay thẳng) | Mở khoá kiến thức | Biết 禃 (trực) mở khoá: 直 (trực, thẳng), 禃 gợi nhớ phẩm hạnh ngay thẳng trong lễ nghi tôn giáo.", "Tự nguyên_Xie": "禃 (trực) là chữ hình thanh: 礻/示 (thị) biểu nghĩa + 直 (trực) biểu âm. Wiktionary ghi nghĩa ''một lòng, kiên định'' (single-minded, determined), mang tính chất cổ-chuẩn (obs-std). Kết hợp bộ Thị (thần linh) với âm Trực gợi sự kiên định trước thần minh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "禃", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 直", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻直", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "直", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禃", "Unihan_Traditional (Chữ Phồn thể)": "禃", "Pinyin_Xie": "zhí", "Âm Hán Việt_Xie": "trực", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ mô tả thái độ tôn kính hoặc phẩm chất ngay thẳng của con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秔', '{"9000": "7483.0", "Chữ Trung Quốc": "秔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 9 | nét | 秔 | canh | tượng hình | gạo tẻ, lúa không dẻo | 秔 là dị thể của 粳 (canh, lúa gạo tẻ), thuộc bộ Hòa (禾, cây lúa). Cấu tạo chi tiết không được phân tích trong nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"canh\": bộ Hòa (禾, lúa) — canh mễ là gạo tẻ thông thường, loại gạo nấu cơm hằng ngày. | Gương Hán-Việt | canh mễ — canh trong ''canh mễ'' (gạo tẻ), hay 粳米 trong tiếng Hoa hiện đại | Mở khoá kiến thức | Biết 秔 (canh) = 粳 — mở khoá từ 粳米 (jīng mǐ, gạo tẻ), quan trọng trong ẩm thực và y học cổ truyền.", "Tự nguyên_Xie": "Tiểu triện | 秔 (canh) là dị thể cổ của 粳 — chỉ loại lúa gạo tẻ, không dẻo (non-glutinous rice). Wiktionary ghi rõ ''{{zh-see|粳|v}}'' — xem tại mục 粳. Bộ thủ Hòa (禾) khẳng định liên quan đến ngũ cốc/lúa gạo. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "甔", "Hạng Tần Suất (Jun Da)": "5401.0", "Tần Suất % (Jun Da)": "99.953965297", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 亢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾亢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "粳", "Unihan_Traditional (Chữ Phồn thể)": "秔", "Pinyin_Xie": "jīng", "Âm Hán Việt_Xie": "canh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại lúa hạt tròn, thường làm chủ ngữ hoặc tân ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穻', '{"9000": "7484.0", "Chữ Trung Quốc": "穻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 8 | nét | 穻 | áo | tượng hình | sâu thẳm trong lòng đất | 穻 thuộc bộ Huyệt (穴, hố sâu), chưa có phân tích thành phần học thuật rõ ràng. Bộ thủ Huyệt gợi ý nghĩa liên quan đến hang hốc, chỗ sâu. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"áo\": bộ Huyệt (穴, hang sâu) — áo bí, sâu thẳm như hang hốc không thấy đáy. | Gương Hán-Việt | áo bí — áo trong ''áo bí'' (sâu xa bí ẩn), hay 奥 (áo) nghĩa sâu xa | Mở khoá kiến thức | Biết 穻 (áo) liên hệ với 奥 (áo, sâu xa, uyên áo) — cùng âm, cùng nghĩa sâu thẳm.", "Tự nguyên_Xie": "穻 (áo) thuộc bộ Huyệt (穴, hang, hốc sâu), không có nguồn từ nguyên học thuật trong Wiktionary. Nghĩa ''sâu thẳm'' phù hợp với bộ thủ Huyệt. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "绻", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 于", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴于", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "于", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "穻", "Unihan_Traditional (Chữ Phồn thể)": "穻", "Pinyin_Xie": "yū", "Âm Hán Việt_Xie": "áo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường dùng làm tính từ bổ nghĩa cho danh từ để tả không gian sâu thẳm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籐', '{"9000": "7485.0", "Chữ Trung Quốc": "籐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 21 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 滕 | đằng | biểu âm | nước vọt lên | 籐 = 竹 (Trúc, biểu nghĩa: tre trúc) + 滕 (Đằng, biểu âm); chữ hình thanh. Phần Trúc chỉ nghĩa đồ vật làm từ tre; phần Đằng cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đằng\": trúc (竹) vươn đằng xa — cây đằng leo bằng tre, dây leo uốn lượn như cây trúc dài. | Gương Hán-Việt | đằng la — đằng trong ''đằng la'' (dây leo tơi bời); 藤 (đằng) là cây leo phổ biến trong cổ văn | Mở khoá kiến thức | Biết 籐 (đằng) = 藤 — mở khoá: 藤蔓 (đằng mạn, dây leo), 牵籐帶葉 (kéo dây mang lá).", "Tự nguyên_Xie": "籐 (đằng) là chữ hình thanh: 竹 (trúc) biểu nghĩa + 滕 (đằng) biểu âm. Wiktionary ghi đây là dạng chuẩn cổ (obs-std) của 藤 — chỉ cây leo, dây leo (climbing plants, vines, cane). Cũng là họ tên (surname). Nghĩa ''đồ vật bằng tre'' là nghĩa gốc sớm hơn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Cây nho", "Hạng Tần Suất (Jun Da)": "2195.0", "Tần Suất % (Jun Da)": "97.7717951056", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 滕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮滕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "滕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "藤", "Unihan_Traditional (Chữ Phồn thể)": "籐", "Pinyin_Xie": "téng", "Âm Hán Việt_Xie": "đằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các loài cây leo hoặc vật liệu mây tre, làm tân ngữ hoặc chủ ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絏', '{"9000": "7486.0", "Chữ Trung Quốc": "絏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 絏 | duệ | tượng hình | dây trói, dây thừng | 絏 thuộc bộ Mịch (糸, sợi chỉ, dây), chưa có phân tích thành phần học thuật trong nguồn hiện có. Bộ thủ Mịch khẳng định liên quan đến dây thừng, sợi dây.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"duệ\": bộ Mịch (糸, dây) — duệ là sợi dây trói buộc; cũng gợi ''dây'' trong tiếng Việt (slug day-絏). | Gương Hán-Việt | duệ tuyến — duệ gợi dây dợ, sợi buộc trong cổ văn | Mở khoá kiến thức | Biết 絏 (duệ/dây) liên hệ toàn bộ nhóm bộ Mịch: 結 (kết, buộc), 繩 (thằng, dây thừng), 絆 (phán, buộc chân).", "Tự nguyên_Xie": "絏 (duệ) thuộc bộ Mịch (糸, sợi dây). Không có nguồn từ nguyên học thuật trong Wiktionary. Nghĩa ''dây thừng, trói buộc'' phù hợp với bộ thủ. Đọc Hán-Việt là ''duệ'' (dây), phản ánh trong slug day-絏. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhà tù", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 曳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹曳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "絏", "Unihan_Traditional (Chữ Phồn thể)": "絏", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "duệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ dây trói hoặc động từ chỉ hành động trói buộc trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纕', '{"9000": "7487.0", "Chữ Trung Quốc": "纕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 23 | nét | 纕 | nhương | tượng hình | dây đai, dây lưng | 纕 thuộc bộ Mịch (糸, sợi dây), chưa có phân tích thành phần trong Wiktionary. Nghĩa ''đai lưng, dây yên ngựa'' phù hợp với bộ thủ Mịch.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhương\": bộ Mịch (糸, dây) — nhương là sợi đai buộc quanh người; kéo nhương lên là chuẩn bị hành động. | Gương Hán-Việt | nhương tay — nhương gợi hành động kéo, vén lên (攘 nhương trong ''nhương tay áo'') | Mở khoá kiến thức | Biết 纕 (nhương) liên hệ với 攘 (nhương, kéo vén) — cùng âm, dị thể trong nghĩa hành động.", "Tự nguyên_Xie": "Tiểu triện | 纕 (nhương) thuộc bộ Mịch (糸). Wiktionary ghi nghĩa: đai lưng (belt, sash), dây yên ngựa (horse girth), và động từ: kéo tay áo lên (pull up sleeves to expose arms) — dị thể của 攘 (nhương). Có hai cách đọc: xiāng và rǎng. Chưa có phân tích hình thanh/hội ý cụ thể. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "纕", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 襄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹襄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "襄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "𬙋", "Unihan_Traditional (Chữ Phồn thể)": "纕", "Pinyin_Xie": "rǎng", "Âm Hán Việt_Xie": "nhương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Làm danh từ chỉ dây đai trang trí hoặc động từ chỉ việc thắt, đeo dây đai. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翐', '{"9000": "7488.0", "Chữ Trung Quốc": "翐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 11 | nét | 翐 | chí | tượng hình | chim bay vấp ngã | 翐 thuộc bộ Vũ (羽, lông vũ), chưa có phân tích thành phần học thuật. Bộ thủ Vũ gợi liên quan đến chim, lông, bay. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chí\": bộ Vũ (羽, lông vũ) — chí là chim bay vấp, loạng choạng; gợi ''chí'' như chí hướng vươn lên dù vấp ngã. | Gương Hán-Việt | chí hướng — chí trong ''chí hướng'', nhắc nhở vượt qua vấp ngã | Mở khoá kiến thức | Biết 翐 (chí) liên hệ bộ Vũ: 翻 (phiên), 翼 (dực, cánh), 翅 (sí, cánh).", "Tự nguyên_Xie": "翐 (chí) thuộc bộ Vũ (羽, lông vũ), không có nguồn từ nguyên học thuật trong Wiktionary. Nghĩa gốc liên quan đến chim vỗ cánh hoặc bay loạng choạng. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Lữ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "羽 + 失", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰羽失", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "失", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翐", "Unihan_Traditional (Chữ Phồn thể)": "翐", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "chí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ miêu tả tư thế bay của chim hoặc kết hợp thành từ láy. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耈', '{"9000": "7489.0", "Chữ Trung Quốc": "耈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 老 | Số nét | 11 | nét | 耈 | cấu | tượng hình | tuổi già lão | 耈 thuộc bộ Lão (老, người già), chưa có phân tích thành phần học thuật. Bộ thủ Lão khẳng định liên quan đến tuổi già. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cấu\": bộ Lão (老, già) — cấu chỉ người già lão, tuổi tác cao; liên hệ với ''cẩu'' (chó già) trong truyền thống nói về tuổi. | Gương Hán-Việt | cấu lão — cấu trong ''cấu lão'' (người rất già, đầy tuổi tác) | Mở khoá kiến thức | Biết 耈 (cấu) trong nhóm bộ Lão: 耄 (mạo, rất già), 耋 (điệt, rất già), 耆 (kỳ, 60 tuổi).", "Tự nguyên_Xie": "耈 (cấu) thuộc bộ Lão (老, già), không có nguồn từ nguyên học thuật trong Wiktionary. Nghĩa ''tuổi già lão'' phù hợp với bộ thủ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "muỗng", "Hạng Tần Suất (Jun Da)": "7489.0", "Tần Suất % (Jun Da)": "99.9984971888", "GavinGrover_Once (Chiết tự trực tiếp)": "老 + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱老句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "老", "Unihan_Simplified (Chữ Giản thể)": "耈", "Unihan_Traditional (Chữ Phồn thể)": "耈", "Pinyin_Xie": "gǒu", "Âm Hán Việt_Xie": "cấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Dùng làm tính từ chỉ sự già cả hoặc danh từ chỉ người cao tuổi trong văn cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耎', '{"9000": "7490.0", "Chữ Trung Quốc": "耎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 而 | Số nét | 9 | nét | 耎 | nhuyễn | tượng hình | mềm, dẻo, yếu | 耎 là chữ độc thể thuộc bộ Nhi (而). Wiktionary ghi đây vốn cùng chữ với 需 (nhu), hai chữ phân kỳ từ thời Hán. Cấu trúc gốc chưa được phân tích rõ hơn trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhuyễn\": chữ xưa cùng gốc với 需 (nhu, cần) — nhuyễn là mềm yếu, cần được nâng đỡ; như đất nhuyễn cần được vun bón. | Gương Hán-Việt | nhuyễn nhược — nhuyễn trong ''nhuyễn nhược'' (mềm yếu, thiếu cứng rắn) | Mở khoá kiến thức | Biết 耎 (nhuyễn) = 軟 (nhuyễn, mềm) — cùng âm, cùng nghĩa, giúp đọc cổ văn y học và triết học.", "Tự nguyên_Xie": "耎 (nhuyễn) vốn là một chữ với 需 (nhu, cần thiết) — hai chữ phân kỳ trong thời Hán theo Wiktionary. Nghĩa ''mềm, dẻo, yếu ớt'' phát triển sau khi tách khỏi 需. Liên hệ với 軟 (nhuyễn) cùng âm, cùng nghĩa mềm. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mềm, dẻo", "Hạng Tần Suất (Jun Da)": "7490.0", "Tần Suất % (Jun Da)": "99.9984987392", "GavinGrover_Once (Chiết tự trực tiếp)": "而 + 大", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱而大", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "大", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "而", "Unihan_Simplified (Chữ Giản thể)": "耎", "Unihan_Traditional (Chữ Phồn thể)": "耎", "Pinyin_Xie": "ruǎn", "Âm Hán Việt_Xie": "nhuyễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Làm tính từ miêu tả tính chất mềm dẻo của vật thể hoặc sự yếu đuối của con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脷', '{"9000": "7491.0", "Chữ Trung Quốc": "脷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | ⺼ | nhục | biểu nghĩa | thịt, thân thể | 利 | lợi | biểu âm | sắc bén, lợi ích | 脷 = ⺼/肉 (Nhục, biểu nghĩa: thịt, bộ phận cơ thể) + 利 (Lợi, biểu âm); chữ hình thanh. Phần Nhục chỉ bộ phận cơ thể; phần Lợi cho âm đọc. Chuyên biệt hoá từ 利.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lợi\": thịt (⺼) sắc bén (利) — lợi là cái lưỡi linh hoạt như lưỡi dao, bộ phận thịt sắc bén nhất trong miệng. | Gương Hán-Việt | lợi khẩu — lợi trong ''lợi khẩu'' (ăn nói sắc bén, lưỡi như dao) | Mở khoá kiến thức | Biết 脷 (lợi) = lưỡi súc vật trong tiếng Quảng Đông; liên hệ với 舌 (thiệt, lưỡi) trong tiếng Hoa phổ thông.", "Tự nguyên_Xie": "脷 (lợi) là chữ hình thanh: ⺼/肉 (nhục) biểu nghĩa + 利 (lợi) biểu âm. Wiktionary ghi đây là chữ chuyên biệt hoá của 利 (lợi), dùng trong tiếng Quảng Đông chỉ ''lưỡi (của súc vật)''. Không có âm cổ Hán (no_och2). Dùng chủ yếu trong tiếng Việt Quảng Đông. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(gia súc) lưỡi (tiếng Quảng Đông)", "Hạng Tần Suất (Jun Da)": "7491.0", "Tần Suất % (Jun Da)": "99.9985002895", "GavinGrover_Once (Chiết tự trực tiếp)": "𣍩 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰𣍩刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𣍩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "脷", "Unihan_Traditional (Chữ Phồn thể)": "脷", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là danh từ chỉ bộ phận cơ thể, chủ yếu dùng trong phương ngôn Quảng Đông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艐', '{"9000": "7492.0", "Chữ Trung Quốc": "艐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 15 | nét | 艐 | khắc | tượng hình | tàu thuyền mắc cạn | 艐 thuộc bộ Chu (舟, thuyền), chưa có phân tích thành phần học thuật chi tiết. Bộ thủ Chu khẳng định liên quan đến thuyền, giao thông đường thủy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khắc\": bộ Chu (舟, thuyền) — khắc là con thuyền bị khắc chặt vào bờ cát, mắc cạn không đi được. | Gương Hán-Việt | khắc phục — gợi hình ảnh vượt qua khó khăn như thuyền mắc cạn phải thoát ra | Mở khoá kiến thức | Biết 艐 (khắc) trong bộ Chu: 船 (thuyền), 航 (hàng, đi biển), 艇 (đĩnh, thuyền nhỏ).", "Tự nguyên_Xie": "艐 (khắc) thuộc bộ Chu (舟, thuyền). Wiktionary ghi nghĩa ''tàu thuyền mắc cạn hoặc bị giạt vào bờ'' (ship stranded or run aground). Có nhiều cách đọc: kè, zōng trong tiếng Hoa. Chưa có phân tích từ nguyên cụ thể. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghiêm khắc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "艐", "Unihan_Traditional (Chữ Phồn thể)": "艐", "Pinyin_Xie": "kè", "Âm Hán Việt_Xie": "khắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ trạng thái thuyền bị mắc cạn hoặc hành động đi đến một nơi nào đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苙', '{"9000": "7493.0", "Chữ Trung Quốc": "苙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 苙 | lập | tượng hình | chuồng nhốt lợn, cũi | 苙 thuộc bộ Thảo (艸/艹, cỏ cây), chưa có phân tích thành phần học thuật chi tiết. Wiktionary chưa định nghĩa rõ (rfdef). Bộ thủ gợi chuồng trại làm từ cây cỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lập\": bộ Thảo (艸, cỏ cây) — lập là chuồng nhốt thú bằng tre cây, cũi làm từ thực vật. | Gương Hán-Việt | lập cũi — lập gợi hình ảnh dựng đứng, lập cũi nhốt thú vật | Mở khoá kiến thức | Biết 苙 (lập) thuộc bộ Thảo — nhóm chữ chỉ thực vật và đồ vật làm từ cây cỏ.", "Tự nguyên_Xie": "苙 (lập) thuộc bộ Thảo (艸). Wiktionary chỉ ghi phát âm mà không định nghĩa rõ (rfdef). Slug rop-苙 ghi âm Hán-Việt là ''rợp'', nhưng học thuật truyền thống đọc là ''lập'' (lì trong tiếng Hoa). Nghĩa liên quan đến chuồng trại hoặc rợp bóng cây. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chuồng lợn; cỏ lập, cỏ bạch nhĩ", "Hạng Tần Suất (Jun Da)": "7493.0", "Tần Suất % (Jun Da)": "99.998506491", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 立", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹立", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "立", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苙", "Unihan_Traditional (Chữ Phồn thể)": "苙", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lập", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ đứng sau động từ chỉ hoạt động chăn nuôi hoặc làm tên một loại cỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葹', '{"9000": "7494.0", "Chữ Trung Quốc": "葹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葹 | thi | tượng hình | cây ké, xương rồng gai | 葹 thuộc bộ Thảo (艸, cỏ cây), chưa có phân tích thành phần học thuật. Là tên một loại cây — cây ké (cocklebur, Xanthium sibiricum) — loài cỏ dại có gai thường gặp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thi\": bộ Thảo (艸) — thi là cây ké cỏ dại có gai, giống như một bài thơ (thi) gai góc, ấn tượng khó quên. | Gương Hán-Việt | thi thảo — thi trong tên cây cỏ cổ văn; gợi 詩 (thi, thơ) cùng âm | Mở khoá kiến thức | Biết 葹 (thi) = cây ké — loài cỏ dại xuất hiện trong thơ ca Sở Từ và y học cổ truyền.", "Tự nguyên_Xie": "葹 (thi) thuộc bộ Thảo (艸). Wiktionary ghi đây là tên cây ké đầu ngựa (cocklebur, đặc biệt là Xanthium sibiricum). Đồng nghĩa: 蒼耳, 卷耳, 菤耳, 葈耳, 枲耳. Chưa có phân tích từ nguyên cụ thể. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: quyển thi 菤葹)", "Hạng Tần Suất (Jun Da)": "7494.0", "Tần Suất % (Jun Da)": "99.9985080413", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 施", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹施", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "施", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葹", "Unihan_Traditional (Chữ Phồn thể)": "葹", "Pinyin_Xie": "shī", "Âm Hán Việt_Xie": "thi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong danh từ ghép quyển thi để chỉ một loại cây thân thảo cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓂', '{"9000": "7495.0", "Chữ Trung Quốc": "蓂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 艸 | tháu | biểu nghĩa | cỏ cây | 冥 | minh | biểu âm | tối tăm, sâu thẳm | 蓂 = 艸 (Thảo/Tháu, biểu nghĩa: cỏ cây) + 冥 (Minh, biểu âm); chữ hình thanh. Phần Thảo chỉ loài thực vật; phần Minh cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"minh\": cỏ (艸) tối tăm sâu thẳm (冥) — minh là loài cỏ thần bí, nở hoa theo tháng âm lịch; cây minh giáp báo hiệu ngày tháng. | Gương Hán-Việt | minh giáp — minh trong 蓂莢 (minh giáp), loài cỏ thần thoại báo ngày trong cung đình cổ | Mở khoá kiến thức | Biết 蓂 (minh) = 蓂莢 — cây lịch thiêng liêng trong cổ văn, giúp đọc thơ phú triều đình.", "Tự nguyên_Xie": "Tiểu triện | 蓂 (minh) là chữ hình thanh: 艸 (thảo) biểu nghĩa + 冥 (minh) biểu âm. Wiktionary không định nghĩa chi tiết ngoài cấu trúc hình thanh. Nghĩa ''nơi lành, cây lành'' — trong từ ghép 蓂莢 (minh giáp) là tên loài cây huyền thoại trong cổ văn Trung Quốc, nở hoa theo ngày trong tháng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: minh giáp 蓂莢)", "Hạng Tần Suất (Jun Da)": "7495.0", "Tần Suất % (Jun Da)": "99.9985095917", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 冥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹冥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓂", "Unihan_Traditional (Chữ Phồn thể)": "蓂", "Pinyin_Xie": "míng", "Âm Hán Việt_Xie": "minh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong cụm từ minh giáp để chỉ loài cỏ thần thoại biểu thị ngày tháng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔲', '{"9000": "7496.0", "Chữ Trung Quốc": "蔲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 蔲 | khấu | tượng hình | nhục đậu khấu | 蔲 thuộc bộ Thảo (艸, cỏ cây), chưa có phân tích thành phần học thuật. Là tên một loài thực vật gia vị — nhục đậu khấu (nutmeg). Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khấu\": bộ Thảo (艸) — khấu là gia vị thực vật quý; 豆蔲 (đậu khấu) là loài gia vị nổi tiếng trong y học và ẩm thực. | Gương Hán-Việt | đậu khấu — khấu trong ''豆蔲 đậu khấu'' (cardamom/nutmeg), gia vị y học cổ truyền | Mở khoá kiến thức | Biết 蔲 (khấu) trong từ 豆蔲 — mở khoá thế giới gia vị y học cổ truyền: 草蔻, 白蔻, 肉蔻.", "Tự nguyên_Xie": "蔲 (khấu) thuộc bộ Thảo (艸), không có nguồn từ nguyên học thuật trong Wiktionary. Nghĩa ''nhục đậu khấu'' (nutmeg) phù hợp với bộ thủ thực vật. Thường thấy trong danh xưng 豆蔲/豆蔻 (đậu khấu). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蔲", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蔲", "Unihan_Traditional (Chữ Phồn thể)": "蔲", "Pinyin_Xie": "kòu", "Âm Hán Việt_Xie": "khấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép đậu khấu để chỉ một loại cây thảo dược hoặc tuổi trẻ của thiếu nữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薋', '{"9000": "7497.0", "Chữ Trung Quốc": "薋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 薋 | tư | tượng hình | cỏ dại um tùm | 薋 thuộc bộ Thảo (艸, cỏ cây), chưa có phân tích thành phần học thuật. Wiktionary chưa định nghĩa (rfdef). Nghĩa ''cỏ dại um tùm'' phù hợp với bộ thủ Thảo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": bộ Thảo (艸) um tùm — tư là cỏ dại rậm rịt, mọc lan tràn; gợi ''tư mao'' (cỏ um tùm che phủ). | Gương Hán-Việt | tư thảo — tư trong ''tư thảo'' (cỏ dại um tùm, cỏ mọc hoang) | Mở khoá kiến thức | Biết 薋 (tư) trong thơ Sở Từ — loài cỏ dại chỉ sự hoang vu, bỏ bê của vườn tược.", "Tự nguyên_Xie": "薋 (tư) thuộc bộ Thảo (艸). Wiktionary chưa cung cấp định nghĩa cụ thể (rfdef). Nghĩa ''cỏ dại um tùm'' phù hợp bộ thủ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ dại um tùm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 資", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹資", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "資", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薋", "Unihan_Traditional (Chữ Phồn thể)": "薋", "Pinyin_Xie": "cí", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ miêu tả trạng thái cỏ mọc hoang rậm rạp hoặc làm danh từ chỉ cỏ dại. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛷', '{"9000": "7498.0", "Chữ Trung Quốc": "蛷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 虫 | trùng | biểu nghĩa | rắn, côn trùng | 求 | cầu | biểu âm | cầu, tìm kiếm | 蛷 = 虫 (Trùng, biểu nghĩa: rắn, côn trùng) + 求 (Cầu, biểu âm); chữ hình thanh. Phần Trùng chỉ loài côn trùng; phần Cầu cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cầu\": trùng (虫) cầu cứu — con 蛷 trong 蛷螋 là loài côn trùng nhỏ, cuộn tròn như đang cầu xin. | Gương Hán-Việt | cầu trùng — cầu trong tên loài 蛷螋 (loài rết tai) | Mở khoá kiến thức | Biết 蛷 (cầu) trong từ 蛷螋 — giúp đọc tên côn trùng trong cổ văn và sách y học tự nhiên.", "Tự nguyên_Xie": "蛷 (cầu) là chữ hình thanh: 虫 (trùng, rắn/côn trùng) biểu nghĩa + 求 (cầu) biểu âm. Wiktionary ghi chỉ dùng trong từ ghép 蛷螋 (cầu sưu) — tên loài côn trùng (earwig, con rết tai). Nghĩa độc lập chưa rõ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蛷", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 求", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫求", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "求", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛷", "Unihan_Traditional (Chữ Phồn thể)": "蛷", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "cầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại côn trùng nhiều chân giống như con cuốn chiếu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜑', '{"9000": "7499.0", "Chữ Trung Quốc": "蜑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 延 | diên | biểu âm | kéo dài | 虫 | trùng | biểu nghĩa | rắn | 蜑 = 延 (Diên, biểu âm) + 虫 (Trùng, biểu nghĩa: rắn); chữ hình thanh. Phần Trùng gợi nghĩa ban đầu liên quan đến rắn/nước; phần Diên cho âm đọc. Về sau chỉ tộc người Đản sống trên thuyền.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đản\": trùng (虫, rắn nước) kéo dài (延) trên sóng — đản là người Tanka sống trên thuyền, dọc biển dài dọc sông. | Gương Hán-Việt | đản dân — đản trong ''蜑民 đản dân'' (người Tanka, tộc ngư dân thuyền chài) | Mở khoá kiến thức | Biết 蜑 (đản) = 蜑家 — tộc ngư dân nổi tiếng Quảng Đông, giúp đọc sử Việt và Hoa Nam.", "Tự nguyên_Xie": "蜑 (đản) là chữ hình thanh: 延 (diên) biểu âm + 虫 (trùng, rắn) biểu nghĩa. Wiktionary ghi nghĩa chính: người Tanka (蜑家) — tộc người sống trên thuyền ở miền nam Trung Quốc và Việt Nam. Wiktionary dẫn nguồn 嶺外代答: ''Người Đản lấy thuyền làm nhà, sống trên biển''. Cũng là dị thể của 蛋 (quả trứng). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một tộc Mán ở phương Nam (Trung Quốc)", "Hạng Tần Suất (Jun Da)": "7499.0", "Tần Suất % (Jun Da)": "99.9985157931", "GavinGrover_Once (Chiết tự trực tiếp)": "延 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱延虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "延", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜑", "Unihan_Traditional (Chữ Phồn thể)": "蜑", "Pinyin_Xie": "dàn", "Âm Hán Việt_Xie": "đản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một tộc người sống bằng nghề chài lưới trên sông nước ở miền Nam Trung Quốc cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衂', '{"9000": "7500.0", "Chữ Trung Quốc": "衂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 血 | Số nét | 9 | nét | 衂 | nục | tượng hình | chảy máu cam, bại trận | 衂 thuộc bộ Huyết (血, máu), chưa có phân tích thành phần học thuật trong nguồn hiện có. Bộ thủ Huyết khẳng định liên quan đến máu. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nục\": bộ Huyết (血, máu) — nục là máu chảy ra từ mũi; ''chảy máu nục'' là thành ngữ tiếng Việt. | Gương Hán-Việt | nục huyết — nục trong ''chảy máu nục'' (máu cam, chảy máu mũi) | Mở khoá kiến thức | Biết 衂 (nục) liên hệ với 衄 (nục, phổ biến hơn) — cùng nghĩa chảy máu cam, giúp đọc sách y học cổ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 衂 (nục) thuộc bộ Huyết (血, máu). Không có nguồn từ nguyên học thuật trong Wiktionary. Nghĩa ''chảy máu cam, bại trận'' phù hợp với bộ thủ Huyết. Chưa có nguồn học thuật. Có hình tiểu triện và lục thư thông. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đổ máu cam", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "血 + 刃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰血刃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "血", "Unihan_Simplified (Chữ Giản thể)": "衂", "Unihan_Traditional (Chữ Phồn thể)": "衂", "Pinyin_Xie": "niù", "Âm Hán Việt_Xie": "nục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ hành động chảy máu mũi hoặc ẩn dụ cho sự thất bại, tổn hao lực lượng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衋', '{"9000": "7501.0", "Chữ Trung Quốc": "衋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 血 | Số nét | 24 | nét | 聿 | duật | biểu nghĩa | bút, dụng cụ viết | 皕 | bích | biểu âm | 200 | 血 | huyết | biểu nghĩa | máu | 衋 = 聿 (Duật, biểu nghĩa) + 皕 (Bích, biểu âm) + 血 (Huyết, biểu nghĩa: máu); chữ hình thanh phức tạp. Hai thành phần biểu nghĩa (聿 + 血) cùng với âm 皕 tạo nên chữ chỉ nỗi đau thương xót.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hức\": máu (血) và bút (聿) cùng rớt xuống — hức là nỗi đau sâu thẳm đến mức máu trào ra; bi thương tột cùng. | Gương Hán-Việt | hức thương — hức trong ''hức thương'' (đau đớn thương xót, bi thương) | Mở khoá kiến thức | Biết 衋 (hức) trong Thượng Thư — giúp đọc văn bản kinh điển triều đình về nỗi khổ nhân dân.", "Tự nguyên_Xie": "衋 (hức) là chữ hình thanh: 聿 (duật) + 血 (huyết, máu) biểu nghĩa + 皕 (bích) biểu âm. Wiktionary ghi nghĩa ''đau xót, bi thương'' (sorrowful, desolate), đây là chữ cổ và hiếm. Dẫn chứng từ Thượng Thư: ''Dân đều đau xót thương tâm''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đau xót, đau đớn", "Hạng Tần Suất (Jun Da)": "7501.0", "Tần Suất % (Jun Da)": "99.9985188938", "GavinGrover_Once (Chiết tự trực tiếp)": "聿 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱聿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "衋", "Unihan_Traditional (Chữ Phồn thể)": "衋", "Pinyin_Xie": "xì", "Âm Hán Việt_Xie": "hực", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả tâm trạng vô cùng đau đớn, xót xa trước cảnh tượng bi thảm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袿', '{"9000": "7502.0", "Chữ Trung Quốc": "袿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 11 | nét | 袿 | khuê | tượng hình | áo cánh dài, áo choàng phụ nữ | 袿 thuộc bộ Y (衣, áo), chưa có phân tích thành phần học thuật chi tiết. Wiktionary chưa định nghĩa rõ (rfdef). Bộ thủ Y khẳng định đây là loại y phục.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuê\": bộ Y (衣, áo) — khuê là áo choàng dài dành cho phụ nữ quý tộc; khuê phòng là nơi mặc những tà áo như vậy. | Gương Hán-Việt | khuê phòng — khuê trong ''khuê phòng'' (phòng của phụ nữ), gợi áo khuê dài thướt tha | Mở khoá kiến thức | Biết 袿 (khuê) trong y phục cổ đại — giúp đọc thơ tả vẻ đẹp phụ nữ quý tộc thời Hán.", "Tự nguyên_Xie": "袿 (khuê) thuộc bộ Y (衣, áo). Wiktionary chỉ ghi phát âm guī mà không định nghĩa (rfdef). Nghĩa ''áo cánh dài của phụ nữ, áo choàng'' phổ biến trong tài liệu học thuật khác về y phục cổ đại. Chưa có nguồn Wiktionary đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo cánh dài, áo choàng của đàn bà", "Hạng Tần Suất (Jun Da)": "7502.0", "Tần Suất % (Jun Da)": "99.9985204442", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 圭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤圭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袿", "Unihan_Traditional (Chữ Phồn thể)": "袿", "Pinyin_Xie": "guī", "Âm Hán Việt_Xie": "khuê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loại áo dài trang trọng của phụ nữ quý tộc thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('誳', '{"9000": "7503.0", "Chữ Trung Quốc": "誳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 15 | nét | 誳 | quật | tượng hình | bẻ cong lời nói, nói vòng vo | 誳 thuộc bộ Ngôn (言, lời nói), chưa có phân tích thành phần học thuật. Bộ thủ Ngôn khẳng định liên quan đến lời nói. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quật\": bộ Ngôn (言, lời) — quật là lời nói bẻ cong, uốn lượn; giống cành cây quật lại (屈) trong lời nói. | Gương Hán-Việt | quật khúc — quật trong ''quật khúc'' (nói vòng vo, uốn lượn không thẳng) | Mở khoá kiến thức | Biết 誳 (quật) liên hệ với 屈 (khuất/quật, bẻ cong) — cùng âm, gợi hành động uốn cong.", "Tự nguyên_Xie": "誳 (quật) thuộc bộ Ngôn (言). Không có nguồn từ nguyên học thuật trong Wiktionary. Nghĩa ''bẻ cong lời nói, nói không thẳng thắn'' phù hợp với bộ thủ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "誳", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 屈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言屈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "誳", "Unihan_Traditional (Chữ Phồn thể)": "誳", "Pinyin_Xie": "qū", "Âm Hán Việt_Xie": "quật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ để miêu tả trạng thái quanh co, uốn khúc hoặc không ngay thẳng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('諆', '{"9000": "7504.0", "Chữ Trung Quốc": "諆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 15 | nét | 諆 | khê | tượng hình | lừa dối, mưu tính | 諆 thuộc bộ Ngôn (言, lời nói), chưa có phân tích thành phần học thuật. Bộ thủ Ngôn liên quan đến lời nói gian dối. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khê\": bộ Ngôn (言, lời) — khê là lời lừa dối mưu mô; như 欺 (khi, lừa) cùng âm. | Gương Hán-Việt | khê trá — khê trong ''khê trá'' (lừa dối, mưu mô xảo trá) | Mở khoá kiến thức | Biết 諆 (khê) liên hệ với 欺 (khi, lừa dối) — cùng âm, cùng hướng nghĩa.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | 諆 (khê) thuộc bộ Ngôn (言). Wiktionary chưa định nghĩa (rfdef). Nghĩa ''lừa dối, mưu hoạch'' ghi trong dữ liệu Mongo. Có hình từ kim văn, đại triện, tiểu triện. Chưa có phân tích cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lừa dối; mưu hoạch, mưu tính", "Hạng Tần Suất (Jun Da)": "7504.0", "Tần Suất % (Jun Da)": "99.9985281959", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 其", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言其", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "其", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "諆", "Unihan_Traditional (Chữ Phồn thể)": "諆", "Pinyin_Xie": "qī", "Âm Hán Việt_Xie": "khi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước đối tượng bị lừa dối hoặc làm vị ngữ trong câu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讱', '{"9000": "7505.0", "Chữ Trung Quốc": "讱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 5 | nét | 讱 | nhẫn | tượng hình | nói thận trọng, ăn nói dè dặt | 讱 là dạng giản thể thuộc bộ Ngôn (讠, giản), chữ phồn thể là 訒. Chưa có phân tích thành phần học thuật chi tiết trong nguồn hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhẫn\": bộ Ngôn (讠, lời) — nhẫn là nhẫn nại trong lời nói, ăn nói dè dặt; Khổng Tử dạy người nhân thì nói thận trọng. | Gương Hán-Việt | nhẫn khẩu — nhẫn trong ''nhẫn khẩu'' (nhẫn nại lời nói, không vội mở miệng) | Mở khoá kiến thức | Biết 讱 (nhẫn) từ Luận Ngữ — mở khoá triết học Nho gia: 仁者其言也訒 (người nhân nói thận trọng).", "Tự nguyên_Xie": "Đại triện | 讱 (nhẫn) là dạng giản thể của 訒, thuộc bộ Ngôn. Wiktionary dẫn Luận Ngữ: Khổng Tử nói ''người nhân đức thì nói thận trọng chậm rãi''. Nghĩa: chậm và thận trọng trong lời nói (slow and cautious in speech). Có hình đại triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói thận trọng", "Hạng Tần Suất (Jun Da)": "7505.0", "Tần Suất % (Jun Da)": "99.9985297463", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 刃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠刃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "讱", "Unihan_Traditional (Chữ Phồn thể)": "訒", "Pinyin_Xie": "rèn", "Âm Hán Việt_Xie": "nhẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả thái độ nói năng dè dặt hoặc làm động từ chỉ việc nói khó khăn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軃', '{"9000": "7506.0", "Chữ Trung Quốc": "軃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 身 | Số nét | 19 | nét | 軃 | đoả | tượng hình | thân người rủ xuống, lảo đảo | 軃 thuộc bộ Thân (身, thân thể), chưa có phân tích thành phần học thuật. Là dị thể của 亸 (đoả) — chỉ trạng thái thân thể rũ xuống, lảo đảo. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đoả\": bộ Thân (身, thân thể) — đoả là thân người rũ xuống mềm oặt; như bông hoa (朵, đoả) rủ cánh. | Gương Hán-Việt | đoả thể — đoả gợi thân thể mềm rũ, không đứng thẳng được | Mở khoá kiến thức | Biết 軃 (đoả) = 亸 — dị thể cổ chỉ trạng thái rũ xuống; liên hệ với 朵 (đoả, bông hoa rủ xuống).", "Tự nguyên_Xie": "軃 (đoả) thuộc bộ Thân (身), không có nguồn từ nguyên học thuật trong Wiktionary. Là dị thể/cổ tự của 亸 (duǒ) — nghĩa thân thể rũ xuống, lảo đảo, mềm oặt. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem \"亸\"", "Hạng Tần Suất (Jun Da)": "7506.0", "Tần Suất % (Jun Da)": "99.9985312966", "GavinGrover_Once (Chiết tự trực tiếp)": "身 + 單", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰身單", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "單", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "身", "Unihan_Simplified (Chữ Giản thể)": "軃", "Unihan_Traditional (Chữ Phồn thể)": "軃", "Pinyin_Xie": "duǒ", "Âm Hán Việt_Xie": "đả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ miêu tả trạng thái rủ xuống của tóc, cành cây hoặc tà áo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轝', '{"9000": "7507.0", "Chữ Trung Quốc": "轝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 20 | nét | 轝 | dư | tượng hình | xe, kiệu chở người | 轝 thuộc bộ Xa (車, xe), chưa có phân tích thành phần học thuật. Nghĩa ''xe chở đồ, trời đất'' liên quan đến phương tiện vận chuyển. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dư\": bộ Xa (車, xe) — dư là xe kiệu sang trọng; ''dư luận'' gốc từ dư = xe chở — mọi người cùng đẩy xe tạo ra dư luận. | Gương Hán-Việt | dư luận — dư trong ''舆論 dư luận'' (ý kiến công chúng, chữ thông dụng là 輿) | Mở khoá kiến thức | Biết 轝 (dư) = 輿 (dư, xe kiệu) — mở khoá: 輿論 (dư luận), 轎輿 (kiệu xe), 天輿 (trời đất).", "Tự nguyên_Xie": "轝 (dư) thuộc bộ Xa (車, xe). Không có nguồn từ nguyên học thuật trong Wiktionary. Nghĩa ''xe, kiệu'' gắn với bộ Xa. Liên hệ với 輿 (dư, xe kiệu) — cùng âm, cùng nghĩa. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xe chở đồ; trời đất", "Hạng Tần Suất (Jun Da)": "7507.0", "Tần Suất % (Jun Da)": "99.998532847", "GavinGrover_Once (Chiết tự trực tiếp)": "與 + 車", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱與車", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "與", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "轝", "Unihan_Traditional (Chữ Phồn thể)": "轝", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "dư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ các loại xe kiệu thời xưa hoặc làm động từ với nghĩa nâng đỡ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郀', '{"9000": "7508.0", "Chữ Trung Quốc": "郀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 8 | nét | 郀 | khô | tượng hình | địa danh cổ | 郀 thuộc bộ Ấp (邑/⻏, thành ấp), chưa có phân tích thành phần học thuật chi tiết. Bộ Ấp khẳng định đây là tên địa danh hoặc đơn vị hành chính cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khô\": bộ Ấp (邑, ấp thành) — khô là tên đất cổ, như 郀首 (vùng đất đầu nước); liên hệ với 枯 (khô héo) cùng âm. | Gương Hán-Việt | khô thủ — khô trong 郀首 (địa danh cổ Trung Quốc) | Mở khoá kiến thức | Biết 郀 (khô) giúp đọc sử ký địa lý cổ Trung Quốc về các tiểu quốc thời Xuân Thu.", "Tự nguyên_Xie": "郀 (khô) thuộc bộ Ấp (邑). Wiktionary ghi chỉ dùng trong tên địa danh (zh-used2|p), có trong từ ghép 郀首 (Khô Thủ — địa danh cổ). Không có phân tích từ nguyên cụ thể. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "郀", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "夸 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰夸阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郀", "Unihan_Traditional (Chữ Phồn thể)": "郀", "Pinyin_Xie": "kū", "Âm Hán Việt_Xie": "khô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng chỉ địa danh cổ trong các tài liệu lịch sử. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鉐', '{"9000": "7509.0", "Chữ Trung Quốc": "鉐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 鉐 | thạch | tượng hình | hợp kim đồng vàng cổ | 鉐 thuộc bộ Kim (金, kim loại), chưa có phân tích thành phần học thuật chi tiết. Bộ thủ Kim khẳng định liên quan đến kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thạch\": bộ Kim (金, kim loại) + âm thạch — kết hợp kim loại với đá gợi loại hợp kim cứng như đá; 鍮鉐 là hợp kim đồng vàng quý. | Gương Hán-Việt | thạch kim — thạch trong ''thạch kim'' (kim loại cứng như đá); 鍮鉐 là đồng thau cổ | Mở khoá kiến thức | Biết 鉐 (thạch) trong từ 鍮鉐 — giúp đọc sách kim loại học và công nghệ cổ đại Trung Quốc.", "Tự nguyên_Xie": "鉐 (thạch) thuộc bộ Kim (金). Wiktionary ghi hai cách đọc: (1) shí — chỉ dùng trong 鍮鉐 (thoa thạch, loại đồng vàng cổ); (2) zú — là họ tên. Chưa có phân tích từ nguyên cụ thể. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鉉", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "石", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鉐", "Unihan_Traditional (Chữ Phồn thể)": "鉐", "Pinyin_Xie": "shí", "Âm Hán Việt_Xie": "thạch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loại hợp kim đồng hoặc khoáng vật trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鍧', '{"9000": "7510.0", "Chữ Trung Quốc": "鍧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 鍧 | hoành | tượng hình | chữ kim loại phát tiếng vang lớn | 鍧 là chữ độc thể thuộc bộ 金 (kim loại). Wiktionary không cung cấp cấu trúc nội tại; chữ tạo muộn, cấu tạo chưa rõ hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoành\": chữ bộ 金 (kim loại) gợi tiếng vang dội — hình dung thanh âm 鏗鍧 của kiếm chạm nhau. | Gương Hán-Việt | hoành — ít dùng độc lập trong tiếng Việt Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鍧 giúp nhận ra từ cổ văn 鏗鍧 (keng hoành) — âm thanh kim loại vang rền.", "Tự nguyên_Xie": "Wiktionary chỉ ghi nhận âm Hán cổ (MC: hōng) mà không phân tích cấu trúc tự dạng. Chữ xuất hiện trong từ ghép 鏗鍧 (keng-hoành) diễn tả âm thanh vang rền của kim loại. Chưa có nguồn học thuật phân tích từng thành tố. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tháng sáu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 訇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金訇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "訇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鍧", "Unihan_Traditional (Chữ Phồn thể)": "鍧", "Pinyin_Xie": "hōng", "Âm Hán Việt_Xie": "hoành", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Danh từ | 名词 | Thường dùng làm từ tượng thanh mô tả âm thanh vang dội của tiếng sấm hoặc tiếng chuông. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鍼', '{"9000": "7511.0", "Chữ Trung Quốc": "鍼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 鍼 | châm | tượng hình | kim bằng kim loại dùng để châm cứu | 鍼 là dạng phồn thể cổ của 針 (châm). Wiktionary không phân tích cấu trúc nội tại của 鍼; bộ 金 (kim loại) gợi chất liệu, nhưng thành tố biểu âm không được xác nhận. Chữ tạo muộn trong chuỗi diễn biến tự dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"châm\": bộ 金 (kim loại) + hình dạng kim nhỏ nhọn → 鍼 là cây kim châm cứu bằng kim loại quý. | Gương Hán-Việt | châm — dùng trong \"châm cứu\" (鍼灸), \"kim châm\" (loại kim nhỏ) | Mở khoá kiến thức | Biết 鍼 mở khoá từ y học cổ truyền: 鍼灸 (châm cứu), 鍼刺 (châm chích).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi {{Han etym}} không khai triển. 鍼 là dạng cổ đồng nghĩa với 針 (châm — cây kim). Bộ 金 (kim) chỉ chất liệu kim loại; chữ này xuất hiện trong kim văn và tiểu triện liên quan đến công cụ y học cổ truyền. Chưa có nguồn học thuật xác nhận thành tố biểu âm cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây kim", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 咸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金咸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鍼", "Unihan_Traditional (Chữ Phồn thể)": "鍼", "Pinyin_Xie": "zhēn", "Âm Hán Việt_Xie": "châm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ cây kim châm cứu hoặc làm động từ chỉ hành động châm bệnh, khuyên bảo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鏦', '{"9000": "7512.0", "Chữ Trung Quốc": "鏦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 19 | nét | 鏦 | thung | tượng hình | giáo ngắn bằng kim loại, tiếng va chạm loảng xoảng | 鏦 thuộc bộ 金 (kim loại). Wiktionary không phân tích cấu trúc nội tại; chữ tạo muộn, cấu tạo chưa được xác nhận là hình thanh hay hội ý theo nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thung\": bộ 金 + âm tượng thanh cōng → hình dung tiếng giáo ngắn loảng xoảng khi chạm nhau. | Gương Hán-Việt | thung — không phổ biến trong tiếng Việt Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鏦 giúp đọc từ cổ văn 錚鏦 (tranh thung) — tiếng kim khí vang rền.", "Tự nguyên_Xie": "Wiktionary xác nhận âm Hán cổ (MC: cōng) và định nghĩa là giáo ngắn (short spear). Chữ xuất hiện trong từ ghép 錚鏦 và 鏦鏦 — đều là từ tượng thanh mô tả tiếng kim loại loảng xoảng. Không có phân tích cấu tạo tự dạng từ nguồn học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giáo ngắn; đâm bằng giáo; tiếng kêu loảng xoảng", "Hạng Tần Suất (Jun Da)": "7512.0", "Tần Suất % (Jun Da)": "99.9985421491", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 從", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金從", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "從", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鏦", "Unihan_Traditional (Chữ Phồn thể)": "鏦", "Pinyin_Xie": "cōng", "Âm Hán Việt_Xie": "thung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Từ tượng thanh | 象声词 | Chữ này dùng làm danh từ chỉ vũ khí cổ hoặc động từ chỉ hành động đâm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镵', '{"9000": "7513.0", "Chữ Trung Quốc": "镵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 22 | nét | 镵 | sàm | tượng hình | công cụ sắc nhọn bằng kim loại để đào bới | 镵 (phồn thể: 鑱) thuộc bộ 金 (kim loại). Wiktionary không phân tích cấu trúc hình thanh/hội ý; chữ tạo muộn, cấu tạo nội tại chưa được xác nhận học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sàm\": bộ 金 (kim loại) + hình dạng mũi nhọn → 镵 là dùi/lưỡi cày kim loại sắc bén dùng để đào khoét. | Gương Hán-Việt | sàm — ít dùng trong tiếng Việt hiện đại; gặp trong văn cổ | Mở khoá kiến thức | Biết 镵 giúp đọc văn cổ liên quan đến công cụ nông nghiệp và y cụ: 長鑱 (sàm dài — dụng cụ đào).", "Tự nguyên_Xie": "Wiktionary (dạng phồn thể 鑱) định nghĩa: sắc nhọn, mũi khoan/dùi, động từ châm/chích/đâm, và dụng cụ đào đất hình lưỡi xẻng dùng trong lịch sử. Âm Hán cổ MC: chán. Từ ghép ghi nhận: 長鑱 (dụng cụ đào dài). Chưa có phân tích cấu tạo tự dạng từ nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái dầm, cái lẹm, lưỡi cày; đục, khoét, châm, chích, khắc, trổ; bới lên, xới lên", "Hạng Tần Suất (Jun Da)": "7513.0", "Tần Suất % (Jun Da)": "99.9985436995", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 毚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅毚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镵", "Unihan_Traditional (Chữ Phồn thể)": "鑱", "Pinyin_Xie": "chán", "Âm Hán Việt_Xie": "sàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ nông cụ hoặc động từ chỉ hành động đào, xới đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陗', '{"9000": "7514.0", "Chữ Trung Quốc": "陗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 9 | nét | 阜 | phụ | biểu nghĩa | núi đất, gò cao | 肖 | tiêu | biểu âm | âm tiêu/tiễu | 陗 = 阜 (Phụ, biểu nghĩa: núi đất/gò cao) + 肖 (Tiêu, biểu âm); chữ hình thanh. 阜 gợi địa hình dốc đứng, 肖 cho âm qiào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiễu\": 阜 (gò đất) + 肖 (tiêu — âm) → 陗 là sườn núi đất dốc đứng cheo leo. | Gương Hán-Việt | tiễu — dạng thay thế của 峭 trong văn cổ | Mở khoá kiến thức | Biết 陗 giúp đọc văn cổ về địa hình; dạng đồng nghĩa với 峭 (tiễu — vách dốc).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 陗 là chữ hình thanh gồm 阜 (núi đất — biểu nghĩa) và 肖 (biểu âm). Nghĩa: dốc đứng, ngọn núi cheo leo. Wiktionary đánh dấu đây là dạng thay thế của 峭 (峭 chích — vách núi dốc). Âm Hán cổ MC: qiào. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếu; như \"tiếu (vực)\" (gdhn) tiễu; như \"tiễu (cao dốc)\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陗", "Unihan_Traditional (Chữ Phồn thể)": "陗", "Pinyin_Xie": "qiào", "Âm Hán Việt_Xie": "tiễu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ đứng trước danh từ để miêu tả địa hình núi non hiểm trở. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陼', '{"9000": "7515.0", "Chữ Trung Quốc": "陼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 10 | nét | 陼 | chử | tượng hình | bãi cát nhỏ giữa sông, cù lao | 陼 là chữ độc thể thuộc bộ 阜 (gò đất). Wiktionary không phân tích cấu trúc nội tại; đây là dạng thay thế của 渚 (chử — bãi nhỏ giữa sông).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chử\": bộ 阜 (đất nổi) → 陼 là bãi đất nhỏ nổi lên giữa dòng sông. | Gương Hán-Việt | chử — đồng nghĩa với 渚; dùng trong thơ cổ chỉ bãi cát/cù lao | Mở khoá kiến thức | Biết 陼 giúp đọc thơ cổ: dạng thay thế của 渚 (bãi nước giữa sông).", "Tự nguyên_Xie": "Wiktionary ghi nhận 陼 là dạng thay thế cổ (obs-std) của 渚 (chử — bãi cát nhỏ giữa sông, cù lao). Âm Hán cổ MC: zhǔ. Bộ 阜 gợi địa hình đất nổi lên; chưa có phân tích cấu tạo chi tiết từ nguồn học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngân hàng; cù lao", "Hạng Tần Suất (Jun Da)": "7515.0", "Tần Suất % (Jun Da)": "99.9985499009", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 者", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝者", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陼", "Unihan_Traditional (Chữ Phồn thể)": "陼", "Pinyin_Xie": "zhǔ", "Âm Hán Việt_Xie": "chử", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn viết cổ để chỉ các bãi đất nổi trên sông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韈', '{"9000": "7516.0", "Chữ Trung Quốc": "韈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 23 | nét | 韈 | mạt | tượng hình | tất/vớ làm từ da thuộc | 韈 thuộc bộ 革 (da thuộc). Wiktionary không phân tích cấu trúc nội tại; chữ tạo muộn, là dạng thay thế của 襪 (mạt — tất, vớ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạt\": bộ 革 (da thuộc) → 韈 là tất/vớ xưa làm từ da, che phủ bàn chân. | Gương Hán-Việt | mạt — đồng nghĩa với 襪; dùng trong từ cổ \"tất mạt\" | Mở khoá kiến thức | Biết 韈 giúp đọc văn cổ về trang phục: 朱韈 (tất đỏ quan lại), 韈子 (đôi tất).", "Tự nguyên_Xie": "Wiktionary xác nhận 韈 là dạng thay thế của 襪 (mạt — tất, vớ). Bộ 革 gợi vật liệu da thuộc; các dạng tất cổ đại làm từ da. Âm Hán cổ MC: wà. Từ ghép ghi nhận: 韈子, 朱韈 (tất màu đỏ của quan lại), 韈繫 (dây buộc tất). Chưa có phân tích cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái tất (đi vào chân); áo lót của đàn bà", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 蔑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革蔑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蔑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "韈", "Unihan_Traditional (Chữ Phồn thể)": "韈", "Pinyin_Xie": "wà", "Âm Hán Việt_Xie": "vạt, miệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ các loại tất chân hoặc trang phục lót thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骫', '{"9000": "7517.0", "Chữ Trung Quốc": "骫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 12 | nét | 骫 | ổi | tượng hình | xương cong vẹo, lệch lạc | 骫 thuộc bộ 骨 (xương). Wiktionary không phân tích cấu trúc nội tại; chữ tạo muộn. Bộ 骨 gợi liên quan đến xương, nghĩa \"cong\" phản ánh trạng thái xương lệch.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ổi\": bộ 骨 (xương) → 骫 là xương bị cong vẹo, lệch khỏi thẳng đứng. | Gương Hán-Việt | ổi — ít dùng trong tiếng Việt Hán-Việt hiện đại | Mở khoá kiến thức | Biết 骫 giúp đọc văn cổ tả tư thế cong lệch; thường ghép với 骳 thành 骫骳.", "Tự nguyên_Xie": "Wiktionary định nghĩa 骫 là cong/vẹo (bent, crooked). Âm Hán cổ MC: wěi. Chữ thuộc bộ 骨 (xương) gợi sự cong lệch của xương. Không có phân tích cấu tạo tự dạng chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cong", "Hạng Tần Suất (Jun Da)": "7517.0", "Tần Suất % (Jun Da)": "99.9985530016", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 丸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨丸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "骫", "Unihan_Traditional (Chữ Phồn thể)": "骫", "Pinyin_Xie": "wěi", "Âm Hán Việt_Xie": "uỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả trạng thái cong queo hoặc động từ chỉ việc uốn cong. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骳', '{"9000": "7518.0", "Chữ Trung Quốc": "骳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 14 | nét | 骳 | bội | tượng hình | xương gập lại, co rút; ngỗ nghịch | 骳 thuộc bộ 骨 (xương). Wiktionary không phân tích cấu trúc nội tại; chữ chỉ xuất hiện trong từ ghép 骫骳, mô tả trạng thái cong gập.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bội\": bộ 骨 (xương) → 骳 gợi xương bị gập lại — nhớ qua từ 骫骳 (xương cong gập đôi). | Gương Hán-Việt | bội — chỉ dùng trong từ ghép 骫骳 trong cổ văn | Mở khoá kiến thức | Biết 骳 giúp đọc từ cổ 骫骳 (bội — cong vẹo/ngỗ nghịch).", "Tự nguyên_Xie": "Wiktionary ghi nhận 骳 chỉ dùng trong 骫骳 (wánpí/wěibèi — cong vẹo; hoặc ngỗ nghịch trong một âm đọc khác là pí). Âm Hán cổ MC: bèi. Bộ 骨 gợi liên quan đến xương/cấu trúc cơ thể. Chưa có phân tích cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gập lại; co lại", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 皮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨皮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "骳", "Unihan_Traditional (Chữ Phồn thể)": "骳", "Pinyin_Xie": "bèi", "Âm Hán Việt_Xie": "bí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ chỉ xương bị cong hoặc động từ chỉ sự co gập. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骹', '{"9000": "7519.0", "Chữ Trung Quốc": "骹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 15 | nét | 骨 | cốt | biểu nghĩa | xương | 交 | giao | biểu âm | âm giao/kiều | 骹 = 骨 (Cốt, biểu nghĩa: xương) + 交 (Giao, biểu âm); chữ hình thanh. 骨 gợi bộ phận xương, 交 cho âm qiāo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiều\": 骨 (xương) + 交 (giao — gặp nhau) → 骹 là chỗ xương giao nhau, tức là khớp xương. | Gương Hán-Việt | kiều — ít dùng trong tiếng Việt Hán-Việt; \"cốt\" phổ biến hơn cho xương | Mở khoá kiến thức | Biết 骹 giúp đọc văn y học cổ và phương ngữ Quảng Đông về các khớp xương.", "Tự nguyên_Xie": "Theo Wiktionary: 骹 là chữ hình thanh gồm 骨 (xương — biểu nghĩa) và 交 (biểu âm). Nghĩa: khớp xương, mắt cá chân (trong tiếng Quảng Đông). Âm Hán cổ MC: qiāo. Chủ yếu dùng trong phương ngữ Quảng Đông chỉ các khớp xương. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Phiếu giảm giá", "Hạng Tần Suất (Jun Da)": "7519.0", "Tần Suất % (Jun Da)": "99.9985561023", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 交", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨交", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "交", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "骹", "Unihan_Traditional (Chữ Phồn thể)": "骹", "Pinyin_Xie": "qiāo", "Âm Hán Việt_Xie": "kiều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong y học cổ truyền để chỉ phần xương ống chân hoặc khớp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髠', '{"9000": "7520.0", "Chữ Trung Quốc": "髠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 12 | nét | 髠 | côn | tượng hình | cắt trọc đầu như hình phạt; cây trụi lá | 髠 thuộc bộ 髟 (tóc dài). Wiktionary không cung cấp cấu trúc nội tại (usedForm null). Bộ 髟 gợi tóc; nghĩa \"cắt trọc\" liên quan đến tóc bị cắt đi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"côn\": bộ 髟 (tóc) → 髠 là hình phạt cạo trọc đầu — tóc bị lấy đi như cây bị trụi lá. | Gương Hán-Việt | côn — dùng trong \"côn hình\" (hình phạt cạo đầu trong ngũ hình cổ đại) | Mở khoá kiến thức | Biết 髠 giúp đọc văn lịch sử pháp luật cổ đại: 髠刑 (côn hình — cạo đầu làm nhục).", "Tự nguyên_Xie": "Wiktionary không cung cấp glyphOrigin cho 髠. Bộ 髟 gợi liên quan đến tóc; nghĩa là hình phạt cắt trọc đầu trong luật cổ đại Trung Quốc, hoặc cây bị chặt trụi lá/cành. Đây là một trong năm hình phạt cổ đại (ngũ hình). Chưa có nguồn học thuật phân tích tự dạng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cắt tóc; cây trụi lá", "Hạng Tần Suất (Jun Da)": "7520.0", "Tần Suất % (Jun Da)": "99.9985576527", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 几", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟几", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "几", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "髠", "Unihan_Traditional (Chữ Phồn thể)": "髠", "Pinyin_Xie": "kūn", "Âm Hán Việt_Xie": "khôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ hình phạt cạo đầu thời xưa hoặc tính từ chỉ sự trơ trụi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髥', '{"9000": "7521.0", "Chữ Trung Quốc": "髥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 14 | nét | 髥 | nhiễm | tượng hình | râu dài rủ xuống | 髥 thuộc bộ 髟 (tóc dài rủ xuống). Wiktionary không cung cấp glyphOrigin; chữ có ảnh Lục thư thông từ hanziyuan nhưng không có giải thích cấu tạo học thuật. Chữ tạo muộn (Lục thư thông là bản soạn thời Minh).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhiễm\": bộ 髟 (tóc rủ) → 髥 là chùm râu dài rủ xuống từ cằm hay mép. | Gương Hán-Việt | nhiễm — đồng nghĩa với 髯 (nhiễm — râu dài); hai dạng song song | Mở khoá kiến thức | Biết 髥 giúp đọc mô tả ngoại hình trong cổ văn: đồng nghĩa với 髯 (râu dài).", "Tự nguyên_Xie": "Lục thư thông | Wiktionary không cung cấp phân tích cấu tạo cho 髥. Bộ 髟 gợi tóc/râu dài rủ; nghĩa là râu mép hoặc râu cằm. Ảnh Lục thư thông (thời Minh) cho thấy dạng chữ nhưng không có giáp cốt hay kim văn — chữ tạo muộn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "râu", "Hạng Tần Suất (Jun Da)": "4008.0", "Tần Suất % (Jun Da)": "99.7467509951", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 冄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟冄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "髯", "Unihan_Traditional (Chữ Phồn thể)": "髥", "Pinyin_Xie": "rán", "Âm Hán Việt_Xie": "nhiễm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ phần râu mọc ở hai bên má và cằm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳒', '{"9000": "7522.0", "Chữ Trung Quốc": "鳒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 18 | nét | 鳒 | kiêm | tượng hình | cá bơn miệng rộng | 鳒 thuộc bộ 魚 (cá). Wiktionary ghi dạng phồn thể là 鰜 nhưng không phân tích cấu trúc; chữ tạo muộn, cấu tạo nội tại chưa được xác nhận học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiêm\": bộ 魚 (cá) → 鳒 là loài cá bơn dẹt, nổi tiếng vì miệng rộng. | Gương Hán-Việt | kiêm — ít dùng trong tiếng Việt Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鳒 giúp đọc văn về ngư nghiệp và phân loại động vật học cổ đại Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary dùng dạng 鰜 làm usedForm, xác nhận âm MC: jiān. Nghĩa: loài cá bơn miệng rộng (big-mouthed flounder). Bộ 魚 gợi loại cá. Không có phân tích cấu tạo chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá bơn", "Hạng Tần Suất (Jun Da)": "7522.0", "Tần Suất % (Jun Da)": "99.9985607534", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 兼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼兼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳒", "Unihan_Traditional (Chữ Phồn thể)": "鰜", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "kiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cá thân dẹt sống ở đáy biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶡', '{"9000": "7523.0", "Chữ Trung Quốc": "鶡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 20 | nét | 鶡 | hạt | tượng hình | chim trĩ nâu tai có mào, loài chim dũng mãnh | 鶡 thuộc bộ 鳥 (chim). Wiktionary không phân tích cấu trúc nội tại; chữ tạo muộn, cấu tạo chưa được xác nhận hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạt\": bộ 鳥 (chim) → 鶡 là chim trĩ nâu tai dũng mãnh, lông dùng làm mũ võ quan. | Gương Hán-Việt | hạt — dùng trong \"hạt quan\" (mũ lông chim hạt của võ tướng cổ đại) | Mở khoá kiến thức | Biết 鶡 giúp đọc văn lịch sử: 鶡冠 (hạt quan — mũ lông chim hạt của võ quan).", "Tự nguyên_Xie": "Wiktionary định nghĩa 鶡 là loài chim trĩ nâu tai (brown-eared pheasant, Crossoptilon mantchuricum). Cũng dùng trong 鶡旦 (tên một loài chim khác trong văn học cổ). Âm Hán cổ MC: hé. Từ ghép: 鶡雞, 鶡冠 (mũ đội lông chim hạt của võ quan). Chưa có phân tích cấu tạo tự dạng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Anh ta", "Hạng Tần Suất (Jun Da)": "7879.0", "Tần Suất % (Jun Da)": "99.9991116464", "GavinGrover_Once (Chiết tự trực tiếp)": "曷 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰曷鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鹖", "Unihan_Traditional (Chữ Phồn thể)": "鶡", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim trĩ dũng mãnh thường dùng lông làm mũ võ quan thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龒', '{"9000": "7524.0", "Chữ Trung Quốc": "龒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 龍 | Số nét | 21 | nét | 龒 | long | tượng hình | dạng cổ của 龍 (rồng) | 龒 là dạng cổ/biến thể của 龍 (long — rồng). Wiktionary không cung cấp glyphOrigin; chữ tạo muộn, không có giáp cốt hay kim văn riêng. Bộ 龍 gợi liên quan đến rồng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"long\": biến thể cổ của 龍 (rồng) → 龒 là cách viết khác của long trong văn bản cổ đại. | Gương Hán-Việt | long — đồng nghĩa và đồng âm hoàn toàn với 龍 (rồng) | Mở khoá kiến thức | Biết 龒 giúp nhận ra biến thể cổ khi đọc kim văn hoặc khắc thạch cổ đại.", "Tự nguyên_Xie": "Wiktionary không phân tích cấu tạo 龒; đây là biến thể cổ của 龍 (rồng). Không có giáp cốt văn hay kim văn riêng biệt — chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "biến thể cũ của 龍", "Hạng Tần Suất (Jun Da)": "7524.0", "Tần Suất % (Jun Da)": "99.9985638541", "GavinGrover_Once (Chiết tự trực tiếp)": "龍 + 示", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱龍示", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "示", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "龍", "Unihan_Simplified (Chữ Giản thể)": "龒", "Unihan_Traditional (Chữ Phồn thể)": "龒", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "long", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là biến thể cổ của chữ long, làm danh từ chỉ con rồng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籂', '{"9000": "7525.0", "Chữ Trung Quốc": "籂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 19 | nét | 籂 | tê | tượng hình | chữ cực hiếm, ý nghĩa không rõ | 籂 thuộc bộ 竹 (tre). Wiktionary không cung cấp glyphOrigin (usedForm null); cấu tạo nội tại hoàn toàn chưa rõ. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tê\": bộ 竹 (tre) → 籂 là chữ cực hiếm trong nhóm đồ vật tre, ý nghĩa chưa được xác định rõ. | Gương Hán-Việt | tê — không có từ Hán-Việt thông dụng | Mở khoá kiến thức | 籂 là chữ cực hiếm; biết bộ 竹 giúp đoán liên quan đến tre hoặc đồ vật bằng tre.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích cấu tạo hay định nghĩa rõ ràng cho 籂. Bộ 竹 gợi liên quan đến tre/đồ vật bằng tre. Âm đọc: shi (thanh nhẹ). Đây là chữ cực kỳ hiếm, không có tài liệu học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "炱", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 飾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮飾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "飾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "籂", "Unihan_Traditional (Chữ Phồn thể)": "籂", "Pinyin_Xie": "shi", "Âm Hán Việt_Xie": "tê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ lớp muội than đen bám trên xoong nồi hoặc vách bếp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翯', '{"9000": "7526.0", "Chữ Trung Quốc": "翯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 16 | nét | 羽 | vũ | biểu nghĩa | lông vũ | 高 | cao | biểu âm | âm hào/hạc | 翯 = 羽 (Vũ, biểu nghĩa: lông vũ) + 高 (Cao, biểu âm); chữ hình thanh. 羽 gợi lông chim bóng sáng, 高 cho âm hè/hào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạc\": 羽 (lông vũ) + 高 (cao — âm) → 翯 là lông trắng muốt bóng sáng của chim trên trời cao. | Gương Hán-Việt | hạc — không phổ biến độc lập; liên hệ 翯翯 (hạc hạc — lông trắng muốt) | Mở khoá kiến thức | Biết 翯 giúp đọc thơ cổ điển: 翯翯 (lông chim bóng sáng trắng muốt) trong Kinh Thi.", "Tự nguyên_Xie": "Theo Wiktionary: 翯 là chữ hình thanh gồm 羽 (lông vũ — biểu nghĩa) và 高 (biểu âm). Nghĩa: lông vũ trắng bóng, phản chiếu ánh sáng; cũng dùng chỉ ánh sáng mặt trời phản chiếu trên mặt nước. Trích dẫn từ Kinh Thi và Sử ký. Âm Hán cổ MC: hè. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lông trắng muốt; lông vũ trắng muốt", "Hạng Tần Suất (Jun Da)": "7526.0", "Tần Suất % (Jun Da)": "99.9985669548", "GavinGrover_Once (Chiết tự trực tiếp)": "羽 + 高", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羽高", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "高", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翯", "Unihan_Traditional (Chữ Phồn thể)": "翯", "Pinyin_Xie": "hè", "Âm Hán Việt_Xie": "hạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả vẻ trắng muốt và bóng bẩy của lông chim. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莚', '{"9000": "7527.0", "Chữ Trung Quốc": "莚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 莚 | diên | tượng hình | chiếu tre, bữa tiệc; dây leo lan rộng | 莚 thuộc bộ 艸 (cỏ/thực vật). Wiktionary không phân tích cấu trúc nội tại; chữ tạo muộn. Bộ 艸 gợi liên quan đến thực vật/đan chiếu từ cỏ hoặc tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diên\": bộ 艸 (cỏ) → 莚 gợi chiếu cỏ trải ra, hay dây leo lan rộng như bữa tiệc mở rộng. | Gương Hán-Việt | diên — ít dùng độc lập; dùng trong 莚蔓 (diên mạn — leo lan) | Mở khoá kiến thức | Biết 莚 giúp đọc cổ văn: 莚蔓 (diên mạn — dây leo lan rộng).", "Tự nguyên_Xie": "Wiktionary ghi nhận 莚 chỉ dùng trong 莚蔓 (diên mạn — leo dài lan rộng). Âm Hán cổ MC: yán. Nghĩa gốc là chiếu tre hoặc bữa tiệc (feast); cũng mang nghĩa leo lan rộng ra. Bộ 艸 gợi thực vật. Chưa có phân tích cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chiếu trúc; bữa tiệc", "Hạng Tần Suất (Jun Da)": "7527.0", "Tần Suất % (Jun Da)": "99.9985685052", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 延", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹延", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "延", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莚", "Unihan_Traditional (Chữ Phồn thể)": "莚", "Pinyin_Xie": "yán", "Âm Hán Việt_Xie": "diên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ chiếc chiếu tre hoặc bữa tiệc tiếp đãi khách. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萗', '{"9000": "7528.0", "Chữ Trung Quốc": "萗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 萗 | sách | tượng hình | chữ hiếm thuộc bộ cỏ, ý nghĩa không rõ | 萗 thuộc bộ 艸 (cỏ/thực vật). Wiktionary không cung cấp glyphOrigin (usedForm null); cấu tạo hoàn toàn chưa rõ. Chữ tạo muộn, cực kỳ hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sách\": bộ 艸 (cỏ) + âm cè gần 策 (sách) → 萗 là chữ bộ cỏ cực hiếm. | Gương Hán-Việt | sách — không có từ Hán-Việt thông dụng dùng 萗 | Mở khoá kiến thức | 萗 là chữ cực hiếm; nhận bộ 艸 giúp đoán liên quan đến thực vật.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích cấu tạo hay định nghĩa rõ cho 萗. Bộ 艸 gợi liên quan đến thực vật. Âm đọc: cè. Nghĩa gốc là \"xuân\" theo một số nguồn từ điển nhưng chưa được xác nhận học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xuân", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 宗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹宗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萗", "Unihan_Traditional (Chữ Phồn thể)": "萗", "Pinyin_Xie": "cè", "Âm Hán Việt_Xie": "sách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại thực vật thân thảo thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('転', '{"9000": "7529.0", "Chữ Trung Quốc": "転", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 11 | nét | 転 | chuyển | tượng hình | dạng Nhật-thể của 轉 (chuyển — quay, đổi) | 転 là dạng tự dạng Nhật Bản của 轉 (chuyển). Thuộc bộ 車 (xe). Wiktionary không cung cấp glyphOrigin (usedForm null). Dạng giản lược không có trong tiêu chuẩn chữ Hán giản thể Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chuyển\": bộ 車 (xe) → 転 là bánh xe quay tròn, chuyển hướng — dạng Nhật của 轉. | Gương Hán-Việt | chuyển — dùng trong \"chuyển động\", \"chuyển đổi\"; 転 là dạng Nhật của 轉 | Mở khoá kiến thức | Biết 転 giúp đọc văn bản Nhật Bản; đồng nghĩa hoàn toàn với 轉/转 (chuyển).", "Tự nguyên_Xie": "転 là dạng tự dạng Nhật Bản (shinjitai) của 轉 (chuyển — quay vòng, đổi hướng). Bộ 車 (xe) gợi bánh xe quay; phần còn lại cho âm. Chưa có phân tích nguồn gốc riêng biệt. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quay vòng, chuyển, đổi", "Hạng Tần Suất (Jun Da)": "7529.0", "Tần Suất % (Jun Da)": "99.9985716059", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 云", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車云", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "云", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "転", "Unihan_Traditional (Chữ Phồn thể)": "転", "Pinyin_Xie": "zhuǎn", "Âm Hán Việt_Xie": "chuyển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động xoay vần, thay đổi trạng thái hoặc phương hướng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄷', '{"9000": "7530.0", "Chữ Trung Quốc": "鄷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 15 | nét | 鄷 | phong | tượng hình | địa danh cổ, biến thể của 酆 | 鄷 thuộc bộ 邑 (thành ấp). Wiktionary không cung cấp glyphOrigin (usedForm null). Bộ 邑 gợi liên quan đến địa danh/thành ấp. Chữ là biến thể cổ của 酆 (Phong — tên đất cổ đại).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phong\": bộ 邑 (ấp, đất đai) → 鄷 là tên một vùng đất cổ, biến thể của 酆 (kinh đô nhà Chu). | Gương Hán-Việt | phong — trong lịch sử: 鄷京 (Phong Kinh — kinh đô nhà Văn Vương) | Mở khoá kiến thức | Biết 鄷 giúp đọc sử học cổ đại về nhà Chu: tên địa danh lịch sử.", "Tự nguyên_Xie": "鄷 là biến thể cổ của 酆 (Phong — tên kinh đô cổ của nhà Chu). Bộ 邑 trong chữ Hán thường chỉ địa danh. Wiktionary không cung cấp phân tích cấu tạo. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "biến thể cũ của 酆 [Feng1]", "Hạng Tần Suất (Jun Da)": "7530.0", "Tần Suất % (Jun Da)": "99.9985731562", "GavinGrover_Once (Chiết tự trực tiếp)": "豊 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豊阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄷", "Unihan_Traditional (Chữ Phồn thể)": "鄷", "Pinyin_Xie": "fēng", "Âm Hán Việt_Xie": "phong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng chỉ địa danh thời cổ hoặc họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靭', '{"9000": "7531.0", "Chữ Trung Quốc": "靭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 12 | nét | 靭 | nhận | tượng hình | da thuộc dẻo dai; bền chắc | 靭 thuộc bộ 革 (da thuộc). Wiktionary không cung cấp glyphOrigin (usedForm null). Bộ 革 gợi chất liệu da; nghĩa \"dẻo dai\" phản ánh tính chất da thuộc tốt. Dạng biến thể của 韌.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhận\": bộ 革 (da thuộc) → 靭 là da thuộc dẻo dai không dễ đứt — kiên cường bất khuất. | Gương Hán-Việt | nhận — dùng trong \"nhận tính\" (tính dai dẻo), \"cường nhận\" (mạnh mẽ bền bỉ) | Mở khoá kiến thức | Biết 靭 giúp đọc văn mô tả tính cách: biến thể của 韌 (dai, dẻo, kiên cường).", "Tự nguyên_Xie": "靭 là biến thể của 韌 (nhận — dai, bền, dẻo). Wiktionary không cung cấp phân tích cấu tạo tự dạng cho 靭. Bộ 革 (da thuộc) gợi sự dai bền của da; nghĩa mở rộng thành tính cách kiên cường. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhẫn; như \"nhẫn tính\" (gdhn)", "Hạng Tần Suất (Jun Da)": "3131.0", "Tần Suất % (Jun Da)": "99.3004915278", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 刃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革刃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "韧", "Unihan_Traditional (Chữ Phồn thể)": "靭", "Pinyin_Xie": "rèn", "Âm Hán Việt_Xie": "nhận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ bổ nghĩa cho danh từ để chỉ đặc tính dẻo dai, khó đứt gãy. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馉', '{"9000": "7532.0", "Chữ Trung Quốc": "馉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 12 | nét | 馉 | cốt | tượng hình | loại bánh bao nấu nước trong ẩm thực cổ Trung Quốc | 馉 thuộc bộ 食 (thực phẩm). Wiktionary không cung cấp glyphOrigin (usedForm null). Bộ 食 gợi liên quan đến thức ăn; nghĩa là thành tố trong từ 馉饳 (cốt đốt — loại bánh bao nấu nước).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cốt\": bộ 食 (thức ăn) → 馉 là thành tố trong 馉饳 — loại bánh nấu nước xưa của Trung Quốc. | Gương Hán-Việt | cốt — chỉ dùng trong \"cốt đốt\" (馉饳); không có từ độc lập | Mở khoá kiến thức | Biết 馉 giúp đọc văn ẩm thực cổ: 馉饳 (cốt đốt — bánh nấu nước cổ đại).", "Tự nguyên_Xie": "馉 không có glyphOrigin trong Wiktionary. Bộ 食 (thức ăn) gợi rõ liên quan đến ẩm thực. Chữ chỉ xuất hiện trong từ ghép 馉饳 (gǔ duò — loại bánh nấu nước thời cổ, tương tự sủi cảo). Tiếng Việt đọc là \"cốt đốt\" trong từ điển Hán-Việt cổ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: cốt đốt 餶飿,馉饳)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 骨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣骨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "骨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "馉", "Unihan_Traditional (Chữ Phồn thể)": "馉", "Pinyin_Xie": "gǔ", "Âm Hán Việt_Xie": "cốt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường kết hợp thành từ ghép để chỉ một loại bánh hấp truyền thống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼰', '{"9000": "7533.0", "Chữ Trung Quốc": "鼰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼠 | Số nét | 20 | nét | 鼰 | tức | tượng hình | dạng thay thế của 鼳, loài chuột cổ đại | 鼰 thuộc bộ 鼠 (chuột). Wiktionary không phân tích cấu trúc nội tại; chữ là dạng thay thế cổ (obs-std) của 鼳. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tức\": bộ 鼠 (chuột) → 鼰 là loài chuột cổ đại, dạng thay thế của 鼳 trong văn bản cổ. | Gương Hán-Việt | tức — chỉ dùng trong từ điển cổ và văn học cổ đại | Mở khoá kiến thức | Biết 鼰 giúp nhận biết bộ 鼠 trong phân loại động vật học cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi nhận 鼰 là dạng thay thế cổ (obs-std) của 鼳. Âm Hán cổ MC: jú/xí. Bộ 鼠 gợi liên quan đến loài chuột. Không có phân tích cấu tạo chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kiềm chế", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鼠 + 貝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鼠貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼠", "Unihan_Simplified (Chữ Giản thể)": "鼰", "Unihan_Traditional (Chữ Phồn thể)": "鼰", "Pinyin_Xie": "niàn", "Âm Hán Việt_Xie": "tức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ chỉ một loài động vật gặm nhấm sống ở rừng tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臛', '{"9000": "7534.0", "Chữ Trung Quốc": "臛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 20 | nét | 臛 | hoắc | tượng hình | canh thịt đặc, nước dùng thịt | 臛 thuộc bộ 肉 (thịt). Wiktionary không phân tích cấu trúc nội tại; chữ tạo muộn. Bộ ⺼/肉 gợi liên quan đến thịt; nghĩa canh thịt là nghĩa chính.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoắc\": bộ 肉 (thịt) → 臛 là nồi canh thịt đặc sánh, dùng trong văn học ẩm thực cổ điển. | Gương Hán-Việt | hoắc — dùng trong văn cổ chỉ canh thịt; ít gặp trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 臛 giúp đọc văn ẩm thực và thơ cổ điển mô tả bữa tiệc cung đình.", "Tự nguyên_Xie": "Wiktionary xác nhận 臛 là canh thịt (meat broth) trong văn học cổ điển. Âm Hán cổ MC: huò. Bộ 肉 gợi rõ nguồn gốc liên quan đến thịt. Không có phân tích cấu tạo tự dạng chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "canh thịt; hun, nung", "Hạng Tần Suất (Jun Da)": "7534.0", "Tần Suất % (Jun Da)": "99.9985871094", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 霍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月霍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "霍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臛", "Unihan_Traditional (Chữ Phồn thể)": "臛", "Pinyin_Xie": "huò", "Âm Hán Việt_Xie": "hoắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ món canh thịt hầm đặc trong ẩm thực cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軡', '{"9000": "7535.0", "Chữ Trung Quốc": "軡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 11 | nét | 軡 | khiên | tượng hình | khuôn vuông trong thùng xe; cấu kiện bánh xe cổ đại | 軡 thuộc bộ 車 (xe). Wiktionary không cung cấp glyphOrigin (usedForm null); cấu tạo nội tại hoàn toàn chưa rõ. Chữ tạo muộn, cực hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiên\": bộ 車 (xe) → 軡 là bộ phận vuông bên trong thùng xe ngựa cổ đại. | Gương Hán-Việt | khiên — không có từ Hán-Việt thông dụng | Mở khoá kiến thức | 軡 là chữ chuyên ngành xe cộ cổ đại; biết bộ 車 giúp nhận ra nhóm này.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích cấu tạo hay định nghĩa đầy đủ cho 軡. Bộ 車 (xe) gợi liên quan đến xe cộ. Âm đọc: qián. Nghĩa theo từ điển: khuôn vuông trong thùng xe (phần nội thất xe ngựa cổ đại). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khuôn vuông trong hòm xe; bánh xe", "Hạng Tần Suất (Jun Da)": "7535.0", "Tần Suất % (Jun Da)": "99.9985933109", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 今", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車今", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "今", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "軡", "Unihan_Traditional (Chữ Phồn thể)": "軡", "Pinyin_Xie": "qián", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một bộ phận bằng gỗ trên xe ngựa thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞐', '{"9000": "7536.0", "Chữ Trung Quốc": "瞐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 15 | nét | 目 | mục | biểu nghĩa | mắt | 目 | mục | biểu nghĩa | mắt (x3 — ba mắt chồng lên) | 瞐 theo Wiktionary là chữ ba mắt ({{zh-etym-triple|目|eye}}) — ba chữ 目 chồng lên nhau. Đây là cấu trúc tăng gấp bội (triple ideograph), nhấn mạnh mắt đẹp sáng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạch\": ba chữ 目 (mắt) chồng lên → 瞐 nhấn mạnh đôi mắt đẹp rực rỡ — ba đôi mắt hội tụ ánh nhìn. | Gương Hán-Việt | mạch — ít dùng trong tiếng Việt Hán-Việt hiện đại | Mở khoá kiến thức | Biết 瞐 giúp nhận ra kiểu tạo chữ triple-ideograph; liên hệ 森 (ba cây), 磊 (ba đá), 轟 (ba xe).", "Tự nguyên_Xie": "Theo Wiktionary: 瞐 là chữ gồm ba chữ 目 (mắt) chồng lên nhau (triple-ideograph). Nghĩa cổ: mắt đẹp; ngoại hình đẹp; mắt tối/sâu. Âm Hán cổ MC: mò. Đây là kiểu tạo chữ bằng cách nhân ba (triple 目) để tăng cường nghĩa, tương tự như 森 (ba cây), 磊 (ba đá). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "琐", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "品 (Kiến trúc tam giác)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴目", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "瞐", "Unihan_Traditional (Chữ Phồn thể)": "瞐", "Pinyin_Xie": "mò", "Âm Hán Việt_Xie": "mạch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chủ yếu dùng làm tính từ miêu tả vẻ đẹp của đôi mắt trong văn cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('銶', '{"9000": "7537.0", "Chữ Trung Quốc": "銶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 金 | kim | biểu nghĩa | kim loại | 求 | cầu | biểu âm | cầu xin (biểu âm) | 銶 = 金 (Kim, biểu nghĩa: kim loại) + 求 (Cầu, biểu âm); chữ hình thanh. Bộ 金 chỉ chất liệu, 求 cho âm đọc gần qiú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cầu\" (đọc theo 求): dụng cụ kim loại (金) dùng để đục — hình dung chiếc đục bằng thép cầm trong tay. | Gương Hán-Việt | Chữ 銶 hiếm, không xuất hiện trong từ Hán-Việt thông dụng. Bộ 金 gặp trong: kim loại, kim cương. | Mở khoá kiến thức | Biết 銶 giúp nhận ra các chữ bộ 金 chỉ dụng cụ thủ công cổ đại.", "Tự nguyên_Xie": "Chữ hình thanh: 金 (kim loại) biểu nghĩa, 求 biểu âm. Wiktionary ghi nhận cấu trúc hình thanh nhưng định nghĩa còn bỏ trống (rfdef). Nghĩa phổ biến nhất được ghi nhận là một loại đục kim loại. Chưa tìm thấy giải thích nguồn gốc chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "銶", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 求", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金求", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "求", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "𨱇", "Unihan_Traditional (Chữ Phồn thể)": "銶", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "cầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ công cụ thủ công nghiệp thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钖', '{"9000": "7538.0", "Chữ Trung Quốc": "钖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 8 | nét | 钖 | dương | tượng hình | vật trang sức kim loại (giản thể từ 鍚) | 钖 là dạng giản thể của 鍚, đơn giản hóa từ 釒 (kim) + 昜 (dương). Chữ chỉ đồ trang sức kim loại gắn trên trán ngựa hoặc phía sau khiên. Cấu trúc gốc là hình thanh nhưng dạng giản thể đã mất đi bộ phận biểu âm rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dương\": vật kim loại sáng lấp lánh (dương = ánh sáng) gắn lên trán ngựa — hào quang chiến trận. | Gương Hán-Việt | Chữ 钖 rất hiếm; bộ 钅(金) gặp trong nhiều từ kim loại thông dụng. | Mở khoá kiến thức | Biết 钖 giúp đọc văn bản lễ nghi cổ mô tả trang phục và trang bị ngựa chiến.", "Tự nguyên_Xie": "Lục thư thông | Wiktionary ghi 钖 là giản hóa của 鍚, trong đó 釒 viết thành 钅 và 昜 giản thành 𠃓. Chữ gốc 鍚 chỉ đồ trang sức kim loại trên trán ngựa hay phần trang trí sau lưng khiên. Chữ tạo muộn, chủ yếu xuất hiện trong văn bản lễ nghi cổ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vật trang sức bằng kim loại trên trán ngựa; phần trang sức sau lưng khiên (cái mộc)", "Hạng Tần Suất (Jun Da)": "7538.0", "Tần Suất % (Jun Da)": "99.998602613", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 𠃓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅𠃓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠃓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钖", "Unihan_Traditional (Chữ Phồn thể)": "鍚", "Pinyin_Xie": "yáng", "Âm Hán Việt_Xie": "dương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ đồ trang sức cho ngựa trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矊', '{"9000": "7539.0", "Chữ Trung Quốc": "矊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 19 | nét | 矊 | miên | tượng hình | nhìn, liếc mắt | 矊 có bộ 目 (mục, mắt) nhưng cấu trúc thành phần chi tiết chưa được Wiktionary phân tích rõ. Theo bộ thủ, chữ liên quan đến mắt/nhìn. Chưa xác định rõ hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miên\": con mắt (目) nhìn mờ như qua màn sương — liên tưởng đến cái nhìn lơ đãng, mơ màng. | Gương Hán-Việt | Chữ 矊 rất hiếm; bộ 目 gặp trong: mục tiêu, nhãn khoa. | Mở khoá kiến thức | Biết 矊 giúp nhận dạng các chữ bộ 目 chỉ trạng thái ánh mắt trong văn học cổ.", "Tự nguyên_Xie": "Wiktionary chỉ ghi âm đọc, không có giải thích nguồn gốc hình thành chữ. Nghĩa gốc liên quan đến ánh mắt hoặc cách nhìn. Bộ 目 (mắt) là thành phần nhận diện chính. Chưa có nguồn học thuật giải thích cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "犊", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 綿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目綿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "綿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "矊", "Unihan_Traditional (Chữ Phồn thể)": "矊", "Pinyin_Xie": "mián", "Âm Hán Việt_Xie": "miên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ hành vi nhìn hoặc tính từ tả mắt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矘', '{"9000": "7540.0", "Chữ Trung Quốc": "矘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 25 | nét | 矘 | đảng | tượng hình | nhìn thẳng, nhìn trân trân | 矘 có bộ 目 (mục, mắt), chỉ trạng thái đôi mắt nhìn trực tiếp hay ngây ra. Cấu trúc chi tiết chưa được phân tích trong Wiktionary. Chữ hiếm, dùng trong văn học cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đảng\": đôi mắt (目) ngây ra nhìn thẳng — như kẻ bị choáng ngợp không chớp mắt. | Gương Hán-Việt | Chữ 矘 rất hiếm; bộ 目 xuất hiện trong: mục đích, nhãn quan. | Mở khoá kiến thức | Biết 矘 mở ra vốn từ văn học cổ miêu tả trạng thái nhìn ngây dại.", "Tự nguyên_Xie": "Wiktionary ghi nhận âm đọc và hệ thống phiên âm nhưng không cung cấp giải thích nguồn gốc. Bộ 目 gợi ý liên quan đến thị giác. Chữ có thể là hình thanh với 目 biểu nghĩa. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "矘", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 黨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目黨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "矘", "Unihan_Traditional (Chữ Phồn thể)": "矘", "Pinyin_Xie": "tǎng", "Âm Hán Việt_Xie": "đảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Dùng làm tính từ miêu tả trạng thái thị lực hoặc ánh mắt sáng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矡', '{"9000": "7541.0", "Chữ Trung Quốc": "矡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 矛 | Số nét | 25 | nét | 矡 | giác | tượng hình | loại binh khí (giáo, mâu) | 矡 thuộc bộ 矛 (mâu, giáo). Cấu trúc chi tiết chưa được xác định; nhiều khả năng là hình thanh với 矛 biểu nghĩa. Chưa có phân tích thành phần trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giác\": cây giáo (矛) — hình dung vũ khí nhọn, sắc bén dùng trong chiến trận cổ đại. | Gương Hán-Việt | Chữ 矡 rất hiếm; bộ 矛 gặp trong: mâu thuẫn (矛盾). | Mở khoá kiến thức | Biết 矡 giúp nhận dạng nhóm chữ bộ 矛 chỉ vũ khí cổ đại trong văn bản lịch sử.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc trong Wiktionary. Chữ thuộc bộ 矛 (mâu), gợi ý liên quan đến binh khí có cán dài. Chưa có nguồn học thuật giải thích. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "硡", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "矛 + 矍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰矛矍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "矛", "Unihan_Simplified (Chữ Giản thể)": "矡", "Unihan_Traditional (Chữ Phồn thể)": "矡", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "giác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ miêu tả động tác mắt mở to kinh ngạc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硽', '{"9000": "7542.0", "Chữ Trung Quốc": "硽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 13 | nét | 硽 | yên | tượng hình | băng đảng; bộ 石 | 硽 thuộc bộ 石 (thạch, đá). Cấu trúc thành phần chi tiết chưa được xác định; không có phân tích Wiktionary. Nghĩa ghi nhận là \"băng đảng\" — mối liên hệ với đá chưa rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yên\": nhóm người cứng như đá (石) — 硽 là băng đảng kiên cố, khó phá vỡ. | Gương Hán-Việt | Chữ 硽 rất hiếm; bộ 石 gặp trong: thạch anh, bàn thạch (vững như đá). | Mở khoá kiến thức | Biết 硽 giúp nhận ra nhóm chữ bộ 石 trong từ vựng cổ phương ngữ.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc trong Wiktionary. Nghĩa ghi nhận: băng đảng. Bộ 石 (thạch) là thành phần nhận diện. Có thể là chữ vùng phương ngữ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "băng đảng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 奄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石奄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硽", "Unihan_Traditional (Chữ Phồn thể)": "硽", "Pinyin_Xie": "yān", "Âm Hán Việt_Xie": "yên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ địa hình đất đá trong văn tự cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磿', '{"9000": "7543.0", "Chữ Trung Quốc": "磿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 17 | nét | 磿 | lịch | tượng hình | nghiền, xay (bộ 石) | 磿 thuộc bộ 石 (thạch, đá), gợi ý liên quan đến nghiền, xay đá. Cấu trúc chi tiết chưa được phân tích trong Wiktionary. Chữ hiếm gặp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lịch\": viên đá (石) mài giũa — hình dung cối đá xay lúa, tiếng rền vang. | Gương Hán-Việt | Chữ 磿 rất hiếm; bộ 石 gặp trong: thạch học, lịch sử (không liên quan trực tiếp). | Mở khoá kiến thức | Biết 磿 giúp nhận dạng nhóm chữ bộ 石 chỉ dụng cụ gia công vật liệu cứng.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc trong Wiktionary. Bộ 石 gợi ý nghĩa liên quan đến đá, nghiền xay. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "磿", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "厤 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厤石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磿", "Unihan_Traditional (Chữ Phồn thể)": "磿", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ mô phỏng âm thanh hoặc động từ chỉ việc mài giũa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礈', '{"9000": "7544.0", "Chữ Trung Quốc": "礈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 17 | nét | 礈 | trụy | tượng hình | đá; bộ 石 | 礈 thuộc bộ 石 (thạch, đá). Cấu trúc chi tiết chưa được xác định; không có phân tích Wiktionary. Chữ rất hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trụy\": viên đá (石) rơi xuống — trụy mang nghĩa sa rớt, viên đá nặng lăn xuống dốc. | Gương Hán-Việt | Bộ 石 gặp trong: thạch anh, trụy lạc (không liên quan trực tiếp). | Mở khoá kiến thức | Biết 礈 giúp nhận dạng chữ bộ 石 trong tài liệu địa chất cổ.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc trong Wiktionary. Bộ 石 gợi ý liên quan đến đá. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "爈", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 遂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石遂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "遂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礈", "Unihan_Traditional (Chữ Phồn thể)": "礈", "Pinyin_Xie": "zhuì", "Âm Hán Việt_Xie": "trụy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ loại đá hoặc động từ chỉ trạng thái rơi rụng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礜', '{"9000": "7545.0", "Chữ Trung Quốc": "礜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 18 | nét | 與 | dữ | biểu âm | cho, cùng (biểu âm) | 石 | thạch | biểu nghĩa | đá, khoáng vật | 礜 = 石 (Thạch, biểu nghĩa: đá/khoáng) + 與 (Dữ, biểu âm); chữ hình thanh. Bộ 石 chỉ chất liệu khoáng, 與 cho âm đọc yù/dữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dự\": viên đá (石) độc hại — 礜 là thạch tín, loại khoáng vật cực độc mà người xưa vừa sợ vừa dùng làm thuốc. | Gương Hán-Việt | \"礜石\" — thạch tín (arsenic); bộ 石 trong: thạch học, ngọc thạch. | Mở khoá kiến thức | Biết 礜 mở ra từ vựng y dược cổ: 礜石 (thạch tín, thạch tín/arsenic trioxide dùng trong bào chế cổ).", "Tự nguyên_Xie": "Lục thư thông | Wiktionary xác nhận cấu trúc hình thanh: 石 (thạch, đá) biểu nghĩa, 與 (dữ) biểu âm. Nghĩa gốc: thạch tín — loại khoáng vật có độc (arsenolite, arsenic trioxide). Chữ xuất hiện trong y học cổ đại như một chất có độc tính mạnh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thạch tín", "Hạng Tần Suất (Jun Da)": "7545.0", "Tần Suất % (Jun Da)": "99.9986150158", "GavinGrover_Once (Chiết tự trực tiếp)": "與 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱與石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "與", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礜", "Unihan_Traditional (Chữ Phồn thể)": "礜", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "dự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại khoáng vật độc hại trong đông y. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秲', '{"9000": "7546.0", "Chữ Trung Quốc": "秲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 11 | nét | 禾 | hòa | biểu nghĩa | lúa, ngũ cốc | 寺 | tự | biểu âm | chùa (biểu âm) | 秲 = 禾 (Hòa, biểu nghĩa: lúa) + 寺 (Tự, biểu âm); chữ hình thanh. Bộ 禾 chỉ cây lúa, 寺 cho âm đọc zhì/tự.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trĩ\": cây lúa (禾) đứng thẳng — trĩ là lúa đang đòng, mầm hoa nhú lên từ thân cây. | Gương Hán-Việt | Chữ 秲 rất hiếm; bộ 禾 gặp trong: hòa bình, hạt (thóc), nông nghiệp. | Mở khoá kiến thức | Biết 秲 mở ra vốn từ nông nghiệp cổ điển miêu tả các giai đoạn sinh trưởng của lúa.", "Tự nguyên_Xie": "Wiktionary xác nhận cấu trúc hình thanh: 禾 (lúa) biểu nghĩa, 寺 biểu âm. Nghĩa gốc: đòng — thời kỳ cây lúa trổ đòng đòng (trước khi thành hạt). Từ điển Nam Bộ ghi: \"đòng đòng\" (mầm hoa lúa). Chữ rất chuyên biệt, dùng trong nông nghiệp cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đòng; như \"đòng đòng\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 寺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾寺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秲", "Unihan_Traditional (Chữ Phồn thể)": "秲", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "thì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bông lúa non khi còn nằm trong bẹ lá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笗', '{"9000": "7547.0", "Chữ Trung Quốc": "笗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 笗 | đông | tượng hình | đồ vật bằng tre; bộ 竹 | 笗 có bộ 竹 (trúc, tre). Cấu trúc chi tiết chưa được xác định; không có phân tích Wiktionary. Chữ hiếm gặp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đông\": đồ tre (竹) phương đông — hình dung giỏ tre truyền thống. | Gương Hán-Việt | Bộ 竹 gặp trong: trúc lâm (rừng tre), tre trúc. | Mở khoá kiến thức | Biết 笗 giúp nhận dạng nhóm chữ bộ 竹 chỉ đồ dùng làm từ tre.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc trong Wiktionary. Bộ 竹 gợi ý liên quan đến đồ vật làm từ tre. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "笗", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 冬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮冬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笗", "Unihan_Traditional (Chữ Phồn thể)": "笗", "Pinyin_Xie": "dōng", "Âm Hán Việt_Xie": "đông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một giống tre hoặc ống tre dùng trong đời sống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箘', '{"9000": "7548.0", "Chữ Trung Quốc": "箘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 箘 | quân | tượng hình | loại tre làm tên; bộ 竹 | 箘 có bộ 竹 (trúc, tre). Chữ chỉ loại tre đặc biệt dùng để làm mũi tên. Cấu trúc chi tiết chưa được phân tích đầy đủ trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quân\": cây tre (竹) thẳng như mũi tên — quân tử ngay thẳng như tre 箘 dùng làm tên. | Gương Hán-Việt | Bộ 竹 gặp trong: trúc mã (ngựa tre), trúc lâm thất hiền. | Mở khoá kiến thức | Biết 箘 giúp nhận dạng nhóm chữ bộ 竹 chỉ các loài tre đặc dụng trong thủ công cổ.", "Tự nguyên_Xie": "Wiktionary ghi nhận âm đọc và nghĩa: loại tre dùng để làm tên (arrow bamboo); cũng có nghĩa là chồi tre (bamboo shoot). Chữ có hai âm đọc: jùn và jūn. Bộ 竹 biểu nghĩa. Chưa có giải thích nguồn gốc hình thành chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "măng", "Hạng Tần Suất (Jun Da)": "7548.0", "Tần Suất % (Jun Da)": "99.9986227676", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 囷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮囷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "囷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箘", "Unihan_Traditional (Chữ Phồn thể)": "箘", "Pinyin_Xie": "jùn", "Âm Hán Việt_Xie": "duẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ măng non hoặc loại tre nhỏ dùng làm cán tên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箽', '{"9000": "7549.0", "Chữ Trung Quốc": "箽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 15 | nét | 箽 | đổng | tượng hình | đồ đan bằng tre; bộ 竹 | 箽 có bộ 竹 (trúc, tre). Cấu trúc chi tiết chưa được xác định trong Wiktionary. Chữ hiếm gặp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đổng\": rổ tre (竹) dày nặng — như thủ lĩnh (đổng lý) cầm giỏ tre đựng đầy hàng. | Gương Hán-Việt | Bộ 竹 gặp trong: trúc lâm, tre trúc; \"đổng\" gặp trong tên người. | Mở khoá kiến thức | Biết 箽 giúp nhận ra nhóm chữ bộ 竹 chỉ đồ đựng bằng tre.", "Tự nguyên_Xie": "Wiktionary chỉ ghi âm đọc, không có giải thích nguồn gốc. Bộ 竹 gợi ý liên quan đến đồ vật bằng tre. Nghĩa ghi nhận liên quan đến vải dệt (罽). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "罽", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 重", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮重", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "重", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箽", "Unihan_Traditional (Chữ Phồn thể)": "箽", "Pinyin_Xie": "dǒng", "Âm Hán Việt_Xie": "đổng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ đồ dùng đan bằng tre nứa để đựng đồ vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簜', '{"9000": "7550.0", "Chữ Trung Quốc": "簜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 18 | nét | 簜 | thang | tượng hình | tre lớn, tre dày; bộ 竹 | 簜 có bộ 竹 (trúc, tre). Wiktionary ghi nhận âm đọc và nghĩa nhưng không cung cấp phân tích thành phần chi tiết. Nghĩa: tre dày, lớn; cũng chỉ nhạc cụ từ tre lớn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thang\": cây tre (竹) to như thang — 簜 là loại tre lớn, thân rỗng to bản như bậc thang. | Gương Hán-Việt | \"thang\" trong từ ghép Hán-Việt ít thông dụng ở nghĩa này; bộ 竹 gặp trong trúc âm nhạc. | Mở khoá kiến thức | Biết 簜/thang giúp đọc văn học cổ mô tả nhạc cụ dân gian và các loại tre đặc dụng.", "Tự nguyên_Xie": "Wiktionary ghi nhận nghĩa: tre lớn, dày (obs-std); cũng là nhạc cụ làm từ tre lớn. Hai âm đọc: dàng và dong1/dong6. Bộ 竹 biểu nghĩa. Chưa có giải thích nguồn gốc hình thành chữ chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây tre", "Hạng Tần Suất (Jun Da)": "7550.0", "Tần Suất % (Jun Da)": "99.9986274187", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 湯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮湯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "湯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簜", "Unihan_Traditional (Chữ Phồn thể)": "簜", "Pinyin_Xie": "dàng", "Âm Hán Việt_Xie": "đãng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ một loại tre thân to và rỗng dùng trong xây dựng hoặc chế tác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粷', '{"9000": "7551.0", "Chữ Trung Quốc": "粷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 14 | nét | 粷 | cúc | tượng hình | bánh nếp nhân đậu; bộ 米 | 粷 có bộ 米 (mễ, gạo). Cấu trúc chi tiết chưa được xác định; không có phân tích Wiktionary. Nghĩa ghi nhận là loại bánh nếp nhân đậu (theo từ điển Nam Bộ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cúc\": gạo nếp (米) viên tròn như bông cúc — bánh cúc làm từ nếp, nhân đậu xanh tròn xinh. | Gương Hán-Việt | \"cúc\" phương ngữ Nam Bộ; bộ 米 gặp trong: gạo (mễ), tinh, lương thực. | Mở khoá kiến thức | Biết 粷 giúp nhận dạng chữ bộ 米 chỉ loại thực phẩm chế biến từ gạo trong từ điển phương ngữ.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc trong Wiktionary. Bộ 米 gợi ý liên quan đến gạo, thực phẩm từ gạo. Nghĩa ghi nhận: cúc — bánh cúc, một loại bánh nếp nhân đậu (gdhn). Chữ thuộc phương ngữ Nam Bộ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cúc; như \"bánh cúc (một loại bánh nếp nhân đậu)\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 匊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米匊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粷", "Unihan_Traditional (Chữ Phồn thể)": "粷", "Pinyin_Xie": "jú", "Âm Hán Việt_Xie": "cúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ men làm rượu hoặc một loại bánh nếp truyền thống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('緷', '{"9000": "7552.0", "Chữ Trung Quốc": "緷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 15 | nét | 緷 | uẩn | tượng hình | dây, sợi bện; bộ 糸 | 緷 thuộc bộ 糸 (mịch, sợi/tơ). Wiktionary chỉ ghi nhận âm đọc, không có phân tích thành phần. Bộ 糸 biểu nghĩa (sợi/dây). Chữ rất hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uẩn\": sợi tơ (糸) quấn chứa (uẩn = ẩn chứa) — dây bện chứa đựng sức mạnh bên trong. | Gương Hán-Việt | \"uẩn\" trong: uẩn khúc (chứa đựng điều khuất lấp); bộ 糸 gặp trong tơ lụa. | Mở khoá kiến thức | Biết 緷 giúp nhận dạng nhóm chữ bộ 糸 chỉ loại dây bện trong thủ công cổ.", "Tự nguyên_Xie": "Wiktionary chỉ ghi âm đọc (yùn, wan6, gwan2) và tham chiếu MFCCD. Không có giải thích nguồn gốc. Bộ 糸 gợi ý liên quan đến sợi dây. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "緷", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 軍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹軍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "軍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "緷", "Unihan_Traditional (Chữ Phồn thể)": "緷", "Pinyin_Xie": "yùn", "Âm Hán Việt_Xie": "uẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ các loại dây buộc hoặc đường viền trang trí trên trang phục cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繉', '{"9000": "7553.0", "Chữ Trung Quốc": "繉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 17 | nét | 繉 | hồn | tượng hình | sợi lẫn lộn; bộ 糸 | 繉 thuộc bộ 糸 (mịch, sợi/tơ). Không có phân tích thành phần trong Wiktionary. Bộ 糸 biểu nghĩa (sợi/dây). Chữ rất hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồn\": sợi tơ (糸) hỗn độn — hồn là hỗn hợp lẫn lộn, như sợi chỉ rối không gỡ được. | Gương Hán-Việt | Bộ 糸 gặp trong tơ lụa; \"hồn\" trong: hồn loạn, hỗn độn. | Mở khoá kiến thức | Biết 繉 giúp nhận dạng chữ bộ 糸 chỉ trạng thái sợi rối loạn.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc trong Wiktionary. Bộ 糸 gợi ý liên quan đến sợi dây, tơ lụa. Nghĩa ghi nhận: hình ảnh (có thể chỉ sự lẫn lộn của sợi). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hình ảnh", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 眺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹眺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "眺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "繉", "Unihan_Traditional (Chữ Phồn thể)": "繉", "Pinyin_Xie": "hún", "Âm Hán Việt_Xie": "hồn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ trong văn ngôn để chỉ các loại dây buộc hoặc dải mũ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繙', '{"9000": "7554.0", "Chữ Trung Quốc": "繙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 18 | nét | 繙 | phiên | tượng hình | phiên dịch, phấp phới; bộ 糸 | 繙 thuộc bộ 糸 (mịch, sợi/tơ). Không có phân tích thành phần chi tiết trong Wiktionary. Nghĩa gốc: lật qua, phiên dịch; cũng có nghĩa phấp phới (cờ bay). Bộ 糸 gợi ý liên quan đến sợi dây/vải.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiên\": sợi vải (糸) lật qua lật lại — phiên dịch là lật nghĩa từ ngôn ngữ này sang ngôn ngữ khác. | Gương Hán-Việt | \"phiên dịch\" (dịch thuật), \"phiên âm\" — bộ 糸 gặp trong tơ lụa. | Mở khoá kiến thức | Biết 繙/phiên mở ra: phiên dịch, phiên âm, phiên bản trong ngữ văn học.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc trong Wiktionary. Bộ 糸 (sợi) biểu nghĩa, gợi ý hành động cuộn/lật sợi hay vải. Nghĩa mở rộng sang phiên dịch (lật qua ngôn ngữ khác) và cờ phấp phới. Chữ truyền thống. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phấp phới; phiên dịch", "Hạng Tần Suất (Jun Da)": "7554.0", "Tần Suất % (Jun Da)": "99.9986382712", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 番", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹番", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "番", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "繙", "Unihan_Traditional (Chữ Phồn thể)": "繙", "Pinyin_Xie": "fān", "Âm Hán Việt_Xie": "phiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn bản cổ với nghĩa là dịch sách hoặc lật giở trang giấy. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罁', '{"9000": "7555.0", "Chữ Trung Quốc": "罁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 缶 | Số nét | 14 | nét | 罁 | cương | tượng hình | chum, vại đất (bộ 缶) | 罁 thuộc bộ 缶 (phẫu, đồ đựng bằng đất nung). Cấu trúc chi tiết chưa được xác định trong Wiktionary. Bộ 缶 biểu nghĩa chỉ đồ gốm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cương\": cái chum đất (缶) cứng rắn — vại gốm nung chắc chắn, kiên cố. | Gương Hán-Việt | Bộ 缶 gặp trong: 缸 (gang, chum lớn), 罐 (quán, bình). | Mở khoá kiến thức | Biết 罁 giúp nhận dạng nhóm chữ bộ 缶 chỉ đồ gốm sứ trong văn bản cổ.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc trong Wiktionary. Bộ 缶 (đồ đựng bằng đất nung) biểu nghĩa. Chữ rất hiếm, có thể chỉ một loại vại/chum đất nung. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "灁", "Hạng Tần Suất (Jun Da)": "7555.0", "Tần Suất % (Jun Da)": "99.9986398215", "GavinGrover_Once (Chiết tự trực tiếp)": "缶 + 岡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰缶岡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "岡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "缶", "Unihan_Simplified (Chữ Giản thể)": "罁", "Unihan_Traditional (Chữ Phồn thể)": "罁", "Pinyin_Xie": "gāng", "Âm Hán Việt_Xie": "cương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loại đồ chứa bằng đất nung như chum, vại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羇', '{"9000": "7556.0", "Chữ Trung Quốc": "羇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 22 | nét | 羇 | ki | tượng hình | dây cương ngựa; ở trọ, giam giữ; bộ 网 | 羇 có bộ 网 (võng, lưới). Chữ là dị thể của 羈, chỉ dây cương ngựa; sau mở rộng sang nghĩa giam cầm, ở trọ (bị ràng buộc). Cấu trúc chi tiết chưa được phân tích đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ki\": dây lưới (网) buộc chặt — ki là giam cầm, ràng buộc, ở trọ xa nhà như bị xích. | Gương Hán-Việt | \"羇旅\" (kẻ tha hương), \"羇縻\" (ràng buộc) trong thơ cổ. | Mở khoá kiến thức | Biết 羇/ki giúp đọc thơ cổ chủ đề tha hương: 羇旅, 羇縻, người lữ thứ ở trọ.", "Tự nguyên_Xie": "Wiktionary ghi 羇 là dạng thay thế của 羈 (ký nghĩa: dây cương; giam cầm; ở nhờ). Nghĩa gốc liên quan đến buộc, ràng — cả người lẫn ngựa. Thường thấy trong thành ngữ 羇旅 (kẻ ở trọ, người xa quê). Chưa có giải thích nguồn gốc chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ở nhờ, ở gửi, ở trọ", "Hạng Tần Suất (Jun Da)": "7556.0", "Tần Suất % (Jun Da)": "99.9986429222", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + 䩭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒䩭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䩭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "羇", "Unihan_Traditional (Chữ Phồn thể)": "羇", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "ki", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ sự ràng buộc hoặc trạng thái đi chơi xa, lưu lạc nơi đất khách. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聣', '{"9000": "7557.0", "Chữ Trung Quốc": "聣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 14 | nét | 聣 | nghê | tượng hình | điếc, cứng tai; bộ 耳 | 聣 có bộ 耳 (nhĩ, tai). Không có phân tích thành phần trong Wiktionary. Bộ 耳 biểu nghĩa (liên quan đến thính giác). Chữ rất hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghê\": đôi tai (耳) không nghe — nghê như con ngựa kỳ lân (nghê) không cần nghe lời ai. | Gương Hán-Việt | Bộ 耳 gặp trong: nhĩ (tai), thính giác, lãng tai. | Mở khoá kiến thức | Biết 聣 giúp nhận dạng chữ bộ 耳 chỉ trạng thái thính giác bất thường.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc trong Wiktionary. Bộ 耳 gợi ý liên quan đến tai/thính giác. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "聣", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 兒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳兒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聣", "Unihan_Traditional (Chữ Phồn thể)": "聣", "Pinyin_Xie": "ní", "Âm Hán Việt_Xie": "nghê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ trong văn ngôn để chỉ hành động liếc mắt nhìn nghiêng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脙', '{"9000": "7558.0", "Chữ Trung Quốc": "脙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 肉 | nhục | biểu nghĩa | thịt, cơ thể | 求 | cầu | biểu âm | biểu âm gần xiū | 脙 = 肉 (Nhục, biểu nghĩa: thịt) + 求 (Cầu, biểu âm); chữ hình thanh. Bộ 肉 chỉ phần cơ thể, 求 cho âm đọc gần xiū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tu\": phần thịt (肉) mỡ béo — tu là gàu, phần bụng bò nhiều mỡ ngon béo trong tô phở. | Gương Hán-Việt | Bộ 肉 gặp trong: nhục (thịt), cơ thể; \"tu\" ít thông dụng trong Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 脙 giúp đọc từ điển ẩm thực phương ngữ Nam Bộ miêu tả các phần thịt bò.", "Tự nguyên_Xie": "Wiktionary xác nhận cấu trúc hình thanh: 肉 (thịt) biểu nghĩa, 求 biểu âm. Nghĩa ghi nhận trong từ điển Nam Bộ: gàu — như trong \"phở gàu\", \"gầu\" (phần thịt bụng bò có mỡ). Âm đọc xiū. Chữ dùng trong từ điển phương ngữ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gàu; như \"phở gàu\" (gdhn) gầu (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 求", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月求", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "求", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脙", "Unihan_Traditional (Chữ Phồn thể)": "脙", "Pinyin_Xie": "xiū", "Âm Hán Việt_Xie": "tu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ để miêu tả dáng vẻ gầy gò hoặc làm danh từ chỉ thịt khô. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脻', '{"9000": "7559.0", "Chữ Trung Quốc": "脻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 脻 | giai | tượng hình | khớp cơ thể; bộ 肉 | 脻 có bộ 肉 (nhục, thịt/cơ thể). Cấu trúc chi tiết chưa được xác định trong Wiktionary. Bộ 肉 biểu nghĩa (bộ phận cơ thể). Chữ rất hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giai\": bộ phận thân thể (肉) giao nhau — giai như giao tiếp, khớp xương nơi hai phần gặp nhau. | Gương Hán-Việt | Bộ 肉 gặp trong: nhục thể, cơ bắp; \"giai\" ít thông dụng. | Mở khoá kiến thức | Biết 脻 giúp nhận dạng chữ bộ 肉 trong y văn cổ mô tả khớp cơ thể.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc trong Wiktionary. Bộ 肉 gợi ý liên quan đến bộ phận cơ thể. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "軻", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 疌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月疌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "疌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脻", "Unihan_Traditional (Chữ Phồn thể)": "脻", "Pinyin_Xie": "jiē", "Âm Hán Việt_Xie": "giai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong y học cổ truyền hoặc văn thơ để chỉ lông mi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脼', '{"9000": "7560.0", "Chữ Trung Quốc": "脼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 脼 | lưỡng | tượng hình | hai bên thịt sườn; bộ 肉 | 脼 có bộ 肉 (nhục, thịt). Cấu trúc chi tiết chưa được xác định trong Wiktionary. Bộ 肉 biểu nghĩa. Chữ rất hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưỡng\": hai phần thịt (肉) sườn đối xứng — lưỡng là hai, hai bên. | Gương Hán-Việt | \"lưỡng\" trong: lưỡng lự (do dự), song lưỡng (hai bên); bộ 肉 gặp trong nhục thể. | Mở khoá kiến thức | Biết 脼 giúp nhận dạng chữ bộ 肉 trong y văn cổ miêu tả hai phần cơ thể đối xứng.", "Tự nguyên_Xie": "Wiktionary chỉ ghi âm đọc, không có giải thích nguồn gốc. Bộ 肉 gợi ý liên quan đến thịt. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "脼", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "𣍷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: me", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "𣍷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "脼", "Unihan_Traditional (Chữ Phồn thể)": "脼", "Pinyin_Xie": "liǎng", "Âm Hán Việt_Xie": "lưỡng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong văn ngôn để chỉ các loại thịt ướp gia vị hoặc thịt khô. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腗', '{"9000": "7561.0", "Chữ Trung Quốc": "腗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 腗 | tỳ | tượng hình | phần thịt; bộ 肉 | 腗 có bộ 肉 (nhục, thịt). Cấu trúc chi tiết chưa được xác định trong Wiktionary. Bộ 肉 biểu nghĩa. Chữ rất hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỳ\": phần thịt (肉) tỳ vào — tỳ vị (脾胃) liên quan đến tiêu hóa, phần thịt nội tạng. | Gương Hán-Việt | \"tỳ\" trong: tỳ vị (lá lách và dạ dày); bộ 肉 gặp trong nhục thể, cơ quan nội tạng. | Mở khoá kiến thức | Biết 腗 giúp nhận dạng chữ bộ 肉 trong y văn cổ miêu tả các cơ quan.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc trong Wiktionary. Bộ 肉 gợi ý liên quan đến thịt/cơ thể. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "藗", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 畁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月畁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腗", "Unihan_Traditional (Chữ Phồn thể)": "腗", "Pinyin_Xie": "pí", "Âm Hán Việt_Xie": "tỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ chỉ cơ quan tiêu hóa hoặc tính từ chỉ trạng thái béo tốt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艜', '{"9000": "7562.0", "Chữ Trung Quốc": "艜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 17 | nét | 艜 | đãi | tượng hình | tàu thuyền dài hẹp; bộ 舟 | 艜 có bộ 舟 (chu, thuyền). Cấu trúc chi tiết chưa được xác định trong Wiktionary ngoài âm đọc. Bộ 舟 biểu nghĩa (thuyền bè). Wiktionary ghi nhận là một tàu dài hẹp với hai cột buồm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đãi\": con thuyền (舟) mỏng dài — đãi như chờ đợi, con thuyền dài chờ gió thuận mà dong buồm. | Gương Hán-Việt | Bộ 舟 gặp trong: thuyền bè (chu du), hàng hải. | Mở khoá kiến thức | Biết 艜 giúp đọc văn học hàng hải cổ miêu tả các loại thuyền đặc dụng.", "Tự nguyên_Xie": "Wiktionary ghi nhận âm đọc dài và nghĩa: tàu dài hẹp với hai cột buồm. Bộ 舟 biểu nghĩa. Chưa có giải thích nguồn gốc hình thành chữ chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một con tàu dài hẹp với hai cột buồm", "Hạng Tần Suất (Jun Da)": "7562.0", "Tần Suất % (Jun Da)": "99.9986553251", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 帶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟帶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艜", "Unihan_Traditional (Chữ Phồn thể)": "艜", "Pinyin_Xie": "dài", "Âm Hán Việt_Xie": "đại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò là danh từ chỉ một loại thuyền nhỏ và dài thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葘', '{"9000": "7563.0", "Chữ Trung Quốc": "葘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葘 | tai | tượng hình | ruộng bỏ hoang năm đầu; bộ 艸 | 葘 có bộ 艸 (thảo, cỏ/thực vật). Cấu trúc chi tiết chưa được xác định trong Wiktionary. Bộ 艸 biểu nghĩa gợi ý liên quan đến thực vật/ruộng đất. Chữ rất hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tai\": cánh đồng cỏ (艸) bị tai hoạ bỏ hoang — ruộng hoang như tai ương, để cỏ mọc lấp đầy. | Gương Hán-Việt | \"tai\" trong: tai hoạ, tai họa; bộ 艸 gặp trong thảo mộc. | Mở khoá kiến thức | Biết 葘 giúp đọc văn bản nông nghiệp cổ miêu tả các giai đoạn khai hoang ruộng đất.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc trong Wiktionary. Bộ 艸 gợi ý liên quan đến cây cỏ, ruộng đất. Nghĩa ghi nhận có thể liên quan đến ruộng bỏ hoang (fallow field). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "葘", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "葘", "Unihan_Traditional (Chữ Phồn thể)": "葘", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ ruộng hoang mới vỡ hoặc động từ chỉ việc phát hoang làm ruộng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葢', '{"9000": "7564.0", "Chữ Trung Quốc": "葢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葢 | cái | tượng hình | nắp đậy, che phủ; bộ 艸 | 葢 có bộ 艸 (thảo, cỏ/thực vật). Là dạng cổ/biến thể của 蓋 (cái, nắp đậy). Bộ 艸 gợi ý lá cỏ dùng để che phủ. Cấu trúc chi tiết chưa được phân tích đầy đủ trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cái\": cỏ (艸) che phủ lên trên — cái (nắp đậy) như lá cỏ che kín, giữ nhiệt giữ độ ẩm. | Gương Hán-Việt | \"cái thế\" (hơn cả thế gian), \"bao cái\" (che phủ toàn bộ) trong thơ cổ. | Mở khoá kiến thức | Biết 葢/cái (biến thể 蓋) giúp đọc văn bản cổ: cái thế anh hùng, thiên cái (mái trời).", "Tự nguyên_Xie": "Wiktionary ghi nhận 葢 là biến thể cổ của 蓋 (gài), xem 盖. Nghĩa gốc của 蓋/葢: nắp đậy, che phủ (từ hình ảnh lá cỏ che phủ). Không có dữ liệu nguồn gốc riêng cho 葢. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem \"盖\"", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 盇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹盇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "盇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葢", "Unihan_Traditional (Chữ Phồn thể)": "葢", "Pinyin_Xie": "gài", "Âm Hán Việt_Xie": "cái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Phó từ | 副词 | Thường dùng làm động từ che đậy hoặc danh từ chỉ cái nắp, cái vung. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藘', '{"9000": "7565.0", "Chữ Trung Quốc": "藘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 藘 | lư | tượng hình | cây lư (cây mặt trời đỏ, Rubia cordifolia) | 藘 là chữ độc lập, không phân tích được thành các thành phần IDS rõ ràng trong dữ liệu hiện có. Theo ngữ cảnh, đây là tên một loài thực vật (cây nhuộm đỏ họ Rubiaceae), có thể là biến thể hay ký tự chuyên dùng cho loài cây 茹藘.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lư\": cây 藘 cùng họ với 茹 (nhai/ăn) — người xưa ''ăn'' màu đỏ từ rễ cây lư để nhuộm vải. | Gương Hán-Việt | lư trong ''lư thứ'' (cây lư), ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 藘 giúp nhận ra tổ hợp 茹藘 trong văn thơ cổ Trung Quốc chỉ cây nhuộm đỏ.", "Tự nguyên_Xie": "Không có cấu trúc hán tự kép rõ ràng từ nguồn Wiktionary. 藘 xuất hiện chủ yếu trong tổ hợp 茹藘 (cây mặt trời đỏ, madder — Rubia cordifolia), dùng làm thuốc nhuộm đỏ trong thời cổ. Chưa có nguồn học thuật về cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xe: như lư 茹藘)", "Hạng Tần Suất (Jun Da)": "7565.0", "Tần Suất % (Jun Da)": "99.9986646272", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 慮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹慮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "慮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藘", "Unihan_Traditional (Chữ Phồn thể)": "藘", "Pinyin_Xie": "lǘ", "Âm Hán Việt_Xie": "lư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong từ ghép để chỉ một loại thảo dược dùng làm thuốc nhuộm màu đỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛬', '{"9000": "7566.0", "Chữ Trung Quốc": "蛬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 蛬 | củng | tượng hình | con dế (cricket) | 蛬 là chữ cổ không phân rã IDS rõ ràng. Theo ngữ âm học lịch sử, có thể liên quan đến bộ 虫 (trùng) nhưng cấu trúc không xác định trong dữ liệu. Đây là dạng cổ của 蛩 (con dế), cũng đọc là gǒng/qióng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"củng\": 蛬 là con dế cổ đại — tiếng kêu ''củng củng'' vang trong đêm như âm thanh thời xưa. | Gương Hán-Việt | củng, ít dùng trong tiếng Việt hiện đại; dạng thông dụng hơn là 蛩 | Mở khoá kiến thức | Biết 蛬 giúp đọc văn chương cổ Trung Quốc nơi dùng chữ này thay cho 蟋蟀 (con dế).", "Tự nguyên_Xie": "Không có cấu trúc han tự kép từ nguồn Wiktionary. 蛬 là dạng cổ chỉ con dế (cricket), đồng nghĩa với 蟋蟀. Cũng là dị thể của 蛩 (qióng/gǒng). Chưa có nguồn học thuật về tự hình chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dế; con dế; dế mèn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "共 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱共虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "共", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛬", "Unihan_Traditional (Chữ Phồn thể)": "蛬", "Pinyin_Xie": "qióng", "Âm Hán Việt_Xie": "cung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ con dế mèn trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螁', '{"9000": "7567.0", "Chữ Trung Quốc": "螁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 螁 | bán | tượng hình | loài côn trùng (không xác định rõ) | 螁 không có cấu trúc IDS hay glyph origin trong dữ liệu hiện có. Đây là ký tự cực hiếm, không có thông tin từ Wiktionary. Có thể liên quan đến bộ 虫 (trùng) nhưng không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bán\": 螁 là loài côn trùng không rõ tên — chỉ biết nó mang âm ''bán'' và thuộc thế giới sâu bọ. | Gương Hán-Việt | bán, không dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | 螁 là ký tự học thuật dùng để nghiên cứu chữ Hán cổ hiếm gặp.", "Tự nguyên_Xie": "Không có dữ liệu tự hình từ bất kỳ nguồn nào. 螁 là ký tự cực hiếm, xuất hiện trong từ điển cổ nhưng không có giải thích cấu trúc. Chưa có nguồn học thuật về tự hình. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "螞", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 退", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫退", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "退", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螁", "Unihan_Traditional (Chữ Phồn thể)": "螁", "Pinyin_Xie": "ban", "Âm Hán Việt_Xie": "bán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ sự lột xác của côn trùng hoặc danh từ chỉ lớp vỏ đã lột. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螚', '{"9000": "7568.0", "Chữ Trung Quốc": "螚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 能 | năng | biểu âm | có thể, tài năng | 虫 | trùng | biểu nghĩa | côn trùng | 螚 = 虫 (Trùng, biểu nghĩa: côn trùng) + 能 (Năng, biểu âm); chữ hình thanh. Bộ 虫 xác định đây là loài côn trùng, 能 (năng) cung cấp âm đọc gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nại\": con 虫 mang sức 能 (năng lực) — loài ruồi nhỏ đốt ngứa đòi hỏi sức chịu đựng (nại nhẫn). | Gương Hán-Việt | nại, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 螚 giúp đọc văn bản cổ điển về côn trùng học Trung Hoa.", "Tự nguyên_Xie": "Chữ hình thanh: bộ 虫 (côn trùng) biểu nghĩa, 能 biểu âm. 螚 là tên cổ chỉ loài ruồi nhỏ (gadfly) hoặc các loài côn trùng giống ong và ong vẽ. Không có hình ảnh tự hình trong dữ liệu. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Eristalis tenax", "Hạng Tần Suất (Jun Da)": "7568.0", "Tần Suất % (Jun Da)": "99.998672379", "GavinGrover_Once (Chiết tự trực tiếp)": "能 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱能虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "能", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螚", "Unihan_Traditional (Chữ Phồn thể)": "螚", "Pinyin_Xie": "nài", "Âm Hán Việt_Xie": "năng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài côn trùng giống con ong trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螤', '{"9000": "7569.0", "Chữ Trung Quốc": "螤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 螤 | trung | tượng hình | loài côn trùng (không xác định) | 螤 không có cấu trúc IDS hay glyph origin trong dữ liệu hiện có. Đây là ký tự cực hiếm không có thông tin tự hình. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trung\": 螤 là loài sâu bọ mang âm ''trung'' — ký tự học thuật dùng trong nghiên cứu chữ Hán cổ. | Gương Hán-Việt | trung, không dùng trong tiếng Việt hiện đại với nghĩa này | Mở khoá kiến thức | 螤 là ký tự nghiên cứu trong ngữ văn học Hán Nôm cổ đại.", "Tự nguyên_Xie": "Không có dữ liệu tự hình từ bất kỳ nguồn học thuật nào. 螤 là ký tự cực hiếm. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "褤", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "蚉 + 㬰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰蚉㬰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㬰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "蚉", "Unihan_Simplified (Chữ Giản thể)": "螤", "Unihan_Traditional (Chữ Phồn thể)": "螤", "Pinyin_Xie": "zhōng", "Âm Hán Việt_Xie": "trung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần vạt áo hoặc loại áo dài thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袇', '{"9000": "7570.0", "Chữ Trung Quốc": "袇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 9 | nét | 袇 | nhiêm | tượng hình | loại trang phục (không rõ) | 袇 không có cấu trúc IDS hay glyph origin. Đây là ký tự cực hiếm thuộc bộ 衣 (y phục). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhiêm\": bộ 衣 (y phục) — 袇 là một loại áo cổ đọc âm ''nhiêm'', nay gần như không dùng. | Gương Hán-Việt | nhiêm, không dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | 袇 là ký tự học thuật trong nghiên cứu trang phục cổ Trung Hoa.", "Tự nguyên_Xie": "Không có dữ liệu tự hình từ nguồn học thuật. 袇 thuộc bộ 衣 (y phục), pinyin là rán, có thể liên quan đến một loại trang phục cổ tên gọi địa danh ''Ninh''. Chưa có nguồn học thuật về cấu trúc. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Ninh", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 丹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤丹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袇", "Unihan_Traditional (Chữ Phồn thể)": "袇", "Pinyin_Xie": "rán", "Âm Hán Việt_Xie": "nhiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ trang phục nghi lễ thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袌', '{"9000": "7571.0", "Chữ Trung Quốc": "袌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 11 | nét | 袌 | bão | tượng hình | ôm ấp, bế (liên quan y phục/vòng ôm) | 袌 không có cấu trúc IDS rõ ràng trong dữ liệu. Thuộc bộ 衣 (y phục). Wiktionary có phát âm (bào) nhưng không giải thích cấu trúc tự hình. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bão\": bộ 衣 (áo) + âm ''bão'' — chiếc áo choàng BAO bọc, ôm ấp người mặc. | Gương Hán-Việt | bão, không dùng phổ biến trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 袌 giúp đọc văn bản cổ điển về trang phục và cử chỉ ôm bế trong văn hóa Hán.", "Tự nguyên_Xie": "Không có cấu trúc han tự kép từ nguồn Wiktionary (chỉ có {{rfdef|zh}}). 袌 thuộc bộ 衣 (y phục), nghĩa là ''ôm ấp, bế, vừa khít''. Có thể liên quan đến 抱 (ôm) cùng âm bào. Chưa có nguồn học thuật về cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ôm ấp, bế; ấp ủ; vừa khít, khớp", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衣 + 包", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴衣包", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "包", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "袌", "Unihan_Traditional (Chữ Phồn thể)": "袌", "Pinyin_Xie": "bào", "Âm Hán Việt_Xie": "bão", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động ôm giữ hoặc làm danh từ chỉ vạt áo trước. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袔', '{"9000": "7572.0", "Chữ Trung Quốc": "袔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袔 | hạc | tượng hình | áo choàng (loại trang phục cổ) | 袔 không có cấu trúc IDS rõ ràng. Thuộc bộ 衣 (y phục), pinyin là hè. Wiktionary chỉ có {{rfdef|zh}}, không giải thích cấu trúc. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạc\": bộ 衣 (áo) mang âm ''hạc'' — chiếc áo choàng trắng như HẠC bay. | Gương Hán-Việt | hạc, không dùng phổ biến trong tiếng Việt với nghĩa y phục | Mở khoá kiến thức | 袔 là ký tự học thuật về trang phục cổ Trung Hoa.", "Tự nguyên_Xie": "Không có cấu trúc han tự kép từ nguồn Wiktionary. 袔 thuộc bộ 衣 (y phục), nghĩa là ''áo choàng, mantle''. Chưa có nguồn học thuật về cấu trúc tự hình. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo choàng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 可", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤可", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "可", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袔", "Unihan_Traditional (Chữ Phồn thể)": "袔", "Pinyin_Xie": "hè", "Âm Hán Việt_Xie": "hạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại áo khoác ngoài thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袦', '{"9000": "7573.0", "Chữ Trung Quốc": "袦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袦 | nạp | tượng hình | loại y phục cổ (không xác định rõ) | 袦 không có cấu trúc IDS. Thuộc bộ 衣 (y phục), pinyin là nà. Wiktionary chỉ có {{rfdef|zh}}. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nạp\": bộ 衣 (áo) + âm ''nạp'' — loại áo NẠP (nhận vào, thu nạp) dùng trong nghi lễ cổ. | Gương Hán-Việt | nạp, không dùng với nghĩa y phục trong tiếng Việt hiện đại | Mở khoá kiến thức | 袦 là ký tự học thuật trong nghiên cứu trang phục và văn hóa Hán cổ.", "Tự nguyên_Xie": "Không có cấu trúc han tự kép từ nguồn học thuật. 袦 thuộc bộ 衣 (y phục), nghĩa không xác định rõ. Chưa có nguồn học thuật về cấu trúc tự hình. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "袦", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 出", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤出", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "出", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袦", "Unihan_Traditional (Chữ Phồn thể)": "袦", "Pinyin_Xie": "nà", "Âm Hán Việt_Xie": "nạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại áo mặc sát thân người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袨', '{"9000": "7574.0", "Chữ Trung Quốc": "袨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袨 | huyền | tượng hình | loại trang phục màu tối/đen cổ đại | 袨 không có cấu trúc IDS. Thuộc bộ 衣 (y phục), pinyin là xuàn. Wiktionary chỉ có {{rfdef|zh}}. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyền\": bộ 衣 (áo) + âm ''huyền'' — loại áo HUYỀN bí màu tối của quý tộc cổ đại. | Gương Hán-Việt | huyền, không dùng với nghĩa y phục trong tiếng Việt | Mở khoá kiến thức | 袨 là ký tự học thuật trong nghiên cứu y phục quý tộc Hán cổ.", "Tự nguyên_Xie": "Không có cấu trúc han tự kép từ nguồn học thuật. 袨 thuộc bộ 衣 (y phục). Nghĩa không xác định rõ trong nguồn hiện đại. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "袨", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 玄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤玄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "玄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袨", "Unihan_Traditional (Chữ Phồn thể)": "袨", "Pinyin_Xie": "xuàn", "Âm Hán Việt_Xie": "huyền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ trang phục màu đen hoặc tính từ chỉ sự lộng lẫy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('覂', '{"9000": "7575.0", "Chữ Trung Quốc": "覂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 襾 | Số nét | 10 | nét | 覂 | phủng | tượng hình | lật đổ, thiếu hụt | 覂 không có cấu trúc IDS rõ ràng trong dữ liệu. Thuộc bộ 襾 (tây — nắp đậy). Wiktionary có định nghĩa (overturn, topple) nhưng không giải thích tự hình. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phủng\": bộ 襾 (nắp) bị PHỦNG (lật) — hình ảnh cái nắp bị hất tung, lật đổ. | Gương Hán-Việt | phủng, không dùng phổ biến trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 覂 giúp đọc văn ngôn cổ điển có các từ 覂駕, 覂竭, 覂軌.", "Tự nguyên_Xie": "Không có cấu trúc han tự kép từ nguồn Wiktionary. 覂 thuộc bộ 襾, có nghĩa văn ngôn là ''lật đổ, nghiêng đổ, thiếu hụt''. Xuất hiện trong các tổ hợp 覂駕 (lật xe ngựa), 覂竭 (cạn kiệt). Chưa có nguồn học thuật về tự hình. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đổ xuống; lật đổ; thiếu; thiếu hụt; không đủ", "Hạng Tần Suất (Jun Da)": "7575.0", "Tần Suất % (Jun Da)": "99.9986832315", "GavinGrover_Once (Chiết tự trực tiếp)": "覀 + 乏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱覀乏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "覀", "Unihan_Simplified (Chữ Giản thể)": "覂", "Unihan_Traditional (Chữ Phồn thể)": "覂", "Pinyin_Xie": "fěng", "Âm Hán Việt_Xie": "phủng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ hành động lật úp hoặc tính từ chỉ trạng thái thiếu thốn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訋', '{"9000": "7576.0", "Chữ Trung Quốc": "訋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 訋 | điệu | tượng hình | ký tự Hán cổ hiếm thuộc bộ ngôn | 訋 không có cấu trúc IDS hay glyph origin. Thuộc bộ 言 (ngôn), pinyin là diào. Không có dữ liệu Wiktionary. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệu\": bộ 言 (lời) + âm ''điệu'' — một loại lời nói hay văn phong ĐIỆU đà, nay ít dùng. | Gương Hán-Việt | điệu, không dùng với nghĩa ngôn ngữ trong tiếng Việt hiện đại | Mở khoá kiến thức | 訋 là ký tự nghiên cứu trong ngữ văn học Hán cổ.", "Tự nguyên_Xie": "Không có dữ liệu tự hình từ bất kỳ nguồn học thuật nào. 訋 thuộc bộ 言 (ngôn ngữ). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "訋", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 勺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言勺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "訋", "Unihan_Traditional (Chữ Phồn thể)": "訋", "Pinyin_Xie": "diào", "Âm Hán Việt_Xie": "điệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ việc nói năng lộn xộn hoặc tính từ miêu tả sự ồn ào. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詻', '{"9000": "7577.0", "Chữ Trung Quốc": "詻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 13 | nét | 詻 | ngạc | tượng hình | mệnh lệnh nghiêm, tranh luận thẳng thắn | 詻 không có cấu trúc IDS rõ ràng từ dữ liệu. Thuộc bộ 言 (ngôn), pinyin là è. Wiktionary chỉ nói ''{{zh-used|詻詻}}'' (dùng trong từ ghép 詻詻). Có kim văn và tiểu triện trong dữ liệu hình ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạc\": bộ 言 (lời) + âm ''ngạc'' — lời nói NGẠC nhiên, thẳng thắn, mạnh mẽ như mệnh lệnh. | Gương Hán-Việt | ngạc trong ''kinh ngạc'', nhưng 詻 mang nghĩa nghiêm khắc không liên quan | Mở khoá kiến thức | Biết 詻 giúp đọc văn ngôn cổ có tổ hợp 詻詻 (lời nghiêm, thẳng thắn).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Không có cấu trúc han tự kép từ nguồn Wiktionary. 詻 dùng trong từ ghép 詻詻 với nghĩa mệnh lệnh nghiêm khắc, tranh luận thẳng thắn. Có kim văn (Chiến quốc) và tiểu triện trong dữ liệu, cho thấy chữ khá cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mệnh lệnh nghiêm; nghiêm túc; tranh luận thẳng thắn", "Hạng Tần Suất (Jun Da)": "7577.0", "Tần Suất % (Jun Da)": "99.9986925336", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 各", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "詻", "Unihan_Traditional (Chữ Phồn thể)": "詻", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ chỉ thái độ nghiêm nghị hoặc động từ chỉ việc tranh cãi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('譃', '{"9000": "7578.0", "Chữ Trung Quốc": "譃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 18 | nét | 言 | ngôn | biểu nghĩa | lời nói | 虛 | hư | biểu âm | trống rỗng, hư không | 譃 = 言 (Ngôn, biểu nghĩa: lời nói) + 虛 (Hư, biểu âm); chữ hình thanh. Bộ 言 chỉ đây là lời nói, 虛 (hư — trống rỗng) cung cấp âm và gợi ý nghĩa: lời nói HƯ (rỗng tuếch) tức là lời nói dối.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hư\": 言 (lời) + 虛 (hư rỗng) — lời HƯ (rỗng không thật) chính là lời dối trá — 譃. | Gương Hán-Việt | hư trong ''hư ngôn'' (lời nói dối), ''hư cấu'' (hư cấu) | Mở khoá kiến thức | Biết 譃 giúp hiểu từ nguyên: lời nói (言) hư rỗng (虛) = lời dối trá.", "Tự nguyên_Xie": "Chữ hình thanh: bộ 言 (lời nói) biểu nghĩa, 虛 biểu âm. 譃 có nghĩa là ''nói dối, nói láo''. Cấu trúc ngữ nghĩa-âm thanh phản ánh trực tiếp: lời nói (言) mà hư (虛) — tức lời dối trá. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "胃", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 虚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言虚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "譃", "Unihan_Traditional (Chữ Phồn thể)": "譃", "Pinyin_Xie": "xū", "Âm Hán Việt_Xie": "hư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chủ yếu dùng làm động từ chỉ hành vi nói năng không chân thật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('譄', '{"9000": "7579.0", "Chữ Trung Quốc": "譄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 19 | nét | 譄 | tăng | tượng hình | ký tự Hán cổ hiếm thuộc bộ ngôn | 譄 không có cấu trúc IDS. Thuộc bộ 言 (ngôn), pinyin là zēng. Wiktionary chỉ có {{rfdef|zh}}. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tăng\": bộ 言 (lời) mang âm ''tăng'' — lời nói TĂNG thêm, thuộc về ngôn ngữ học cổ. | Gương Hán-Việt | tăng, không dùng phổ biến trong tiếng Việt với nghĩa này | Mở khoá kiến thức | 譄 là ký tự nghiên cứu trong ngữ văn học Hán cổ.", "Tự nguyên_Xie": "Không có cấu trúc han tự kép từ nguồn học thuật. 譄 thuộc bộ 言, nghĩa không xác định rõ. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "脄", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 曾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言曾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "譄", "Unihan_Traditional (Chữ Phồn thể)": "譄", "Pinyin_Xie": "zēng", "Âm Hán Việt_Xie": "tăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ để chỉ hành vi vu khống hoặc đổ oan cho người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('賰', '{"9000": "7580.0", "Chữ Trung Quốc": "賰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 16 | nét | 貝 | bối | biểu nghĩa | vỏ sò, tiền tệ, của cải | 春 | xuân | biểu âm | mùa xuân | 賰 = 貝 (Bối, biểu nghĩa: tiền/của cải) + 春 (Xuân, biểu âm); chữ hình thanh. Bộ 貝 chỉ đây liên quan đến tài sản, 春 (xuân) cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xuẩn\": 貝 (tiền) + 春 (xuân) — mùa XUÂN tiền bạc XUẨN (dồi dào), của cải sung túc. | Gương Hán-Việt | xuẩn, không dùng phổ biến trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 賰 giúp đọc văn bản cổ điển về của cải và sự sung túc.", "Tự nguyên_Xie": "Chữ hình thanh: bộ 貝 (vỏ sò, tiền tệ) biểu nghĩa, 春 biểu âm. 賰 mang nghĩa giàu có, sung túc, quà cáp hào phóng. Không có hình ảnh tự hình trong dữ liệu. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "谰", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "貝 + 春", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰貝春", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "春", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "賰", "Unihan_Traditional (Chữ Phồn thể)": "賰", "Pinyin_Xie": "chǔn", "Âm Hán Việt_Xie": "xuẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Dùng làm tính từ để miêu tả trạng thái dư dả, giàu sang của gia cảnh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趮', '{"9000": "7581.0", "Chữ Trung Quốc": "趮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 20 | nét | 趮 | táo | tượng hình | nóng vội, hung hăng (biến thể của 躁) | 趮 là dị thể của 躁 (táo — nóng vội, bồn chồn). Thuộc bộ 走 (tẩu — đi). Không có cấu trúc IDS rõ trong dữ liệu, nhưng bộ 走 gợi hành động chuyển động bồn chồn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táo\": bộ 走 (chạy) — người TÁO tính không ngồi yên được, cứ chạy đi chạy lại bồn chồn. | Gương Hán-Việt | táo trong ''táo bạo'', ''táo tính'', ''nóng táo'' | Mở khoá kiến thức | Biết 趮 giúp nhận ra biến thể 躁 (táo) trong văn bản cổ về tính khí và hành vi.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 趮 là dạng cổ/dị thể của 躁 (táo), nghĩa là ''dễ cáu, hung hăng, nóng vội''. Bộ 走 (đi, chạy) gợi sự bồn chồn không yên. Có đại triện và tiểu triện trong dữ liệu hình ảnh. Wiktionary xác nhận là alt form của 躁. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem \"躁\"", "Hạng Tần Suất (Jun Da)": "7581.0", "Tần Suất % (Jun Da)": "99.9987049365", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 喿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走喿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趮", "Unihan_Traditional (Chữ Phồn thể)": "趮", "Pinyin_Xie": "zào", "Âm Hán Việt_Xie": "táo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ miêu tả tâm trạng bồn chồn hoặc hành vi hấp tấp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹱', '{"9000": "7582.0", "Chữ Trung Quốc": "蹱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 19 | nét | 蹱 | trung | tượng hình | đi lảo đảo, vấp ngã | 蹱 không có cấu trúc IDS rõ ràng. Thuộc bộ 足 (túc — chân), pinyin là zhōng. Wiktionary chỉ có {{rfdef|zh}}, nhưng nghĩa liên quan đến đi lảo đảo (stagger). Bộ 足 gợi hành động của chân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trung\": bộ 足 (chân) + âm ''trung'' — chân đi TRUNG (giữa) không vững, lảo đảo TRUNG tâm không ổn định. | Gương Hán-Việt | trung, không dùng với nghĩa chân/đi trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 蹱 giúp đọc tổ hợp cổ 躘蹱 (đi lảo đảo).", "Tự nguyên_Xie": "Không có cấu trúc han tự kép từ nguồn học thuật. 蹱 thuộc bộ 足 (chân), nghĩa là đi lảo đảo, vấp ngã. Xuất hiện trong tổ hợp 躘蹱. Chưa có nguồn học thuật về tự hình chi tiết. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "豱", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 童", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊童", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "童", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹱", "Unihan_Traditional (Chữ Phồn thể)": "蹱", "Pinyin_Xie": "zhōng", "Âm Hán Việt_Xie": "trung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ miêu tả dáng đi xiêu vẹo hoặc hành động vấp ngã. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軙', '{"9000": "7583.0", "Chữ Trung Quốc": "軙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 11 | nét | 軙 | trần | tượng hình | ký tự Hán cổ thuộc bộ xe | 軙 không có cấu trúc IDS hay glyph origin. Thuộc bộ 車 (xa — xe), pinyin là chén. Không có dữ liệu Wiktionary. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trần\": bộ 車 (xe) mang âm ''trần'' — ký tự cổ liên quan đến phụ tùng xe hoặc tên riêng. | Gương Hán-Việt | trần, không dùng với nghĩa xe trong tiếng Việt | Mở khoá kiến thức | 軙 là ký tự học thuật trong nghiên cứu chữ Hán cổ.", "Tự nguyên_Xie": "Không có dữ liệu tự hình từ bất kỳ nguồn học thuật nào. 軙 thuộc bộ 車 (xe). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "軙", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 攴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車攴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "攴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "軙", "Unihan_Traditional (Chữ Phồn thể)": "軙", "Pinyin_Xie": "chén", "Âm Hán Việt_Xie": "trần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc bố trí, sắp đặt đồ vật hoặc binh lực. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軠', '{"9000": "7584.0", "Chữ Trung Quốc": "軠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 11 | nét | 軠 | nhẫm | tượng hình | biến thể cũ của 軖, xảo quyệt | 軠 không có cấu trúc IDS hay glyph origin. Thuộc bộ 車 (xa — xe), pinyin là rèn. Không có dữ liệu Wiktionary. Là biến thể cũ của 軖 [kuang2]. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhẫm\": bộ 車 (xe) + âm ''nhẫm'' — ký tự cổ liên quan đến xe hoặc tính xảo quyệt. | Gương Hán-Việt | nhẫm, không dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | 軠 là ký tự học thuật dùng nghiên cứu biến thể chữ Hán cổ.", "Tự nguyên_Xie": "Không có dữ liệu tự hình từ bất kỳ nguồn học thuật nào. 軠 thuộc bộ 車 (xe), là biến thể cũ của 軖 với nghĩa xảo quyệt, gian xảo. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "biến thể cũ của 軖 [kuang2]", "Hạng Tần Suất (Jun Da)": "7584.0", "Tần Suất % (Jun Da)": "99.9987095875", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 壬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車壬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "壬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "軠", "Unihan_Traditional (Chữ Phồn thể)": "軠", "Pinyin_Xie": "rèn", "Âm Hán Việt_Xie": "khuông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ chỉ dụng cụ quay sợi thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄫', '{"9000": "7585.0", "Chữ Trung Quốc": "鄫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 14 | nét | 鄫 | tằng | tượng hình | tên nước chư hầu cổ đại (Tằng quốc) | 鄫 không có cấu trúc IDS rõ ràng. Thuộc bộ 邑 (ấp), pinyin là zēng. Wiktionary xác nhận là tên hai nước chư hầu cổ (nay thuộc Sơn Đông và Hà Nam). Có kim văn, đại triện, tiểu triện trong dữ liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tằng\": bộ 邑 (ấp) + âm ''tằng'' — nước TẰNG cổ đại, vùng đất lịch sử thời Xuân Thu. | Gương Hán-Việt | tằng trong ''tằng tổ'' (tổ tiên cao), gần âm nhưng nghĩa khác; 鄫 là địa danh | Mở khoá kiến thức | Biết 鄫 giúp đọc sử liệu Xuân Thu về các nước chư hầu nhỏ.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | 鄫 là địa danh lịch sử: tên hai nước chư hầu thời Xuân Thu — một ở Sơn Đông, một ở Hà Nam. Bộ 邑 (ấp) xác nhận đây là địa danh. Có kim văn và tiểu triện trong dữ liệu, cho thấy chữ có gốc rễ khá cổ. Cũng là họ người. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Tằng", "Hạng Tần Suất (Jun Da)": "7585.0", "Tần Suất % (Jun Da)": "99.9987173393", "GavinGrover_Once (Chiết tự trực tiếp)": "曾 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰曾阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄫", "Unihan_Traditional (Chữ Phồn thể)": "鄫", "Pinyin_Xie": "zēng", "Âm Hán Việt_Xie": "tằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng chỉ một nước chư hầu thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄿', '{"9000": "7586.0", "Chữ Trung Quốc": "鄿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 17 | nét | 鄿 | ki | tượng hình | tên địa điểm cổ | 鄿 không có cấu trúc IDS hay glyph origin. Thuộc bộ 邑 (ấp), pinyin là jī. Không có dữ liệu Wiktionary. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ki\": bộ 邑 (ấp) + âm ''ki'' — vùng đất KI xa xôi ở phương Tây (Tân Cương) của đế chế Hán. | Gương Hán-Việt | ki, không dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | 鄿 là ký tự địa danh học trong nghiên cứu lịch sử Trung Quốc.", "Tự nguyên_Xie": "Không có dữ liệu tự hình từ nguồn học thuật. 鄿 thuộc bộ 邑 (ấp), là địa danh cổ (tên huyện ở Tân Cương). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(thảo mộc); tên địa điểm", "Hạng Tần Suất (Jun Da)": "7586.0", "Tần Suất % (Jun Da)": "99.9987188897", "GavinGrover_Once (Chiết tự trực tiếp)": "蕇 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰蕇阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蕇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄿", "Unihan_Traditional (Chữ Phồn thể)": "鄿", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "cần, kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng chỉ địa danh cổ hoặc tên thảo mộc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酀', '{"9000": "7587.0", "Chữ Trung Quốc": "酀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 18 | nét | 酀 | yến | tượng hình | địa danh cổ, tên người | 酀 không có cấu trúc IDS. Thuộc bộ 邑 (ấp), pinyin là yàn/yǎn. Wiktionary xác nhận là tên địa cổ và dùng trong tên người. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yến\": bộ 邑 (ấp) + âm ''yến'' — vùng đất YẾN, địa danh cổ hay dùng trong tên người. | Gương Hán-Việt | yến trong ''yến tiệc'', gần âm nhưng nghĩa khác; 酀 là địa danh | Mở khoá kiến thức | 酀 là ký tự địa danh và nhân danh học cổ Trung Hoa.", "Tự nguyên_Xie": "Không có cấu trúc han tự kép từ nguồn học thuật. 酀 thuộc bộ 邑, là tên địa cổ và dùng làm tên người ({{zh-used2|n}}). Có hai âm đọc: yàn (tên địa danh) và yǎn (dùng trong tên). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "酀", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "燕 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰燕阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "燕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "酀", "Unihan_Traditional (Chữ Phồn thể)": "酀", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "yến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng chỉ một địa danh thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('釡', '{"9000": "7588.0", "Chữ Trung Quốc": "釡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 釡 | phủ | tượng hình | nồi lớn, vạc (biến thể cổ của 釜) | 釡 là biến thể cũ của 釜 (fǔ — nồi lớn, vạc). Không có cấu trúc IDS. Thuộc bộ 金 (kim — kim loại), pinyin là fǔ. Không có glyph origin từ Wiktionary. Có tiểu triện trong dữ liệu hình ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phủ\": bộ 金 (kim) + âm ''phủ'' — cái vạc kim loại PHỦ xuống mặt lửa để nấu — đó là 釡 (nồi lớn). | Gương Hán-Việt | phủ trong ''phủ dụ'', gần âm nhưng nghĩa khác; 釡 là cái nồi lớn | Mở khoá kiến thức | Biết 釡 giúp nhận ra biến thể 釜 (phủ) trong văn bản và thành ngữ cổ như 釜底抽薪 (rút củi dưới vạc — triệt hạ căn nguyên).", "Tự nguyên_Xie": "Tiểu triện | 釡 là biến thể cổ của 釜 (nồi lớn, vạc). Bộ 金 (kim loại) gợi đây là dụng cụ bằng kim loại. Không có giải thích tự hình học thuật riêng — xem 釜 để hiểu nghĩa gốc. Có tiểu triện trong dữ liệu. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "biến thể cũ của 釜 [fu3]", "Hạng Tần Suất (Jun Da)": "7588.0", "Tần Suất % (Jun Da)": "99.9987219904", "GavinGrover_Once (Chiết tự trực tiếp)": "八 + 金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱八金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "金", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "八", "Unihan_Simplified (Chữ Giản thể)": "釡", "Unihan_Traditional (Chữ Phồn thể)": "釡", "Pinyin_Xie": "fǔ", "Âm Hán Việt_Xie": "phủ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ dụng cụ nấu ăn thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('釢', '{"9000": "7589.0", "Chữ Trung Quốc": "釢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 釢 | nãi | tượng hình | tên cũ của nguyên tố Neodymium (Nd) | 釢 không có cấu trúc IDS. Thuộc bộ 金 (kim — kim loại), pinyin là nǎi. Không có glyph origin từ Wiktionary. Đây là ký tự hiện đại dùng để phiên âm tên nguyên tố Neodymium (Nd) trong bảng tuần hoàn Trung Quốc cổ hơn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nãi\": bộ 金 (kim loại) + âm ''nãi'' — kim loại NÃI (Neodymium), nguyên tố từ tính mạnh dùng trong nam châm hiện đại. | Gương Hán-Việt | nãi, không dùng phổ biến trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 釢 giúp đọc bảng tuần hoàn Trung Quốc thế hệ cũ, nhận ra tên gọi cổ của Neodymium.", "Tự nguyên_Xie": "Không có dữ liệu tự hình từ nguồn học thuật. 釢 thuộc bộ 金 (kim loại), là tên cũ dùng cho nguyên tố Neodymium (Nd, số nguyên tử 60). Đây là ký tự tạo muộn để phục vụ dịch thuật khoa học, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên gọi cũ của nguyên tố neodi, Nd", "Hạng Tần Suất (Jun Da)": "7589.0", "Tần Suất % (Jun Da)": "99.9987235407", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 乃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金乃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "釢", "Unihan_Traditional (Chữ Phồn thể)": "釢", "Pinyin_Xie": "nǎi", "Âm Hán Việt_Xie": "nãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ nguyên tố hóa học trong tài liệu cũ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鉃', '{"9000": "7590.0", "Chữ Trung Quốc": "鉃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 鉃 | thị | tượng hình | kim loại cổ, dạng tự lập | 鉃 là chữ độc thể thuộc bộ 金 (kim). Không rõ cấu trúc hội ý hay hình thanh; chữ này cực hiếm, không có nguồn phân tích ngữ tố học xác tín.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thị\": chữ kim loại cổ hiếm gặp — bộ 金 (kim) gợi vật liệu kim thuộc, đọc như 是 (shì, \"là\") nhưng nghĩa hoàn toàn khác biệt. | Gương Hán-Việt | chưa phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鉃 giúp nhận diện các chữ kim loại cổ trong văn bản cổ điển Trung Quốc.", "Tự nguyên_Xie": "Không có nguồn Wiktionary về ngữ nguyên chữ 鉃. Theo bộ 金 (kim loại), chữ này liên quan đến kim loại hay vật liệu kim thuộc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鉃", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 矢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金矢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鉃", "Unihan_Traditional (Chữ Phồn thể)": "鉃", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ đầu nhọn của mũi tên kim loại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鍎', '{"9000": "7591.0", "Chữ Trung Quốc": "鍎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 鍎 | đồ | tượng hình | kim loại, vật dụng | 鍎 là chữ độc thể thuộc bộ 金 (kim). Không có phân tích thành phần rõ ràng; cấu trúc không minh bạch do chữ cực hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồ\": chữ kim loại hiếm thuộc bộ 金 — âm tú (tú), nghĩa mơ hồ như nhiều chữ cổ cực hiếm trong văn bản kinh điển. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鍎 giúp đọc hiểu văn bản cổ liên quan đến dụng cụ kim loại đặc biệt.", "Tự nguyên_Xie": "Không có nguồn Wiktionary về ngữ nguyên cụ thể của chữ 鍎. Theo nghĩa ghi nhận, chữ mang nghĩa ''cùng một lúc'' hoặc liên quan đến dụng cụ kim loại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Cùng một lúc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 盾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金盾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "盾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鍎", "Unihan_Traditional (Chữ Phồn thể)": "鍎", "Pinyin_Xie": "tú", "Âm Hán Việt_Xie": "đồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Chữ này chủ yếu dùng làm phó từ trong văn ngôn để chỉ các hành động diễn ra cùng lúc. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞗', '{"9000": "7592.0", "Chữ Trung Quốc": "鞗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 15 | nét | 鞗 | điều | tượng hình | dây cương ngựa, đồ da | 鞗 là chữ độc thể thuộc bộ 革 (cách, da). Không có phân tích thành phần rõ ràng; bộ 革 gợi vật liệu da thuộc, liên quan đến dây cương ngựa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điều\": bộ 革 (da thuộc) — sợi dây da dùng để điều khiển ngựa, dây cương là ''điều tiết'' (điều chỉnh hướng đi) con ngựa. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鞗 giúp nhận diện từ vựng cổ về đồ da và dụng cụ kỵ mã trong văn bản kinh điển.", "Tự nguyên_Xie": "Chữ 鞗 thuộc bộ 革 (cách, da thuộc), nghĩa là dây cương ngựa. Theo trường nghĩa, liên quan đến 鞗革 (dây cương và da ngựa). Chưa có nguồn Wiktionary phân tích ngữ nguyên chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây cương ngựa", "Hạng Tần Suất (Jun Da)": "7592.0", "Tần Suất % (Jun Da)": "99.9987328428", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鞗", "Unihan_Traditional (Chữ Phồn thể)": "鞗", "Pinyin_Xie": "tiáo", "Âm Hán Việt_Xie": "điều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong văn học cổ để chỉ sợi dây cương điều khiển ngựa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韱', '{"9000": "7593.0", "Chữ Trung Quốc": "韱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 韭 | Số nét | 17 | nét | 韭 | cửu | biểu nghĩa | hẹ, rau cửu | 㦰 | (vô) | biểu âm | thành phần biểu âm cổ | 韱 = 韭 (Cửu, biểu nghĩa: rau hẹ) + 㦰 (biểu âm). Chữ hình thanh: bộ 韭 chỉ loại rau thuộc họ hành hẹ, thành phần 㦰 cho âm đọc. Chữ chỉ loại hành dại hay tỏi tây.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêm\": Cửu (rau hẹ) + âm — loại hành dại mọc tự nhiên, tiêm nhỏ như cọng hẹ. Trong Kinh Thi đã nhắc đến loại rau hương vị đậm này. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 韱 giúp đọc tài liệu thực vật học cổ và y học cổ truyền Trung Quốc về các loại rau họ hành.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 韱 là chữ hình thanh (psc): bộ 韭 biểu nghĩa ''rau hẹ'', thành phần 㦰 biểu âm. Nghĩa là hành dại (wild onion) hoặc tỏi tây (leek), một loại rau thuộc họ Allium dùng trong ẩm thực và y học cổ truyền Trung Quốc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "926.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tiêm (韯) Cửu (925)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tiêm (韯 - chỉ âm) ở trên chữ Cửu (số 925 - rau hẹ/chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Tiêm là rau hẹ núi, cũng có ý chỉ sự nhỏ nhắn, thon nhỏ.", "Nghĩa Tiếng Việt_Xie": "hành tây hoặc tỏi tây", "Hạng Tần Suất (Jun Da)": "7593.0", "Tần Suất % (Jun Da)": "99.9987343932", "GavinGrover_Once (Chiết tự trực tiếp)": "从 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰从", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "韱", "Unihan_Traditional (Chữ Phồn thể)": "韱", "Pinyin_Xie": "xiān", "Âm Hán Việt_Xie": "tiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại cỏ nhỏ hoặc cây tỏi hoang dã. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('餁', '{"9000": "7594.0", "Chữ Trung Quốc": "餁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 14 | nét | 餁 | nhẫm | tượng hình | thức ăn nấu chín kỹ, đồ ăn | 餁 là chữ độc thể thuộc bộ 食 (thực, ăn). Không có phân tích thành phần rõ ràng; bộ 食 gợi liên quan đến thức ăn và nấu nướng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhẫm\": bộ 食 (ăn, thức ăn) — thức ăn đã nấu chín kỹ, nhẫm nại nấu cho đến khi mềm nhừ. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 餁 giúp nhận diện từ vựng ẩm thực trong văn bản cổ điển Trung Quốc.", "Tự nguyên_Xie": "Không có nguồn Wiktionary về ngữ nguyên chữ 餁. Theo bộ 食 (thực), chữ liên quan đến thức ăn nấu chín. Nghĩa ghi nhận là ''thức ăn đã nấu; nấu cho chín kỹ''. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nấu nướng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 任", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠任", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "任", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "餁", "Unihan_Traditional (Chữ Phồn thể)": "餁", "Pinyin_Xie": "rèn", "Âm Hán Việt_Xie": "nhẫm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Dùng làm động từ chỉ việc nấu nướng hoặc làm tính từ chỉ thức ăn đã được nấu chín. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('騺', '{"9000": "7595.0", "Chữ Trung Quốc": "騺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 21 | nét | 執 | chấp | biểu âm | nắm chặt, giữ chặt | 馬 | mã | biểu nghĩa | ngựa | 騺 = 執 (Chấp, biểu âm) + 馬 (Mã, biểu nghĩa: ngựa). Chữ hình thanh: 馬 chỉ đây là trạng thái liên quan đến ngựa, 執 cho âm đọc. Nghĩa cổ là ngựa bị nặng không đi được, chân bị vẹo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chấp\": Chấp (nắm chặt) + Mã (ngựa) — con ngựa bị ''chấp'' (giữ chặt) vì chân bị vẹo, không thể phi nước đại. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 騺 giúp đọc văn bản cổ điển mô tả ngựa và kỵ mã thời cổ đại.", "Tự nguyên_Xie": "Theo Wiktionary, 騺 là chữ hình thanh (psc): bộ 馬 biểu nghĩa ''ngựa'', thành phần 執 biểu âm. Nghĩa cổ điển: ngựa không thể di chuyển vì bị quá nặng hoặc chân bị vẹo; cũng có nghĩa dừng lại, mạnh mẽ, dũng cảm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa nặng; ngựa không thể di chuyển vì bị trẹo chân; làm phiền", "Hạng Tần Suất (Jun Da)": "7595.0", "Tần Suất % (Jun Da)": "99.9987514471", "GavinGrover_Once (Chiết tự trực tiếp)": "執 + 馬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱執馬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "執", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "騺", "Unihan_Traditional (Chữ Phồn thể)": "騺", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "chí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ để miêu tả tính chất mạnh mẽ, hung dũng của loài ngựa hoặc chim săn mồi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鯚', '{"9000": "7596.0", "Chữ Trung Quốc": "鯚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 19 | nét | 鯚 | kế | tượng hình | cá quy, cá lệ (mandarin fish) | 鯚 là chữ độc thể thuộc bộ 魚 (ngư, cá). Không có phân tích thành phần rõ ràng; chữ chỉ một loài cá cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kế\": bộ 魚 (cá) — loài cá quy hiếm, màu sắc đẹp như ''kế hoạch'' của tạo hóa. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鯚 giúp nhận diện từ vựng ngư học và sinh học thủy sinh trong văn bản chuyên ngành.", "Tự nguyên_Xie": "Theo Wiktionary, 鯚 là tên gọi cổ của cá quy hay cá lệ (mandarin fish — Siniperca chuatsi), một loài cá nước ngọt quý ở Trung Quốc. Chưa có nguồn phân tích ngữ nguyên chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鯚", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 季", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚季", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "季", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鯚", "Unihan_Traditional (Chữ Phồn thể)": "鯚", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "kế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ đứng độc lập hoặc kết hợp với các từ khác để chỉ một loài cá nước ngọt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳛', '{"9000": "7597.0", "Chữ Trung Quốc": "鳛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 19 | nét | 鳛 | tập | tượng hình | cá chạch, cá lươn nhỏ | 鳛 là chữ độc thể thuộc bộ 魚 (ngư, cá). Chữ cổ dạng 鰼. Không có phân tích thành phần rõ ràng; chỉ một loài cá chạch (loach).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tập\": bộ 魚 (cá) — cá chạch nhỏ ''tập hợp'' theo đàn trong bùn, 鳛水 là tên sông cổ. Cá chạch dự báo thời tiết bằng cách bơi lên mặt nước. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鳛 giúp đọc tài liệu sinh học thủy sinh và địa danh cổ Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Chữ 鳛 (dạng cổ 鰼) có dạng tiểu triện còn lưu. Theo Wiktionary, nghĩa là cá chạch (weather loach, Misgurnus anguillicaudatus) — loài cá nước ngọt nhỏ dùng trong ẩm thực và y học cổ truyền. Chữ còn dùng làm địa danh 鳛水 (Tập Thủy). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá chạch", "Hạng Tần Suất (Jun Da)": "7597.0", "Tần Suất % (Jun Da)": "99.9987576485", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 習", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼習", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "習", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳛", "Unihan_Traditional (Chữ Phồn thể)": "鰼", "Pinyin_Xie": "xí", "Âm Hán Việt_Xie": "tập", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loài cá nước ngọt nhỏ hoặc dùng trong địa danh cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴮', '{"9000": "7598.0", "Chữ Trung Quốc": "鴮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 17 | nét | 鴮 | ô | tượng hình | loài chim cổ, chỉ dùng trong 鴮鸅 | 鴮 là chữ độc thể thuộc bộ 鳥 (điểu, chim). Chỉ dùng trong từ ghép 鴮鸅, tên một loài chim cổ không xác định rõ. Không có phân tích thành phần rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ô\": bộ 鳥 (chim) — chữ chim cổ đơn giản, như con quạ (ô) nhưng là loài chim 鴮鸅 bí ẩn trong kinh thư cổ. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鴮 giúp nhận diện tên chim cổ trong văn bản kinh điển Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 鴮 chỉ xuất hiện trong từ ghép 鴮鸅 — tên một loài chim cổ. Không có thông tin ngữ nguyên chi tiết ngoài dạng tiểu triện tiếng Trung cổ điển. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tao", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "夸 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰夸鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鴮", "Unihan_Traditional (Chữ Phồn thể)": "鴮", "Pinyin_Xie": "wū", "Âm Hán Việt_Xie": "ô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong cụm từ ghép để chỉ loài chim bồ nông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴲', '{"9000": "7599.0", "Chữ Trung Quốc": "鴲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 17 | nét | 鴲 | chi | tượng hình | loài chim không xác định | 鴲 là chữ độc thể thuộc bộ 鳥 (điểu, chim). Chữ cực hiếm, không có thông tin nghĩa rõ ràng từ Wiktionary. Có dạng tiểu triện còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chi\": bộ 鳥 (chim) — chữ chim cổ bí ẩn, âm chi như tiếng chim kêu, hình dạng trong tiểu triện gợi một loài chim. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鴲 giúp nhận diện chữ hiếm trong danh mục chim cổ điển Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Chữ 鴲 có dạng tiểu triện còn lưu. Wiktionary không cung cấp định nghĩa rõ ràng (rfdef). Chưa có nguồn phân tích ngữ nguyên chi tiết. Chữ thuộc bộ 鳥 (điểu) — chỉ một loài chim không xác định trong thư tịch cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鲲", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "旨 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰旨鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鴲", "Unihan_Traditional (Chữ Phồn thể)": "鴲", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "chi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loài chim nhỏ theo thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴷', '{"9000": "7600.0", "Chữ Trung Quốc": "鴷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 17 | nét | 鴷 | liệt | tượng hình | chim gõ kiến | 鴷 là chữ độc thể thuộc bộ 鳥 (điểu, chim). Không có phân tích thành phần rõ ràng từ nguồn; chữ chỉ một loài chim gõ kiến (woodpecker).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liệt\": bộ 鳥 (chim) — con chim gõ kiến ''liệt'' (nhanh, mạnh) mỏ vào cây theo nhịp đều đặn, tiếng gõ vang xa. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鴷 giúp nhận diện tên chim trong văn bản sinh học và văn học cổ Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 鴷 là tên gọi cho loài chim gõ kiến (woodpecker). Không có thông tin ngữ nguyên chi tiết hơn từ Wiktionary. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim gõ kiến", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "列 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱列鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "列", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "䴕", "Unihan_Traditional (Chữ Phồn thể)": "鴷", "Pinyin_Xie": "liè", "Âm Hán Việt_Xie": "liệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ đứng độc lập hoặc làm trung tâm ngữ để chỉ loài chim gõ kiến. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鷷', '{"9000": "7601.0", "Chữ Trung Quốc": "鷷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 23 | nét | 尊 | tôn | biểu âm | tôn kính, cao quý | 鳥 | điểu | biểu nghĩa | chim | 鷷 = 尊 (Tôn, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim). Chữ hình thanh: bộ 鳥 chỉ đây là loài chim, 尊 cho âm đọc. Nghĩa là loài chim trĩ (pheasant) hoặc chim lặn (grebe) trong văn bản cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tôn\": Điểu (chim) + Tôn (tôn kính) — con chim trĩ ''tôn quý'' với bộ lông sặc sỡ, đuôi dài duyên dáng. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鷷 giúp nhận diện tên chim cổ trong tài liệu sinh học và văn học Trung Quốc cổ điển.", "Tự nguyên_Xie": "Theo Wiktionary, 鷷 là chữ hình thanh (psc): bộ 鳥 biểu nghĩa ''chim'', thành phần 尊 biểu âm. Nghĩa cổ điển là chim trĩ (pheasant). Chữ cực hiếm, chỉ gặp trong từ điển chuyên ngành sinh học cổ điển. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá bống tượng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "尊 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰尊鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鷷", "Unihan_Traditional (Chữ Phồn thể)": "鷷", "Pinyin_Xie": "zūn", "Âm Hán Việt_Xie": "tôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cá nước ngọt thuộc họ cá bống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸀', '{"9000": "7602.0", "Chữ Trung Quốc": "鸀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 24 | nét | 鸀 | thục | tượng hình | loài chim cổ, chỉ dùng trong 鸀鳿 | 鸀 là chữ độc thể thuộc bộ 鳥 (điểu, chim). Chỉ dùng trong từ ghép 鸀鳿, tên một loài chim cổ không xác định rõ. Không có phân tích thành phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thục\": bộ 鳥 (chim) — loài chim cổ 鸀鳿 trong kinh thư, ''thục'' gợi sự quen thuộc/chín chắn nhưng chim 鸀 lại bí ẩn không ai biết rõ. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鸀 giúp nhận diện tên chim cổ trong văn bản học thuật Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 鸀 chỉ xuất hiện trong từ ghép 鸀鳿 — tên một loài chim trong thư tịch cổ. Không có thông tin ngữ nguyên chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "diều", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "蜀 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰蜀鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蜀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鸀", "Unihan_Traditional (Chữ Phồn thể)": "鸀", "Pinyin_Xie": "chǔ", "Âm Hán Việt_Xie": "thục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim cổ trong văn học Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麎', '{"9000": "7603.0", "Chữ Trung Quốc": "麎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 18 | nét | 麎 | trần | tượng hình | hươu cái, thú họ nai | 麎 là chữ độc thể thuộc bộ 鹿 (lộc, hươu). Không có phân tích thành phần rõ ràng; chữ chỉ hươu cái Père David (Elaphurus davidianus).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trần\": bộ 鹿 (hươu) — con hươu cái Père David, loài hươu quý từng sống trong vườn ngự của Hoàng đế. Âm trần như ''trần thế'' — thú quý của thế gian. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 麎 giúp đọc tài liệu động vật học cổ và văn bản cung đình Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 麎 nghĩa là hươu cái Père David (female Père David''s deer — Elaphurus davidianus), một loài hươu quý hiếm từng phổ biến ở Trung Quốc. Chưa có nguồn phân tích ngữ nguyên chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Xi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 辰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿辰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麎", "Unihan_Traditional (Chữ Phồn thể)": "麎", "Pinyin_Xie": "chén", "Âm Hán Việt_Xie": "trần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con hươu cái hoặc nai cái. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麡', '{"9000": "7604.0", "Chữ Trung Quốc": "麡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 25 | nét | 麡 | kỳ | tượng hình | thú họ hươu, kỳ lân | 麡 là chữ độc thể thuộc bộ 鹿 (lộc, hươu). Không có phân tích thành phần; chữ chỉ một loài thú giống hươu (kỳ lân hoặc thú thần thoại).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": bộ 鹿 (hươu) — con thú kỳ lạ (kỳ) giống hươu trong thần thoại, có thể là kỳ lân hay linh thú cổ. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 麡 giúp đọc văn bản thần thoại và động vật học cổ Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 麡 là tên một loài thú giống hươu (animal resembling a deer). Chưa có nguồn phân tích ngữ nguyên chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "麡", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 齊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿齊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "齊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麡", "Unihan_Traditional (Chữ Phồn thể)": "麡", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài hươu nhỏ có tuyến xạ hương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麧', '{"9000": "7605.0", "Chữ Trung Quốc": "麧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 麥 | Số nét | 14 | nét | 麧 | hạt | tượng hình | trấu còn lại sau khi giã, vỏ lúa | 麧 là chữ độc thể thuộc bộ 麥 (mạch, lúa mì). Không có phân tích thành phần rõ ràng; bộ 麥 gợi liên quan đến ngũ cốc, và nghĩa là phần vỏ trấu còn sót sau khi giã.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạt\": bộ 麥 (lúa mì) — phần trấu cứng, bã còn lại sau khi giã thóc, như cái ''hạt'' cứng còn sót lại. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 麧 giúp đọc văn bản nông học và y học cổ về ngũ cốc và xử lý thóc gạo.", "Tự nguyên_Xie": "Theo Wiktionary, 麧 là dạng thay thế của 覈, nghĩa là vỏ trấu còn lại sau khi giã thóc. Chữ thuộc bộ 麥 (lúa mì, ngũ cốc). Không có thông tin ngữ nguyên chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "麧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "麥 + 乞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰麥乞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "麥", "Unihan_Simplified (Chữ Giản thể)": "麧", "Unihan_Traditional (Chữ Phồn thể)": "麧", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại bột lúa mạch hoặc bột mì còn lẫn cám. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼇', '{"9000": "7606.0", "Chữ Trung Quốc": "鼇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黽 | Số nét | 23 | nét | 鼇 | ngao | tượng hình | rùa biển khổng lồ, linh vật | 鼇 là chữ độc thể thuộc bộ 黽 (minh, ếch/rùa). Dạng chuẩn hơn là 鰲. Không có phân tích thành phần rõ ràng; gợi hình ảnh sinh vật biển khổng lồ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngao\": bộ 黽 (rùa) — con rùa ngao khổng lồ của thần thoại, 獨占鰲頭 là thành ngữ ''đứng đầu thiên hạ''. Tiếng Việt: ''ngao du'' không liên quan, nhưng âm ngao dễ nhớ. | Gương Hán-Việt | ngao — trong thành ngữ Hán-Việt cổ | Mở khoá kiến thức | Biết 鼇 mở khoá: 鼇頭 (đứng đầu), 獨占鰲頭 (chiếm ngôi đầu), thần thoại Nữ Oa.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 鼇 là dạng biến thể của 鰲 — con rùa biển khổng lồ trong thần thoại Trung Quốc. Trong thần thoại, Nữ Oa chặt chân Ngao (鼇) để chống đỡ bầu trời. Thành ngữ 獨占鰲頭 (đứng đầu, chiến thắng) có nguồn từ chữ này. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Áo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "敖 + 黽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敖黽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黽", "Unihan_Simplified (Chữ Giản thể)": "鼇", "Unihan_Traditional (Chữ Phồn thể)": "鼇", "Pinyin_Xie": "áo", "Âm Hán Việt_Xie": "ngao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài rùa biển khổng lồ trong thần thoại cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼞', '{"9000": "7607.0", "Chữ Trung Quốc": "鼞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼓 | Số nét | 24 | nét | 鼞 | đương | tượng hình | tiếng trống, âm thanh trống | 鼞 là chữ độc thể thuộc bộ 鼓 (cổ, trống). Không có phân tích thành phần rõ ràng; chữ mang nghĩa liên quan đến âm thanh của trống. Wiktionary không có định nghĩa rõ (rfdef).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đương\": bộ 鼓 (trống) — âm ''đương đương'' của tiếng trống vang lên, như tiếng trống trận hào hùng. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鼞 giúp nhận diện từ vựng âm nhạc và nghi lễ cổ đại liên quan đến trống.", "Tự nguyên_Xie": "Chữ 鼞 thuộc bộ 鼓 (cổ, trống). Không có nguồn Wiktionary về ngữ nguyên chi tiết (chỉ rfdef). Âm đọc tāng gợi tiếng trống ''đùng'' hay ''đang'' — từ tượng thanh. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鼞", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鼓 + 堂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱鼓堂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼓", "Unihan_Simplified (Chữ Giản thể)": "鼞", "Unihan_Traditional (Chữ Phồn thể)": "鼞", "Pinyin_Xie": "tāng", "Âm Hán Việt_Xie": "đương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ tượng thanh | 象声词 | Chữ này làm danh từ hoặc từ mô phỏng âm thanh dồn dập của tiếng trống lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼤', '{"9000": "7608.0", "Chữ Trung Quốc": "鼤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼠 | Số nét | 17 | nét | 鼤 | văn | tượng hình | chuột đốm, chuột bông | 鼤 là chữ độc thể thuộc bộ 鼠 (thử, chuột). Không có phân tích thành phần rõ ràng; chữ chỉ một loài chuột có đốm hay có hoa văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"văn\": bộ 鼠 (chuột) — con chuột có hoa văn (văn) đốm trên lưng, như chú chuột bông nhiều màu trong các bộ sưu tập thú cưng cổ đại. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鼤 giúp nhận diện từ vựng động vật học trong văn bản cổ Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 鼤 nghĩa là ''chuột đốm'' hay ''chuột bông'' (spotted mouse). Chữ thuộc bộ 鼠 (thử, chuột). Không có nguồn phân tích ngữ nguyên chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chuột đốm; chuột bông", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鼠 + 文", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鼠文", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "文", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼠", "Unihan_Simplified (Chữ Giản thể)": "鼤", "Unihan_Traditional (Chữ Phồn thể)": "鼤", "Pinyin_Xie": "wén", "Âm Hán Việt_Xie": "văn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chuột có lông đốm hoặc sọc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齺', '{"9000": "7609.0", "Chữ Trung Quốc": "齺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 25 | nét | 齒 | xỉ | biểu nghĩa | răng | 芻 | so | biểu âm | cỏ, thức ăn gia súc | 齺 = 齒 (Xỉ, biểu nghĩa: răng) + 芻 (So/Sô, biểu âm). Chữ hình thanh: bộ 齒 chỉ liên quan đến răng hay nhai, 芻 cho âm đọc. Wiktionary không cung cấp định nghĩa rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trâu\": Xỉ (răng) + So (âm 芻) — hàm răng nhai cỏ như trâu bò (芻 là cỏ gia súc), chữ hình thanh về răng nhai. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 齺 giúp đọc văn bản y học cổ về răng miệng và giải phẫu học cổ đại.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 齺 là chữ hình thanh (psc): bộ 齒 biểu nghĩa ''răng'', thành phần 芻 biểu âm. Không có định nghĩa rõ ràng từ Wiktionary (rfdef). Chữ thuộc nhóm từ vựng cổ về răng và nhai. Chưa có nguồn học thuật. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "麺", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "齒 + 芻", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齒芻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "芻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齒", "Unihan_Simplified (Chữ Giản thể)": "齺", "Unihan_Traditional (Chữ Phồn thể)": "齺", "Pinyin_Xie": "zōu", "Âm Hán Việt_Xie": "trâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ miêu tả hàm răng mọc không đều hoặc động từ chỉ việc nhai. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齽', '{"9000": "7610.0", "Chữ Trung Quốc": "齽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 28 | nét | 齽 | tẫn | tượng hình | răng, bộ xỉ | 齽 là chữ độc thể thuộc bộ 齒 (xỉ, răng). Không có phân tích thành phần rõ ràng; chữ cực hiếm với Wiktionary chỉ cung cấp dạng tiểu triện tối giản.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tẫn\": bộ 齒 (răng) — chữ răng cổ hiếm gặp nhất trong nhóm bộ 齒, âm tẫn như ''tận lực'' nhưng là về răng cổ đại. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 齽 giúp nhận diện nhóm chữ cổ về răng trong y học và giải phẫu học cổ Trung Quốc.", "Tự nguyên_Xie": "Chữ 齽 thuộc bộ 齒 (xỉ, răng). Wiktionary chỉ cung cấp {{Han etym}} tối thiểu, không có định nghĩa hay phân tích ngữ nguyên. Nghĩa không rõ ràng; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "齽", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "齒 + 禁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齒禁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齒", "Unihan_Simplified (Chữ Giản thể)": "齽", "Unihan_Traditional (Chữ Phồn thể)": "齽", "Pinyin_Xie": "jìn", "Âm Hán Việt_Xie": "tẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ miêu tả trạng thái răng bị ghê, ê buốt do đồ chua lạnh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龑', '{"9000": "7611.0", "Chữ Trung Quốc": "龑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 龍 | Số nét | 20 | nét | 龑 | yểm | tượng hình | cao và sáng, chữ tạo ra cho tên riêng | 龑 là chữ độc thể thuộc bộ 龍 (long, rồng). Không có nguồn Wiktionary; đây là chữ được tạo ra đặc biệt (tự tạo) cho vua Nam Hán Lưu Nham (劉龑) thời Ngũ Đại, gộp 飛 và 龍 vào một chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yểm\": bộ 龍 (rồng) — chữ được tạo riêng cho Vua Nam Hán, mang nghĩa ''cao sáng như rồng''. Đây là trường hợp hiếm: một chữ Hán được phát minh cho một người cụ thể. | Gương Hán-Việt | không phổ biến trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 龑 là ví dụ độc đáo về việc tạo chữ Hán mới trong lịch sử, thường chỉ xảy ra với tên vua.", "Tự nguyên_Xie": "Không có nguồn Wiktionary về ngữ nguyên chữ 龑. Đây là chữ tự tạo (tự chế) được thiết kế riêng cho Lưu Nham (劉龑), vua Nam Hán thời Ngũ Đại (917-971), có nghĩa ''cao và sáng''. Loại chữ tạo ra cho tên vua hay nhân vật quan trọng gọi là ''tạo chữ mới''. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鑑", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "龍 + 天", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱龍天", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "天", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "龍", "Unihan_Simplified (Chữ Giản thể)": "䶮", "Unihan_Traditional (Chữ Phồn thể)": "龑", "Pinyin_Xie": "yǎn", "Âm Hán Việt_Xie": "yểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này chủ yếu làm danh từ riêng trong tên người hoặc tính từ chỉ sự cao rộng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裏', '{"9000": "7612.0", "Chữ Trung Quốc": "裏", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "裏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "裏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "裏", "Unihan_Traditional (Chữ Phồn thể)": "裏", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砮', '{"9000": "7615.0", "Chữ Trung Quốc": "砮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 砮 | nỗ | tượng hình | đá dùng làm đầu mũi tên | 砮 là chữ độc thể, chưa rõ cấu trúc hình thanh hay hội ý qua Wiktionary. Tiểu triện còn lưu hình dạng cổ. Chưa có phân tích thành phần xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nỗ\": bộ Thạch (石, đá) gợi chất liệu — đá mài sắc làm mũi tên bắn nỗ lực xuyên mục tiêu. | Gương Hán-Việt | nỗ — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 砮 (nỗ) giúp nhận ra các chữ bộ Thạch (石) chỉ vật liệu đá như 砭, 砝.", "Tự nguyên_Xie": "Tiểu triện | 砮 chỉ loại đá dùng làm đầu mũi tên, ghi nhận trong Thư Kinh. Tiểu triện còn hình. Chưa có nguồn học thuật phân tích cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá dùng làm tên bắn", "Hạng Tần Suất (Jun Da)": "7615.0", "Tần Suất % (Jun Da)": "99.9987871053", "GavinGrover_Once (Chiết tự trực tiếp)": "奴 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱奴石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砮", "Unihan_Traditional (Chữ Phồn thể)": "砮", "Pinyin_Xie": "nǔ", "Âm Hán Việt_Xie": "nỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại đá cứng dùng chế tác vũ khí thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綟', '{"9000": "7616.0", "Chữ Trung Quốc": "綟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 14 | nét | 綟 | lệ | tượng hình | tơ lụa màu xanh lục | 綟 thuộc bộ Mịch (糸, tơ sợi), cấu trúc cụ thể không rõ qua Wiktionary. Chữ chưa có phân tích thành phần xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lệ\": bộ Mịch (糸, tơ) + âm lệ — tơ lụa màu lệ (xanh lục) rực rỡ như lá non. | Gương Hán-Việt | lệ — ít xuất hiện trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 綟 (lệ) giúp nhận ra nhóm chữ bộ Mịch (糸) chỉ màu sắc vải lụa.", "Tự nguyên_Xie": "綟 chỉ màu xanh lục của tơ lụa, hoặc tơ lụa màu xanh. Không có nguồn Wiktionary phân tích chi tiết. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "綟", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 戾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹戾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "綟", "Unihan_Traditional (Chữ Phồn thể)": "綟", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường dùng làm danh từ chỉ màu sắc hoặc động từ chỉ hành động vặn xoắn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('緜', '{"9000": "7617.0", "Chữ Trung Quốc": "緜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 15 | nét | 帛 | bạch | biểu nghĩa | lụa trắng, vải | 系 | hệ | biểu nghĩa | sợi, nối liền | 緜 là chữ hội ý (hội ý): 帛 (Bạch, lụa) + 系 (Hệ, sợi nối), gợi ý tơ lụa mỏng manh kéo dài liên tục. Về sau phát triển thành 綿 và sinh ra 棉.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miên\": 帛 (lụa) + 系 (sợi) — sợi lụa miên man kéo dài không dứt, mềm mại như bông. | Gương Hán-Việt | miên — trong \"miên man\" (kéo dài), \"miên mật\" (liên tục) | Mở khoá kiến thức | Biết 緜 (miên) mở khoá 綿 (miên, bông vải), 棉 (miên, bông), nhóm chữ chỉ sợi mềm liên tục.", "Tự nguyên_Xie": "Theo nghiên cứu Zhao (1996) và Chen (2018), 緜 biến thể hình học từ 縣, kết hợp 帛 (lụa) và 系 (sợi). Chữ này về sau phát triển thành 綿 (bông, tơ) và tạo ra chữ con 棉. Nghĩa gốc: tơ tằm mỏng manh kéo dài. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tơ tằm; kéo dài, liền; mềm mại", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "帛 + 系", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰帛系", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "系", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "帛", "Unihan_Simplified (Chữ Giản thể)": "緜", "Unihan_Traditional (Chữ Phồn thể)": "緜", "Pinyin_Xie": "mián", "Âm Hán Việt_Xie": "miên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm danh từ chỉ tơ sợi hoặc tính từ mô tả sự kéo dài, mềm mại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繑', '{"9000": "7618.0", "Chữ Trung Quốc": "繑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 18 | nét | 繑 | kiều | tượng hình | dây buộc quần áo | 繑 thuộc bộ Mịch (糸, tơ sợi). Tiểu triện còn lưu hình. Cấu trúc nội bộ chưa được Wiktionary phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiều\": bộ Mịch (糸, sợi) — sợi dây kiều kỳ dùng buộc chặt vạt áo. | Gương Hán-Việt | kiều — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 繑 (kiều) nhận ra nhóm chữ bộ Mịch chỉ dây, dải vải trang phục.", "Tự nguyên_Xie": "Tiểu triện | 繑 chỉ dây buộc hoặc dải vải dùng trong trang phục. Tiểu triện còn hình dạng cổ. Chưa có nguồn học thuật phân tích cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "繑", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 喬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹喬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "繑", "Unihan_Traditional (Chữ Phồn thể)": "繑", "Pinyin_Xie": "qiāo", "Âm Hán Việt_Xie": "kiều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ mép viền giày hoặc động từ chỉ việc khâu viền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纑', '{"9000": "7619.0", "Chữ Trung Quốc": "纑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 22 | nét | 纑 | lô | tượng hình | sợi gai đã giã mềm | 纑 thuộc bộ Mịch (糸, tơ sợi). Cấu trúc chi tiết chưa được Wiktionary phân tích. Chữ chỉ sợi gai sau khi xử lý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lô\": bộ Mịch (糸, sợi) — sợi lô mộc đã xử lý, thô như lau sậy nhưng dệt được. | Gương Hán-Việt | lô — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 纑 (lô) mở khoá nhóm chữ bộ Mịch chỉ các loại sợi thô chưa qua dệt.", "Tự nguyên_Xie": "纑 chỉ sợi gai hoặc gai đã giã mềm sẵn sàng kéo sợi. Wiktionary chỉ ghi nhận âm đọc mà không phân tích cấu tạo. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợi vải; gai giã rồi", "Hạng Tần Suất (Jun Da)": "7619.0", "Tần Suất % (Jun Da)": "99.9987933067", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 盧", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹盧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "盧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "纑", "Unihan_Traditional (Chữ Phồn thể)": "纑", "Pinyin_Xie": "lú", "Âm Hán Việt_Xie": "lư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên liệu dệt may thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠙', '{"9000": "7620.0", "Chữ Trung Quốc": "蠙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 20 | nét | 虫 | trùng | biểu nghĩa | sâu, côn trùng, động vật nhỏ | 賓 | tân | biểu âm | khách (cho âm) | 蠙 là chữ hình thanh (psc): 虫 (Trùng, biểu nghĩa: sinh vật nhỏ/thủy sản) + 賓 (Tân, biểu âm). Chỉ loài hàu hoặc con trai biển cho ngọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tân\": 虫 (sinh vật biển) + 賓 (Tân, biểu âm) — con trai tân quý giá nhả ra 蠙珠 (ngọc trai). | Gương Hán-Việt | tân — ít dùng độc lập; xuất hiện trong 蠙珠 (ngọc trai) | Mở khoá kiến thức | Biết 蠙 (tân) giúp đọc văn cổ nói về ngọc trai và hàu biển.", "Tự nguyên_Xie": "蠙 là chữ hình thanh: bộ Trùng (虫) biểu nghĩa chỉ sinh vật biển, 賓 biểu âm. Dùng trong 蠙珠 (ngọc trai). Wiktionary ghi nhận nghĩa cổ: loài hàu biển. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con chồn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 賓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫賓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "賓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "𧏖", "Unihan_Traditional (Chữ Phồn thể)": "蠙", "Pinyin_Xie": "pín", "Âm Hán Việt_Xie": "tân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài trai sông sinh ngọc quý. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輴', '{"9000": "7621.0", "Chữ Trung Quốc": "輴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 16 | nét | 輴 | xuân | tượng hình | xe tang chở linh cữu | 輴 thuộc bộ Xa (車, xe). Cấu trúc chi tiết không có trong Wiktionary. Chữ chỉ loại xe đặc biệt dùng trong tang lễ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xuân\": bộ Xa (車, xe) — xe xuân (tang) chậm rãi chở linh cữu trong nghi lễ tiễn biệt. | Gương Hán-Việt | xuân — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 輴 (xuân) giúp nhận ra bộ Xa (車) trong chữ chỉ các loại xe chuyên dụng cổ đại.", "Tự nguyên_Xie": "輴 chỉ xe chở linh cữu trong tang lễ hoặc xe trượt trên bùn lầy. Wiktionary không phân tích cấu tạo. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xe chở linh cữu, xe tang; công cụ giao thông đi trên sình lầy", "Hạng Tần Suất (Jun Da)": "7621.0", "Tần Suất % (Jun Da)": "99.9987979578", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 盾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車盾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "盾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "輴", "Unihan_Traditional (Chữ Phồn thể)": "輴", "Pinyin_Xie": "chūn", "Âm Hán Việt_Xie": "xuân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phương tiện vận chuyển đặc biệt thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酨', '{"9000": "7622.0", "Chữ Trung Quốc": "酨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 13 | nét | 酉 | dậu | biểu nghĩa | bình rượu, dậu (can chi) | 𢦏 | biểu âm | cho âm | 酨 là chữ hình thanh (psc): 酉 (Dậu, biểu nghĩa: rượu/bình rượu) + 𢦏 (biểu âm). Wiktionary xác nhận cấu trúc psc rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tải\": 酉 (bình rượu) + âm tải — rượu chua tải đầy vò, vị chua sắc như muối dưa. | Gương Hán-Việt | tải — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 酨 (tải) giúp nhận ra nhóm chữ bộ Dậu (酉) chỉ các loại rượu và đồ lên men.", "Tự nguyên_Xie": "酨 là chữ hình thanh: bộ Dậu (酉) biểu nghĩa chỉ rượu, 𢦏 biểu âm. Nghĩa: rượu chua hoặc đồ hầm. Wiktionary ghi nhận âm đọc trung cổ và thượng cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Món hầm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "𢦏 + 酉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𢦏酉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𢦏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酨", "Unihan_Traditional (Chữ Phồn thể)": "酨", "Pinyin_Xie": "zài", "Âm Hán Việt_Xie": "tải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại nước chua dùng trong ẩm thực cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鏂', '{"9000": "7623.0", "Chữ Trung Quốc": "鏂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 19 | nét | 鏂 | âu | tượng hình | kim loại hoặc đồ vật bằng kim loại | 鏂 thuộc bộ Kim (金, kim loại). Cấu trúc chi tiết chưa được Wiktionary phân tích, chỉ ghi nhận âm đọc và định nghĩa chưa rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"âu\": bộ Kim (金, kim loại) — vật kim loại dạng âu (cái bát) hoặc cái móc kim loại. | Gương Hán-Việt | âu — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鏂 (âu) giúp nhận ra bộ Kim (金) trong chữ chỉ đồ vật kim loại ít gặp.", "Tự nguyên_Xie": "鏂 thuộc bộ Kim (金). Wiktionary ghi nhận âm đọc nhưng không phân tích cấu tạo hoặc nghĩa cụ thể. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鏂", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 區", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金區", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "區", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鏂", "Unihan_Traditional (Chữ Phồn thể)": "鏂", "Pinyin_Xie": "ōu", "Âm Hán Việt_Xie": "âu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ đồ đựng bằng kim loại hoặc vũ khí cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('駹', '{"9000": "7624.0", "Chữ Trung Quốc": "駹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 17 | nét | 駹 | mang | tượng hình | ngựa đen mặt trắng | 駹 thuộc bộ Mã (馬, ngựa). Cấu trúc chi tiết chưa được Wiktionary phân tích rõ ràng. Chữ chỉ loại ngựa đặc thù theo màu lông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mang\": bộ Mã (馬, ngựa) — ngựa mang lông đen mặt trắng, tương phản rõ như ánh mang lung linh. | Gương Hán-Việt | mang — ít dùng trong từ Hán-Việt hiện đại; cf. 茫 (mang mang, mênh mông) | Mở khoá kiến thức | Biết 駹 (mang) giúp đọc văn cổ miêu tả các loại ngựa theo màu lông đặc trưng.", "Tự nguyên_Xie": "駹 chỉ ngựa đen với mặt trắng, hoặc gia súc tạp sắc. Wiktionary ghi nhận âm đọc và nghĩa nhưng không phân tích cấu tạo. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa ô; ngựa đen; gia súc tạp sắc", "Hạng Tần Suất (Jun Da)": "7624.0", "Tần Suất % (Jun Da)": "99.9988026088", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 尨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬尨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "駹", "Unihan_Traditional (Chữ Phồn thể)": "駹", "Pinyin_Xie": "máng", "Âm Hán Việt_Xie": "mang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ giống ngựa hoặc tính từ mô tả màu lông hỗn hợp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞕', '{"9000": "7625.0", "Chữ Trung Quốc": "瞕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 16 | nét | 瞕 | chướng | tượng hình | đục thủy tinh thể, bệnh mắt | 瞕 thuộc bộ Mục (目, mắt). Cấu trúc chi tiết không có trong Wiktionary. Chữ chỉ bệnh đục thủy tinh thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chướng\": bộ Mục (目, mắt) — màn chướng che phủ mắt, tầm nhìn bị cản như qua tấm kính mờ. | Gương Hán-Việt | chướng — trong \"chướng ngại\" (vật cản); ở đây là vật cản trong mắt | Mở khoá kiến thức | Biết 瞕 (chướng) giúp nhận ra bộ Mục (目) trong chữ chỉ bệnh lý mắt.", "Tự nguyên_Xie": "瞕 chỉ bệnh đục thủy tinh thể (cataract) trong mắt. Wiktionary không phân tích cấu tạo. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đục thủy tinh thể trong mắt", "Hạng Tần Suất (Jun Da)": "7625.0", "Tần Suất % (Jun Da)": "99.9988057096", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 章", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目章", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "章", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞕", "Unihan_Traditional (Chữ Phồn thể)": "瞕", "Pinyin_Xie": "zhàng", "Âm Hán Việt_Xie": "trướng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ chứng bệnh mờ mắt hoặc tính từ mô tả trạng thái mắt không nhìn rõ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肻', '{"9000": "7626.0", "Chữ Trung Quốc": "肻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | 肻 | khẩn | tượng hình | gân thịt, xương ức | 肻 thuộc bộ Nhục (肉/月, thịt). Kim văn còn lưu hình. Cấu trúc chi tiết không có trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khẩn\": bộ Nhục (月/肉, thịt) — phần gân thịt khẩn (chắc, bám) vào xương, không dễ tách rời. | Gương Hán-Việt | khẩn — cf. 肯 (khẳng, chịu/ưng thuận); 肻 là dạng hiếm cùng gốc | Mở khoá kiến thức | Biết 肻 (khẩn) giúp nhận ra nhóm chữ bộ Nhục (月) chỉ các bộ phận cơ thể cụ thể.", "Tự nguyên_Xie": "Kim văn | 肻 có âm đọc gần 肯 (khẳng, xương ức/gân). Kim văn còn hình. Wiktionary không phân tích cấu tạo. Có thể là dạng cổ hoặc biến thể của 肯. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Xu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 月", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "肻", "Unihan_Traditional (Chữ Phồn thể)": "肻", "Pinyin_Xie": "kěn", "Âm Hán Việt_Xie": "khẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Trợ động từ | 能愿动词 | Động từ | 动词 | Thường dùng như một trợ động từ đứng trước động từ khác để biểu thị sự đồng ý hoặc sẵn lòng làm gì. | Trợ động từ | 能愿动词 | Đứng trước động từ chính để nêu khả năng, ý muốn hoặc sự cho phép: 会, 能, 可以, 想, 要. Phủ định đặt 不 trước chính nó — 不能去. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鐰', '{"9000": "7627.0", "Chữ Trung Quốc": "鐰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 21 | nét | 鐰 | thao | tượng hình | đồng thau, kim loại màu vàng | 鐰 thuộc bộ Kim (金, kim loại). Cấu trúc chi tiết chưa được Wiktionary phân tích rõ ràng. Chữ chỉ đồng thau hoặc kim loại tương tự.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thao\": bộ Kim (金, kim loại) — kim loại thao (đồng thau) vàng óng như \"vàng thau\" trong ca dao Việt. | Gương Hán-Việt | thao — trong \"mâm thau\", \"vàng thau\"; đồng thau quen thuộc trong văn hóa Việt | Mở khoá kiến thức | Biết 鐰 (thao) giúp nhận ra từ chỉ đồng thau trong văn bản Hán cổ và chữ Nôm.", "Tự nguyên_Xie": "鐰 chỉ đồng thau (thau đồng), âm đọc thao/thau trong tiếng Việt Hán. Wiktionary ghi nhận nhiều âm đọc (qiāo, cáo, sào, shǔ) nhưng không phân tích cấu tạo. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thau; như \"mâm thau\" (vhn) thao; như \"vàng thau\" (btcn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 喿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金喿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鐰", "Unihan_Traditional (Chữ Phồn thể)": "鐰", "Pinyin_Xie": "qiāo", "Âm Hán Việt_Xie": "thiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ chất liệu đồng thau hoặc các vật dụng làm từ thau. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綵', '{"9000": "7628.0", "Chữ Trung Quốc": "綵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 14 | nét | 糹 | mịch | biểu nghĩa | tơ, sợi, lụa | 采 | thái | biểu âm | hái lượm (cho âm) | 綵 là chữ hình thanh (psc): 糹 (Mịch, biểu nghĩa: tơ lụa) + 采 (Thái, biểu âm). Wiktionary xác nhận cấu trúc psc. Chữ truyền thống chỉ lụa nhiều màu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thải\": 糹 (tơ lụa) + 采 (Thái, biểu âm) — lụa thải màu rực rỡ, kết 綵 trang trí trong lễ hội. | Gương Hán-Việt | thải — trong \"kết thải\" (kết 綵), \"cắt thải\" (剪綵); lễ khai trương | Mở khoá kiến thức | Biết 綵 (thải) mở khoá từ 張燈結綵 (treo đèn kết thải), 剪綵 (cắt băng khánh thành).", "Tự nguyên_Xie": "綵 là chữ hình thanh: bộ Mịch (糸/糹) biểu nghĩa chỉ tơ lụa, 采 biểu âm (âm thái/thải). Nghĩa: lụa nhiều màu rực rỡ, hoa văn trang trí. Wiktionary ghi nhận nhiều từ ghép như 張燈結綵, 剪綵. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1537.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Thái (1127)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糸 /chỉ ý) ở bên trái chữ Thái (số 1127 - ngắt lấy/ 采 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thái chỉ âm, bộ Mịch chỉ ý. Thái là loại tơ lụa có màu sắc lộng lẫy, rực rỡ. (Thường được dùng chung và giản thể thành chữ 彩).", "Nghĩa Tiếng Việt_Xie": "tia sáng; rực rỡ, nhiều màu; tiếng hoan hô, reo hò", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 采", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹采", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "采", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "䌽", "Unihan_Traditional (Chữ Phồn thể)": "綵", "Pinyin_Xie": "cǎi", "Âm Hán Việt_Xie": "thải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ dải lụa màu trang trí hoặc tính từ chỉ sự rực rỡ, đa sắc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鮰', '{"9000": "7629.0", "Chữ Trung Quốc": "鮰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 鮰 | hồi | tượng hình | cá nguy, cá trê sông Dương Tử | 鮰 thuộc bộ Ngư (魚, cá). Cấu trúc chi tiết không có trong Wiktionary. Chữ chỉ loài cá nước ngọt sông Dương Tử.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồi\": bộ Ngư (魚, cá) — cá hồi lội ngược dòng về nguồn như hồi hương. | Gương Hán-Việt | hồi — ít dùng trong từ Hán-Việt hiện đại cho loài cá | Mở khoá kiến thức | Biết 鮰 (hồi) giúp nhận ra bộ Ngư (魚) trong tên các loài cá hiếm của sông Trung Quốc.", "Tự nguyên_Xie": "鮰 chỉ loài cá nước ngọt sông Dương Tử (Leiocassis longirostris). Wiktionary không phân tích cấu tạo. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá nguy (leiocassis longirostris)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 回", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚回", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "回", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鮰", "Unihan_Traditional (Chữ Phồn thể)": "鮰", "Pinyin_Xie": "huí", "Âm Hán Việt_Xie": "nguy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong tên gọi các loài cá sông hoặc món ăn chế biến từ cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳾', '{"9000": "7630.0", "Chữ Trung Quốc": "鳾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 15 | nét | 鳾 | thi | tượng hình | chim leo cây (nuthatch) | 鳾 thuộc bộ Điểu (鳥, chim). Cấu trúc chi tiết không có trong Wiktionary. Chữ chỉ nhóm chim nhỏ leo cây.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thi\": bộ Điểu (鳥, chim) — chim thi (nuthatch) leo cây xuống đầu để tìm sâu, như người thi thố tài năng. | Gương Hán-Việt | thi — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鳾 (thi) giúp nhận ra bộ Điểu (鳥) trong tên các loài chim hiếm trong điển tịch.", "Tự nguyên_Xie": "鳾 chỉ nhóm chim nhỏ (tổng danh). Wiktionary không phân tích cấu tạo. Bộ Điểu (鳥) xác nhận đây là chim. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con rùa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "帀 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰帀鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "䴓", "Unihan_Traditional (Chữ Phồn thể)": "鳾", "Pinyin_Xie": "shī", "Âm Hán Việt_Xie": "thi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các tài liệu sinh học để chỉ loài chim trèo cây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虰', '{"9000": "7631.0", "Chữ Trung Quốc": "虰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 8 | nét | 虫 | trùng | biểu nghĩa | côn trùng, sâu bọ | 丁 | đinh | biểu âm | đinh (cho âm) | 虰 thuộc bộ Trùng (虫). Khả năng cao là chữ hình thanh: 虫 biểu nghĩa + 丁 biểu âm (âm đinh). Wiktionary ghi nhận hai âm dīng và chēng. Chỉ dùng trong từ 虰蛵.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đinh\": 虫 (côn trùng) + 丁 (Đinh, biểu âm) — con đinh trùng trong từ 虰蛵, nhỏ như cái đinh. | Gương Hán-Việt | đinh — ít dùng độc lập; chỉ xuất hiện trong 虰蛵 | Mở khoá kiến thức | Biết 虰 (đinh) giúp nhận ra từ 虰蛵 trong văn cổ miêu tả côn trùng.", "Tự nguyên_Xie": "虰 chỉ dùng trong từ 虰蛵. Wiktionary ghi nhận cấu trúc có yếu tố Trùng (虫) và âm đinh. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn rõ ràng. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem 虰 蛵", "Hạng Tần Suất (Jun Da)": "7631.0", "Tần Suất % (Jun Da)": "99.9988181124", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 丁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫丁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "虰", "Unihan_Traditional (Chữ Phồn thể)": "虰", "Pinyin_Xie": "dīng", "Âm Hán Việt_Xie": "đinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ, xuất hiện chủ yếu trong các từ ghép cổ để chỉ các loài côn trùng nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驎', '{"9000": "7632.0", "Chữ Trung Quốc": "驎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 22 | nét | 馬 | mã | biểu nghĩa | ngựa | 粦 | lân | biểu âm | lân (cho âm) | 驎 thuộc bộ Mã (馬, ngựa). Khả năng cao là chữ hình thanh: 馬 biểu nghĩa + phần âm biểu âm lân. Chỉ dùng trong từ 騏驎 (kỳ lân ngựa).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lân\": bộ Mã (馬, ngựa) + âm lân — ngựa lân kỳ diệu trong từ 騏驎, linh vật chạy ngàn dặm. | Gương Hán-Việt | lân — trong 騏驎 (kỳ lân, ngựa thiên lý); cf. 麟 (kỳ lân thú) | Mở khoá kiến thức | Biết 驎 (lân) giúp đọc từ 騏驎 trong thơ ca cổ điển ca ngợi tuấn mã.", "Tự nguyên_Xie": "驎 chỉ dùng trong từ 騏驎 (rút gọn của 騏驎, chỉ ngựa thiên lý hoặc kỳ thú). Wiktionary ghi nhận âm lín và hạn chế dùng độc lập. chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tao", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 粦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬粦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "粦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "𬴊", "Unihan_Traditional (Chữ Phồn thể)": "驎", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn học cổ để chỉ những con chiến mã có màu sắc đặc biệt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荬', '{"9000": "7633.0", "Chữ Trung Quốc": "荬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 买 | mãi | biểu âm | mua (cho âm) | 荬 là giản thể của 蕒, bản thân là chữ hình thanh: 艹 (Thảo, biểu nghĩa: thực vật) + 买 (Mãi, biểu âm). Wiktionary xác nhận đây là giản thể, đọc âm mǎi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mãi\": 艹 (cỏ/cây) + 买 (Mãi, biểu âm) — rau mãi (rau riếp dại) hái không tốn tiền mua. | Gương Hán-Việt | mãi — trong \"cự mãi thái\" (rau riếp lớn, loài rau dân gian) | Mở khoá kiến thức | Biết 荬 (mãi) giúp nhận ra từ 苦荬菜 (rau đắng dại) trong văn bản y học/thực vật học.", "Tự nguyên_Xie": "荬 là chữ giản thể hóa từ 蕒 (蕒菜, rau riếp hoang). Wiktionary ghi nhận 荬 = giản thể của 买 bộ + 艹. Là loại rau dại ăn được trong văn hóa dân gian. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rau củ mại; mãi; như \"cự mãi thái (rau riếp)\" (gdhn)", "Hạng Tần Suất (Jun Da)": "7633.0", "Tần Suất % (Jun Da)": "99.9988212131", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 买", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹买", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "买", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荬", "Unihan_Traditional (Chữ Phồn thể)": "蕒", "Pinyin_Xie": "mǎi", "Âm Hán Việt_Xie": "mại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong tên gọi các loại rau dại hoặc thảo dược dân gian. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鑛', '{"9000": "7634.0", "Chữ Trung Quốc": "鑛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 22 | nét | 金 | kim | biểu nghĩa | kim loại | 廣 | quảng | biểu âm | rộng, Quảng (cho âm) | 鑛 là chữ hình thanh (psc): 金 (Kim, biểu nghĩa: kim loại/khoáng vật) + 廣 (Quảng, biểu âm). Wiktionary xác nhận cấu trúc psc. Dạng truyền thống của 礦.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoáng\": 金 (kim loại) + 廣 (Quảng, biểu âm) — mỏ khoáng (鑛) rộng lớn chứa kim loại quý. | Gương Hán-Việt | khoáng — trong \"khoáng sản\" (tài nguyên khoáng vật), \"khoáng chất\" | Mở khoá kiến thức | Biết 鑛 (khoáng) mở khoá 礦石 (quặng), 礦山 (mỏ), nhóm từ công nghiệp khai khoáng.", "Tự nguyên_Xie": "鑛 là chữ hình thanh: bộ Kim (金) biểu nghĩa chỉ kim loại/khoáng sản, 廣 biểu âm (âm quảng/khoáng). Wiktionary ghi nhận 鑛 là dạng cũ của 礦 (quặng). Nghĩa: quặng kim loại, mỏ khoáng sản. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quặng, khoáng sản", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 廣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金廣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "廣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鑛", "Unihan_Traditional (Chữ Phồn thể)": "鑛", "Pinyin_Xie": "kuàng", "Âm Hán Việt_Xie": "khoáng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loại quặng mỏ hoặc khoáng chất tự nhiên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('犏', '{"9000": "7635.0", "Chữ Trung Quốc": "犏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 牛 | Số nét | 13 | nét | 牛 | ngưu | biểu nghĩa | bò, trâu | 扁 | thiên | biểu âm | dẹt (cho âm) | 犏 là chữ hình thanh (psc): 牛 (Ngưu, biểu nghĩa: bò) + 扁 (Thiên, biểu âm). Wiktionary xác nhận cấu trúc psc. Chỉ con bò lai giữa bò yak và bò thường.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiên\": 牛 (bò) + 扁 (Thiên, biểu âm) — con bò thiên (lai) dẹt lưng thấp, lai giữa yak và bò đồng bằng. | Gương Hán-Việt | thiên — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 犏 (thiên) giúp đọc văn bản nông nghiệp/sinh thái về động vật lai ở Tây Tạng.", "Tự nguyên_Xie": "犏 là chữ hình thanh: bộ Ngưu (牛) biểu nghĩa chỉ bò, 扁 biểu âm. Nghĩa: dzo (con lai giữa bò yak cái và bò đực thường). Wiktionary trích dẫn Thủy Đông Nhật Ký thế kỷ 15: \"牦牛與黃牛合，則生犏牛\". | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con bò lai", "Hạng Tần Suất (Jun Da)": "7635.0", "Tần Suất % (Jun Da)": "99.9988243138", "GavinGrover_Once (Chiết tự trực tiếp)": "牛 + 扁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰牛扁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "扁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "牛", "Unihan_Simplified (Chữ Giản thể)": "犏", "Unihan_Traditional (Chữ Phồn thể)": "犏", "Pinyin_Xie": "piān", "Âm Hán Việt_Xie": "thiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ loài bò lai giữa bò Tây Tạng và bò vàng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞧', '{"9000": "7636.0", "Chữ Trung Quốc": "鞧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 18 | nét | 革 | cách | biểu nghĩa | da thuộc | 酋 | tù | biểu âm | thủ lĩnh (cho âm) | 鞧 là chữ hình thanh (psc): 革 (Cách, biểu nghĩa: da thuộc) + 酋 (Tù, biểu âm). Wiktionary xác nhận cấu trúc psc. Chỉ dây da buộc phía sau ngựa kéo xe.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thu\": 革 (da thuộc) + 酋 (Tù, biểu âm) — dây da thu chặt phía sau yên ngựa, giữ vững khi chạy. | Gương Hán-Việt | thu — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鞧 (thu) giúp nhận ra bộ Cách (革) trong chữ chỉ dụng cụ da thuộc cho ngựa.", "Tự nguyên_Xie": "鞧 là chữ hình thanh: bộ Cách (革) biểu nghĩa chỉ da thuộc/yên cương, 酋 biểu âm (âm tù/thu). Nghĩa: dây crupper (dải da vòng qua đuôi ngựa giữ yên không trượt). Wiktionary ghi nhận từ 後鞧, 馬鞧. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây thắng đái", "Hạng Tần Suất (Jun Da)": "7636.0", "Tần Suất % (Jun Da)": "99.9988258642", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 酋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革酋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "酋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞧", "Unihan_Traditional (Chữ Phồn thể)": "鞧", "Pinyin_Xie": "qiū", "Âm Hán Việt_Xie": "thu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ bộ phận dây cương bằng da vòng qua mông gia súc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鮋', '{"9000": "7637.0", "Chữ Trung Quốc": "鮋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 魚 | ngư | biểu nghĩa | cá | 由 | do | biểu âm | do (cho âm) | 鮋 là chữ hình thanh (psc): 魚 (Ngư, biểu nghĩa: cá) + 由 (Do, biểu âm). Wiktionary xác nhận cấu trúc psc. Chỉ loài cá mù cơ (scorpionfish).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"do\": 魚 (cá) + 由 (Do, biểu âm) — cá do dự ẩn mình dưới đá, loài cá độc như bọ cạp biển. | Gương Hán-Việt | do — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 鮋 (do) giúp nhận ra bộ Ngư (魚) trong tên loài cá biển sâu ít phổ biến.", "Tự nguyên_Xie": "鮋 là chữ hình thanh: bộ Ngư (魚) biểu nghĩa chỉ cá, 由 biểu âm (âm do/dầu). Chỉ loài cá mù cơ (Sebastiscus) hoặc cá bọ cạp biển. Wiktionary xác nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tao", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 由", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚由", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "由", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鮋", "Unihan_Traditional (Chữ Phồn thể)": "鮋", "Pinyin_Xie": "yóu", "Âm Hán Việt_Xie": "do", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong tên gọi các loài cá thuộc họ cá mù làn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盕', '{"9000": "7638.0", "Chữ Trung Quốc": "盕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 11 | nét | 盕 | phạm | tượng hình | đồ đựng (bộ Mãnh) | 盕 thuộc bộ Mãnh (皿, đồ đựng). Cấu trúc chi tiết không có trong Wiktionary. Chữ rất hiếm, nghĩa không rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phạm\": bộ Mãnh (皿, đồ đựng) — cái đồ đựng phạm (rộng khắp), hình dung vật chứa lớn. | Gương Hán-Việt | phạm — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 盕 (phạm) giúp nhận ra bộ Mãnh (皿) trong chữ chỉ đồ đựng cổ đại.", "Tự nguyên_Xie": "盕 thuộc bộ Mãnh (皿). Wiktionary không phân tích cấu tạo hoặc nghĩa cụ thể. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "畕", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "汎 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱汎皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "汎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盕", "Unihan_Traditional (Chữ Phồn thể)": "盕", "Pinyin_Xie": "fàn", "Âm Hán Việt_Xie": "phạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động nước tràn ra hoặc vật nổi lên mặt nước. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盩', '{"9000": "7639.0", "Chữ Trung Quốc": "盩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 17 | nét | 盩 | châu | tượng hình | tên địa danh cổ (huyện Châu Chí) | 盩 thuộc bộ Mãnh (皿). Cấu trúc chi tiết không có trong Wiktionary. Chữ chủ yếu dùng trong địa danh Châu Chí (盩厔) ở Thiểm Tây.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"châu\": bộ Mãnh (皿) — địa danh châu (盩厔) ở Thiểm Tây, vùng đất lịch sử. | Gương Hán-Việt | châu — dùng trong địa danh 盩厔; cf. 州 (châu, đơn vị hành chính) | Mở khoá kiến thức | Biết 盩 (châu) giúp nhận ra địa danh 盩厔 trong văn bản lịch sử Trung Quốc.", "Tự nguyên_Xie": "盩 dùng trong địa danh 盩厔 (Châu Chí, huyện ở tỉnh Thiểm Tây). Wiktionary không phân tích cấu tạo. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Châu Chí (tên huyện ở tỉnh Thiểm Tây, Trung Quốc.)", "Hạng Tần Suất (Jun Da)": "7639.0", "Tần Suất % (Jun Da)": "99.9988325824", "GavinGrover_Once (Chiết tự trực tiếp)": "𪯧 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𪯧皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𪯧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盩", "Unihan_Traditional (Chữ Phồn thể)": "盩", "Pinyin_Xie": "zhōu", "Âm Hán Việt_Xie": "chu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ chỉ sự quanh co hoặc làm danh từ trong địa danh cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盻', '{"9000": "7640.0", "Chữ Trung Quốc": "盻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 9 | nét | 目 | mục | biểu nghĩa | mắt | 兮 | hề | biểu âm | than từ (cho âm) | 盻 thuộc bộ Mục (目, mắt). Khả năng cao là chữ hình thanh: 目 biểu nghĩa + phần biểu âm. Chỉ cái nhìn giận dữ, nhìn trừng trừng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hệ\": bộ Mục (目, mắt) — đôi mắt hệ (trừng) nhìn trừng trừng với sự giận dữ, tức tối. | Gương Hán-Việt | hệ — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 盻 (hệ) giúp nhận ra nhóm chữ bộ Mục (目) chỉ các kiểu nhìn khác nhau.", "Tự nguyên_Xie": "盻 chỉ nhìn giận dữ hoặc nhìn trừng trừng với thái độ oán hận. Wiktionary ghi nhận nhưng không phân tích cấu tạo chi tiết. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhìn giận dữ; nhìn trừng trừng", "Hạng Tần Suất (Jun Da)": "7640.0", "Tần Suất % (Jun Da)": "99.998833616", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 兮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目兮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "盻", "Unihan_Traditional (Chữ Phồn thể)": "盻", "Pinyin_Xie": "xì", "Âm Hán Việt_Xie": "hễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ thể hiện ánh mắt giận dữ hoặc liếc nhìn ai đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眖', '{"9000": "7641.0", "Chữ Trung Quốc": "眖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 10 | nét | 眖 | khoáng | tượng hình | mắt mờ hoặc trạng thái của mắt | 眖 thuộc bộ Mục (目, mắt). Cấu trúc chi tiết không có trong Wiktionary. Chữ rất hiếm, nghĩa không rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoáng\": bộ Mục (目, mắt) — mắt khoáng đãng nhìn xa rộng, tầm nhìn khoáng. | Gương Hán-Việt | khoáng — cf. 眶 (khoáng, hốc mắt) | Mở khoá kiến thức | Biết 眖 (khoáng) giúp nhận ra bộ Mục (目) trong chữ chỉ trạng thái mắt.", "Tự nguyên_Xie": "眖 thuộc bộ Mục (目). Wiktionary không có trang cho chữ này. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "眖", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 兄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目兄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眖", "Unihan_Traditional (Chữ Phồn thể)": "眖", "Pinyin_Xie": "kuàng", "Âm Hán Việt_Xie": "khoáng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động nhìn hoặc ghé mắt xem trong văn ngôn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砛', '{"9000": "7642.0", "Chữ Trung Quốc": "砛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 9 | nét | 砛 | câm | tượng hình | đá ngầm, đá chìm dưới nước | 砛 thuộc bộ Thạch (石, đá). Cấu trúc chi tiết không có trong Wiktionary. Chữ chỉ đá ngầm dưới nước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"câm\": bộ Thạch (石, đá) — tảng đá câm lặng ẩn mình dưới nước, ngầm mà nguy hiểm. | Gương Hán-Việt | câm — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 砛 (câm) giúp nhận ra bộ Thạch (石) trong chữ chỉ các loại đá đặc biệt.", "Tự nguyên_Xie": "砛 chỉ đá ngầm (submerged rock), theo từ điển Hán-Việt Nguyễn Quốc Hùng: \"đá ngầm\". Wiktionary không có trang cho chữ này. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngầm; như \"đá ngầm\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 今", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石今", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "今", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砛", "Unihan_Traditional (Chữ Phồn thể)": "砛", "Pinyin_Xie": "jin", "Âm Hán Việt_Xie": "câm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các rạn đá hoặc đá tảng ẩn dưới mặt nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硈', '{"9000": "7643.0", "Chữ Trung Quốc": "硈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 硈 | khiếp | tượng hình | đá cứng hoặc trạng thái đá | 硈 thuộc bộ Thạch (石, đá). Cấu trúc chi tiết không có trong Wiktionary. Chữ rất hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiếp\": bộ Thạch (石, đá) — đá khiếp (cứng cứng, sắc bén) vỡ lẻ ra từng mảnh. | Gương Hán-Việt | khiếp — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 硈 (khiếp) giúp nhận ra bộ Thạch (石) trong chữ chỉ tính chất đá.", "Tự nguyên_Xie": "硈 thuộc bộ Thạch (石). Wiktionary không có trang cho chữ này. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "爡", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 吉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石吉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硈", "Unihan_Traditional (Chữ Phồn thể)": "硈", "Pinyin_Xie": "qià", "Âm Hán Việt_Xie": "khiếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Dùng làm tính từ chỉ độ cứng của đá hoặc danh từ mô tả âm thanh đá va chạm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禢', '{"9000": "7644.0", "Chữ Trung Quốc": "禢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 14 | nét | 禢 | tạ | tượng hình | họ Tạ hoặc liên quan nghi lễ | 禢 thuộc bộ Thị (示, nghi lễ/thần linh). Cấu trúc chi tiết không có trong Wiktionary. Chữ chỉ họ Tạ hoặc xem thêm 褟.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tạ\": bộ Thị (示, nghi lễ) — họ Tạ được ghi bằng bộ Thị, liên quan đến lễ nghi thần linh. | Gương Hán-Việt | tạ — trong họ Tạ (tên người); cf. 謝 (tạ, cảm ơn/xin lỗi) | Mở khoá kiến thức | Biết 禢 (tạ) giúp nhận ra bộ Thị (示) trong chữ liên quan đến họ tên và nghi lễ.", "Tự nguyên_Xie": "禢 thuộc bộ Thị (示). Có thể dùng cho họ Tạ hoặc liên quan 褟. Wiktionary không phân tích cấu tạo. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem thêm 褟 [ta1]; họ Tạ", "Hạng Tần Suất (Jun Da)": "7644.0", "Tần Suất % (Jun Da)": "99.9988377502", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 𦐇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻𦐇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦐇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禢", "Unihan_Traditional (Chữ Phồn thể)": "禢", "Pinyin_Xie": "tà", "Âm Hán Việt_Xie": "tháp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ chỉ họ người hoặc tên riêng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禥', '{"9000": "7645.0", "Chữ Trung Quốc": "禥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 15 | nét | 禥 | kỳ | tượng hình | dị bản của 祺 (kỳ phúc, điều lành) | 禥 là dị thể của 祺, thuộc bộ Thị (示, nghi lễ/phúc lành). Wiktionary xác nhận: 禥 = dị thể tự của 祺. Chỉ điều may mắn, kỳ phúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": bộ Thị (示, phúc lành thần) — chữ kỳ (禥) như 祺, chỉ điều kỳ diệu tốt lành đến từ thần linh. | Gương Hán-Việt | kỳ — trong \"kỳ phúc\" (điều may mắn); cf. 祺 (kỳ, cát tường) | Mở khoá kiến thức | Biết 禥 (kỳ) mở khoá 祺 (kỳ phúc), nhóm chữ bộ Thị chỉ điều lành trong lễ nghi.", "Tự nguyên_Xie": "禥 là dị thể của 祺 (kỳ, phúc lành, điều tốt lành). Wiktionary xác nhận quan hệ này. Bộ Thị (示) liên quan đến nghi lễ thần linh và điều phúc lành. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "禥", "Hạng Tần Suất (Jun Da)": "7645.0", "Tần Suất % (Jun Da)": "99.9988387838", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 基", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻基", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "基", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禥", "Unihan_Traditional (Chữ Phồn thể)": "禥", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ chỉ điềm lành hoặc tính từ trong tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窼', '{"9000": "7646.0", "Chữ Trung Quốc": "窼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 16 | nét | 窼 | tiêu | tượng hình | dị bản, nghĩa không rõ | 窼 thuộc bộ Huyệt (穴, hốc/hang). Cấu trúc chi tiết không có trong Wiktionary. Chữ rất hiếm, được ghi là dị bản của một chữ khác.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": bộ Huyệt (穴, hốc) — cái hốc tiêu điều, trống rỗng như hang hoang. | Gương Hán-Việt | tiêu — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 窼 (tiêu) giúp nhận ra bộ Huyệt (穴) trong chữ chỉ chỗ lõm rỗng.", "Tự nguyên_Xie": "窼 thuộc bộ Huyệt (穴). Wiktionary không phân tích cấu tạo. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "缪", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 巢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴巢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窼", "Unihan_Traditional (Chữ Phồn thể)": "窼", "Pinyin_Xie": "zhāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ tổ của các loài chim muông thú vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('竏', '{"9000": "7647.0", "Chữ Trung Quốc": "竏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 立 | Số nét | 8 | nét | 立 | lập | biểu nghĩa | đứng, đơn vị | 千 | thiên | biểu âm | nghìn (cho âm và nghĩa số lượng) | 竏 là chữ phái sinh hiện đại: 立 (đơn vị đo lường) + 千 (Thiên, nghìn) — gợi ý kilô (nghìn đơn vị). Chỉ đơn vị đo lường kilolít. Chữ tạo muộn trong hệ thống đo lường hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiên\": 立 (đơn vị) + 千 (Thiên, nghìn) — một thiên lít (kilolít), đơn vị đo thể tích lớn. | Gương Hán-Việt | thiên — trong \"thiên lít\" (kilolít); cf. 千 (thiên, nghìn) | Mở khoá kiến thức | Biết 竏 (thiên) giúp nhận ra hệ thống chữ đo lường SI trong văn bản khoa học tiếng Trung.", "Tự nguyên_Xie": "竏 là chữ tạo muộn trong hệ thống đo lường hiện đại của Trung Quốc, chỉ kilolít (kl). Dựa trên bộ Lập (立) biểu thị đơn vị thể tích + 千 gợi ý tiền tố kilo (nghìn). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "竏", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "立 + 干", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰立干", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "干", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "立", "Unihan_Simplified (Chữ Giản thể)": "竏", "Unihan_Traditional (Chữ Phồn thể)": "竏", "Pinyin_Xie": "qian", "Âm Hán Việt_Xie": "thiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Chữ này dùng làm lượng từ đo lường thể tích trong hệ mét cổ. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筈', '{"9000": "7648.0", "Chữ Trung Quốc": "筈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 12 | nét | 竹 | trúc | biểu nghĩa | tre, vật làm từ tre | 活 | hoạt | biểu âm | sống/linh hoạt (cho âm gần) | 筈 thuộc bộ Trúc (竹, tre). Khả năng cao là chữ hình thanh: 竹 biểu nghĩa + phần âm biểu âm (gần âm kuò). Chỉ đuôi mũi tên (nock) thường làm bằng tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quát\": 竹 (tre) + âm quát — phần đuôi tre quát (chặn) mũi tên vào dây cung, giữ chắc khi bắn. | Gương Hán-Việt | quát — ít dùng độc lập; xuất hiện trong 箭筈 (đuôi mũi tên) | Mở khoá kiến thức | Biết 筈 (quát) mở khoá 箭筈 (nock của mũi tên) trong văn bản võ thuật/cung tên cổ đại.", "Tự nguyên_Xie": "筈 chỉ phần đuôi mũi tên (nock), chỗ đặt lên dây cung. Thường làm bằng tre, do đó bộ Trúc (竹). Wiktionary ghi nhận nghĩa literary: arrow nock. Từ ghép 箭筈. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đuôi mũi tên", "Hạng Tần Suất (Jun Da)": "7648.0", "Tần Suất % (Jun Da)": "99.9988418845", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 舌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮舌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筈", "Unihan_Traditional (Chữ Phồn thể)": "筈", "Pinyin_Xie": "kuò", "Âm Hán Việt_Xie": "quát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận khấc ở đuôi mũi tên để đặt vào dây cung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筽', '{"9000": "7649.0", "Chữ Trung Quốc": "筽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 13 | nét | 筽 | ổ | tượng hình | dạng chữ không rõ nguồn gốc, thuộc bộ 竹 (trúc) | 筽 thuộc bộ 竹 (Trúc). Cấu trúc nội bộ không được ghi nhận trong các nguồn hiện có. Chưa xác định rõ hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ổ\": bộ 竹 (trúc) gợi đồ vật bằng tre — chữ hiếm, ít dùng trong văn bản hiện đại. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa chữ 筽 trong tiếng Việt. | Mở khoá kiến thức | Chữ 筽 cực kỳ hiếm, chưa có trong từ điển Hán-Việt thông dụng — gặp trong văn bản cổ liên quan đến tre nứa.", "Tự nguyên_Xie": "Chữ 筽 thuộc bộ 竹 (trúc), gợi liên quan đến tre hoặc đồ vật làm từ tre. Không có nguồn Wiktionary hay giáp cốt/kim văn ghi lại. Chữ tạo muộn, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tháng sáu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 吴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮吴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筽", "Unihan_Traditional (Chữ Phồn thể)": "筽", "Pinyin_Xie": "o", "Âm Hán Việt_Xie": "ổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng trong địa danh ở một số vùng của Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篴', '{"9000": "7650.0", "Chữ Trung Quốc": "篴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 竹 | trúc | biểu nghĩa | tre, bamboo | 逐 | trục | biểu âm | đuổi theo (biểu âm) | 篴 = 竹 (Trúc, biểu nghĩa: tre) + 逐 (Trục, biểu âm). Chữ hình thanh: bộ 竹 cho biết liên quan đến tre/sáo trúc; 逐 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"địch\": bộ 竹 (trúc) + 逐 (trục) → sáo trúc xưa, âm vang đuổi theo gió — nhớ 篴 là nhạc cụ tre cổ. | Gương Hán-Việt | \"Địch\" trong \"địch thủ\" (敵手) dùng chữ khác; 篴 là chữ hiếm chỉ riêng loại sáo trúc cổ. | Mở khoá kiến thức | Biết 篴 giúp nhận ra nhóm chữ nhạc cụ bộ 竹: 笛 (địch, sáo), 篴 (sáo cổ), 籥 (ước, sáo lỗ).", "Tự nguyên_Xie": "Theo Wiktionary, 篴 là chữ hình thanh (psc): 竹 (tre) làm thành phần biểu nghĩa, 逐 làm thành phần biểu âm. Chữ chỉ loại sáo trúc trong văn bản cổ Trung Quốc. Chưa thấy dạng giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái sáo (để thổi)", "Hạng Tần Suất (Jun Da)": "7650.0", "Tần Suất % (Jun Da)": "99.9988439517", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 逐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮逐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "逐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篴", "Unihan_Traditional (Chữ Phồn thể)": "篴", "Pinyin_Xie": "dí", "Âm Hán Việt_Xie": "địch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ chỉ nhạc cụ thổi bằng trúc, tương tự như chữ địch thông thường. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籆', '{"9000": "7651.0", "Chữ Trung Quốc": "籆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 19 | nét | 籆 | ước | tượng hình | thuộc bộ 竹, cấu trúc nội bộ không rõ | 籆 thuộc bộ 竹 (Trúc). Cấu trúc chi tiết không được ghi nhận; có thể là dạng hình thanh nhưng chưa xác định được thành phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ước\": bộ 竹 (trúc) gợi đồ vật bằng tre — 籆 là trục quay tre dùng để cuộn chỉ tơ trong nghề dệt cổ. | Gương Hán-Việt | \"Ước\" trong \"ước lượng\" (約量) dùng chữ khác; 籆 là chữ hiếm chuyên ngành dệt cổ. | Mở khoá kiến thức | Chữ 籆 mở khoá nhóm từ vựng nghề dệt cổ điển và đồ dùng bằng tre trong văn bản Hán.", "Tự nguyên_Xie": "Chữ 籆 thuộc bộ 竹, chỉ cuộn chỉ hoặc trục quay bằng tre. Không có nguồn Wiktionary hay dạng giáp cốt/kim văn được ghi lại. Chữ tạo muộn, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "guồng; cái guồng (dụng cụ để quay tơ, sợi...)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 蒦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮蒦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蒦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "籆", "Unihan_Traditional (Chữ Phồn thể)": "籆", "Pinyin_Xie": "yuè", "Âm Hán Việt_Xie": "dược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ chỉ dụng cụ dùng để cuộn tơ hoặc sợi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籇', '{"9000": "7652.0", "Chữ Trung Quốc": "籇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 20 | nét | 籇 | hào | tượng hình | thuộc bộ 竹, cấu trúc không rõ | 籇 thuộc bộ 竹 (Trúc). Thành phần nội bộ không được ghi nhận trong CHISE hay Wiktionary. Chưa xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hào\": bộ 竹 (trúc) — 籇 là chữ cực hiếm thuộc nhóm đồ vật hoặc nhạc cụ bằng tre trong cổ văn. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 籇 trong tiếng Việt. | Mở khoá kiến thức | Chữ 籇 gặp chủ yếu trong từ điển chuyên khảo chữ Hán cổ; ít dùng trong văn bản thực tế.", "Tự nguyên_Xie": "Chữ 籇 thuộc bộ 竹. Không có nguồn Wiktionary hay dạng giáp cốt/kim văn. Chữ tạo muộn, chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "燇", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 豪", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮豪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "籇", "Unihan_Traditional (Chữ Phồn thể)": "籇", "Pinyin_Xie": "háo", "Âm Hán Việt_Xie": "hào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ chỉ các loại dụng cụ đan bằng tre nứa thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('紏', '{"9000": "7653.0", "Chữ Trung Quốc": "紏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 10 | nét | 紏 | cữu | tượng hình | thuộc bộ 糸 (mịch), cấu trúc không rõ | 紏 thuộc bộ 糸 (Mịch, sợi tơ). Cấu trúc chi tiết không được ghi nhận. Bộ 糸 gợi liên quan đến sợi chỉ, dây buộc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cữu\": bộ 糸 (mịch, sợi tơ) — 紏 gợi hình ảnh sợi chỉ hoặc dây buộc trong cổ văn. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 紏 trong tiếng Việt. | Mở khoá kiến thức | Biết bộ 糸 (mịch) giúp nhận ra nhóm chữ liên quan đến sợi vải: 经 (kinh), 纺 (phưởng), 紏 (hiếm).", "Tự nguyên_Xie": "Chữ 紏 thuộc bộ 糸 (sợi tơ). Không có nguồn Wiktionary hay dạng giáp cốt/kim văn. Chữ tạo muộn, chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "珴", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 斗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹斗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "紏", "Unihan_Traditional (Chữ Phồn thể)": "紏", "Pinyin_Xie": "tǒu", "Âm Hán Việt_Xie": "cữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này dùng làm danh từ chỉ sợi tơ hoặc tính từ chỉ màu sắc của ngọc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肣', '{"9000": "7654.0", "Chữ Trung Quốc": "肣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | 肣 | hàm | tượng hình | thuộc bộ 月/肉, cấu trúc nội bộ không xác định | 肣 thuộc bộ 月/肉 (Nhục, thịt). Cấu trúc nội bộ không được CHISE ghi nhận. Bộ 肉 gợi liên quan đến bộ phận cơ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàm\" (cằm): bộ 肉 (nhục) cho biết đây là bộ phận cơ thể — hình dung cái hàm/cằm gắn với thịt ở mặt. | Gương Hán-Việt | \"Hàm\" trong \"hàm răng\" (gần nghĩa hàm/cằm); 肣 là dạng chữ cổ ít dùng. | Mở khoá kiến thức | Biết 肣 giúp nhận ra nhóm chữ bộ 肉 chỉ bộ phận mặt: 颏 (cằm), 颌 (hàm), 肣 (cổ tự).", "Tự nguyên_Xie": "Tiểu triện | Chữ 肣 thuộc bộ 肉 (nhục, thịt), đọc âm Hán là hán (MC: hán). Wiktionary không ghi rõ glyphOrigin; dạng tiểu triện còn lưu lại. Nghĩa cụ thể chưa được xác định trong nguồn học thuật. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cằm; như \"cái cằm\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 今", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月今", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "今", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肣", "Unihan_Traditional (Chữ Phồn thể)": "肣", "Pinyin_Xie": "hán", "Âm Hán Việt_Xie": "hàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ chỉ bộ phận cằm trên khuôn mặt người hoặc động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胑', '{"9000": "7655.0", "Chữ Trung Quốc": "胑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 9 | nét | 肉 | nhục | biểu nghĩa | thịt, bộ phận cơ thể | 只 | chỉ | biểu âm | chỉ (biểu âm) | 胑 = 肉 (Nhục, biểu nghĩa: thịt/bộ phận cơ thể) + 只 (Chỉ, biểu âm). Chữ hình thanh: bộ 肉 cho biết liên quan đến chi thể; 只 cho âm đọc. Wiktionary ghi đây là dị thể của 肢.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chi\": 肉 (nhục, thịt) + 只 (chỉ, biểu âm) → tay chân là \"chi\" của cơ thể — 胑 là dạng cổ của 肢. | Gương Hán-Việt | \"Chi\" trong \"tứ chi\" (四肢, bốn chi); 胑 là dạng cổ ít dùng của 肢. | Mở khoá kiến thức | Biết 胑 = 肢 cổ thể giúp đọc văn bản y học và cổ điển: tứ 胑 = tứ chi (四肢).", "Tự nguyên_Xie": "Theo Wiktionary, 胑 là chữ hình thanh (psc): 肉 (thịt/chi thể) làm biểu nghĩa, 只 làm biểu âm. Đây là dạng thay thế cổ của 肢 (chi, tay chân). Không tìm thấy dạng giáp cốt hay kim văn riêng biệt. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chân của động vật; đôi cánh của chim", "Hạng Tần Suất (Jun Da)": "7655.0", "Tần Suất % (Jun Da)": "99.9988491195", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 只", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月只", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "只", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胑", "Unihan_Traditional (Chữ Phồn thể)": "胑", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "chi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ chỉ các bộ phận tay chân hoặc cánh của sinh vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臮', '{"9000": "7656.0", "Chữ Trung Quốc": "臮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 自 | Số nét | 12 | nét | 自 | tự | biểu âm | tự (biểu âm) | 乑 | biểu nghĩa | ba người đứng (biểu nghĩa) | 臮 = 自 (Tự, biểu âm) + 乑 (ba người đứng, biểu nghĩa). Chữ hình thanh: 乑 gợi ý nghĩa tập hợp người; 自 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tức\": 乑 (ba người) + 自 (tự, biểu âm) → nhiều người tụ lại — 臮 gợi hình ảnh đám đông hay cộng đồng. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 臮 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Chữ 臮 cực hiếm; biết bộ 乑 (ba người) giúp nhận ra nhóm chữ chỉ tập thể trong văn bản cổ.", "Tự nguyên_Xie": "Theo Wiktionary, 臮 là chữ hình thanh (psc): 乑 (ba người đứng) làm biểu nghĩa, 自 làm biểu âm. Nghĩa gốc liên quan đến tập hợp hoặc cộng đồng người. Chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "议", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "自 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱自", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "臮", "Unihan_Traditional (Chữ Phồn thể)": "臮", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "tức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Liên từ | 连词 | Giới từ | 介词 | Động từ | 动词 | Chữ này thường dùng làm liên từ hoặc giới từ trong văn ngôn để biểu thị sự đồng hành hoặc giới hạn. | Liên từ | 连词 | Nối từ, cụm từ hoặc mệnh đề: 和, 但是, 因为…所以…. Lưu ý 和 chỉ nối danh từ, không nối hai câu như ''và'' tiếng Việt. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苲', '{"9000": "7657.0", "Chữ Trung Quốc": "苲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 苲 | rạ | tượng hình | thuộc bộ 艸 (thảo), cấu trúc không rõ | 苲 thuộc bộ 艸 (Thảo, cỏ). Cấu trúc nội bộ không được ghi nhận. Bộ 艸 cho biết liên quan đến thực vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"rạ\": bộ 艸 (thảo, cỏ) — 苲 gợi hình ảnh cỏ rạ, thực vật dại mọc ven nước trong cổ văn. | Gương Hán-Việt | \"Rạ\" trong tiếng Việt chỉ thân lúa sau thu hoạch; 苲 là chữ Hán tương ứng cho loại cỏ/rạ. | Mở khoá kiến thức | Biết 苲 giúp đọc văn bản nông nghiệp cổ và thực vật học Hán cổ điển.", "Tự nguyên_Xie": "Chữ 苲 thuộc bộ 艸 (cỏ), đọc Hán-Việt là rạ. Không có nguồn Wiktionary hay dạng giáp cốt/kim văn. Nghĩa liên quan đến loại cỏ dại hay rong nước. Chữ tạo muộn, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rong", "Hạng Tần Suất (Jun Da)": "7657.0", "Tần Suất % (Jun Da)": "99.9988511866", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 乍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹乍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苲", "Unihan_Traditional (Chữ Phồn thể)": "苲", "Pinyin_Xie": "zhǎ", "Âm Hán Việt_Xie": "trả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ một loại cỏ nước hoặc dùng trong địa danh cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒃', '{"9000": "7658.0", "Chữ Trung Quốc": "蒃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 蒃 | chuyển | tượng hình | thuộc bộ 艸, cấu trúc không rõ | 蒃 thuộc bộ 艸 (Thảo, cỏ). Cấu trúc nội bộ không được CHISE ghi nhận. Bộ 艸 gợi liên quan đến thực vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chuyển\": bộ 艸 (thảo) — 蒃 là chữ hiếm chỉ loại thực vật không xác định trong văn bản cổ. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 蒃 trong tiếng Việt. | Mở khoá kiến thức | Chữ 蒃 cực hiếm, gặp trong từ điển chuyên khảo thực vật học cổ điển.", "Tự nguyên_Xie": "Chữ 蒃 thuộc bộ 艸 (cỏ). Không có nguồn Wiktionary hay dạng cổ nào ghi lại. Chữ tạo muộn, chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "胃", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 彖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹彖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒃", "Unihan_Traditional (Chữ Phồn thể)": "蒃", "Pinyin_Xie": "zhuàn", "Âm Hán Việt_Xie": "chuyển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn bản cổ để chỉ dạ dày hoặc nét chữ triện. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虗', '{"9000": "7659.0", "Chữ Trung Quốc": "虗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虍 | Số nét | 11 | nét | 虗 | hư | tượng hình | dạng cổ của 虚 (hư, trống rỗng), bộ 虍 | 虗 là dạng cổ/dị thể của 虚 (Hư), thuộc bộ 虍 (Hổ). Cấu trúc nội bộ không được CHISE ghi nhận rõ; chỉ có dạng Lục thư thông (thời Minh) lưu lại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hư\": 虗 là dạng cổ của 虚 — hư không, trống rỗng, như \"hư tâm\" (lòng khiêm tốn) hay \"hư ảo\" (ảo tưởng). | Gương Hán-Việt | \"Hư\" trong \"hư không\" (虛空), \"hư tâm\" (虛心), \"hư cấu\" (虛構). | Mở khoá kiến thức | Biết 虗 = 虚 cổ thể giúp đọc văn bản Đạo giáo và triết học cổ: 虗靜 (hư tĩnh), 虗無 (hư vô).", "Tự nguyên_Xie": "Lục thư thông | 虗 là dạng cổ của 虚 (hư, trống rỗng). Chỉ có dạng Lục thư thông (biên soạn thời Minh) — chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Nghĩa: trống rỗng, không có thực chất, khiêm tốn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "虗", "Hạng Tần Suất (Jun Da)": "7659.0", "Tần Suất % (Jun Da)": "99.9988532538", "GavinGrover_Once (Chiết tự trực tiếp)": "虍 + 丘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴虍丘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虍", "Unihan_Simplified (Chữ Giản thể)": "虗", "Unihan_Traditional (Chữ Phồn thể)": "虗", "Pinyin_Xie": "xū", "Âm Hán Việt_Xie": "hư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ đứng trước danh từ hoặc làm vị ngữ để chỉ trạng thái trống rỗng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜌', '{"9000": "7660.0", "Chữ Trung Quốc": "蜌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 蜌 | bí | tượng hình | thuộc bộ 虫, cấu trúc không rõ | 蜌 thuộc bộ 虫 (Trùng, sâu bọ). Cấu trúc nội bộ không được CHISE ghi nhận. Bộ 虫 gợi liên quan đến động vật nhỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": bộ 虫 (trùng) — 蜌 chỉ con sò biển nhỏ, vỏ cứng; nhớ bộ 虫 là dấu hiệu loài vật nhỏ. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 蜌 trong tiếng Việt. | Mở khoá kiến thức | Biết 蜌 giúp nhận ra nhóm chữ bộ 虫 chỉ động vật thân mềm trong văn bản cổ.", "Tự nguyên_Xie": "Chữ 蜌 thuộc bộ 虫 (sâu bọ), chỉ loài sò/hến biển (clam). Không có nguồn Wiktionary hay dạng giáp cốt/kim văn. Chữ tạo muộn, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蜜", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 坒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫坒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "坒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜌", "Unihan_Traditional (Chữ Phồn thể)": "蜌", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loài động vật thân mềm hai mảnh vỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跘', '{"9000": "7661.0", "Chữ Trung Quốc": "跘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 12 | nét | 跘 | bán | tượng hình | thuộc bộ 足, cấu trúc không rõ | 跘 thuộc bộ 足 (Túc, chân). Cấu trúc nội bộ không được CHISE ghi nhận. Bộ 足 gợi liên quan đến động tác chân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bán\": bộ 足 (túc, chân) — 跘 gợi hình ảnh bước chân vấp vào vật gì, dáng đi không vững. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 跘 trong tiếng Việt. | Mở khoá kiến thức | Biết 跘 giúp đọc văn bản cổ miêu tả dáng đi, bước chân trong thơ văn Hán.", "Tự nguyên_Xie": "Chữ 跘 thuộc bộ 足 (chân). Không có nguồn Wiktionary hay dạng giáp cốt/kim văn. Nghĩa liên quan đến bước đi hoặc vấp ngã. Chữ tạo muộn, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蘘", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 半", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊半", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "半", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跘", "Unihan_Traditional (Chữ Phồn thể)": "跘", "Pinyin_Xie": "pán", "Âm Hán Việt_Xie": "bán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động đi đứng không vững hoặc bị vấp ngã. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鷭', '{"9000": "7662.0", "Chữ Trung Quốc": "鷭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 23 | nét | 番 | phan | biểu âm | phiên/phan (biểu âm) | 鳥 | điểu | biểu nghĩa | chim | 鷭 = 番 (Phan, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim). Chữ hình thanh: bộ 鳥 cho biết đây là loài chim; 番 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phàn\": 鳥 (điểu, chim) + 番 (phan, biểu âm) → chim le le nước — 鷭 là loài chim dưới nước trong văn học cổ. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 鷭 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 鷭 giúp đọc thơ văn tả cảnh đồng quê: chim le le, diệc nước xuất hiện thường xuyên trong thơ Tống.", "Tự nguyên_Xie": "Theo Wiktionary, 鷭 là chữ hình thanh (psc): 鳥 (chim) làm biểu nghĩa, 番 làm biểu âm. Chỉ loài chim le le hay diệc nước (waterhen/moorhen). Chưa thấy dạng giáp cốt. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gà phiên (loài gà có chân xanh, sống ở bờ nước, ăn cá, ốc, côn trùng)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "番 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰番鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "番", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "𬸪", "Unihan_Traditional (Chữ Phồn thể)": "鷭", "Pinyin_Xie": "fán", "Âm Hán Việt_Xie": "phàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc trong cụm từ để chỉ loài chim nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸼', '{"9000": "7663.0", "Chữ Trung Quốc": "鸼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 11 | nét | 鸼 | trứu | tượng hình | thuộc bộ 鸟, loài chim cổ | 鸼 thuộc bộ 鸟 (Điểu, chim). Cấu trúc nội bộ không được CHISE ghi nhận. Bộ 鸟 xác nhận đây là loài chim.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trứu\": bộ 鸟 (điểu) — 鸼 là tên một loài chim cổ, gặp trong từ điển bách khoa thời Hán. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 鸼 trong tiếng Việt. | Mở khoá kiến thức | Chữ 鸼 thuộc nhóm chim tên cổ trong bộ 鸟 — gặp trong Nhĩ Nhã (爾雅) và Thuyết Văn.", "Tự nguyên_Xie": "Tiểu triện | Chữ 鸼 thuộc bộ 鸟 (chim). Có dạng tiểu triện lưu lại. Không có nguồn Wiktionary chi tiết về glyphOrigin. Chỉ loài chim không xác định trong văn bản cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cốt trào (một loại chim nói trong sách cổ); châu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鸟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "鸼", "Unihan_Traditional (Chữ Phồn thể)": "鸼", "Pinyin_Xie": "zhōu", "Âm Hán Việt_Xie": "điểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn học cổ để chỉ một loài chim giống chim bói cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹐', '{"9000": "7664.0", "Chữ Trung Quốc": "鹐", "Bộ thủ & thành phần_Xie": "Số nét | 13 | nét | 鹐 | tiêm | tượng hình | thuộc bộ 鸟, cấu trúc không rõ | 鹐 thuộc bộ 鸟 (Điểu, chim). Cấu trúc chi tiết không được CHISE ghi nhận. Wiktionary xác nhận nghĩa: chim mổ (to peck).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêm\": bộ 鸟 (điểu) — 鹐 gợi hình ảnh con chim nghiêng đầu mổ vào thức ăn, mổ vào vật gì đó. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 鹐 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 鹐 giúp đọc thơ văn tả hành động của chim trong văn học cổ điển Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 鹐 (qiān) có nghĩa cổ: (chim) mổ. Dùng theo nghĩa ẩn dụ trong văn học. Không có glyphOrigin chi tiết hay dạng giáp cốt/kim văn. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mổ; ăn (chim, gà)", "Hạng Tần Suất (Jun Da)": "7664.0", "Tần Suất % (Jun Da)": "99.9988604888", "GavinGrover_Once (Chiết tự trực tiếp)": "臽 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰臽鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹐", "Unihan_Traditional (Chữ Phồn thể)": "鵮", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "khiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ thức ăn để tả hành động của loài chim. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矄', '{"9000": "7665.0", "Chữ Trung Quốc": "矄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 19 | nét | 矄 | huân | tượng hình | thuộc bộ 目, cấu trúc không rõ | 矄 thuộc bộ 目 (Mục, mắt). Cấu trúc nội bộ không được CHISE ghi nhận. Bộ 目 gợi liên quan đến thị giác hay ánh mắt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huân\": bộ 目 (mục, mắt) — 矄 gợi trạng thái mắt mờ, nhìn không rõ hoặc ánh sáng le lói. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 矄 trong tiếng Việt. | Mở khoá kiến thức | Chữ 矄 cực hiếm, thuộc nhóm chữ bộ 目 mô tả trạng thái thị giác đặc biệt.", "Tự nguyên_Xie": "Chữ 矄 thuộc bộ 目 (mắt). Không có nguồn Wiktionary hay dạng giáp cốt/kim văn. Chữ tạo muộn, chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "焄", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 熏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目熏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "熏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "矄", "Unihan_Traditional (Chữ Phồn thể)": "矄", "Pinyin_Xie": "xūn", "Âm Hán Việt_Xie": "huân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho mắt hoặc trạng thái ánh sáng mờ tối. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魖', '{"9000": "7666.0", "Chữ Trung Quốc": "魖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬼 | Số nét | 20 | nét | 魖 | hư | tượng hình | thuộc bộ 鬼, cấu trúc không rõ | 魖 thuộc bộ 鬼 (Quỷ, ma). Cấu trúc nội bộ không được CHISE ghi nhận. Bộ 鬼 xác nhận liên quan đến ma quỷ hay linh hồn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hư\": bộ 鬼 (quỷ) + âm hư → hồn ma hư ảo — 魖 là tên gọi một loại linh hồn vô định trong văn hóa cổ. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 魖 trong tiếng Việt. | Mở khoá kiến thức | Biết 魖 giúp đọc văn bản đạo giáo và dân gian cổ về các loại ma quỷ.", "Tự nguyên_Xie": "Chữ 魖 thuộc bộ 鬼 (quỷ, ma), đọc xū. Wiktionary không ghi glyphOrigin chi tiết. Nghĩa liên quan đến loại ma hay linh hồn trong văn hóa dân gian cổ Trung Quốc. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màu đen; xem 黑 魖 魖 [hei1 xu1 xu1]", "Hạng Tần Suất (Jun Da)": "7666.0", "Tần Suất % (Jun Da)": "99.9988625559", "GavinGrover_Once (Chiết tự trực tiếp)": "鬼 + 虚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鬼虚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鬼", "Unihan_Simplified (Chữ Giản thể)": "魖", "Unihan_Traditional (Chữ Phồn thể)": "魖", "Pinyin_Xie": "xū", "Âm Hán Việt_Xie": "khư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ chỉ loài quỷ hoặc tính từ mô tả sắc đen tối tăm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴐', '{"9000": "7667.0", "Chữ Trung Quốc": "鴐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 16 | nét | 鴐 | già | tượng hình | thuộc bộ 鳥, loài ngỗng trời cổ | 鴐 thuộc bộ 鳥 (Điểu, chim). Cấu trúc nội bộ không được CHISE ghi nhận. Wiktionary ghi: chỉ dùng trong 鴐鵝 (jiā''é) — ngỗng trời/ngỗng tuyết (swan goose).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"già\": bộ 鳥 (điểu) — 鴐 chỉ xuất hiện trong 鴐鵝 (ngỗng trời); hình dung đàn ngỗng thiên di bay thành hàng chữ 一. | Gương Hán-Việt | \"Già\" trong \"鴐鵝\" (ngỗng thiên di); ít gặp độc lập trong Hán-Việt. | Mở khoá kiến thức | Biết 鴐 giúp đọc văn bản thiên nhiên và thơ tả chim di cư trong cổ điển Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 鴐 là chữ cổ, chỉ dùng trong từ ghép 鴐鵝 (swan goose — ngỗng thiên di). Không có glyphOrigin chi tiết hay dạng giáp cốt. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鐴", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "加 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱加鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "加", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鴐", "Unihan_Traditional (Chữ Phồn thể)": "鴐", "Pinyin_Xie": "gē", "Âm Hán Việt_Xie": "già", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ trong từ ghép để chỉ một loài chim nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薀', '{"9000": "7668.0", "Chữ Trung Quốc": "薀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 薀 | uẩn | tượng hình | thuộc bộ 艸, rong nước cổ tự | 薀 thuộc bộ 艸 (Thảo, cỏ). Cấu trúc nội bộ không được CHISE ghi nhận. Wiktionary ghi: nghĩa cổ gồm rong nước (waterweed) và tích tụ/ẩn chứa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uẩn\": bộ 艸 (thảo, cỏ) — 薀 gợi rong nước tích tụ dưới đáy ao, ẩn chứa như \"uẩn khúc\" trong tiếng Việt. | Gương Hán-Việt | \"Uẩn\" trong \"uẩn khúc\" (ẩn ý sâu xa); 薀 là dạng có bộ 艸, nhấn khía cạnh thực vật. | Mở khoá kiến thức | Biết 薀 giúp phân biệt với 蘊 (uẩn, tích tụ tinh thần) — 薀 nghiêng về thực vật nước.", "Tự nguyên_Xie": "Theo Wiktionary, 薀 (cổ chữ, đọc wēn hoặc yùn) có hai nghĩa: (1) loại rong nước, (2) tích tụ, ẩn chứa (dùng cổ). Không có glyphOrigin chi tiết. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "薀", "Hạng Tần Suất (Jun Da)": "6205.0", "Tần Suất % (Jun Da)": "99.9877831994", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 溫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹溫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "溫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕰", "Unihan_Traditional (Chữ Phồn thể)": "薀", "Pinyin_Xie": "yùn", "Âm Hán Việt_Xie": "uẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ sự tích tụ hoặc danh từ chỉ loài rong nước. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('謏', '{"9000": "7669.0", "Chữ Trung Quốc": "謏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 16 | nét | 謏 | tiểu | tượng hình | thuộc bộ 言, cấu trúc không rõ | 謏 thuộc bộ 言 (Ngôn, lời nói). Cấu trúc nội bộ không được CHISE ghi nhận. Bộ 言 gợi liên quan đến ngôn ngữ, danh tiếng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiểu\": bộ 言 (ngôn, lời) — 謏 gợi tiếng tăm nhỏ nhoi, tài học tầm thường — \"謏才\" (tiểu tài) là người học vấn hạn chế. | Gương Hán-Việt | \"謏才\" (tiểu tài) — người tài nhỏ; ít dùng trong Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 謏 giúp đọc văn bản tự khiêm trong văn học cổ: \"謏才陋識\" (tài mọn học hẹp).", "Tự nguyên_Xie": "Tiểu triện | Chữ 謏 thuộc bộ 言 (lời nói), đọc xiǎo, nghĩa nhỏ nhoi/tầm thường (về danh tiếng hoặc tài năng). Có dạng tiểu triện lưu lại. Không có glyphOrigin Wiktionary chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhỏ bé", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 叟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言叟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "𫍲", "Unihan_Traditional (Chữ Phồn thể)": "謏", "Pinyin_Xie": "xiǎo", "Âm Hán Việt_Xie": "tiểu, tẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ chỉ sự nhỏ nhặt hoặc động từ chỉ việc dụ dỗ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脎', '{"9000": "7670.0", "Chữ Trung Quốc": "脎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 脎 | tát | tượng hình | thuộc bộ 肉, cấu trúc không rõ | 脎 thuộc bộ 肉 (Nhục, thịt). Cấu trúc nội bộ không được CHISE ghi nhận. Bộ 肉 gợi liên quan đến cơ thể hoặc thịt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tát\": bộ 肉 (nhục) — 脎 là chữ cực hiếm thuộc nhóm bộ phận hay chất liệu cơ thể trong cổ văn. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 脎 trong tiếng Việt. | Mở khoá kiến thức | Chữ 脎 cực hiếm, gặp trong từ điển chuyên khảo y học cổ điển Trung Quốc.", "Tự nguyên_Xie": "Chữ 脎 thuộc bộ 肉 (thịt). Không có nguồn Wiktionary hay dạng cổ nào ghi lại. Chữ tạo muộn, chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ô-xa-dôn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 杀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月杀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "杀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脎", "Unihan_Traditional (Chữ Phồn thể)": "脎", "Pinyin_Xie": "sà", "Âm Hán Việt_Xie": "tát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ trong thuật ngữ hóa học để chỉ hợp chất osazone. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聧', '{"9000": "7671.0", "Chữ Trung Quốc": "聧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 15 | nét | 聧 | khuy | tượng hình | thuộc bộ 耳, cấu trúc không rõ | 聧 thuộc bộ 耳 (Nhĩ, tai). Cấu trúc nội bộ không được CHISE ghi nhận. Bộ 耳 gợi liên quan đến thính giác hay tai.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuy\": bộ 耳 (nhĩ, tai) — 聧 gợi hình ảnh cái tai khiếm khuyết, không nghe rõ tiếng. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 聧 trong tiếng Việt. | Mở khoá kiến thức | Chữ 聧 cực hiếm, thuộc nhóm chữ bộ 耳 mô tả trạng thái thính giác đặc biệt.", "Tự nguyên_Xie": "Chữ 聧 thuộc bộ 耳 (tai), đọc kuī. Wiktionary không ghi glyphOrigin chi tiết. Có thể liên quan đến điếc hoặc tai không nghe rõ. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "觧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 癸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳癸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "癸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聧", "Unihan_Traditional (Chữ Phồn thể)": "聧", "Pinyin_Xie": "kuī", "Âm Hán Việt_Xie": "khuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này dùng làm động từ chỉ sự chia lìa hoặc tính từ chỉ sự trái ngược nhau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脜', '{"9000": "7672.0", "Chữ Trung Quốc": "脜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 脜 | hữu | tượng hình | thuộc bộ 肉, cấu trúc không rõ | 脜 thuộc bộ 肉 (Nhục, thịt). Cấu trúc nội bộ không được CHISE ghi nhận. Bộ 肉 gợi liên quan đến cơ thể hoặc thịt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hữu\": bộ 肉 (nhục) — 脜 là chữ hiếm thuộc nhóm bộ phận hay trạng thái cơ thể trong cổ văn y học. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 脜 trong tiếng Việt. | Mở khoá kiến thức | Chữ 脜 cực hiếm, gặp trong văn bản y học hay bách khoa cổ điển.", "Tự nguyên_Xie": "Chữ 脜 thuộc bộ 肉 (thịt). Không có nguồn Wiktionary hay dạng giáp cốt/kim văn. Chữ tạo muộn, chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蜜", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 𦣻", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月𦣻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦣻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脜", "Unihan_Traditional (Chữ Phồn thể)": "脜", "Pinyin_Xie": "yǒu", "Âm Hán Việt_Xie": "hữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này dùng làm tính từ chỉ tính chất mềm mại hoặc danh từ chỉ sắc mặt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荖', '{"9000": "7673.0", "Chữ Trung Quốc": "荖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 荖 | lão | tượng hình | thuộc bộ 艸, cấu trúc không rõ | 荖 thuộc bộ 艸 (Thảo, cỏ). Cấu trúc nội bộ không được CHISE ghi nhận. Bộ 艸 gợi liên quan đến thực vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lão\": bộ 艸 (thảo) — 荖 là tên cổ của cây trầu không, loại thực vật quen thuộc trong văn hóa ăn trầu Á Đông. | Gương Hán-Việt | \"Lão\" trong tiếng Việt có nghĩa già; 荖 là chữ Hán chỉ cây trầu không, ít dùng trong Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 荖 giúp nhận ra tên gọi Hán cổ cho cây trầu không trong văn bản dược liệu và bản thảo học.", "Tự nguyên_Xie": "Chữ 荖 thuộc bộ 艸 (cỏ), đọc lǎo, chỉ lá trầu không (betel pepper leaf — Piper betle). Không có nguồn Wiktionary chi tiết. Chữ tạo muộn, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem \"差\"", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 老", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹老", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "老", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荖", "Unihan_Traditional (Chữ Phồn thể)": "荖", "Pinyin_Xie": "lǎo", "Âm Hán Việt_Xie": "sai, si, soa, ta, tha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ cây trầu hoặc các bộ phận của cây trầu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕌', '{"9000": "7674.0", "Chữ Trung Quốc": "蕌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕌 | lỗi | tượng hình | thuộc bộ 艸, cấu trúc không rõ | 蕌 thuộc bộ 艸 (Thảo, cỏ). Cấu trúc nội bộ không được CHISE ghi nhận. Bộ 艸 gợi liên quan đến thực vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lỗi\": bộ 艸 (thảo) — 蕌 là chữ hiếm chỉ loại cỏ/thực vật không xác định trong văn bản cổ. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 蕌 trong tiếng Việt. | Mở khoá kiến thức | Chữ 蕌 cực hiếm, gặp trong từ điển thực vật học cổ điển.", "Tự nguyên_Xie": "Chữ 蕌 thuộc bộ 艸 (cỏ). Không có nguồn Wiktionary hay dạng giáp cốt/kim văn. Chữ tạo muộn, chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "茌", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 晶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹晶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "晶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕌", "Unihan_Traditional (Chữ Phồn thể)": "蕌", "Pinyin_Xie": "lěi", "Âm Hán Việt_Xie": "lỗi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ chồi cây hoặc một loại kiệu hoang. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠷', '{"9000": "7675.0", "Chữ Trung Quốc": "蠷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 24 | nét | 蠷 | cự | tượng hình | thuộc bộ 虫, côn trùng cổ tự | 蠷 thuộc bộ 虫 (Trùng, sâu bọ). Cấu trúc nội bộ không được CHISE ghi nhận. Wiktionary xác nhận dùng trong 蠷蝚/蠷螋 (earwig — con đuôi kìm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cự\": bộ 虫 (trùng) — 蠷 gặp trong 蠷螋, chỉ con đuôi kìm (earwig) với đôi kìm đáng sợ ở đuôi. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 蠷 trong tiếng Việt. | Mở khoá kiến thức | Biết 蠷 giúp nhận ra tên gọi Hán cổ của các loài côn trùng trong bản thảo và côn trùng học cổ điển.", "Tự nguyên_Xie": "Theo Wiktionary, 蠷 dùng trong từ ghép 蠷螋 (earwig — con đuôi kìm). Không có glyphOrigin chi tiết hay dạng giáp cốt. Chữ tạo muộn, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cù; như \"cù sưu (loại bọ có càng phía sau đít)\"", "Hạng Tần Suất (Jun Da)": "7675.0", "Tần Suất % (Jun Da)": "99.9988739252", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 瞿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫瞿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瞿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠷", "Unihan_Traditional (Chữ Phồn thể)": "蠷", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "cù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường đi kèm với chữ khác để chỉ loài côn trùng đuôi kìm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褏', '{"9000": "7676.0", "Chữ Trung Quốc": "褏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 14 | nét | 褏 | tụ | tượng hình | thuộc bộ 衣, cấu trúc không rõ | 褏 thuộc bộ 衣 (Y, áo). Cấu trúc nội bộ không được CHISE ghi nhận. Bộ 衣 gợi liên quan đến trang phục.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tụ\": bộ 衣 (y, áo) — 褏 là dạng cổ của 袖 (tay áo); hình dung ống tay áo dài rủ xuống của trang phục cổ đại. | Gương Hán-Việt | \"Tụ\" (tay áo): 褏 là dạng cổ của 袖; gặp trong văn bản mô tả trang phục cổ. | Mở khoá kiến thức | Biết 褏 = 袖 cổ thể giúp đọc văn bản miêu tả trang phục trong thơ Đường, Tống.", "Tự nguyên_Xie": "Chữ 褏 thuộc bộ 衣 (áo), đọc xiù, nghĩa: tay áo (sleeve). Đây là dạng cổ của 袖 (xiù — tay áo). Không có glyphOrigin Wiktionary chi tiết hay dạng giáp cốt. Chữ tạo muộn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tay áo", "Hạng Tần Suất (Jun Da)": "7676.0", "Tần Suất % (Jun Da)": "99.9988749588", "GavinGrover_Once (Chiết tự trực tiếp)": "衣 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴衣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "褏", "Unihan_Traditional (Chữ Phồn thể)": "褏", "Pinyin_Xie": "xiù", "Âm Hán Việt_Xie": "tụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần ống tay của trang phục. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觽', '{"9000": "7677.0", "Chữ Trung Quốc": "觽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 角 | Số nét | 22 | nét | 觽 | huề | tượng hình | thuộc bộ 角, dụng cụ mở nút thắt bằng ngà | 觽 thuộc bộ 角 (Giác, sừng). Cấu trúc nội bộ không được CHISE ghi nhận. Wiktionary ghi đây là dạng thay thế của 觿 (xī) — dụng cụ mở nút thắt làm từ ngà/sừng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huề\": bộ 角 (giác, sừng) — 觽 là cái dùi ngà mở nút thắt, vật lễ nghi thời Chu — sừng nhọn dùng để gỡ nút. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 觽 trong tiếng Việt. | Mở khoá kiến thức | Biết 觽 giúp đọc Kinh Thi và văn bản lễ nghi Chu — vật dụng nghi lễ quan trọng.", "Tự nguyên_Xie": "Theo Wiktionary, 觽 là dạng thay thế của 觿. Đây là dụng cụ hình côn làm từ ngà voi hoặc sừng, dùng để mở nút thắt dây trong Chu Lễ. Không có glyphOrigin chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái móc tháo nút thắt", "Hạng Tần Suất (Jun Da)": "7677.0", "Tần Suất % (Jun Da)": "99.9988759923", "GavinGrover_Once (Chiết tự trực tiếp)": "角 + 嶲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰角嶲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "嶲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "角", "Unihan_Simplified (Chữ Giản thể)": "觽", "Unihan_Traditional (Chữ Phồn thể)": "觽", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "huề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ dụng cụ cổ đại làm bằng sừng để cởi nút dây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踫', '{"9000": "7678.0", "Chữ Trung Quốc": "踫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 15 | nét | 踫 | bổng | tượng hình | thuộc bộ 足, cấu trúc không rõ | 踫 thuộc bộ 足 (Túc, chân). Cấu trúc nội bộ không được CHISE ghi nhận. Bộ 足 gợi liên quan đến động tác chân hoặc va chạm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bổng\": bộ 足 (túc, chân) — 踫 gợi hai người va chân vào nhau khi đụng mặt; là dạng cổ/phương ngữ của 碰 (va chạm). | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 踫 trong tiếng Việt. | Mở khoá kiến thức | Biết 踫 = 碰 cổ/phương ngữ giúp đọc văn bản phương ngữ và cổ tịch miêu tả va chạm.", "Tự nguyên_Xie": "Chữ 踫 thuộc bộ 足 (chân), đọc pèng, nghĩa: va vào, đụng phải, gặp gỡ. Đây là dạng thay thế của 碰 (pèng) trong một số phương ngữ và văn bản cổ. Không có nguồn Wiktionary chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhấc lên", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 並", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊並", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "並", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踫", "Unihan_Traditional (Chữ Phồn thể)": "踫", "Pinyin_Xie": "pèng", "Âm Hán Việt_Xie": "bổng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ thể hiện hành động nâng vật gì đó lên cao hoặc va chạm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹽', '{"9000": "7679.0", "Chữ Trung Quốc": "蹽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 19 | nét | 足 | túc | biểu nghĩa | chân, bàn chân | 尞 | liêu | biểu âm | liêu (biểu âm) | 蹽 = 足 (Túc, biểu nghĩa: chân) + 尞 (Liêu, biểu âm). Chữ hình thanh: bộ 足 cho biết liên quan đến động tác chân; 尞 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trèo\": 足 (túc, chân) + 尞 (liêu, biểu âm) → dùng chân leo trèo lên cao — 蹽 là chữ Nôm ghi âm \"trèo\" trong tiếng Việt. | Gương Hán-Việt | \"Trèo\" trong tiếng Việt: trèo cây, leo trèo — 蹽 là chữ Nôm ghi âm này. | Mở khoá kiến thức | Biết 蹽 giúp đọc văn bản Nôm cổ: 蹽 = trèo (leo lên), phân biệt với 跳 (nhảy).", "Tự nguyên_Xie": "Theo Wiktionary Nôm, 蹽 là chữ Nôm đọc leo/trèo/trẹo (Hán-Việt: trèo). Cấu trúc hình thanh: 足 (chân, biểu nghĩa) + 尞 (liêu, biểu âm). Chữ chủ yếu dùng trong tiếng Việt cổ để ghi âm \"trèo\" (leo lên). Không có dạng giáp cốt. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lén lút bỏ đi", "Hạng Tần Suất (Jun Da)": "7679.0", "Tần Suất % (Jun Da)": "99.9988780595", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 尞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊尞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹽", "Unihan_Traditional (Chữ Phồn thể)": "蹽", "Pinyin_Xie": "liāo", "Âm Hán Việt_Xie": "liêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong khẩu ngữ để chỉ hành động đi nhanh hoặc trốn đi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軉', '{"9000": "7680.0", "Chữ Trung Quốc": "軉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 身 | Số nét | 27 | nét | 軉 | vũ | tượng hình | thuộc bộ 身, cấu trúc không rõ | 軉 thuộc bộ 身 (Thân, thân thể). Cấu trúc nội bộ không được CHISE ghi nhận. Bộ 身 gợi liên quan đến thân xác hoặc tư thế.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vũ\": bộ 身 (thân) — 軉 là chữ cực hiếm thuộc nhóm chữ mô tả thân hình hay tư thế trong cổ văn. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 軉 trong tiếng Việt. | Mở khoá kiến thức | Chữ 軉 cực hiếm, gặp trong từ điển chuyên khảo chữ Hán cổ.", "Tự nguyên_Xie": "Chữ 軉 thuộc bộ 身 (thân thể). Không có nguồn Wiktionary hay dạng giáp cốt/kim văn. Chữ tạo muộn, chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "艉", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "身 + 寶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰身寶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "身", "Unihan_Simplified (Chữ Giản thể)": "軉", "Unihan_Traditional (Chữ Phồn thể)": "軉", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "vũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ bộ phận phía sau hoặc bánh lái của thuyền bè. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('墚', '{"9000": "7681.0", "Chữ Trung Quốc": "墚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 14 | nét | 墚 | lương | tượng hình | thuộc bộ 土, cấu trúc không rõ | 墚 thuộc bộ 土 (Thổ, đất). Cấu trúc nội bộ không được CHISE ghi nhận. Bộ 土 gợi liên quan đến đất đai hoặc công trình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lương\": bộ 土 (thổ, đất) — 墚 gợi hình ảnh gờ đất hay đê đập, thường gặp trong địa danh vùng Sơn Tây Trung Quốc. | Gương Hán-Việt | \"Lương\" trong các địa danh Trung Quốc (vùng đất cao, gờ đất); ít dùng trong Hán-Việt thông thường. | Mở khoá kiến thức | Biết 墚 giúp đọc địa danh và văn bản địa lý cổ điển về vùng Hoàng Thổ Cao Nguyên.", "Tự nguyên_Xie": "Chữ 墚 thuộc bộ 土 (đất), đọc liáng. Nghĩa liên quan đến gờ đất, bờ đất hoặc địa danh (tên làng/địa phương ở Sơn Tây, Trung Quốc). Không có glyphOrigin Wiktionary chi tiết. Chữ tạo muộn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồi đất vàng (Tây Bắc, Trung Quốc)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 梁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土梁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "梁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "墚", "Unihan_Traditional (Chữ Phồn thể)": "墚", "Pinyin_Xie": "liáng", "Âm Hán Việt_Xie": "lương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ địa hình đồi đất dài và hẹp ở vùng Tây Bắc Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搌', '{"9000": "7682.0", "Chữ Trung Quốc": "搌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 13 | nét | 搌 | triển | tượng hình | thuộc bộ 手, cấu trúc không rõ | 搌 thuộc bộ 手 (Thủ, tay). Cấu trúc nội bộ không được CHISE ghi nhận. Bộ 手 gợi liên quan đến động tác tay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"triển\": bộ 手 (thủ, tay) — 搌 gợi bàn tay cầm khăn lau sạch bề mặt, chùi đi vết bẩn. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 搌 trong tiếng Việt. | Mở khoá kiến thức | Biết 搌 giúp đọc văn bản miêu tả công việc bếp núc và vệ sinh trong văn học cổ điển.", "Tự nguyên_Xie": "Chữ 搌 thuộc bộ 手 (tay), đọc zhǎn. Wiktionary chỉ ghi {{Han etym}} không có glyphOrigin chi tiết. Nghĩa: lau, chùi, thấm hút (như lau bằng vải). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lau, thấm, chùi; buộc, bó lại", "Hạng Tần Suất (Jun Da)": "7682.0", "Tần Suất % (Jun Da)": "99.9988821938", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 展", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌展", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "展", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "搌", "Unihan_Traditional (Chữ Phồn thể)": "搌", "Pinyin_Xie": "zhǎn", "Âm Hán Việt_Xie": "triển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ động tác lau nhẹ hoặc thấm hút chất lỏng bằng vải. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('擗', '{"9000": "7683.0", "Chữ Trung Quốc": "擗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 16 | nét | 擗 | tích | tượng hình | thuộc bộ 手, cấu trúc không rõ | 擗 thuộc bộ 手 (Thủ, tay). Cấu trúc nội bộ không được CHISE ghi nhận. Wiktionary chỉ ghi {{Han etym}} không có glyphOrigin. Bộ 手 gợi động tác tay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": bộ 手 (thủ, tay) — 擗 gợi hình ảnh hai tay đấm vào ngực trong cơn đau khổ cùng cực, như trong Kinh Thi. | Gương Hán-Việt | Chưa tìm thấy từ Hán-Việt thông dụng chứa 擗 trong tiếng Việt. | Mở khoá kiến thức | Biết 擗 giúp đọc thơ Kinh Thi và văn bản tang lễ cổ: 擗踴 (đấm ngực nhảy chân than khóc).", "Tự nguyên_Xie": "Chữ 擗 thuộc bộ 手 (tay), đọc pǐ. Nghĩa: đấm ngực than khóc (beat one''s breast in grief) — hành động thể hiện đau thương mãnh liệt trong thơ cổ. Wiktionary không có glyphOrigin chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bẻ ra; vỗ bụng", "Hạng Tần Suất (Jun Da)": "7683.0", "Tần Suất % (Jun Da)": "99.9988832273", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 辟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌辟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "擗", "Unihan_Traditional (Chữ Phồn thể)": "擗", "Pinyin_Xie": "pǐ", "Âm Hán Việt_Xie": "tịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động dùng tay bẻ đôi hoặc vỗ vào ngực khi đau buồn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哳', '{"9000": "7684.0", "Chữ Trung Quốc": "哳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 10 | nét | 哳 | chít | tượng hình | tiếng chim líu lo, âm thanh nhỏ nhặt | 哳 là tự dạng độc lập, dùng miêu tả âm thanh chim chóc líu lo (擬音字). Cấu trúc gốc hiện chưa rõ trong CHISE; chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chít\": bộ 口 (khẩu — miệng) gợi âm thanh phát ra; 哳 là tiếng chim chít chít líu lo. | Gương Hán-Việt | chít — dùng trong từ cổ chỉ âm thanh líu lo, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 哳 giúp nhận ra từ phức 嘲哳 (tiếng chim líu lo) trong thơ văn cổ Trung Hoa.", "Tự nguyên_Xie": "哳 (zhā) là chữ tượng thanh mô tả tiếng chim ríu rít, tương tự như trong 嘲哳 — từ phức chỉ tiếng líu lo. Wiktionary chưa có mô tả cấu trúc cụ thể. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: triêu triết 啁哳)", "Hạng Tần Suất (Jun Da)": "7684.0", "Tần Suất % (Jun Da)": "99.9988842609", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 折", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口折", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "折", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哳", "Unihan_Traditional (Chữ Phồn thể)": "哳", "Pinyin_Xie": "zhā", "Âm Hán Việt_Xie": "triết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Danh từ | 名词 | Thường dùng trong từ láy tượng thanh để mô tả âm thanh hỗn tạp của chim chóc. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('楗', '{"9000": "7685.0", "Chữ Trung Quốc": "楗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 木 | mộc | biểu nghĩa | gỗ | 建 | kiến | biểu âm | 楗 = 木 (Mộc, biểu nghĩa: gỗ) + 建 (Kiến, biểu âm); chữ hình thanh. 木 cho biết vật làm bằng gỗ, 建 cho âm đọc gần jiàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiện\": 木 (Mộc — gỗ) + 建 (Kiến — xây dựng) → thanh gỗ chặn cửa, then cài cửa bằng gỗ. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 楗 giúp hiểu từ cổ 關楗 (then cửa) trong văn chương cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 楗 (jiàn) là chữ hình thanh: 木 (gỗ) là phần biểu nghĩa, 建 là phần biểu âm. Chữ chỉ thanh ngang gỗ chặn cửa, cái then cửa. Có dạng tiểu triện và lục thư thông. Từ phức: 關楗 (then khóa cửa). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "then; cái đóng chốt cửa; vật liệu hàn khẩu (chỗ đê vỡ)", "Hạng Tần Suất (Jun Da)": "7685.0", "Tần Suất % (Jun Da)": "99.998886328", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 建", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木建", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "建", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "楗", "Unihan_Traditional (Chữ Phồn thể)": "楗", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "kiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ cái then chốt gỗ để khóa cửa hoặc cột gỗ ngăn nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韂', '{"9000": "7686.0", "Chữ Trung Quốc": "韂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 22 | nét | 韂 | tượng hình | tấm che bùn bên yên ngựa | 韂 có bộ 革 (cách — da thuộc), gợi vật dụng làm bằng da dùng cho ngựa. Cấu trúc chi tiết không có trong CHISE. Chưa có nguồn học thuật xác nhận chi tiết cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiêm\": bộ 革 (Cách — da thuộc) + ngữ nghĩa che chắn → tấm da che bùn treo bên yên ngựa. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 韂 giúp đọc hiểu từ 鞍韂 trong văn học và lịch sử kỵ binh cổ Trung Hoa.", "Tự nguyên_Xie": "韂 (chàn) thuộc bộ 革 (da thuộc), chỉ tấm che bùn bên yên ngựa — vật liệu da treo từ yên xuống để che bùn đất. Wiktionary ghi nghĩa \"saddle blanket that hangs down to block mud\". Từ phức: 鞍韂 (yên cương ngựa đầy đủ). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bộ yên ngựa (gồm yên và đệm)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 詹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革詹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "詹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "韂", "Unihan_Traditional (Chữ Phồn thể)": "韂", "Pinyin_Xie": "chàn", "Âm Hán Việt_Xie": "phiến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ tấm da hoặc đệm lót dưới yên ngựa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饏', '{"9000": "7687.0", "Chữ Trung Quốc": "饏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 20 | nét | 饏 | tượng hình | thức ăn thơm ngon | 饏 có bộ 食 (thực — thức ăn), gợi liên quan đến ẩm thực. Cấu trúc chi tiết không có trong CHISE. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạm\": bộ 食 (Thực — ăn uống) liên quan đến ẩm thực ngon; 饏 chỉ vị ngon, thơm. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | 饏 thuộc bộ 食 — nhóm chữ liên quan ẩm thực như 飯, 飲, 館.", "Tự nguyên_Xie": "饏 (dàn) thuộc bộ 食 (thức ăn), mang nghĩa thơm ngon, có hương vị. Wiktionary không có mục từ này; không có phân tích cấu trúc. Chữ cực hiếm, chưa thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thơm ngon", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "敢 + 食", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敢食", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "食", "Unihan_Simplified (Chữ Giản thể)": "饏", "Unihan_Traditional (Chữ Phồn thể)": "饏", "Pinyin_Xie": "dàn", "Âm Hán Việt_Xie": "đạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Dùng làm tính từ để mô tả hương vị thức ăn thơm ngon hoặc cảm giác no nê. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耥', '{"9000": "7688.0", "Chữ Trung Quốc": "耥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耒 | Số nét | 14 | nét | 耥 | tượng hình | nông cụ bừa ruộng | 耥 có bộ 耒 (lỗi — cán cày), gợi dụng cụ nông nghiệp. Cấu trúc chi tiết không có trong CHISE. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tang\": bộ 耒 (Lỗi — cán cày) kết hợp âm tāng → dụng cụ bừa đất trong nông nghiệp truyền thống. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | 耥 thuộc bộ 耒 — nhóm nông cụ như 耕 (cày), 耙 (bừa), 耘 (làm cỏ).", "Tự nguyên_Xie": "耥 (tāng) thuộc bộ 耒 (cán cày), chỉ công cụ nông nghiệp dùng để bừa ruộng, làm mềm đất sau khi cày. Wiktionary không có mục từ này. Chữ cực hiếm, chưa thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bừa ruộng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "耒 + 尚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耒尚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耒", "Unihan_Simplified (Chữ Giản thể)": "耥", "Unihan_Traditional (Chữ Phồn thể)": "耥", "Pinyin_Xie": "tāng", "Âm Hán Việt_Xie": "thảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ nông cụ bừa ruộng hoặc động từ chỉ hoạt động bừa đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髼', '{"9000": "7689.0", "Chữ Trung Quốc": "髼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 17 | nét | 髼 | tượng hình | tóc rối bù, xõa | 髼 có bộ 髟 (tiêu — tóc dài), gợi liên quan đến tóc tai. Cấu trúc chi tiết không có trong CHISE. Chủ yếu dùng trong từ phức 髼鬆 và 髼鬙. Chưa có nguồn học thuật xác nhận chi tiết cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bồng\": bộ 髟 (Tiêu — tóc) + âm péng → tóc bồng xõa bù xù như bụi cây um tùm. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; liên tưởng \"bồng\" trong \"tóc bồng\" | Mở khoá kiến thức | Biết 髼 giúp đọc từ 髼鬆 (tóc bồng bềnh) trong văn học miêu tả ngoại hình.", "Tự nguyên_Xie": "髼 (péng) thuộc bộ 髟 (tóc dài), chỉ tóc rối xõa. Wiktionary ghi dùng trong 髼鬆 (tóc bồng bềnh) và 髼鬙 (tóc rối). Chữ chỉ dùng trong từ phức, ít đứng độc lập. Chưa có nguồn học thuật xác nhận. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tóc rối", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 夆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟夆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "髼", "Unihan_Traditional (Chữ Phồn thể)": "髼", "Pinyin_Xie": "péng", "Âm Hán Việt_Xie": "bồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ miêu tả trạng thái tóc tai bù xù, không chải chuốt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篼', '{"9000": "7690.0", "Chữ Trung Quốc": "篼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 17 | nét | 篼 | tượng hình | giỏ tre, xe cáng bằng tre | 篼 có bộ 竹 (trúc — tre), gợi vật dụng làm bằng tre. Cấu trúc chi tiết không có trong CHISE. Chữ cực hiếm, có dạng tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đậu\": bộ 竹 (Trúc — tre) + âm dōu → vật đan bằng tre, như giỏ hoặc xe cáng miền núi. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | 篼 thuộc bộ 竹 — nhóm vật dụng tre như 篮 (giỏ), 箱 (hộp), 筐 (sọt).", "Tự nguyên_Xie": "Tiểu triện | 篼 (dōu) thuộc bộ 竹 (tre), chỉ giỏ đan bằng tre hoặc chiếc xe cáng bằng tre dùng ở vùng núi (mountain sedan chair). Wiktionary không có mục từ này. Có dạng tiểu triện. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái gùi; xe bằng tre", "Hạng Tần Suất (Jun Da)": "7690.0", "Tần Suất % (Jun Da)": "99.9988925295", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 兜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮兜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篼", "Unihan_Traditional (Chữ Phồn thể)": "篼", "Pinyin_Xie": "dōu", "Âm Hán Việt_Xie": "đâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ các loại giỏ đeo vai bằng tre hoặc kiệu tre đơn sơ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬑', '{"9000": "7691.0", "Chữ Trung Quốc": "鬑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 20 | nét | 鬑 | tượng hình | tóc mai dài rủ, tóc suôn | 鬑 có bộ 髟 (tiêu — tóc dài), gợi liên quan đến mái tóc. Cấu trúc chi tiết không có trong CHISE. Chủ yếu dùng trong 鬑鬑 (tóc mai dài mượt). Có dạng tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêm\": bộ 髟 (Tiêu — tóc) + âm lián → tóc mai dài mượt rủ xuống như dải lụa. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; âm lián gợi liên tưởng \"liên\" (dài liên tiếp) | Mở khoá kiến thức | Biết 鬑 giúp nhận dạng từ 鬑鬑 trong thơ miêu tả dung nhan.", "Tự nguyên_Xie": "Tiểu triện | 鬑 (lián) thuộc bộ 髟 (tóc dài), chỉ mái tóc dài mượt rủ xuống. Wiktionary ghi \"long, flowing hair\"; dùng trong từ phức 鬑鬑 (tóc mai dài). Có dạng tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tóc mai rủ xuống", "Hạng Tần Suất (Jun Da)": "7691.0", "Tần Suất % (Jun Da)": "99.998893563", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 兼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟兼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "鬑", "Unihan_Traditional (Chữ Phồn thể)": "鬑", "Pinyin_Xie": "lián", "Âm Hán Việt_Xie": "liêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Dùng làm tính từ miêu tả vẻ đẹp của tóc mai dài rủ xuống hoặc tóc thưa thớt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醑', '{"9000": "7692.0", "Chữ Trung Quốc": "醑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 16 | nét | 醑 | tượng hình | rượu ngon lọc qua, tinh chất rượu | 醑 có bộ 酉 (dậu — bình rượu), gợi liên quan đến rượu và ẩm thực. Cấu trúc chi tiết không có trong CHISE. Chữ chỉ rượu ngon được lọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hử\": bộ 酉 (Dậu — bình rượu) + âm xǔ → rượu trong bình được lọc qua, tinh khiết, thơm ngon. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; bộ 酉 liên hệ \"dậu\" (giờ dậu), giờ uống rượu | Mở khoá kiến thức | Biết 醑 giúp hiểu thuật ngữ dược học 醑劑 (tincture — thuốc pha rượu).", "Tự nguyên_Xie": "醑 (xǔ) thuộc bộ 酉 (bình rượu), chỉ quá trình lọc rượu và sản phẩm thu được — rượu tinh lọc, rượu ngon. Wiktionary có pronunciation nhưng không có phân tích cấu trúc rõ ràng. Từ phức: 醑劑 (thuốc pha rượu, tincture trong dược học). Chưa có nguồn học thuật xác nhận. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rượu ngon", "Hạng Tần Suất (Jun Da)": "7692.0", "Tần Suất % (Jun Da)": "99.9988945966", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 胥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉胥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醑", "Unihan_Traditional (Chữ Phồn thể)": "醑", "Pinyin_Xie": "xǔ", "Âm Hán Việt_Xie": "tữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ rượu ngon đã được lọc kỹ hoặc động từ lọc rượu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴧', '{"9000": "7693.0", "Chữ Trung Quốc": "鴧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 16 | nét | 鴧 | tượng hình | tên một loài chim cổ | 鴧 có bộ 鳥 (điểu — chim), gợi đây là tên một loài chim. Cấu trúc chi tiết không có trong CHISE. Wiktionary không có mục từ. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhung\": bộ 鳥 (Điểu — chim) xác định đây là tên một loài chim cổ không rõ danh tính trong sách vở hiện đại. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | 鴧 thuộc bộ 鳥 — nhóm chim như 鸡 (gà), 鹏 (đại bàng thần thoại), 鹰 (chim ưng).", "Tự nguyên_Xie": "鴧 (ròng) thuộc bộ 鳥 (chim), chỉ một loài chim không rõ danh tính trong phân loại hiện đại. Wiktionary không có mục từ này; không có phân tích cấu trúc. Chữ cực hiếm. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "駧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "宂 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰宂鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鴧", "Unihan_Traditional (Chữ Phồn thể)": "鴧", "Pinyin_Xie": "ròng", "Âm Hán Việt_Xie": "nhung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loài chim nhỏ bay rất nhanh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眜', '{"9000": "7694.0", "Chữ Trung Quốc": "眜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 10 | nét | 眜 | mắt | tượng hình | mắt, tai mắt | 眜 có bộ 目 (mục — mắt), gợi liên quan đến mắt và thị giác. Cấu trúc chi tiết không có trong CHISE. Chữ dùng trong ngữ nghĩa \"tai mắt\" (gián điệp, người do thám). Chưa có nguồn học thuật xác nhận chi tiết cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mắt\": bộ 目 (Mục — mắt) trực tiếp gợi đây là chữ chỉ mắt; 眜 dùng theo nghĩa ẩn dụ \"tai mắt\" (người do thám). | Gương Hán-Việt | mắt — tiếng Việt vay mượn trực tiếp, như \"tai mắt\" (người theo dõi) | Mở khoá kiến thức | Biết 眜 (mắt) giúp nhận ra bộ 目 và liên hệ với \"mục\" trong \"mục tiêu\", \"mục đích\".", "Tự nguyên_Xie": "眜 (mò) thuộc bộ 目 (mắt), mang nghĩa liên quan đến mắt, đôi khi được dùng theo nghĩa ẩn dụ \"tai mắt\" trong tiếng Việt Hán. Wiktionary chỉ có phiên âm, không có phân tích cấu trúc. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mắt; như \"con mắt; tai mắt\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 末", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目末", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "末", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眜", "Unihan_Traditional (Chữ Phồn thể)": "眜", "Pinyin_Xie": "mò", "Âm Hán Việt_Xie": "mạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Dùng làm tính từ chỉ trạng thái mắt mờ tối hoặc danh từ chỉ con mắt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞷', '{"9000": "7695.0", "Chữ Trung Quốc": "瞷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 17 | nét | 瞷 | tượng hình | nhìn trộm, nhìn lén | 瞷 có bộ 目 (mục — mắt), gợi hành động dùng mắt lén nhìn. Cấu trúc chi tiết không có trong CHISE. Chữ cực hiếm. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giản\": bộ 目 (Mục — mắt) + âm jiàn → dùng mắt lén nhìn, thăm dò lén lút từ xa. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng | Mở khoá kiến thức | 瞷 thuộc bộ 目 — nhóm hành động nhìn như 看 (nhìn), 瞧 (ngó), 窥 (nhìn trộm).", "Tự nguyên_Xie": "瞷 (jiàn) thuộc bộ 目 (mắt), chỉ hành động nhìn lén, nhìn trộm để thăm dò. Wiktionary không có mục từ này. Chữ cực hiếm, chưa thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhìn trộm; thăm dò; nhìn lén", "Hạng Tần Suất (Jun Da)": "7695.0", "Tần Suất % (Jun Da)": "99.9988976973", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 間", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目間", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "間", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞷", "Unihan_Traditional (Chữ Phồn thể)": "瞷", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "gián", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành vi nhìn lén hoặc theo dõi ngầm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磦', '{"9000": "7696.0", "Chữ Trung Quốc": "磦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 16 | nét | 磦 | tượng hình | loại đá, nghĩa chưa rõ | 磦 có bộ 石 (thạch — đá), gợi liên quan đến khoáng thạch. Cấu trúc chi tiết không có trong CHISE. Nghĩa chưa được ghi chép rõ ràng. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": bộ 石 (Thạch — đá) + âm biāo → loại đá hoặc khoáng vật, nghĩa cụ thể thất truyền. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | 磦 thuộc bộ 石 — nhóm khoáng thạch như 碳 (than đá), 砂 (cát), 礁 (đá ngầm).", "Tự nguyên_Xie": "磦 (biāo) thuộc bộ 石 (đá), chỉ một loại đá hoặc khoáng vật không rõ tên. Wiktionary không có mục từ này. Chữ cực hiếm, chưa thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "磦", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 票", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石票", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "票", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磦", "Unihan_Traditional (Chữ Phồn thể)": "磦", "Pinyin_Xie": "biāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại đá có màu sắc đặc trưng hoặc âm thanh của đá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礨', '{"9000": "7697.0", "Chữ Trung Quốc": "礨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 20 | nét | 礨 | tượng hình | tảng đá lớn, đống đá | 礨 có bộ 石 (thạch — đá), gợi liên quan đến khoáng thạch lớn. Cấu trúc chi tiết không có trong CHISE. Chữ cực hiếm. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lỗi\": bộ 石 (Thạch — đá) + âm lěi gợi liên tưởng 磊 (đá chồng chất) → tảng đá lớn hoặc đống đá xếp chồng. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | 礨 thuộc bộ 石, liên hệ với 磊 (lỗi — đá chồng, phẩm hạnh thẳng thắn) qua cùng âm lěi.", "Tự nguyên_Xie": "礨 (lěi) thuộc bộ 石 (đá), chỉ tảng đá lớn hoặc đống đá chồng. Wiktionary không có mục từ này. Chữ cực hiếm, chưa thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "礨", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "畾 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱畾石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礨", "Unihan_Traditional (Chữ Phồn thể)": "礨", "Pinyin_Xie": "lěi", "Âm Hán Việt_Xie": "lỗi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ chỉ đá lớn hoặc tính từ mô tả địa hình gồ ghề. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祃', '{"9000": "7698.0", "Chữ Trung Quốc": "祃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 7 | nét | 衣 | y | biểu nghĩa | áo, quần áo | 馬 | mã | biểu âm | 祃 = 衣 (Y, biểu nghĩa) + 馬 (Mã, biểu âm); chữ hình thanh. Wiktionary dùng dạng 禡 (với bộ 示 rõ hơn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mã\": 馬 (Mã — ngựa, biểu âm) + bộ lễ → lễ tế thổ thần khi quân đội ra trận trên lưng ngựa. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; bộ 示 liên hệ với \"thần\" trong \"thần linh\" | Mở khoá kiến thức | Biết 祃 giúp hiểu nghi lễ 禡牙 (lễ tế cầu thắng trận) trong sử sách Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 祃 (mà) là dạng biến thể của 禡, chữ hình thanh: 衣 (áo) là phần ngữ nghĩa gốc, 馬 (Mã) là biểu âm. Chỉ lễ tế thổ thần trước khi xuất quân, hoặc lễ tế định kỳ vào ngày mùng 2 và 16 âm lịch. Từ phức: 禡牙 (lễ tế trước khi ra trận). Có dạng tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lễ tế thổ thần", "Hạng Tần Suất (Jun Da)": "7698.0", "Tần Suất % (Jun Da)": "99.998900798", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 马", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻马", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "马", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祃", "Unihan_Traditional (Chữ Phồn thể)": "禡", "Pinyin_Xie": "mà", "Âm Hán Việt_Xie": "mạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ nghi lễ tế thần hoặc động từ thực hiện nghi lễ này trước khi xuất quân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祲', '{"9000": "7699.0", "Chữ Trung Quốc": "祲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 11 | nét | 祲 | tượng hình | khí xấu, điềm gở, khí độc | 祲 có bộ 示 (thị — thần linh, nghi lễ), gợi liên quan đến điềm báo và tâm linh. Cấu trúc chi tiết không có trong CHISE. Chữ chỉ khí độc, điềm gở, sinh khí âm u. Có dạng tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tẩm\": bộ 示 (Thị — thần linh) + âm jìn → khí xấu ngấm vào không gian, điềm gở từ thần linh. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 祲 giúp đọc cổ văn miêu tả điềm báo chiến tranh, dịch bệnh và thảm họa tự nhiên.", "Tự nguyên_Xie": "Tiểu triện | 祲 (jìn) thuộc bộ 示 (thần linh/lễ nghi), chỉ khí xấu, điềm gở hoặc sinh khí âm u báo điềm xấu. Wiktionary không có mục từ này. Có dạng tiểu triện. Chữ dùng trong văn học cổ miêu tả điềm báo và khí trời. Chưa có nguồn học thuật xác nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khí độc", "Hạng Tần Suất (Jun Da)": "7699.0", "Tần Suất % (Jun Da)": "99.9989018316", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "祲", "Unihan_Traditional (Chữ Phồn thể)": "祲", "Pinyin_Xie": "jìn", "Âm Hán Việt_Xie": "tẩm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ thời tiết hoặc điềm báo để chỉ luồng khí xấu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祻', '{"9000": "7700.0", "Chữ Trung Quốc": "祻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 12 | nét | 祻 | tượng hình | liên quan tế lễ, nghĩa chưa rõ | 祻 có bộ 示 (thị — thần linh, lễ), gợi liên quan đến nghi lễ hoặc tâm linh. Cấu trúc chi tiết không có trong CHISE. Chữ cực hiếm. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cố\": bộ 示 (Thị — lễ nghi) + âm gù → liên quan đến lễ cổ, nghĩa chi tiết đã thất truyền. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | 祻 thuộc bộ 示 — nhóm lễ thần như 神 (thần), 福 (phúc), 祖 (tổ tiên).", "Tự nguyên_Xie": "祻 (gù) thuộc bộ 示 (lễ/thần), có lẽ liên quan đến nghi lễ cổ xưa. Wiktionary không có mục từ này. Chữ cực hiếm, chưa thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tùy", "Hạng Tần Suất (Jun Da)": "7700.0", "Tần Suất % (Jun Da)": "99.9989028652", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 固", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻固", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "固", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祻", "Unihan_Traditional (Chữ Phồn thể)": "祻", "Pinyin_Xie": "gù", "Âm Hán Việt_Xie": "cố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ phúc lành hoặc động từ trong các nghi thức cúng tế cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窊', '{"9000": "7701.0", "Chữ Trung Quốc": "窊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 10 | nét | 窊 | tượng hình | chỗ trũng, hố đất, vùng đất thấp | 窊 có bộ 穴 (huyệt — hang hố), gợi chỗ trũng, lõm xuống. Cấu trúc chi tiết không có trong CHISE. Có dạng tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oa\": bộ 穴 (Huyệt — hang, hố) + âm wā → chỗ trũng lõm xuống như cái hố. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 窊 giúp đọc từ phức 窊凸 (lồi lõm không bằng phẳng) trong văn mô tả địa hình.", "Tự nguyên_Xie": "Tiểu triện | 窊 (wā) thuộc bộ 穴 (hang hố), chỉ chỗ trũng, hố đất hoặc vùng đất thấp. Wiktionary ghi các nghĩa: pit (hố), vault (vòm), to store in a pit, lowland swamp, và theo tiếng Quảng Đông là cánh tay. Từ phức: 窊凸 (lồi lõm). Có dạng tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỗ trũng", "Hạng Tần Suất (Jun Da)": "7701.0", "Tần Suất % (Jun Da)": "99.9989038987", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 瓜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴瓜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瓜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窊", "Unihan_Traditional (Chữ Phồn thể)": "窊", "Pinyin_Xie": "wā", "Âm Hán Việt_Xie": "oa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ miêu tả địa hình hoặc danh từ chỉ vùng đất trũng thấp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簥', '{"9000": "7702.0", "Chữ Trung Quốc": "簥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 18 | nét | 簥 | tượng hình | ống tre lớn, nhạc cụ ống tre cổ đại | 簥 có bộ 竹 (trúc — tre), gợi nhạc cụ hoặc ống bằng tre. Cấu trúc chi tiết không có trong CHISE. Wiktionary ghi \"loại ống nhạc đã lỗi thời\".", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiêu\": bộ 竹 (Trúc — tre) + âm jiāo → ống tre lớn dùng làm nhạc cụ, như sáo trúc cỡ lớn. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 簥 giúp nhận ra nhạc cụ cổ trong tranh vẽ và ghi chép nhạc lý Trung Hoa.", "Tự nguyên_Xie": "簥 (jiāo) thuộc bộ 竹 (tre), chỉ một loại nhạc cụ ống tre lớn đã lỗi thời trong văn nhạc cổ Trung Hoa. Wiktionary ghi là \"obsolete musical pipe instrument\". Chữ cực hiếm trong văn bản hiện đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ống lớn", "Hạng Tần Suất (Jun Da)": "7702.0", "Tần Suất % (Jun Da)": "99.9989049323", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 喬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮喬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簥", "Unihan_Traditional (Chữ Phồn thể)": "簥", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "kiểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại nhạc cụ thổi bằng tre thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('縢', '{"9000": "7703.0", "Chữ Trung Quốc": "縢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 16 | nét | 縢 | tượng hình | dây buộc, xà cạp, dây bó | 縢 có bộ 糸 (mịch — sợi tơ/dây), gợi vật dụng bằng dây sợi. Cấu trúc chi tiết không có trong CHISE. Wiktionary ghi có dạng kim văn và tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đằng\": bộ 糸 (Mịch — dây sợi) + âm téng → dây buộc chặt, quấn quanh như dây leo 藤 (đằng). | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; âm téng liên hệ \"đằng\" trong dây leo | Mở khoá kiến thức | Biết 縢 giúp hiểu từ 金縢 (hộp vàng niêm phong) trong Kinh Thư và văn học Chu.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 縢 (téng) thuộc bộ 糸 (sợi tơ), chỉ dây buộc, dây bó; cụ thể là xà cạp quấn quanh chân khi đi dài. Wiktionary ghi các nghĩa: to tie up/bind/seal, cord/rope, leg wrapping. Từ phức: 行縢 (xà cạp đi đường), 金縢 (hộp vàng có dây niêm phong). Có dạng kim văn, tiểu triện, lục thư thông. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ghim lại, bó buộc, quấn xà cạp", "Hạng Tần Suất (Jun Da)": "7703.0", "Tần Suất % (Jun Da)": "99.9989069994", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 絭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月絭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "絭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "縢", "Unihan_Traditional (Chữ Phồn thể)": "縢", "Pinyin_Xie": "téng", "Âm Hán Việt_Xie": "đằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ hành động trói buộc hoặc danh từ chỉ dây thừng, xà cạp. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繌', '{"9000": "7704.0", "Chữ Trung Quốc": "繌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 17 | nét | 繌 | tượng hình | loại sợi hoặc vải, nghĩa chưa rõ | 繌 có bộ 糸 (mịch — sợi tơ), gợi liên quan đến vải sợi. Cấu trúc chi tiết không có trong CHISE. Chữ cực hiếm, không có mục từ trong Wiktionary. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sa\": bộ 糸 (Mịch — sợi tơ) + âm sha → loại vải hoặc sợi, nghĩa cụ thể chưa được ghi chép rõ. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng | Mở khoá kiến thức | 繌 thuộc bộ 糸 — nhóm chữ vải sợi như 绸 (sa tơ), 丝 (sợi), 织 (dệt).", "Tự nguyên_Xie": "繌 (sha) thuộc bộ 糸 (sợi tơ), có lẽ chỉ một loại vải hoặc sợi dệt. Wiktionary không có mục từ này. Chữ cực hiếm, chưa thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "猌", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "繌", "Unihan_Traditional (Chữ Phồn thể)": "繌", "Pinyin_Xie": "sha", "Âm Hán Việt_Xie": "sa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ các loại dây trang trí hoặc dây buộc trên mũ áo cổ trang. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聜', '{"9000": "7705.0", "Chữ Trung Quốc": "聜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 14 | nét | 聜 | tượng hình | nghĩa chưa rõ, liên quan tai/nghe | 聜 có bộ 耳 (nhĩ — tai), gợi liên quan đến thính giác. Cấu trúc chi tiết không có trong CHISE. Chữ cực hiếm, không có mục từ trong Wiktionary. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đê\": bộ 耳 (Nhĩ — tai) + âm dǐ → liên quan đến tai và thính giác; nghĩa cụ thể chưa rõ. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng | Mở khoá kiến thức | 聜 thuộc bộ 耳 — nhóm thính giác như 聪 (thông minh/thính), 聊 (tán gẫu), 聚 (tụ tập).", "Tự nguyên_Xie": "聜 (dǐ) thuộc bộ 耳 (tai), có lẽ liên quan đến hành động nghe hoặc thuộc tính của tai. Wiktionary không có mục từ này. Chữ cực hiếm, chưa thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "聜", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 空", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳空", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "空", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聜", "Unihan_Traditional (Chữ Phồn thể)": "聜", "Pinyin_Xie": "dǐ", "Âm Hán Việt_Xie": "đê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ chỉ trạng thái nghe hiểu rõ ràng hoặc động từ lắng nghe. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胔', '{"9000": "7706.0", "Chữ Trung Quốc": "胔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 胔 | tượng hình | thịt thối, xác chết phân hủy | 胔 có bộ 肉 (nhục — thịt), gợi liên quan đến thi thể. Cấu trúc chi tiết không có trong CHISE. Wiktionary ghi \"remains, rotting corpse\". Có dạng đại triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tí\": bộ 肉 (Nhục — thịt) + âm zì → thịt thối rữa, tử thi phân hủy. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; bộ 肉 liên hệ \"nhục\" trong \"nhục thể\" | Mở khoá kiến thức | Biết 胔 giúp đọc thành ngữ 掩骼埋胔 trong văn bản lịch sử về đạo từ thiện chôn cất.", "Tự nguyên_Xie": "Đại triện | 胔 (zì) thuộc bộ 肉 (thịt), chỉ thi thể phân hủy, xác chết bốc mùi. Wiktionary ghi nghĩa \"remains; rotting corpse\". Từ phức: 掩骼埋胔 (chôn cất hài cốt xương thịt thối). Có dạng đại triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thịt ôi; thịt thiu; thịt thối", "Hạng Tần Suất (Jun Da)": "7706.0", "Tần Suất % (Jun Da)": "99.9989111337", "GavinGrover_Once (Chiết tự trực tiếp)": "此 + 肉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱此肉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "此", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "肉", "Unihan_Simplified (Chữ Giản thể)": "胔", "Unihan_Traditional (Chữ Phồn thể)": "胔", "Pinyin_Xie": "zì", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn cổ để chỉ xác động vật hoặc người đang phân hủy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胾', '{"9000": "7707.0", "Chữ Trung Quốc": "胾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 肉 | nhục | biểu nghĩa | thịt | 胾 = 肉 (Nhục, biểu nghĩa: thịt) + 𢦏 (biểu âm, ký tự ngoài Unicode thông thường); chữ hình thanh. Bộ 肉 cho biết liên quan đến thịt, phần còn lại cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tế\": 肉 (Nhục — thịt) + phần biểu âm → miếng thịt to thái sẵn, khác 胔 là thịt thối. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; bộ 肉 liên hệ \"nhục\" trong từ Hán-Việt | Mở khoá kiến thức | Biết 胾 giúp phân biệt từ điển cổ: 胾 (thịt tươi cắt miếng) vs 胔 (thịt thối).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | 胾 (zì) là chữ hình thanh: 肉 (thịt) là phần biểu nghĩa, 𢦏 là phần biểu âm. Chữ chỉ miếng thịt đã cắt, thịt to thái miếng. Có dạng giáp cốt văn, kim văn và tiểu triện — là chữ rất cổ. Phân biệt với 胔 (thịt thối). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tảng thịt; miếng thịt (to)", "Hạng Tần Suất (Jun Da)": "7707.0", "Tần Suất % (Jun Da)": "99.9989121673", "GavinGrover_Once (Chiết tự trực tiếp)": "𢦏 + 肉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𢦏肉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𢦏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "肉", "Unihan_Simplified (Chữ Giản thể)": "胾", "Unihan_Traditional (Chữ Phồn thể)": "胾", "Pinyin_Xie": "zì", "Âm Hán Việt_Xie": "chí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ miếng thịt cắt to, thường dùng trong văn ngôn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脨', '{"9000": "7708.0", "Chữ Trung Quốc": "脨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 脨 | tượng hình | nghĩa chưa rõ, liên quan thịt/cơ thể | 脨 có bộ 肉 (nhục — thịt), gợi liên quan đến cơ thể. Cấu trúc chi tiết không có trong CHISE. Chữ cực hiếm, không có mục từ trong Wiktionary. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thốt\": bộ 肉 (Nhục — thịt, cơ thể) + âm cù → bộ phận cơ thể hoặc trạng thái cơ bắp, nghĩa cụ thể chưa rõ. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng | Mở khoá kiến thức | 脨 thuộc bộ 肉 — nhóm cơ thể như 脑 (não), 胸 (ngực), 腹 (bụng).", "Tự nguyên_Xie": "脨 (cù) thuộc bộ 肉 (thịt), chỉ một bộ phận hoặc trạng thái của cơ thể. Wiktionary không có mục từ này. Chữ cực hiếm, chưa thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "訨", "Hạng Tần Suất (Jun Da)": "7708.0", "Tần Suất % (Jun Da)": "99.9989132009", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 束", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月束", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "束", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脨", "Unihan_Traditional (Chữ Phồn thể)": "脨", "Pinyin_Xie": "cù", "Âm Hán Việt_Xie": "thốt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận chân, rất hiếm dùng trong tiếng Trung hiện đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膼', '{"9000": "7709.0", "Chữ Trung Quốc": "膼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 15 | nét | 膼 | tượng hình | chân, đá chân (phương ngữ Tứ Xuyên) | 膼 có bộ 肉 (nhục — thịt/cơ thể), gợi liên quan đến bộ phận cơ thể. Cấu trúc chi tiết không có trong CHISE. Wiktionary ghi nghĩa: leg (chân), swell (sưng), và theo tiếng Tứ Xuyên là \"đá chân\".", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"troa\": bộ 肉 (Nhục — thịt/cơ thể) + âm zhuā → bộ phận chân, theo phương ngữ Tứ Xuyên còn có nghĩa là đá chân. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | 膼 thuộc bộ 肉 — nhóm chân tay như 腿 (đùi chân), 脚 (bàn chân), 腕 (cổ tay).", "Tự nguyên_Xie": "膼 (zhuā) thuộc bộ 肉 (cơ thể), chỉ cái chân; theo phương ngữ Tứ Xuyên còn có nghĩa là \"đá\" (kick). Wiktionary ghi phương ngữ Tứ Xuyên: 踢 (kick). Chưa có nguồn học thuật xác nhận. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tây An", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 過", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月過", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "過", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膼", "Unihan_Traditional (Chữ Phồn thể)": "膼", "Pinyin_Xie": "zhuā", "Âm Hán Việt_Xie": "troa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần đùi của động vật hoặc dùng trong phương ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艕', '{"9000": "7710.0", "Chữ Trung Quốc": "艕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 16 | nét | 艕 | tượng hình | hai thuyền áp sát nhau | 艕 có bộ 舟 (chu — thuyền), gợi liên quan đến thuyền bè. Cấu trúc chi tiết không có trong CHISE. Chữ chỉ trạng thái hai thuyền buộc cạnh nhau. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạng\": bộ 舟 (Chu — thuyền) + âm bàng gợi \"bên cạnh\" (傍) → hai thuyền áp sát mạn nhau. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng | Mở khoá kiến thức | 艕 thuộc bộ 舟 — nhóm thuyền bè như 船 (thuyền), 舰 (tàu chiến), 艇 (xuồng).", "Tự nguyên_Xie": "艕 (bàng) thuộc bộ 舟 (thuyền), chỉ hai chiếc thuyền buộc áp sát cạnh nhau (boats fastened side by side). Wiktionary không có mục từ này. Chữ cực hiếm. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áp mạn (thuyền). 船和船相靠.", "Hạng Tần Suất (Jun Da)": "7710.0", "Tần Suất % (Jun Da)": "99.998915268", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 旁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟旁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艕", "Unihan_Traditional (Chữ Phồn thể)": "艕", "Pinyin_Xie": "bàng", "Âm Hán Việt_Xie": "bạng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc hai thuyền áp sát vào nhau hoặc làm danh từ chỉ mạn thuyền. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苼', '{"9000": "7711.0", "Chữ Trung Quốc": "苼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 苼 | tượng hình | tên thực vật, nghĩa chưa rõ | 苼 có bộ 艸 (thảo — cỏ cây), gợi liên quan đến thực vật. Cấu trúc chi tiết không có trong CHISE. Chữ cực hiếm, không có mục từ trong Wiktionary. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sinh\": bộ 艸 (Thảo — cỏ cây) + âm shēng → tên một loại cây cỏ mọc hoang, nghĩa cụ thể chưa rõ. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; âm shēng gợi \"sinh trưởng\" | Mở khoá kiến thức | 苼 thuộc bộ 艸 — nhóm thực vật như 草 (cỏ), 花 (hoa), 苔 (rêu).", "Tự nguyên_Xie": "苼 (shēng) thuộc bộ 艸 (cỏ cây), có lẽ là tên một loại cây hoặc cỏ cổ đại. Wiktionary không có mục từ này. Chữ cực hiếm, chưa thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "苼", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 生", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹生", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "生", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苼", "Unihan_Traditional (Chữ Phồn thể)": "苼", "Pinyin_Xie": "shēng", "Âm Hán Việt_Xie": "sinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cỏ tế, thường xuất hiện trong tên riêng hoặc thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莻', '{"9000": "7712.0", "Chữ Trung Quốc": "莻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 匕 | Số nét | 13 | nét | 莻 | tượng hình | muộn, cổ (late); nghĩa chưa rõ | 莻 có bộ 匕 (thị — con dao nhỏ). Cấu trúc chi tiết không có trong CHISE. Chữ cực hiếm, không có mục từ trong Wiktionary. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cống\": bộ 匕 (Thị — dao nhỏ) + âm gòng → chữ cổ hiếm, nghĩa \"muộn màng\", thất truyền. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng | Mở khoá kiến thức | 莻 hiếm gặp; bộ 匕 liên hệ với 化 (biến đổi), 北 (bắc).", "Tự nguyên_Xie": "莻 (gòng) thuộc bộ 匕, mang nghĩa \"late\" (muộn) theo nguồn dữ liệu. Wiktionary không có mục từ này. Chữ cực hiếm, chưa thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "莻", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "莻", "Unihan_Traditional (Chữ Phồn thể)": "莻", "Pinyin_Xie": "gòng", "Âm Hán Việt_Xie": "cống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cỏ cổ, hầu như không dùng trong văn bản hiện đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓨', '{"9000": "7713.0", "Chữ Trung Quốc": "蓨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蓨 | tượng hình | giỏ tre; tên đất cổ (nay thuộc Hà Bắc) | 蓨 có bộ 艸 (thảo — cỏ cây), gợi liên quan đến thực vật. Cấu trúc chi tiết không có trong CHISE. Wiktionary ghi là dạng cũ của 蓧 và tên huyện cổ thuộc Hà Bắc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điều\": bộ 艸 (Thảo — cây cỏ) + âm tiáo → giỏ tre hoặc địa danh cổ Hà Bắc. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; âm tiáo liên hệ 条 (nhánh cây dài) | Mở khoá kiến thức | Biết 蓨 giúp nhận ra địa danh cổ tỉnh Hà Bắc trong sử sách Trung Hoa.", "Tự nguyên_Xie": "蓨 (tiáo) thuộc bộ 艸 (cỏ cây), là dạng chữ cũ của 蓧 (giỏ tre). Wiktionary ghi hai nghĩa: (1) dạng thay thế của 蓧, (2) tên huyện cổ thuộc Hà Bắc. Chữ cực hiếm trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái giỏ tre; tên đất thời cổ (nay thuộc tỉnh Hà Bắc của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 脩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹脩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "脩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓨", "Unihan_Traditional (Chữ Phồn thể)": "蓨", "Pinyin_Xie": "tiáo", "Âm Hán Việt_Xie": "điều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cái giỏ tre hoặc dùng làm địa danh cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓵', '{"9000": "7714.0", "Chữ Trung Quốc": "蓵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 蓵 | tượng hình | rèm cỏ, màn cỏ | 蓵 có bộ 艸 (thảo — cỏ cây), gợi liên quan đến thực vật. Wiktionary ghi nghĩa \"grass curtain\" (rèm cỏ). Chưa có nguồn học thuật xác nhận chi tiết cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiệt\": bộ 艸 (Thảo — cỏ cây) → rèm đan bằng cỏ che cửa, đơn giản và tự nhiên. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng | Mở khoá kiến thức | 蓵 thuộc bộ 艸 — nhóm vật dụng thực vật như 席 (chiếu cỏ), 簾 (rèm tre).", "Tự nguyên_Xie": "蓵 (jié) thuộc bộ 艸 (cỏ cây), chỉ rèm làm bằng cỏ hoặc lá cây. Wiktionary ghi \"obs-std grass curtain\". Chữ cực hiếm, không dùng trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蓵", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 捷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹捷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "捷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓵", "Unihan_Traditional (Chữ Phồn thể)": "蓵", "Pinyin_Xie": "jié", "Âm Hán Việt_Xie": "tiệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cỏ dại, chủ yếu xuất hiện trong từ điển cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓾', '{"9000": "7715.0", "Chữ Trung Quốc": "蓾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 蓾 | tượng hình | tên một loại cỏ | 蓾 có bộ 艸 (thảo — cỏ cây), gợi liên quan đến thực vật. Wiktionary ghi \"a kind of grass\". Chưa có nguồn học thuật xác nhận chi tiết cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lỗ\": bộ 艸 (Thảo — cỏ cây) + âm lǔ → tên một loại cỏ cổ đại, nay thất truyền trong danh pháp thực vật học. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; âm lǔ gợi 鲁 (tên nước Lỗ) | Mở khoá kiến thức | 蓾 thuộc bộ 艸 — nhóm tên cỏ hiếm trong thực vật học cổ đại Trung Hoa.", "Tự nguyên_Xie": "蓾 (lǔ) thuộc bộ 艸 (cỏ cây), chỉ một loại cỏ cụ thể không được định danh rõ trong tài liệu hiện đại. Wiktionary ghi \"obs-std a kind of grass\". Chữ cực hiếm. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "KHÔNG", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 鹵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹鹵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鹵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓾", "Unihan_Traditional (Chữ Phồn thể)": "蓾", "Pinyin_Xie": "lǔ", "Âm Hán Việt_Xie": "lỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cỏ, rất hiếm gặp trong văn bản thông thường. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藦', '{"9000": "7716.0", "Chữ Trung Quốc": "藦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 藦 | tượng hình | tên thực vật, cây la ma (蘿藦) | 藦 có bộ 艸 (thảo — cỏ cây), gợi liên quan đến thực vật. Chủ yếu dùng trong từ phức 蘿藦 (la ma, một loại cây leo). Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạc\": bộ 艸 (Thảo — cây cỏ) + âm mò → thành phần của tên cây 蘿藦 (la ma), loài cây leo Đông Á. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 藦 giúp nhận dạng tên cây 蘿藦 trong dược liệu và thực vật học cổ đại.", "Tự nguyên_Xie": "藦 (mò) thuộc bộ 艸 (cỏ cây), dùng chủ yếu trong từ phức 蘿藦/萝藦 — tên một loại cây leo (Metaplexis japonica), có quả dạng hạt. Wiktionary không có mục từ này. Chữ cực hiếm khi đứng độc lập. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: la ma 蘿藦,萝藦)", "Hạng Tần Suất (Jun Da)": "7716.0", "Tần Suất % (Jun Da)": "99.9989214694", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 摩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹摩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "摩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藦", "Unihan_Traditional (Chữ Phồn thể)": "藦", "Pinyin_Xie": "mò", "Âm Hán Việt_Xie": "ma", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường kết hợp thành từ ghép la ma để chỉ một loài cây leo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虀', '{"9000": "7717.0", "Chữ Trung Quốc": "虀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 22 | nét | 艹 | thảo | biểu nghĩa | cỏ cây | 韲 | biểu âm | 虀 = 艹 (Thảo, biểu nghĩa: cỏ/rau) + 韲 (biểu âm); chữ hình thanh. 艹 cho biết liên quan đến rau cỏ, 韲 cho âm đọc. Wiktionary ghi nguyên gốc là 𧆌; dạng hợp thể gồm 艸+齏/韲.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tê\": 艹 (Thảo — rau) + 韲 (biểu âm) → rau muối băm nhỏ, dưa cải cổ đại. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; bộ 艸 liên hệ \"thảo\" (cỏ) | Mở khoá kiến thức | Biết 虀 giúp đọc văn cổ về ẩm thực Trung Hoa, đặc biệt cách chế biến dưa muối truyền thống.", "Tự nguyên_Xie": "虀 (jī) là chữ hình thanh: 艹 (cỏ/rau) là biểu nghĩa, 韲 là biểu âm. Nguyên gốc từ 𧆌. Chỉ dưa cải muối, rau muối, cách băm nhỏ rau thành dưa. Wiktionary ghi: minced pickles, leeks, mix, salt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dưa muối", "Hạng Tần Suất (Jun Da)": "7717.0", "Tần Suất % (Jun Da)": "99.998922503", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 韲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹韲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "韲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "虀", "Unihan_Traditional (Chữ Phồn thể)": "虀", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "tê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ món dưa muối hoặc rau thái nhỏ trộn gia vị. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚈', '{"9000": "7718.0", "Chữ Trung Quốc": "蚈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 蚈 | tượng hình | đom đóm (phương ngôn), rết | 蚈 có bộ 虫 (trùng — sâu bọ), gợi liên quan đến côn trùng. Cấu trúc chi tiết không có trong CHISE. Wiktionary chỉ có phiên âm không có định nghĩa rõ. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiên\": bộ 虫 (Trùng — sâu bọ) + âm qiān → côn trùng nhỏ (đom đóm hoặc rết), nghĩa cụ thể chưa thống nhất. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng | Mở khoá kiến thức | 蚈 thuộc bộ 虫 — nhóm côn trùng như 蛇 (rắn), 蜂 (ong), 蜜蜂 (ong mật).", "Tự nguyên_Xie": "蚈 (qiān) thuộc bộ 虫 (sâu bọ), trong phương ngôn chỉ con đom đóm. Wiktionary chỉ có phiên âm mà không có định nghĩa. Chữ cực hiếm, chưa thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(vòm.) đom đóm", "Hạng Tần Suất (Jun Da)": "7718.0", "Tần Suất % (Jun Da)": "99.9989235366", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 开", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫开", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "开", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚈", "Unihan_Traditional (Chữ Phồn thể)": "蚈", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "khiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con đom đóm, là cách gọi cổ hoặc trong văn thơ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛡', '{"9000": "7719.0", "Chữ Trung Quốc": "蛡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 蛡 | tượng hình | tổ ong, con sâu | 蛡 có bộ 虫 (trùng — sâu bọ), gợi liên quan đến côn trùng hoặc sâu bọ. Cấu trúc chi tiết không có trong CHISE. Wiktionary không có mục từ này. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghị\": bộ 虫 (Trùng — sâu bọ) + âm yì → loài côn trùng nhỏ, tổ ong hoặc sâu; nghĩa cụ thể chưa rõ. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng | Mở khoá kiến thức | 蛡 thuộc bộ 虫 — nhóm côn trùng như 蚁 (kiến), 蜂 (ong), 蛹 (nhộng).", "Tự nguyên_Xie": "蛡 (yì) thuộc bộ 虫 (sâu bọ), chỉ tổ ong hoặc một loại sâu. Wiktionary không có mục từ này. Chữ cực hiếm, chưa thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tổ ong; tổ ong", "Hạng Tần Suất (Jun Da)": "7719.0", "Tần Suất % (Jun Da)": "99.9989245701", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛡", "Unihan_Traditional (Chữ Phồn thể)": "蛡", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò làm danh từ chỉ tổ của loài ong hoặc côn trùng trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝝', '{"9000": "7720.0", "Chữ Trung Quốc": "蝝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 虫 | trùng | biểu nghĩa | côn trùng | 爰 | viên | biểu âm | 蝝 gồm 虫 (Trùng, biểu nghĩa: côn trùng) và 爰 (Viên, biểu âm, đọc gần yuán); chữ hình thanh. Chỉ ấu trùng châu chấu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"viên\": con 虫 còn \"viên\" (non trẻ) — ấu trùng châu chấu chưa mọc cánh. | Gương Hán-Việt | viên — ít dùng trong tiếng Việt hiện đại, gặp trong cổ văn chỉ sâu bọ non | Mở khoá kiến thức | Biết 蝝 giúp đọc cổ văn nông nghiệp mô tả nạn châu chấu non phá mùa màng.", "Tự nguyên_Xie": "Wiktionary chỉ ghi phiên âm, không có phân tích glyph. Dựa cấu trúc: 蝝 = 虫 (côn trùng) + 爰 (biểu âm). Chữ chuyên chỉ ấu trùng của châu chấu hoặc kiến, xuất hiện trong văn bản cổ điển; chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ấu trùng của con châu chấu; ấu trùng của con kiến", "Hạng Tần Suất (Jun Da)": "7720.0", "Tần Suất % (Jun Da)": "99.9989266373", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 彖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫彖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝝", "Unihan_Traditional (Chữ Phồn thể)": "蝝", "Pinyin_Xie": "yuán", "Âm Hán Việt_Xie": "duyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong văn bản cổ để chỉ các loại ấu trùng côn trùng mới nở. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝹', '{"9000": "7721.0", "Chữ Trung Quốc": "蝹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 虫 | trùng | biểu nghĩa | côn trùng / sinh vật | 員 | viên | biểu âm | 蝹 gồm 虫 (Trùng) và 員 (Viên, biểu âm, đọc gần yūn); chữ hình thanh suy đoán. Nghĩa gốc không rõ — cổ thư ghi là loài sói hoặc sinh vật bò sát; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vẫn\": hình ảnh sinh vật (虫) \"vẫn\" (員) bí ẩn — chữ cổ chỉ loài thú hoang hiếm gặp. | Gương Hán-Việt | vẫn — không phổ biến trong tiếng Việt, chỉ xuất hiện trong từ điển Hán-Việt cổ | Mở khoá kiến thức | Biết 蝹 giúp đọc từ điển cổ phần mô tả động vật huyền thoại Trung Hoa.", "Tự nguyên_Xie": "Không có nguồn Wiktionary phân tích glyph. Chữ cực hiếm, cổ thư Trung Quốc ghi 蝹 có nghĩa liên quan đến chó sói hoặc sinh vật bí ẩn. Bộ 虫 thường chỉ sinh vật nhỏ hoặc bò sát. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chó sói", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 昷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫昷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝹", "Unihan_Traditional (Chữ Phồn thể)": "蝹", "Pinyin_Xie": "yūn", "Âm Hán Việt_Xie": "vẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ loài sói hoặc tính từ mô tả dáng điệu uốn lượn của côn trùng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟿', '{"9000": "7722.0", "Chữ Trung Quốc": "蟿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 19 | nét | 虫 | trùng | biểu nghĩa | côn trùng | 㡀 | biểu âm | phần biểu âm (hình dạng phức tạp) | 蟿 chứa bộ 虫 (Trùng, biểu nghĩa: côn trùng); phần còn lại biểu âm. Chữ hình thanh chuyên chỉ loài châu chấu Tryxalis masuta, chỉ dùng trong tổ hợp 蟿螽.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khí\": con 虫 mang \"khí\" (qì) vượt — loài châu chấu nhảy vọt đầy khí thế. | Gương Hán-Việt | khí — không dùng độc lập trong tiếng Việt; chỉ xuất hiện trong từ điển Hán cổ | Mở khoá kiến thức | Biết 蟿 giúp đọc danh pháp côn trùng trong cổ điển như Nhĩ Nhã (爾雅).", "Tự nguyên_Xie": "Wiktionary ghi nhận âm đọc Middle Chinese và Old Chinese nhưng không phân tích glyph. 蟿 chỉ dùng trong 蟿螽, chỉ một loài châu chấu đặc biệt ghi trong cổ điển Trung Quốc. Chữ tạo muộn dành riêng cho danh pháp động vật học cổ; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(côn trùng); Tryxalis masuta", "Hạng Tần Suất (Jun Da)": "7722.0", "Tần Suất % (Jun Da)": "99.9989287044", "GavinGrover_Once (Chiết tự trực tiếp)": "𣪠 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𣪠虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𣪠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟿", "Unihan_Traditional (Chữ Phồn thể)": "蟿", "Pinyin_Xie": "qì", "Âm Hán Việt_Xie": "kỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loài côn trùng cụ thể thuộc họ cào cào trong cổ thư. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衼', '{"9000": "7723.0", "Chữ Trung Quốc": "衼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 9 | nét | 衤 | y | biểu nghĩa | quần áo | 只 | chỉ | biểu âm | chỉ, duy nhất | 衼 gồm 衤 (Y, biểu nghĩa: quần áo) và 只 (Chỉ, biểu âm, đọc gần zhī); chữ hình thanh. Chỉ y phục của tăng ni, chỉ dùng trong 衹衼.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chỉ\": tấm áo (衤) mà nhà tu chỉ (只) mặc một kiểu — y phục giản dị của tăng ni. | Gương Hán-Việt | chỉ — trong \"衹衼\" (y phục tăng ni); ít dùng độc lập | Mở khoá kiến thức | Biết 衼 giúp đọc văn bản Phật giáo cổ điển Trung Hoa mô tả trang phục tu sĩ.", "Tự nguyên_Xie": "Wiktionary ghi nhận phiên âm Middle/Old Chinese và xác định chữ chỉ dùng trong tổ hợp 衹衼 (y phục tăng ni Phật giáo). Bộ 衤 xác nhận nghĩa liên quan trang phục. Chưa có phân tích glyph sâu; chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "衼", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 支", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤支", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "支", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "衼", "Unihan_Traditional (Chữ Phồn thể)": "衼", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "chỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ bộ phận của trang phục hoặc bộ phận cơ thể trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褦', '{"9000": "7724.0", "Chữ Trung Quốc": "褦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 15 | nét | 衤 | y | biểu nghĩa | quần áo | 能 | năng | biểu âm | có thể, tài năng | 褦 = 衤 (Y, biểu nghĩa: quần áo) + 能 (Năng, biểu âm, đọc gần nài); chữ hình thanh. Chỉ mũ che nắng hoặc người không hiểu chuyện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nại\": cái áo-mũ (衤) mà người \"năng\" (能) ngu ngơ đội — ai đội mũ che mắt thì không biết gì. | Gương Hán-Việt | nại — trong \"褦襶\" (nại đới): kẻ quê mùa, không biết gì | Mở khoá kiến thức | Biết 褦 mở khoá từ \"褦襶\" — chỉ người lạc lõng, không biết phép tắc xã hội.", "Tự nguyên_Xie": "Wiktionary xác nhận: 褦 = 衤 (quần áo, biểu nghĩa) + 能 (biểu âm). Chữ hình thanh điển hình. Nghĩa gốc là mũ che nắng; nghĩa phái sinh chỉ người không biết gì, kém hiểu biết — có lẽ từ hình ảnh người đội mũ che mắt không nhìn rõ sự đời. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "không biết, không hiểu; mũ che nắng", "Hạng Tần Suất (Jun Da)": "7724.0", "Tần Suất % (Jun Da)": "99.9989307716", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 能", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤能", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "能", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褦", "Unihan_Traditional (Chữ Phồn thể)": "褦", "Pinyin_Xie": "nài", "Âm Hán Việt_Xie": "nại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường kết hợp với chữ đới thành từ ghép nại đới để chỉ sự ngu ngơ hoặc che mắt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('襶', '{"9000": "7725.0", "Chữ Trung Quốc": "襶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 22 | nét | 衤 | y | biểu nghĩa | quần áo | 帶 | đới | biểu âm | dây đai, mang theo | 襶 gồm 衤 (Y, biểu nghĩa: quần áo) và 帶 (Đới, biểu âm, đọc gần dài); chữ hình thanh suy đoán. Chỉ y phục lộn xộn, bù xù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đới\": quần áo (衤) đeo \"đai\" (帶) bừa bãi — hình ảnh người ăn mặc luộm thuộm. | Gương Hán-Việt | đới — trong \"褦襶\" (nại đới): quần áo lộn xộn, kẻ không biết phép tắc | Mở khoá kiến thức | Biết 襶 giúp đọc văn học cổ điển mô tả nhân vật quê mùa, luộm thuộm.", "Tự nguyên_Xie": "Wiktionary ghi phiên âm Middle/Old Chinese, không phân tích glyph sâu. 襶 chủ yếu dùng trong tổ hợp 褦襶 (quần áo bẩn thỉu, lộn xộn; kẻ quê mùa). Bộ 衤 xác nhận liên quan trang phục. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bù xù, lộn xộn", "Hạng Tần Suất (Jun Da)": "7725.0", "Tần Suất % (Jun Da)": "99.9989318051", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 戴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤戴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "襶", "Unihan_Traditional (Chữ Phồn thể)": "襶", "Pinyin_Xie": "dài", "Âm Hán Việt_Xie": "đái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chủ yếu dùng làm tính từ trong từ ghép nại đới để mô tả trạng thái luộm thuộm hoặc ngu ngơ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('覐', '{"9000": "7726.0", "Chữ Trung Quốc": "覐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 見 | Số nét | 11 | nét | 見 | kiến | biểu nghĩa | nhìn, thấy | 學 | học | biểu âm | học | 覐 chứa bộ 見 (Kiến, nhìn thấy); phần trên có thể là biểu âm liên quan 學/覺. Chữ hình thanh suy đoán, nghĩa không rõ trong từ điển hiện đại; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giác\": dùng mắt (見) để \"giác\" ngộ — nhìn thấy mà hiểu ra điều gì đó. | Gương Hán-Việt | giác — liên quan đến 覺 (giác ngộ, nhận thức) | Mở khoá kiến thức | Biết 覐 liên hệ đến 覺 (giác) — nhận thức, nhìn ra sự thật.", "Tự nguyên_Xie": "Không có nguồn Wiktionary phân tích glyph. Bộ thủ 見 gợi liên quan đến nhìn, quan sát. Dạng chữ gần với 覺 (giác, nhận biết). Chữ cực hiếm, chưa thấy trong giáp cốt/kim văn; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "覐", "Hạng Tần Suất (Jun Da)": "7726.0", "Tần Suất % (Jun Da)": "99.9989328387", "GavinGrover_Once (Chiết tự trực tiếp)": "見 + 爻", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴見爻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "見", "Unihan_Simplified (Chữ Giản thể)": "覐", "Unihan_Traditional (Chữ Phồn thể)": "覐", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "giác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ biểu thị sự nhận thức, cảm giác hoặc tỉnh ngộ, là dạng cổ của chữ giác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詯', '{"9000": "7727.0", "Chữ Trung Quốc": "詯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 13 | nét | 言 | ngôn | biểu nghĩa | lời nói, ngôn ngữ | 回 | hồi | biểu âm | quay lại, vòng tròn | 詯 gồm 言 (Ngôn, biểu nghĩa: lời nói) và 回 (Hồi, biểu âm, đọc gần huì); chữ hình thanh. Nghĩa cụ thể không rõ trong nguồn hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hối\": lời nói (言) \"hồi\" về — có thể là lời nói quay vòng, không rõ ý. | Gương Hán-Việt | hối — ít dùng độc lập; liên quan nhóm 言 (ngôn ngữ) | Mở khoá kiến thức | Biết 詯 giúp nhận ra nhóm chữ 言 chỉ các sắc thái lời nói trong cổ văn.", "Tự nguyên_Xie": "Wiktionary ghi phiên âm Middle/Old Chinese nhưng không phân tích nghĩa hay glyph. Bộ 言 xác nhận liên quan đến lời nói. Chữ cực hiếm, chưa có nguồn học thuật về nghĩa gốc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "诩", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 自", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言自", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "自", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "詯", "Unihan_Traditional (Chữ Phồn thể)": "詯", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "hối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Dùng làm động từ hoặc tính từ chỉ hành vi nói khoác, tự cao tự đại trong văn cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('誴', '{"9000": "7728.0", "Chữ Trung Quốc": "誴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 15 | nét | 言 | ngôn | biểu nghĩa | lời nói | 从 | tùng | biểu âm | theo, từ | 誴 gồm 言 (Ngôn, biểu nghĩa: lời nói) và 从 (Tùng, biểu âm, đọc gần cóng); chữ hình thanh. Nghĩa không rõ trong nguồn hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tùng\": lời (言) theo (从) nhau — nhiều lời nói tiếp nối. | Gương Hán-Việt | tùng — ít dùng độc lập trong tiếng Việt; bộ 言 | Mở khoá kiến thức | Biết 誴 giúp nhận biết nhóm chữ 言 hiếm dùng trong cổ văn Trung Hoa.", "Tự nguyên_Xie": "Wiktionary chỉ ghi phiên âm, không có định nghĩa hay phân tích glyph. Bộ 言 xác nhận liên quan đến lời nói. Chữ cực hiếm; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "贴", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 宗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言宗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "誴", "Unihan_Traditional (Chữ Phồn thể)": "誴", "Pinyin_Xie": "cóng", "Âm Hán Việt_Xie": "tùng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động đính, dán hoặc áp sát vật này vào vật khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('諓', '{"9000": "7729.0", "Chữ Trung Quốc": "諓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 15 | nét | 言 | ngôn | biểu nghĩa | lời nói | 戔 | tiên | biểu âm | nhỏ, ít | 諓 gồm 言 (Ngôn, biểu nghĩa: lời nói) và 戔 (Tiên, biểu âm, đọc gần jiàn); chữ hình thanh. Nghĩa: khéo ăn nói, lưu loát.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiển\": lời (言) nhỏ (戔) mà trơn — kẻ khéo mồm chỉ dùng lời nhỏ nhẹ êm tai. | Gương Hán-Việt | tiển — trong \"諓諓\" (lời lẽ trơn tru, khéo léo); ít dùng độc lập | Mở khoá kiến thức | Biết 諓 giúp đọc văn học cổ điển mô tả kiểu người khéo mồm nhưng thiếu thực chất.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi: 諓 là tính từ văn ngôn (literary) nghĩa là nói năng lưu loát, khéo léo, suave. Bộ 言 xác nhận liên quan lời nói. Hay dùng trong tổ hợp 諓諓 (lời lẽ khéo léo trơn tru). Nguồn âm Middle Chinese: zien. Chưa có phân tích glyph chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khéo nói; giỏi ăn nói", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 戔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言戔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "諓", "Unihan_Traditional (Chữ Phồn thể)": "諓", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "tiễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả người có tài hùng biện nhưng lời nói thiếu chiều sâu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('謧', '{"9000": "7730.0", "Chữ Trung Quốc": "謧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 17 | nét | 言 | ngôn | biểu nghĩa | lời nói | 离 | ly | biểu âm | xa cách, lìa | 謧 gồm 言 (Ngôn, biểu nghĩa: lời nói) và 离 (Ly, biểu âm, đọc gần lí); chữ hình thanh. Nghĩa không rõ trong nguồn hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ly\": lời (言) \"ly\" biệt — lời nói xa cách, không gần gũi. | Gương Hán-Việt | ly — ít dùng độc lập; bộ 言 nhóm chữ hiếm | Mở khoá kiến thức | Biết 謧 giúp nhận biết nhóm chữ 言+ly trong cổ văn.", "Tự nguyên_Xie": "Wiktionary ghi phiên âm Middle/Old Chinese nhưng không cung cấp định nghĩa hay phân tích glyph. Bộ 言 xác nhận liên quan đến ngôn ngữ hoặc lời nói. Chữ cực hiếm; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "觧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 离", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言离", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "离", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "謧", "Unihan_Traditional (Chữ Phồn thể)": "謧", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "ly", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này chủ yếu dùng làm động từ trong văn ngôn để chỉ hành động phân chia hoặc giải thích. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('謪', '{"9000": "7731.0", "Chữ Trung Quốc": "謪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 18 | nét | 言 | ngôn | biểu nghĩa | lời nói | 商 | thương | biểu âm | thương mại; thương lượng | 謪 = 言 (Ngôn, biểu nghĩa: lời nói) + 商 (Thương, biểu âm, đọc shāng); chữ hình thanh. Nghĩa: dùng lời mà khiển trách, luận tội.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thương\": dùng lời (言) mà \"thương\" lượng tội trạng — khiển trách công khai. | Gương Hán-Việt | thương — trong \"謪責\" (thương trách): lời khiển trách | Mở khoá kiến thức | Biết 謪 giúp đọc văn bản pháp lý cổ điển mô tả hình phạt và lời buộc tội.", "Tự nguyên_Xie": "Wiktionary xác nhận: 謪 = 言 (biểu nghĩa) + 商 (biểu âm), chữ hình thanh. Wiktionary dẫn sang 商 như một dạng biến thể. Nghĩa là khiển trách bằng lời, chỉ ra lỗi lầm. Phiên âm Middle Chinese: ʃɨɐŋ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khiển trách, phạt; lỗi lầm; biến khí", "Hạng Tần Suất (Jun Da)": "7731.0", "Tần Suất % (Jun Da)": "99.9989380065", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 商", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言商", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "商", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "謪", "Unihan_Traditional (Chữ Phồn thể)": "謪", "Pinyin_Xie": "shāng", "Âm Hán Việt_Xie": "trích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ để chỉ việc khiển trách hoặc làm danh từ chỉ lỗi lầm trong văn bản cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('譁', '{"9000": "7732.0", "Chữ Trung Quốc": "譁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 17 | nét | 言 | ngôn | biểu nghĩa | lời nói, tiếng động | 華 | hoa | biểu âm | hoa lệ, rực rỡ | 譁 = 言 (Ngôn, biểu nghĩa: tiếng động, lời nói) + 華 (Hoa, biểu âm, đọc huá); chữ hình thanh. Là dạng chính thể (truyền thống) của 嘩, nghĩa: ồn ào, náo loạn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoa\": tiếng (言) \"hoa\" lệ ầm ĩ — đám đông la ó rực rỡ như hoa nở. | Gương Hán-Việt | hoa — trong \"譁然\" (hoa nhiên): ồn ào náo loạn; \"譁變\" (hoa biến): binh biến | Mở khoá kiến thức | Biết 譁 mở khoá 譁然、譁變 — ồn ào náo loạn và binh biến trong sử học.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận 譁 là dạng truyền thống (chính thể) của 嘩. Chữ hình thanh: 言 (biểu nghĩa, tiếng ồn) + 華 (biểu âm). Nghĩa gốc: tiếng ồn ào, náo nhiệt đến mức rối loạn — 譁然 (ồn ào náo loạn), 譁變 (binh biến kèm tiếng la hét). Seal inscription còn lưu giữ dạng cổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Ồ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 華", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言華", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "華", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "譁", "Unihan_Traditional (Chữ Phồn thể)": "譁", "Pinyin_Xie": "huá", "Âm Hán Việt_Xie": "hoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả âm thanh ồn ào hoặc động từ chỉ sự làm loạn, xôn xao. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貤', '{"9000": "7733.0", "Chữ Trung Quốc": "貤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 10 | nét | 貝 | bối | biểu nghĩa | vỏ sò, tiền của | 也 | dã | biểu âm | cũng, vậy | 貤 gồm 貝 (Bối, biểu nghĩa: của cải, tiền) và 也 (Dã, biểu âm, đọc gần yí); chữ hình thanh. Nghĩa: chuyển nhượng tước vị hoặc của cải cho người khác.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\": của (貝) \"di\" chuyển sang — trao tước phong cho người thân. | Gương Hán-Việt | di — trong \"貤贈\" (di tặng): ban phong tước thêm cho thân nhân quan viên | Mở khoá kiến thức | Biết 貤 giúp đọc văn bản phong kiến về chế độ phong tước và bổng lộc.", "Tự nguyên_Xie": "Wiktionary ghi phiên âm Middle/Old Chinese. Bộ 貝 xác nhận liên quan đến tài sản, của cải. 貤 dùng trong các từ như 貤贈 (tặng thêm tước phẩm cho người nhà quan viên), 貤封 (phong thêm tước cho thân nhân). Chữ thuộc hệ thống phong kiến Trung Quốc; chưa có phân tích glyph chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thay đổi, chuyển cho người khác", "Hạng Tần Suất (Jun Da)": "7733.0", "Tần Suất % (Jun Da)": "99.9989400737", "GavinGrover_Once (Chiết tự trực tiếp)": "貝 + 也", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰貝也", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "也", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "貤", "Unihan_Traditional (Chữ Phồn thể)": "貤", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "dị, di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn ngôn để chỉ việc chuyển giao tước vị hoặc ban tặng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赪', '{"9000": "7734.0", "Chữ Trung Quốc": "赪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 赤 | Số nét | 13 | nét | 赤 | xích | biểu nghĩa | màu đỏ | 贞 | trinh | biểu âm | trinh tiết, kiên định | 赪 gồm 赤 (Xích, biểu nghĩa: màu đỏ) và 贞 (Trinh, biểu âm, đọc gần chēng); chữ hình thanh. Là dạng giản thể của 赬, chỉ màu đỏ thẫm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tranh\": màu 赤 đỏ mà \"trinh\" (贞) kiên — đỏ thẫm, đỏ son không phai. | Gương Hán-Việt | tranh — trong \"赪顏\" (tranh nhan): mặt đỏ ửng | Mở khoá kiến thức | Biết 赪 giúp đọc thơ văn cổ mô tả màu sắc và sắc mặt.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary xác nhận: 赪 là dạng giản thể hoá của 赬 (Han simp: f=貞, t=贞). Bộ 赤 (đỏ) xác nhận nghĩa màu sắc. 赬/赪 chỉ màu đỏ thẫm, màu cá đỏ. Trong đại triện và tiểu triện còn lưu dạng cổ của chữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màu đỏ", "Hạng Tần Suất (Jun Da)": "7734.0", "Tần Suất % (Jun Da)": "99.9989411073", "GavinGrover_Once (Chiết tự trực tiếp)": "赤 + 贞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰赤贞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "赤", "Unihan_Simplified (Chữ Giản thể)": "赪", "Unihan_Traditional (Chữ Phồn thể)": "赬", "Pinyin_Xie": "chēng", "Âm Hán Việt_Xie": "trinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ để miêu tả màu đỏ hoặc động từ chỉ trạng thái đỏ mặt vì ngượng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踖', '{"9000": "7735.0", "Chữ Trung Quốc": "踖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 15 | nét | 足 | túc | biểu nghĩa | chân, bước chân | 脊 | tích | biểu âm | xương sống | 踖 gồm 足 (Túc, biểu nghĩa: chân, bước đi) và 脊 (Tích, biểu âm, đọc gần jí); chữ hình thanh. Nghĩa: chạy nhanh, bước vội vàng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tếch\": cái chân (足) \"tếch\" nhanh đi — chạy vội để lo công việc. | Gương Hán-Việt | tếch — trong tiếng Việt gốc Hán ít dùng; nghĩa chạy nhanh | Mở khoá kiến thức | Biết 踖 giúp đọc văn học phương ngữ Mân Nam mô tả cảnh chạy vội làm việc.", "Tự nguyên_Xie": "Wiktionary ghi: 踖 trong tiếng Mân Nam (Hokkien) có nghĩa là chạy nhanh, chạy vội để làm việc. Bộ 足 (chân) xác nhận nghĩa liên quan đến bước chân. Âm Middle Chinese: dzik. Dùng nhiều trong phương ngữ Mân Nam hơn tiếng Hán phổ thông. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vượt qua", "Hạng Tần Suất (Jun Da)": "7735.0", "Tần Suất % (Jun Da)": "99.9989421408", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 昔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊昔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踖", "Unihan_Traditional (Chữ Phồn thể)": "踖", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ hành động bước đi hoặc tính từ miêu tả dáng đi cung kính. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軆', '{"9000": "7736.0", "Chữ Trung Quốc": "軆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 身 | Số nét | 20 | nét | 骨 | cốt | biểu nghĩa | xương | 豊 | lễ | biểu âm | lễ nghi, phong phú | 軆 là dạng chữ cổ của 體 (thể). Gồm 骨 (Cốt, biểu nghĩa: xương, thân thể) và 豊 (Lễ, biểu âm, đọc tǐ); chữ hình thanh. Nghĩa: thân thể, hình thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thể\": xương (骨) dựng nên thân thể (豊) — khung xương kiên cố là nền tảng của hình thể. | Gương Hán-Việt | thể — trong \"軆裁\" (thể tài): thể loại; dạng cổ của 體 | Mở khoá kiến thức | Biết 軆 nhận ra dạng biến thể của 體 trong văn bản cổ và kim văn.", "Tự nguyên_Xie": "軆 là dạng dị thể (biến thể) của 體 (thân thể). Không có nguồn Wiktionary phân tích glyph riêng. Cấu trúc tương đương 體: bộ 骨 (xương) biểu nghĩa thân xác; phần biểu âm 豊 gần âm tǐ. Chữ tạo muộn; không thấy rõ trong giáp cốt/kim văn; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thân, mình; hình thể; dạng", "Hạng Tần Suất (Jun Da)": "7736.0", "Tần Suất % (Jun Da)": "99.9989431744", "GavinGrover_Once (Chiết tự trực tiếp)": "身 + 豊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰身豊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "身", "Unihan_Simplified (Chữ Giản thể)": "軆", "Unihan_Traditional (Chữ Phồn thể)": "軆", "Pinyin_Xie": "tǐ", "Âm Hán Việt_Xie": "thể", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ cơ thể con người hoặc hình thức, thể loại của sự vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輈', '{"9000": "7737.0", "Chữ Trung Quốc": "輈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 13 | nét | 車 | xa | biểu nghĩa | xe, xe ngựa | 周 | chu | biểu âm | xung quanh, chu toàn | 輈 gồm 車 (Xa, biểu nghĩa: xe ngựa) và 周 (Chu, biểu âm, đọc zhōu); chữ hình thanh. Chỉ cái càng xe, trục xe ngựa thời cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trù\": cái xe (車) vòng (周) quanh — thanh càng xe xoay quanh trục kéo ngựa. | Gương Hán-Việt | trù — ít dùng trong tiếng Việt; chỉ bộ phận xe ngựa cổ | Mở khoá kiến thức | Biết 輈 giúp đọc văn bản kỹ thuật cổ về chế tạo xe ngựa thời Chu-Hán.", "Tự nguyên_Xie": "Tiểu triện | Lưu thư thông (chữ tạo muộn) | Không có phân tích glyph chi tiết từ Wiktionary. Bộ 車 xác nhận liên quan đến xe. 輈 là thanh gỗ ngang hoặc càng xe ngựa kéo, một bộ phận cụ thể của xe cổ. Tiểu triện và lưu thư thông còn lưu dạng cổ. Chữ tạo muộn, không thấy trong giáp cốt văn; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Thang", "Hạng Tần Suất (Jun Da)": "6705.0", "Tần Suất % (Jun Da)": "99.995146354", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 舟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車舟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "辀", "Unihan_Traditional (Chữ Phồn thể)": "輈", "Pinyin_Xie": "zhōu", "Âm Hán Việt_Xie": "trù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ bộ phận càng xe thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄛', '{"9000": "7738.0", "Chữ Trung Quốc": "鄛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 13 | nét | 巢 | sào | biểu âm | tổ (chim), sào huyệt | 邑 | ấp | biểu nghĩa | làng, ấp, địa danh | 鄛 gồm 巢 (Sào, biểu âm, đọc gần cháo) và 邑/阝 (Ấp, biểu nghĩa: địa danh, làng ấp); chữ hình thanh. Chuyên dùng làm địa danh cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sào\": ấp (阝) của người \"sào\" — làng cổ có tên liên quan đến sào huyệt, tổ chim. | Gương Hán-Việt | sào — dùng trong địa danh cổ vùng Trung Nguyên | Mở khoá kiến thức | Biết 鄛 giúp đọc bản đồ lịch sử và địa chí cổ Trung Quốc.", "Tự nguyên_Xie": "Kim văn | Bạch thư (Mã Vương Đôi) | Tiểu triện | Wiktionary xác nhận: 鄛 là địa danh cổ, dùng trong 地名 (place name). Bộ 邑/阝 (ấp, làng) đặc trưng của chữ chỉ tên đất. Âm Middle Chinese: dræu. Kim văn, bạch thư (silk) và tiểu triện đều còn lưu dạng cổ, cho thấy đây là địa danh lâu đời. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鄛", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "巢 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巢阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄛", "Unihan_Traditional (Chữ Phồn thể)": "鄛", "Pinyin_Xie": "cháo", "Âm Hán Việt_Xie": "sào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng để chỉ địa danh hoặc tên huyện thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄡', '{"9000": "7739.0", "Chữ Trung Quốc": "鄡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 13 | nét | 喬 | kiều | biểu âm | cao, kiều | 邑 | ấp | biểu nghĩa | làng, ấp, địa danh | 鄡 gồm 喬 (Kiều, biểu âm, đọc gần qiāo) và 邑/阝 (Ấp, biểu nghĩa: địa danh); chữ hình thanh. Chuyên dùng làm địa danh cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiều\": ấp (阝) cao (喬) trên núi — địa danh cổ ở vùng đất cao. | Gương Hán-Việt | kiều — dùng trong địa danh cổ, không phổ biến trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 鄡 giúp nhận biết nhóm chữ 邑 chuyên dùng cho địa danh cổ.", "Tự nguyên_Xie": "Wiktionary ghi phiên âm Middle/Old Chinese nhưng không có định nghĩa cụ thể. Bộ 邑/阝 đặc trưng cho chữ chỉ tên đất. Chữ cực hiếm, chỉ xuất hiện trong địa lý học cổ Trung Quốc; chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鄡", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "梟 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰梟阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "梟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄡", "Unihan_Traditional (Chữ Phồn thể)": "鄡", "Pinyin_Xie": "qiāo", "Âm Hán Việt_Xie": "kiều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng để chỉ địa danh cổ ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醖', '{"9000": "7740.0", "Chữ Trung Quốc": "醖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 16 | nét | 酉 | dậu | biểu nghĩa | bình rượu, men rượu | 昷 | ôn | biểu âm | ấm áp | 醖 gồm 酉 (Dậu, biểu nghĩa: bình rượu, ủ rượu) và 昷 (Ôn, biểu âm, đọc gần yùn); chữ hình thanh. Là dạng dị thể của 醞, nghĩa: pha chế, ủ rượu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uẩn\": bình rượu (酉) giữ \"ôn\" ấm — ủ rượu âm thầm lên men bên trong. | Gương Hán-Việt | uẩn — trong \"醖釀\" (uẩn nương): ủ rượu, thai nghén kế hoạch | Mở khoá kiến thức | Biết 醖 nhận ra dị thể của 醞 trong văn bản cổ, liên quan ủ rượu và thai nghén ý tưởng.", "Tự nguyên_Xie": "Wiktionary xác nhận: 醖 là dạng biến thể (variant) của 醞 (pha chế, ủ rượu). Bộ 酉 (bình rượu) xác nhận nghĩa liên quan đến rượu và lên men. 醞/醖 mô tả quá trình ủ lên men, pha chế rượu. Dùng trong 醞釀 (ủ rượu, thai nghén ý tưởng). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "pha chế", "Hạng Tần Suất (Jun Da)": "7740.0", "Tần Suất % (Jun Da)": "99.9989473087", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 昷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉昷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醖", "Unihan_Traditional (Chữ Phồn thể)": "醖", "Pinyin_Xie": "yùn", "Âm Hán Việt_Xie": "uẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ việc cất rượu hoặc danh từ chỉ rượu ngon. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('屺', '{"9000": "7741.0", "Chữ Trung Quốc": "屺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 6 | nét | 山 | sơn | biểu nghĩa | núi | 己 | kỷ | biểu âm | bản thân, can chi Kỷ | 屺 = 山 (Sơn, biểu nghĩa: núi) + 己 (Kỷ, biểu âm, đọc gần qǐ); chữ hình thanh. Nghĩa: ngọn núi trọc, không có cây cối.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khỉ\": ngọn núi (山) như \"kỷ\" (己) cô đơn — núi trơ trọc, không một bóng cây. | Gương Hán-Việt | khỉ — trong thơ cổ chỉ núi trọc; ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 屺 giúp đọc Kinh Thi và thơ Đường mô tả cảnh núi non hoang vu.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận: 屺 = 山 (núi, biểu nghĩa) + 己 (biểu âm). Chữ hình thanh điển hình. Nghĩa gốc là ngọn núi trọc, không có cây cối phủ xanh. Tiểu triện còn lưu dạng cổ. Hay xuất hiện trong thơ Kinh Thi và cổ điển Trung Quốc mô tả cảnh núi hoang. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "núi trọc", "Hạng Tần Suất (Jun Da)": "7741.0", "Tần Suất % (Jun Da)": "99.9989483423", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 己", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山己", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "己", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "屺", "Unihan_Traditional (Chữ Phồn thể)": "屺", "Pinyin_Xie": "qǐ", "Âm Hán Việt_Xie": "dĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong văn thơ cổ để chỉ ngọn núi trọc không có cây cối. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鍑', '{"9000": "7742.0", "Chữ Trung Quốc": "鍑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 金 | kim | biểu nghĩa | kim loại | 复 | phục | biểu âm | lại, phục hồi | 鍑 gồm 金 (Kim, biểu nghĩa: kim loại) và 复 (Phục, biểu âm, đọc gần fù); chữ hình thanh. Chỉ nồi đồng miệng rộng thời cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phức\": cái nồi (金) \"phục\" (复) hồi — nồi đồng lớn tái sử dụng nhiều lần. | Gương Hán-Việt | phức — ít dùng trong tiếng Việt; chỉ đồ vật kim loại cổ | Mở khoá kiến thức | Biết 鍑 giúp đọc văn bản khảo cổ và tản văn cổ mô tả đồ dùng nhà bếp thời Hán.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary ghi: 鍑 là nồi kim loại lớn, miệng rộng, đôi khi có nắp, dùng trong thời cổ đại (historical). Bộ 金 xác nhận làm từ kim loại. Đại triện và tiểu triện còn lưu dạng cổ. Âm Middle Chinese: buwk. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鑍", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 复", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金复", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "复", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鍑", "Unihan_Traditional (Chữ Phồn thể)": "鍑", "Pinyin_Xie": "fù", "Âm Hán Việt_Xie": "phức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại dụng cụ nấu ăn bằng kim loại thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鏉', '{"9000": "7743.0", "Chữ Trung Quốc": "鏉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 19 | nét | 金 | kim | biểu nghĩa | kim loại | 叜 | tẩu | biểu âm | ông già | 鏉 gồm 金 (Kim, biểu nghĩa: kim loại) và 叜 (Tẩu, biểu âm, đọc gần shòu); chữ hình thanh suy đoán. Nghĩa không rõ trong từ điển hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thụ\": vật kim loại (金) nhỏ \"thụ\" — kim loại tối giản, ít ỏi. | Gương Hán-Việt | thụ — ít dùng độc lập; bộ 金 nhóm chữ hiếm | Mở khoá kiến thức | Biết 鏉 giúp nhận biết nhóm chữ 金 hiếm dùng trong từ điển kim loại cổ.", "Tự nguyên_Xie": "Không có nguồn Wiktionary phân tích glyph. Bộ 金 xác nhận liên quan đến kim loại. Nghĩa \"tối thiểu\" trong từ điển có thể là phái sinh hoặc hiểu nhầm. Chữ cực hiếm; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tối thiểu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 欶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金欶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "欶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鏉", "Unihan_Traditional (Chữ Phồn thể)": "鏉", "Pinyin_Xie": "shòu", "Âm Hán Việt_Xie": "thụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường dùng làm danh từ chỉ vết rỉ sét hoặc động từ chỉ việc khắc vẽ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雊', '{"9000": "7744.0", "Chữ Trung Quốc": "雊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 隹 | Số nét | 13 | nét | 隹 | chuy | biểu nghĩa | chim đuôi ngắn | 句 | cú | biểu âm | câu, cong | 雊 gồm 隹 (Chuy, biểu nghĩa: chim đuôi ngắn) và 句 (Cú, biểu âm, đọc gần gòu); chữ hình thanh. Chỉ tiếng kêu của chim trĩ đực.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cú\": con chim (隹) kêu \"cú\" gòu — tiếng trĩ đực gọi bạn tình trong rừng. | Gương Hán-Việt | cú — ít dùng độc lập; trong thơ cổ chỉ tiếng chim trĩ | Mở khoá kiến thức | Biết 雊 giúp đọc thơ Kinh Thi và cổ điển mô tả âm thanh thiên nhiên.", "Tự nguyên_Xie": "Tiểu triện | Không có nguồn Wiktionary phân tích glyph chi tiết. Bộ 隹 (chim đuôi ngắn) xác nhận liên quan đến chim. 雊 mô tả tiếng kêu đặc trưng của chim trĩ (pheasant) đực trong mùa sinh sản. Tiểu triện còn lưu dạng cổ. Chữ xuất hiện trong cổ điển mô tả cảnh vật thiên nhiên; chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng chim trĩ kêu", "Hạng Tần Suất (Jun Da)": "7744.0", "Tần Suất % (Jun Da)": "99.998951443", "GavinGrover_Once (Chiết tự trực tiếp)": "句 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰句隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "隹", "Unihan_Simplified (Chữ Giản thể)": "雊", "Unihan_Traditional (Chữ Phồn thể)": "雊", "Pinyin_Xie": "gòu", "Âm Hán Việt_Xie": "cẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ mô tả tiếng kêu của chim trĩ hoặc danh từ chỉ âm thanh đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飐', '{"9000": "7745.0", "Chữ Trung Quốc": "飐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 風 | Số nét | 9 | nét | 风 | phong | biểu nghĩa | gió | 占 | chiêm | biểu âm | chiếm, xem bói | 飐 = 风 (Phong, biểu nghĩa: gió) + 占 (Chiêm, biểu âm, đọc gần zhǎn); chữ hình thanh. Là dạng giản thể của 颭, nghĩa: gió lay động cành lá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiêm\": gió (风) \"chiêm\" — cánh hoa rung rinh như quẻ bói dưới làn gió. | Gương Hán-Việt | chiêm — trong \"風飐\" (phong chiêm): gió lay; ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 飐 giúp đọc thơ cổ Trung Hoa mô tả gió lay cành lá.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận: 飐 là dạng giản thể của 颭 (Han simp: f=風, t=风). Bộ 风 (gió) xác nhận nghĩa liên quan đến gió. 飐/颭 mô tả gió lay động cành lá, cờ hiệu rung rinh trong gió. Tiểu triện còn lưu dạng cổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gió lay động", "Hạng Tần Suất (Jun Da)": "7745.0", "Tần Suất % (Jun Da)": "99.9989535101", "GavinGrover_Once (Chiết tự trực tiếp)": "风 + 占", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴风占", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "占", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "风", "Unihan_Simplified (Chữ Giản thể)": "飐", "Unihan_Traditional (Chữ Phồn thể)": "颭", "Pinyin_Xie": "zhǎn", "Âm Hán Việt_Xie": "triển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ mô tả trạng thái hoa lá hoặc đồ vật lay động trước gió. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稆', '{"9000": "7746.0", "Chữ Trung Quốc": "稆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 11 | nét | 禾 | hòa | biểu nghĩa | lúa, ngũ cốc | 呂 | lữ | biểu âm | họ Lữ, âm nhạc | 稆 gồm 禾 (Hòa, biểu nghĩa: lúa, ngũ cốc) và 呂 (Lữ, biểu âm, đọc gần lǚ); chữ hình thanh. Nghĩa: lúa chét, lúa mọc tự nhiên không có người trồng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lữ\": lúa (禾) \"lữ\" hành — lúa không ai trồng, tự mọc như khách lữ hành. | Gương Hán-Việt | lữ — ít dùng trong tiếng Việt; chỉ lúa hoang trong văn bản nông học cổ | Mở khoá kiến thức | Biết 稆 giúp đọc văn bản nông nghiệp cổ điển mô tả các loại lúa hoang dại.", "Tự nguyên_Xie": "Wiktionary ghi: 稆 là wild grain (lúa hoang dại). Bộ 禾 (lúa) xác nhận nghĩa ngũ cốc. 稆 chỉ loại lúa mọc tự nhiên từ hạt rụng năm trước, không do người gieo — lúa chét hoặc lúa ma trong văn bản nông nghiệp cổ. Âm Middle Chinese và Old Chinese đều còn ghi chép. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lúa chét, lúa ma", "Hạng Tần Suất (Jun Da)": "7746.0", "Tần Suất % (Jun Da)": "99.9989545437", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 吕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾吕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稆", "Unihan_Traditional (Chữ Phồn thể)": "稆", "Pinyin_Xie": "lǚ", "Âm Hán Việt_Xie": "lữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ lúa tự mọc hoặc tính từ bổ nghĩa cho cây trồng hoang dại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('駳', '{"9000": "7747.0", "Chữ Trung Quốc": "駳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 16 | nét | 馬 | mã | biểu nghĩa | ngựa | 單 | đơn | biểu âm | đơn, một mình | 駳 gồm 馬 (Mã, biểu nghĩa: ngựa) và 單 (Đơn, biểu âm, đọc gần dàn); chữ hình thanh suy đoán. Chỉ giống ngựa hoặc màu sắc ngựa cụ thể trong cổ thư.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạm\": con ngựa (馬) \"đơn\" (單) sắc — ngựa một màu, đơn thuần. | Gương Hán-Việt | đạm — ít dùng độc lập; nhóm chữ mã hiếm trong từ điển cổ | Mở khoá kiến thức | Biết 駳 giúp nhận biết nhóm chữ Mã chuyên chỉ giống ngựa trong cổ điển.", "Tự nguyên_Xie": "Không có nguồn Wiktionary phân tích glyph. Bộ 馬 xác nhận liên quan đến ngựa. Chữ cực hiếm trong từ điển, có thể chỉ một giống ngựa cụ thể hoặc tính chất của ngựa trong cổ văn Trung Quốc; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "駳", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 延", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬延", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "延", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "駳", "Unihan_Traditional (Chữ Phồn thể)": "駳", "Pinyin_Xie": "dàn", "Âm Hán Việt_Xie": "đạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ miêu tả tư thế chạy nhanh của loài ngựa. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('騽', '{"9000": "7748.0", "Chữ Trung Quốc": "騽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 21 | nét | 馬 | mã | biểu nghĩa | ngựa | 習 | tập | biểu âm | tập luyện, quen thuộc | 騽 gồm 馬 (Mã, biểu nghĩa: ngựa) và 習 (Tập, biểu âm, đọc gần xí); chữ hình thanh. Chỉ loại ngựa đen lưng vàng (black horse with yellow back).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tập\": con ngựa (馬) \"tập\" luyện — ngựa đen lưng vàng quen thuộc với chiến trường. | Gương Hán-Việt | tập — ít dùng độc lập; chỉ giống ngựa đặc biệt trong cổ điển | Mở khoá kiến thức | Biết 騽 giúp đọc cổ điển quân sự và thi ca mô tả ngựa chiến đặc biệt.", "Tự nguyên_Xie": "Wiktionary xác nhận: 騽 (obsolete standard form) chỉ con ngựa đen có lưng màu vàng. Bộ 馬 xác nhận liên quan đến ngựa. Là chữ cổ chỉ màu sắc giống ngựa đặc biệt. Âm Middle Chinese và Old Chinese còn ghi chép. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "súng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 習", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬習", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "習", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "騽", "Unihan_Traditional (Chữ Phồn thể)": "騽", "Pinyin_Xie": "xí", "Âm Hán Việt_Xie": "tập", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một giống ngựa có màu sắc lông đặc biệt thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骍', '{"9000": "7749.0", "Chữ Trung Quốc": "骍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 10 | nét | 馬 | mã | biểu nghĩa | ngựa | 幸 | hạnh | biểu âm | may mắn, hạnh phúc | 骍 gồm 馬 (Mã, biểu nghĩa: ngựa) và 幸 (Hạnh, biểu âm, đọc gần xīng); chữ hình thanh. Nghĩa: ngựa lông đỏ; cũng chỉ màu đỏ nói chung (literary).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tinh\": con ngựa (馬) \"hạnh\" (幸) may — ngựa đỏ được chọn cho tế lễ, màu may mắn. | Gương Hán-Việt | tinh — trong \"骍旄\" (tinh mao): cờ đỏ; ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 骍 giúp đọc cổ điển lễ nghi và chiến trận mô tả ngựa đỏ trong tế lễ.", "Tự nguyên_Xie": "Lưu thư thông (chữ tạo muộn) | Wiktionary xác nhận: 骍 (literary) có nghĩa là ngựa đỏ và màu đỏ. Bộ 馬 xác nhận liên quan đến ngựa. Chữ dùng trong văn ngôn mô tả ngựa chiến màu đỏ hồng cao quý. Lưu thư thông (Liushutong) còn lưu dạng cổ. Hay dùng trong tổ hợp 騂剛, 騂旄. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa lông đỏ", "Hạng Tần Suất (Jun Da)": "7749.0", "Tần Suất % (Jun Da)": "99.9989576444", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 辛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马辛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骍", "Unihan_Traditional (Chữ Phồn thể)": "騂", "Pinyin_Xie": "xīng", "Âm Hán Việt_Xie": "tuynh, tinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm tính từ chỉ sắc đỏ của lông thú hoặc danh từ chỉ con ngựa đỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筻', '{"9000": "7750.0", "Chữ Trung Quốc": "筻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 13 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 岡 | cương | biểu âm | sườn núi, đồi | 筻 gồm 竹 (Trúc, biểu nghĩa: tre) và 岡 (Cương, biểu âm, đọc gần gàng); chữ hình thanh suy đoán. Chuyên dùng cho địa danh 筻口 (Gǎngkǒu) tại Hồ Nam.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cương\": bụi trúc (竹) trên \"cương\" đồi — địa danh nơi có nhiều tre trên sườn núi. | Gương Hán-Việt | cương — ít dùng độc lập; chỉ địa danh 筻口 ở Hồ Nam | Mở khoá kiến thức | Biết 筻 giúp nhận ra địa danh 筻口 trong bản đồ và địa chí tỉnh Hồ Nam.", "Tự nguyên_Xie": "Không có nguồn Wiktionary phân tích glyph. Bộ 竹 gợi liên quan đến tre. 筻 là chữ chuyên dùng cho địa danh 筻口 (Gangkou), một địa danh ở tỉnh Hồ Nam, Trung Quốc. Chữ tạo muộn; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Cánh Khẩu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 更", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮更", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "更", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筻", "Unihan_Traditional (Chữ Phồn thể)": "筻", "Pinyin_Xie": "gàng", "Âm Hán Việt_Xie": "cống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ dụng cụ bằng tre hoặc dùng trong địa danh Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魱', '{"9000": "7751.0", "Chữ Trung Quốc": "魱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 魚 | ngư | biểu nghĩa | cá | 夸 | khoa | biểu âm | khoe khoang, phóng đại | 魱 gồm 魚 (Ngư, biểu nghĩa: cá) và 夸 (Khoa, biểu âm, đọc gần hú); chữ hình thanh. Chỉ loài cá 當魱 (Reeve''s shad, Tenualosa reevesii).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồ\": con cá (魚) \"khoa\" trương — loài cá nổi tiếng trong ẩm thực cổ đại. | Gương Hán-Việt | hồ — ít dùng trong tiếng Việt; tên loài cá trong sinh học cổ điển | Mở khoá kiến thức | Biết 魱 giúp đọc tài liệu ngư nghiệp và sinh vật học cổ điển Trung Hoa.", "Tự nguyên_Xie": "Wiktionary xác nhận: 魱 chỉ dùng trong 當魱, tên loài cá Tenualosa reevesii (cá tế hay cá manh Trung Quốc). Bộ 魚 xác nhận đây là tên cá. Chữ chuyên dùng cho danh pháp sinh học cổ điển. Âm Middle và Old Chinese còn ghi chép. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chí", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 互", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚互", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "互", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "魱", "Unihan_Traditional (Chữ Phồn thể)": "魱", "Pinyin_Xie": "hú", "Âm Hán Việt_Xie": "hồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cá sông theo cách gọi cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舣', '{"9000": "7752.0", "Chữ Trung Quốc": "舣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 9 | nét | 舟 | chu | biểu nghĩa | thuyền, tàu | 义 | nghĩa | biểu âm | nghĩa, công bằng | 舣 gồm 舟 (Chu, biểu nghĩa: thuyền) và 义 (Nghĩa, biểu âm, đọc gần yǐ); chữ hình thanh. Nghĩa: cập thuyền vào bờ, neo đậu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghĩa\": con thuyền (舟) ghé \"nghĩa\" — thuyền cập bến như người tìm chỗ neo đúng nghĩa. | Gương Hán-Việt | nghĩa — ít dùng độc lập; trong thơ mô tả thuyền cập bờ | Mở khoá kiến thức | Biết 舣 giúp đọc thơ cổ điển mô tả cảnh sông hồ và thuyền bè.", "Tự nguyên_Xie": "Không có nguồn Wiktionary phân tích glyph. Bộ 舟 (thuyền) xác nhận nghĩa liên quan đến thuyền bè. 舣 mô tả hành động đưa thuyền sát bờ để neo đậu hoặc lên bờ. Chữ hay gặp trong thơ văn mô tả cảnh sông nước; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuyền ghé vào bờ, đậu thuyền", "Hạng Tần Suất (Jun Da)": "7752.0", "Tần Suất % (Jun Da)": "99.9989607451", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 义", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟义", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "义", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "舣", "Unihan_Traditional (Chữ Phồn thể)": "艤", "Pinyin_Xie": "yǐ", "Âm Hán Việt_Xie": "nghĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động điều khiển thuyền cập bến. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鮾', '{"9000": "7753.0", "Chữ Trung Quốc": "鮾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 18 | nét | 魚 | ngư | biểu nghĩa | cá | 內 | nội | biểu âm | bên trong | 鮾 gồm 魚 (Ngư, biểu nghĩa: cá) và 內 (Nội, biểu âm, đọc gần něi); chữ hình thanh. Nghĩa: cá thối, cá ươn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nội\": cá (魚) \"nội\" bộ hỏng — cá thối từ bên trong, mùi hôi thấm vào lõi. | Gương Hán-Việt | nội — ít dùng trong tiếng Việt; dạng cổ của 餒 (cá ươn) | Mở khoá kiến thức | Biết 鮾 giúp đọc cổ văn ẩm thực và vệ sinh thực phẩm thời cổ đại.", "Tự nguyên_Xie": "Wiktionary xác nhận: 鮾 (obsolete) nghĩa là cá thối, cá ươn. Bộ 魚 xác nhận liên quan đến cá. 鮾 là dạng cổ, hiện đại dùng 餒 (něi, đói/cá thối). Âm Middle Chinese và Old Chinese còn ghi chép. Dạng thay thế gồm 脮, 餒. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鮾", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 妥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚妥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "妥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鮾", "Unihan_Traditional (Chữ Phồn thể)": "鮾", "Pinyin_Xie": "něi", "Âm Hán Việt_Xie": "nội", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ chỉ cá ươn hoặc tính từ mô tả trạng thái cá bị ươn thối. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鯋', '{"9000": "7754.0", "Chữ Trung Quốc": "鯋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 18 | nét | 魚 | ngư | biểu nghĩa | cá | 沙 | sa | biểu âm | cát, cát vàng | 鯋 gồm 魚 (Ngư, biểu nghĩa: cá) và 沙 (Sa, biểu âm, đọc gần shā); chữ hình thanh suy đoán. Nghĩa không rõ trong từ điển hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sa\": con cá (魚) ở bãi \"sa\" cát — loài cá sống ở vùng nước nông cát vàng. | Gương Hán-Việt | sa — ít dùng độc lập; nhóm chữ ngư hiếm trong từ điển cổ | Mở khoá kiến thức | Biết 鯋 giúp nhận biết nhóm chữ Ngư chuyên dùng trong danh pháp cá cổ điển.", "Tự nguyên_Xie": "Không có nguồn Wiktionary phân tích glyph. Bộ 魚 xác nhận liên quan đến cá. Chữ cực hiếm, có thể chỉ một loài cá cụ thể trong cổ thư Trung Quốc; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鯋", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 沙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚沙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "沙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鯋", "Unihan_Traditional (Chữ Phồn thể)": "鯋", "Pinyin_Xie": "shā", "Âm Hán Việt_Xie": "sa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò làm danh từ để chỉ các loài cá mập hoặc cá nhám. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鯏', '{"9000": "7755.0", "Chữ Trung Quốc": "鯏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 18 | nét | 魚 | ngư | biểu nghĩa | cá | 利 | lợi | biểu âm | lợi ích, sắc bén | 鯏 gồm 魚 (Ngư, biểu nghĩa: cá) và 利 (Lợi, biểu âm, đọc gần lí); chữ hình thanh. Chỉ một loài cá cụ thể trong cổ thư.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lợi\": con cá (魚) \"lợi\" — loài cá nhanh nhẹn, có ích trong ẩm thực cổ. | Gương Hán-Việt | lợi — ít dùng độc lập; tên cá trong từ điển cổ | Mở khoá kiến thức | Biết 鯏 giúp nhận biết nhóm chữ Ngư chuyên dùng trong danh pháp cá cổ.", "Tự nguyên_Xie": "Không có nguồn Wiktionary phân tích glyph. Bộ 魚 xác nhận đây là tên cá. Chữ cực hiếm, nghĩa còn tranh luận trong học giới; chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sắc lệnh của triều đình", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "穌 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰穌刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "穌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "鯏", "Unihan_Traditional (Chữ Phồn thể)": "鯏", "Pinyin_Xie": "li", "Âm Hán Việt_Xie": "lợi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ để gọi tên một loài cá bống nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶃', '{"9000": "7756.0", "Chữ Trung Quốc": "鶃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 19 | nét | 鳥 | điểu | biểu nghĩa | chim | 益 | ích | biểu âm | ích lợi, thêm | 鶃 gồm 鳥 (Điểu, biểu nghĩa: chim) và 益 (Ích, biểu âm, đọc gần yì); chữ hình thanh suy đoán. Chỉ loài chim cụ thể trong cổ thư.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ích\": con chim (鳥) \"ích\" — loài chim có ích, chim lành trong cổ điển. | Gương Hán-Việt | ích — ít dùng độc lập; tên chim trong từ điển cổ | Mở khoá kiến thức | Biết 鶃 giúp nhận biết nhóm chữ Điểu chuyên dùng trong danh pháp chim cổ.", "Tự nguyên_Xie": "Không có nguồn Wiktionary phân tích glyph. Bộ 鳥 xác nhận đây là tên chim. Chữ cực hiếm, nghĩa không rõ trong từ điển hiện đại; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "郃", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鳥 + 兒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鳥兒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鶃", "Unihan_Traditional (Chữ Phồn thể)": "鶃", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này được dùng làm danh từ để chỉ một loài chim nước cổ xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶫', '{"9000": "7757.0", "Chữ Trung Quốc": "鶫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 20 | nét | 鳥 | điểu | biểu nghĩa | chim | 東 | đông | biểu âm | phương đông | 鶫 gồm 鳥 (Điểu, biểu nghĩa: chim) và 東 (Đông, biểu âm, đọc gần dōng); chữ hình thanh. Là dạng đơn giản hoá của 鶇, chỉ chim hét (thrush).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đông\": chim (鳥) \"đông\" phương — chim hét mùa đông, hót vang khi trời lạnh. | Gương Hán-Việt | đông — ít dùng trong tiếng Việt; tên chim trong văn bản Nhật-Hán | Mở khoá kiến thức | Biết 鶫 giúp đọc tài liệu điểu học Nhật Bản và sinh vật học cổ điển Đông Á.", "Tự nguyên_Xie": "Wiktionary xác nhận: 鶫 là chữ kokoji (国字) của Nhật Bản, phát triển như dạng giản lược của 鶇 (truyền thống). Chữ chỉ chim hét (thrush) trong tiếng Nhật; được dùng trong phân loại sinh học. Bộ 鳥 xác nhận đây là tên chim. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鶫", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "柬 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰柬鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "柬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鶫", "Unihan_Traditional (Chữ Phồn thể)": "鶫", "Pinyin_Xie": "dong", "Âm Hán Việt_Xie": "đông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ loài chim hoét trong phân loại học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齛', '{"9000": "7758.0", "Chữ Trung Quốc": "齛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 20 | nét | 齛 | tiết | tượng hình | nhai lại, nghiền thức ăn (tự thể độc lập thuộc bộ Xỉ) | 齛 là chữ thuộc bộ Xỉ (齒 — răng). Wiktionary chỉ ghi {{Han etym}} mà không cung cấp cấu trúc hình thanh/hội ý rõ ràng; chưa có nguồn học thuật xác nhận. Chữ mô tả hành động nhai lại thức ăn, liên quan đến răng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiết\": chữ bộ Răng (齒) — hình ảnh con bò đứng nhai lại thức ăn, hàm răng chuyển động đều đặn. | Gương Hán-Việt | tiết — ít dùng trong từ ghép Hán-Việt thông dụng | Mở khoá kiến thức | Biết 齛 giúp nhận ra nhóm chữ bộ 齒 chỉ hoạt động của răng miệng như 齧 (gặm), 齡 (tuổi/răng).", "Tự nguyên_Xie": "Wiktionary chỉ ghi nhãn {{Han etym}} mà không phân tích cấu trúc. Nghĩa gốc: nhai lại, nghiền thức ăn (to ruminate, chew the cud). Chữ thuộc bộ Xỉ (齒, răng), gợi ý liên quan hoạt động của miệng/răng. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "齛", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "齒 + 世", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齒世", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "世", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齒", "Unihan_Simplified (Chữ Giản thể)": "齛", "Unihan_Traditional (Chữ Phồn thể)": "齛", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "tiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành vi nhai lại thức ăn của các loài động vật ăn cỏ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矙', '{"9000": "7759.0", "Chữ Trung Quốc": "矙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 24 | nét | 矙 | khám | tượng hình | nhòm, rình xem (tự thể độc lập thuộc bộ Mục) | 矙 thuộc bộ Mục (目 — mắt), với 24 nét. Không có dữ liệu cấu trúc hình thanh/hội ý từ Wiktionary. Nghĩa \"nhòm, rình xem\" gợi liên quan trực tiếp đến bộ mắt. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khám\": bộ Mắt (目) to lớn — hình ảnh đôi mắt thật to đang rình nhìn qua khe cửa hẹp. | Gương Hán-Việt | khám — như trong \"khám phá\" (khám phá), \"khám xét\" | Mở khoá kiến thức | Biết 矙 giúp liên kết nhóm chữ bộ 目 chỉ hoạt động nhìn như 看 (khán), 觀 (quan), 覽 (lãm).", "Tự nguyên_Xie": "Không có anchor Wiktionary cho 矙. Chữ thuộc bộ Mục (目, mắt), nghĩa là nhòm ngó, rình xem. Cấu tạo chính xác chưa được xác nhận bởi nguồn học thuật. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhòm, rình xem", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "矙", "Unihan_Traditional (Chữ Phồn thể)": "矙", "Pinyin_Xie": "kàn", "Âm Hán Việt_Xie": "khám", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện hành động nhìn lén hoặc rình rập quan sát. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絾', '{"9000": "7760.0", "Chữ Trung Quốc": "絾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 絾 | thừa | tượng hình | dây thừng, dây buộc (tự thể độc lập thuộc bộ Mịch) | 絾 thuộc bộ Mịch (糸 — sợi, tơ), với 12 nét. Không có dữ liệu cấu trúc hình thanh/hội ý từ Wiktionary. Nghĩa liên quan đến sợi/dây, phù hợp với bộ thủ Mịch. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thừa\": bộ Mịch (糸, sợi) — hình ảnh những sợi tơ được xe lại thành dây thừng, nối tiếp nhau. | Gương Hán-Việt | thừa — như trong \"dư thừa\", \"thừa kế\", \"thừa nhận\" | Mở khoá kiến thức | Biết 絾 giúp nhận ra nhóm chữ bộ 糸 liên quan sợi, dệt như 經 (kinh), 紡 (phưởng), 繩 (thằng).", "Tự nguyên_Xie": "Không có anchor Wiktionary cho 絾. Chữ thuộc bộ Mịch (糸, sợi), nghĩa liên quan đến dây, sợi dệt. Pinyin chéng. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "絵", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 成", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹成", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "成", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "絾", "Unihan_Traditional (Chữ Phồn thể)": "絾", "Pinyin_Xie": "chéng", "Âm Hán Việt_Xie": "thừa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này có thể dùng làm danh từ chỉ sợi dây hoặc động từ chỉ việc may vá, hoàn thành. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袗', '{"9000": "7761.0", "Chữ Trung Quốc": "袗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袗 | chẩn | tượng hình | áo đơn, áo không lót (tự thể thuộc bộ Y) | 袗 thuộc bộ Y (衣 — áo, quần áo). Wiktionary chỉ ghi {{Han etym}} mà không phân tích cấu trúc chi tiết. Nghĩa \"áo đơn\" (áo không lót) phù hợp với bộ thủ Y. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chẩn\": bộ Y (衣, áo) — hình ảnh chiếc áo mỏng một lớp, không có vải lót bên trong, dùng vào mùa hè. | Gương Hán-Việt | chẩn — ít xuất hiện trong từ ghép Hán-Việt thông dụng hiện đại | Mở khoá kiến thức | Biết 袗 giúp nhận ra nhóm chữ bộ 衣 chỉ trang phục như 裙 (quần), 裳 (thường), 襦 (nhu).", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} nhưng không cung cấp cấu trúc rõ ràng cho 袗. Nghĩa gốc: áo đơn, áo một lớp không lót. Chữ thuộc bộ Y (衣, áo), gợi ý liên quan trực tiếp đến trang phục. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo đơn", "Hạng Tần Suất (Jun Da)": "7761.0", "Tần Suất % (Jun Da)": "99.9989700472", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 㐱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤㐱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袗", "Unihan_Traditional (Chữ Phồn thể)": "袗", "Pinyin_Xie": "zhěn", "Âm Hán Việt_Xie": "chân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ loại áo đơn hoặc tính từ chỉ sự đơn chiếc, có hoa văn vẽ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('襬', '{"9000": "7762.0", "Chữ Trung Quốc": "襬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 20 | nét | 襬 | bãi | tượng hình | gấu áo, viền dưới của áo (bộ Y) | 襬 thuộc bộ Y (衣 — áo, quần áo), với 20 nét. Wiktionary ghi {{Han etym}} nhưng không cung cấp phân tích cấu trúc hình thanh/hội ý. Nghĩa \"gấu áo, viền dưới\" phù hợp với bộ Y. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bãi\": bộ Y (衣, áo) — hình ảnh gấu áo dài đung đưa (bãi) khi người mặc bước đi, phần cuối tà áo. | Gương Hán-Việt | bãi — ít xuất hiện trong từ ghép Hán-Việt thông dụng hiện đại | Mở khoá kiến thức | Biết 襬 giúp nhận ra nhóm chữ bộ 衣 chỉ các phần của trang phục như 袖 (tụ/tay áo), 領 (lĩnh/cổ áo), 裾 (cư/vạt áo).", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} cho 襬 nhưng không phân tích cấu trúc. Nghĩa: gấu áo (hem), phần viền dưới của trang phục. Chữ thuộc bộ Y (衣, áo). Định nghĩa trong Wiktionary: hem at the bottom of a garment. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con lắc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 罷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤罷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "罷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "䙓", "Unihan_Traditional (Chữ Phồn thể)": "襬", "Pinyin_Xie": "bǎi", "Âm Hán Việt_Xie": "bãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ phần vạt áo hoặc gấu váy của trang phục. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('漤', '{"9000": "7763.0", "Chữ Trung Quốc": "漤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 氵 | thủy | biểu nghĩa | nước | 婪 | lam | biểu âm | tham lam (cho âm) | 漤 = 氵(Thủy, biểu nghĩa: nước) + 婪 (Lam, biểu âm); chữ hình thanh. Phần 氵cho biết nghĩa liên quan đến nước/chất lỏng; phần 婪 cho âm đọc lǎn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lãm\": nước (氵) + 婪 (lam, tham) — hình ảnh ngâm thực phẩm trong nước muối, \"tham\" hút hết vị chát ra ngoài. | Gương Hán-Việt | lãm — ít dùng trong từ ghép Hán-Việt thông dụng hiện đại; liên quan \"lãm\" trong \"du lãm\" (游覽) | Mở khoá kiến thức | Biết 漤 giúp nhận ra nhóm chữ bộ 氵chỉ quy trình chế biến bằng chất lỏng như 漬 (tí/ngâm), 浸 (tẩm/ngâm), 醃 (yêm/muối).", "Tự nguyên_Xie": "Wiktionary phân tích: 漤 là chữ hình thanh (psc) gồm 氵(tam thủy, biểu nghĩa: nước) + 婪 (biểu âm). Nghĩa: ngâm thực phẩm trong nước muối hoặc gia vị (làm gỏi, nộm); ngâm vôi để khử chát. Phần 氵chỉ rõ quy trình có liên quan đến chất lỏng/nước. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nộm; gỏi (trộn muối hoặc các gia vị khác như gỏi cá, gỏi thịt, gỏi rau sống); ngâm; ngâm vôi (ngâm trong nước nóng hoặc nước vôi cho hết chát)", "Hạng Tần Suất (Jun Da)": "7763.0", "Tần Suất % (Jun Da)": "99.9989721144", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 婪", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵婪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "婪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "漤", "Unihan_Traditional (Chữ Phồn thể)": "漤", "Pinyin_Xie": "lǎn", "Âm Hán Việt_Xie": "lạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc ngâm quả cho bớt chát hoặc làm danh từ chỉ món nộm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬐', '{"9000": "7764.0", "Chữ Trung Quốc": "鬐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 20 | nét | 鬐 | kỳ | tượng hình | bờm, vây (tự thể độc lập thuộc bộ Tư) | 鬐 thuộc bộ 髟 (tóc dài rủ xuống), với 20 nét. Không có dữ liệu Wiktionary. Nghĩa \"bờm ngựa\" phù hợp với bộ 髟 (tóc/lông dài). Chưa có nguồn học thuật xác nhận cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": bộ 髟 (tóc/lông dài) — hình ảnh bờm ngựa phất phơ (kỳ diệu) theo gió khi ngựa phi nước đại. | Gương Hán-Việt | kỳ — như trong \"kỳ lân\" (麒麟, con vật có bờm), \"kỳ dị\" | Mở khoá kiến thức | Biết 鬐 giúp nhận ra nhóm chữ bộ 髟 chỉ tóc/lông như 髮 (phát/tóc), 髯 (nhiêm/râu), 鬃 (tung/lông gáy).", "Tự nguyên_Xie": "Không có anchor Wiktionary cho 鬐. Chữ thuộc bộ 髟 (tóc dài), nghĩa là bờm (ngựa) hoặc vây lưng (cá). Pinyin qí. Nghĩa liên quan đến phần lông/tóc mọc dựng lên trên cơ thể động vật. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bờm ngựa", "Hạng Tần Suất (Jun Da)": "7764.0", "Tần Suất % (Jun Da)": "99.9989741815", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 耆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟耆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "鬐", "Unihan_Traditional (Chữ Phồn thể)": "鬐", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bờm của ngựa hoặc vây trên lưng cá trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲾', '{"9000": "7765.0", "Chữ Trung Quốc": "鲾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 魚 | ngư | biểu nghĩa | cá | 畐 | bức | biểu âm | (cho âm bī) | 鲾 = 魚 (Ngư, biểu nghĩa: cá) + 畐 (Bức, biểu âm); chữ hình thanh. Phần 魚 chỉ rõ đây là tên một loại cá; phần 畐 cho âm đọc bī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bức\": cá (魚) + 畐 (âm) — hình ảnh con cá đồng tiền tròn dẹt, nom như đồng tiền xu, bơi trong làn nước. | Gương Hán-Việt | bức — ít dùng trong từ ghép Hán-Việt thông dụng; \"bức\" gợi \"bức tranh\", \"áp bức\" | Mở khoá kiến thức | Biết 鲾 giúp nhận ra nhóm chữ bộ 魚 chỉ các loài cá như 鯉 (lý/cá chép), 鮭 (khuê/cá hồi), 鯊 (sa/cá mập).", "Tự nguyên_Xie": "Wiktionary phân tích: 鲾 là chữ hình thanh (psc) gồm 魚 (ngư, biểu nghĩa: cá) + 畐 (biểu âm). Nghĩa: cá đồng tiền (ponyfish), họ Leiognathidae — loài cá biển nhỏ, thân dẹt hình bầu dục, phổ biến ở vùng biển nhiệt đới Đông Nam Á. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá đồng tiền", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 畐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼畐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲾", "Unihan_Traditional (Chữ Phồn thể)": "鲾", "Pinyin_Xie": "bī", "Âm Hán Việt_Xie": "bì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một họ cá biển nhỏ thân dẹt thường gặp ở vùng duyên hải. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴾', '{"9000": "7766.0", "Chữ Trung Quốc": "鴾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 17 | nét | 鴾 | mưu | tượng hình | tên chim cổ (tự thể thuộc bộ Điểu) | 鴾 thuộc bộ Điểu (鳥 — chim), với 17 nét. Wiktionary chỉ ghi {{Han etym}} mà không phân tích cấu trúc. Nghĩa chỉ một loài chim cổ (鴾母, 鴾鷡). Chưa có nguồn học thuật xác nhận cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mưu\": bộ Điểu (鳥, chim) — hình ảnh con chim tiếng kêu \"mưu mưu\", tên gợi thanh. | Gương Hán-Việt | mưu — như trong \"mưu kế\", \"mưu lược\"; chữ 鴾 ít xuất hiện trong văn bản hiện đại | Mở khoá kiến thức | Biết 鴾 giúp nhận ra nhóm chữ bộ 鳥 chỉ các loài chim như 鴻 (hồng/thiên nga), 鷹 (ưng), 鶴 (hạc).", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} cho 鴾, chỉ dùng trong từ ghép cổ 鴾母 và 鴾鷡 (tên loài chim). Pinyin móu. Chữ thuộc bộ Điểu (鳥, chim). Chưa có phân tích cấu tạo chi tiết từ nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鴴", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "牟 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰牟鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "牟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鴾", "Unihan_Traditional (Chữ Phồn thể)": "鴾", "Pinyin_Xie": "móu", "Âm Hán Việt_Xie": "mưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim nước tương tự như chim choi choi trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稭', '{"9000": "7767.0", "Chữ Trung Quốc": "稭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 14 | nét | 稭 | giai | tượng hình | rơm (lúa đã tuốt hết hạt), biến thể của 秸 (bộ Hòa) | 稭 là biến thể/dị thể của chữ 秸, thuộc bộ Hòa (禾 — lúa), với 14 nét. Wiktionary ghi {{zh-see|秸|v}} — nghĩa là 稭 là cách viết cũ của 秸. Cả hai chỉ rơm rạ sau khi lúa đã gặt. Chưa có nguồn học thuật riêng biệt cho 稭.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giai\": bộ Hòa (禾, lúa) — hình ảnh bó rơm vàng sau mùa gặt, thân lúa khô cứng còn lại trên đồng. | Gương Hán-Việt | giai — ít dùng trong từ ghép Hán-Việt hiện đại; 秸 thông dụng hơn | Mở khoá kiến thức | Biết 稭 giúp nhận ra nhóm chữ bộ 禾 liên quan lúa thóc như 稻 (đạo/lúa), 稷 (tắc/kê), 穗 (tuệ/bông lúa).", "Tự nguyên_Xie": "Wiktionary xác nhận 稭 là dị thể (variant form) của 秸. Chữ thuộc bộ Hòa (禾, lúa). Nghĩa gốc: rơm, thân cây lúa hoặc mạch sau khi đã tuốt hết hạt. Đọc là giai hoặc kiết (cũng đọc là \"giải\"). Chữ đơn giản hơn là 秸. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giai; như \"mạch giai (rơm)\" \n (Danh) Rơm (lúa đã tuốt hết hạt). \n§ Cũng đọc là kiết. Cũng như kiết 秸.", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 皆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾皆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稭", "Unihan_Traditional (Chữ Phồn thể)": "稭", "Pinyin_Xie": "jiē", "Âm Hán Việt_Xie": "giai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần thân cây lúa hoặc hoa màu sau khi đã tuốt hết hạt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籄', '{"9000": "7768.0", "Chữ Trung Quốc": "籄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 20 | nét | 籄 | quỹ | tượng hình | giỏ tre, hộp tre (tự thể thuộc bộ Trúc) | 籄 thuộc bộ Trúc (竹 — tre), với 20 nét. Không có dữ liệu Wiktionary. Nghĩa liên quan đến đồ vật làm bằng tre. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỹ\": bộ Trúc (竹, tre) — hình ảnh chiếc giỏ tre đan khéo léo, dùng đựng đồ vật trong gia đình. | Gương Hán-Việt | quỹ — như trong \"quỹ đạo\", \"quỹ tích\"; chữ 籄 ít dùng trong văn bản hiện đại | Mở khoá kiến thức | Biết 籄 giúp nhận ra nhóm chữ bộ 竹 chỉ đồ vật tre như 籠 (lung/lồng), 筐 (khuông/thúng), 箱 (sương/hộp).", "Tự nguyên_Xie": "Không có anchor Wiktionary cho 籄. Chữ thuộc bộ Trúc (竹, tre). Pinyin kuì. Nghĩa liên quan đến đồ đan từ tre. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "焄", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "籄", "Unihan_Traditional (Chữ Phồn thể)": "籄", "Pinyin_Xie": "kuì", "Âm Hán Việt_Xie": "quỹ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại sọt đan bằng tre dùng để vận chuyển đất đá thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聺', '{"9000": "7769.0", "Chữ Trung Quốc": "聺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 20 | nét | 聺 | khai | tượng hình | nghe rõ, tai thính (tự thể thuộc bộ Nhĩ) | 聺 thuộc bộ Nhĩ (耳 — tai), với 20 nét. Không có dữ liệu Wiktionary. Nghĩa liên quan đến tai/thính giác. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khai\": bộ Nhĩ (耳, tai) — hình ảnh tai lắng nghe, \"khai\" gợi mở ra, đón nhận âm thanh. | Gương Hán-Việt | khai — như trong \"khai mạc\", \"khai thông\"; chữ 聺 ít xuất hiện trong văn bản hiện đại | Mở khoá kiến thức | Biết 聺 giúp nhận ra nhóm chữ bộ 耳 liên quan tai nghe như 聽 (thính/nghe), 聰 (thông/thính tai), 聞 (văn/nghe).", "Tự nguyên_Xie": "Không có anchor Wiktionary cho 聺. Chữ thuộc bộ Nhĩ (耳, tai), pinyin qié. Nghĩa chưa được xác nhận rõ ràng từ nguồn học thuật. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Kai", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 察", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳察", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "察", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聺", "Unihan_Traditional (Chữ Phồn thể)": "聺", "Pinyin_Xie": "qié", "Âm Hán Việt_Xie": "khai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ mô tả trạng thái thính lực kém hoặc tai bị điếc nhẹ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褹', '{"9000": "7770.0", "Chữ Trung Quốc": "褹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 16 | nét | 褹 | nghệ | tượng hình | áo ngắn, áo khoác ngắn (bộ Y) | 褹 thuộc bộ Y (衣 — áo, quần áo), với 16 nét. Wiktionary ghi {{Han etym}} và cho biết chữ có hai cách đọc: yì (áo ngắn, chỉ dùng trong từ 筩褹) và niè. Chưa có phân tích cấu trúc hình thanh/hội ý rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghệ\": bộ Y (衣, áo) — hình ảnh chiếc áo khoác ngắn dùng khi làm nghề (nghệ), tiện lợi và gọn gàng. | Gương Hán-Việt | nghệ — như trong \"nghệ thuật\", \"kỹ nghệ\"; chữ 褹 ít xuất hiện trong văn bản hiện đại | Mở khoá kiến thức | Biết 褹 giúp nhận ra nhóm chữ bộ 衣 chỉ các loại áo như 袍 (bào/áo dài), 衫 (sam/áo), 裘 (cầu/áo lông).", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} cho 褹. Chữ dùng trong từ ghép 筩褹 (áo khoác ngắn). Hai đọc âm: yì và niè. Thuộc bộ Y (衣, áo). Chưa có phân tích cấu tạo chi tiết từ nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "褹", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 埶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤埶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "埶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褹", "Unihan_Traditional (Chữ Phồn thể)": "褹", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "nghệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần tay áo hoặc vạt áo của trang phục cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鏕', '{"9000": "7771.0", "Chữ Trung Quốc": "鏕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 19 | nét | 鏕 | lục | tượng hình | lưỡi hái, liềm (bộ Kim) | 鏕 thuộc bộ Kim (金 — kim loại), với 19 nét. Wiktionary chỉ ghi {{Han etym}} mà không phân tích cấu trúc. Nghĩa liên quan đến công cụ/nông cụ bằng kim loại. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lục\": bộ Kim (金, kim loại) — hình ảnh lưỡi dao kim loại sáng bóng, ánh lên màu lục biếc khi gặp ánh nắng. | Gương Hán-Việt | lục — như trong \"lục địa\", \"lục sắc\" (màu xanh lá); chữ 鏕 ít dùng trong văn bản hiện đại | Mở khoá kiến thức | Biết 鏕 giúp nhận ra nhóm chữ bộ 金 chỉ nông cụ/vũ khí kim loại như 鐮 (liêm/lưỡi hái), 鋤 (sừ/cuốc), 鏟 (sản/xẻng).", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} cho 鏕 mà không cung cấp cấu trúc. Pinyin lù, nghĩa liên quan đến liềm, lưỡi hái hoặc công cụ nông nghiệp bằng kim loại. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "镰", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 鹿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金鹿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鹿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鏕", "Unihan_Traditional (Chữ Phồn thể)": "鏕", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại nông cụ bằng sắt dùng để cắt cỏ hoặc gặt lúa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齆', '{"9000": "7772.0", "Chữ Trung Quốc": "齆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼻 | Số nét | 24 | nét | 齆 | úng | tượng hình | ngạt mũi, mũi bị tắc (bộ Tỵ) | 齆 thuộc bộ Tỵ (鼻 — mũi), với 24 nét. Wiktionary ghi {{Han etym}} và định nghĩa là \"mũi bị tắc\" (stuffy nose). Không có phân tích cấu trúc hình thanh/hội ý chi tiết. Nghĩa gắn trực tiếp với bộ Tỵ (mũi).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"úng\": bộ Tỵ (鼻, mũi) — hình ảnh mũi bị úng tắc, tiếng nói ra nghe ong ong như tiếng \"úng úng\". | Gương Hán-Việt | úng — như trong \"úng nước\" (ngập nước), \"úng thủy\"; chữ 齆 ít xuất hiện trong văn bản hiện đại | Mở khoá kiến thức | Biết 齆 giúp nhận ra nhóm chữ bộ 鼻 liên quan mũi như 鼾 (hãn/ngáy), 嗅 (khứu/ngửi).", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} cho 齆. Nghĩa: mũi bị tắc (ngạt mũi), giọng nói bị ảnh hưởng do mũi bị tắc. Thuộc bộ Tỵ (鼻, mũi). Chưa có phân tích cấu tạo chi tiết từ nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngạt mũi", "Hạng Tần Suất (Jun Da)": "7772.0", "Tần Suất % (Jun Da)": "99.9989834836", "GavinGrover_Once (Chiết tự trực tiếp)": "鼻 + 邕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鼻邕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "邕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼻", "Unihan_Simplified (Chữ Giản thể)": "齆", "Unihan_Traditional (Chữ Phồn thể)": "齆", "Pinyin_Xie": "wèng", "Âm Hán Việt_Xie": "úng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ miêu tả trạng thái tắc mũi gây khó thở hoặc phát âm nghẹt giọng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盫', '{"9000": "7773.0", "Chữ Trung Quốc": "盫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 18 | nét | 盫 | am | tượng hình | hộp đựng thức ăn, tráp (bộ Mãnh) | 盫 thuộc bộ Mãnh (皿 — đồ đựng), với 18 nét. Không có dữ liệu Wiktionary. Nghĩa liên quan đến đồ vật dùng để đựng. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"am\": bộ Mãnh (皿, đồ đựng) — hình ảnh chiếc tráp nhỏ (am) bằng gỗ đựng đồ quý, nằm yên như \"am\" (chùa nhỏ yên tĩnh). | Gương Hán-Việt | am — như trong \"am tường\" (hiểu rõ), \"am hiểu\"; chữ 盫 ít dùng trong văn bản hiện đại | Mở khoá kiến thức | Biết 盫 giúp nhận ra nhóm chữ bộ 皿 chỉ đồ đựng như 盤 (bàn/mâm), 盆 (bồn), 盛 (thịnh/đựng đầy).", "Tự nguyên_Xie": "Không có anchor Wiktionary cho 盫. Chữ thuộc bộ Mãnh (皿, đồ đựng). Pinyin ān. Nghĩa liên quan đến hộp, tráp đựng đồ vật. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tiểu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "𨠭 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𨠭皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𨠭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盫", "Unihan_Traditional (Chữ Phồn thể)": "盫", "Pinyin_Xie": "ān", "Âm Hán Việt_Xie": "am", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ nắp đậy của đồ dùng hoặc làm động từ với nghĩa úp đậy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矎', '{"9000": "7774.0", "Chữ Trung Quốc": "矎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 19 | nét | 矎 | huyên | tượng hình | nhìn thẳng, mắt nhìn đăm đăm (bộ Mục) | 矎 thuộc bộ Mục (目 — mắt), với 19 nét. Wiktionary ghi {{Han etym}} nhưng không cung cấp cấu trúc hình thanh/hội ý. Nghĩa \"nhìn thẳng\" phù hợp bộ thủ Mục. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyên\": bộ Mục (目, mắt) — hình ảnh đôi mắt nhìn thẳng không chớp, ánh nhìn \"huyên náo\" tập trung. | Gương Hán-Việt | huyên — như trong \"huyên náo\", \"huyên thiên\" (nói nhiều); chữ 矎 ít xuất hiện trong văn bản hiện đại | Mở khoá kiến thức | Biết 矎 giúp nhận ra nhóm chữ bộ 目 chỉ hoạt động của mắt như 眺 (diễu/nhìn xa), 瞪 (đắng/trợn mắt), 盯 (đinh/nhìn chằm).", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} cho 矎. Pinyin xuān, dùng trong từ ghép 矎矎 (nhìn chằm chằm). Thuộc bộ Mục (目, mắt). Chưa có phân tích cấu tạo chi tiết từ nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhìn thẳng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 夐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目夐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "矎", "Unihan_Traditional (Chữ Phồn thể)": "矎", "Pinyin_Xie": "xuān", "Âm Hán Việt_Xie": "huyến, huýnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ miêu tả hành động nhìn chăm chú hoặc trợn mắt nhìn thẳng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礋', '{"9000": "7775.0", "Chữ Trung Quốc": "礋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 18 | nét | 礋 | trát | tượng hình | cái trục đá lăn, con lăn đá (bộ Thạch) | 礋 thuộc bộ Thạch (石 — đá), với 18 nét. Không có dữ liệu Wiktionary. Nghĩa liên quan đến công cụ làm bằng đá. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trát\": bộ Thạch (石, đá) — hình ảnh con lăn đá nặng nề lăn qua lăn lại, \"trát\" đất bằng phẳng. | Gương Hán-Việt | trát — như trong \"trát vữa\" (tô tường), \"trát nhựa\"; chữ 礋 ít dùng trong văn bản hiện đại | Mở khoá kiến thức | Biết 礋 giúp nhận ra nhóm chữ bộ 石 chỉ công cụ đá như 碾 (niễn/trục nghiền), 礫 (lịch/sỏi đá), 磨 (ma/cối xay).", "Tự nguyên_Xie": "Không có anchor Wiktionary cho 礋. Chữ thuộc bộ Thạch (石, đá). Pinyin zé. Nghĩa liên quan đến con lăn đá hoặc công cụ nghiền bằng đá. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "礋", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 睪", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石睪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "睪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礋", "Unihan_Traditional (Chữ Phồn thể)": "礋", "Pinyin_Xie": "zé", "Âm Hán Việt_Xie": "trát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ để chỉ một loại đá mài hoặc đá cứng trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窌', '{"9000": "7776.0", "Chữ Trung Quốc": "窌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 10 | nét | 窌 | liệu | tượng hình | hầm chứa thực phẩm, hố ngầm (bộ Huyệt) | 窌 thuộc bộ Huyệt (穴 — hang, hố), với 10 nét. Wiktionary ghi {{Han etym}} và cho biết nghĩa là \"hầm, hố chứa thực phẩm\" (cellar, pit for food storage). Không có phân tích hình thanh/hội ý chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liệu\": bộ Huyệt (穴, hang/hố) — hình ảnh hầm tối dưới lòng đất, nơi \"liệu\" (liệu lý, sắp đặt) thức ăn để bảo quản suốt mùa đông. | Gương Hán-Việt | liệu — như trong \"liệu lý\", \"liệu pháp\", \"tài liệu\"; chữ 窌 ít dùng trong văn bản hiện đại | Mở khoá kiến thức | Biết 窌 giúp nhận ra nhóm chữ bộ 穴 chỉ không gian hố/hang như 窖 (giáo/hầm chứa), 窟 (quật/hang động), 窑 (diêu/lò gốm).", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} cho 窌. Nghĩa: hầm ngầm, hố chứa thực phẩm (cellar, pit). Nhiều âm đọc: jiào, liáo, liù, pào. Thuộc bộ Huyệt (穴, hang/hố). Nghĩa liên quan đến không gian ngầm dưới đất. Chưa có phân tích cấu tạo chi tiết từ nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vùng trời xa; bầu trời xa; huyệt (châm cứu)", "Hạng Tần Suất (Jun Da)": "7776.0", "Tần Suất % (Jun Da)": "99.9989876179", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 卯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴卯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窌", "Unihan_Traditional (Chữ Phồn thể)": "窌", "Pinyin_Xie": "jiào", "Âm Hán Việt_Xie": "giáo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ hầm đất hoặc động từ với nghĩa đào hầm cất giấu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簼', '{"9000": "7777.0", "Chữ Trung Quốc": "簼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 19 | nét | 簼 | lung | tượng hình | dây cương ngựa bằng tre (bộ Trúc) | 簼 thuộc bộ Trúc (竹 — tre), với nhiều nét. Không có dữ liệu Wiktionary. Pinyin lóng, nghĩa liên quan đến dây cương hoặc đồ vật bằng tre dùng điều khiển ngựa. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lung\": bộ Trúc (竹, tre) — hình ảnh dây cương bện bằng tre dẻo, \"lung\" gợi nhốt, kiểm soát như chiếc \"lồng\" (lung) tre. | Gương Hán-Việt | lung — như trong \"lung lay\", \"long lanh\"; chữ 簼 ít dùng trong văn bản hiện đại | Mở khoá kiến thức | Biết 簼 giúp nhận ra nhóm chữ bộ 竹 chỉ dụng cụ/đồ vật tre như 籠 (lung/lồng), 笼 (lồng), 竿 (can/cần câu).", "Tự nguyên_Xie": "Không có anchor Wiktionary cho 簼. Chữ thuộc bộ Trúc (竹, tre). Pinyin lóng, nghĩa liên quan đến điều khiển (rein) hoặc dụng cụ bằng tre. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Rein", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 搆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮搆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "搆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簼", "Unihan_Traditional (Chữ Phồn thể)": "簼", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "lung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ dây cương điều khiển ngựa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纴', '{"9000": "7778.0", "Chữ Trung Quốc": "纴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 7 | nét | 纴 | nhâm | tượng hình | dệt vải, mắc sợi vào khung cửi (bộ Mịch) | 纴 thuộc bộ Mịch (糸 — sợi, tơ). Wiktionary ghi {{Han etym}} nhưng không cung cấp phân tích hình thanh/hội ý chi tiết. Nghĩa dệt vải, mắc sợi phù hợp với bộ Mịch. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhâm\": bộ Mịch (糸, sợi) — hình ảnh người thợ dệt (nhâm) đưa thoi qua những sợi dọc, tạo tấm vải. | Gương Hán-Việt | nhâm — như trong \"nhâm nhi\" (nhấm nháp); 纴 nghĩa dệt vải khác nghĩa thông thường của âm này | Mở khoá kiến thức | Biết 纴 giúp nhận ra nhóm chữ bộ 糸 liên quan dệt may như 織 (chức/dệt), 紡 (phưởng/kéo sợi), 絲 (ti/tơ lụa).", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} cho 纴. Nghĩa: dệt vải, mắc sợi vào khung cửi (weaving). Pinyin rèn. Thuộc bộ Mịch (糸, sợi). Chưa có phân tích cấu tạo chi tiết từ nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dệt vải", "Hạng Tần Suất (Jun Da)": "7778.0", "Tần Suất % (Jun Da)": "99.9989907186", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 壬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟壬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "壬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "纴", "Unihan_Traditional (Chữ Phồn thể)": "紝", "Pinyin_Xie": "rèn", "Âm Hán Việt_Xie": "nhâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ hoạt động dệt may hoặc danh từ chỉ sợi chỉ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翚', '{"9000": "7779.0", "Chữ Trung Quốc": "翚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 12 | nét | 翚 | huy | tượng hình | bay vút lên; chim trĩ sặc sỡ (bộ Vũ) | 翚 thuộc bộ Vũ (羽 — lông, cánh), với nhiều nét. Wiktionary ghi {{Han etym}} và cho biết nghĩa: bay tít (của chim) và con chim trĩ (pheasant). Không có phân tích hình thanh/hội ý chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huy\": bộ Vũ (羽, cánh) — hình ảnh con chim trĩ sặc sỡ vẫy \"huy\" đôi cánh rực rỡ rồi vút bay lên trời cao. | Gương Hán-Việt | huy — như trong \"huy hoàng\", \"huy hiệu\", \"chỉ huy\"; chữ 翚 gợi vẻ rực rỡ của 翚trĩ | Mở khoá kiến thức | Biết 翚 giúp nhận ra nhóm chữ bộ 羽 chỉ chim/cánh như 翔 (tường/bay lượn), 翅 (thí/cánh chim), 翩 (phiên/bay nhẹ).", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} cho 翚. Nghĩa: (chim) bay vút lên; con chim trĩ sặc sỡ (五彩雉). Pinyin huī. Thuộc bộ Vũ (羽, lông cánh). Chưa có phân tích cấu tạo chi tiết từ nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bay tít; con chim trĩ", "Hạng Tần Suất (Jun Da)": "7779.0", "Tần Suất % (Jun Da)": "99.9989927858", "GavinGrover_Once (Chiết tự trực tiếp)": "羽 + 军", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羽军", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "军", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翚", "Unihan_Traditional (Chữ Phồn thể)": "翬", "Pinyin_Xie": "huī", "Âm Hán Việt_Xie": "huy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ loài chim trĩ hoặc động từ chỉ hành động bay vút lên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耰', '{"9000": "7780.0", "Chữ Trung Quốc": "耰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耒 | Số nét | 21 | nét | 耰 | ưu | tượng hình | bừa không răng để san đất sau gieo hạt (bộ Lỗi) | 耰 thuộc bộ Lỗi (耒 — cày bừa), với nhiều nét. Wiktionary ghi {{Han etym}} và định nghĩa: bừa không răng (toothless rake) để san phủ đất sau khi gieo hạt. Không có phân tích hình thanh/hội ý chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ưu\": bộ Lỗi (耒, nông cụ) — hình ảnh người nông dân cầm cái bừa nhẹ nhàng \"ưu ái\" vuốt phẳng đất sau khi gieo hạt xong. | Gương Hán-Việt | ưu — như trong \"ưu tiên\", \"ưu việt\"; chữ 耰 là nông cụ cổ ít dùng trong văn bản hiện đại | Mở khoá kiến thức | Biết 耰 giúp nhận ra nhóm chữ bộ 耒 chỉ nông cụ như 耕 (canh/cày), 耙 (bả/bừa), 耜 (tự/phần lưỡi cày).", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} cho 耰. Nghĩa: bừa không răng, cái đầm đất (toothless rake for drawing earth over seeds after sowing). Pinyin yōu. Thuộc bộ Lỗi (耒, cày bừa). Chưa có phân tích cấu tạo chi tiết từ nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bừa phủ (bừa lại sau khi gieo hạt); cái đầm (để nện đất)", "Hạng Tần Suất (Jun Da)": "7780.0", "Tần Suất % (Jun Da)": "99.9989938193", "GavinGrover_Once (Chiết tự trực tiếp)": "耒 + 憂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耒憂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "憂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耒", "Unihan_Simplified (Chữ Giản thể)": "耰", "Unihan_Traditional (Chữ Phồn thể)": "耰", "Pinyin_Xie": "yōu", "Âm Hán Việt_Xie": "ưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ nông cụ san đất hoặc động từ chỉ việc bừa đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艧', '{"9000": "7781.0", "Chữ Trung Quốc": "艧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 19 | nét | 艧 | hoặc | tượng hình | thuyền nhỏ, thuyền chèo (bộ Chu) | 艧 thuộc bộ Chu (舟 — thuyền), với nhiều nét. Không có dữ liệu Wiktionary. Pinyin huò, nghĩa liên quan đến thuyền/tàu. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoặc\": bộ Chu (舟, thuyền) — hình ảnh con thuyền trôi lặng lẽ trên sông, \"hoặc\" gợi sự bất định, thuyền trôi theo dòng. | Gương Hán-Việt | hoặc — như trong \"hoặc là\", \"nghi hoặc\"; chữ 艧 ít dùng trong văn bản hiện đại | Mở khoá kiến thức | Biết 艧 giúp nhận ra nhóm chữ bộ 舟 chỉ thuyền bè như 船 (thuyền), 艦 (hạm/tàu chiến), 航 (hàng/hàng hải).", "Tự nguyên_Xie": "Không có anchor Wiktionary cho 艧. Chữ thuộc bộ Chu (舟, thuyền). Pinyin huò. Nghĩa liên quan đến một loại thuyền cổ. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "艧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 蒦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟蒦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蒦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艧", "Unihan_Traditional (Chữ Phồn thể)": "艧", "Pinyin_Xie": "huò", "Âm Hán Việt_Xie": "hoặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn học cổ để chỉ các loại thuyền lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藇', '{"9000": "7782.0", "Chữ Trung Quốc": "藇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 艹 | thảo | biểu nghĩa | cỏ, cây | 與 | dữ | biểu âm | và, cùng với (cho âm xù) | 藇 = 艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 與 (Dữ, biểu âm); chữ hình thanh. Phần 艹 chỉ rõ nghĩa liên quan đến thực vật; phần 與 cho âm đọc xù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dự\": cỏ (艹) + 與 (dữ, âm) — hình ảnh cây cỏ sum suê tươi tốt, \"dự\" như trong \"dự phần\" vào vẻ đẹp thiên nhiên. | Gương Hán-Việt | dự — như trong \"dự phần\", \"tham dự\"; chữ 藇 ít dùng trong văn bản hiện đại | Mở khoá kiến thức | Biết 藇 giúp nhận ra nhóm chữ bộ 艹 chỉ thực vật đẹp như 芳 (phương/thơm), 葱 (thông/hành xanh), 薇 (vi/cây cỏ vi).", "Tự nguyên_Xie": "Wiktionary phân tích: 藇 là chữ hình thanh (psc) gồm 艹 (thảo, biểu nghĩa: cỏ) + 與 (dữ, biểu âm). Nghĩa: xinh đẹp, tươi tốt (của cây cỏ). Nhiều âm đọc. Đây cũng được dùng như họ tên người (họ Xu). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xinh đẹp; họ Xu", "Hạng Tần Suất (Jun Da)": "7782.0", "Tần Suất % (Jun Da)": "99.9989958865", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 與", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹與", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "與", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藇", "Unihan_Traditional (Chữ Phồn thể)": "藇", "Pinyin_Xie": "xù", "Âm Hán Việt_Xie": "tự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Dùng làm tính từ chỉ sự tốt đẹp hoặc danh từ chỉ một loại cây khoai. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虖', '{"9000": "7783.0", "Chữ Trung Quốc": "虖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虍 | Số nét | 11 | nét | 虖 | hô | tượng hình | bốc lên; tiếng hổ gầm; gọi lại (bộ Hổ) | 虖 thuộc bộ Hổ (虍 — hổ), với nhiều nét. Wiktionary ghi {{Han etym}}. Nghĩa: bốc lên/bốc khói; tiếng hổ gầm; gọi lại. Không có phân tích hình thanh/hội ý chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hô\": bộ Hổ (虍, hổ) — hình ảnh con hổ gầm \"hô\" vang, tiếng gầm bốc lên trong rừng thẳm. | Gương Hán-Việt | hô — như trong \"hô hào\" (kêu gọi), \"hô hấp\" (thở), \"hô khẩu hiệu\" | Mở khoá kiến thức | Biết 虖 giúp nhận ra nhóm chữ bộ 虍 liên quan hổ như 虎 (hổ), 虐 (ngược/tàn bạo), 彪 (tiêu/hổ nhỏ).", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} cho 虖. Nghĩa bao gồm: bốc lên; tiếng hổ gầm; gọi lại (recall). Pinyin hū. Thuộc bộ Hổ (虍, hổ). Chưa có phân tích cấu tạo chi tiết từ nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bốc lên; tiếng hổ gầm; gọi lại", "Hạng Tần Suất (Jun Da)": "7783.0", "Tần Suất % (Jun Da)": "99.9989969201", "GavinGrover_Once (Chiết tự trực tiếp)": "虍 + 乎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴虍乎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虍", "Unihan_Simplified (Chữ Giản thể)": "虖", "Unihan_Traditional (Chữ Phồn thể)": "虖", "Pinyin_Xie": "hū", "Âm Hán Việt_Xie": "hô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Trợ từ | 助词 | Từ tượng thanh | 象声词 | Thường dùng làm động từ chỉ tiếng gầm, tiếng gọi hoặc làm trợ từ ngữ khí cuối câu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí). | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚖', '{"9000": "7784.0", "Chữ Trung Quốc": "蚖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 蚖 | viên | tượng hình | con vật giống kỳ nhông hoặc sa giông (bộ Trùng) | 蚖 thuộc bộ Trùng (虫 — sâu bọ/sinh vật nhỏ), với nhiều nét. Wiktionary ghi {{Han etym}} và định nghĩa: con vật giống thằn lằn/sa giông (lizard or salamander). Không có phân tích hình thanh/hội ý chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"viên\": bộ Trùng (虫, sinh vật) — hình ảnh con sa giông \"viên\" (tròn trịa) nằm bên bờ suối ẩm ướt. | Gương Hán-Việt | viên — như trong \"viên chức\", \"nhân viên\"; chữ 蚖 là tên động vật cổ ít dùng | Mở khoá kiến thức | Biết 蚖 giúp nhận ra nhóm chữ bộ 虫 chỉ bò sát/lưỡng cư như 蜥 (tích/thằn lằn), 蛇 (xà/rắn), 鱷 (ngạc/cá sấu).", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} cho 蚖. Nghĩa: con vật giống thằn lằn hoặc sa giông (obsolete term). Pinyin yuán. Thuộc bộ Trùng (虫). Chữ dùng trong văn hiến cổ, không còn phổ thông. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "An Huy", "Hạng Tần Suất (Jun Da)": "7784.0", "Tần Suất % (Jun Da)": "99.9989979536", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 元", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫元", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "元", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚖", "Unihan_Traditional (Chữ Phồn thể)": "蚖", "Pinyin_Xie": "yuán", "Âm Hán Việt_Xie": "ngoan, nguyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loài bò sát hoặc lưỡng cư cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜎', '{"9000": "7785.0", "Chữ Trung Quốc": "蜎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng | 肙 | quyên | biểu âm | (cho âm yuān) | 蜎 = 虫 (Trùng, biểu nghĩa: sâu bọ) + 肙 (Quyên, biểu âm); chữ hình thanh. Phần 虫 chỉ rõ đây là sinh vật nhỏ; phần 肙 cho âm đọc yuān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyên\": sâu (虫) + 肙 (âm) — hình ảnh con bọ gậy \"quyên\" tròn xoắn trong chậu nước đọng, là ấu trùng muỗi. | Gương Hán-Việt | quyên — như trong \"quyên góp\", \"từ quyên\"; chữ 蜎 là tên sinh vật ít dùng trong văn bản thông thường | Mở khoá kiến thức | Biết 蜎 giúp nhận ra nhóm chữ bộ 虫 chỉ ấu trùng như 蛹 (dũng/nhộng), 孑 (kiệt/bọ gậy), 孓 (quyết/đuôi bọ gậy).", "Tự nguyên_Xie": "Wiktionary phân tích: 蜎 là chữ hình thanh (psc) gồm 虫 (trùng, biểu nghĩa: côn trùng) + 肙 (biểu âm). Nghĩa: ấu trùng muỗi (bọ gậy, cung quăng). Pinyin yuān. Đây là giai đoạn ấu trùng của muỗi, sống trong nước. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con bọ gậy, con cung quăng", "Hạng Tần Suất (Jun Da)": "7785.0", "Tần Suất % (Jun Da)": "99.9989989872", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 肙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫肙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜎", "Unihan_Traditional (Chữ Phồn thể)": "蜎", "Pinyin_Xie": "yuān", "Âm Hán Việt_Xie": "quyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường dùng làm danh từ để chỉ ấu trùng của muỗi hoặc làm động từ chỉ sự co duỗi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜨', '{"9000": "7786.0", "Chữ Trung Quốc": "蜨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 蜨 | điệp | tượng hình | con bươm bướm (bộ Trùng) | 蜨 thuộc bộ Trùng (虫 — sâu bọ), với nhiều nét. Wiktionary ghi {{Han etym}} nhưng không có phân tích cấu trúc. Nghĩa con bướm phù hợp bộ Trùng. Đây có thể là dạng cổ hoặc biến thể của 蝶 (điệp, bươm bướm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệp\": bộ Trùng (虫, sâu bọ) — hình ảnh con bướm (điệp) xòe đôi cánh rực rỡ, lượn nhẹ nhàng qua những bông hoa. | Gương Hán-Việt | điệp — như trong \"bươm bướm\", \"điệp khúc\" (motif lặp lại như cánh bướm), \"hồ điệp\" (bướm trong mộng Trang Tử) | Mở khoá kiến thức | Biết 蜨 giúp đọc \"hồ điệp\" (蝴蝶, bươm bướm), \"điệp mộng\" (giấc mộng bướm của Trang Tử).", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} cho 蜨. Nghĩa: con bươm bướm. Pinyin dié. Thuộc bộ Trùng (虫). Có thể là biến thể/dạng cổ của 蝶 (cũng nghĩa bươm bướm). Chưa có phân tích cấu tạo chi tiết từ nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con bươm bướm", "Hạng Tần Suất (Jun Da)": "2301.0", "Tần Suất % (Jun Da)": "98.0543577136", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 疌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫疌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "疌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝶", "Unihan_Traditional (Chữ Phồn thể)": "蜨", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là biến thể của chữ điệp 蝶, đóng vai trò danh từ trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠭', '{"9000": "7787.0", "Chữ Trung Quốc": "蠭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 22 | nét | 逢 | phùng | biểu âm | gặp (cho âm fēng) | 䖵 | côn | biểu nghĩa | côn trùng | 蠭 = 逢 (Phùng, biểu âm) + 䖵 (Côn, biểu nghĩa: côn trùng); chữ hình thanh. Wiktionary xác nhận đây là dạng gốc của 蜂 (ong). Phần 䖵 chỉ rõ đây là côn trùng; phần 逢 cho âm fēng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phong\": côn trùng (䖵) + 逢 (phùng/gặp, âm) — hình ảnh khi \"phùng\" (gặp) con ong (蠭), phải cẩn thận kẻo bị chích. | Gương Hán-Việt | phong — như trong \"ong phong\" (蜂), \"phong trào\" (蜂擁/phong trào ào ạt như đàn ong) | Mở khoá kiến thức | Biết 蠭 (dạng gốc) giúp nhận ra 蜂 (ong) và đọc \"mật ong\" (蜂蜜), \"tổ ong\" (蜂窩), \"phong trào\" (蜂擁).", "Tự nguyên_Xie": "Wiktionary phân tích: 蠭 là chữ hình thanh (psc) gồm 逢 (phùng, biểu âm) + 䖵 (côn, biểu nghĩa: côn trùng). Đây là dạng gốc (original form) của chữ 蜂 (ong). Nghĩa: con ong (bee/wasp). Chữ 蜂 là dạng đơn giản hóa phổ thông hơn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "譭", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "逢 + 䖵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱逢䖵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䖵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "逢", "Unihan_Simplified (Chữ Giản thể)": "蠭", "Unihan_Traditional (Chữ Phồn thể)": "蠭", "Pinyin_Xie": "fēng", "Âm Hán Việt_Xie": "phong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là dạng cổ của chữ phong 蜂, dùng làm danh từ chỉ loài ong. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詟', '{"9000": "7788.0", "Chữ Trung Quốc": "詟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 12 | nét | 詟 | thiếp | tượng hình | hoảng sợ, sợ hãi, khiếp vía (bộ Ngôn) | 詟 thuộc bộ Ngôn (言 — lời nói), với nhiều nét. Không có dữ liệu Wiktionary. Pinyin zhé. Nghĩa hoảng sợ, sợ hãi có thể liên quan đến lời nói run rẩy do khiếp sợ. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiếp\": bộ Ngôn (言, lời nói) — hình ảnh người \"thiếp\" (thiếp đi vì sợ), lời nói bị cắt đứt bởi nỗi kinh hoàng. | Gương Hán-Việt | thiếp — như trong \"thiếp đi\" (ngất), \"thư thiếp\"; chữ 詟 ít dùng trong văn bản hiện đại | Mở khoá kiến thức | Biết 詟 giúp nhận ra nhóm chữ bộ 言 liên quan lời nói/cảm xúc như 諾 (nặc/đồng ý), 諫 (gián/can ngăn), 譴 (khiển/trách mắng).", "Tự nguyên_Xie": "Không có anchor Wiktionary cho 詟. Chữ thuộc bộ Ngôn (言, lời nói). Pinyin zhé. Nghĩa: hoảng sợ, khiếp vía. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoảng sợ, sợ hãi", "Hạng Tần Suất (Jun Da)": "7788.0", "Tần Suất % (Jun Da)": "99.9990020879", "GavinGrover_Once (Chiết tự trực tiếp)": "龙 + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱龙言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "言", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "龙", "Unihan_Simplified (Chữ Giản thể)": "詟", "Unihan_Traditional (Chữ Phồn thể)": "讋", "Pinyin_Xie": "zhé", "Âm Hán Việt_Xie": "triệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ thể hiện trạng thái lo sợ hoặc bị khuất phục trước uy lực. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豭', '{"9000": "7789.0", "Chữ Trung Quốc": "豭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豕 | Số nét | 16 | nét | 豕 | thỉ | biểu nghĩa | lợn | 叚 | giả | biểu âm | (cho âm jiā) | 豭 = 豕 (Thỉ, biểu nghĩa: lợn) + 叚 (Giả, biểu âm); chữ hình thanh. Wiktionary cho biết dạng gốc là tượng hình (pictograph) heo đực với bộ phận sinh dục hiện rõ. Dạng hiện tại: 豕 + 叚. Chữ cũng là tổ tiên của 家 (gia, nhà).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"gia\": lợn (豕) + 叚 (âm) — lợn đực, con vật quan trọng trong gia đình; \"gia\" (nhà) bắt nguồn từ đây (mái nhà + lợn = nhà ở). | Gương Hán-Việt | gia — như trong \"gia đình\", \"gia súc\", \"gia tộc\"; 豭 là dạng gốc của nghĩa này | Mở khoá kiến thức | Biết 豭 giúp hiểu nguồn gốc 家 (gia, nhà): lợn (豕) dưới mái nhà. Đọc được \"gia súc\" (livestock), \"gia quyến\" (family).", "Tự nguyên_Xie": "Wiktionary phân tích: 豭 ban đầu là tượng hình (pictograph) heo đực với bộ phận sinh dục. Trong dạng hiện tại: hình thanh gồm 豕 (thỉ, biểu nghĩa: lợn) + 叚 (biểu âm). Nghĩa: lợn đực. Dẫn xuất của chữ này là 家 (gia, nhà — nơi nuôi lợn dưới mái nhà). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con lợn (heo) đực", "Hạng Tần Suất (Jun Da)": "7789.0", "Tần Suất % (Jun Da)": "99.9990051886", "GavinGrover_Once (Chiết tự trực tiếp)": "豕 + 叚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豕叚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豕", "Unihan_Simplified (Chữ Giản thể)": "豭", "Unihan_Traditional (Chữ Phồn thể)": "豭", "Pinyin_Xie": "jiā", "Âm Hán Việt_Xie": "gia", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ con lợn đực trong văn ngôn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趬', '{"9000": "7790.0", "Chữ Trung Quốc": "趬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 19 | nét | 走 | tẩu | biểu nghĩa | đi, chạy | 堯 | nghiêu | biểu âm | (cho âm qiāo) | 趬 = 走 (Tẩu, biểu nghĩa: đi/chạy) + 堯 (Nghiêu, biểu âm); chữ hình thanh. Phần 走 chỉ rõ nghĩa liên quan đến vận động; phần 堯 cho âm qiāo. Nghĩa: đi kiễng chân, bước nhẹ nhàng (light-footed movement).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiêu\": đi (走) + 堯 (nghiêu, âm) — hình ảnh người thiếu nữ kiêu sa bước đi kiễng gót, dáng nhẹ nhàng thanh thoát. | Gương Hán-Việt | kiêu — như trong \"kiêu ngạo\", \"kiêu sa\"; chữ 趬 là từ văn học cổ ít dùng | Mở khoá kiến thức | Biết 趬 giúp nhận ra nhóm chữ bộ 走 chỉ vận động như 趨 (xu/đi gấp), 趾 (chỉ/ngón chân), 踵 (chủng/gót chân).", "Tự nguyên_Xie": "Wiktionary phân tích: 趬 là chữ hình thanh (psc) gồm 走 (tẩu, biểu nghĩa: đi) + 堯 (nghiêu, biểu âm). Nghĩa: bước đi nhẹ nhàng, kiễng chân (light-footed, dainty movement). Dùng trong văn học cổ điển để miêu tả dáng đi thanh thoát. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "褬", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 堯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走堯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趬", "Unihan_Traditional (Chữ Phồn thể)": "趬", "Pinyin_Xie": "qiāo", "Âm Hán Việt_Xie": "kiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ miêu tả tư thế đi đứng nhẹ nhàng hoặc nhanh nhẹn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阢', '{"9000": "7791.0", "Chữ Trung Quốc": "阢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 5 | nét | 阢 | ngột | tượng hình | gò đất dốc, bất ổn | 阢 là chữ độc thể, bộ 阜 (phụ — gò đất cao). Chưa xác định rõ cấu trúc hình thanh hay hội ý vì thiếu nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngột\": bộ 阜 (gò đất) gợi cảnh núi dốc chênh vênh — đứng trên gò cao mà lòng ngột ngạt, lo lắng. | Gương Hán-Việt | ngột — cảm giác bất an, ngột ngạt | Mở khoá kiến thức | Biết 阢 mở khoá nhóm chữ bộ 阜 chỉ địa hình gồ ghề, bất ổn.", "Tự nguyên_Xie": "阢 thuộc bộ 阜 (gò đất). Không tìm thấy nguồn Wiktionary mô tả glyph origin. Từ ngữ nghĩa lo lắng, bất an, có thể liên quan hình ảnh đất dốc cheo leo không vững. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lo lắng sợ hãi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 兀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝兀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "阢", "Unihan_Traditional (Chữ Phồn thể)": "阢", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "ngột", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ mô tả trạng thái chông chênh, không vững vàng hoặc lo âu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('圊', '{"9000": "7792.0", "Chữ Trung Quốc": "圊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 囗 | Số nét | 11 | nét | 囗 | vi | biểu nghĩa | vây quanh, khuôn viên | 青 | thanh | biểu âm | xanh — cho âm | 圊 = 囗 (Vi, biểu nghĩa: khuôn viên khép kín) + 青 (Thanh, biểu âm). Chữ hình thanh: 囗 chỉ ý nghĩa (nhà xí là khoảng không gian khép kín), 青 cho âm đọc qīng/thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thanh\": 囗 (khuôn viên kín) + 青 (thanh) — nhà xí là chỗ kín đáo mang âm thanh. | Gương Hán-Việt | thanh — âm Hán-Việt của 青, dùng ở đây làm phần biểu âm | Mở khoá kiến thức | Biết 圊 mở khoá nhóm chữ bộ 囗 chỉ không gian khép kín, và liên kết âm 青 (thanh).", "Tự nguyên_Xie": "圊 là chữ hình thanh (psc): 囗 (vi — vây quanh) là phần biểu nghĩa, 青 (thanh — xanh) là phần biểu âm. Nghĩa gốc: nhà vệ sinh, hố xí — một khoảng không gian khép kín. Wiktionary ghi đây là từ cổ-chuẩn (obs-std) chỉ toilet/latrine. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chò, chuồng xí", "Hạng Tần Suất (Jun Da)": "7792.0", "Tần Suất % (Jun Da)": "99.9990093229", "GavinGrover_Once (Chiết tự trực tiếp)": "囗 + 青", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴囗青", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "青", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "囗", "Unihan_Simplified (Chữ Giản thể)": "圊", "Unihan_Traditional (Chữ Phồn thể)": "圊", "Pinyin_Xie": "qīng", "Âm Hán Việt_Xie": "thanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ nơi đi vệ sinh trong tiếng Hán cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('録', '{"9000": "7793.0", "Chữ Trung Quốc": "録", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 録 | lục | tượng hình | ghi chép, chép lại | 録 là dạng phồn thể, bộ 金 (kim — kim loại). Wiktionary không cung cấp glyph origin. Hình ảnh tiểu triện cho thấy cấu trúc có bộ 金 và phần biểu âm, gợi ý chữ hình thanh chỉ việc ghi chép (khắc vào kim loại). Chưa xác định thành phần cụ thể từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lục\": bộ 金 (kim loại) — xưa khắc lục lại sự kiện lên thẻ kim, tạo nên bản ghi chép lục. | Gương Hán-Việt | lục — dùng trong \"lục âm\" (ghi âm), \"mục lục\" (danh sách) | Mở khoá kiến thức | Biết 録/录 mở khoá: 記録 (ghi chép), 錄音 (thu âm), 目錄 (mục lục), 收录 (thu nhận).", "Tự nguyên_Xie": "Tiểu triện | 録 (dạng phồn thể của 录) thuộc bộ 金 (kim — kim loại). Nghĩa gốc liên quan ghi chép, sao chép — xưa khắc chữ lên thanh tre hay thẻ kim loại. Dạng giản thể 录 thông dụng hơn. Có hình tiểu triện trong kho ảnh. Glyph origin chi tiết chưa có trong nguồn học thuật tra được. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ghi chép", "Hạng Tần Suất (Jun Da)": "7793.0", "Tần Suất % (Jun Da)": "99.99901139", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 录", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金录", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "录", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "録", "Unihan_Traditional (Chữ Phồn thể)": "録", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ biểu thị hành động ghi chép hoặc làm danh từ chỉ danh sách, sổ sách. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鍮', '{"9000": "7794.0", "Chữ Trung Quốc": "鍮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 鍮 | thau | tượng hình | đồng thau, hợp kim đồng | 鍮 thuộc bộ 金 (kim — kim loại). Wiktionary chỉ ghi {{Han etym}} mà không phân tích cấu trúc. Đây là chữ chỉ loại hợp kim, nhiều khả năng là hình thanh với 金 biểu nghĩa, nhưng thành phần biểu âm không xác định được từ nguồn hiện có. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thau\": bộ 金 (kim loại) — chữ chuyên chỉ kim loại thau, hợp kim sáng bóng màu vàng. | Gương Hán-Việt | thau — dùng trong \"đồng thau\" (brass), vật liệu truyền thống làm đồ thờ | Mở khoá kiến thức | Biết 鍮 mở khoá nhóm chữ bộ 金 chỉ các loại kim loại và hợp kim đặc thù.", "Tự nguyên_Xie": "鍮 thuộc bộ 金 (kim — kim loại). Nghĩa: đồng thau, một loại hợp kim đồng vàng. Wiktionary không cung cấp phân tích glyph origin. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quặng đồng thau; quặng đồng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 俞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金俞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鍮", "Unihan_Traditional (Chữ Phồn thể)": "鍮", "Pinyin_Xie": "tōu", "Âm Hán Việt_Xie": "thâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ để chỉ kim loại đồng thau hoặc hợp kim đồng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鍸', '{"9000": "7795.0", "Chữ Trung Quốc": "鍸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 鍸 | hồ | tượng hình | nồi, vạc kim loại | 鍸 thuộc bộ 金 (kim — kim loại). Không có glyph origin trong Wiktionary. Nhiều khả năng là hình thanh với 金 biểu nghĩa và thành phần biểu âm liên quan âm hú/hồ, nhưng không xác định được chính xác. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồ\": bộ 金 (kim loại) — nồi hồ, vạc kim loại đựng thức ăn. | Gương Hán-Việt | hồ — âm Hán-Việt liên quan chữ 胡 (hồ), 湖 (hồ nước) | Mở khoá kiến thức | Biết 鍸 mở khoá nhóm chữ bộ 金 chỉ dụng cụ nấu nướng và đồ dùng kim loại.", "Tự nguyên_Xie": "鍸 thuộc bộ 金 (kim). Wiktionary không cung cấp glyph origin. Nghĩa liên quan đồ dùng kim loại, thức ăn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鍍", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 胡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金胡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鍸", "Unihan_Traditional (Chữ Phồn thể)": "鍸", "Pinyin_Xie": "hú", "Âm Hán Việt_Xie": "hồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ cổ chỉ một loại đồ đựng bằng gỗ hoặc kim loại dùng trong tế lễ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闚', '{"9000": "7796.0", "Chữ Trung Quốc": "闚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 19 | nét | 闚 | khuy | tượng hình | nhìn lén qua khe cửa | 闚 thuộc bộ 門 (môn — cửa). Wiktionary ghi {{Han etym}} nhưng không phân tích chi tiết. Cấu trúc trực quan: cửa + một thành phần bên trong gợi hành động nhìn trộm qua khe. Có ảnh tiểu triện và Lục thư thông trong kho ảnh. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuy\": bộ 門 (cửa) — hé cửa mà khuy ngó — nhìn trộm qua khe cửa hé. | Gương Hán-Việt | khuy — dùng trong \"khuy thám\" (thám thính bí mật) | Mở khoá kiến thức | Biết 闚 mở khoá nhóm chữ bộ 門 chỉ hành động liên quan cửa và quan sát; đồng nghĩa với 窥.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 闚 thuộc bộ 門 (môn — cửa). Wiktionary không mô tả glyph origin chi tiết. Nghĩa: nhìn lén, liếc nhanh, nhìn trộm qua khe cửa — động từ mô tả hành động quan sát bí mật. Tương đương với 窥 trong tiếng Trung hiện đại. Có hình tiểu triện và Lục thư thông. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thoáng qua", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "門 + 規", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門規", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "規", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "闚", "Unihan_Traditional (Chữ Phồn thể)": "闚", "Pinyin_Xie": "kuī", "Âm Hán Việt_Xie": "khuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện hành vi nhìn lén qua khe hở hoặc quan sát kín đáo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阤', '{"9000": "7797.0", "Chữ Trung Quốc": "阤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 5 | nét | 阤 | đà | tượng hình | dốc đất, chỗ gập ghềnh | 阤 thuộc bộ 阜 (phụ — gò đất cao). Wiktionary ghi {{Han etym}} nhưng không phân tích cấu trúc chi tiết. Có hình đại triện và tiểu triện. Chưa xác định rõ hình thanh hay hội ý từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\": bộ 阜 (gò đất) — đà xuống dốc, một khi đã xuống đà thì khó dừng. | Gương Hán-Việt | đà — dùng trong \"đà xuống\" (momentum, sức xuôi chiều) | Mở khoá kiến thức | Biết 阤 mở khoá nhóm chữ bộ 阜 chỉ địa hình dốc, gập ghềnh.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 阤 thuộc bộ 阜 (phụ — gò đất, địa hình). Wiktionary không mô tả glyph origin chi tiết. Nghĩa: chỗ đất dốc, gập ghềnh; đà (quán tính, sức xuôi). Có hình đại triện và tiểu triện trong kho ảnh. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỗ gập ghềnh; đà, quán tính", "Hạng Tần Suất (Jun Da)": "7797.0", "Tần Suất % (Jun Da)": "99.9990155243", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 也", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝也", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "也", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "阤", "Unihan_Traditional (Chữ Phồn thể)": "阤", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "trĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ sườn núi dốc hoặc làm động từ chỉ sự sụt lở đất đá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霫', '{"9000": "7798.0", "Chữ Trung Quốc": "霫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 19 | nét | 霫 | tập | tượng hình | mưa nhiều, ẩm ướt | 霫 thuộc bộ 雨 (vũ — mưa). Wiktionary không phân tích cấu trúc glyph origin. Nhiều khả năng là hình thanh với 雨 biểu nghĩa (mưa), nhưng thành phần biểu âm không xác định được. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tập\": bộ 雨 (mưa) — mưa tập tành liên tục, ẩm ướt không dứt. | Gương Hán-Việt | tập — âm Hán-Việt, liên quan đến ẩm ướt, mưa nhiều | Mở khoá kiến thức | Biết 霫 mở khoá nhóm chữ bộ 雨 chỉ các hiện tượng mưa ẩm.", "Tự nguyên_Xie": "霫 thuộc bộ 雨 (vũ — mưa). Wiktionary ghi: rainy (mưa nhiều) và tên một bộ tộc Tiele (Đột Quyết). Phát âm xí/xí. Không có phân tích glyph origin. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mưa", "Hạng Tần Suất (Jun Da)": "7798.0", "Tần Suất % (Jun Da)": "99.9990165579", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 習", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨習", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "習", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霫", "Unihan_Traditional (Chữ Phồn thể)": "霫", "Pinyin_Xie": "xí", "Âm Hán Việt_Xie": "tập", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ thời tiết mưa dầm hoặc dùng làm tên riêng của bộ tộc cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞎', '{"9000": "7799.0", "Chữ Trung Quốc": "鞎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 15 | nét | 鞎 | ngân | tượng hình | đồ trang trí da trên xe ngựa | 鞎 thuộc bộ 革 (cách — da thuộc). Wiktionary không phân tích glyph origin cụ thể. Nhiều khả năng là hình thanh với 革 biểu nghĩa (da), nhưng thành phần biểu âm chưa xác định. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngân\": bộ 革 (da thuộc) — miếng da ngân trang trí phần trước xe ngựa quý tộc. | Gương Hán-Việt | ngân — âm Hán-Việt ít dùng, liên quan vật dụng da trang trí | Mở khoá kiến thức | Biết 鞎 mở khoá nhóm chữ bộ 革 chỉ đồ dùng và trang trí bằng da trong văn hóa cổ.", "Tự nguyên_Xie": "鞎 thuộc bộ 革 (cách — da thuộc). Wiktionary định nghĩa: đồ trang trí da ở phần trước xe ngựa (historical leather decoration on front of carriage). Phát âm hén. Glyph origin không được mô tả. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鞞", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 艮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革艮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "艮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞎", "Unihan_Traditional (Chữ Phồn thể)": "鞎", "Pinyin_Xie": "hén", "Âm Hán Việt_Xie": "ngân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần bao da hoặc trang trí bằng da trên vũ khí thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韗', '{"9000": "7800.0", "Chữ Trung Quốc": "韗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 韋 | Số nét | 18 | nét | 韗 | uẩn | tượng hình | người làm trống da | 韗 thuộc bộ 韋 (vi — da thuộc mềm). Wiktionary không phân tích glyph origin chi tiết ngoài {{Han etym}}. Nghĩa liên quan người chế tạo trống da. Chưa xác định rõ cấu trúc hình thanh hay hội ý. Có hình tiểu triện trong kho ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uẩn\": bộ 韋 (da thuộc) — nghệ nhân uẩn chứa kỹ năng bịt da căng trống. | Gương Hán-Việt | uẩn — âm Hán-Việt, liên quan người thợ da làm trống | Mở khoá kiến thức | Biết 韗 mở khoá nhóm chữ bộ 韋 chỉ đồ dùng và nghề nghiệp liên quan da thuộc.", "Tự nguyên_Xie": "Tiểu triện | 韗 thuộc bộ 韋 (vi — da thuộc). Wiktionary định nghĩa chưa rõ (rfdef), nhưng từ ghép 韗人 gợi nghĩa: người chuyên làm trống da. Phát âm yùn/xuàn. Có hình tiểu triện. Chưa có nguồn học thuật đầy đủ về glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "闗", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "韋 + 軍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰韋軍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "軍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "韋", "Unihan_Simplified (Chữ Giản thể)": "韗", "Unihan_Traditional (Chữ Phồn thể)": "韗", "Pinyin_Xie": "yùn", "Âm Hán Việt_Xie": "vận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ người thợ chuyên làm trống hoặc nghề thuộc da thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬖', '{"9000": "7801.0", "Chữ Trung Quốc": "鬖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 21 | nét | 鬖 | sam | tượng hình | tóc rũ xuống, tóc bù xù | 鬖 thuộc bộ 髟 (tiêu — tóc dài). Wiktionary ghi {{Han etym}} không phân tích glyph origin. Âm sān/sam. Nghĩa: tóc rũ xuống, bù xù. Chưa xác định cấu trúc nội tại từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sam\": bộ 髟 (tóc) — mái tóc sam sam rũ xuống, bù xù không chải. | Gương Hán-Việt | sam — âm Hán-Việt gợi hình ảnh tóc thưa rũ xuống | Mở khoá kiến thức | Biết 鬖 mở khoá nhóm chữ bộ 髟 chỉ các trạng thái và kiểu tóc.", "Tự nguyên_Xie": "鬖 thuộc bộ 髟 (tiêu — tóc dài buông). Wiktionary định nghĩa: dùng trong 鬖髿 — tóc rủ xuống, rối bù, hoang dại. Glyph origin không được mô tả chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mái tóc hoang dã", "Hạng Tần Suất (Jun Da)": "7801.0", "Tần Suất % (Jun Da)": "99.9990196586", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 參", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟參", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "參", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "鬖", "Unihan_Traditional (Chữ Phồn thể)": "鬖", "Pinyin_Xie": "sān", "Âm Hán Việt_Xie": "tam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả trạng thái tóc tai buông xõa hoặc rối bù, thường dùng dạng láy. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳠', '{"9000": "7802.0", "Chữ Trung Quốc": "鳠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 21 | nét | 鳠 | hộ | tượng hình | cá nheo, cá trê họ Mystus | 鳠 thuộc bộ 魚 (ngư — cá). Wiktionary ghi {{Han etym}} không phân tích glyph origin rõ ràng. Wiktionary dùng usedForm 鱯 (dạng khác). Nghĩa: loài cá nheo chi Mystus. Chưa có nguồn học thuật về cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hộ\": bộ 魚 (cá) — cá hộ, loài cá nheo to sống ở đáy sông. | Gương Hán-Việt | hộ — âm Hán-Việt chỉ loài cá nheo đặc trưng | Mở khoá kiến thức | Biết 鳠 mở khoá nhóm chữ bộ 魚 chỉ các loài cá đặc thù trong văn bản cổ.", "Tự nguyên_Xie": "鳠 thuộc bộ 魚 (ngư — cá). Wiktionary định nghĩa: một loài cá nheo (mystus catfish) thuộc chi Mystus. Dạng thay thế 鱯 cũng được dùng. Glyph origin không được phân tích. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá nheo", "Hạng Tần Suất (Jun Da)": "7802.0", "Tần Suất % (Jun Da)": "99.9990206922", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 蒦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼蒦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蒦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳠", "Unihan_Traditional (Chữ Phồn thể)": "鱯", "Pinyin_Xie": "hù", "Âm Hán Việt_Xie": "ngư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cá nước ngọt không vảy thuộc họ cá nheo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴼', '{"9000": "7803.0", "Chữ Trung Quốc": "鴼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 17 | nét | 鴼 | lạc | tượng hình | loài chim (kéc/két) | 鴼 thuộc bộ 鳥 (điểu — chim). Wiktionary không có glyph origin. Nghĩa Hán-Việt ghi là \"chim kéc\" hoặc \"chim lạc\". Chưa có nguồn học thuật về cấu trúc nội tại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạc\": bộ 鳥 (chim) — chim lạc, loài chim hoang dã vùng sông nước. | Gương Hán-Việt | lạc — âm Hán-Việt, liên quan chim lạc trong văn hóa Việt cổ | Mở khoá kiến thức | Biết 鴼 mở khoá nhóm chữ bộ 鳥 chỉ các loài chim hiếm gặp trong văn bản cổ.", "Tự nguyên_Xie": "鴼 thuộc bộ 鳥 (điểu — chim). Wiktionary không cung cấp glyph origin. Nghĩa Việt: chim kéc hoặc chim lạc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kéc; như \"chim kéc\" (vhn) lạc; như \"chim lạc\" (btcn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鳥 + 各", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鳥各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鴼", "Unihan_Traditional (Chữ Phồn thể)": "鴼", "Pinyin_Xie": "luò", "Âm Hán Việt_Xie": "lộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim hoang dã theo thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鷇', '{"9000": "7804.0", "Chữ Trung Quốc": "鷇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 21 | nét | 鳥 | điểu | biểu nghĩa | chim | 𣪊 | biểu âm | thành phần biểu âm cổ | 鷇 = 鳥 (Điểu, biểu nghĩa: chim) + 𣪊 (biểu âm, cổ tự không phổ biến). Chữ hình thanh: 鳥 chỉ loài vật, 𣪊 cho âm kòu/cấu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cấu\": 鳥 (chim) + 𣪊 (biểu âm) — chim cấu, con chim non há mỏ cấu thức ăn từ mẹ. | Gương Hán-Việt | cấu — âm Hán-Việt, hình ảnh chim non đòi mồi | Mở khoá kiến thức | Biết 鷇 mở khoá hình ảnh chim non trong thơ cổ; bộ 鳥 liên kết các loài chim.", "Tự nguyên_Xie": "鷇 là chữ hình thanh (psc) theo Wiktionary: 鳥 (điểu — chim) là phần biểu nghĩa, 𣪊 là phần biểu âm. Nghĩa: chim non còn trong tổ, chim non chờ mẹ mớm mồi. Glyph origin rõ ràng từ {{Han compound}}. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim non", "Hạng Tần Suất (Jun Da)": "7804.0", "Tần Suất % (Jun Da)": "99.9990227593", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鷇", "Unihan_Traditional (Chữ Phồn thể)": "鷇", "Pinyin_Xie": "kòu", "Âm Hán Việt_Xie": "cấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ những con chim non mới nở còn tự há mỏ chờ mẹ mớm mồi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黇', '{"9000": "7805.0", "Chữ Trung Quốc": "黇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黃 | Số nét | 16 | nét | 黇 | thiêm | tượng hình | vàng trắng, màu hươu đama | 黇 thuộc bộ 黃 (hoàng — màu vàng). Wiktionary không phân tích glyph origin rõ ràng. Nghĩa: màu vàng trắng, dùng trong 黇鹿 (hươu đama — fallow deer). Có hình tiểu triện. Chưa xác định cấu trúc từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiêm\": bộ 黃 (vàng) — màu thiêm là vàng nhạt pha trắng, màu lông hươu đama đặc trưng. | Gương Hán-Việt | thiêm — âm Hán-Việt, mô tả màu sắc vàng trắng đặc biệt | Mở khoá kiến thức | Biết 黇 mở khoá từ 黇鹿 (hươu đama) và nhóm chữ bộ 黃 chỉ màu sắc cổ.", "Tự nguyên_Xie": "Tiểu triện | 黇 thuộc bộ 黃 (hoàng — vàng). Wiktionary ghi: màu vàng trắng (obs-std), dùng chủ yếu trong từ ghép 黇鹿 (hươu đama). Có hình tiểu triện trong kho ảnh. Glyph origin không được phân tích chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hươu đama", "Hạng Tần Suất (Jun Da)": "7805.0", "Tần Suất % (Jun Da)": "99.9990237929", "GavinGrover_Once (Chiết tự trực tiếp)": "黄 + 占", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰黄占", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "占", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黄", "Unihan_Simplified (Chữ Giản thể)": "黇", "Unihan_Traditional (Chữ Phồn thể)": "黇", "Pinyin_Xie": "tiān", "Âm Hán Việt_Xie": "chiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường dùng làm tính từ chỉ màu sắc hoặc danh từ chỉ một loài hươu trong văn bản cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黡', '{"9000": "7806.0", "Chữ Trung Quốc": "黡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黑 | Số nét | 18 | nét | 黡 | yểm | tượng hình | nốt ruồi, vết thâm đen trên da | 黡 là dạng giản lược của 黶 (thay 厭 bằng 厌). Bộ 黑 (hắc — đen). Wiktionary ghi: {{Han simp|黶|f=厭|t=厌}}, tức là dạng giản thể của 黶. Nghĩa: nốt ruồi, vết bầm đen. Có hình tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yểm\": bộ 黑 (đen) — nốt ruồi yểm đen nổi trên da, như dấu vết định mệnh. | Gương Hán-Việt | yểm — dùng trong \"yểm bùa\" (vết đen huyền bí); nốt ruồi mang màu sắc huyền ảo | Mở khoá kiến thức | Biết 黡 mở khoá nhóm chữ bộ 黑 chỉ vết đen, nốt sậm trên da và bề mặt.", "Tự nguyên_Xie": "Tiểu triện | 黡 là dạng giản lược của 黶, thay thành phần 厭 bằng 厌. Bộ 黑 (hắc — đen). Wiktionary dẫn sang 黶 như từ đầy đủ. Nghĩa: nốt ruồi, vết đen trên da. Có hình tiểu triện trong kho ảnh. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nốt ruồi", "Hạng Tần Suất (Jun Da)": "7806.0", "Tần Suất % (Jun Da)": "99.9990248265", "GavinGrover_Once (Chiết tự trực tiếp)": "厌 + 黑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厌黑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黑", "Unihan_Simplified (Chữ Giản thể)": "黡", "Unihan_Traditional (Chữ Phồn thể)": "黶", "Pinyin_Xie": "yǎn", "Âm Hán Việt_Xie": "yểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ nốt ruồi hoặc vết đen trên cơ thể, xuất hiện trong các từ ghép y học cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齣', '{"9000": "7807.0", "Chữ Trung Quốc": "齣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 20 | nét | 齒 | xỉ | biểu nghĩa | răng | 句 | câu | biểu âm | câu văn — cho âm | 齣 = 齒 (Xỉ, biểu nghĩa: răng — gợi sự rõ nét, rành rọt từng tiết) + 句 (Câu, biểu âm, cho âm chū/xuất). Chữ hình thanh: 齒 là phần biểu nghĩa, 句 là phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xuất\": 齒 (răng, rõ từng nét) + 句 (câu văn) — mỗi màn xuất của vở kịch rành rọt như từng câu, từng hồi. | Gương Hán-Việt | xuất — dùng trong \"xuất hiện\", \"một xuất kịch\" (một màn kịch) | Mở khoá kiến thức | Biết 齣 mở khoá cách đếm màn kịch trong văn bản cổ điển và tiếng Quảng, Mân.", "Tự nguyên_Xie": "齣 là chữ hình thanh (psc): 齒 (xỉ — răng) biểu nghĩa, 句 (câu) biểu âm cho âm chū. Wiktionary định nghĩa: lượng từ cho vở kịch, hồi/màn. Cũng dùng cho phim ảnh (Quảng Đông), kịch (Mân Nam). Có nghĩa mở rộng: rắc rối, phiền toái. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngoài", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "齒 + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齒句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齒", "Unihan_Simplified (Chữ Giản thể)": "齣", "Unihan_Traditional (Chữ Phồn thể)": "齣", "Pinyin_Xie": "chū", "Âm Hán Việt_Xie": "xuất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Thường dùng làm lượng từ cho các vở kịch, tuồng chèo hoặc bộ phim. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眅', '{"9000": "7808.0", "Chữ Trung Quốc": "眅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 9 | nét | 眅 | phán | tượng hình | lộ lòng trắng mắt | 眅 thuộc bộ 目 (mục — mắt). Wiktionary ghi {{Han etym}} không phân tích glyph origin. Nghĩa: lộ lòng trắng mắt. Có hình tiểu triện. Chưa xác định cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phán\": bộ 目 (mắt) — mắt lộ trắng dã, như ánh mắt phán xét gay gắt. | Gương Hán-Việt | phán — âm Hán-Việt liên quan cái nhìn rõ ràng, lộ mắt | Mở khoá kiến thức | Biết 眅 mở khoá nhóm chữ bộ 目 chỉ trạng thái và đặc điểm của mắt.", "Tự nguyên_Xie": "Tiểu triện | 眅 thuộc bộ 目 (mục — mắt). Wiktionary không định nghĩa rõ ràng (rfdef). Nghĩa Việt: hiển thị lòng trắng của mắt. Phát âm pān. Có hình tiểu triện trong kho ảnh. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hiển thị lòng trắng của mắt", "Hạng Tần Suất (Jun Da)": "7808.0", "Tần Suất % (Jun Da)": "99.9990279272", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 反", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目反", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "反", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眅", "Unihan_Traditional (Chữ Phồn thể)": "眅", "Pinyin_Xie": "pān", "Âm Hán Việt_Xie": "ban", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ mô tả trạng thái của mắt khi trợn lên hoặc bị bệnh về mắt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磈', '{"9000": "7809.0", "Chữ Trung Quốc": "磈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 14 | nét | 磈 | nguy | tượng hình | đá chất đống, ưu tư chất chứa | 磈 thuộc bộ 石 (thạch — đá). Wiktionary ghi {{Han etym}} nhưng không phân tích glyph origin. Nghĩa: đá chất đống; ưu phiền tích tụ. Chưa xác định cấu trúc từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nguy\": bộ 石 (đá) — đá nguy nga chất đống, lòng nặng như đá, nguy cơ sụp đổ. | Gương Hán-Việt | nguy — âm Hán-Việt gợi sự nặng nề, tích tụ như đá | Mở khoá kiến thức | Biết 磈 mở khoá nhóm chữ bộ 石 chỉ trạng thái đá và nỗi lòng nặng nề trong thơ cổ.", "Tự nguyên_Xie": "磈 thuộc bộ 石 (thạch — đá). Wiktionary không định nghĩa rõ ràng (rfdef). Nghĩa Việt: đá đổ đống, ưu tư chất chứa trong lòng. Phát âm wěi/kuǐ. Glyph origin không được mô tả. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá đổ đống; đá chất đống; ưu tư; ưu phiền; phiền muộn (nỗi ưu tư chất chứa trong lòng)", "Hạng Tần Suất (Jun Da)": "7809.0", "Tần Suất % (Jun Da)": "99.9990289607", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 鬼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石鬼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鬼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磈", "Unihan_Traditional (Chữ Phồn thể)": "磈", "Pinyin_Xie": "wěi", "Âm Hán Việt_Xie": "uỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ miêu tả địa hình hiểm trở hoặc trạng thái tâm lý lo âu, phiền muộn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磳', '{"9000": "7810.0", "Chữ Trung Quốc": "磳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 17 | nét | 磳 | tằng | tượng hình | đá nhọn gồ ghề | 磳 thuộc bộ 石 (thạch — đá). Wiktionary ghi {{Han etym}} không phân tích cấu trúc. Dùng trong từ ghép 碅磳, 砸磳. Chưa xác định rõ hình thanh hay hội ý từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tằng\": bộ 石 (đá) — đá nhọn tằng tằng lởm chởm, như bậc đá tầng tầng. | Gương Hán-Việt | tằng — âm Hán-Việt gợi sự nhô lên từng lớp của đá | Mở khoá kiến thức | Biết 磳 mở khoá nhóm chữ bộ 石 chỉ địa hình đá gồ ghề nhọn sắc.", "Tự nguyên_Xie": "磳 thuộc bộ 石 (thạch — đá). Wiktionary không định nghĩa rõ (rfdef), dùng trong từ ghép 碅磳 (đá lởm chởm) và 砸磳. Phát âm zēng. Chưa có nguồn học thuật về glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "糳", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 曾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石曾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磳", "Unihan_Traditional (Chữ Phồn thể)": "磳", "Pinyin_Xie": "zēng", "Âm Hán Việt_Xie": "tằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ miêu tả sự cao lớn, hiểm trở của núi đá. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窅', '{"9000": "7811.0", "Chữ Trung Quốc": "窅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 10 | nét | 窅 | yểu | tượng hình | hố sâu thẳm, mắt trũng sâu | 窅 thuộc bộ 穴 (huyệt — hố lõm). Wiktionary không cung cấp glyph origin. Có nhiều hình ảnh tiểu triện và Lục thư thông trong kho ảnh. Nghĩa: sâu thẳm, lặng bặt xa xôi; mắt trũng sâu. Chưa xác định cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yểu\": bộ 穴 (hố) — hố yểu sâu tăm tối, như đôi mắt yểu buồn trũng sâu không đáy. | Gương Hán-Việt | yểu — dùng trong \"yểu điệu\" (xa xôi mờ ảo), \"yểu mệnh\" (mờ tối không rõ) | Mở khoá kiến thức | Biết 窅 mở khoá nhóm chữ bộ 穴 chỉ sự sâu thẳm, u ám trong thơ cổ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 窅 thuộc bộ 穴 (huyệt — hố lõm, hang sâu). Wiktionary không cung cấp glyph origin. Nghĩa: sâu thẳm mờ xa; mắt trũng (sunken eyes); buồn. Có nhiều hình tiểu triện và Lục thư thông trong kho ảnh. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mờ mịt, lặng bặt; sâu thẳm", "Hạng Tần Suất (Jun Da)": "7811.0", "Tần Suất % (Jun Da)": "99.9990320614", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 目", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴目", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "目", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窅", "Unihan_Traditional (Chữ Phồn thể)": "窅", "Pinyin_Xie": "yǎo", "Âm Hán Việt_Xie": "yểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ để tả đôi mắt sâu hoặc không gian sâu thẳm, yên ắng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窾', '{"9000": "7812.0", "Chữ Trung Quốc": "窾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 17 | nét | 窾 | khoan | tượng hình | lỗ hổng, khoảng rỗng | 窾 thuộc bộ 穴 (huyệt — hố lõm). Wiktionary không cung cấp glyph origin. Nghĩa: chỗ hở rỗng, khoảng trống. Chưa xác định cấu trúc chi tiết từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoan\": bộ 穴 (hố) — bên trong khoan rỗng như cái hang không có gì. | Gương Hán-Việt | khoan — âm Hán-Việt liên quan sự rỗng, khoảng trống | Mở khoá kiến thức | Biết 窾 mở khoá nhóm chữ bộ 穴 chỉ sự rỗng ruột, hố lõm trong văn bản triết học cổ.", "Tự nguyên_Xie": "窾 thuộc bộ 穴 (huyệt — hang, hố rỗng). Wiktionary không cung cấp glyph origin. Nghĩa: lỗ hổng, rỗng bên trong. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỗ hở ra; rỗng", "Hạng Tần Suất (Jun Da)": "7812.0", "Tần Suất % (Jun Da)": "99.999033095", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 款", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴款", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "款", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窾", "Unihan_Traditional (Chữ Phồn thể)": "窾", "Pinyin_Xie": "kuǎn", "Âm Hán Việt_Xie": "khoản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ khoảng trống, khe hở hoặc tính từ chỉ trạng thái trống rỗng, không có thực chất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筭', '{"9000": "7813.0", "Chữ Trung Quốc": "筭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 13 | nét | 筭 | toán | tượng hình | que tính cổ đại, dụng cụ toán học | 筭 thuộc bộ 竹 (trúc — tre). Wiktionary ghi {{Han etym}} nhưng không phân tích cụ thể. Nghĩa: dụng cụ tính đếm bằng que tre thời cổ; dạng thay thế của 算 (tính toán). Có hình tiểu triện trong kho ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toán\": bộ 竹 (tre) — những que tre dùng toán toán số, dụng cụ tính cổ nhất của người Hoa. | Gương Hán-Việt | toán — dùng trong \"toán học\" (数学), \"toán số\" (tính số) | Mở khoá kiến thức | Biết 筭 mở khoá dạng cổ của 算 và nhóm chữ bộ 竹 chỉ công cụ tre trong lịch sử.", "Tự nguyên_Xie": "Tiểu triện | 筭 thuộc bộ 竹 (trúc — tre). Wiktionary định nghĩa: dụng cụ cổ đại dùng tính số (que tính bằng tre); chiến lược, sách lược; dạng thay thế của 算 (tính toán). Có hình tiểu triện trong kho ảnh. Glyph origin không phân tích chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tính toán", "Hạng Tần Suất (Jun Da)": "7813.0", "Tần Suất % (Jun Da)": "99.9990341286", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "筭", "Unihan_Traditional (Chữ Phồn thể)": "筭", "Pinyin_Xie": "suàn", "Âm Hán Việt_Xie": "toán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành vi tính toán, lập kế hoạch hoặc danh từ chỉ công cụ tính toán thời xưa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箣', '{"9000": "7814.0", "Chữ Trung Quốc": "箣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 箣 | trắc | tượng hình | tầm vông, tre gai | 箣 thuộc bộ 竹 (trúc — tre). Wiktionary không cung cấp glyph origin. Nghĩa Việt: tầm vông — loại tre đặc, gai. Chưa xác định cấu trúc từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trắc\": bộ 竹 (tre) — cây tầm vông trắc trở, gai nhọn khó gần. | Gương Hán-Việt | trắc — âm Hán-Việt, liên quan loại tre gai trong văn hóa Nam Bộ Việt Nam | Mở khoá kiến thức | Biết 箣 mở khoá nhóm chữ bộ 竹 chỉ các loài tre và cây họ tre đặc thù.", "Tự nguyên_Xie": "箣 thuộc bộ 竹 (trúc — tre). Wiktionary không cung cấp glyph origin. Nghĩa: tầm vông, một loại tre đặc thân to gai nhọn, dùng làm hàng rào. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tầm vông", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 刺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮刺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箣", "Unihan_Traditional (Chữ Phồn thể)": "箣", "Pinyin_Xie": "cè", "Âm Hán Việt_Xie": "sách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp với các từ khác để chỉ một loại tre hoặc roi tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簃', '{"9000": "7815.0", "Chữ Trung Quốc": "簃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 17 | nét | 竹 | trúc | biểu nghĩa | tre, vật liệu xây cất | 移 | di | biểu âm | di chuyển — cho âm yí/di | 簃 = 竹 (Trúc, biểu nghĩa: tre — vật liệu xây cất) + 移 (Di, biểu âm, cho âm yí). Chữ hình thanh: 竹 chỉ ý nghĩa (công trình bằng tre), 移 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\": 竹 (tre) + 移 (di chuyển) — gian phòng di chuyển sang bên cạnh, nhỏ bé nhưng yên tĩnh để đọc sách. | Gương Hán-Việt | di — âm gợi sự di chuyển, phòng nhỏ tách ra một bên | Mở khoá kiến thức | Biết 簃 mở khoá hình ảnh phòng đọc sách trong vườn trúc của học giả cổ.", "Tự nguyên_Xie": "Tiểu triện | 簃 là chữ hình thanh (psc) theo Wiktionary: 竹 (trúc — tre) là phần biểu nghĩa, 移 là phần biểu âm cho âm yí. Nghĩa: phòng nhỏ bên cạnh công trình lớn hơn; căn lều nhỏ kề đình tạ — thường dùng đặt tên phòng đọc sách. Có hình tiểu triện trong kho ảnh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phòng nhỏ; phòng đọc sách", "Hạng Tần Suất (Jun Da)": "7815.0", "Tần Suất % (Jun Da)": "99.9990361957", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 移", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮移", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "移", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簃", "Unihan_Traditional (Chữ Phồn thể)": "簃", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ gian phòng nhỏ hoặc thư phòng thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簺', '{"9000": "7816.0", "Chữ Trung Quốc": "簺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 19 | nét | 簺 | tái | tượng hình | trò đánh bạc bằng tre cổ đại | 簺 thuộc bộ 竹 (trúc — tre). Wiktionary ghi {{Han etym}} nhưng không phân tích glyph origin chi tiết. Nghĩa: trò đánh bạc cổ đại; dụng cụ bắt cá bằng tre. Chưa xác định cấu trúc từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tái\": bộ 竹 (tre) — trò tái chơi cờ bạc bằng que tre, ăn thua bằng những lần tái lại. | Gương Hán-Việt | tái — âm Hán-Việt liên quan trò chơi có yếu tố đỏ đen | Mở khoá kiến thức | Biết 簺 mở khoá nhóm chữ bộ 竹 chỉ đồ dùng và trò chơi bằng tre trong văn hóa cổ.", "Tự nguyên_Xie": "簺 thuộc bộ 竹 (trúc — tre). Wiktionary định nghĩa: trò cờ bạc cổ đại và dụng cụ bắt cá bằng tre. Glyph origin không được phân tích. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "簰", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 塞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮塞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "塞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簺", "Unihan_Traditional (Chữ Phồn thể)": "簺", "Pinyin_Xie": "sài", "Âm Hán Việt_Xie": "tái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ một loại cờ cổ hoặc động từ chỉ việc chơi cờ này. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粴', '{"9000": "7817.0", "Chữ Trung Quốc": "粴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 13 | nét | 粴 | lý | tượng hình | chất gạo, phẩm chất ngũ cốc | 粴 thuộc bộ 米 (mễ — gạo). Wiktionary không cung cấp glyph origin. Chưa xác định cấu trúc từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lý\": bộ 米 (gạo) — chất lý bên trong hạt gạo, phẩm chất tinh tế của ngũ cốc. | Gương Hán-Việt | lý — âm Hán-Việt liên quan phẩm chất, lý lẽ bên trong | Mở khoá kiến thức | Biết 粴 mở khoá nhóm chữ bộ 米 chỉ các tính chất và chế phẩm từ gạo.", "Tự nguyên_Xie": "粴 thuộc bộ 米 (mễ — gạo). Wiktionary không cung cấp glyph origin hoặc định nghĩa rõ ràng. Nghĩa chưa rõ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "粴", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 里", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米里", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "里", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粴", "Unihan_Traditional (Chữ Phồn thể)": "粴", "Pinyin_Xie": "lǐ", "Âm Hán Việt_Xie": "lý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Dùng làm lượng từ để đo chiều dài trong hệ mét. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糦', '{"9000": "7818.0", "Chữ Trung Quốc": "糦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 18 | nét | 糦 | hí | tượng hình | ngũ cốc cúng tế | 糦 thuộc bộ 米 (mễ — gạo, ngũ cốc). Wiktionary ghi {{Han etym}} không phân tích glyph origin chi tiết. Nghĩa chưa rõ ràng (rfdef). Chưa xác định cấu trúc từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hí\": bộ 米 (gạo) — gạo hí dâng cúng trong lễ tế, ngũ cốc thiêng liêng nhất. | Gương Hán-Việt | hí — âm Hán-Việt liên quan ngũ cốc lễ nghi | Mở khoá kiến thức | Biết 糦 mở khoá nhóm chữ bộ 米 chỉ lương thực trong lễ nghi và văn bản cúng tế cổ.", "Tự nguyên_Xie": "糦 thuộc bộ 米 (mễ — gạo). Wiktionary không định nghĩa rõ (rfdef). Phát âm chì/xī. Liên quan ngũ cốc dùng trong tế lễ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "禳", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 喜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米喜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "糦", "Unihan_Traditional (Chữ Phồn thể)": "糦", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ đồ ăn hoặc cơm dùng trong tế lễ ngày xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絟', '{"9000": "7819.0", "Chữ Trung Quốc": "絟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 絟 | quyến | tượng hình | loại lụa mỏng, vải mịn | 絟 thuộc bộ 糸 (mịch — sợi chỉ, vải). Wiktionary không cung cấp glyph origin. Nghĩa chưa rõ. Chưa xác định cấu trúc từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyến\": bộ 糸 (sợi chỉ) — vải lụa quyến quyến mỏng mịn, cuộn lại dễ dàng. | Gương Hán-Việt | quyến — âm Hán-Việt liên quan vải lụa và sợi chỉ mịn | Mở khoá kiến thức | Biết 絟 mở khoá nhóm chữ bộ 糸 chỉ các loại vải và sợi chỉ đặc thù.", "Tự nguyên_Xie": "絟 thuộc bộ 糸 (mịch — sợi chỉ, lụa). Wiktionary không cung cấp glyph origin hoặc định nghĩa. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "絟", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 全", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹全", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "全", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "絟", "Unihan_Traditional (Chữ Phồn thể)": "絟", "Pinyin_Xie": "quán", "Âm Hán Việt_Xie": "quyến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loại vải mịn hoặc dây thừng nhỏ thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('緺', '{"9000": "7820.0", "Chữ Trung Quốc": "緺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 14 | nét | 緺 | oa | tượng hình | màu tím xanh, búi chỉ tím | 緺 thuộc bộ 糸 (mịch — sợi chỉ). Wiktionary ghi {{Han etym}} nhưng chỉ cho biết dùng trong phiên thiết (Fanqie transcription). Nghĩa: màu tím xanh; búi tua chỉ. Chưa xác định cấu trúc từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oa\": bộ 糸 (sợi chỉ) — sợi chỉ màu oa tím xanh xoắn ốc, búi tua trang trí quan phục. | Gương Hán-Việt | oa — âm Hán-Việt, màu tím xanh đặc trưng của quan phục cổ | Mở khoá kiến thức | Biết 緺 mở khoá nhóm chữ bộ 糸 chỉ màu sắc và kiểu dệt vải lụa trong văn hóa quan trường cổ.", "Tự nguyên_Xie": "緺 thuộc bộ 糸 (mịch — sợi chỉ). Wiktionary ghi: dùng trong phiên thiết (Fanqie transcription). Nghĩa: màu tím xanh, búi tua chỉ. Glyph origin không được phân tích. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màu tím xanh; búi, mớ, túm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 咼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹咼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "緺", "Unihan_Traditional (Chữ Phồn thể)": "緺", "Pinyin_Xie": "guā", "Âm Hán Việt_Xie": "oa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ dây đeo ấn tín của quan lại thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('縩', '{"9000": "7821.0", "Chữ Trung Quốc": "縩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 17 | nét | 縩 | thải | tượng hình | tiếng vải sột soạt | 縩 thuộc bộ 糸 (mịch — sợi chỉ, vải). Wiktionary không cung cấp glyph origin. Dùng chủ yếu trong từ ghép 綷縩 (tiếng vải sột soạt). Chưa xác định cấu trúc từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thải\": bộ 糸 (vải) — tiếng thải thải của vạt lụa thướt tha cọ nhau khi bước đi. | Gương Hán-Việt | thải — âm Hán-Việt gợi âm thanh vải lụa chuyển động | Mở khoá kiến thức | Biết 縩 mở khoá từ ghép 綷縩 trong thơ cổ mô tả chuyển động của y phục.", "Tự nguyên_Xie": "縩 thuộc bộ 糸 (mịch — sợi chỉ, lụa). Wiktionary không cung cấp glyph origin. Nghĩa: xem 綷縩 (tiếng vải sột soạt khi di chuyển). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tuý sái 綷縩)", "Hạng Tần Suất (Jun Da)": "7821.0", "Tần Suất % (Jun Da)": "99.9990423971", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 祭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹祭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "祭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "縩", "Unihan_Traditional (Chữ Phồn thể)": "縩", "Pinyin_Xie": "cài", "Âm Hán Việt_Xie": "sái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Tính từ | 形容词 | Thường kết hợp thành từ láy để mô tả âm thanh của trang phục khi di chuyển. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罍', '{"9000": "7822.0", "Chữ Trung Quốc": "罍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 缶 | Số nét | 21 | nét | 罍 | lôi | tượng hình | bình rượu lớn miệng nhỏ | 罍 thuộc bộ 缶 (phẫu — bình, vò đất). Wiktionary ghi {{Han etym}} không phân tích glyph origin cụ thể. Nghĩa: bình rượu lớn miệng nhỏ, có tay cầm và nắp, dùng trong lễ nghi cổ. Có hình tiểu triện trong kho ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lôi\": bộ 缶 (bình đất) — chiếc bình lôi to đùng, miệng nhỏ như tiếng sấm lôi cất tiếng ở bàn tiệc. | Gương Hán-Việt | lôi — âm gợi sấm sét, nhưng 罍 là bình rượu lớn trong tiệc cổ | Mở khoá kiến thức | Biết 罍 mở khoá nhóm chữ bộ 缶 chỉ bình vò đồ gốm và đồ dùng lễ nghi cổ đại.", "Tự nguyên_Xie": "Tiểu triện | 罍 thuộc bộ 缶 (phẫu — bình đất). Wiktionary định nghĩa: lei — loại bình rượu lớn miệng nhỏ, hai tay cầm, có nắp, dùng trong nghi lễ. Từ ghép: 金罍, 瓶罄罍恥. Có hình tiểu triện trong kho ảnh. Glyph origin không phân tích chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chén uống rượu", "Hạng Tần Suất (Jun Da)": "7822.0", "Tần Suất % (Jun Da)": "99.9990434307", "GavinGrover_Once (Chiết tự trực tiếp)": "畾 + 缶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱畾缶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "缶", "Unihan_Simplified (Chữ Giản thể)": "罍", "Unihan_Traditional (Chữ Phồn thể)": "罍", "Pinyin_Xie": "léi", "Âm Hán Việt_Xie": "lôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loại bình rượu bằng đồng hoặc gỗ thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翣', '{"9000": "7823.0", "Chữ Trung Quốc": "翣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 14 | nét | 翣 | sáp | tượng hình | quạt lông trang trí quan tài; quạt lớn bằng gỗ | 翣 thuộc bộ 羽 (vũ — lông vũ). Wiktionary không cung cấp glyph origin. Nghĩa: lông vũ trang trí quan tài; quạt lớn bằng gỗ. Chưa xác định cấu trúc từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sáp\": bộ 羽 (lông vũ) — lông chim sáp vào quan tài và quạt lớn trong lễ tang quý tộc. | Gương Hán-Việt | sáp — âm Hán-Việt gợi sự gắn kết, sáp nhập vào lễ nghi tang lễ | Mở khoá kiến thức | Biết 翣 mở khoá nhóm chữ bộ 羽 chỉ đồ dùng lông vũ trong tang lễ và lễ nghi cổ.", "Tự nguyên_Xie": "翣 thuộc bộ 羽 (vũ — lông vũ). Wiktionary không cung cấp glyph origin. Nghĩa: lông vũ dùng trang trí quan tài; quạt lớn bằng gỗ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái quạt vả", "Hạng Tần Suất (Jun Da)": "7823.0", "Tần Suất % (Jun Da)": "99.9990444643", "GavinGrover_Once (Chiết tự trực tiếp)": "羽 + 妾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羽妾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "妾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翣", "Unihan_Traditional (Chữ Phồn thể)": "翣", "Pinyin_Xie": "shà", "Âm Hán Việt_Xie": "sáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ nghi trượng hình chiếc quạt lớn trong tang lễ xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聟', '{"9000": "7824.0", "Chữ Trung Quốc": "聟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 14 | nét | 夫 | phu | biểu nghĩa | người đàn ông, phu quân | 咠 | nghiện | biểu âm | cho âm xù/tế | 聟 = 夫 (Phu, biểu nghĩa — nhưng đã bị biến dạng thành 矢 trong thực tế viết) + 咠 (biểu âm). Wiktionary ghi: {{Han compound|c1=s|c2=p|夫|咠}}; 夫 bị hỏng thành 矢. Là dạng biến thể của 婿 (rể).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tế\": 夫 (người đàn ông, biến dạng thành 矢) + 咠 (biểu âm) — người đàn ông tế gia nhập gia đình nhà vợ. | Gương Hán-Việt | tế — dùng trong \"con tế\" (con rể), \"phụ tế\" (con rể phụ) | Mở khoá kiến thức | Biết 聟/婿 mở khoá: 女婿 (con rể), cách gọi quan hệ hôn nhân trong gia đình Hán-Việt.", "Tự nguyên_Xie": "聟 là dạng biến thể của 婿 (tế — con rể). Wiktionary ghi: hình thanh với 夫 (phu — người đàn ông) biểu nghĩa, 咠 biểu âm; nhưng thành phần 夫 đã bị hỏng biến thành 矢 trong quá trình truyền chép. Nghĩa: con rể, chồng. Wiktionary dẫn sang 婿 như từ chuẩn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蟟", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "知 + 耳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱知耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "知", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聟", "Unihan_Traditional (Chữ Phồn thể)": "聟", "Pinyin_Xie": "xù", "Âm Hán Việt_Xie": "tế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để gọi con rể, là biến thể cổ của chữ tế. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肊', '{"9000": "7825.0", "Chữ Trung Quốc": "肊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 5 | nét | 肊 | ức | tượng hình | ngực, lồng ngực | 肊 thuộc bộ 肉 (nhục — thịt, cơ thể). Wiktionary không cung cấp glyph origin. Nghĩa: ngực. Có hình đại triện và tiểu triện trong kho ảnh. Chưa xác định cấu trúc từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ức\": bộ 肉 (cơ thể) — phần ức ngực, nơi chứa tim gan ức chế xúc cảm. | Gương Hán-Việt | ức — dùng trong \"tức ức\" (ngực tức), \"ức đoán\" (đoán trong lòng) | Mở khoá kiến thức | Biết 肊 mở khoá nhóm chữ bộ 肉 chỉ các bộ phận ngực và cơ thể trên.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 肊 thuộc bộ 肉 (nhục — thịt, phần cơ thể). Wiktionary không cung cấp glyph origin. Nghĩa: ngực, lồng ngực. Có hình đại triện và tiểu triện trong kho ảnh. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngực", "Hạng Tần Suất (Jun Da)": "7825.0", "Tần Suất % (Jun Da)": "99.9990465314", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + ㇠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月㇠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肊", "Unihan_Traditional (Chữ Phồn thể)": "肊", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ bộ phận ngực của người hoặc động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肙', '{"9000": "7826.0", "Chữ Trung Quốc": "肙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 7 | nét | 肙 | quyên | tượng hình | con sâu nhỏ; rỗng; vòng quanh | 肙 thuộc bộ 肉 (nhục — thịt, sinh vật). Wiktionary ghi {{Han etym}} không phân tích glyph origin chi tiết. Nghĩa: con sâu nhỏ; xoắn vòng; vây quanh; rỗng. Có hình kim văn, đại triện và tiểu triện trong kho ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyên\": bộ 肉 (sinh vật) — con sâu quyên quyên nhỏ bé, cuộn xoắn vòng trong không gian rỗng. | Gương Hán-Việt | quyên — âm liên quan sự tròn xoắn, mềm yếu nhỏ bé | Mở khoá kiến thức | Biết 肙 mở khoá nhóm chữ bộ 肉 chỉ sinh vật nhỏ và hành động vòng xoắn.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | 肙 thuộc bộ 肉 (nhục). Wiktionary định nghĩa: con sâu nhỏ; xoắn; bao quanh; rỗng. Phát âm yuàn. Có hình kim văn, đại triện và tiểu triện trong kho ảnh. Glyph origin không phân tích chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một con sâu nhỏ; trống; bao quanh; xoắn", "Hạng Tần Suất (Jun Da)": "7826.0", "Tần Suất % (Jun Da)": "99.999047565", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 月", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱口月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "月", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "肙", "Unihan_Traditional (Chữ Phồn thể)": "肙", "Pinyin_Xie": "yuàn", "Âm Hán Việt_Xie": "quyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Tính từ | 形容词 | Dùng làm danh từ chỉ ấu trùng muỗi hoặc động từ chỉ sự uốn lượn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肞', '{"9000": "7827.0", "Chữ Trung Quốc": "肞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 7 | nét | 肞 | sá | tượng hình | loại thịt hoặc sinh vật nhỏ | 肞 thuộc bộ 肉 (nhục — thịt). Wiktionary không cung cấp glyph origin. Nghĩa chưa rõ (liên quan sâu nhỏ theo nghĩa Việt). Chưa xác định cấu trúc từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sá\": bộ 肉 (thịt) — sinh vật nhỏ sá như thịt vụn, ít ai để ý. | Gương Hán-Việt | sá — âm Hán-Việt ít phổ biến, liên quan sinh vật hoặc thịt nhỏ | Mở khoá kiến thức | Biết 肞 mở khoá nhóm chữ bộ 肉 chỉ các sinh vật nhỏ trong văn bản tự nhiên cổ.", "Tự nguyên_Xie": "肞 thuộc bộ 肉 (nhục — thịt, sinh vật). Wiktionary không cung cấp glyph origin hoặc định nghĩa rõ ràng. Nghĩa Việt ghi là liên quan loài sâu. Phát âm chā. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "螞", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 叉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月叉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肞", "Unihan_Traditional (Chữ Phồn thể)": "肞", "Pinyin_Xie": "chā", "Âm Hán Việt_Xie": "sá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ để chỉ phần thịt ở đùi hoặc hông của động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臞', '{"9000": "7828.0", "Chữ Trung Quốc": "臞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 22 | nét | ⺼ | nhục | biểu nghĩa | thịt, thân xác | 瞿 | cự | biểu âm | nhìn sợ hãi | 臞 là chữ hình thanh: ⺼ (Nhục, biểu nghĩa: thịt/thân xác) + 瞿 (Cự, biểu âm); thịt người tiêu hao gầy còm — cấu trúc psc theo Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cừ\": ⺼ (thịt) + 瞿 (mắt trợn sợ) — thân xác gầy tong teo đến mức nhìn mà sợ. | Gương Hán-Việt | ít dùng trong tiếng Việt hiện đại; xuất hiện trong văn ngôn cổ chỉ người tiều tụy | Mở khoá kiến thức | Biết 臞 giúp đọc văn cổ nói về hình thể tiều tụy, gầy gò vì khổ não.", "Tự nguyên_Xie": "Theo Wiktionary: 臞 là chữ hình thanh, ghép từ ⺼ (bộ nhục/thịt, biểu nghĩa: thịt, thân xác gầy mòn) và 瞿 (biểu âm, cho âm đọc gần qú). Ý nghĩa: gầy gò, tiều tụy vì mòn mỏi thịt xác. Văn ngữ dẫn Hàn Phi Tử: kẻ trong lòng mâu thuẫn giữa nghĩa và lợi, chưa phân thắng bại nên thân thể hao mòn 臞. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gầy gò", "Hạng Tần Suất (Jun Da)": "7828.0", "Tần Suất % (Jun Da)": "99.9990496321", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 瞿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月瞿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瞿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臞", "Unihan_Traditional (Chữ Phồn thể)": "臞", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "cù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả dáng vẻ gầy gò, ốm yếu của người hoặc động vật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苶', '{"9000": "7829.0", "Chữ Trung Quốc": "苶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 苶 | niết | tượng hình | cỏ héo rũ, mệt mỏi | 苶 là chữ độc thể, bộ thủ là 艸 (thảo/cỏ). Không có nguồn phân tích hình thanh rõ ràng; hình dáng gợi cỏ yếu ớt, rũ xuống — ẩn dụ sự mệt mỏi, bơ phờ. Cấu trúc không xác định được theo IDS.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niết\": cỏ (艸) rũ héo — người mệt lả như cọng cỏ tàn, bơ phờ không còn sức sống. | Gương Hán-Việt | ít dùng trong tiếng Việt; xuất hiện trong văn ngôn cổ chỉ trạng thái tiều tụy | Mở khoá kiến thức | Biết 苶 giúp đọc thơ văn ngôn nói về sự suy nhược, bơ phờ của con người hay xã hội.", "Tự nguyên_Xie": "Theo Wiktionary: 苶 là chữ cổ chỉ trạng thái mệt mỏi, bơ phờ, uể oải. Thuộc bộ 艸 (thảo/cỏ). Có nghĩa phái sinh: xã hội suy tàn, tinh thần sa sút. Thơ Hoàng Tuân Hiến (cuối thế kỷ 19) dùng 苶 tả xã hội Đông Hán suy vi. Chưa có nguồn phân tích cấu tạo học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mệt mỏi, bơ phờ, phờ phạc", "Hạng Tần Suất (Jun Da)": "7829.0", "Tần Suất % (Jun Da)": "99.9990506657", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 尒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹尒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苶", "Unihan_Traditional (Chữ Phồn thể)": "苶", "Pinyin_Xie": "nié", "Âm Hán Việt_Xie": "niết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ biểu thị trạng thái mệt mỏi, thiếu sức sống của con người hoặc cây cỏ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菭', '{"9000": "7830.0", "Chữ Trung Quốc": "菭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菭 | đài | tượng hình | rêu, địa y mọc trên đất ẩm | 菭 là dạng cổ/dị thể của 苔 (đài/rêu). Bộ 艸 (thảo/cỏ) là thành phần ngữ nghĩa chính, chỉ loại thực vật nhỏ mọc nơi ẩm ướt. Cấu trúc cụ thể không xác định được theo IDS.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đài\": bộ 艸 (cỏ) + hình dạng mọc bám — như lớp rêu (đài) phủ trên tảng đá ẩm ướt. | Gương Hán-Việt | rêu phủ trong thơ cổ: \"đài phong\" (rêu xanh phủ dày) | Mở khoá kiến thức | Biết 菭/苔 (đài) giúp đọc thơ Đường tả cảnh hoang sơ: \"rêu xanh\" thường là dấu hiệu nơi vắng vẻ, cổ xưa.", "Tự nguyên_Xie": "Theo Wiktionary: 菭 là dạng cổ của 苔 (rêu, địa y). Bộ 艸 (thảo) chỉ nhóm thực vật. Có âm đọc tái/chí/zhī tuỳ phương ngữ. Nghĩa chính: rêu, địa y — loài thực vật nhỏ mọc bám trên đá, đất ẩm. Chưa có nguồn phân tích cấu tạo học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đầy; như \"đầy đặn; đầy đủ; tràn đầy\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 治", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹治", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "治", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菭", "Unihan_Traditional (Chữ Phồn thể)": "菭", "Pinyin_Xie": "tái", "Âm Hán Việt_Xie": "đài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ chỉ loài rêu hoặc làm tính từ chỉ sự đầy đặn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葖', '{"9000": "7831.0", "Chữ Trung Quốc": "葖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葖 | nhút | tượng hình | củ cải, quả nang | 葖 thuộc bộ 艸 (thảo/cỏ), chỉ loại thực vật. Không phân tích được cấu tạo IDS rõ ràng; chữ này chủ yếu xuất hiện trong từ ghép 蓇葖 (follicle/quả nang) và có nghĩa riêng là củ cải. Cấu trúc chưa xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhút\": bộ 艸 (cỏ) + hình dáng thân mập tròn — củ (nhút) như củ cải mọc dưới đất. | Gương Hán-Việt | ít dùng; \"nhút\" xuất hiện trong từ Hán-Việt cổ chỉ loại cây | Mở khoá kiến thức | Biết 葖 giúp đọc danh pháp thực vật cổ, đặc biệt từ 蓇葖 trong thực vật học.", "Tự nguyên_Xie": "Theo Wiktionary: 葖 nghĩa là củ cải (radish), thuộc bộ 艸. Xuất hiện chủ yếu trong từ ghép 蓇葖 (quả nang — loại quả khô của thực vật). Âm đọc tū. Chưa có nguồn phân tích cấu tạo học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: cốt đột 蓇葖)", "Hạng Tần Suất (Jun Da)": "7831.0", "Tần Suất % (Jun Da)": "99.9990527328", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 突", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹突", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "突", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葖", "Unihan_Traditional (Chữ Phồn thể)": "葖", "Pinyin_Xie": "tū", "Âm Hán Việt_Xie": "đột", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ trong các từ ghép thực vật học để chỉ loại quả tự nứt hoặc củ cải. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕳', '{"9000": "7832.0", "Chữ Trung Quốc": "蕳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕳 | giản | tượng hình | loại cỏ thơm, lan cỏ | 蕳 thuộc bộ 艸 (thảo/cỏ). Không có dữ liệu phân tích cấu tạo Wiktionary. Từ ngữ cảnh, đây là tên một loại cỏ thơm trong thi ca cổ (có thể là một dạng của 蘭 — lan). Cấu trúc chưa xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giản\": bộ 艸 (cỏ) — một loại cỏ thơm (giản) dùng trong thi ca cổ, gợi không khí thanh tao. | Gương Hán-Việt | ít dùng trong tiếng Việt hiện đại; xuất hiện trong thư tịch thi ca cổ | Mở khoá kiến thức | Biết 蕳 giúp nhận ra tên thảo mộc trong thơ ca cổ điển Trung Hoa.", "Tự nguyên_Xie": "蕳 là tên một loại cỏ thơm trong văn học cổ điển Trung Quốc, thuộc bộ 艸 (thảo/cỏ). Âm đọc jiān. Chưa có nguồn phân tích cấu tạo học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ gian (như cỏ lân)", "Hạng Tần Suất (Jun Da)": "7832.0", "Tần Suất % (Jun Da)": "99.9990537664", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 間", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹間", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "間", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕳", "Unihan_Traditional (Chữ Phồn thể)": "蕳", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "gian", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cỏ lan thơm thường xuất hiện trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚒', '{"9000": "7833.0", "Chữ Trung Quốc": "蚒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 蚒 | đồng | tượng hình | sâu bọ, dị thể cổ của 彤/赨 | 蚒 thuộc bộ 虫 (trùng/côn trùng). Theo Wiktionary, đây là dạng cổ/dị thể của 彤 (đỏ tươi) hoặc 赨. Không có phân tích cấu tạo IDS rõ ràng. Cấu trúc chưa xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\": bộ 虫 (trùng) — chữ cổ hiếm, dị thể của 彤 (đỏ tươi), gợi màu đỏ của côn trùng. | Gương Hán-Việt | ít dùng; dạng thông dụng là 彤 (đồng) nghĩa đỏ tươi | Mở khoá kiến thức | Biết 蚒 giúp nhận diện dị thể cổ trong thư tịch, liên hệ với 彤 (màu đỏ tươi).", "Tự nguyên_Xie": "Theo Wiktionary: 蚒 là dạng cổ của 彤 (đỏ tươi) hoặc 赨. Thuộc bộ 虫 (trùng). Âm đọc tóng. Đây là chữ hiếm gặp trong văn ngôn cổ; nghĩa cụ thể không xác định được ngoài vai trò dị thể. Chưa có nguồn phân tích cấu tạo học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giun đất", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 丹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫丹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚒", "Unihan_Traditional (Chữ Phồn thể)": "蚒", "Pinyin_Xie": "tóng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài giun đất trong tiếng Trung cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜪', '{"9000": "7834.0", "Chữ Trung Quốc": "蜪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 蜪 | đào | tượng hình | ấu trùng châu chấu | 蜪 thuộc bộ 虫 (trùng). Theo Wiktionary, 蜪 chỉ dùng trong từ ghép 蝮蜪 (ấu trùng châu chấu/bọ). Không có phân tích cấu tạo IDS rõ ràng. Cấu trúc chưa xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đào\": bộ 虫 (côn trùng) — ấu trùng (đào) của châu chấu đào xới đất trước khi lớn. | Gương Hán-Việt | ít dùng; xuất hiện trong danh pháp côn trùng học cổ | Mở khoá kiến thức | Biết 蜪 giúp đọc danh pháp cổ về côn trùng, đặc biệt trong từ 蝮蜪.", "Tự nguyên_Xie": "Theo Wiktionary: 蜪 dùng trong từ 蝮蜪 chỉ ấu trùng của châu chấu hoặc côn trùng tương tự. Bộ 虫 (trùng). Âm đọc tāo hoặc táo. Chưa có nguồn phân tích cấu tạo học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蜪", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 匋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫匋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜪", "Unihan_Traditional (Chữ Phồn thể)": "蜪", "Pinyin_Xie": "táo", "Âm Hán Việt_Xie": "đào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài côn trùng hoặc sâu bọ theo sách cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠜', '{"9000": "7835.0", "Chữ Trung Quốc": "蠜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 21 | nét | 蠜 | phàn | tượng hình | loại côn trùng hiếm | 蠜 thuộc bộ 虫 (trùng). Wiktionary chưa cung cấp định nghĩa cụ thể (rfdef). Âm đọc fán. Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phàn\": bộ 虫 (côn trùng) — chữ cực hiếm (phàn), một loại sâu bọ chưa được ghi nhận rõ trong từ điển hiện đại. | Gương Hán-Việt | ít dùng; không có từ Hán-Việt thông dụng chứa 蠜 | Mở khoá kiến thức | Biết 蠜 chủ yếu giúp nhận diện chữ hiếm trong văn bản cổ hoặc nghiên cứu cổ văn tự.", "Tự nguyên_Xie": "Theo Wiktionary: 蠜 thuộc bộ 虫 (trùng), âm đọc fán (phàn). Định nghĩa cụ thể chưa được ghi nhận (rfdef). Có âm Quảng Đông faan4/faan6. Đây là chữ cực hiếm chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khí phàn 氣蠜)", "Hạng Tần Suất (Jun Da)": "7835.0", "Tần Suất % (Jun Da)": "99.9990579007", "GavinGrover_Once (Chiết tự trực tiếp)": "棥 + 𧈹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱棥𧈹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𧈹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "棥", "Unihan_Simplified (Chữ Giản thể)": "蠜", "Unihan_Traditional (Chữ Phồn thể)": "蠜", "Pinyin_Xie": "fán", "Âm Hán Việt_Xie": "phàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài côn trùng thuộc họ cào cào, châu chấu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "",