INSERT INTO characters (char, data) VALUES ('袕', '{"9000": "7836.0", "Chữ Trung Quốc": "袕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袕 | huyệt | tượng hình | loại y phục cổ, không rõ nghĩa | 袕 thuộc bộ 衣 (y/quần áo). Wiktionary ghi rfdef (chưa có định nghĩa). Âm đọc xué. Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyệt\": bộ 衣 (quần áo) — một loại y phục (huyệt) cổ hiếm gặp, nghĩa chưa được xác định rõ. | Gương Hán-Việt | ít dùng; không có từ Hán-Việt thông dụng chứa 袕 | Mở khoá kiến thức | Biết 袕 giúp nhận diện tên y phục hiếm trong thư tịch cổ.", "Tự nguyên_Xie": "Theo Wiktionary: 袕 thuộc bộ 衣 (y/quần áo), âm đọc xué. Định nghĩa cụ thể chưa được ghi nhận. Đây là chữ cực hiếm trong văn bản cổ. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "袕", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 穴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤穴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "穴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袕", "Unihan_Traditional (Chữ Phồn thể)": "袕", "Pinyin_Xie": "xué", "Âm Hán Việt_Xie": "huyệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần tay áo chật hoặc nếp gấp, đường may trên trang phục cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裋', '{"9000": "7837.0", "Chữ Trung Quốc": "裋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 12 | nét | 裋 | thụ | tượng hình | áo ngắn thô, y phục người lao động | 裋 thuộc bộ 衣 (y/quần áo). Không có dữ liệu anchor Wiktionary. Nghĩa chính trong văn ngôn: loại áo ngắn thô sơ mặc bởi người lao động, nô lệ thời cổ. Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thụ\": bộ 衣 (quần áo) — áo thô ngắn (thụ) của người lao khổ, tương phản với y phục quý tộc. | Gương Hán-Việt | ít dùng; \"thụ\" trong văn ngôn cổ chỉ y phục thô sơ của người nghèo | Mở khoá kiến thức | Biết 裋 giúp đọc mô tả y phục dân dã trong thư tịch lịch sử Trung Hoa.", "Tự nguyên_Xie": "裋 là tên y phục cổ: áo ngắn thô sơ dùng bởi người lao động, nô tỳ trong xã hội cổ đại Trung Hoa. Bộ 衣 (y). Âm đọc shù. Xuất hiện trong từ ghép 裋褐 (áo thô ngắn của người nghèo). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo vải xấu", "Hạng Tần Suất (Jun Da)": "7837.0", "Tần Suất % (Jun Da)": "99.9990599678", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 豆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤豆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裋", "Unihan_Traditional (Chữ Phồn thể)": "裋", "Pinyin_Xie": "shù", "Âm Hán Việt_Xie": "thụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại áo ngắn làm bằng vải thô của người lao động thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裩', '{"9000": "7838.0", "Chữ Trung Quốc": "裩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 13 | nét | 裩 | côn | tượng hình | quần lót, quần đùi cổ | 裩 thuộc bộ 衣 (y/quần áo). Không có dữ liệu anchor Wiktionary. Là dạng dị thể/tương đương của 褌 (quần lót). Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"côn\": bộ 衣 (quần áo) — loại quần lót (côn) cổ, dị thể của 褌, mặc sát trong cùng. | Gương Hán-Việt | ít dùng; dạng thông dụng là 褌 (côn) | Mở khoá kiến thức | Biết 裩/褌 (côn) giúp đọc mô tả y phục nội địa trong văn hóa Hán-Nhật cổ.", "Tự nguyên_Xie": "裩 là dạng dị thể của 褌 (quần lót, quần đùi cổ). Bộ 衣 (y). Âm đọc kūn. Nghĩa: quần lót truyền thống, loại 褌 trong văn hóa Nhật Bản (fundoshi). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "裩", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 昆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤昆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裩", "Unihan_Traditional (Chữ Phồn thể)": "裩", "Pinyin_Xie": "kūn", "Âm Hán Việt_Xie": "côn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loại quần mặc bên trong thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褎', '{"9000": "7839.0", "Chữ Trung Quốc": "褎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 14 | nét | 衣 | y | biểu nghĩa | quần áo, vải vóc | 𥝩 | biểu âm | thành phần biểu âm | 褎 là chữ hình thanh: 衣 (Y, biểu nghĩa: quần áo) + 𥝩 (biểu âm). Có hai âm đọc: yòu và xiù (dị thể của 袖 — tay áo). Cấu trúc psc theo Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tụ\": 衣 (y/quần áo) — tay áo (tụ/袖) rộng che phủ; nghĩa phái sinh: nổi bật, vượt trội như tay áo rộng che khuất cả. | Gương Hán-Việt | ít dùng; dạng thông dụng là 袖 (tụ/tay áo) | Mở khoá kiến thức | Biết 褎 giúp đọc thành ngữ cổ như 褎如充耳 (giả điếc không nghe) và 褎然舉首 (đứng đầu nổi bật).", "Tự nguyên_Xie": "Theo Wiktionary: 褎 là chữ hình thanh ghép từ 衣 (y/quần áo, biểu nghĩa) và 𥝩 (biểu âm). Âm đọc 1: yòu — nghĩa chưa xác định; Âm đọc 2: xiù — dị thể của 袖 (tay áo). Từ 褎然 nghĩa là nổi bật, vượt trội. Từ 褎如充耳 nghĩa bịt tai giả điếc (thành ngữ). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tay áo", "Hạng Tần Suất (Jun Da)": "7839.0", "Tần Suất % (Jun Da)": "99.9990630686", "GavinGrover_Once (Chiết tự trực tiếp)": "衣 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴衣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "褎", "Unihan_Traditional (Chữ Phồn thể)": "褎", "Pinyin_Xie": "xiù", "Âm Hán Việt_Xie": "tụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ tay áo hoặc tính từ chỉ vẻ rộng rãi, thong dong. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('襫', '{"9000": "7840.0", "Chữ Trung Quốc": "襫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 20 | nét | 襫 | thích | tượng hình | áo mưa cổ làm từ cói/lá | 襫 thuộc bộ 衣 (y/quần áo). Theo Wiktionary, 襫 chỉ dùng trong từ 襏襫 — loại áo mưa truyền thống làm từ cỏ cói hoặc lá dùng bởi nông dân. Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thích\": bộ 衣 (quần áo) — áo mưa (thích) làm từ lá cói bện lại, như chiếc áo tơi của nông dân cổ. | Gương Hán-Việt | ít dùng; 襫 xuất hiện trong mô tả trang phục nông dân cổ | Mở khoá kiến thức | Biết 襫 giúp đọc mô tả trang phục dân dã cổ đại, đặc biệt trong từ 襏襫 (áo tơi).", "Tự nguyên_Xie": "Theo Wiktionary: 襫 chỉ dùng trong từ 襏襫 — áo mưa cổ truyền làm từ cỏ cói hoặc lá (dùng bởi nông dân và ngư dân thời cổ đại). Bộ 衣 (y). Âm đọc shì. Xuất hiện trong từ điển Mân Nam và Khách Gia. Chưa có phân tích cấu tạo học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bát thích 襏襫)", "Hạng Tần Suất (Jun Da)": "7840.0", "Tần Suất % (Jun Da)": "99.9990641021", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 奭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤奭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "襫", "Unihan_Traditional (Chữ Phồn thể)": "襫", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường xuất hiện trong từ ghép để chỉ loại áo tơi đi mưa thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觭', '{"9000": "7841.0", "Chữ Trung Quốc": "觭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 角 | Số nét | 15 | nét | 觭 | kỳ | tượng hình | sừng chênh vênh; số lẻ; đơn độc | 觭 thuộc bộ 角 (giác/sừng). Theo Wiktionary, nghĩa: sừng mọc lên xuống lệch chiều; nghĩa phái sinh là số lẻ (odd), đơn độc (single). Cấu trúc IDS không xác định rõ từ dữ liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": bộ 角 (sừng) — sừng mọc lệch (kỳ lạ/奇), không đều đặn; từ đó mang nghĩa số lẻ, đơn độc, kỳ quặc. | Gương Hán-Việt | ít dùng; liên quan đến 奇 (kỳ) nghĩa kỳ lạ, số lẻ | Mở khoá kiến thức | Biết 觭 giúp đọc thuật ngữ số học cổ (số lẻ) và mô tả vật có sừng bất đối xứng trong thư tịch.", "Tự nguyên_Xie": "Theo Wiktionary: 觭 thuộc bộ 角 (giác/sừng), âm jī. Nghĩa 1: sừng mọc không đều — một chiếc chỉ lên, một chiếc chỉ xuống. Nghĩa 2 (dị thể của 奇): số lẻ, đơn độc. Dùng trong từ 觭夢 (giải mộng lẻ tẻ/kỳ lạ), 觭輪 (bánh xe đơn). Chưa có nguồn phân tích cấu tạo chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sừng thú một cúi một ngửa; nghiêng về một bên", "Hạng Tần Suất (Jun Da)": "7841.0", "Tần Suất % (Jun Da)": "99.9990661693", "GavinGrover_Once (Chiết tự trực tiếp)": "角 + 奇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰角奇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "角", "Unihan_Simplified (Chữ Giản thể)": "觭", "Unihan_Traditional (Chữ Phồn thể)": "觭", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "cơ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Làm tính từ miêu tả trạng thái sừng thú hoặc đồ vật bị nghiêng lệch, không đều nhau. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訆', '{"9000": "7842.0", "Chữ Trung Quốc": "訆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 9 | nét | 訆 | khiếu | tượng hình | dị thể cổ của 叫 (kêu, la hét) | 訆 là dạng cổ/dị thể của 叫 (kêu, la hét). Thuộc bộ 言 (ngôn/lời nói). Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiếu\": bộ 言 (lời nói) — kêu to (khiếu), la hét; dạng cổ của 叫, đặt thêm bộ 言 để nhấn mạnh dùng lời. | Gương Hán-Việt | khiếu trong: hiếu khiếu (叫嚣), khiếu oan — dùng trong văn ngôn cổ | Mở khoá kiến thức | Biết 訆 giúp nhận diện dị thể cổ của 叫 trong thư tịch; liên hệ với 叫 (kêu) trong tiếng Hán hiện đại.", "Tự nguyên_Xie": "Theo Wiktionary: 訆 là dị thể của 叫 (kêu to, la hét). Bộ 言 (ngôn). Âm đọc jiào. Dạng thông dụng ngày nay là 叫. Chưa có nguồn phân tích cấu tạo học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "訆", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 丩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言丩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "訆", "Unihan_Traditional (Chữ Phồn thể)": "訆", "Pinyin_Xie": "jiào", "Âm Hán Việt_Xie": "khiếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ biểu thị hành động kêu to hoặc gào thét trong văn bản cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訏', '{"9000": "7843.0", "Chữ Trung Quốc": "訏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 訏 | hư | tượng hình | khoe khoang, cường điệu; to lớn, rộng rãi | 訏 thuộc bộ 言 (ngôn/lời nói). Theo Wiktionary, nghĩa: khoe khoang, nói quá; hoặc to lớn, rộng lớn. Dùng trong từ 訏謨 (kế sách lớn lao). Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hư\": bộ 言 (lời nói) + âm xū — lời nói hư huyễn (hư), phóng đại quá mức; hoặc mưu kế (謨) hư không rộng lớn. | Gương Hán-Việt | ít dùng; 訏謨 (hư mô) xuất hiện trong thơ kinh cổ chỉ mưu kế lớn | Mở khoá kiến thức | Biết 訏 giúp đọc 訏謨 trong thơ ca cổ điển — mưu kế rộng lớn của bậc hiền thần.", "Tự nguyên_Xie": "Theo Wiktionary: 訏 thuộc bộ 言 (ngôn/lời nói), âm xū. Nghĩa: khoe khoang, nói cường điệu, đánh lừa; hoặc to lớn, rộng lớn, vĩ đại. Dùng trong 訏謨 (mưu kế lớn lao) và 訏訏 (tả âm thanh to). Có ghi nhận trong từ điển Khách Gia (PHMZ). Chưa có nguồn phân tích cấu tạo học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khoe khoang; to, lớn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 于", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言于", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "于", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "𬣙", "Unihan_Traditional (Chữ Phồn thể)": "訏", "Pinyin_Xie": "xū", "Âm Hán Việt_Xie": "hu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho sự vật to lớn hoặc động từ chỉ việc nói khoác. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訽', '{"9000": "7844.0", "Chữ Trung Quốc": "訽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 12 | nét | 訽 | cấu | tượng hình | dị thể cổ của 詬 (sỉ nhục, mắng chửi) | 訽 là dạng cổ/dị thể của 詬. Thuộc bộ 言 (ngôn/lời nói). Nghĩa: sỉ nhục, mắng chửi bằng lời. Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cấu\": bộ 言 (lời nói) — lời mắng chửi (cấu) xúc phạm danh dự; 訽 là dạng cổ của 詬. | Gương Hán-Việt | ít dùng; dạng thông dụng là 詬 (cấu) nghĩa sỉ nhục, mắng | Mở khoá kiến thức | Biết 訽/詬 (cấu) giúp đọc mô tả sự sỉ nhục, ô danh trong văn ngôn cổ.", "Tự nguyên_Xie": "Theo Wiktionary: 訽 là dị thể của 詬 (sỉ nhục, mắng chửi). Bộ 言 (ngôn). Âm đọc gòu. Nghĩa phái sinh: nhục nhã, ô danh. Dạng thông dụng hiện nay là 詬. Chưa có nguồn phân tích cấu tạo học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tông", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "訽", "Unihan_Traditional (Chữ Phồn thể)": "訽", "Pinyin_Xie": "gòu", "Âm Hán Việt_Xie": "cấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Dùng làm động từ chỉ hành vi lăng mạ hoặc danh từ chỉ sự sỉ nhục. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詨', '{"9000": "7845.0", "Chữ Trung Quốc": "詨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 13 | nét | 詨 | hào | tượng hình | la hét, kêu to; khoe khoang; tượng thanh | 詨 thuộc bộ 言 (ngôn/lời nói). Theo Wiktionary, nghĩa: la hét, kêu to; khoe khoang; hoặc dùng làm từ tượng thanh. Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hào\": bộ 言 (lời nói) — la hét ầm ĩ (hào), kêu to phô trương; dạng cổ dùng trong văn ngôn. | Gương Hán-Việt | ít dùng; không có từ Hán-Việt thông dụng chứa 詨 | Mở khoá kiến thức | Biết 詨 giúp đọc mô tả tiếng kêu la, sự phô trương trong văn ngôn cổ.", "Tự nguyên_Xie": "Theo Wiktionary: 詨 thuộc bộ 言 (ngôn), âm xiào. Nghĩa cổ: la hét, kêu to; khoe khoang, phô trương; hoặc từ tượng thanh. Dùng trong 詨訛 (nói sai lệch/lừa dối) và 詨詨 (tả âm ồn ào). Chưa có nguồn phân tích cấu tạo học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "loại ve sầu, vũ trụ", "Hạng Tần Suất (Jun Da)": "7845.0", "Tần Suất % (Jun Da)": "99.9990703035", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 交", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言交", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "交", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "詨", "Unihan_Traditional (Chữ Phồn thể)": "詨", "Pinyin_Xie": "xiào", "Âm Hán Việt_Xie": "giáo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ hành động la hét hoặc gọi lớn tiếng trong cổ văn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('譻', '{"9000": "7846.0", "Chữ Trung Quốc": "譻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 21 | nét | 譻 | oanh | tượng hình | dị thể cổ của 嚶 (tiếng chim hót thánh thót) | 譻 là dạng cổ/dị thể của 嚶. Thuộc bộ 言 (ngôn/lời nói). Nghĩa: tiếng chim hót thánh thót, âm thanh réo rắt. Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oanh\": bộ 言 (tiếng) — tiếng hót (oanh) du dương của chim; 譻 là dạng cổ của 嚶, tượng thanh tiếng chim. | Gương Hán-Việt | oanh trong: oanh oanh (嚶嚶 — tiếng chim hót); liên hệ chim oanh vàng | Mở khoá kiến thức | Biết 譻/嚶 (oanh) giúp đọc mô tả âm thanh thiên nhiên, tiếng chim trong thơ Đường.", "Tự nguyên_Xie": "Theo Wiktionary: 譻 là dị thể của 嚶 (tiếng chim hót thánh thót, âm thanh du dương). Bộ 言 (ngôn). Âm đọc yīng. Dạng thông dụng là 嚶. Chưa có nguồn phân tích cấu tạo học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "軻", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "賏 + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱賏言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "賏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "譻", "Unihan_Traditional (Chữ Phồn thể)": "譻", "Pinyin_Xie": "yīng", "Âm Hán Việt_Xie": "oanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ miêu tả âm thanh vang vọng, trong trẻo hoặc tiếng chim kêu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诇', '{"9000": "7847.0", "Chữ Trung Quốc": "诇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 7 | nét | 讠 | ngôn | biểu nghĩa | lời nói (dạng giản thể của 言) | 詗 | hướng | biểu âm | thám thính, do thám | 诇 là chữ giản thể: 讠(Ngôn, biểu nghĩa: lời nói, dạng giản của 言) thay cho 言 trong 詗. Theo Wiktionary, đây là giản thể hóa từ 詗 (f=言→讠). Nghĩa: thám thính, do thám bằng lời.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hướng\": 讠(lời nói) — người do thám (hướng) dùng lời nói khéo léo để thu thập thông tin tình báo. | Gương Hán-Việt | ít dùng; dạng phồn thể là 詗 (hướng) — do thám, thám thính | Mở khoá kiến thức | Biết 诇/詗 (hướng) giúp đọc văn bản quân sự cổ nói về hoạt động do thám, tình báo.", "Tự nguyên_Xie": "Theo Wiktionary: 诇 là dạng giản thể của 詗, tạo bằng cách thay 言 thành 讠. Nghĩa: do thám, thám thính, thu thập tình báo. Âm đọc xiòng. Dạng phồn thể là 詗. Chưa có nguồn phân tích cấu tạo học thuật riêng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thăm dò", "Hạng Tần Suất (Jun Da)": "7847.0", "Tần Suất % (Jun Da)": "99.9990723707", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 冋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠冋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诇", "Unihan_Traditional (Chữ Phồn thể)": "詗", "Pinyin_Xie": "xiòng", "Âm Hán Việt_Xie": "huýnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động đi do thám hoặc thu thập tin tức tình báo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貑', '{"9000": "7848.0", "Chữ Trung Quốc": "貑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豸 | Số nét | 16 | nét | 貑 | gia | tượng hình | loài gấu đặc biệt, gấu có đốm | 貑 thuộc bộ 豸 (trĩ — loài thú không chân). Theo Wiktionary, dùng trong từ 貑羆 (loại gấu đặc biệt) và 貑貜. Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"gia\": bộ 豸 (loài thú) — một loại gấu (gia) đặc biệt được ghi chép trong thư tịch động vật học cổ đại. | Gương Hán-Việt | ít dùng; không có từ Hán-Việt thông dụng chứa 貑 | Mở khoá kiến thức | Biết 貑 giúp đọc danh pháp động vật trong Sơn Hải Kinh và thư tịch tự nhiên học cổ.", "Tự nguyên_Xie": "Theo Wiktionary: 貑 thuộc bộ 豸 (loài thú), âm jiā. Dùng trong từ 貑羆 (một loại gấu) và 貑貜. Chữ hiếm chỉ xuất hiện trong danh pháp động vật cổ đại. Chưa có nguồn phân tích cấu tạo học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "葑", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "豸 + 叚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豸叚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豸", "Unihan_Simplified (Chữ Giản thể)": "貑", "Unihan_Traditional (Chữ Phồn thể)": "貑", "Pinyin_Xie": "jiā", "Âm Hán Việt_Xie": "gia", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con lợn đực trong văn ngôn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跱', '{"9000": "7849.0", "Chữ Trung Quốc": "跱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 13 | nét | 足 | túc | biểu nghĩa | chân, bàn chân | 寺 | tự | biểu âm | chùa (cung cấp âm đọc gần zhì/shì) | 跱 là chữ hình thanh: 足 (Túc, biểu nghĩa: chân) + 寺 (Tự, biểu âm); chân đứng yên một chỗ. Cấu trúc psc theo Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trĩ\": 足 (chân) + 寺 (tự — âm) — chân (trĩ) đứng vững như cột chùa (寺), không nhúc nhích. | Gương Hán-Việt | ít dùng; không có từ Hán-Việt thông dụng chứa 跱 | Mở khoá kiến thức | Biết 跱 giúp nhận diện chữ hình thanh bộ 足 trong văn bản cổ nói về trạng thái đứng.", "Tự nguyên_Xie": "Theo Wiktionary: 跱 là chữ hình thanh ghép từ 足 (túc/chân, biểu nghĩa) và 寺 (biểu âm, cho âm gần zhì/shì). Nghĩa chưa được xác định rõ (rfdef), nhưng cấu trúc gợi ý liên quan đến đứng yên, dừng lại bằng chân. Âm đọc Quảng Đông zi6. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngừng, đứng lâu; đứng đối diện, đối lập; quán bên đường", "Hạng Tần Suất (Jun Da)": "7849.0", "Tần Suất % (Jun Da)": "99.9990744378", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 寺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊寺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跱", "Unihan_Traditional (Chữ Phồn thể)": "跱", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "trĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động đứng sừng sững hoặc tích trữ lương thảo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坶', '{"9000": "7850.0", "Chữ Trung Quốc": "坶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 8 | nét | 坶 | mẫu | tượng hình | địa danh cổ; đất mềm | 坶 thuộc bộ 土 (thổ/đất). Không có dữ liệu anchor Wiktionary. Nghĩa: địa danh cổ (牧野/Mục Dã khu vực) hoặc đất mềm. Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mẫu\": bộ 土 (đất) — vùng đất (mẫu) gắn với địa danh lịch sử cổ đại Trung Hoa. | Gương Hán-Việt | ít dùng; không có từ Hán-Việt thông dụng chứa 坶 | Mở khoá kiến thức | Biết 坶 giúp đọc địa danh lịch sử cổ đại trong thư tịch Trung Hoa.", "Tự nguyên_Xie": "坶 thuộc bộ 土 (thổ/đất), âm mǔ. Theo văn cảnh lịch sử, liên quan đến địa danh cổ (vùng Mục Dã — nơi diễn ra trận chiến quyết định nhà Chu thắng nhà Thương). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đất đen", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 母", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土母", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "母", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坶", "Unihan_Traditional (Chữ Phồn thể)": "坶", "Pinyin_Xie": "mǔ", "Âm Hán Việt_Xie": "mẫu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loại đất đen hoặc địa danh cổ như Mẫu Dã. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躘', '{"9000": "7851.0", "Chữ Trung Quốc": "躘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 23 | nét | 躘 | ruông | tượng hình | loạng choạng; chạy tán loạn | 躘 thuộc bộ 足 (túc/chân). Theo Wiktionary, dùng trong từ 躘蹱 và có nghĩa trong tiếng Đài Sơn: chạy tán loạn, chạy hết chỗ này đến chỗ khác. Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ruông\": bộ 足 (chân) — chân (ruông) lảo đảo loạng choạng; dùng trong 躘蹱 tả dáng đi không vững. | Gương Hán-Việt | ít dùng; không có từ Hán-Việt thông dụng chứa 躘 | Mở khoá kiến thức | Biết 躘 giúp đọc mô tả dáng đi loạng choạng trong văn học cổ và phương ngữ.", "Tự nguyên_Xie": "Theo Wiktionary: 躘 thuộc bộ 足 (túc/chân), âm lóng (ruông theo HV). Dùng trong từ 躘蹱 (loạng choạng, đi lảo đảo). Trong tiếng Đài Sơn: chạy tán loạn, chạy hết chỗ này đến chỗ khác. Âm Quảng Đông lung4/luung1. Chưa có nguồn phân tích cấu tạo học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đi bộ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 龍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊龍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "𨀁", "Unihan_Traditional (Chữ Phồn thể)": "躘", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "ruông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ mô tả dáng đi hoặc hành động đi bộ trong văn cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輖', '{"9000": "7852.0", "Chữ Trung Quốc": "輖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 15 | nét | 輖 | chu | tượng hình | bộ phận xe cổ; dùng trong 軒輖 | 輖 thuộc bộ 車 (xa/xe). Theo Wiktionary, dùng trong từ 軒輖. Không có nghĩa độc lập rõ ràng. Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chu\": bộ 車 (xe) — bộ phận của xe (chu) cổ đại, dùng trong mô tả xe ngựa truyền thống. | Gương Hán-Việt | ít dùng; không có từ Hán-Việt thông dụng chứa 輖 | Mở khoá kiến thức | Biết 輖 giúp đọc mô tả xe cộ và phương tiện trong thư tịch cổ đại.", "Tự nguyên_Xie": "Theo Wiktionary: 輖 thuộc bộ 車 (xa/xe), âm zhōu. Dùng trong từ 軒輖 (liên quan đến xe cổ, có thể là bộ phận hoặc loại xe). Nghĩa cụ thể chưa xác định rõ. Chưa có nguồn phân tích cấu tạo học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "薖", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 周", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車周", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "周", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "輖", "Unihan_Traditional (Chữ Phồn thể)": "輖", "Pinyin_Xie": "zhōu", "Âm Hán Việt_Xie": "chu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Làm danh từ chỉ loại xe cổ có đầu thấp hoặc tính từ tả xe nặng phía trước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轇', '{"9000": "7853.0", "Chữ Trung Quốc": "轇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 18 | nét | 轇 | giao | tượng hình | rối rắm, chằng chịt; dùng trong 轇轕 | 轇 thuộc bộ 車 (xa/xe). Theo Wiktionary, chỉ dùng trong từ 轇轕 (rối rắm, chằng chịt, hỗn loạn). Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giao\": bộ 車 (xe) — nhiều xe (giao) đan chéo nhau tạo nên cảnh hỗn loạn rối rắm 轇轕. | Gương Hán-Việt | ít dùng; không có từ Hán-Việt thông dụng chứa 轇 | Mở khoá kiến thức | Biết 轇 giúp đọc từ 轇轕 trong văn ngôn cổ mô tả tình trạng hỗn loạn, chằng chịt.", "Tự nguyên_Xie": "Theo Wiktionary: 轇 thuộc bộ 車 (xa/xe), âm jiāo. Chỉ dùng trong từ 轇轕 nghĩa rối rắm, chằng chịt, hỗn độn. Âm Quảng Đông gaau1. Chưa có nguồn phân tích cấu tạo học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chân", "Hạng Tần Suất (Jun Da)": "7853.0", "Tần Suất % (Jun Da)": "99.9990785721", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 翏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車翏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "轇", "Unihan_Traditional (Chữ Phồn thể)": "轇", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "giao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ trong từ ghép như giao cát để tả sự hỗn loạn, rối ren. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轋', '{"9000": "7854.0", "Chữ Trung Quốc": "轋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 17 | nét | 轋 | hồn | tượng hình | bộ phận xe cổ; âm hún | 轋 thuộc bộ 車 (xa/xe). Không có dữ liệu anchor Wiktionary. Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồn\": bộ 車 (xe) — bộ phận hoặc loại xe (hồn) cực hiếm trong thư tịch cổ đại. | Gương Hán-Việt | ít dùng; không có từ Hán-Việt thông dụng chứa 轋 | Mở khoá kiến thức | Biết 轋 giúp nhận diện chữ hiếm liên quan đến phương tiện xe trong văn bản cổ.", "Tự nguyên_Xie": "轋 thuộc bộ 車 (xa/xe), âm hún. Không có định nghĩa hay phân tích cấu tạo từ Wiktionary. Đây là chữ cực hiếm. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Thạch", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 連", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車連", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "連", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "轋", "Unihan_Traditional (Chữ Phồn thể)": "轋", "Pinyin_Xie": "hún", "Âm Hán Việt_Xie": "hồn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ một loại xe chở đồ hoặc xe tang thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轕', '{"9000": "7855.0", "Chữ Trung Quốc": "轕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 19 | nét | 轕 | cát | tượng hình | rối rắm, chằng chịt; dùng trong 轇轕 | 轕 thuộc bộ 車 (xa/xe). Không có dữ liệu anchor Wiktionary riêng. Chỉ dùng trong từ 轇轕 (rối rắm, chằng chịt). Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cát\": bộ 車 (xe) — xe (cát) mắc kẹt, chằng chịt rối; trong 轇轕 mô tả sự hỗn độn. | Gương Hán-Việt | ít dùng; chỉ xuất hiện trong từ 轇轕 | Mở khoá kiến thức | Biết 轕 giúp hiểu trọn nghĩa của từ 轇轕 (rối rắm hỗn loạn) trong văn ngôn cổ.", "Tự nguyên_Xie": "轕 thuộc bộ 車 (xa/xe), âm gé. Chỉ xuất hiện trong từ ghép 轇轕 cùng với 轇. Nghĩa: rối rắm, hỗn loạn (khi kết hợp). Không có nguồn phân tích cấu tạo học thuật riêng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蕕", "Hạng Tần Suất (Jun Da)": "7855.0", "Tần Suất % (Jun Da)": "99.9990806392", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 葛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車葛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "葛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "轕", "Unihan_Traditional (Chữ Phồn thể)": "轕", "Pinyin_Xie": "gé", "Âm Hán Việt_Xie": "cát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm tính từ tả cảnh binh mã hỗn loạn hoặc danh từ chỉ xe quân sự. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迒', '{"9000": "7856.0", "Chữ Trung Quốc": "迒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 7 | nét | 辶 | sước | biểu nghĩa | đi, bước đi (bộ chước) | 亢 | kháng | biểu âm | cao, cứng nhắc (cung cấp âm gần háng) | 迒 là chữ hình thanh: 辶 (Sước, biểu nghĩa: đi, bước đi) + 亢 (Kháng, biểu âm); dấu vết đường đi của con thú. Cấu trúc psc theo Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàng\": 辶 (đi) + 亢 (kháng — âm) — dấu vết (hàng) con thú để lại trên đường, thợ săn theo dấu mà tìm. | Gương Hán-Việt | ít dùng; không có từ Hán-Việt thông dụng chứa 迒 | Mở khoá kiến thức | Biết 迒 giúp đọc văn bản săn bắt và tự nhiên học cổ đại mô tả dấu vết thú rừng.", "Tự nguyên_Xie": "Theo Wiktionary: 迒 là chữ hình thanh ghép từ 辶 (chước/đi, biểu nghĩa) và 亢 (biểu âm, cho âm gần háng/hàng). Nghĩa: dấu vết đường đi, vết chân của thú trên đường. Âm đọc háng. Chữ cổ xuất hiện trong mô tả săn bắt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Hảo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 亢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶亢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迒", "Unihan_Traditional (Chữ Phồn thể)": "迒", "Pinyin_Xie": "háng", "Âm Hán Việt_Xie": "hàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ dấu vết của muông thú để lại trên mặt đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郘', '{"9000": "7857.0", "Chữ Trung Quốc": "郘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 8 | nét | 郘 | lữ | tượng hình | địa danh cổ; bộ 邑 (ấp) | 郘 thuộc bộ 邑 (ấp/làng). Không có dữ liệu anchor Wiktionary. Thường là tên địa danh hay tên đất trong văn bản lịch sử. Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lữ\": bộ 邑 (ấp/làng) — địa danh cổ (lữ) một vùng đất được ghi trong thư tịch địa lý lịch sử. | Gương Hán-Việt | ít dùng; không có từ Hán-Việt thông dụng chứa 郘 | Mở khoá kiến thức | Biết 郘 giúp nhận diện tên địa danh trong thư tịch lịch sử Trung Hoa cổ đại.", "Tự nguyên_Xie": "郘 thuộc bộ 邑 (ấp/làng), âm lǘ. Không có dữ liệu Wiktionary. Theo cấu trúc, đây là tên địa danh cổ — chữ bộ 邑 thường chỉ tên vùng đất, ấp, quận huyện. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "阘", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "吕 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰吕阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郘", "Unihan_Traditional (Chữ Phồn thể)": "郘", "Pinyin_Xie": "lǘ", "Âm Hán Việt_Xie": "lữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng chỉ địa danh cổ hoặc họ người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醄', '{"9000": "7858.0", "Chữ Trung Quốc": "醄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 15 | nét | 醄 | đào | tượng hình | say khướt; rượu nặng | 醄 thuộc bộ 酉 (dậu/rượu). Không có dữ liệu anchor Wiktionary. Nghĩa suy từ bộ thủ: trạng thái say rượu. Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đào\": bộ 酉 (rượu) — say khướt (đào) ngả nghiêng như đào mềm rữa — hình ảnh người uống rượu đến say tràn. | Gương Hán-Việt | ít dùng; không có từ Hán-Việt thông dụng chứa 醄 | Mở khoá kiến thức | Biết 醄 giúp đọc mô tả trạng thái say rượu trong văn học cổ điển Trung Hoa.", "Tự nguyên_Xie": "醄 thuộc bộ 酉 (dậu/rượu), âm táo. Bộ 酉 liên quan đến rượu và các trạng thái liên quan đến rượu. Nghĩa: say khướt, hoặc loại rượu nặng. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "say mèm", "Hạng Tần Suất (Jun Da)": "7858.0", "Tần Suất % (Jun Da)": "99.99908374", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 匋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉匋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醄", "Unihan_Traditional (Chữ Phồn thể)": "醄", "Pinyin_Xie": "táo", "Âm Hán Việt_Xie": "đào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả trạng thái say rượu hoặc vui vẻ phấn chấn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醼', '{"9000": "7859.0", "Chữ Trung Quốc": "醼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 23 | nét | 醼 | yến | tượng hình | dị thể cổ của 宴 (tiệc, yến tiệc) | 醼 là dạng dị thể/cổ của 宴 (yến tiệc). Thuộc bộ 酉 (dậu/rượu). Bộ 酉 gợi đến rượu — thành phần không thể thiếu trong yến tiệc. Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yến\": bộ 酉 (rượu) — yến tiệc (yến) đồng nghĩa với 宴; rượu là linh hồn của buổi tiệc. | Gương Hán-Việt | yến tiệc (宴/醼), yến hội — tất cả chỉ bữa tiệc sang trọng | Mở khoá kiến thức | Biết 醼/宴 (yến) mở khoá: yến tiệc, yến hội, chiêu yến — mọi từ ghép nói về bữa tiệc chiêu đãi.", "Tự nguyên_Xie": "Theo Wiktionary: 醼 là dị thể của 宴 (yến tiệc, tiệc chiêu đãi). Bộ 酉 (dậu/rượu). Âm đọc yàn. Rượu là yếu tố trung tâm của yến tiệc — bộ 酉 biểu thị điều đó. Dạng thông dụng ngày nay là 宴. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "yến tiệc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 燕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉燕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "燕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醼", "Unihan_Traditional (Chữ Phồn thể)": "醼", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "yến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Làm danh từ chỉ bữa tiệc hoặc động từ chỉ việc bày tiệc chiêu đãi khách. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鋋', '{"9000": "7860.0", "Chữ Trung Quốc": "鋋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 鋋 | thiền | tượng hình | giáo ngắn; đâm xuyên | 鋋 thuộc bộ 金 (kim/kim loại). Theo Wiktionary, nghĩa: giáo ngắn, vũ khí ngắn để đâm; cũng nghĩa đâm xuyên. Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiền\": bộ 金 (kim loại) — cây giáo ngắn (thiền) bằng kim loại, vũ khí cận chiến trong 戈鋋. | Gương Hán-Việt | ít dùng; 鋋 trong thơ văn cổ gắn với hình ảnh chiến trận | Mở khoá kiến thức | Biết 鋋 giúp đọc mô tả vũ khí trong thơ chiến trận cổ đại Trung Hoa.", "Tự nguyên_Xie": "Theo Wiktionary: 鋋 thuộc bộ 金 (kim/kim loại), âm chán hoặc yán. Nghĩa: giáo ngắn (short spear), vũ khí cầm tay để đâm xuyên. Dùng trong từ 戈鋋 (giáo và các vũ khí ngắn). Âm Quảng Đông jin4/sin4. Chưa có nguồn phân tích cấu tạo học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giáo ngắn cán sắt (binh khí cổ)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 延", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金延", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "延", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鋋", "Unihan_Traditional (Chữ Phồn thể)": "鋋", "Pinyin_Xie": "chán", "Âm Hán Việt_Xie": "diên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại binh khí cổ, thường dùng trong văn bản lịch sử. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鏁', '{"9000": "7861.0", "Chữ Trung Quốc": "鏁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 19 | nét | 鏁 | tỏa | tượng hình | dị thể cổ của 鎖 (khóa, xích) | 鏁 là dạng dị thể của 鎖 (khóa, xích). Thuộc bộ 金 (kim/kim loại). Nghĩa: khóa, xiềng xích, cùm. Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỏa\": bộ 金 (kim loại) — chiếc khóa/xiềng xích (tỏa) bằng kim loại giam giữ người; dạng cổ của 鎖. | Gương Hán-Việt | phong tỏa (封鎖/鏁), giam tỏa — tất cả mang nghĩa phong bế, giam cầm | Mở khoá kiến thức | Biết 鏁/鎖 (tỏa) mở khoá: phong tỏa, tỏa chặt, giam tỏa — tất cả nghĩa khóa/bít kín.", "Tự nguyên_Xie": "鏁 là dạng cổ/dị thể của 鎖 (khóa, xích, cùm). Bộ 金 (kim). Âm đọc suǒ. Nghĩa: vật dụng bằng kim loại để khóa/xiềng. Chưa có nguồn phân tích cấu tạo học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giam, nhốt, khoá chặt", "Hạng Tần Suất (Jun Da)": "7861.0", "Tần Suất % (Jun Da)": "99.9990868407", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 巢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金巢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鏁", "Unihan_Traditional (Chữ Phồn thể)": "鏁", "Pinyin_Xie": "suǒ", "Âm Hán Việt_Xie": "toả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ hành động khóa hoặc giam giữ, là biến thể của chữ tỏa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鏭', '{"9000": "7862.0", "Chữ Trung Quốc": "鏭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 19 | nét | 鏭 | tê | tượng hình | dụng cụ kim loại cổ; âm xī | 鏭 thuộc bộ 金 (kim/kim loại). Không có dữ liệu anchor Wiktionary. Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tê\": bộ 金 (kim loại) — một dụng cụ/vật dụng kim loại (tê) cực hiếm trong thư tịch cổ đại. | Gương Hán-Việt | ít dùng; không có từ Hán-Việt thông dụng chứa 鏭 | Mở khoá kiến thức | Biết 鏭 giúp nhận diện chữ hiếm liên quan đến kim khí trong văn bản cổ.", "Tự nguyên_Xie": "鏭 thuộc bộ 金 (kim/kim loại), âm xī. Không có dữ liệu Wiktionary hay nguồn phân tích cấu tạo. Đây là chữ cực hiếm. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "魭", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 悉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金悉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "悉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鏭", "Unihan_Traditional (Chữ Phồn thể)": "鏭", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ cổ rất hiếm gặp, chủ yếu xuất hiện trong các thư tịch cổ chỉ sinh vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鐄', '{"9000": "7863.0", "Chữ Trung Quốc": "鐄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 19 | nét | 鐄 | hoàng | tượng hình | loại chuông/nhạc khí kim loại cổ | 鐄 thuộc bộ 金 (kim/kim loại). Không có dữ liệu anchor Wiktionary chi tiết. Theo âm đọc hoàng và bộ thủ kim, đây có thể là tên nhạc khí hoặc đồ vật bằng đồng. Cấu trúc IDS không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\": bộ 金 (kim loại) — nhạc khí hoặc vật kim loại (hoàng) màu vàng óng, đúc từ đồng thau. | Gương Hán-Việt | ít dùng; không có từ Hán-Việt thông dụng chứa 鐄 | Mở khoá kiến thức | Biết 鐄 giúp nhận diện tên nhạc khí/vật dụng kim loại cổ trong thư tịch âm nhạc hoặc lịch sử.", "Tự nguyên_Xie": "鐄 thuộc bộ 金 (kim/kim loại), âm huáng (hoàng). Không có dữ liệu Wiktionary chi tiết. Bộ 金 chỉ đây là vật dụng kim loại. Âm đọc gợi liên hệ với 鑄 (đúc), 磺 (khoáng vật). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鐄", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 黄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金黄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "𨱑", "Unihan_Traditional (Chữ Phồn thể)": "鐄", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ nhạc khí cổ hoặc làm động từ chỉ tiếng chuông vang lên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辁', '{"9000": "7864.0", "Chữ Trung Quốc": "辁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 10 | nét | 辁 | toàn | tượng hình | bánh xe nhỏ không có căm | 辁 là chữ độc thể, chưa xác định rõ cấu trúc hình thanh hay hội ý từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toàn\": bánh xe (辁) toàn vẹn nhưng không có căm — bánh xe đơn giản nhất. | Gương Hán-Việt | toàn trong \"toàn bộ\" — nghĩa gốc là đầy đủ, trọn vẹn | Mở khoá kiến thức | Biết 辁 mở ra từ vựng về xe cộ, bánh xe trong văn bản cổ Trung Hoa.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ chỉ loại bánh xe nhỏ không có căm. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bánh xe đặc (không có nan hoa)", "Hạng Tần Suất (Jun Da)": "7864.0", "Tần Suất % (Jun Da)": "99.9990920085", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 全", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车全", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "全", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "辁", "Unihan_Traditional (Chữ Phồn thể)": "輇", "Pinyin_Xie": "quán", "Âm Hán Việt_Xie": "thuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ loại bánh xe cổ hoặc làm tính từ chỉ sự nông cạn, thô sơ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阸', '{"9000": "7865.0", "Chữ Trung Quốc": "阸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 7 | nét | 阸 | ách | tượng hình | nơi hiểm trở, eo đất | 阸 là chữ độc thể hoặc chưa có phân tích thành phần học thuật rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ách\": nơi ách tắc (阸) — con đường hiểm trở bị chặn lại như cái ách trên cổ. | Gương Hán-Việt | ách trong \"ách tắc\" — chỗ bị nghẽn, không thông | Mở khoá kiến thức | Biết 阸 giúp đọc văn bản địa lý quân sự cổ Trung Hoa về vị trí hiểm yếu.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ chỉ nơi hiểm trở, chỗ tắc nghẽn, eo đất. Biến thể của 阨/厄. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "阸", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 戹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝戹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "阸", "Unihan_Traditional (Chữ Phồn thể)": "阸", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ địa hình hiểm yếu hoặc làm động từ chỉ sự cản trở, khốn cùng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('牿', '{"9000": "7866.0", "Chữ Trung Quốc": "牿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 牛 | Số nét | 11 | nét | 牿 | cốc | tượng hình | chuồng trâu bò | 牿 là chữ độc thể, chưa có phân tích cấu trúc học thuật rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cốc\": chuồng cốc giữ trâu bò (牿) — nơi nhốt gia súc để kiểm soát. | Gương Hán-Việt | cốc trong \"cốc thóc\" — nghĩa rộng hơn là chứa đựng, nhốt giữ | Mở khoá kiến thức | Biết 牿 giúp đọc văn bản nông nghiệp cổ về chăn nuôi gia súc.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ chỉ chuồng nhốt trâu bò, hoặc ách đeo vào cổ bò. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thanh gỗ ngang buộc ở sừng trâu để đề phòng trâu chém người; chuồng nuôi trâu hoặc ngựa", "Hạng Tần Suất (Jun Da)": "7866.0", "Tần Suất % (Jun Da)": "99.9990940757", "GavinGrover_Once (Chiết tự trực tiếp)": "牛 + 告", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰牛告", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "告", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "牛", "Unihan_Simplified (Chữ Giản thể)": "牿", "Unihan_Traditional (Chữ Phồn thể)": "牿", "Pinyin_Xie": "gù", "Âm Hán Việt_Xie": "cố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ chuồng nuôi trâu ngựa hoặc làm động từ chỉ việc nhốt giữ gia súc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞝', '{"9000": "7867.0", "Chữ Trung Quốc": "鞝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 17 | nét | 鞝 | thướng | tượng hình | đế giày, lót giày | 鞝 là chữ độc thể, chưa có dữ liệu cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thướng\": đế giày thướt tha (鞝) — tấm da lót dưới bàn chân. | Gương Hán-Việt | thướng trong phương ngữ miền Nam chỉ đế giày dép | Mở khoá kiến thức | Biết 鞝 giúp đọc văn bản thủ công nghiệp, đồ da cổ Trung Hoa.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ liên quan đến đế giày hoặc lót giày, thuộc bộ 革 (da). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "miếng da", "Hạng Tần Suất (Jun Da)": "7867.0", "Tần Suất % (Jun Da)": "99.9990951092", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 尚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革尚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞝", "Unihan_Traditional (Chữ Phồn thể)": "鞝", "Pinyin_Xie": "shàng", "Âm Hán Việt_Xie": "thướng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ phần da của giày hoặc làm động từ chỉ việc khâu đế giày. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('頞', '{"9000": "7868.0", "Chữ Trung Quốc": "頞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 15 | nét | 安 | an | biểu âm | yên (biểu âm) | 頁 | hiệt | biểu nghĩa | đầu, mặt | 頞 = 安 (An, biểu âm) + 頁 (Hiệt, biểu nghĩa: đầu/mặt); chữ hình thanh. Bộ 頁 cho biết liên quan đến phần đầu, 安 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"át\": sống mũi (頞) — bộ Hiệt (頁, mặt người) + An (安) cho âm át. | Gương Hán-Việt | át trong \"át chế\" — nghĩa gốc là phần chặn, ngăn (sống mũi) | Mở khoá kiến thức | Biết 頞 giúp đọc văn bản y học cổ về giải phẫu khuôn mặt.", "Tự nguyên_Xie": "Chữ hình thanh. Theo Wiktionary: 頁 (đầu/mặt) là bộ phận biểu nghĩa, 安 là bộ phận biểu âm. Chỉ sống mũi hoặc phần trên của mũi. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sống mũi", "Hạng Tần Suất (Jun Da)": "7868.0", "Tần Suất % (Jun Da)": "99.9990961428", "GavinGrover_Once (Chiết tự trực tiếp)": "安 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰安頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "安", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "頞", "Unihan_Traditional (Chữ Phồn thể)": "頞", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "át", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận sống mũi trên khuôn mặt trong y học cổ truyền hoặc nhân tướng học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞵', '{"9000": "7869.0", "Chữ Trung Quốc": "瞵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 17 | nét | 目 | mục | biểu nghĩa | mắt | 粦 | lân | biểu âm | ma trơi (biểu âm) | 瞵 = 目 (Mục, biểu nghĩa: mắt) + 粦 (Lân, biểu âm); chữ hình thanh. Bộ 目 cho biết liên quan đến mắt nhìn, phần 粦 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lân\": ánh mắt lân tinh (瞵) — mắt (目) sáng như ma trơi (粦) nhìn chòng chọc. | Gương Hán-Việt | lân trong \"lân cận\" — nghĩa gốc là gần gũi, nhìn kỹ | Mở khoá kiến thức | Biết 瞵 giúp đọc thơ cổ miêu tả ánh mắt sáng hoặc nhìn chăm chú.", "Tự nguyên_Xie": "Chữ hình thanh. Theo Wiktionary: 目 (mắt) là bộ phận biểu nghĩa, 粦 là bộ phận biểu âm. Chỉ ánh mắt sáng lên, nhìn chòng chọc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chăm chú nhìn; nhãn cầu, tròng mắt", "Hạng Tần Suất (Jun Da)": "7869.0", "Tần Suất % (Jun Da)": "99.9990971764", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 粦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目粦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "粦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞵", "Unihan_Traditional (Chữ Phồn thể)": "瞵", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ mô tả ánh mắt nhìn chăm chú hoặc dòm ngó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饤', '{"9000": "7870.0", "Chữ Trung Quốc": "饤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 5 | nét | 饤 | đính | tượng hình | bày thức ăn lên đĩa | 饤 là chữ độc thể, chưa có phân tích cấu trúc học thuật rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đính\": đính thức ăn (饤) lên đĩa — bày biện món ăn cho đẹp mắt. | Gương Hán-Việt | đính trong \"đính kèm\" — nghĩa gốc là gắn, đặt lên | Mở khoá kiến thức | Biết 饤 giúp đọc văn bản ẩm thực, lễ nghi cổ về bày biện thức ăn.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ chỉ hành động bày thức ăn lên đĩa để trưng bày, thuộc bộ 食 (ăn). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mâm ngũ quả", "Hạng Tần Suất (Jun Da)": "7870.0", "Tần Suất % (Jun Da)": "99.9990982099", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 丁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣丁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饤", "Unihan_Traditional (Chữ Phồn thể)": "飣", "Pinyin_Xie": "dìng", "Âm Hán Việt_Xie": "đính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường dùng làm động từ với nghĩa bày biện thức ăn hoặc làm danh từ chỉ đồ ăn bày biện để trang trí. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('駃', '{"9000": "7871.0", "Chữ Trung Quốc": "駃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 14 | nét | 駃 | quyết | tượng hình | ngựa nhanh; trong 駃騠 chỉ con la nhanh | 駃 là chữ độc thể thuộc bộ 馬, chưa có phân tích cấu trúc học thuật rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyết\": ngựa quyết tốc (駃) — con vật nhanh như cắt, thường ghép với 騠 thành 駃騠. | Gương Hán-Việt | quyết trong \"quyết định\" — nghĩa gốc là nhanh, dứt khoát | Mở khoá kiến thức | Biết 駃 giúp đọc văn bản cổ về giống ngựa và la tốc độ cao.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ thuộc bộ 馬, thường xuất hiện trong tổ hợp 駃騠 (quyết đề) chỉ con la nhanh. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "駃", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 夬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬夬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "𫘝", "Unihan_Traditional (Chữ Phồn thể)": "駃", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này chủ yếu làm danh từ chỉ giống ngựa tốt hoặc làm tính từ mô tả dáng ngựa chạy nhanh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('駉', '{"9000": "7872.0", "Chữ Trung Quốc": "駉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 15 | nét | 駉 | quýnh | tượng hình | ngựa béo khỏe | 駉 là chữ độc thể thuộc bộ 馬, chưa có phân tích cấu trúc học thuật rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quýnh\": ngựa quýnh quáng vì béo (駉) — con ngựa tròn trịa, khỏe mạnh trong Kinh Thi. | Gương Hán-Việt | quýnh trong phương ngữ — chỉ sự tròn đầy, béo tốt | Mở khoá kiến thức | Biết 駉 giúp đọc Kinh Thi và thơ ca cổ miêu tả ngựa béo tốt.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ thuộc bộ 馬, chỉ ngựa béo khỏe mạnh. Xuất hiện trong Kinh Thi. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa khoẻ, ngựa tốt", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 冋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬冋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "𬳶", "Unihan_Traditional (Chữ Phồn thể)": "駉", "Pinyin_Xie": "jiōng", "Âm Hán Việt_Xie": "quynh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ để tả dáng ngựa mập mạp, khỏe mạnh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('騠', '{"9000": "7873.0", "Chữ Trung Quốc": "騠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 19 | nét | 騠 | đề | tượng hình | con la nhanh; trong 駃騠 | 騠 là chữ độc thể thuộc bộ 馬, thường chỉ xuất hiện trong tổ hợp 駃騠.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đề\": đề bạt ngựa nhanh (騠) — luôn đi cùng 駃 trong từ 駃騠 chỉ con la tốc độ. | Gương Hán-Việt | đề trong \"đề nghị\" — nghĩa gốc là nêu lên, nhắc đến | Mở khoá kiến thức | Biết 騠 giúp đọc văn bản cổ về giống ngựa, la phương Bắc.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ thuộc bộ 馬, trong tổ hợp 駃騠 chỉ con la nhanh ở phương Bắc Trung Hoa. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "騠", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 是", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬是", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "是", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "𫘨", "Unihan_Traditional (Chữ Phồn thể)": "騠", "Pinyin_Xie": "tí", "Âm Hán Việt_Xie": "đề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong các từ ghép để chỉ các giống ngựa tốt thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驡', '{"9000": "7874.0", "Chữ Trung Quốc": "驡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 26 | nét | 驡 | lung | tượng hình | ngựa hoang, không khuất phục | 驡 là chữ độc thể thuộc bộ 馬, chưa có phân tích cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lung\": ngựa lồng lộn (驡) — con ngựa hoang không chịu bị kiểm soát. | Gương Hán-Việt | lung trong \"long trời lở đất\" — sức mạnh không kềm được | Mở khoá kiến thức | Biết 驡 giúp đọc văn bản cổ miêu tả ngựa hoang bất khuất.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ thuộc bộ 馬, chỉ ngựa hoang hoặc ngựa không chịu khuất phục. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "顡", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "龍 + 馬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱龍馬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "馬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "龍", "Unihan_Simplified (Chữ Giản thể)": "驡", "Unihan_Traditional (Chữ Phồn thể)": "驡", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "lung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ cổ dùng để chỉ một loại ngựa hoang hoặc ngựa khỏe. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髪', '{"9000": "7875.0", "Chữ Trung Quốc": "髪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 14 | nét | 髟 | phiêu | biểu nghĩa | tóc dài | 友 | hữu | biểu âm | bạn bè (thay thế 犮 trong dạng giản) | 髪 là dạng shinjitai Nhật Bản của 髮. Bộ 髟 (tóc dài) giữ nguyên, phần 犮 được giản lược thành 友. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phát\": tóc phát triển (髪) — bộ Phiêu (髟, tóc dài) ghép với 友 trong dạng chữ Nhật shinjitai. | Gương Hán-Việt | phát trong \"mái tóc\" (發/髮) — phát âm giống nhau | Mở khoá kiến thức | Biết 髪 giúp đọc văn bản Nhật Bản và phân biệt với phồn thể 髮 trong tiếng Trung.", "Tự nguyên_Xie": "髪 là dạng shinjitai (tân tự thể) của Nhật Bản, giản hóa từ 髮 bằng cách thay 犮 bằng 友. Chữ gốc 髮 là hình thanh: 髟 (tóc dài) biểu nghĩa, 犮 biểu âm. Dạng 髪 chỉ dùng trong hệ thống chữ Nhật, không phải phồn thể Hán ngữ chuẩn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tóc; một phần nghìn của một tấc", "Hạng Tần Suất (Jun Da)": "7875.0", "Tần Suất % (Jun Da)": "99.9991033778", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 友", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟友", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "友", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "髪", "Unihan_Traditional (Chữ Phồn thể)": "髪", "Pinyin_Xie": "fà", "Âm Hán Việt_Xie": "phát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng sau các từ chỉ bộ phận cơ thể hoặc làm định ngữ để chỉ những gì nhỏ như sợi tóc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬿', '{"9000": "7876.0", "Chữ Trung Quốc": "鬿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬼 | Số nét | 13 | nét | 鬿 | kì | tượng hình | tên chòm sao cổ đại | 鬿 là chữ độc thể, không có dữ liệu cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kì\": chòm sao kì lạ (鬿) — tên thiên văn cổ đại hiếm gặp. | Gương Hán-Việt | kì trong \"kỳ lạ\" — điều bí ẩn, khó hiểu | Mở khoá kiến thức | Biết 鬿 giúp đọc văn bản thiên văn cổ Trung Hoa.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ chỉ một chòm sao trong thiên văn học cổ Trung Hoa. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Yi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鬼 + 斤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鬼斤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鬼", "Unihan_Simplified (Chữ Giản thể)": "鬿", "Unihan_Traditional (Chữ Phồn thể)": "鬿", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ riêng trong văn học cổ để chỉ tên chòm sao hoặc sinh vật thần thoại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鱻', '{"9000": "7877.0", "Chữ Trung Quốc": "鱻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 33 | nét | 魚 | ngư | biểu nghĩa | cá (thứ nhất) | 魚 | ngư | biểu nghĩa | cá (thứ hai) | 魚 | ngư | biểu nghĩa | cá (thứ ba) | 鱻 = 魚 × 3; chữ hội ý tam điệp. Ba chữ Ngư (魚) kết hợp để nhấn mạnh sự tươi sống, nhiều cá. Đây là dạng cổ của 鮮.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiên\": ba con cá tiên tươi (鱻) — ba chữ Ngư (魚) xếp lại thành chữ cá tươi sống. | Gương Hán-Việt | tiên trong \"tươi tiên\" — tươi sống, không ôi | Mở khoá kiến thức | Biết 鱻 (tiên) giúp nhận ra 鮮 (tiên/tiển) — tươi, ít gặp — trong văn bản cổ và kim văn.", "Tự nguyên_Xie": "Chữ hội ý. Theo Wiktionary: ba chữ 魚 (ngư, cá) kết hợp tạo thành 鱻. Nguyên nghĩa là cá tươi sống, là dạng cổ của 鮮. Khi ba bộ giống nhau ghép lại thường mang nghĩa nhiều hoặc nhấn mạnh đặc tính. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá tươi; sáng sủa; ngon lành", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "品 (Kiến trúc tam giác)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴魚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鱻", "Unihan_Traditional (Chữ Phồn thể)": "鱻", "Pinyin_Xie": "xiān", "Âm Hán Việt_Xie": "tiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ để miêu tả vị tươi ngon của thức ăn hoặc làm danh từ chỉ các loại cá tươi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鷫', '{"9000": "7878.0", "Chữ Trung Quốc": "鷫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 24 | nét | 鷫 | túc | tượng hình | chim trong tổ hợp 鷫鷞 | 鷫 là chữ độc thể thuộc bộ 鳥, chưa có phân tích cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"túc\": chim túc tắc bay (鷫) — một nửa của tổ hợp 鷫鷞 trong thơ Sở từ. | Gương Hán-Việt | túc trong \"túc trực\" — nghĩa gốc là nghiêm cẩn, chỉnh tề | Mở khoá kiến thức | Biết 鷫 giúp đọc Sở từ và thơ ca cổ điển có miêu tả chim huyền thoại.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ thuộc bộ 鳥, thường xuất hiện trong tổ hợp 鷫鷞 chỉ một loài chim huyền thoại hoặc hiếm gặp trong văn học Sở từ. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuổng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "肅 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰肅鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鹔", "Unihan_Traditional (Chữ Phồn thể)": "鷫", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "túc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong tên gọi loài chim cổ hoặc ngọc quý. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹖', '{"9000": "7879.0", "Chữ Trung Quốc": "鹖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 14 | nét | 鹖 | hạt | tượng hình | chim trĩ tai nâu | 鹖 là chữ độc thể thuộc bộ 鸟, chưa có phân tích cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạt\": chim hạt trĩ dũng mãnh (鹖) — loài trĩ tai nâu gan lì, dùng lông đuôi trang trí mũ chiến binh. | Gương Hán-Việt | hạt trong \"mũ hạt\" — mũ chiến binh cổ đại được trang trí lông chim 鹖 | Mở khoá kiến thức | Biết 鹖 giúp đọc văn bản lịch sử quân sự và điểu học cổ Trung Hoa.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ chỉ loài chim trĩ tai nâu (brown-eared pheasant), nổi tiếng vì lông đuôi dài và tính chiến đấu gan lì. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hạt kê 鶡雞,鹖鸡)", "Hạng Tần Suất (Jun Da)": "7879.0", "Tần Suất % (Jun Da)": "99.9991116464", "GavinGrover_Once (Chiết tự trực tiếp)": "曷 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰曷鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹖", "Unihan_Traditional (Chữ Phồn thể)": "鶡", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim trĩ cổ xưa thường dùng trang trí mũ võ quan. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磩', '{"9000": "7880.0", "Chữ Trung Quốc": "磩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 16 | nét | 磩 | thứ | tượng hình | loại đá; trong 碝磩 | 磩 là chữ độc thể thuộc bộ 石, chưa có phân tích cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thứ\": đá thứ cấp (磩) — bộ Thạch (石) ghép lại, một loại đá trong tổ hợp 碝磩. | Gương Hán-Việt | thứ trong \"thứ hạng\" — loại, hàng thứ | Mở khoá kiến thức | Biết 磩 giúp đọc văn bản địa chất và khoáng vật cổ Trung Hoa.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ thuộc bộ 石, thường xuất hiện trong tổ hợp 碝磩 chỉ loại đá quý hoặc đá trang trí. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "磩", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 戚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石戚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磩", "Unihan_Traditional (Chữ Phồn thể)": "磩", "Pinyin_Xie": "qì", "Âm Hán Việt_Xie": "thứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bậc thềm bằng đá hoặc loại đá có hoa văn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磭', '{"9000": "7881.0", "Chữ Trung Quốc": "磭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 16 | nét | 磭 | xước | tượng hình | môi dày lớn (theo một nguồn) | 磭 là chữ thuộc bộ 石, nhưng nghĩa được ghi là ''môi dày'' — có thể có sự phân loại bộ thủ không thống nhất trong các nguồn cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xước\": xước đá (磭) — bộ 石 nhưng nghĩa liên quan đến hình thái miệng, chữ hiếm gặp. | Gương Hán-Việt | xước trong \"trầy xước\" — vết rạch, cứng chắc | Mở khoá kiến thức | Biết 磭 giúp nhận biết chữ hiếm trong tự điển cổ.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Theo một số tài liệu, 磭 chỉ môi dày hoặc miệng lớn, tuy thuộc bộ 石. Có thể có sự nhầm lẫn hoặc dùng bộ thủ không thống nhất. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "môi lớn", "Hạng Tần Suất (Jun Da)": "7881.0", "Tần Suất % (Jun Da)": "99.9991137135", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 脣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石脣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "脣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磭", "Unihan_Traditional (Chữ Phồn thể)": "磭", "Pinyin_Xie": "chuò", "Âm Hán Việt_Xie": "thác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò danh từ chỉ các loại đá nhám hoặc đá dùng để mài. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稌', '{"9000": "7882.0", "Chữ Trung Quốc": "稌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 12 | nét | 稌 | đồ | tượng hình | lúa nếp, gạo nếp | 稌 là chữ độc thể thuộc bộ 禾, chưa có phân tích cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồ\": lúa đồ nếp (稌) — bộ Hòa (禾, lúa) chỉ giống nếp dẻo trong lễ nghi cổ. | Gương Hán-Việt | đồ trong \"đồ tể\" — chế biến, xử lý; nghĩa gốc là giống lúa | Mở khoá kiến thức | Biết 稌 giúp đọc văn bản nông nghiệp và lễ nghi ẩm thực cổ Trung Hoa.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ thuộc bộ 禾 (lúa), chỉ giống lúa nếp hoặc gạo nếp. Xuất hiện trong Chu Lễ và Kinh Thi. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lúa nếp", "Hạng Tần Suất (Jun Da)": "7882.0", "Tần Suất % (Jun Da)": "99.9991147471", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 余", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾余", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "余", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稌", "Unihan_Traditional (Chữ Phồn thể)": "稌", "Pinyin_Xie": "tú", "Âm Hán Việt_Xie": "đồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cây lúa nếp hoặc hạt gạo nếp trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穃', '{"9000": "7883.0", "Chữ Trung Quốc": "穃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 15 | nét | 穃 | nhung | tượng hình | loại cây ngũ cốc hiếm | 穃 là chữ độc thể thuộc bộ 禾, không có dữ liệu cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhung\": lúa nhung mềm (穃) — bộ Hòa (禾) chỉ loại ngũ cốc mềm, hiếm gặp. | Gương Hán-Việt | nhung trong \"nhung lụa\" — mềm mại, hiếm quý | Mở khoá kiến thức | Biết 穃 giúp nhận biết chữ hiếm trong từ điển nông nghiệp cổ.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ thuộc bộ 禾, chỉ một loại cây ngũ cốc hiếm trong văn bản cổ. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "烃", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 容", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾容", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "容", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "穃", "Unihan_Traditional (Chữ Phồn thể)": "穃", "Pinyin_Xie": "rong", "Âm Hán Việt_Xie": "nhung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này chủ yếu làm tính từ miêu tả trạng thái lúa mọc tươi tốt, xum xuê. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綂', '{"9000": "7884.0", "Chữ Trung Quốc": "綂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 綂 | thống | tượng hình | biến thể của 統, chỉ huy, thống nhất | 綂 là dị thể cổ của 統, thuộc bộ 糸, không có phân tích cấu trúc học thuật riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thống\": thống nhất (綂) — dị thể cổ của 統, bộ Mịch (糸, sợi) kết nối mọi thứ lại. | Gương Hán-Việt | thống trong \"thống nhất\", \"tổng thống\" — cai quản, điều hành | Mở khoá kiến thức | Biết 綂 giúp đọc văn bản cổ khi gặp dị thể của 統.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. 綂 là dị thể cổ của 統 (thống). Bộ 糸 (sợi) trong 統 gợi ý sự kết nối, thống nhất. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tề", "Hạng Tần Suất (Jun Da)": "7884.0", "Tần Suất % (Jun Da)": "99.9991168142", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "綂", "Unihan_Traditional (Chữ Phồn thể)": "綂", "Pinyin_Xie": "tǒng", "Âm Hán Việt_Xie": "thống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này là dạng cổ của chữ Thống, dùng làm danh từ chỉ đầu mối hoặc động từ cai trị. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膥', '{"9000": "7885.0", "Chữ Trung Quốc": "膥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 17 | nét | 膥 | xuân | tượng hình | trứng (phương ngữ Mân) | 膥 là chữ phương ngữ Mân (Hokkien/Teochew) chỉ trứng. Theo Wiktionary là hợp thể của 未成肉 (chưa thành thịt). Không xếp loại hình thanh hay hội ý theo học thuật truyền thống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xuân\": trứng xuân (膥) — phương ngữ Mân dùng âm xuân để gọi trứng, hợp thể 未成肉 (chưa thành thịt). | Gương Hán-Việt | xuân trong \"mùa xuân\" — khởi đầu sự sống, hạt mầm | Mở khoá kiến thức | Biết 膥 giúp đọc văn bản phương ngữ Mân và Triều Châu về ẩm thực.", "Tự nguyên_Xie": "Theo Wiktionary: 膥 là hợp thể của 未成肉 (chưa thành thịt), mô tả trứng là vật chất chưa phát triển thành thịt. Đây là biến thể phương ngữ Mân của chữ 春 khi dùng để chỉ trứng. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "襥", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 肉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱肉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "膥", "Unihan_Traditional (Chữ Phồn thể)": "膥", "Pinyin_Xie": "chūn", "Âm Hán Việt_Xie": "xuân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ trong phương ngôn để chỉ trứng chim, trứng gà hoặc bộ phận sinh dục. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膱', '{"9000": "7886.0", "Chữ Trung Quốc": "膱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 16 | nét | 膱 | chức | tượng hình | mỡ bẩn, mỡ cặn | 膱 là chữ độc thể thuộc bộ 肉 (月), chưa có phân tích cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chức\": mỡ chức năng (膱) — bộ Nhục (肉) chỉ loại mỡ cặn, bẩn trong thực phẩm. | Gương Hán-Việt | chức trong \"chức vụ\" — nghĩa gốc hoàn toàn khác, đây là từ đồng âm | Mở khoá kiến thức | Biết 膱 giúp đọc văn bản ẩm thực và y học cổ về chất mỡ.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ thuộc bộ 肉, chỉ mỡ bẩn hoặc mỡ đặc cặn. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "豱", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "膱", "Unihan_Traditional (Chữ Phồn thể)": "膱", "Pinyin_Xie": "zhí", "Âm Hán Việt_Xie": "chức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ thịt khô hoặc tính từ chỉ mùi thịt ôi thiu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臿', '{"9000": "7887.0", "Chữ Trung Quốc": "臿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 臼 | Số nét | 9 | nét | 干 | can | biểu nghĩa | chày giã | 臼 | cối | biểu nghĩa | cối giã | 臿 = 干 (Can, chày) + 臼 (Cối, cối giã); chữ hội ý. Chày (干) cắm vào cối (臼) mô tả hành động xúc, đào. Nghĩa là cái xẻng hoặc dụng cụ xúc đất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táp\": xẻng táp đất (臿) — chày (干) cắm vào cối (臼) thành hội ý dụng cụ xúc đào. | Gương Hán-Việt | táp trong \"táp nham\" — cứng chắc, liên quan đến đất đá | Mở khoá kiến thức | Biết 臿 giúp đọc văn bản công trình, nông nghiệp cổ về dụng cụ canh tác.", "Tự nguyên_Xie": "Chữ hội ý. Theo Wiktionary: 干 (chày/pestle) + 臼 (cối/mortar) mang nghĩa giã, đào. Chỉ cái xẻng hoặc dụng cụ xúc đất trong nông nghiệp và xây dựng cổ đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1274.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thiên (024) Cữu (134)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thiên (số 024 - ngàn/viết là 干 với nét phẩy) nằm xuyên qua bộ Cữu (số 134 - cối giã gạo/ 臼). Cái tay quay được lắp trên cái cối xay. Giải thích sự chuyển ý: Đây là chữ Tượng hình kiêm Hội ý. Sáp là cái cối xay thóc (hay cái chày giã gạo, cái xẻng xúc đất).", "Nghĩa Tiếng Việt_Xie": "cái thuổng; cái mai", "Hạng Tần Suất (Jun Da)": "7887.0", "Tần Suất % (Jun Da)": "99.9991199149", "GavinGrover_Once (Chiết tự trực tiếp)": "千 + 臼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: lock", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "千臼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "千", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "臼", "Unihan_Simplified (Chữ Giản thể)": "臿", "Unihan_Traditional (Chữ Phồn thể)": "臿", "Pinyin_Xie": "chā", "Âm Hán Việt_Xie": "tráp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này vừa làm danh từ chỉ công cụ đào đất vừa làm động từ với nghĩa cắm, cấy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艎', '{"9000": "7888.0", "Chữ Trung Quốc": "艎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 15 | nét | 艎 | hoàng | tượng hình | thuyền nhanh, thuyền lớn | 艎 là chữ độc thể thuộc bộ 舟 (thuyền), chưa có phân tích cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\": thuyền hoàng gia (艎) — bộ Chu (舟, thuyền) chỉ loại thuyền lớn nhanh. | Gương Hán-Việt | hoàng trong \"hoàng gia\" — to lớn, bề thế | Mở khoá kiến thức | Biết 艎 giúp đọc văn bản thủy chiến và địa lý sông nước cổ Trung Hoa.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ thuộc bộ 舟, chỉ loại thuyền nhanh hoặc thuyền lớn trong văn bản thủy chiến cổ. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuyền lướt nhanh", "Hạng Tần Suất (Jun Da)": "7888.0", "Tần Suất % (Jun Da)": "99.9991209485", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 皇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟皇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艎", "Unihan_Traditional (Chữ Phồn thể)": "艎", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại thuyền lớn hoặc thuyền chiến thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苃', '{"9000": "7889.0", "Chữ Trung Quốc": "苃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 苃 | hữu | tượng hình | loại cỏ cổ đại | 苃 là chữ độc thể thuộc bộ 艸, chưa có phân tích cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hữu\": cỏ hữu ích (苃) — bộ Thảo (艸, cỏ) chỉ loại cỏ trong sách cổ. | Gương Hán-Việt | hữu trong \"hữu ích\" — có lợi, tốt | Mở khoá kiến thức | Biết 苃 giúp nhận biết chữ hiếm trong tự điển thực vật cổ.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ thuộc bộ 艸 (cỏ), chỉ một loại cỏ trong văn bản thực vật học cổ. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "苃", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 友", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹友", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "友", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苃", "Unihan_Traditional (Chữ Phồn thể)": "苃", "Pinyin_Xie": "yǒu", "Âm Hán Việt_Xie": "hữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cỏ hoặc dùng trong tên người, tên đất cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茍', '{"9000": "7890.0", "Chữ Trung Quốc": "茍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 羊 | dương | biểu nghĩa | dê/cừu (hoặc phần trên của chữ) | 卩 | tiết | biểu nghĩa | người ngồi quỳ gối | 茍 = 羊 (Dương, phần trên) + 卩 (Tiết, người quỳ); chữ hội ý. Theo một thuyết mô tả con chó ngồi phục tùng, theo thuyết khác là 羊+卩. Nghĩa là cẩn thận, nếu như, tạm thời.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cẩu\": cẩn thận như cẩu (茍) — hội ý dê (羊) và người quỳ (卩), nghĩa là phục tùng cẩn thận. | Gương Hán-Việt | cẩu trong \"cẩu thả\" — không cẩn thận (nghĩa đảo) | Mở khoá kiến thức | Biết 茍 giúp đọc văn ngôn cổ điển khi gặp liên từ điều kiện ''nếu như''.", "Tự nguyên_Xie": "Chữ hội ý. Theo Wiktionary: có thể mô tả con chó ngồi phục tùng (tượng hình), hoặc là 羊+卩 (người quỳ trước dê/chủ). Chỉ sự cẩn trọng, phục tùng; nghĩa phái sinh là ''nếu như'', ''tạm thời''. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cấp bách", "Hạng Tần Suất (Jun Da)": "7890.0", "Tần Suất % (Jun Da)": "99.9991230156", "GavinGrover_Once (Chiết tự trực tiếp)": "卝 + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱卝句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "卝", "Unihan_Simplified (Chữ Giản thể)": "茍", "Unihan_Traditional (Chữ Phồn thể)": "茍", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "cẩu, cức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường dùng làm động từ tự răn đe hoặc tính từ chỉ sự cấp bách trong văn ngôn cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒟', '{"9000": "7891.0", "Chữ Trung Quốc": "蒟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蒟 | cử | tượng hình | trầu lá (betel) hoặc củ khoai nưa (konjac) | 蒟 là chữ độc thể thuộc bộ 艸, chưa có phân tích cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cử\": cây cử trầu (蒟) — bộ Thảo (艸) chỉ cây có lá dùng ăn trầu hoặc củ konjac. | Gương Hán-Việt | cử trong \"cử chỉ\" — nghĩa gốc hoàn toàn khác, đây là đồng âm | Mở khoá kiến thức | Biết 蒟 giúp đọc bản thảo y học cổ và văn bản thực vật học Trung Hoa.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ thuộc bộ 艸, chỉ cây trầu lá hoặc củ khoai nưa (konjac). Xuất hiện trong các văn bản thực vật học và y học cổ. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: củ tương 蒟醬,蒟酱)", "Hạng Tần Suất (Jun Da)": "7891.0", "Tần Suất % (Jun Da)": "99.9991240492", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 竘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹竘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "竘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒟", "Unihan_Traditional (Chữ Phồn thể)": "蒟", "Pinyin_Xie": "jǔ", "Âm Hán Việt_Xie": "củ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các từ ghép chỉ tên thực vật như củ tương hay ma củ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藣', '{"9000": "7892.0", "Chữ Trung Quốc": "藣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 艸 | tháu | biểu nghĩa | cỏ, cây | 罷 | bãi | biểu âm | nghỉ, thôi (biểu âm) | 藣 = 艸 (Tháu, biểu nghĩa: cỏ/cây) + 罷 (Bãi, biểu âm); chữ hình thanh. Bộ 艸 cho biết liên quan đến thực vật, phần 罷 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bái\": cây bái (藣) — bộ Thảo (艸, cỏ) + Bãi (罷) âm; loại thực vật hiếm gặp. | Gương Hán-Việt | bái trong \"bái phục\" — nghĩa gốc hoàn toàn khác, đây là đồng âm | Mở khoá kiến thức | Biết 藣 giúp đọc văn bản thực vật học cổ Trung Hoa.", "Tự nguyên_Xie": "Chữ hình thanh. Theo Wiktionary: 艸 (cỏ) là bộ phận biểu nghĩa, 罷 là bộ phận biểu âm. Chỉ một loại cây trong thực vật học cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Người kế nhiệm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 罷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹罷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "罷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藣", "Unihan_Traditional (Chữ Phồn thể)": "藣", "Pinyin_Xie": "bēi", "Âm Hán Việt_Xie": "bái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ người kế thừa hoặc nối dõi trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虈', '{"9000": "7893.0", "Chữ Trung Quốc": "虈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 24 | nét | 艸 | tháu | biểu nghĩa | cỏ, cây | 嚻 | hiêu | biểu âm | ồn ào (biểu âm) | 虈 = 艸 (Tháu, biểu nghĩa: cỏ/cây) + 嚻 (Hiêu, biểu âm); chữ hình thanh. Bộ 艸 chỉ thực vật, 嚻 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiêu\": cỏ hiêu thơm (虈) — bộ Thảo (艸, cỏ) + Hiêu (嚻) âm; cây thơm trong Sở từ. | Gương Hán-Việt | hiêu trong \"hiêu hắt\" — mùi bay xa, phảng phất | Mở khoá kiến thức | Biết 虈 giúp đọc Sở từ và thơ phú cổ điển có tên cây thơm.", "Tự nguyên_Xie": "Chữ hình thanh. Theo Wiktionary: 艸 (cỏ) là bộ phận biểu nghĩa, 囂/嚻 là bộ phận biểu âm. Chỉ loại cây thơm trong Sở từ, thường là một loại huệ hoặc cây có hương. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "興", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 嚻", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹嚻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "嚻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "虈", "Unihan_Traditional (Chữ Phồn thể)": "虈", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "hiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ một loại cỏ thơm dùng làm thuốc trong Đông y cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜐', '{"9000": "7894.0", "Chữ Trung Quốc": "蜐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 蜐 | tiết | tượng hình | con hà (barnacle) | 蜐 là chữ độc thể thuộc bộ 虫, chưa có phân tích cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiết\": con tiết hà bám đá (蜐) — bộ Trùng (虫) chỉ loài giáp xác barnacle. | Gương Hán-Việt | tiết trong \"tiết kiệm\" — nghĩa gốc là đốt, khúc; con hà có vỏ đốt | Mở khoá kiến thức | Biết 蜐 giúp đọc văn bản hải sản và sinh học biển cổ Trung Hoa.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ thuộc bộ 虫 (côn trùng/động vật nhỏ), chỉ con hà — loài giáp xác bám vào đá và thuyền bè. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sò đá", "Hạng Tần Suất (Jun Da)": "7894.0", "Tần Suất % (Jun Da)": "99.9991271499", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 劫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫劫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "劫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜐", "Unihan_Traditional (Chữ Phồn thể)": "蜐", "Pinyin_Xie": "jié", "Âm Hán Việt_Xie": "tý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loài động vật nhuyễn thể sống bám vào đá ở biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訅', '{"9000": "7895.0", "Chữ Trung Quốc": "訅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 9 | nét | 訅 | cầu | tượng hình | chữ hiếm, nghĩa không xác định | 訅 là chữ độc thể thuộc bộ 言, chưa có phân tích cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cầu\": lời cầu xin (訅) — bộ Ngôn (言, lời nói) trong chữ hiếm này. | Gương Hán-Việt | cầu trong \"cầu nguyện\" — xin, mong | Mở khoá kiến thức | Biết 訅 giúp nhận biết chữ hiếm trong tự điển cổ thuộc bộ 言.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ thuộc bộ 言 (lời nói), nghĩa không xác định rõ ràng trong các nguồn hiện có. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "訅", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 九", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言九", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "九", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "訅", "Unihan_Traditional (Chữ Phồn thể)": "訅", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "cầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ hành vi ép buộc hoặc oán trách trong văn ngôn cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讈', '{"9000": "7896.0", "Chữ Trung Quốc": "讈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 23 | nét | 讈 | lệ | tượng hình | chữ hiếm, nghĩa không xác định | 讈 là chữ độc thể thuộc bộ 言, không có dữ liệu cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lệ\": lời lệ lạc (讈) — bộ Ngôn (言) trong chữ cực hiếm này. | Gương Hán-Việt | lệ trong \"lệ lạc\" — quy tắc, phép tắc | Mở khoá kiến thức | Biết 讈 giúp nhận biết chữ hiếm trong tự điển cổ.", "Tự nguyên_Xie": "Chưa có nguồn học thuật rõ ràng. Chữ thuộc bộ 言, nghĩa không xác định trong các nguồn hiện có. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "興", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 歷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言歷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "歷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "讈", "Unihan_Traditional (Chữ Phồn thể)": "讈", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ âm thanh lớn hoặc động từ thể hiện sự gầm thét trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趷', '{"9000": "7897.0", "Chữ Trung Quốc": "趷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 10 | nét | 趷 | 趷 | tượng hình | bộ 足 (chân) + âm vị không rõ; chỉ động tác chân | 趷 mang bộ 足 (túc, chân), gợi ý liên quan đến chuyển động của chân. Cấu tạo nội bộ chưa được phân tích đầy đủ trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: bộ 足 (chân) nhớ tới đây là chữ chỉ chuyển động chân — nhảy, giật. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng ghi nhận chữ này. | Mở khoá kiến thức | Chữ cực hiếm, hầu như không xuất hiện trong văn bản hiện đại.", "Tự nguyên_Xie": "趷 là chữ hiếm gặp, mang bộ 足 (túc, chân), dùng để chỉ động tác nhảy hoặc giật cục. Nguồn Wiktionary chưa cung cấp phân tích nguồn gốc chi tiết. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhảy", "Hạng Tần Suất (Jun Da)": "7897.0", "Tần Suất % (Jun Da)": "99.9991323178", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 乞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊乞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "趷", "Unihan_Traditional (Chữ Phồn thể)": "趷", "Pinyin_Xie": "kē", "Âm Hán Việt_Xie": "khất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ mô tả động tác co chân hoặc nhảy lên trong bạch thoại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹹', '{"9000": "7898.0", "Chữ Trung Quốc": "蹹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 19 | nét | 蹹 | 蹹 | tượng hình | dị thể của 踏; bộ 足 (chân) + âm phần | 蹹 là dị thể cổ của 踏, mang bộ 足 (túc, chân). Wiktionary xác nhận đây là hình thức thay thế (alt form) của 踏.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: nhớ 蹹 = dị thể của 踏 (đạp) — cùng bộ 足 (chân), cùng nghĩa dẫm lên. | Gương Hán-Việt | Dị thể của 踏; không có từ Hán-Việt riêng. | Mở khoá kiến thức | Hiểu 蹹 giúp nhận ra các dị thể chữ cổ trong văn bản cổ điển.", "Tự nguyên_Xie": "蹹 là dị thể của 踏 (dẫm, đạp), cùng bộ 足 (chân). Wiktionary ghi nhận 蹹 như một hình thức thay thế không phổ biến của 踏, nghĩa là dẫm lên, bước lên. Không còn dùng trong văn viết hiện đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 翕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊翕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹹", "Unihan_Traditional (Chữ Phồn thể)": "蹹", "Pinyin_Xie": "tá", "Âm Hán Việt_Xie": "đạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động giẫm lên hoặc dùng chân đá mạnh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鋫', '{"9000": "7899.0", "Chữ Trung Quốc": "鋫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 鋫 | 鋫 | tượng hình | bộ 金 (kim loại); nghĩa và cấu tạo không rõ | 鋫 mang bộ 金 (kim, kim loại). Cấu tạo và nguồn gốc chưa được phân tích trong các nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: bộ 金 (kim loại) nhớ tới đây là chữ liên quan đến kim khí, song nghĩa thực tế rất hiếm gặp. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng ghi nhận chữ này. | Mở khoá kiến thức | Chữ cực hiếm, hầu như không xuất hiện trong văn bản thông thường.", "Tự nguyên_Xie": "鋫 là chữ cực hiếm, mang bộ 金 (kim loại). Không có phân tích nguồn gốc trong Wiktionary. Nghĩa ghi nhận là ''狫'' — tên một sắc tộc cổ. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "狫", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "利 + 金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱利金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "利", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鋫", "Unihan_Traditional (Chữ Phồn thể)": "鋫", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ cổ rất hiếm gặp, chủ yếu dùng làm tên riêng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('騛', '{"9000": "7900.0", "Chữ Trung Quốc": "騛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 19 | nét | 騛 | 騛 | tượng hình | bộ 馬 (ngựa); chỉ ngựa phi nhanh | 騛 mang bộ 馬 (mã, ngựa), gợi ý liên quan đến ngựa hoặc sự di chuyển nhanh. Cấu tạo chi tiết chưa được phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: bộ 馬 (mã, ngựa) + âm fēi như 飛 (bay) → 騛 gợi hình ảnh ngựa phi nhanh như tung cánh. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng ghi nhận chữ này. | Mở khoá kiến thức | Chữ cực hiếm, gần như chỉ xuất hiện trong từ điển chữ Hán.", "Tự nguyên_Xie": "騛 là chữ hiếm, mang bộ 馬 (mã, ngựa), đọc fēi. Wiktionary chưa cung cấp định nghĩa cụ thể (rfdef). Âm fēi trùng với 飛 (bay), gợi hình ảnh ngựa phi nhanh như bay. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "騛", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 飛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬飛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "飛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "騛", "Unihan_Traditional (Chữ Phồn thể)": "騛", "Pinyin_Xie": "fēi", "Âm Hán Việt_Xie": "phi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Dùng làm danh từ chỉ loài ngựa thần chạy nhanh như bay trong truyền thuyết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鰤', '{"9000": "7901.0", "Chữ Trung Quốc": "鰤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 21 | nét | 鰤 | 鰤 | tượng hình | bộ 魚 (cá); chỉ loài cá cam vàng | 鰤 mang bộ 魚 (ngư, cá), chỉ loài cá yellowtail (amberjack). Cấu tạo nội bộ chưa được phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: bộ 魚 (ngư, cá) → 鰤 là cá cam vàng (yellowtail) — loài cá béo ngon dùng làm sashimi. | Gương Hán-Việt | Chưa có từ Hán-Việt; tiếng Việt gọi là ''cá cam vàng'' hoặc ''cá buri''. | Mở khoá kiến thức | Biết 鰤 giúp đọc thực đơn và tài liệu thuỷ sản Nhật-Trung.", "Tự nguyên_Xie": "鰤 là chữ bộ 魚 (ngư, cá), đọc shī, chỉ loài cá yellowtail hay amberjack — loài cá mặn có giá trị cao. Wiktionary ghi nhận nghĩa yellowtail và liệt kê các từ ghép 鰤魚, 五條鰤, 黃條鰤. Không có phân tích cấu tạo chi tiết. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hổ phách", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 師", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚師", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "師", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "𫚕", "Unihan_Traditional (Chữ Phồn thể)": "鰤", "Pinyin_Xie": "shī", "Âm Hán Việt_Xie": "sư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ loài cá cam Nhật Bản thường dùng làm thực phẩm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶢', '{"9000": "7902.0", "Chữ Trung Quốc": "鶢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 20 | nét | 鶢 | 鶢 | tượng hình | bộ 鳥 (chim); chỉ loài chim ven biển | 鶢 mang bộ 鳥 (điểu, chim), chỉ loài chim thường sống ở ven biển. Cấu tạo chi tiết chưa được phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: bộ 鳥 (điểu, chim) + âm yuán → 鶢 là loài chim ven biển — nhớ âm yuán như 遠 (xa) gợi chim bay trên sóng biển xa. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Chữ cực hiếm, hầu như chỉ xuất hiện trong từ điển chữ Hán.", "Tự nguyên_Xie": "鶢 là chữ bộ 鳥 (điểu, chim), đọc yuán, chỉ loài chim thường xuất hiện ở bờ biển. Wiktionary ghi nhận chủ yếu dùng trong từ ghép 鶢鶋 (tên loài chim biển cụ thể). Không có phân tích cấu tạo. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鶢", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鶢", "Unihan_Traditional (Chữ Phồn thể)": "鶢", "Pinyin_Xie": "yuán", "Âm Hán Việt_Xie": "viên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim nước thời cổ, thường xuất hiện trong từ ghép viên cừ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶳', '{"9000": "7903.0", "Chữ Trung Quốc": "鶳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 21 | nét | 鶳 | 鶳 | tượng hình | bộ 鳥 (chim); loài chim chưa xác định | 鶳 mang bộ 鳥 (điểu, chim). Cấu tạo và nghĩa cụ thể không được ghi nhận trong các nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: bộ 鳥 (điểu, chim) — 鶳 là tên loài chim cực hiếm chưa được xác định rõ trong học thuật. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Chữ cực hiếm, hầu như chỉ xuất hiện trong từ điển chữ Hán.", "Tự nguyên_Xie": "鶳 là chữ cực hiếm, mang bộ 鳥 (điểu, chim). Wiktionary chỉ có phần {{Han etym}} mà không có nội dung phân tích cụ thể. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鶳", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鳥 + 師", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鳥師", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "師", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鶳", "Unihan_Traditional (Chữ Phồn thể)": "鶳", "Pinyin_Xie": "shī", "Âm Hán Việt_Xie": "sư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim cổ, thường dùng trong văn bản cổ hoặc tên riêng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黋', '{"9000": "7904.0", "Chữ Trung Quốc": "黋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黃 | Số nét | 17 | nét | 黋 | 黋 | tượng hình | bộ 黃 (vàng); nghĩa và cấu tạo không rõ | 黋 mang bộ 黃 (hoàng, màu vàng). Cấu tạo và nguồn gốc chưa được phân tích trong các nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: bộ 黃 (hoàng, vàng) — 黋 là chữ cổ hiếm gặp, nghĩa tiêu cực liên quan đến hành vi không đứng đắn. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Chữ cực hiếm, hầu như không xuất hiện trong văn bản hiện đại.", "Tự nguyên_Xie": "黋 là chữ cực hiếm, mang bộ 黃 (hoàng, màu vàng). Không có phân tích nguồn gốc trong Wiktionary. Nghĩa ghi nhận mang hàm ý tiêu cực về hành vi đồi truỵ. Chữ tạo muộn. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đĩ điếm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "光 + 黄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴光黄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "光", "Unihan_Simplified (Chữ Giản thể)": "黋", "Unihan_Traditional (Chữ Phồn thể)": "黋", "Pinyin_Xie": "kuàng", "Âm Hán Việt_Xie": "khoáng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả trạng thái sáng sủa hoặc sắc vàng, ít dùng trong tiếng Trung hiện đại. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齢', '{"9000": "7905.0", "Chữ Trung Quốc": "齢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 17 | nét | 齢 | 齢 | tượng hình | biến thể Nhật của 齡; bộ 齒 (răng) + 令; chỉ tuổi tác | 齢 là biến thể chữ Nhật (shinjitai) của 齡 (thể phồn/giản thể: 龄). Mang bộ 齒 (xỉ, răng) + 令 (lệnh). Răng là chỉ dấu của tuổi tác trong văn hoá Hán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: bộ 齒 (xỉ, răng) → 齢 là tuổi tác — nhớ răng người già bị mòn theo năm tháng. | Gương Hán-Việt | Tương ứng với 齡 (linh) trong từ Hán-Việt: 年齡 (niên linh, tuổi tác), 高齡 (cao linh). | Mở khoá kiến thức | Biết 齢 giúp đọc văn bản tiếng Nhật và nhận ra dạng phồn thể 齡 trong tiếng Hán.", "Tự nguyên_Xie": "齢 là biến thể Nhật Bản của chữ 齡 (Hán phồn thể)/龄 (Hán giản thể), nghĩa là tuổi, số tuổi. Bộ 齒 (xỉ, răng) — vì răng phản ánh tuổi tác — kết hợp với 令 (lệnh). Không có phân tích nguồn gốc riêng trong Wiktionary. chưa có nguồn học thuật độc lập. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Biến thể tiếng Nhật của 齡", "Hạng Tần Suất (Jun Da)": "7905.0", "Tần Suất % (Jun Da)": "99.9991498885", "GavinGrover_Once (Chiết tự trực tiếp)": "⻭ + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻭令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻭", "Unihan_Simplified (Chữ Giản thể)": "齢", "Unihan_Traditional (Chữ Phồn thể)": "齢", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ tuổi tác, thường dùng trong tiếng Nhật hoặc văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聝', '{"9000": "7906.0", "Chữ Trung Quốc": "聝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 14 | nét | 耳 | nhĩ | biểu nghĩa | tai | 或 | hoặc | biểu âm | giáo mác, vũ khí; âm guó | 聝 = 耳 (Nhĩ, biểu nghĩa: tai) + 或 (Hoặc, biểu âm: giáo/vũ khí, âm guó); chữ hình thanh. Kết hợp bộ 耳 (tai) với âm 或 chỉ hành động cắt tai kẻ địch sau chiến trận, một tục lệ cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: 耳 (nhĩ, tai) + 或 (hoặc, âm) → 聝 là hành động cắt tai địch sau chiến — tục lệ cổ đại dùng tai người để chứng minh công trận. | Gương Hán-Việt | Dị thể của 馘; không có từ Hán-Việt riêng. | Mở khoá kiến thức | Biết 聝 giúp đọc văn bản quân sự cổ đại, đặc biệt mô tả nghi lễ chiến trận.", "Tự nguyên_Xie": "聝 là chữ hình thanh, ghép 耳 (nhĩ, tai, biểu nghĩa) với 或 (hoặc, giáo/vũ khí, biểu âm). Nghĩa là cắt tai trái của kẻ địch đã bị giết — một tục lệ chiến trận cổ đại để tính công. Wiktionary ghi nhận 聝 được thay thế bởi 馘. Theo Wiktionary. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem \"馘\"", "Hạng Tần Suất (Jun Da)": "7906.0", "Tần Suất % (Jun Da)": "99.9991540227", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 或", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳或", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "或", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聝", "Unihan_Traditional (Chữ Phồn thể)": "聝", "Pinyin_Xie": "guó", "Âm Hán Việt_Xie": "quắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động cắt tai quân địch thời xưa để tính công trạng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膴', '{"9000": "7907.0", "Chữ Trung Quốc": "膴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 16 | nét | 膴 | 膴 | tượng hình | bộ 肉/月 (thịt); chỉ thịt dày, đất màu mỡ | 膴 mang bộ 肉 (nhục, thịt, viết tắt thành 月 bên trái). Cấu tạo chi tiết chưa được phân tích trong nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: bộ 肉 (nhục, thịt) → 膴 gợi hình ảnh thịt dày, đất đai phong phú — nghĩa sung túc, màu mỡ. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Chữ hiếm, chủ yếu gặp trong văn ngôn miêu tả đất đai màu mỡ.", "Tự nguyên_Xie": "膴 là chữ bộ 肉 (nhục, thịt), đọc wú, nghĩa là thịt dày, phong phú; cũng chỉ đất đai màu mỡ. Wiktionary không có phân tích cấu tạo chi tiết. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "miếng thịt lớn; thịt khô", "Hạng Tần Suất (Jun Da)": "7907.0", "Tần Suất % (Jun Da)": "99.9991550563", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 無", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月無", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "無", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膴", "Unihan_Traditional (Chữ Phồn thể)": "膴", "Pinyin_Xie": "hū", "Âm Hán Việt_Xie": "hô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ miếng thịt cúng tế lớn hoặc tính từ chỉ sự béo tốt, giàu có. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芵', '{"9000": "7908.0", "Chữ Trung Quốc": "芵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 芵 | 芵 | tượng hình | bộ 艸/艹 (cỏ); tên loài thực vật | 芵 mang bộ 艸 (thảo, cỏ), chỉ một loại thực vật. Cấu tạo chi tiết chưa được phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: bộ 艹 (thảo, cỏ) → 芵 là tên cây cỏ hiếm gặp trong thực vật học cổ. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Chữ cực hiếm, hầu như chỉ xuất hiện trong từ điển thực vật học cổ.", "Tự nguyên_Xie": "芵 là chữ bộ 艸 (thảo, cỏ), đọc jué, chỉ một loài thực vật cụ thể. Wiktionary không có phân tích cấu tạo chi tiết. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tín dụng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 夬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹夬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芵", "Unihan_Traditional (Chữ Phồn thể)": "芵", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cây thân thảo dùng làm thuốc trong Đông y. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藫', '{"9000": "7909.0", "Chữ Trung Quốc": "藫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 藫 | 藫 | tượng hình | bộ 艸/艹 (cỏ); loài thực vật thuỷ sinh | 藫 mang bộ 艸 (thảo, cỏ), chỉ một loài thực vật thuỷ sinh. Cấu tạo chi tiết chưa được phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: bộ 艹 (thảo, cỏ) + âm tán → 藫 là loài cỏ nước hiếm trong thực vật học cổ. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Chữ cực hiếm, hầu như chỉ xuất hiện trong từ điển thực vật học cổ.", "Tự nguyên_Xie": "藫 là chữ bộ 艸 (thảo, cỏ), đọc tán, chỉ loài thực vật thuỷ sinh — có thể là một loại rong hoặc cỏ nước. Wiktionary không có phân tích cấu tạo chi tiết. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hắc ín", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "藫", "Unihan_Traditional (Chữ Phồn thể)": "藫", "Pinyin_Xie": "tán", "Âm Hán Việt_Xie": "đàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loài thực vật thủy sinh như tảo hoặc rêu dưới nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跰', '{"9000": "7910.0", "Chữ Trung Quốc": "跰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 13 | nét | 跰 | 跰 | tượng hình | bộ 足 (chân); chỉ cách bước đi song song | 跰 mang bộ 足 (túc, chân), chỉ cách đi bước song song hoặc sánh đôi. Cấu tạo chi tiết chưa được phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: bộ 足 (túc, chân) → 跰 gợi hình ảnh hai chân bước song song — đi sánh đôi. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Chữ hiếm, chủ yếu gặp trong văn ngôn miêu tả dáng đi.", "Tự nguyên_Xie": "跰 là chữ bộ 足 (túc, chân), đọc pián, chỉ bước đi song song hoặc dáng đi nhẹ nhàng. Wiktionary không có phân tích cấu tạo chi tiết. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "móng chân ngay và phẳng của giống thú; chai (phần da dày lên)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 并", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊并", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "并", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跰", "Unihan_Traditional (Chữ Phồn thể)": "跰", "Pinyin_Xie": "pián", "Âm Hán Việt_Xie": "kiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này dùng làm tính từ miêu tả vết chai hoặc móng chân phẳng của loài thú. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踥', '{"9000": "7911.0", "Chữ Trung Quốc": "踥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 15 | nét | 踥 | 踥 | tượng hình | bộ 足 (chân); chỉ bước đi nhanh | 踥 mang bộ 足 (túc, chân), chỉ bước đi nhanh, thoăn thoắt. Cấu tạo chi tiết chưa được phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: bộ 足 (túc, chân) + âm qiè → 踥 gợi bước chân nhanh thoăn thoắt. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Chữ hiếm, chủ yếu gặp trong văn ngôn miêu tả dáng đi.", "Tự nguyên_Xie": "踥 là chữ bộ 足 (túc, chân), đọc qiè, chỉ bước đi nhanh hoặc nhẹ nhàng. Wiktionary không có phân tích cấu tạo chi tiết. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bước rảo, bước vội", "Hạng Tần Suất (Jun Da)": "7911.0", "Tần Suất % (Jun Da)": "99.9991643584", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 妾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊妾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "妾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踥", "Unihan_Traditional (Chữ Phồn thể)": "踥", "Pinyin_Xie": "qiè", "Âm Hán Việt_Xie": "thiếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ miêu tả dáng đi nhanh hoặc vội vã trong văn cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迆', '{"9000": "7912.0", "Chữ Trung Quốc": "迆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 6 | nét | 迆 | 迆 | tượng hình | bộ 辵/辶 (đi bộ); chỉ đường ngoằn ngoèo kéo dài | 迆 mang bộ 辵 (xước/辶, đi bộ, di chuyển), chỉ đường đi ngoằn ngoèo hoặc kéo dài. Cấu tạo chi tiết chưa được phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: bộ 辶 (đi bộ) → 迆 gợi hình ảnh con đường uốn lượn chạy dài về phía xa. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Chữ hiếm, chủ yếu gặp trong thơ cổ miêu tả địa hình uốn lượn.", "Tự nguyên_Xie": "Tiểu triện | 迆 là chữ bộ 辵 (辶, đi bộ/di chuyển), đọc yǐ, nghĩa là ngoằn ngoèo kéo dài, uốn lượn. Cũng có âm đọc biến thể yí. Wiktionary không có phân tích cấu tạo chi tiết. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thế đất quanh co", "Hạng Tần Suất (Jun Da)": "7912.0", "Tần Suất % (Jun Da)": "99.999165392", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 也", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶也", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "也", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迆", "Unihan_Traditional (Chữ Phồn thể)": "迆", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di, dĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm tính từ miêu tả địa hình đồi núi uốn lượn, kéo dài. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逤', '{"9000": "7913.0", "Chữ Trung Quốc": "逤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 10 | nét | 逤 | 逤 | tượng hình | bộ 辵/辶 (đường đi); nghĩa không rõ | 逤 mang bộ 辵 (辶, đi bộ/đường đi). Cấu tạo và nghĩa cụ thể không được ghi nhận trong các nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định: bộ 辶 (đường đi) — 逤 là chữ cực hiếm chưa xác định được nghĩa cụ thể. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Chữ cực hiếm, hầu như chỉ xuất hiện trong từ điển chữ Hán.", "Tự nguyên_Xie": "逤 là chữ cực hiếm, mang bộ 辵 (辶, đường đi). Không có phân tích nguồn gốc hay định nghĩa trong Wiktionary. Chữ tạo muộn. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ở lại", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 沙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶沙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "沙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逤", "Unihan_Traditional (Chữ Phồn thể)": "逤", "Pinyin_Xie": "suò", "Âm Hán Việt_Xie": "tác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này là động từ cổ chỉ hành động dừng lại hoặc dáng đi không vững. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麅', '{"9000": "7914.0", "Chữ Trung Quốc": "麅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 16 | nét | 麅 | bào | tượng hình | con nai, con hoẵng | 麅 thuộc bộ 鹿 (lộc – hươu nai), chỉ loài hươu nai nhỏ. Không có phân tích cấu trúc Wiktionary. Chưa có nguồn học thuật đầy đủ về glyph origin.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bào\": con nai (bộ 鹿) chạy nhanh như tên bắn — bào gợi tốc độ. | Gương Hán-Việt | bào lộc (麅鹿 — nai hoẵng), ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 麅 giúp nhận diện các loài nai trong văn bản sinh học và cổ văn Trung Quốc.", "Tự nguyên_Xie": "Chữ thuộc bộ 鹿 (lộc), chỉ loài nai nhỏ hoặc hoẵng (Capreolus). Không có dữ liệu glyph origin từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con nai", "Hạng Tần Suất (Jun Da)": "7914.0", "Tần Suất % (Jun Da)": "99.9991757277", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 包", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿包", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "包", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麅", "Unihan_Traditional (Chữ Phồn thể)": "麅", "Pinyin_Xie": "páo", "Âm Hán Việt_Xie": "bào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài động vật thuộc họ hươu nai. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缷', '{"9000": "7915.0", "Chữ Trung Quốc": "缷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 缶 | Số nét | 8 | nét | 缷 | tháo | tượng hình | dỡ, tháo xuống, bỏ ra | 缷 thuộc bộ 缶 (phẫu – vò, bình), chỉ hành động dỡ/tháo/bỏ xuống. Không có phân tích compound Wiktionary. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiết\": tay tháo đồ ra khỏi cái vò (缶) — dỡ xuống, bỏ ra, tháo gỡ. | Gương Hán-Việt | tháo gỡ, dỡ hàng — chữ ít gặp trong tiếng Việt Hán | Mở khoá kiến thức | Biết 缷 giúp đọc văn bản kỹ thuật và cổ văn miêu tả công việc dỡ hàng, tháo dỡ.", "Tự nguyên_Xie": "Tiểu triện | Chữ bộ 缶 (phẫu – vò/bình), nghĩa là dỡ xuống, tháo ra. Có thể liên quan đến hành động lấy đồ vật ra khỏi bình/vò. Tiểu triện đã ghi nhận. Chưa có nguồn học thuật đầy đủ — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Dỡ; bỏ;gỡ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "缶 + 卩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰缶卩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "缶", "Unihan_Simplified (Chữ Giản thể)": "缷", "Unihan_Traditional (Chữ Phồn thể)": "缷", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "tá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động dỡ hàng hóa hoặc tháo rời các bộ phận. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虙', '{"9000": "7916.0", "Chữ Trung Quốc": "虙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虍 | Số nét | 11 | nét | 虙 | phục | tượng hình | họ người, tên riêng — Phục Hi | 虙 thuộc bộ 虍 (hổ), là chữ dùng làm tên họ/tên người (Phục Hi). Wiktionary ghi chú là tên riêng, không phân tích hội ý hay hình thanh. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phục\": chữ thuộc bộ Hổ (虍) — Phục Hi, ông tổ huyền thoại ẩn sau nanh vuốt hổ. | Gương Hán-Việt | Phục Hi (虙羲 — vị thần tổ trong thần thoại Trung Hoa) | Mở khoá kiến thức | Biết 虙 giúp nhận diện tên thần Phục Hi trong văn học và triết học cổ Trung Quốc.", "Tự nguyên_Xie": "Chữ bộ 虍 (hổ), dùng làm tên riêng: 虙羲 (Phục Hi — vị thần tổ trong thần thoại Trung Quốc), 虙妃 (Phục Phi — nàng tiên trong cổ văn). Chỉ gặp trong tên riêng và cổ văn. Chưa có nguồn học thuật về glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "虙", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虍 + 必", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴虍必", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "必", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虍", "Unihan_Simplified (Chữ Giản thể)": "虙", "Unihan_Traditional (Chữ Phồn thể)": "虙", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Động từ | 动词 | Chữ này chủ yếu dùng làm danh từ riêng chỉ họ người hoặc dùng như chữ phục với nghĩa ẩn nấp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齗', '{"9000": "7917.0", "Chữ Trung Quốc": "齗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 19 | nét | 齗 | ngân | tượng hình | nướu răng | 齗 thuộc bộ 齒 (xỉ – răng), chỉ nướu răng. Wiktionary không phân tích compound rõ ràng. Có tiểu triện và lục thư thông. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngân\": bộ Răng (齒) — nướu răng, mép nướu, chỗ tiếp giáp giữa răng và lợi. | Gương Hán-Việt | ngân (nướu răng) — ít gặp trong tiếng Việt Hán hiện đại | Mở khoá kiến thức | Biết 齗 giúp đọc văn bản y học cổ và mô tả giải phẫu miệng trong Đông y.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ bộ 齒 (xỉ – răng), nghĩa là nướu răng hoặc mép răng. Tiểu triện đã ghi nhận. Từ ghép 齗齗 chỉ sự tranh cãi ồn ào — có lẽ hình ảnh hai hàm răng chạm nhau. Chưa có nguồn học thuật đầy đủ — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Phúc Kiến", "Hạng Tần Suất (Jun Da)": "6468.0", "Tần Suất % (Jun Da)": "99.9926725036", "GavinGrover_Once (Chiết tự trực tiếp)": "齒 + 斤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齒斤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齒", "Unihan_Simplified (Chữ Giản thể)": "龂", "Unihan_Traditional (Chữ Phồn thể)": "齗", "Pinyin_Xie": "yín", "Âm Hán Việt_Xie": "ngân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ phần nướu răng hoặc làm động từ chỉ sự tranh cãi gay gắt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裓', '{"9000": "7918.0", "Chữ Trung Quốc": "裓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 12 | nét | 裓 | cách | tượng hình | vạt áo, túi trong áo | 裓 thuộc bộ 衣 (y – áo), chỉ vạt áo hoặc túi trong tà áo. Wiktionary ghi nhận chữ này nhưng không phân tích hội ý hay hình thanh rõ ràng. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cách\": bộ Áo (衣) — vạt áo, cái túi nhỏ khâu trong tà áo người xưa. | Gương Hán-Việt | y cách (衣裓 — túi trong áo), ít gặp trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 裓 giúp đọc mô tả trang phục cổ và văn bản về y phục truyền thống Trung Quốc.", "Tự nguyên_Xie": "Chữ bộ 衣 (y – áo), nghĩa là vạt áo hoặc phần túi bên trong áo (衣裓). Gặp trong từ cổ 衣裓 chỉ túi trong áo để đựng đồ. Chưa có nguồn học thuật đầy đủ về glyph origin — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "裓", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "裓", "Unihan_Traditional (Chữ Phồn thể)": "裓", "Pinyin_Xie": "gé", "Âm Hán Việt_Xie": "cách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần vạt áo trước ngực của tăng sĩ Phật giáo dùng để đựng hoa cúng dường. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铹', '{"9000": "7919.0", "Chữ Trung Quốc": "铹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 铹 | lao | tượng hình | nguyên tố Lawrencium (Lr), số nguyên tử 103 | 铹 thuộc bộ 金 (kim – kim loại), là chữ phiên âm hiện đại chỉ nguyên tố hóa học Lawrencium (Lr). Chữ tạo muộn theo quy ước phiên âm nguyên tố trong tiếng Trung.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lao\": kim loại (金) mang tên Lawrence — 铹 là Lawrencium, nguyên tố phóng xạ siêu nặng. | Gương Hán-Việt | lao (铹 – Lawrencium), thuật ngữ hóa học hiện đại | Mở khoá kiến thức | Biết 铹 giúp đọc bảng tuần hoàn và văn bản hóa học tiếng Trung hiện đại.", "Tự nguyên_Xie": "Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. 铹 = 钅(kim – kim loại) + 劳 (lao – biểu âm), phiên âm tên nhà khoa học Ernest Lawrence để đặt tên nguyên tố Lawrencium (Lr, Z=103). Quy ước tạo chữ: bộ 金 chỉ kim loại + âm Hán gần với tên gốc. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố lorenxi, Lw", "Hạng Tần Suất (Jun Da)": "7919.0", "Tần Suất % (Jun Da)": "99.9991829627", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 劳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅劳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "劳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铹", "Unihan_Traditional (Chữ Phồn thể)": "鐒", "Pinyin_Xie": "láo", "Âm Hán Việt_Xie": "lao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chuyên ngành hóa học để chỉ nguyên tố phóng xạ nhân tạo Lawrencium. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睙', '{"9000": "7920.0", "Chữ Trung Quốc": "睙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 13 | nét | 睙 | liệt | tượng hình | cuộn nhãn cầu, liếc mắt | 睙 thuộc bộ 目 (mục – mắt), chỉ động tác cuộn nhãn cầu hoặc liếc mắt. Không có phân tích compound Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liệt\": con mắt (目) liếc nhanh một cái — cuộn nhãn cầu nhìn nghiêng. | Gương Hán-Việt | liệt (睙 – liếc mắt), ít gặp trong tiếng Việt Hán | Mở khoá kiến thức | Biết 睙 giúp đọc văn bản miêu tả nét mặt, cử chỉ trong văn học cổ Trung Quốc.", "Tự nguyên_Xie": "Chữ bộ 目 (mục – mắt), nghĩa là cuộn nhãn cầu để nhìn, liếc. Không có dữ liệu glyph origin từ Wiktionary. Chưa có nguồn học thuật — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cuộn nhãn cầu để nhìn", "Hạng Tần Suất (Jun Da)": "7920.0", "Tần Suất % (Jun Da)": "99.9991839963", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 戾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目戾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睙", "Unihan_Traditional (Chữ Phồn thể)": "睙", "Pinyin_Xie": "liè", "Âm Hán Việt_Xie": "liệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động chuyển động nhãn cầu để nhìn xéo hoặc liếc mắt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矟', '{"9000": "7921.0", "Chữ Trung Quốc": "矟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 矛 | Số nét | 12 | nét | 矟 | sác | tượng hình | cái giáo dài, ngọn giáo | 矟 thuộc bộ 矛 (mâu – giáo), là dạng thay thế của chữ 槊 (sác), chỉ cây giáo dài. Wiktionary ghi chú đây là dị thể của 槊. Chưa có phân tích compound riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sác\": bộ Mâu (矛) — cây giáo dài sắc bén, sác gợi tiếng thét xung trận. | Gương Hán-Việt | sác (矟/槊 – giáo dài), ít gặp trong tiếng Việt Hán hiện đại | Mở khoá kiến thức | Biết 矟 giúp đọc văn bản lịch sử quân sự và tiểu thuyết võ hiệp Trung Quốc.", "Tự nguyên_Xie": "Chữ là dị thể của 槊 (sác – giáo dài), thuộc bộ 矛 (mâu – giáo). Wiktionary ghi rõ: alt form of 槊, nghĩa là cây giáo dài dùng trong chiến trận. Từ ghép cổ: 黑矟公 (Hắc Sác Công – biệt danh tướng cầm giáo đen). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái giáo dài; một trò đánh cờ", "Hạng Tần Suất (Jun Da)": "7921.0", "Tần Suất % (Jun Da)": "99.9991850298", "GavinGrover_Once (Chiết tự trực tiếp)": "矛 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰矛肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "矛", "Unihan_Simplified (Chữ Giản thể)": "矟", "Unihan_Traditional (Chữ Phồn thể)": "矟", "Pinyin_Xie": "shuò", "Âm Hán Việt_Xie": "sác, sáo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại binh khí cổ hoặc một trò chơi cờ thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硣', '{"9000": "7922.0", "Chữ Trung Quốc": "硣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 12 | nét | 硣 | tiêu | tượng hình | loại đá, khoáng chất | 硣 thuộc bộ 石 (thạch – đá), chỉ một loại đá hoặc khoáng chất. Không có phân tích compound Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": đá (石) mang âm tiêu — loại đá khoáng vật hiếm gặp trong địa chất cổ. | Gương Hán-Việt | tiêu (硣 – khoáng thạch), ít gặp trong tiếng Việt Hán | Mở khoá kiến thức | Biết 硣 giúp nhận diện tên khoáng vật hiếm trong văn bản địa chất và dược liệu Đông y cổ.", "Tự nguyên_Xie": "Chữ bộ 石 (thạch – đá). Không có dữ liệu glyph origin từ Wiktionary. Chưa có nguồn học thuật — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "硣", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 孝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石孝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硣", "Unihan_Traditional (Chữ Phồn thể)": "硣", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ tượng thanh | 象声词 | Chữ này làm danh từ chỉ âm thanh hoặc từ mô phỏng tiếng các tảng đá va vào nhau. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磹', '{"9000": "7923.0", "Chữ Trung Quốc": "磹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 17 | nét | 磹 | đam | tượng hình | nêm đá, chốt đá | 磹 thuộc bộ 石 (thạch – đá), chỉ viên đá dùng làm nêm hoặc chốt. Wiktionary ghi nhận nhưng không phân tích cấu trúc compound rõ ràng. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đam\": viên đá (石) nhỏ nhét vào khe để giữ chặt — đam, nêm, chốt. | Gương Hán-Việt | đam (磹 – nêm đá), ít gặp trong tiếng Việt Hán | Mở khoá kiến thức | Biết 磹 giúp đọc văn bản kiến trúc và kỹ thuật xây dựng cổ Trung Quốc.", "Tự nguyên_Xie": "Chữ bộ 石 (thạch – đá), nghĩa là nêm bằng đá, đặt đá làm chốt giữ. Wiktionary ghi nhận nhưng không phân tích glyph origin. Chưa có nguồn học thuật đầy đủ — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nêm đá", "Hạng Tần Suất (Jun Da)": "7923.0", "Tần Suất % (Jun Da)": "99.999187097", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 覃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石覃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "覃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磹", "Unihan_Traditional (Chữ Phồn thể)": "磹", "Pinyin_Xie": "tán", "Âm Hán Việt_Xie": "điệm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ cái nêm bằng đá hoặc động từ chỉ hành động chêm đá cho chặt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礀', '{"9000": "7924.0", "Chữ Trung Quốc": "礀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 17 | nét | 礀 | giản | tượng hình | khe núi, hẻm đá | 礀 thuộc bộ 石 (thạch – đá), chỉ khe núi hoặc hẻm đá. Không có phân tích compound Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giản\": đá (石) hai bên kẹp lấy — khe giản, hẻm núi sâu. | Gương Hán-Việt | giản (礀 – khe đá núi), ít gặp trong tiếng Việt Hán | Mở khoá kiến thức | Biết 礀 giúp đọc thơ văn miêu tả phong cảnh núi non và địa danh trong cổ thi Trung Quốc.", "Tự nguyên_Xie": "Chữ bộ 石 (thạch – đá), nghĩa là khe núi, hẻm đá giữa các tảng đá lớn. Không có dữ liệu glyph origin từ Wiktionary. Chưa có nguồn học thuật — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "礀", "Hạng Tần Suất (Jun Da)": "7924.0", "Tần Suất % (Jun Da)": "99.9991881306", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 閒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石閒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "閒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礀", "Unihan_Traditional (Chữ Phồn thể)": "礀", "Pinyin_Xie": "jian", "Âm Hán Việt_Xie": "giản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ khe suối nhỏ chảy giữa hai sườn núi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秶', '{"9000": "7925.0", "Chữ Trung Quốc": "秶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 11 | nét | 秶 | tư | tượng hình | kê, lúa mạch dùng tế lễ | 秶 thuộc bộ 禾 (hoà – lúa), là dị thể của 粢 (tư), chỉ loại kê dùng trong nghi lễ tế tự. Wiktionary ghi: alt form of 粢 (millet). Chưa có phân tích compound riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": cây lúa (禾) đặc biệt dành cho tế lễ — hạt kê tư dâng thần, không được ăn thường ngày. | Gương Hán-Việt | tư lương (粢糧 – lương thực tế lễ), ít gặp trong tiếng Việt Hán hiện đại | Mở khoá kiến thức | Biết 秶/粢 giúp đọc văn bản nghi lễ tế tự và kinh điển Nho giáo.", "Tự nguyên_Xie": "Tiểu triện | Dị thể của 粢 (tư – kê tế lễ), thuộc bộ 禾 (hoà – lúa). Wiktionary xác nhận: alt form of 粢, nghĩa là kê hoặc ngũ cốc dùng trong tế lễ. Tiểu triện đã ghi nhận. Nghĩa gốc là các loại ngũ cốc dâng cúng thần linh. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Yao", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "次 + 禾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱次禾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "次", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秶", "Unihan_Traditional (Chữ Phồn thể)": "秶", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại ngũ cốc dâng cúng trong các nghi lễ cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窇', '{"9000": "7926.0", "Chữ Trung Quốc": "窇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 10 | nét | 窇 | bạc | tượng hình | hang hốc, chỗ trũng | 窇 thuộc bộ 穴 (huyệt – hang, lỗ hổng), chỉ chỗ trũng hoặc hốc nhỏ. Wiktionary ghi nhận nhưng không định nghĩa rõ (rfdef). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạc\": cái hang (穴) nông và trũng — bạc gợi cạn, rỗng, không sâu. | Gương Hán-Việt | bạc (窇 – hang hốc), ít gặp trong tiếng Việt Hán | Mở khoá kiến thức | Biết 窇 giúp nhận diện chữ bộ 穴 trong văn bản địa lý và miêu tả địa hình cổ.", "Tự nguyên_Xie": "Chữ bộ 穴 (huyệt – hang, lỗ hổng). Wiktionary ghi nhận chữ này nhưng đánh dấu rfdef (cần định nghĩa thêm), chưa có nghĩa xác định rõ ràng. Chưa có nguồn học thuật — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "窇", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 包", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴包", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "包", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窇", "Unihan_Traditional (Chữ Phồn thể)": "窇", "Pinyin_Xie": "báo", "Âm Hán Việt_Xie": "bạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động đào đất hoặc danh từ chỉ hang hốc nhỏ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('竷', '{"9000": "7927.0", "Chữ Trung Quốc": "竷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 立 | Số nét | 20 | nét | 竷 | khảm | tượng hình | dáng nhảy múa, bước đi khập khiễng | 竷 thuộc bộ 立 (lập – đứng), chỉ dáng đi hoặc nhảy múa. Wiktionary ghi nhận nhưng không định nghĩa rõ (rfdef). Tiểu triện đã ghi nhận. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khảm\": đứng (立) mà bước lảo đảo — dáng khảm khiễng như chạm hố. | Gương Hán-Việt | khảm (竷 – bước đi lảo đảo), ít gặp trong tiếng Việt Hán | Mở khoá kiến thức | Biết 竷 giúp nhận diện chữ hiếm thuộc bộ 立 trong cổ văn miêu tả vũ điệu hoặc dáng đi.", "Tự nguyên_Xie": "Tiểu triện | Chữ bộ 立 (lập – đứng). Wiktionary ghi nhận hai âm đọc (kǎn, kàn) nhưng không cho nghĩa cụ thể (rfdef). Chữ tạo muộn, chưa thấy giải thích học thuật rõ ràng — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "竷", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "章 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰章", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "竷", "Unihan_Traditional (Chữ Phồn thể)": "竷", "Pinyin_Xie": "kǎn", "Âm Hán Việt_Xie": "khảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ hoạt động ca hát nhảy múa hoặc tính từ miêu tả sự vui tươi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笣', '{"9000": "7928.0", "Chữ Trung Quốc": "笣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 笣 | vầu | tượng hình | cây tre vầu, một giống tre làm mũi tên | 笣 thuộc bộ 竹 (trúc – tre), chỉ giống tre vầu, loại tre có măng mọc mùa đông. Không có phân tích compound Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vầu\": bộ Tre (竹) — cây vầu thẳng và cứng, xưa dùng làm tên bắn. | Gương Hán-Việt | vầu (笣 – cây vầu), dùng trong tiếng Việt để chỉ loài tre đặc biệt này | Mở khoá kiến thức | Biết 笣 giúp nhận diện tên loài thực vật tre trúc trong văn bản nông lâm và thực vật học cổ.", "Tự nguyên_Xie": "Chữ bộ 竹 (trúc – tre), chỉ cây vầu — một giống tre mà măng mọc mùa đông, thân thường dùng làm mũi tên. Không có dữ liệu glyph origin từ Wiktionary. Chưa có nguồn học thuật — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vầu; như \"tre vầu; cây vầu (một loại cây hay làm mũi tên)\" \n (Danh) Một giống tre; măng nó mọc mùa đông.", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 包", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮包", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "包", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笣", "Unihan_Traditional (Chữ Phồn thể)": "笣", "Pinyin_Xie": "bāo", "Âm Hán Việt_Xie": "bao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài tre thân to hoặc măng mọc vào mùa đông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篃', '{"9000": "7929.0", "Chữ Trung Quốc": "篃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 15 | nét | 篃 | muội | tượng hình | một loại tre | 篃 thuộc bộ 竹 (trúc – tre), chỉ một loài tre. Không có phân tích compound Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"muội\": bộ Tre (竹) — loài tre muội, tên cổ ít người biết đến. | Gương Hán-Việt | muội (篃 – một loại tre), ít gặp trong tiếng Việt Hán | Mở khoá kiến thức | Biết 篃 giúp nhận diện tên loài tre hiếm trong văn bản thực vật học cổ Trung Quốc.", "Tự nguyên_Xie": "Chữ bộ 竹 (trúc – tre), chỉ một loài tre không rõ danh. Không có dữ liệu glyph origin từ Wiktionary. Chưa có nguồn học thuật — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loại tre", "Hạng Tần Suất (Jun Da)": "7929.0", "Tần Suất % (Jun Da)": "99.999194332", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 眉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮眉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "眉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篃", "Unihan_Traditional (Chữ Phồn thể)": "篃", "Pinyin_Xie": "mèi", "Âm Hán Việt_Xie": "lũy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một giống tre nhỏ dùng trong đời sống thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簬', '{"9000": "7930.0", "Chữ Trung Quốc": "簬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 19 | nét | 簬 | rọ | tượng hình | cây tre, loài tre chất lượng cao | 簬 thuộc bộ 竹 (trúc – tre), chỉ loài tre tốt (箘簬). Wiktionary ghi chú dùng trong 箘簬 — cặp từ chỉ hai loài tre quý. Chưa có phân tích compound riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"rọ\": bộ Tre (竹) — cây tre 簬 dùng trong 箘簬, đôi tre quý dùng trong nghi lễ và vũ khí. | Gương Hán-Việt | rọ (簬 – loài tre quý), ít gặp trong tiếng Việt Hán hiện đại | Mở khoá kiến thức | Biết 簬 giúp đọc cổ văn và văn bản kỹ thuật về tre trúc trong văn hóa Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Chữ bộ 竹 (trúc – tre). Wiktionary xác nhận: chữ này chỉ dùng trong từ ghép 箘簬, chỉ loài tre quý dùng làm tên bắn hoặc dụng cụ. Tiểu triện đã ghi nhận. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây tre", "Hạng Tần Suất (Jun Da)": "7930.0", "Tần Suất % (Jun Da)": "99.9991953655", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 路", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮路", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "路", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簬", "Unihan_Traditional (Chữ Phồn thể)": "簬", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại tre thân thẳng và cứng chuyên dùng làm tên bắn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簯', '{"9000": "7931.0", "Chữ Trung Quốc": "簯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 18 | nét | 簯 | kiều | tượng hình | loại tre, cây trúc | 簯 thuộc bộ 竹 (trúc – tre), chỉ một loài tre. Không có phân tích compound Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiều\": bộ Tre (竹) — loài tre kiều, tên cổ còn gặp trong thực vật học lịch sử. | Gương Hán-Việt | kiều (簯 – loài tre), ít gặp trong tiếng Việt Hán | Mở khoá kiến thức | Biết 簯 giúp nhận diện tên loài tre trong thực vật học cổ Trung Quốc.", "Tự nguyên_Xie": "Chữ bộ 竹 (trúc – tre). Không có dữ liệu glyph origin từ Wiktionary. Chưa có nguồn học thuật — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Kiều", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 棋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮棋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "棋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簯", "Unihan_Traditional (Chữ Phồn thể)": "簯", "Pinyin_Xie": "qi", "Âm Hán Việt_Xie": "kiều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại dụng cụ hoặc rổ rá được đan bằng tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粓', '{"9000": "7932.0", "Chữ Trung Quốc": "粓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 11 | nét | 粓 | cam | tượng hình | cơm, thức ăn từ gạo | 粓 thuộc bộ 米 (mễ – gạo), chỉ cơm hoặc thức ăn được nấu từ gạo. Không có phân tích compound Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cam\": gạo (米) nấu thành cơm ngon cam — ngọt và dẻo như bữa cơm nhà. | Gương Hán-Việt | cam (粓 – cơm gạo), ít gặp trong tiếng Việt Hán hiện đại | Mở khoá kiến thức | Biết 粓 giúp nhận diện tên thức ăn gạo trong văn bản ẩm thực và nông nghiệp cổ Trung Quốc.", "Tự nguyên_Xie": "Chữ bộ 米 (mễ – gạo), nghĩa là cơm hoặc đồ ăn từ gạo. Không có dữ liệu glyph origin từ Wiktionary. Chưa có nguồn học thuật — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cơm; như \"thổi cơm; cơm nguội; cơm bữa; cơm nước; toi cơm; trống cơm\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 甘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米甘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粓", "Unihan_Traditional (Chữ Phồn thể)": "粓", "Pinyin_Xie": "gān", "Âm Hán Việt_Xie": "cam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ cổ để chỉ nước vo gạo hoặc nước cháo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粶', '{"9000": "7933.0", "Chữ Trung Quốc": "粶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 14 | nét | 粶 | lục | tượng hình | gạo rang, ngũ cốc đã qua xử lý | 粶 thuộc bộ 米 (mễ – gạo), chỉ một loại gạo hoặc ngũ cốc qua chế biến. Không có phân tích compound Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lục\": gạo (米) đặc biệt — lục gợi sắc xanh của lúa mới xay hoặc gạo chọn lọc. | Gương Hán-Việt | lục (粶 – gạo/ngũ cốc chế biến), ít gặp trong tiếng Việt Hán | Mở khoá kiến thức | Biết 粶 giúp nhận diện chữ hiếm bộ 米 trong văn bản nông nghiệp và lương thực cổ.", "Tự nguyên_Xie": "Chữ bộ 米 (mễ – gạo). Không có dữ liệu glyph origin từ Wiktionary. Chưa có nguồn học thuật — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "粶", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 录", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米录", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "录", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粶", "Unihan_Traditional (Chữ Phồn thể)": "粶", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò danh từ chỉ các loại gạo đã qua chế biến thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('縼', '{"9000": "7934.0", "Chữ Trung Quốc": "縼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 17 | nét | 縼 | huyễn | tượng hình | dây buộc, dây cương | 縼 thuộc bộ 糸 (mịch – sợi tơ), chỉ loại dây buộc hoặc dây cương. Wiktionary ghi nhận nhưng không định nghĩa rõ (rfdef). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyễn\": sợi tơ (糸) xoáy vòng vào nhau — dây cương, dây buộc, cuộn tròn và siết chặt. | Gương Hán-Việt | huyễn (縼 – dây buộc), ít gặp trong tiếng Việt Hán | Mở khoá kiến thức | Biết 縼 giúp đọc văn bản về dây thừng và phương tiện ràng buộc trong cổ văn Trung Quốc.", "Tự nguyên_Xie": "Chữ bộ 糸 (mịch – sợi tơ), nghĩa là dây buộc, dây cương ngựa. Wiktionary ghi nhận nhưng đánh dấu rfdef. Chưa có nguồn học thuật — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "縼", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 旋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹旋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "縼", "Unihan_Traditional (Chữ Phồn thể)": "縼", "Pinyin_Xie": "xuàn", "Âm Hán Việt_Xie": "huyễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ loại dây buộc hoặc động từ chỉ hành động trói buộc động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绤', '{"9000": "7935.0", "Chữ Trung Quốc": "绤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 10 | nét | 绤 | khích | tượng hình | vải thô, vải gai thô | 绤 thuộc bộ 糸 (mịch – sợi tơ), chỉ loại vải gai thô. Wiktionary ghi nhận với ví dụ từ Kinh Thi: vải mịn (絺) và vải thô (綌/绤). Tiểu triện đã ghi nhận. Chưa có nguồn học thuật về compound.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khích\": sợi tơ (糸) dệt thô và cứng — vải khích, đối lập với vải mịn 絺 trong Kinh Thi. | Gương Hán-Việt | khích (绤/綌 – vải gai thô), ít gặp trong tiếng Việt Hán hiện đại | Mở khoá kiến thức | Biết 绤 giúp đọc Kinh Thi và văn bản về dệt vải, trang phục cổ Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Chữ bộ 糸 (mịch – sợi tơ), nghĩa là vải gai thô (coarse hemp cloth). Wiktionary dẫn Kinh Thi: \"為絺為綌，服之無斁\" — dệt vải mịn và vải thô, mặc không biết chán. 绤 là dạng giản thể của 綌. Tiểu triện đã ghi nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vải to, vải thô", "Hạng Tần Suất (Jun Da)": "7935.0", "Tần Suất % (Jun Da)": "99.9992098355", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 谷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟谷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "谷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绤", "Unihan_Traditional (Chữ Phồn thể)": "綌", "Pinyin_Xie": "xì", "Âm Hán Việt_Xie": "khích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ để chỉ loại vải dệt từ sợi sắn thô thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罆', '{"9000": "7936.0", "Chữ Trung Quốc": "罆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 缶 | Số nét | 17 | nét | 罆 | quán | tượng hình | bình đựng, hũ (dị thể của 罐) | 罆 thuộc bộ 缶 (phẫu – vò, bình), là dị thể của 罐 (quán – bình/hũ). Không có phân tích compound Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quán\": cái vò (缶) đựng đồ — 罆 là dị thể của 罐 (hũ, bình đựng). | Gương Hán-Việt | quán (罆/罐 – bình, hũ), ít gặp trong tiếng Việt Hán hiện đại | Mở khoá kiến thức | Biết 罆/罐 giúp đọc văn bản về đồ gốm và dụng cụ sinh hoạt cổ Trung Quốc.", "Tự nguyên_Xie": "Chữ bộ 缶 (phẫu – vò, bình), là dị thể (異體字) của 罐 (quán), chỉ bình, hũ, chậu chứa đựng. Không có dữ liệu glyph origin từ Wiktionary. Chưa có nguồn học thuật — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem \"罐\"", "Hạng Tần Suất (Jun Da)": "7936.0", "Tần Suất % (Jun Da)": "99.9992108691", "GavinGrover_Once (Chiết tự trực tiếp)": "缶 + 貫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰缶貫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "缶", "Unihan_Simplified (Chữ Giản thể)": "罆", "Unihan_Traditional (Chữ Phồn thể)": "罆", "Pinyin_Xie": "guàn", "Âm Hán Việt_Xie": "quán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò danh từ chỉ đồ vật dùng để đựng nước hoặc thức ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翆', '{"9000": "7937.0", "Chữ Trung Quốc": "翆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 10 | nét | 翆 | túy | tượng hình | xanh biếc, dị thể của 翠 | 翆 là dị thể không chuẩn của 翠 (túy – xanh biếc). Wiktionary ghi rõ: unorthodox variant of 翠; phần âm 卆 là dị thể của 卒. Bộ 羽 (vũ – lông vũ). Chưa có nguồn học thuật về glyph origin riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thúy\": lông vũ (羽) màu xanh biếc — 翆 là dị thể của 翠, màu xanh biếc của lông chim bói cá. | Gương Hán-Việt | túy trong \"thuý điểu\" (翠鳥 – chim bói cá), \"thuý ngọc\" (cẩm thạch xanh) | Mở khoá kiến thức | Biết 翆/翠 mở khoá: 翠鳥 (túy điểu – chim bói cá), 翡翠 (phỉ túy – ngọc cẩm thạch), 翠绿 (xanh biếc).", "Tự nguyên_Xie": "Dị thể không chuẩn của 翠 (túy – xanh biếc, tên loài chim bói cá màu xanh). Wiktionary xác nhận: phần âm 卆 là biến thể của 卒, thay cho 卒 trong 翠. Nghĩa gốc của 翠: lông chim bói cá màu xanh biếc, sau chỉ màu xanh biếc nói chung. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xanh biếc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "羽 + 卆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羽卆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翆", "Unihan_Traditional (Chữ Phồn thể)": "翆", "Pinyin_Xie": "cuì", "Âm Hán Việt_Xie": "thuý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ bổ nghĩa cho danh từ để chỉ màu xanh ngọc bích hoặc làm danh từ chỉ chim bói cá. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翑', '{"9000": "7938.0", "Chữ Trung Quốc": "翑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 11 | nét | 翑 | cù | tượng hình | lông vũ, liên quan đến lông chim | 翑 thuộc bộ 羽 (vũ – lông vũ), chỉ đặc điểm liên quan đến lông chim. Wiktionary ghi nhận nhưng không định nghĩa rõ (rfdef). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cù\": bộ Lông vũ (羽) — 翑 là chữ hiếm liên quan đến lông chim, âm đọc cù. | Gương Hán-Việt | cù (翑 – lông vũ), ít gặp trong tiếng Việt Hán | Mở khoá kiến thức | Biết 翑 giúp nhận diện chữ hiếm thuộc bộ 羽 trong văn bản cổ về chim muông và lông vũ.", "Tự nguyên_Xie": "Chữ bộ 羽 (vũ – lông vũ). Wiktionary ghi nhận nhưng đánh dấu rfdef (cần định nghĩa thêm). Chưa có nguồn học thuật — chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "翑", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "羽 + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰羽句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翑", "Unihan_Traditional (Chữ Phồn thể)": "翑", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "cù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ cổ ít dùng, chủ yếu làm danh từ chỉ phần lông cánh chim hoặc tính từ miêu tả trạng thái lông dựng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脵', '{"9000": "7939.0", "Chữ Trung Quốc": "脵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 脵 | cổ | tượng hình | phần đùi, mông | 脵 là chữ độc lập thuộc bộ 肉 (thịt). Không có dữ liệu cấu trúc thành phần từ Wiktionary; chữ có thể là biến thể của 股 (cổ: đùi).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cổ\": bộ 肉 (thịt) gợi phần thân thể — đùi và mông là phần thịt dày nhất của cơ thể. | Gương Hán-Việt | \"cổ\" tương tự 股 (cổ phần, đùi) trong tiếng Việt gốc Hán | Mở khoá kiến thức | Biết 脵 giúp nhận diện nhóm chữ bộ 肉 chỉ các bộ phận cơ thể như 股, 脚, 脸.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 脵. Chữ thuộc bộ 肉 (nhục: thịt/thân thể), có nghĩa liên quan đến đùi, mông. Có thể là dị thể của 股. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "赵", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 吴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月吴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脵", "Unihan_Traditional (Chữ Phồn thể)": "脵", "Pinyin_Xie": "gǔ", "Âm Hán Việt_Xie": "cổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ bộ phận đùi của người hoặc động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臄', '{"9000": "7940.0", "Chữ Trung Quốc": "臄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 17 | nét | 肉 | nhục | biểu nghĩa | thịt, thân thể | 豦 | cứ | biểu âm | 臄 = 肉 (Nhục, biểu nghĩa: thịt/thân thể) + 豦 (Cứ, biểu âm); chữ hình thanh. Bộ 肉 xác định nghĩa liên quan đến thịt hay bộ phận cơ thể, 豦 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giác\": thịt (肉) trong miệng — vòm hàm trên là vùng thịt mềm mà ếch dùng để bắt mồi. | Gương Hán-Việt | \"giác\" hiếm dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 臄 giúp nhận diện nhóm chữ bộ 肉 chỉ các bộ phận giải phẫu của miệng và hàm.", "Tự nguyên_Xie": "Theo Wiktionary, 臄 là chữ hình thanh: 肉 (thịt) làm thành phần biểu nghĩa, 豦 làm thành phần biểu âm. Nghĩa là hàm ếch — vòm miệng, phần thịt trên hàm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hàm ếch (chỗ hàm trên miệng)", "Hạng Tần Suất (Jun Da)": "7940.0", "Tần Suất % (Jun Da)": "99.9992170705", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 豦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月豦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臄", "Unihan_Traditional (Chữ Phồn thể)": "臄", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "cược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong y học cổ truyền hoặc giải phẫu để chỉ phần thịt trong khoang miệng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茽', '{"9000": "7941.0", "Chữ Trung Quốc": "茽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 茽 | trọng | tượng hình | loại cỏ | 茽 là chữ thuộc bộ 艸 (thảo: cỏ). Wiktionary dẫn đến dạng chữ 种 nhưng không cung cấp phân tích cấu trúc; cấu tạo nội bộ chưa rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trọng\": bộ 艸 (cỏ) + âm trọng — loại cỏ nặng (trọng), mọc dày. | Gương Hán-Việt | \"trọng\" trong tiếng Việt ít dùng ở nghĩa thực vật | Mở khoá kiến thức | Biết 茽 giúp nhận diện nhóm chữ bộ 艸 chỉ các loại cây cỏ cổ văn.", "Tự nguyên_Xie": "Wiktionary dẫn 茽 sang chữ 种 để tra nguyên gốc, nhưng không có phân tích cụ thể cho 茽. Chữ thuộc bộ 艸 (cỏ), đọc zhòng. Chưa có nguồn học thuật xác nhận chi tiết cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "茽", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 仲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹仲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "仲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茽", "Unihan_Traditional (Chữ Phồn thể)": "茽", "Pinyin_Xie": "zhòng", "Âm Hán Việt_Xie": "trọng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ trong các tài liệu cổ để chỉ một loại thảo mộc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莵', '{"9000": "7942.0", "Chữ Trung Quốc": "莵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 莵 | thố | tượng hình | loại cây leo, tơ tầm dây | 莵 thuộc bộ 艸 (cỏ). Không có dữ liệu Wiktionary; chữ có thể liên quan đến 菟 (loại cây ký sinh). Cấu trúc không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thố\": bộ 艸 (cỏ) gợi loại cây — cây thố là cây leo bám vào cây khác như thỏ (thố: con thỏ) chui vào bụi rậm. | Gương Hán-Việt | \"thố\" ít dùng trong tiếng Việt Hán-Việt hiện đại | Mở khoá kiến thức | Biết 莵 giúp nhận diện nhóm chữ bộ 艸 chỉ cây ký sinh như 菟絲子.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 莵. Chữ thuộc bộ 艸, đọc tū, có nghĩa liên quan đến cây leo hoặc tơ tầm dây. Có thể là dị thể của 菟 (tơ tầm dây, loại cây ký sinh). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ; như \"ư đồ (tên gọi con cọp)\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 兎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹兎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莵", "Unihan_Traditional (Chữ Phồn thể)": "莵", "Pinyin_Xie": "tu", "Âm Hán Việt_Xie": "thỏ, thố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong tên gọi thảo dược hoặc từ cổ chỉ con hổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菕', '{"9000": "7943.0", "Chữ Trung Quốc": "菕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菕 | trun | tượng hình | loại cây | 菕 thuộc bộ 艸 (cỏ). Wiktionary có ghi chú phát âm nhưng định nghĩa trống (rfdef). Cấu trúc nội bộ không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trun\": bộ 艸 (cỏ) — trái trun là loại quả gắn với cây cỏ trong dân gian Việt. | Gương Hán-Việt | \"trun\" trong \"trái trun\" — tên dân gian Việt cho loại quả từ cây này | Mở khoá kiến thức | Biết 菕 giúp nhận diện nhóm từ thực vật dân gian Việt gốc Hán trong y học cổ truyền.", "Tự nguyên_Xie": "Wiktionary ghi nhận 菕 đọc lún (Mandarin), có dữ liệu trung cổ và thượng cổ, nhưng định nghĩa để trống. Chữ thuộc bộ 艸. Chưa có nguồn học thuật xác nhận nghĩa và cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trun; như \"trái trun\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 侖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹侖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "侖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芲", "Unihan_Traditional (Chữ Phồn thể)": "菕", "Pinyin_Xie": "lún", "Âm Hán Việt_Xie": "hoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ để chỉ một loại thảo mộc cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓛', '{"9000": "7944.0", "Chữ Trung Quốc": "蓛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蓛 | sách | tượng hình | châu chấu | 蓛 thuộc bộ 艸 (cỏ). Không có dữ liệu Wiktionary. Nghĩa là châu chấu — một loại côn trùng gắn liền với thực vật (phá hoại mùa màng). Cấu trúc không xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sách\": bộ 艸 (cỏ) — châu chấu sống trong cỏ, phá hoại mùa màng như chiếc sách cào nát cánh đồng. | Gương Hán-Việt | \"sách\" hiếm trong tiếng Việt Hán-Việt | Mở khoá kiến thức | Biết 蓛 giúp nhận diện nhóm chữ cổ chỉ côn trùng gây hại mùa màng.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 蓛. Chữ thuộc bộ 艸, đọc cè, nghĩa là châu chấu. Bộ 艸 có thể phản ánh mối liên hệ giữa châu chấu và cỏ cây (thức ăn/môi trường sống). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "châu chấu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 敇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹敇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓛", "Unihan_Traditional (Chữ Phồn thể)": "蓛", "Pinyin_Xie": "cè", "Âm Hán Việt_Xie": "sách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò là danh từ chỉ loài côn trùng hoặc thực vật trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓷', '{"9000": "7945.0", "Chữ Trung Quốc": "蓷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 蓷 | thôi | tượng hình | cây ích mẫu (motherwort) | 蓷 thuộc bộ 艸 (cỏ). Wiktionary có thông tin phát âm và định nghĩa nhưng không phân tích cấu trúc thành phần. Chữ chỉ cây ích mẫu (Leonurus artemisia).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thôi\": bộ 艸 (cỏ) + âm thôi — cây ích mẫu thôi thúc (thôi) cơ thể phụ nữ hồi phục sau sinh. | Gương Hán-Việt | \"thôi\" trong nghĩa xúc tiến, ít dùng với nghĩa thực vật | Mở khoá kiến thức | Biết 蓷 giúp nhận diện tên cổ của cây ích mẫu — vị thuốc quan trọng trong Đông y phụ khoa.", "Tự nguyên_Xie": "Wiktionary ghi 蓷 là tên cổ của cây ích mẫu (益母草, Leonurus artemisia), bộ 艸. Không có phân tích hình thanh. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ thôi, ích mẫu", "Hạng Tần Suất (Jun Da)": "7945.0", "Tần Suất % (Jun Da)": "99.9992243055", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 推", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹推", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "推", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓷", "Unihan_Traditional (Chữ Phồn thể)": "蓷", "Pinyin_Xie": "tuī", "Âm Hán Việt_Xie": "thôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cây thảo dược dùng trong đông y. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓸', '{"9000": "7946.0", "Chữ Trung Quốc": "蓸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 蓸 | tào | tượng hình | loại cỏ | 蓸 thuộc bộ 艸 (cỏ). Wiktionary ghi đây là loại cỏ cổ (obs-std). Cấu trúc nội bộ không được phân tích trong nguồn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tào\": bộ 艸 (cỏ) + âm tào — loại cỏ tào, mọc lộn xộn (tào loạn) như đám cỏ dại. | Gương Hán-Việt | \"tào\" ít dùng với nghĩa thực vật, phổ biến hơn trong họ Tào (như Tào Tháo) | Mở khoá kiến thức | Biết 蓸 giúp nhận diện nhóm tên cỏ cổ đại trong văn bản y học và thực vật học Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi nhận 蓸 là tên một loại cỏ cổ đại (obs-std), bộ 艸. Không có phân tích cấu tạo hình thanh. Chưa có nguồn học thuật xác nhận chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại thảo mộc)", "Hạng Tần Suất (Jun Da)": "7946.0", "Tần Suất % (Jun Da)": "99.9992253391", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 曹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹曹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓸", "Unihan_Traditional (Chữ Phồn thể)": "蓸", "Pinyin_Xie": "cáo", "Âm Hán Việt_Xie": "tảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ để gọi tên một loại thực vật cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔘', '{"9000": "7947.0", "Chữ Trung Quốc": "蔘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 蔘 | sam | tượng hình | nhân sâm | 蔘 thuộc bộ 艸 (cỏ/thực vật). Wiktionary chỉ có {{Han etym}} không có phân tích cụ thể. Chữ là dị thể của 參 trong nghĩa nhân sâm — vị thuốc quý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sam\": bộ 艸 (cỏ) — nhân sâm (sam) là loại thảo mộc quý nhất, rễ hình người, bổ khí huyết. | Gương Hán-Việt | \"sam\" trong 人蔘/nhân sâm — vị thuốc bổ nổi tiếng nhất Đông y | Mở khoá kiến thức | Biết 蔘 mở khoá nhóm từ về nhân sâm và dược thảo quý trong Đông y.", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} không có nội dung. 蔘 là dạng viết của nhân sâm, bộ 艸 chỉ rõ đây là thực vật. Chữ liên quan đến 參 (sam). Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhân sâm", "Hạng Tần Suất (Jun Da)": "7947.0", "Tần Suất % (Jun Da)": "99.9992263727", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 參", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹參", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "參", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔘", "Unihan_Traditional (Chữ Phồn thể)": "蔘", "Pinyin_Xie": "shēn", "Âm Hán Việt_Xie": "sam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ các loại sâm quý dùng làm thuốc bổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕼', '{"9000": "7948.0", "Chữ Trung Quốc": "蕼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 蕼 | tứ | tượng hình | cỏ non mềm, vui vẻ | 蕼 thuộc bộ 艸 (cỏ). Wiktionary có thông tin phát âm và hai nghĩa nhưng không phân tích cấu trúc. Nghĩa: vui vẻ, thoải mái; cỏ mềm non mới mọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tứ\": bộ 艸 (cỏ) + âm tứ — cỏ non tứ phía (tứ: bốn) mọc mềm mại, gợi cảm giác thoải mái vui vẻ. | Gương Hán-Việt | \"tứ\" ít gặp với nghĩa thực vật, phổ biến hơn trong \"ý tứ\", \"tứ phía\" | Mở khoá kiến thức | Biết 蕼 giúp nhận diện nhóm tính từ thực vật học cổ trong văn thơ cổ điển.", "Tự nguyên_Xie": "Wiktionary ghi 蕼 bộ 艸, đọc sì, có hai nghĩa: vui vẻ/thoải mái; cỏ mềm mới mọc. Không có phân tích cấu tạo hình thanh. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蕼", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 肆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹肆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕼", "Unihan_Traditional (Chữ Phồn thể)": "蕼", "Pinyin_Xie": "sì", "Âm Hán Việt_Xie": "tứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này được dùng như một danh từ để chỉ một loài thực vật thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藖', '{"9000": "7949.0", "Chữ Trung Quốc": "藖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 藖 | hàm | tượng hình | cứng (tính từ cổ) | 藖 thuộc bộ 艸 (cỏ). Wiktionary ghi có nghĩa cổ là ''cứng'' nhưng không phân tích cấu tạo hình thanh. Cấu trúc không xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàm\": bộ 艸 (cỏ) — loài cỏ hàm cứng (hàm: chứa đựng, cứng chắc), rễ bám chắc vào đất. | Gương Hán-Việt | \"hàm\" ít dùng với nghĩa thực vật | Mở khoá kiến thức | Biết 藖 giúp nhận diện tính từ cổ trong văn bản cổ đại Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi 藖 bộ 艸, đọc xián, nghĩa cổ là ''cứng'' (obs-std). Không có phân tích cấu tạo. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "薖", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 賢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹賢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "賢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藖", "Unihan_Traditional (Chữ Phồn thể)": "藖", "Pinyin_Xie": "xián", "Âm Hán Việt_Xie": "hàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò là danh từ chỉ một loài cây cỏ trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藢', '{"9000": "7950.0", "Chữ Trung Quốc": "藢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 藢 | chỉ | tượng hình | loại thực vật | 藢 thuộc bộ 艸 (cỏ). Không có dữ liệu Wiktionary. Nghĩa và cấu tạo không xác định được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chỉ\": bộ 艸 (cỏ) + âm chỉ — loại cỏ dừng lại (chỉ: dừng), mọc lan rồi dừng. | Gương Hán-Việt | \"chỉ\" ít dùng với nghĩa thực vật | Mở khoá kiến thức | Biết 藢 giúp nhận diện nhóm chữ bộ 艸 hiếm trong văn bản cổ.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 藢. Chữ thuộc bộ 艸, đọc zhǐ. Nghĩa và cấu tạo chưa được xác nhận bởi nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "藢", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "藢", "Unihan_Traditional (Chữ Phồn thể)": "藢", "Pinyin_Xie": "zhǐ", "Âm Hán Việt_Xie": "chỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng để chỉ một loại thảo mộc hoặc cỏ thơm cổ xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛢', '{"9000": "7951.0", "Chữ Trung Quốc": "蛢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 虫 | trùng | biểu nghĩa | côn trùng, sâu | 并 | tinh | biểu âm | 蛢 = 虫 (Trùng, biểu nghĩa: côn trùng) + 并 (Tinh/Bình, biểu âm); chữ hình thanh. Bộ 虫 xác định đây là loài côn trùng, 并 cho âm đọc píng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bình\": trùng (虫) + bình (并) — con bọ hung bình dị (bình: bằng phẳng, bình thường) lăn viên phân tròn. | Gương Hán-Việt | \"bình\" ít dùng với nghĩa côn trùng trong tiếng Việt | Mở khoá kiến thức | Biết 蛢 giúp nhận diện nhóm chữ hình thanh bộ 虫 chỉ các loại bọ cánh cứng.", "Tự nguyên_Xie": "Theo Wiktionary, 蛢 là chữ hình thanh: 虫 (côn trùng) làm thành phần biểu nghĩa, 并 làm thành phần biểu âm. Nghĩa là con bọ hung (scarab). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "袢", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 并", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫并", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "并", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛢", "Unihan_Traditional (Chữ Phồn thể)": "蛢", "Pinyin_Xie": "píng", "Âm Hán Việt_Xie": "bình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ một loài côn trùng hoặc động vật thân mềm trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠄', '{"9000": "7952.0", "Chữ Trung Quốc": "蠄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 18 | nét | 蠄 | cầm | tượng hình | nhện, cóc (Quảng Đông) | 蠄 thuộc bộ 虫 (côn trùng). Không có dữ liệu Wiktionary. Trong tiếng Quảng Đông, 蠄蟧 là nhện và 蠄蟝 là con cóc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cầm\": trùng (虫) + cầm — nhện bò (虫) như ngón tay cầm (cầm) vật, tám chân bám chặt. | Gương Hán-Việt | \"cầm\" ít gặp với nghĩa côn trùng trong tiếng Việt | Mở khoá kiến thức | Biết 蠄 giúp nhận biết từ Quảng Đông khẩu ngữ chỉ các loài bò sát và nhện.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 蠄. Chữ thuộc bộ 虫, đọc qín. Chủ yếu dùng trong tiếng Quảng Đông: 蠄蟧 (nhện), 蠄蟝 (cóc). Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gầm; như \"mai gầm (loại rắn độc)\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 禽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫禽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠄", "Unihan_Traditional (Chữ Phồn thể)": "蠄", "Pinyin_Xie": "qín", "Âm Hán Việt_Xie": "cầm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các từ ghép chỉ loài lưỡng cư hoặc bò sát. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠈', '{"9000": "7953.0", "Chữ Trung Quốc": "蠈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 19 | nét | 蠈 | tặc | tượng hình | côn trùng hại mầm cây | 蠈 thuộc bộ 虫 (côn trùng). Wiktionary ghi nghĩa cổ là loại sâu ăn mầm cây (obs-std). Cấu trúc nội bộ không được phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tặc\": trùng (虫) ăn mầm — sâu tặc (tặc: giặc, kẻ trộm) cắn rỉa mầm non như tên giặc phá hoại. | Gương Hán-Việt | \"tặc\" trong 海賊 (hải tặc: cướp biển) — ý tương tự: kẻ phá hoại | Mở khoá kiến thức | Biết 蠈 giúp nhận diện nhóm chữ cổ chỉ côn trùng gây hại nông nghiệp.", "Tự nguyên_Xie": "Wiktionary ghi 蠈 bộ 虫, đọc zé hoặc zéi, là loài sâu hại ăn mầm cây non (obs-std). Không có phân tích cấu tạo. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蠈", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "賊 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱賊虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "賊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠈", "Unihan_Traditional (Chữ Phồn thể)": "蠈", "Pinyin_Xie": "zéi", "Âm Hán Việt_Xie": "tặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ loài sâu bệnh gây hại cho mùa màng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠎', '{"9000": "7954.0", "Chữ Trung Quốc": "蠎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 17 | nét | 蠎 | mãng | tượng hình | trăn, boa constrictor | 蠎 thuộc bộ 虫 (côn trùng/bò sát). Không có dữ liệu Wiktionary. Nghĩa là trăn lớn (python/boa constrictor). Chữ là dị thể của 蟒.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mãng\": trùng (虫) mãng — con trăn khổng lồ (mãng: to lớn, hoang dã) như con thú hoang dã nguy hiểm. | Gương Hán-Việt | \"mãng\" trong 蟒蛇 (mãng xà: trăn lớn) | Mở khoá kiến thức | Biết 蠎 giúp nhận diện nhóm chữ bộ 虫 chỉ rắn và bò sát lớn.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 蠎. Chữ thuộc bộ 虫, đọc mǎng, nghĩa là trăn (python/boa constrictor). Có thể là dị thể của 蟒. Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Gỗ sồi", "Hạng Tần Suất (Jun Da)": "7954.0", "Tần Suất % (Jun Da)": "99.9992387755", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 莾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫莾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "莾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠎", "Unihan_Traditional (Chữ Phồn thể)": "蠎", "Pinyin_Xie": "mǎng", "Âm Hán Việt_Xie": "mãng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ đứng trước các từ khác để chỉ loài trăn lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('覙', '{"9000": "7955.0", "Chữ Trung Quốc": "覙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 見 | Số nét | 12 | nét | 覙 | la | tượng hình | giải thích chi tiết | 覙 thuộc bộ 見 (nhìn, quan sát). Không có dữ liệu Wiktionary. Nghĩa là giải thích tỉ mỉ, trình bày rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"la\": nhìn (見) + la — la liệt trình bày (la: nhiều, phân tán) từng chi tiết một cách tỉ mỉ. | Gương Hán-Việt | \"la\" ít dùng với nghĩa này trong tiếng Việt | Mở khoá kiến thức | Biết 覙 giúp nhận diện nhóm chữ bộ 見 chỉ hành động nhìn và trình bày.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 覙. Chữ thuộc bộ 見, đọc luó, nghĩa là giải thích chi tiết. Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "覙", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "尔 + 見", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰尔見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "見", "Unihan_Simplified (Chữ Giản thể)": "覙", "Unihan_Traditional (Chữ Phồn thể)": "覙", "Pinyin_Xie": "luó", "Âm Hán Việt_Xie": "la", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn viết cổ để chỉ việc xem xét hoặc trình bày chi tiết. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訑', '{"9000": "7956.0", "Chữ Trung Quốc": "訑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 言 | ngôn | biểu nghĩa | lời nói | 也 | dã | biểu âm | 訑 = 言 (Ngôn, biểu nghĩa: lời nói) + 也 (Dã, biểu âm); chữ hình thanh. Bộ 言 xác định liên quan đến lời nói, 也 cho âm đọc yí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\": ngôn (言) + dã (也) — lời nói di dỗi (di: chuyển đi, trốn tránh trách nhiệm) của kẻ kiêu ngạo. | Gương Hán-Việt | \"di\" ít dùng với nghĩa này trong tiếng Việt Hán-Việt | Mở khoá kiến thức | Biết 訑 giúp nhận diện nhóm chữ hình thanh bộ 言 chỉ thái độ lời nói tiêu cực.", "Tự nguyên_Xie": "Theo Wiktionary, 訑 là chữ hình thanh: 言 (lời nói) làm thành phần biểu nghĩa, 也 làm thành phần biểu âm. Nghĩa là lừa dối, kiêu ngạo; cũng có nghĩa thoải mái tự mãn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vẻ thoả mãn đầy đủ", "Hạng Tần Suất (Jun Da)": "7956.0", "Tần Suất % (Jun Da)": "99.9992429098", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 也", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言也", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "也", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "訑", "Unihan_Traditional (Chữ Phồn thể)": "訑", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ miêu tả thái độ tự đắc hoặc kiêu ngạo. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詸', '{"9000": "7957.0", "Chữ Trung Quốc": "詸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 13 | nét | 詸 | mê | tượng hình | nói mê sảng, mê | 詸 thuộc bộ 言 (lời nói). Không có dữ liệu Wiktionary. Theo từ điển Hán-Việt, có nghĩa \"mài\" (miệt mài) và \"mê\" (nói mê). Cấu trúc không xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mê\": ngôn (言) + mê — lời nói mê mẩn (mê: mê hoặc), nói trong cơn mê sảng không kiểm soát. | Gương Hán-Việt | \"mê\" trong nói mê — trạng thái mê sảng dùng lời nói | Mở khoá kiến thức | Biết 詸 giúp nhận diện nhóm chữ bộ 言 chỉ trạng thái nói bất thường.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 詸. Chữ thuộc bộ 言, đọc mí. Từ điển Hán-Việt ghi nghĩa \"mài\" (như miệt mài) và \"mê\" (nói mê sảng). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mài; như \"miệt mài\" (gdhn) mê; như \"nói mê\" (gdhn)", "Hạng Tần Suất (Jun Da)": "7957.0", "Tần Suất % (Jun Da)": "99.9992460105", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 米", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "米", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "詸", "Unihan_Traditional (Chữ Phồn thể)": "詸", "Pinyin_Xie": "mí", "Âm Hán Việt_Xie": "mê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ câu đố hoặc động từ chỉ trạng thái nói mê. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('謥', '{"9000": "7958.0", "Chữ Trung Quốc": "謥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 18 | nét | 謥 | thông | tượng hình | (nghĩa không rõ) | 謥 thuộc bộ 言 (lời nói). Không có dữ liệu Wiktionary. Nghĩa không xác định. Cấu trúc không phân tích được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thông\": ngôn (言) + thông — lời nói thông suốt (thông: thông đạt) hoặc lời tâng bốc. | Gương Hán-Việt | \"thông\" ít gặp với nghĩa này trong tiếng Việt Hán-Việt | Mở khoá kiến thức | Biết 謥 giúp nhận diện nhóm chữ bộ 言 hiếm gặp trong văn bản cổ.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 謥. Chữ thuộc bộ 言, đọc còng. Nghĩa không xác định. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "褥", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 悤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言悤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "悤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "謥", "Unihan_Traditional (Chữ Phồn thể)": "謥", "Pinyin_Xie": "còng", "Âm Hán Việt_Xie": "thông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường dùng trong từ ghép thông thắc để tả dáng vẻ vội vàng, bối rối. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貋', '{"9000": "7959.0", "Chữ Trung Quốc": "貋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豸 | Số nét | 14 | nét | 貋 | hàn | tượng hình | (loài thú bộ 豸) | 貋 thuộc bộ 豸 (loài thú không có chân trước đứng thẳng). Không có dữ liệu Wiktionary. Nghĩa và cấu tạo không xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàn\": bộ 豸 (thú) + hàn — loài thú hàn lạnh (hàn: lạnh) sống trong vùng rừng núi giá rét. | Gương Hán-Việt | \"hàn\" ít dùng với nghĩa thú vật trong tiếng Việt | Mở khoá kiến thức | Biết 貋 giúp nhận diện nhóm chữ bộ 豸 chỉ các loài thú trong văn bản cổ đại.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 貋. Chữ thuộc bộ 豸, đọc hàn. Bộ 豸 chỉ nhóm thú như linh miêu, báo. Nghĩa cụ thể chưa được xác nhận bởi nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "貋", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "豸 + 旱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豸旱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豸", "Unihan_Simplified (Chữ Giản thể)": "貋", "Unihan_Traditional (Chữ Phồn thể)": "貋", "Pinyin_Xie": "hàn", "Âm Hán Việt_Xie": "hàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài thú hoang dã thời cổ đại thuộc họ chó. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貛', '{"9000": "7960.0", "Chữ Trung Quốc": "貛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豸 | Số nét | 24 | nét | 豸 | trại | biểu nghĩa | thú dữ bốn chân | 雚 | biểu âm | 貛 = 豸 (Trại, biểu nghĩa: loài thú) + 雚 (biểu âm, cho âm huān). Chữ hình thanh. Đây là dị thể của 獾, chỉ con lửng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàn\": con lửng (豸—thú dữ) có tiếng kêu như âm hoàn, nấp trong hang đất ban đêm. | Gương Hán-Việt | hoàn — ít dùng trong tiếng Việt Hán-Việt hiện đại; chủ yếu gặp trong từ điển cổ. | Mở khoá kiến thức | Biết 貛/hoàn mở khoá nhóm tên thú trong hán văn cổ như 貂 (điêu), 貉 (hạc), 貘 (mạch).", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 貛 là chữ hình thanh: 豸 (bộ thú dữ) biểu nghĩa, 雚 biểu âm. Chữ này là biến thể của 獾 (lửng). Chỉ xuất hiện trong Lục thư thông, chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con chuột trũi, con lửng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "豸 + 雚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豸雚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豸", "Unihan_Simplified (Chữ Giản thể)": "貛", "Unihan_Traditional (Chữ Phồn thể)": "貛", "Pinyin_Xie": "huān", "Âm Hán Việt_Xie": "hoan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con lửng, một loài động vật ăn thịt nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贁', '{"9000": "7961.0", "Chữ Trung Quốc": "贁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 18 | nét | 贁 | bại | tượng hình | dị thể của 敗, bại trận | 贁 là dị thể cổ của 敗 (bại). Không có dữ liệu phân tích thành phần cụ thể từ nguồn học thuật; căn cứ bộ 貝, có thể hiểu là tiền tài (貝) bị tổn hại — chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bại\": dị thể hiếm của 敗 — tài vật (貝) bị phá hoại, tổn thất, chỉ sự bại trận. | Gương Hán-Việt | bại — ít gặp; chữ thông dụng là 敗 (bại trận, thất bại). | Mở khoá kiến thức | Biết 贁/bại liên hệ với 敗 (thất bại), 敗北 (bại bắc), 失敗 (thất bại).", "Tự nguyên_Xie": "贁 là dị thể của 敗 (bại trận, hư hỏng). Bộ thủ 貝 (tiền/tài vật). Không có glyph-origin chi tiết trong Wiktionary. Căn cứ cấu trúc và nghĩa, đây là biến thể chữ viết, chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem \"败\"", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "賏 + ⺙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰賏⺙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "賏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺙", "Unihan_Simplified (Chữ Giản thể)": "贁", "Unihan_Traditional (Chữ Phồn thể)": "贁", "Pinyin_Xie": "bài", "Âm Hán Việt_Xie": "bại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này chủ yếu làm động từ chỉ sự thất bại hoặc làm tính từ mô tả trạng thái hư hỏng, tàn tạ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贂', '{"9000": "7962.0", "Chữ Trung Quốc": "贂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 18 | nét | 贂 | trần | tượng hình | chữ hiếm, nghĩa chưa rõ | 贂 là chữ cực hiếm trong bộ 貝. Không có dữ liệu phân tích thành phần từ nguồn học thuật; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trần\": chữ bộ 貝 cực hiếm — gặp trong từ điển cổ, nghĩa chưa rõ ràng. | Gương Hán-Việt | trần — không dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | 贂 là chữ cô lập; biết chữ này chủ yếu giúp nhận diện trong văn bản cổ hiếm.", "Tự nguyên_Xie": "贂 không có glyph-origin trong Wiktionary. Bộ 貝 (tiền/tài vật). Chữ cực hiếm, nghĩa chưa được chú giải đầy đủ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "贂", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "貝 + 參", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰貝參", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "參", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "贂", "Unihan_Traditional (Chữ Phồn thể)": "贂", "Pinyin_Xie": "chěn", "Âm Hán Việt_Xie": "trần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường dùng làm tính từ để miêu tả trạng thái nước đục hoặc chất lỏng bị pha tạp chất. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贉', '{"9000": "7963.0", "Chữ Trung Quốc": "贉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 19 | nét | 贉 | đạm | tượng hình | tiền đặt cọc, nhãn lụa trên sách | 贉 là chữ bộ 貝, không có phân tích thành phần trong nguồn học thuật hiện có. Chưa có nguồn học thuật về cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạm\": tiền đặt cọc (贉) mang bộ 貝 (tiền) — khoản tiền giữ chỗ trước khi giao dịch. | Gương Hán-Việt | đạm — không phổ biến trong tiếng Việt Hán-Việt hiện đại. | Mở khoá kiến thức | 贉 là chữ chuyên ngành cổ; biết chữ này giúp đọc văn bản thương mại/hành chính thời cổ.", "Tự nguyên_Xie": "贉 có âm dàn, nghĩa là tiền đặt cọc khi mua bán, hoặc nhãn lụa dán trên sách cổ. Wiktionary chỉ ghi nhận phiên âm và định nghĩa sơ lược, không có glyph-origin chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đặt cọc tiền trước khi mua", "Hạng Tần Suất (Jun Da)": "7963.0", "Tần Suất % (Jun Da)": "99.9992625476", "GavinGrover_Once (Chiết tự trực tiếp)": "貝 + 覃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰貝覃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "覃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "贉", "Unihan_Traditional (Chữ Phồn thể)": "贉", "Pinyin_Xie": "dàn", "Âm Hán Việt_Xie": "đảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này chủ yếu làm động từ chỉ hành động đặt tiền cọc trước khi mua hàng hoặc bồi thêm giấy vào tranh trục. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趤', '{"9000": "7964.0", "Chữ Trung Quốc": "趤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 15 | nét | 趤 | đãng | tượng hình | đi lang thang, bước đi tự do | 趤 là chữ bộ 走, không có phân tích thành phần từ nguồn học thuật. Bộ 走 liên quan đến đi bộ, chạy nhảy. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đãng\": chữ bộ 走 (đi) mang âm đãng — bước đi lang thang, phiêu đãng. | Gương Hán-Việt | đãng — liên hệ với 蕩 (đãng — dao động, lang thang). | Mở khoá kiến thức | 趤 là chữ hiếm; nhận ra bộ 走 giúp đoán nhóm nghĩa liên quan đến chuyển động, đi lại.", "Tự nguyên_Xie": "趤 có âm dàng, bộ 走 (đi bộ). Không có glyph-origin trong Wiktionary. Là dị thể hoặc biến thể ít dùng, liên quan đến chuyển động. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "褤", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 宕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走宕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趤", "Unihan_Traditional (Chữ Phồn thể)": "趤", "Pinyin_Xie": "dàng", "Âm Hán Việt_Xie": "đãng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ chỉ hành vi đi lại vô định, rong chơi hoặc dao động. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趯', '{"9000": "7965.0", "Chữ Trung Quốc": "趯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 21 | nét | 趯 | địch | tượng hình | nhảy nhót; nét móc trong thư pháp | 趯 là chữ bộ 走, không có phân tích thành phần chi tiết từ Wiktionary ngoài {{Han etym}}. Bộ 走 biểu nghĩa về chuyển động. Tiểu triện đã có ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"địch\": bộ 走 (chân chạy) — nhảy vọt lên, cũng dùng để chỉ nét bút móc lên trong thư pháp. | Gương Hán-Việt | địch — ít dùng trong tiếng Việt Hán-Việt; chủ yếu trong thuật ngữ thư pháp cổ. | Mở khoá kiến thức | 趯 liên hệ nhóm chữ bộ 走 chỉ chuyển động: 跳 (khiêu), 跑 (bôn), 越 (việt).", "Tự nguyên_Xie": "Tiểu triện | 趯 bộ 走, âm tì/địch. Wiktionary chỉ ghi {{Han etym}}, không có glyph-origin chi tiết. Tiểu triện đã có ghi nhận hình thể. Nghĩa: nhảy nhót; trong thư pháp chỉ nét móc (khi đưa bút). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhảy nhót; nét móc (khi viết)", "Hạng Tần Suất (Jun Da)": "7965.0", "Tần Suất % (Jun Da)": "99.9992646148", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 翟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走翟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趯", "Unihan_Traditional (Chữ Phồn thể)": "趯", "Pinyin_Xie": "tì", "Âm Hán Việt_Xie": "địch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động nhảy lên hoặc làm danh từ chỉ nét móc khi viết chữ Hán. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趶', '{"9000": "7966.0", "Chữ Trung Quốc": "趶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 10 | nét | 趶 | khốc | tượng hình | vò, hành hạ (chân) | 趶 bộ 足, không có phân tích thành phần chi tiết. Bộ 足 biểu nghĩa liên quan đến chân, bước đi. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khốc\": bộ 足 (chân) — âm khốc gợi sự đau đớn, vò xé; chữ cực hiếm trong văn bản cổ. | Gương Hán-Việt | khốc — liên hệ với 哭 (khốc — khóc); đây là chữ khác âm trùng. | Mở khoá kiến thức | 趶 là chữ cô lập; nhận bộ 足 giúp phân nhóm với: 跑 (bôn), 跳 (khiêu), 踢 (địch).", "Tự nguyên_Xie": "趶 có âm kù, bộ 足 (chân). Không có glyph-origin trong Wiktionary. Nghĩa: giày vò (theo tiếng Hán Việt dân gian). Chữ cực hiếm. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vò; như \"giày vò\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 于", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊于", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "于", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "趶", "Unihan_Traditional (Chữ Phồn thể)": "趶", "Pinyin_Xie": "kù", "Âm Hán Việt_Xie": "khố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ chỉ hành động giẫm đạp hoặc giày vò, hành hạ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跔', '{"9000": "7967.0", "Chữ Trung Quốc": "跔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 12 | nét | 足 | túc | biểu nghĩa | chân | 句 | câu | biểu âm | 跔 = 足 (Túc, biểu nghĩa: chân) + 句 (Câu, biểu âm: cho âm jū/câu). Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"câu\": chân (足) bị co quắp như dấu câu (句) vì lạnh — hình ảnh đôi chân tê cứng mùa đông. | Gương Hán-Việt | câu — ít dùng trong tiếng Việt Hán-Việt hiện đại; liên hệ câu (cong, móc). | Mở khoá kiến thức | 跔 gợi nhóm chữ bộ 足 chỉ tình trạng chân: 跛 (bã —跛行), 踡 (quyển — co chân), 跚 (san — đi loạng choạng).", "Tự nguyên_Xie": "Theo Wiktionary, 跔 là chữ hình thanh: 足 (chân) biểu nghĩa, 句 biểu âm. Nghĩa: chân tê cứng vì lạnh; (Hokkien) ngồi xổm, ở lại. Wiktionary ghi nhận dùng cả ở phương ngữ Mân Nam. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lạnh run", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跔", "Unihan_Traditional (Chữ Phồn thể)": "跔", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "câu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ trạng thái chân tay bị co quắp do lạnh hoặc làm tính từ miêu tả sự tê cóng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹆', '{"9000": "7968.0", "Chữ Trung Quốc": "蹆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 16 | nét | 蹆 | thủi | tượng hình | đi thẳng; thui thủi | 蹆 bộ 足, không có phân tích thành phần từ nguồn học thuật. Bộ 足 biểu nghĩa liên quan đến chân, bước đi. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thủi\": bộ 足 (chân) — đi một mình thui thủi, lẻ loi theo đường thẳng không ngoảnh lại. | Gương Hán-Việt | thủi — trong tiếng Việt: \"thui thủi\" (cô đơn, lẻ loi). | Mở khoá kiến thức | 蹆 liên hệ ngữ cảm với: 獨 (độc — một mình), 孤 (cô — cô đơn) trong cách dùng tiếng Việt Hán-Việt.", "Tự nguyên_Xie": "蹆 có âm tuǐ, bộ 足. Không có glyph-origin trong Wiktionary. Tiếng Quảng Đông dùng với nghĩa di chuyển theo đường thẳng. Trong tiếng Việt Hán-Việt dân gian: thủi, như \"thui thủi\" (cô đơn, lủi thủi). Chưa có nguồn học thuật chính thức. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thủi; như \"thui thủi\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 退", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊退", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "退", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹆", "Unihan_Traditional (Chữ Phồn thể)": "蹆", "Pinyin_Xie": "tuǐ", "Âm Hán Việt_Xie": "thoái, thối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường dùng làm danh từ chỉ bộ phận chân đùi hoặc làm động từ chỉ dáng đi không vững. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('塥', '{"9000": "7969.0", "Chữ Trung Quốc": "塥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 13 | nét | 塥 | cách | tượng hình | cục đất khô, địa danh | 塥 bộ 土 (đất), không có phân tích thành phần từ nguồn học thuật. Bộ 土 biểu nghĩa liên quan đến đất. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cách\": bộ 土 (đất) — mảnh đất khô cứng, gợi hình đất đai cứng rắn phân cách. | Gương Hán-Việt | cách — liên hệ 隔 (cách — ngăn cách), 格 (cách — ô vuông). | Mở khoá kiến thức | 塥 là chữ địa danh; nhận bộ 土 giúp nhóm với: 埠 (bộ), 塢 (ổ), 塘 (đường).", "Tự nguyên_Xie": "塥 có âm gé, bộ 土 (đất). Không có glyph-origin trong Wiktionary. Nghĩa: cục đất khô, thường dùng trong địa danh. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đất cát (thường dùng làm tên đất)", "Hạng Tần Suất (Jun Da)": "7969.0", "Tần Suất % (Jun Da)": "99.9992697826", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 鬲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土鬲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鬲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "塥", "Unihan_Traditional (Chữ Phồn thể)": "塥", "Pinyin_Xie": "gé", "Âm Hán Việt_Xie": "cách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ chỉ địa hình gò đất hoặc dùng trong tên riêng của các địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輰', '{"9000": "7970.0", "Chữ Trung Quốc": "輰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 16 | nét | 車 | xa | biểu nghĩa | xe | 昜 | biểu âm | 輰 = 車 (Xa, biểu nghĩa: xe) + 昜 (biểu âm: cho âm yáng/dương). Chữ hình thanh. Chỉ dùng trong từ ghép 輰䡵.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dương\": xe (車) với bộ phận dây cương (昜 âm) — dây điều khiển ngựa kéo xe. | Gương Hán-Việt | dương — ít dùng; liên hệ 揚 (dương — nâng lên), 陽 (dương — mặt trời). | Mở khoá kiến thức | 輰 là chữ chuyên ngành cổ về xe ngựa; nhóm với: 轡 (phế — dây cương), 軾 (thức — thanh ngang xe).", "Tự nguyên_Xie": "Theo Wiktionary, 輰 là chữ hình thanh: 車 (xe) biểu nghĩa, 昜 biểu âm. Chỉ dùng trong từ ghép 輰䡵 (dây cương xe). Không có hình ảnh từ cổ văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây cương", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 昜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車昜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "輰", "Unihan_Traditional (Chữ Phồn thể)": "輰", "Pinyin_Xie": "yáng", "Âm Hán Việt_Xie": "dương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ để chỉ dây cương xe thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邼', '{"9000": "7971.0", "Chữ Trung Quốc": "邼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 8 | nét | 邼 | khuông | tượng hình | địa danh cổ | 邼 bộ 邑 (ấp — địa danh), không có phân tích thành phần chi tiết. Bộ 邑 thường biểu nghĩa địa danh, quốc gia. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuông\": bộ 邑 (ấp/địa danh) — tên đất cổ âm khuông, gợi hình vùng đất bị bao quanh như khung. | Gương Hán-Việt | khuông — liên hệ 框 (khuông — khung), 匡 (khuông — nắn chỉnh). | Mở khoá kiến thức | 邼 là chữ địa danh; nhận bộ 邑 giúp nhóm với: 邦 (bang), 郡 (quận), 鄉 (hương).", "Tự nguyên_Xie": "邼 có âm kuāng, bộ 邑 (ấp). Wiktionary chỉ ghi {{Han etym}} và phiên âm, không có định nghĩa cụ thể. Là địa danh cổ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "邼", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "匡 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰匡阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邼", "Unihan_Traditional (Chữ Phồn thể)": "邼", "Pinyin_Xie": "kuāng", "Âm Hán Việt_Xie": "khuông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng chỉ địa danh hoặc họ người thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('釟', '{"9000": "7972.0", "Chữ Trung Quốc": "釟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 金 | kim | biểu nghĩa | kim loại | 八 | bát | biểu âm | 釟 = 金 (Kim, biểu nghĩa: kim loại) + 八 (Bát, biểu âm: cho âm bā/bát). Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bát\": kim loại (金) được gập tám (八) lần — gợi hình lưỡi dao nhíp cong gập nhiều lần. | Gương Hán-Việt | bát — ít dùng trong tiếng Việt hiện đại; chữ dân gian dùng cho \"dao nhíp\". | Mở khoá kiến thức | 釟 liên hệ nhóm bộ 金: 銼 (tộ — dũa), 鉗 (kiềm — kẹp), 鑷 (nhiếp — nhíp).", "Tự nguyên_Xie": "Theo Wiktionary, 釟 là chữ hình thanh: 金 (kim loại) biểu nghĩa, 八 biểu âm. Nghĩa trong từ điển: luyện kim; (từ lỗi thời) tên nguyên tố unniloctium (Uno). Trong tiếng Việt Hán-Việt: bát (nhíp, dao nhíp). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhíp; như \"dao nhíp\" (vhn) bát; như \"bát ăn bát để\" (gdhn) díp; như \"cái díp (cái nhíp); dao díp\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 八", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金八", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "八", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "釟", "Unihan_Traditional (Chữ Phồn thể)": "釟", "Pinyin_Xie": "bā", "Âm Hán Việt_Xie": "bát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ dụng cụ gắp hoặc dao nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('釠', '{"9000": "7973.0", "Chữ Trung Quốc": "釠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 釠 | loạn | tượng hình | chữ cực hiếm bộ 金 | 釠 bộ 金 (kim loại), không có phân tích thành phần từ nguồn học thuật. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"loạn\": bộ 金 (kim loại) với âm loạn — chữ cực hiếm, gợi hình kim loại bị rối loạn. | Gương Hán-Việt | loạn — liên hệ 亂 (loạn — hỗn loạn). | Mở khoá kiến thức | 釠 là chữ cô lập; nhận bộ 金 giúp nhóm với các chữ kim loại khác.", "Tự nguyên_Xie": "釠 có âm luàn, bộ 金. Không có glyph-origin trong Wiktionary. Nghĩa không rõ ràng (源字 頠). Chữ cực hiếm. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "頠", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 几", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金几", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "几", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "釠", "Unihan_Traditional (Chữ Phồn thể)": "釠", "Pinyin_Xie": "luàn", "Âm Hán Việt_Xie": "loạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ kim loại quý hoặc động từ liên quan đến luyện kim. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鉂', '{"9000": "7974.0", "Chữ Trung Quốc": "鉂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 鉂 | thỉ | tượng hình | chữ cực hiếm bộ 金 | 鉂 bộ 金 (kim loại), không có phân tích thành phần từ nguồn học thuật. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thỉ\": bộ 金 (kim loại) âm thỉ — chữ cực hiếm, chỉ gặp trong tự điển chuyên sâu. | Gương Hán-Việt | thỉ — liên hệ 矢 (thỉ — mũi tên); đây là chữ âm trùng khác nghĩa. | Mở khoá kiến thức | 鉂 là chữ cô lập; nhận bộ 金 giúp nhóm với các chữ kim khí.", "Tự nguyên_Xie": "鉂 có âm shǐ, bộ 金. Không có glyph-origin trong Wiktionary. Nghĩa không rõ ràng. Chữ cực hiếm. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鉂", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 史", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金史", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "史", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鉂", "Unihan_Traditional (Chữ Phồn thể)": "鉂", "Pinyin_Xie": "shǐ", "Âm Hán Việt_Xie": "thỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong các văn bản cổ hoặc thuật ngữ hóa học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('銊', '{"9000": "7975.0", "Chữ Trung Quốc": "銊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 銊 | tuất | tượng hình | chữ hiếm bộ 金, nghĩa chưa rõ | 銊 bộ 金 (kim loại), không có phân tích thành phần từ nguồn học thuật ngoài ghi nhận Wiktionary là {{rfdef|zh}}. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuất\": bộ 金 (kim loại) âm tuất — liên hệ với địa chi Tuất (戌), âm trùng trong tiếng Việt. | Gương Hán-Việt | tuất — liên hệ 戌 (tuất — địa chi thứ 11), 恤 (tuất — thương xót). | Mở khoá kiến thức | 銊 là chữ cô lập; nhận bộ 金 giúp nhóm kim loại học thuật.", "Tự nguyên_Xie": "銊 có âm xù, bộ 金. Wiktionary ghi {{rfdef|zh}} — nghĩa chưa được định nghĩa chính thức. Trong tiếng Việt Hán-Việt: tuất. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhong; như \"nhong nhong\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 戌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金戌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "銊", "Unihan_Traditional (Chữ Phồn thể)": "銊", "Pinyin_Xie": "xù", "Âm Hán Việt_Xie": "dực", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Danh từ | 名词 | Chữ này thường dùng làm từ tượng thanh mô tả tiếng kêu của kim loại hoặc tiếng nhạc ngựa. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鋭', '{"9000": "7976.0", "Chữ Trung Quốc": "鋭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 金 | kim | biểu nghĩa | kim loại | 兌 | đoái | biểu âm | 鋭 = 金 (Kim, biểu nghĩa: kim loại) + 兌 (Đoái, biểu âm: cho âm ruì/nhọn). Chữ hình thanh. Biểu thị đầu nhọn của lưỡi dao/công cụ cắt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhọn\": kim loại (金) với âm nhọn (兌) — mũi kim loại sắc nhọn như đầu đinh. | Gương Hán-Việt | nhọn — ít dùng trong Hán-Việt học thuật; từ Hán-Việt chính thức: 銳 (nhuệ). | Mở khoá kiến thức | Biết 鋭/nhọn (nhuệ) mở khoá: 鋭利 (nhuệ lợi — sắc bén), 鋭氣 (nhuệ khí — khí thế mạnh), 精鋭 (tinh nhuệ).", "Tự nguyên_Xie": "Theo Wiktionary, 鋭 là chữ hình thanh: 金 (kim loại) biểu nghĩa, 兌 biểu âm. Nghĩa: đầu nhọn, sắc bén của vũ khí hay công cụ kim loại. Mở rộng: sắc bén, tinh tế, mạnh mẽ (鋭利, 鋭氣). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鋭", "Hạng Tần Suất (Jun Da)": "7976.0", "Tần Suất % (Jun Da)": "99.9992873533", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 兑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金兑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鋭", "Unihan_Traditional (Chữ Phồn thể)": "鋭", "Pinyin_Xie": "ruì", "Âm Hán Việt_Xie": "nhọn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ bổ nghĩa cho danh từ để chỉ sự sắc bén của vũ khí hoặc sự nhạy bén của tư duy. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('錃', '{"9000": "7977.0", "Chữ Trung Quốc": "錃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 錃 | bí | tượng hình | chữ cực hiếm bộ 金 | 錃 bộ 金 (kim loại), không có phân tích thành phần từ nguồn học thuật. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": bộ 金 (kim loại) âm bí — chữ cực hiếm, chỉ gặp trong tự điển chuyên sâu. | Gương Hán-Việt | bí — liên hệ 秘 (bí — bí mật), 鄙 (bỉ — thấp kém). | Mở khoá kiến thức | 錃 là chữ cô lập; nhận bộ 金 giúp phân nhóm kim khí.", "Tự nguyên_Xie": "錃 có âm bēi, bộ 金. Không có glyph-origin trong Wiktionary. Nghĩa không rõ ràng. Chữ cực hiếm. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "錃", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "波 + 金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱波金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "波", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "錃", "Unihan_Traditional (Chữ Phồn thể)": "錃", "Pinyin_Xie": "bēi", "Âm Hán Việt_Xie": "bí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ để chỉ một loại dụng cụ cạo gọt bằng kim loại thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('漭', '{"9000": "7978.0", "Chữ Trung Quốc": "漭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 漭 | mãng | tượng hình | bát ngát, mênh mông | 漭 bộ 水 (nước), không có phân tích thành phần chi tiết từ Wiktionary. Bộ 水 biểu nghĩa liên quan đến nước, mặt nước rộng lớn. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mãng\": bộ 水 (nước) âm mãng — mặt nước bát ngát, bao la như đồng bằng trống trải. | Gương Hán-Việt | mãng — liên hệ 莽 (mãng — rừng rậm, mộc mạc); 漭 mang bộ 水 thêm sắc thái nước mênh mông. | Mở khoá kiến thức | 漭 liên hệ nhóm chữ bộ 水 chỉ không gian rộng: 渺 (miểu — xa xôi), 茫 (mang — mịt mờ), 浩 (hạo — bao la).", "Tự nguyên_Xie": "漭 có âm mǎng, bộ 水 (nước). Wiktionary chỉ ghi {{rfdef|zh}}, không có glyph-origin. Nghĩa: bát ngát, mênh mông (như mặt nước rộng lớn). Dùng trong: 漭漭 (mãng mãng — bát ngát), 漭沆 (mãng hàng — rộng mênh mông). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bát ngát, bao la", "Hạng Tần Suất (Jun Da)": "7978.0", "Tần Suất % (Jun Da)": "99.999290454", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 莽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵莽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "莽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "漭", "Unihan_Traditional (Chữ Phồn thể)": "漭", "Pinyin_Xie": "mǎng", "Âm Hán Việt_Xie": "mãng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ mô tả cảnh tượng nước chảy mênh mông hoặc không gian bao la, rộng lớn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鏆', '{"9000": "7979.0", "Chữ Trung Quốc": "鏆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 19 | nét | 鏆 | quán | tượng hình | chữ hiếm bộ 金, nghĩa chưa rõ | 鏆 bộ 金 (kim loại), không có phân tích thành phần từ nguồn học thuật ngoài {{Han etym}} và phiên âm. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quán\": bộ 金 (kim loại) âm quán — chữ hiếm, liên hệ nhóm âm quán như 觀 (quán/quan), 罐 (quán — cái vò). | Gương Hán-Việt | quán — liên hệ 罐 (quán — cái vò/lọ kim loại). | Mở khoá kiến thức | 鏆 là chữ cô lập; nhận bộ 金 giúp nhóm với đồ vật kim loại.", "Tự nguyên_Xie": "鏆 có âm guàn, bộ 金. Wiktionary chỉ ghi {{rfdef|zh}} — nghĩa chưa được định nghĩa. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鏆", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 貫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金貫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鏆", "Unihan_Traditional (Chữ Phồn thể)": "鏆", "Pinyin_Xie": "guàn", "Âm Hán Việt_Xie": "quán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại bình, lon hoặc hũ chứa đồ làm bằng kim loại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鐖', '{"9000": "7980.0", "Chữ Trung Quốc": "鐖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 20 | nét | 鐖 | cơ | tượng hình | chữ cực hiếm bộ 金, nghĩa chưa rõ | 鐖 bộ 金 (kim loại), không có phân tích thành phần từ nguồn học thuật ngoài {{Han etym}} và phiên âm. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cơ\": bộ 金 (kim loại) âm cơ — chữ cực hiếm, liên hệ 機 (cơ — máy móc, cơ chế). | Gương Hán-Việt | cơ — liên hệ 機 (cơ — cơ chế, máy), 幾 (cơ — mấy, gần). | Mở khoá kiến thức | 鐖 là chữ cô lập; nhận bộ 金 giúp nhóm kim khí phức tạp.", "Tự nguyên_Xie": "鐖 có âm jī/qí, bộ 金. Wiktionary chỉ ghi {{rfdef|zh}} — nghĩa chưa được định nghĩa. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鐖", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 幾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金幾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鐖", "Unihan_Traditional (Chữ Phồn thể)": "鐖", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "cơ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại mũi tên có móc ngược hoặc bộ phận cò máy bằng kim loại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鑱', '{"9000": "7981.0", "Chữ Trung Quốc": "鑱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 25 | nét | 鑱 | sàm | tượng hình | dụng cụ nhọn, mũi khoan | 鑱 là chữ không có cấu trúc IDS rõ ràng trong nguồn dữ liệu. Căn cứ vào bộ 金 (kim, kim loại) và hình dạng tổng thể, đây là công cụ kim loại nhọn dùng để đào hoặc đâm xuyên. Chữ tự tham chiếu trong nhóm tượng hình mở rộng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sàm\": bộ 金 (kim loại) ẩn trong chữ — hình dung mũi kim loại nhọn sàm sạm xuyên vào đất cứng. | Gương Hán-Việt | sàm — ít dùng độc lập trong tiếng Việt hiện đại; xuất hiện trong cổ văn chỉ mũi nhọn kim loại | Mở khoá kiến thức | Biết 鑱 giúp đọc hiểu các cổ văn Hán-Việt mô tả dụng cụ đào bới và y cụ cổ đại.", "Tự nguyên_Xie": "Tiểu triện | Chữ 鑱 xuất hiện trong tiểu triện với nghĩa nhọn, sắc bén. Nghĩa gốc là dụng cụ kim loại nhọn dùng để đào đất hoặc đâm xuyên, sau mở rộng sang nghĩa kim, dùi, mũi nhọn. Chưa có nguồn học thuật xác định rõ cấu trúc hình thanh hay hội ý cho chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "镵", "Hạng Tần Suất (Jun Da)": "7513.0", "Tần Suất % (Jun Da)": "99.9985436995", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 毚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金毚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "镵", "Unihan_Traditional (Chữ Phồn thể)": "鑱", "Pinyin_Xie": "chán", "Âm Hán Việt_Xie": "sàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường dùng làm danh từ chỉ các dụng cụ sắc nhọn như mai, xẻng hoặc kim châm y học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镃', '{"9000": "7982.0", "Chữ Trung Quốc": "镃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 镃 | tư | tượng hình | cuốc, bừa, dụng cụ canh tác | 镃 (dạng giản thể / biến thể của 鎡) thuộc bộ 金 (kim). Không tìm thấy cấu trúc IDS rõ ràng. Dựa vào bộ kim và ngữ nghĩa, đây là nông cụ kim loại — cuốc hoặc bừa dùng trong ruộng đồng. Chữ xuất hiện trong sách Mạnh Tử với nghĩa dụng cụ canh tác.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": cuốc nông cụ bằng kim (金) — hình dung người nông dân tư lự (tư) trước khi cuốc đất, nhớ rằng phải đợi đúng thời tiết. | Gương Hán-Việt | tư — hiếm dùng độc lập; thường gặp trong cổ văn nông nghiệp dưới dạng 鎡基 | Mở khoá kiến thức | Biết 镃 giúp đọc các đoạn cổ văn về nông cụ và triết học thực dụng trong sách Mạnh Tử.", "Tự nguyên_Xie": "Tiểu triện | 鎡 (viết đầy đủ) là nông cụ kim loại có miệng hẹp, tương tự cái cuốc nhỏ. Sách Mạnh Tử dẫn câu ngạn ngữ nước Tề: \"Tuy có 鎡基 (dụng cụ nông nghiệp), không bằng đợi đúng thời vụ\" — cho thấy đây là biểu tượng của sự chuẩn bị kỹ càng nhưng vẫn cần thiên thời. Chưa có nguồn học thuật xác định rõ cấu trúc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ làm ruộng, cái cày, cái bừa", "Hạng Tần Suất (Jun Da)": "7982.0", "Tần Suất % (Jun Da)": "99.9992997561", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 兹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅兹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镃", "Unihan_Traditional (Chữ Phồn thể)": "鎡", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, chủ yếu dùng trong từ ghép để chỉ nông cụ gieo cấy thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陜', '{"9000": "7983.0", "Chữ Trung Quốc": "陜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 9 | nét | 陜 | hiệp | tượng hình | hẻm núi hẹp, đèo cao | 陜 thuộc bộ 阜 (phụ, đồi đất). Cấu trúc IDS không rõ trong dữ liệu. Bộ 阜 gợi địa hình đồi núi; nghĩa chữ là hẻm núi hẹp, đèo. Chú ý: 陜 (xiá) và 陝 (shǎn, Thiểm) là hai chữ khác nhau — 陜 ít gặp hơn, nghĩa là hẹp/đèo núi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiệp\": bộ 阜 (đồi đất) + nghĩa hẹp — hình dung đường hiệp (hẻm hẹp) giữa hai vách đồi núi. | Gương Hán-Việt | hiệp — ít dùng độc lập; đừng nhầm với 陝 (thiểm) | Mở khoá kiến thức | Biết 陜 giúp phân biệt với 陝 (Thiểm Tây) khi đọc địa lý cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 陜 mang nghĩa núi non hẹp, con đèo. Chữ này ít thấy trong văn bản hiện đại, dễ bị nhầm với 陝 (Thiểm — tỉnh Thiểm Tây). Nguồn tiểu triện tồn tại nhưng không có giải thích tự hình chi tiết. Chưa có nguồn học thuật xác định cấu trúc hình thanh hay hội ý. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên gọi tắt của tỉnh Thiểm Tây của Trung Quốc", "Hạng Tần Suất (Jun Da)": "7983.0", "Tần Suất % (Jun Da)": "99.9993038904", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 夾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝夾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陜", "Unihan_Traditional (Chữ Phồn thể)": "陜", "Pinyin_Xie": "xiá", "Âm Hán Việt_Xie": "xiểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ sự chật hẹp hoặc làm danh từ chỉ địa danh cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霠', '{"9000": "7984.0", "Chữ Trung Quốc": "霠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 17 | nét | 霠 | âm | tượng hình | trời u ám, mây che khuất | 霠 thuộc bộ 雨 (vũ, mưa). Wiktionary xác nhận đây là biến thể của 𩃬, chữ mô tả trời âm u, mây che phủ. Bộ 雨 xác định liên quan đến thời tiết/trời mây. Chưa có cấu trúc IDS rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"âm\": bộ 雨 (mưa) — hình dung trời âm u (âm) mây che, bộ 雨 như những giọt nước mưa chuẩn bị rơi xuống. | Gương Hán-Việt | âm — xuất hiện trong \"âm u\", \"âm mây\" khi dịch thơ cổ chỉ bầu trời u ám | Mở khoá kiến thức | Biết 霠 giúp nhận diện từ mô tả thời tiết trong thơ văn cổ điển.", "Tự nguyên_Xie": "霠 là biến thể của 𩃬, cùng nghĩa mô tả bầu trời u ám, nhiều mây. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Bộ 雨 (mưa) xác nhận đây là chữ thuộc nhóm thời tiết trong hệ thống chữ Hán. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "霠", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "霠", "Unihan_Traditional (Chữ Phồn thể)": "霠", "Pinyin_Xie": "yīn", "Âm Hán Việt_Xie": "âm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ miêu tả trạng thái thời tiết âm u, tối tăm không có ánh nắng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞖', '{"9000": "7985.0", "Chữ Trung Quốc": "鞖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 16 | nét | 鞖 | tuy | tượng hình | đồ trang trí trên yên ngựa, tua dải | 鞖 thuộc bộ 革 (cách, da thuộc). Không có cấu trúc IDS hay glyphOrigin trong nguồn dữ liệu. Căn cứ bộ 革 (da) và ngữ nghĩa, đây là vật trang trí bằng da gắn trên yên ngựa hoặc dây cương — dạng tua, dải trang trí. Chữ tạo muộn, không có giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuy\": bộ 革 (da) — hình dung tua (tuy) dải da trang trí phất phơ trên yên ngựa quý tộc. | Gương Hán-Việt | tuy — gần như không dùng trong tiếng Việt; chỉ xuất hiện trong cổ văn khảo cổ về trang bị ngựa | Mở khoá kiến thức | Biết 鞖 giúp đọc các văn bản khảo cổ mô tả trang bị và trang sức ngựa chiến cổ đại.", "Tự nguyên_Xie": "鞖 không có glyphOrigin từ Wiktionary. Bộ 革 (da thuộc) xác nhận đây là vật phẩm bằng da dùng trong trang bị ngựa — cụ thể là dải tua trang trí gắn trên yên hoặc dây cương. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鞖", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 妥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革妥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "妥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞖", "Unihan_Traditional (Chữ Phồn thể)": "鞖", "Pinyin_Xie": "suī", "Âm Hán Việt_Xie": "tuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận trang trí hoặc bảo vệ bằng da ở đầu bao kiếm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韨', '{"9000": "7986.0", "Chữ Trung Quốc": "韨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 韋 | Số nét | 9 | nét | 韨 | phất | tượng hình | tạp dề da đầu gối trong tế lễ | 韨 thuộc bộ 韋 (vi, da thuộc mềm). Không có cấu trúc IDS rõ ràng. Bộ 韋 gợi chất liệu da mềm; nghĩa chữ là tấm da che đầu gối mà các quan lại đeo trong nghi lễ tế tự. Chữ cũng là dị thể của 紱 (dải lụa buộc ấn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phất\": bộ 韋 (da mềm) — hình dung tấm da phất (phất phơ, che phủ) đầu gối quan lại trong buổi tế lễ trang nghiêm. | Gương Hán-Việt | phất — gần như không dùng độc lập trong tiếng Việt; liên quan đến \"phất\" trong \"phất tràng\" (cờ phướn) | Mở khoá kiến thức | Biết 韨 giúp đọc các mô tả về phẩm phục tế lễ trong lễ nghi Nho gia và cổ sử Trung Hoa.", "Tự nguyên_Xie": "韨 chỉ tấm che đầu gối bằng da dùng trong tế lễ cổ đại, mà các quan lại và vương hầu đeo như một phần phẩm phục nghi lễ. Là dị thể của 巿 (một dạng viết cổ hơn) và liên quan đến 紱 (dải lụa buộc ấn tín). Wiktionary xác nhận nghĩa này là leather knee covering worn during sacrifices. Chưa có phân tích tự hình hình thanh/hội ý rõ ràng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái phất (để đệm đầu gối khi quỳ)", "Hạng Tần Suất (Jun Da)": "7986.0", "Tần Suất % (Jun Da)": "99.9993090583", "GavinGrover_Once (Chiết tự trực tiếp)": "韦 + 犮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰韦犮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "韦", "Unihan_Simplified (Chữ Giản thể)": "韨", "Unihan_Traditional (Chữ Phồn thể)": "韍", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ trang phục tế lễ cổ, thường đứng sau danh từ chỉ chất liệu hoặc màu sắc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韼', '{"9000": "7987.0", "Chữ Trung Quốc": "韼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 音 | Số nét | 19 | nét | 韼 | bằng | tượng hình | âm thanh (thuộc bộ 音) | 韼 thuộc bộ 音 (âm, âm thanh). Không có cấu trúc IDS hay glyphOrigin. Bộ 音 xác nhận đây là chữ liên quan đến âm thanh, tiếng vang. Chữ tạo muộn, không có nguồn khảo cứu rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bằng\": bộ 音 (âm thanh) — hình dung tiếng vang bằng bặt, lan tỏa như âm thanh (音) trống trải. | Gương Hán-Việt | bằng — gần như không dùng trong tiếng Việt; chữ cực hiếm | Mở khoá kiến thức | Biết 韼 giúp nhận diện chữ hiếm trong bộ 音 khi tra cứu từ điển cổ đại.", "Tự nguyên_Xie": "韼 không có glyphOrigin từ Wiktionary. Bộ 音 (âm thanh) là bộ thủ. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Nghĩa cụ thể không rõ ràng trong các nguồn học thuật hiện đại. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "韼", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "音 + 逢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰音逢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "逢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "音", "Unihan_Simplified (Chữ Giản thể)": "韼", "Unihan_Traditional (Chữ Phồn thể)": "韼", "Pinyin_Xie": "péng", "Âm Hán Việt_Xie": "bằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ tượng thanh | 象声词 | Chữ này chủ yếu dùng làm danh từ chỉ âm thanh hoặc từ mô phỏng tiếng trống vang trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韽', '{"9000": "7988.0", "Chữ Trung Quốc": "韽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 音 | Số nét | 20 | nét | 韽 | ám | tượng hình | âm thanh nhỏ, mờ, tắt tiếng | 韽 thuộc bộ 音 (âm, âm thanh). Không có cấu trúc IDS rõ ràng. Bộ 音 xác định liên quan đến âm thanh; nghĩa là âm mờ nhạt, tiếng khe khẽ, tắt lịm. Wiktionary xác nhận: faint, muffled.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ám\": bộ 音 (âm thanh) + nghĩa mờ — hình dung âm (tiếng) ám (mờ tối) không rõ, như tiếng vọng xa xăm tắt lịm. | Gương Hán-Việt | ám — liên hệ với \"ám\" trong \"mờ ám\", \"ám muội\" — cùng nghĩa mờ không rõ ràng | Mở khoá kiến thức | Biết 韽 giúp đọc thơ cổ mô tả âm thanh mờ nhạt, tiếng vọng xa xăm trong không gian tĩnh lặng.", "Tự nguyên_Xie": "韽 mô tả âm thanh mờ nhạt, tiếng thì thầm tắt dần. Wiktionary ghi nghĩa (of sound) faint; muffled. Bộ 音 (âm thanh) là thành phần ý nghĩa. Chữ dùng trong ghép đôi 韽韽 (âm thanh mờ nhạt liên tục). Chữ tạo muộn, không thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "韽", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "酓 + 音", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酓音", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "酓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "音", "Unihan_Simplified (Chữ Giản thể)": "韽", "Unihan_Traditional (Chữ Phồn thể)": "韽", "Pinyin_Xie": "ān", "Âm Hán Việt_Xie": "ám", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ miêu tả âm thanh nhỏ nhẹ, hòa nhã hoặc làm danh từ chỉ âm thanh đó. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飳', '{"9000": "7989.0", "Chữ Trung Quốc": "飳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 13 | nét | 飳 | tẩu | tượng hình | thuộc bộ thực phẩm (食) | 飳 thuộc bộ 食 (thực, đồ ăn/thức ăn). Không có cấu trúc IDS hay glyphOrigin. Căn cứ bộ 食, đây là chữ liên quan đến thức ăn, nhưng nghĩa cụ thể chưa xác định. Chữ tạo muộn, không thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tẩu\": bộ 食 (thức ăn) — đây là chữ cực hiếm trong nhóm 食 bộ, nghĩa chưa xác định rõ. | Gương Hán-Việt | tẩu — gần như không dùng; chữ cực hiếm | Mở khoá kiến thức | Biết 飳 giúp nhận diện chữ hiếm trong bộ 食 khi tra từ điển cổ tự.", "Tự nguyên_Xie": "飳 không có glyphOrigin từ Wiktionary. Bộ 食 (thức ăn) là bộ thủ. Nghĩa và cấu trúc chưa được xác định rõ trong các nguồn học thuật. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "飳", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 主", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠主", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "主", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "飳", "Unihan_Traditional (Chữ Phồn thể)": "飳", "Pinyin_Xie": "tǒu", "Âm Hán Việt_Xie": "tẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ cổ chỉ một loại bánh bột mì, ít dùng trong tiếng Trung hiện đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飸', '{"9000": "7990.0", "Chữ Trung Quốc": "飸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 14 | nét | 飸 | thao | tượng hình | thuộc bộ thực phẩm (食) | 飸 thuộc bộ 食 (thực, đồ ăn). Không có cấu trúc IDS hay glyphOrigin. Căn cứ bộ 食, đây là chữ liên quan đến thức ăn. Nghĩa cụ thể không xác định được. Chữ tạo muộn, không thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thao\": bộ 食 (thức ăn) — chữ hiếm trong nhóm 食, liên tưởng đến \"thao túng\" thức ăn. | Gương Hán-Việt | thao — gần như không dùng; chữ cực hiếm | Mở khoá kiến thức | Biết 飸 giúp nhận diện chữ hiếm trong bộ 食 khi tra từ điển cổ tự.", "Tự nguyên_Xie": "飸 không có glyphOrigin từ Wiktionary. Bộ 食 (thức ăn) là bộ thủ. Nghĩa và cấu trúc chưa xác định trong nguồn học thuật. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "飸", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "号 + 食", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰号食", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "号", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "食", "Unihan_Simplified (Chữ Giản thể)": "飸", "Unihan_Traditional (Chữ Phồn thể)": "飸", "Pinyin_Xie": "tāo", "Âm Hán Việt_Xie": "thao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ để miêu tả tính tham ăn hoặc kết hợp thành từ ghép chỉ sự thèm thuồng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('餆', '{"9000": "7991.0", "Chữ Trung Quốc": "餆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 14 | nét | 餆 | diêu | tượng hình | loại bánh ngọt thời cổ | 餆 thuộc bộ 食 (thực, đồ ăn). Không có cấu trúc IDS rõ ràng. Bộ 食 xác định đây là loại thức ăn; nghĩa là một loại bánh ngọt hoặc bánh nướng cổ đại. Wiktionary xác nhận: a kind of cake or pastry.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diêu\": bộ 食 (thức ăn) — hình dung bánh diêu (diệu kỳ ngon miệng) được làm từ thời cổ đại xa xôi. | Gương Hán-Việt | diêu — gần như không dùng trong tiếng Việt; chỉ gặp trong cổ văn ẩm thực | Mở khoá kiến thức | Biết 餆 giúp đọc các văn bản cổ đại mô tả thực phẩm và bánh trái Trung Hoa.", "Tự nguyên_Xie": "餆 chỉ một loại bánh hoặc bánh ngọt thời cổ đại. Wiktionary ghi nhận nghĩa a kind of cake or pastry, với âm Hán cổ trung đại là yáo. Bộ 食 (thức ăn) xác nhận đây là loại thực phẩm. Chữ tạo muộn, không thấy trong giáp cốt/kim văn. Loại bánh cụ thể này không còn được ghi chép chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "醆", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 兆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠兆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "餆", "Unihan_Traditional (Chữ Phồn thể)": "餆", "Pinyin_Xie": "yáo", "Âm Hán Việt_Xie": "diêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò danh từ chỉ các món ăn ngon trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('駡', '{"9000": "7992.0", "Chữ Trung Quốc": "駡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 16 | nét | 駡 | mạ | tượng hình | mắng chửi, la hét | 駡 là dị thể của 罵 (mắng chửi). Cấu trúc chính: bộ trên gợi hình hai chữ 口 (miệng) — hai miệng cùng la hét. Phần dưới là 馬 (ngựa). Hội ý: hai miệng la hét trên lưng ngựa — tiếng la lối om sòm. Không có IDS rõ trong dữ liệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạ\": hai miệng (口口) chửi rủa, ngựa (馬) hí vang — hình dung tiếng mạ lị om sòm như ngựa hí. | Gương Hán-Việt | mạ — xuất hiện trong \"mắng mạ\", \"mạ lị\" (罵詈); tiếng Việt mượn âm mạ với nghĩa mắng chửi | Mở khoá kiến thức | Biết 駡 (biến thể của 罵) mở khoá 罵人 (mắng người), 罵街 (chửi đường phố), 咒罵 (chửi rủa).", "Tự nguyên_Xie": "駡 là biến thể viết của 罵 (chính tự). 罵 = 两口 (hai miệng) + 馬 (ngựa) — hội ý: hai miệng hét to như tiếng ngựa hí, tức là mắng chửi om sòm. Nghĩa gốc và hiện đại đều là mắng nhiếc, chửi rủa. Chưa có nguồn học thuật xác nhận cấu trúc riêng của 駡. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "la mắng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "吅 + 馬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱吅馬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "駡", "Unihan_Traditional (Chữ Phồn thể)": "駡", "Pinyin_Xie": "mà", "Âm Hán Việt_Xie": "mạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ vị ngữ trong câu để biểu thị hành vi trách phạt bằng lời nói. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('駷', '{"9000": "7993.0", "Chữ Trung Quốc": "駷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 17 | nét | 駷 | tủng | tượng hình | thúc ngựa đi nhanh bằng roi | 駷 thuộc bộ 馬 (mã, ngựa). Không có cấu trúc IDS rõ ràng. Wiktionary ghi: to use a riding whip to keep a horse walking fast. Bộ 馬 xác định hành động liên quan đến ngựa — dùng roi thúc ngựa chạy đều.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tủng\": bộ 馬 (ngựa) — hình dung roi thúc (tủng tủng) ngựa phi đều, không để chùng bước. | Gương Hán-Việt | tủng — gần như không dùng trong tiếng Việt; chỉ xuất hiện trong cổ văn về cưỡi ngựa | Mở khoá kiến thức | Biết 駷 giúp đọc văn bản cổ đại mô tả kỹ thuật cưỡi ngựa và thuật ngữ quân sự.", "Tự nguyên_Xie": "駷 chỉ hành động dùng roi cưỡi ngựa để giữ ngựa đi đều và nhanh. Wiktionary xác nhận: to use a riding whip to keep a horse walking fast. Bộ 馬 (ngựa) là thành phần ý nghĩa. Chữ tạo muộn, không thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "駷", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 束", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬束", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "束", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "駷", "Unihan_Traditional (Chữ Phồn thể)": "駷", "Pinyin_Xie": "sǒng", "Âm Hán Việt_Xie": "tủng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động thúc ngựa hoặc nhún vai. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('騼', '{"9000": "7994.0", "Chữ Trung Quốc": "騼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 21 | nét | 騼 | lộc | tượng hình | ngựa hoang, ngựa dã thú | 騼 thuộc bộ 馬 (mã, ngựa). Không có cấu trúc IDS rõ ràng. Wiktionary xác nhận: wild horse. Bộ 馬 là thành phần ý nghĩa chính. Đây là loại ngựa hoang sống tự do, chưa được thuần hóa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lộc\": bộ 馬 (ngựa) — hình dung ngựa lộc (lộc là may mắn, tự do) chạy hoang dã trên thảo nguyên, chưa bị thuần hoá. | Gương Hán-Việt | lộc — hiếm dùng độc lập; đừng nhầm với 鹿 (lộc/hươu) | Mở khoá kiến thức | Biết 騼 giúp đọc các văn bản cổ mô tả ngựa hoang và động vật hoang dã thảo nguyên.", "Tự nguyên_Xie": "騼 chỉ ngựa hoang, ngựa dã sống trong thiên nhiên. Wiktionary xác nhận: wild horse. Bộ 馬 (ngựa) là thành phần ý nghĩa. Chữ tạo muộn. Không thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tao", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 鹿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬鹿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鹿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "騼", "Unihan_Traditional (Chữ Phồn thể)": "騼", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loài ngựa hoang hoặc lừa hoang thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魜', '{"9000": "7995.0", "Chữ Trung Quốc": "魜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 13 | nét | 魜 | nhâm | tượng hình | người cá, nhân ngư | 魜 thuộc bộ 魚 (ngư, cá). Không có glyphOrigin từ Wiktionary. Bộ 魚 xác định đây là loài thủy sinh. Theo nghĩa đã ghi nhận (mermaid; manatee), đây là sinh vật biển được miêu tả trong thần thoại hoặc tự nhiên cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhâm\": bộ 魚 (cá) — hình dung nhâm (mang theo) chất nhân ngư huyền bí — loài sinh vật nửa người nửa cá trong truyền thuyết. | Gương Hán-Việt | nhâm — hiếm dùng; chỉ gặp trong cổ văn thần thoại hoặc sinh học cổ đại | Mở khoá kiến thức | Biết 魜 giúp đọc các đoạn cổ văn mô tả sinh vật biển huyền bí và thần thoại Trung Hoa.", "Tự nguyên_Xie": "魜 chỉ loài sinh vật biển huyền thoại — nhân ngư (người cá) hoặc lợn biển (manatee). Wiktionary ghi nghĩa mermaid; manatee. Không có glyphOrigin học thuật. Bộ 魚 (cá) xác định đây là sinh vật thủy sinh. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "霭", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 人", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚人", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "人", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "魜", "Unihan_Traditional (Chữ Phồn thể)": "魜", "Pinyin_Xie": "rén", "Âm Hán Việt_Xie": "nhâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ loài cá có hình dạng giống con người theo truyền thuyết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鰫', '{"9000": "7996.0", "Chữ Trung Quốc": "鰫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 21 | nét | 魚 | ngư | biểu nghĩa | cá | 容 | dung | biểu âm | cho âm yóng | 鰫 = 魚 (Ngư, biểu nghĩa: cá) + 容 (Dung, biểu âm); chữ hình thanh. Bộ 魚 xác định đây là loài cá. 容 cung cấp âm đọc. Nghĩa gốc là một loài cá lớn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dung\": 魚 (cá, biểu nghĩa) + 容 (biểu âm: dung chứa) — hình dung loài cá lớn có thể dung chứa nhiều thứ bên trong. | Gương Hán-Việt | dung — hiếm dùng; chủ yếu trong từ điển chuyên ngành ngư nghiệp cổ đại | Mở khoá kiến thức | Biết 鰫 giúp đọc các văn bản cổ đại về ngư nghiệp và phân loại sinh vật biển.", "Tự nguyên_Xie": "鰫 là chữ hình thanh chỉ một loài cá (được Wiktionary ghi nhận là Triton, có thể là cá mú lớn hoặc cá to thuộc loài khác). 魚 (cá) cho nghĩa, 容 cho âm. Chữ tạo muộn; không có giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá mè", "Hạng Tần Suất (Jun Da)": "7996.0", "Tần Suất % (Jun Da)": "99.9993297297", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 容", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚容", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "容", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鰫", "Unihan_Traditional (Chữ Phồn thể)": "鰫", "Pinyin_Xie": "yóng", "Âm Hán Việt_Xie": "dong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loài cá nước ngọt thuộc họ cá chép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鱽', '{"9000": "7997.0", "Chữ Trung Quốc": "鱽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 10 | nét | 鱽 | đao | tượng hình | cá đao, cá kiếm nhỏ | 鱽 là dạng giản hóa của 魛 (thay bộ 魚 truyền thống bằng bộ 鱼 giản thể). Bộ 魚 (ngư) xác định đây là loài cá. Wiktionary ghi: the mullet — một loài cá biển.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đao\": bộ 魚 (cá) — hình dung cá đao thân dài như lưỡi đao sắc, bơi nhanh dưới nước. | Gương Hán-Việt | đao — hiếm dùng; chủ yếu trong từ điển sinh học cá biển | Mở khoá kiến thức | Biết 鱽 giúp nhận diện tên loài cá trong văn bản ngư nghiệp và sinh học cổ đại.", "Tự nguyên_Xie": "鱽 là giản thể của 魛, một dạng viết thay thế cho cá đao/cá trích nhỏ (mullet). Wiktionary: {{Han simp|魛|f=魚|t=鱼}} — chỉ đơn giản hóa bộ 魚. Nghĩa là một loại cá biển. Không có phân tích tự hình cổ đại rõ ràng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá đao; cá hố", "Hạng Tần Suất (Jun Da)": "7997.0", "Tần Suất % (Jun Da)": "99.9993317968", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 刀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼刀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鱽", "Unihan_Traditional (Chữ Phồn thể)": "魛", "Pinyin_Xie": "dāo", "Âm Hán Việt_Xie": "đao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loài cá có thân dài dẹt giống hình con dao. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲬', '{"9000": "7998.0", "Chữ Trung Quốc": "鲬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 鲬 | dũng | tượng hình | cá đầu dẹt (Platycephalus) | 鲬 thuộc bộ 魚 (ngư, cá) dạng giản thể. Không có cấu trúc IDS hay glyphOrigin từ Wiktionary. Căn cứ tên khoa học (flathead — cá đầu dẹt), đây là loài cá biển có đầu dẹp đặc trưng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dũng\": bộ 魚 (cá) — hình dung con cá dũng mãnh nằm phục dưới đáy biển với cái đầu dẹt. | Gương Hán-Việt | dũng — hiếm dùng; chủ yếu trong từ điển ngư nghiệp chuyên ngành | Mở khoá kiến thức | Biết 鲬 giúp đọc tên loài cá trong văn bản sinh học biển và từ điển chuyên ngành.", "Tự nguyên_Xie": "鲬 không có glyphOrigin từ Wiktionary. Đây là tên loài cá đầu dẹt (flathead fish, Platycephalus sp.) — một loài cá biển đáy thường gặp ở Đông Nam Á và Đông Á. Bộ 魚 (cá) là thành phần ý nghĩa. Chữ tạo muộn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá đuôi trâu (một loại cá, mình dài, dẹp mà phẳng, màu nâu vàng, phần đầu dẹp và to, có vằn nâu đen, không có bong bóng. Sống ở biển.)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 甬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼甬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲬", "Unihan_Traditional (Chữ Phồn thể)": "鲬", "Pinyin_Xie": "yǒng", "Âm Hán Việt_Xie": "dũng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loài cá biển có đầu dẹt và to. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶆', '{"9000": "7999.0", "Chữ Trung Quốc": "鶆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 19 | nét | 來 | lai | biểu âm | cho âm lái | 鳥 | điểu | biểu nghĩa | chim | 鶆 = 來 (Lai, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim); chữ hình thanh. Bộ 鳥 xác định đây là loài chim. 來 cung cấp âm đọc. Wiktionary ghi chỉ dùng trong 鶆鳩 và 鶆䴈 — có thể là chim bồ câu đặc biệt hoặc chim chạy lớn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lai\": 鳥 (chim, biểu nghĩa) + 來 (biểu âm: đến) — hình dung loài chim lai (từ phương xa đến), chim di trú. | Gương Hán-Việt | lai — hiếm dùng; chỉ xuất hiện trong tên ghép 鶆鳩, 鶆䴈 | Mở khoá kiến thức | Biết 鶆 giúp đọc tên loài chim trong văn bản điểu học cổ đại.", "Tự nguyên_Xie": "鶆 là chữ hình thanh: 鳥 (chim) + 來 (biểu âm). Wiktionary: chỉ dùng trong 鶆鳩 (loài chim bồ câu?) và 鶆䴈. Đây là tên loài chim cụ thể, không dùng độc lập. Chữ tạo muộn, không thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đà điểu Châu Mỹ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "來 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰來鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "來", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鶆", "Unihan_Traditional (Chữ Phồn thể)": "鶆", "Pinyin_Xie": "lái", "Âm Hán Việt_Xie": "lai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ để chỉ một loài chim lớn giống đà điểu ở khu vực châu Mỹ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶊', '{"9000": "8000.0", "Chữ Trung Quốc": "鶊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 19 | nét | 鶊 | canh | tượng hình | chim hoàng oanh, chim vàng anh | 鶊 thuộc bộ 鳥 (điểu, chim). Wiktionary ghi chỉ dùng trong 鶬鶊 — tên loài chim oanh vàng (oriole). Không có cấu trúc IDS rõ ràng. Bộ 鳥 xác định đây là loài chim — cụ thể là chim vàng anh tiếng hót hay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"canh\": bộ 鳥 (chim) — hình dung chim vàng anh hót canh (canh gác) chào bình minh mùa xuân. | Gương Hán-Việt | canh — hiếm dùng độc lập; chỉ xuất hiện trong tên ghép 鶬鶊 | Mở khoá kiến thức | Biết 鶊 giúp đọc các bài thơ Đường miêu tả chim vàng anh và cảnh mùa xuân.", "Tự nguyên_Xie": "鶊 chỉ dùng trong 鶬鶊 (hoàng oanh, chim vàng anh). Wiktionary xác nhận: {{zh-only|鶬鶊}}. Đây là loài chim nổi tiếng trong thơ ca Trung Hoa với tiếng hót trong trẻo. 鶬鶊 (oriole) xuất hiện nhiều trong thơ cổ điển như biểu tượng mùa xuân và tiếng gọi thiên nhiên. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鶊", "Hạng Tần Suất (Jun Da)": "8144.0", "Tần Suất % (Jun Da)": "99.9994739127", "GavinGrover_Once (Chiết tự trực tiếp)": "庚 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰庚鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "庚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鹒", "Unihan_Traditional (Chữ Phồn thể)": "鶊", "Pinyin_Xie": "gēng", "Âm Hán Việt_Xie": "canh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong văn học cổ để chỉ chim hoàng anh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鷿', '{"9000": "8001.0", "Chữ Trung Quốc": "鷿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 24 | nét | 鷿 | phích | tượng hình | chim bèo đầu, loài chim lặn nước nhỏ | 鷿 thuộc bộ 鳥 (điểu, chim). Wiktionary ghi chỉ dùng trong 鷿鷉 (pì tī) — loài chim lặn (grebe), có hình dạng giống vịt nhỏ hơn. Bộ 鳥 xác định đây là loài chim. Không có cấu trúc IDS rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phích\": bộ 鳥 (chim) — hình dung chim phích (phịch xuống nước) lặn ngụp như loài chim lặn (grebe) chuyên bắt cá. | Gương Hán-Việt | phích — hiếm dùng; chỉ xuất hiện trong tên ghép 鷿鷉 | Mở khoá kiến thức | Biết 鷿 giúp nhận diện tên loài chim lặn trong từ điển sinh học và thơ ca miêu tả ao hồ.", "Tự nguyên_Xie": "鷿 chỉ dùng trong 鷿鷉 — loài chim lặn nước (grebe), hình dáng giống vịt nhỏ, sống ở ao hồ. Wiktionary: {{only used in|zh|鷿鷉}}. Cũng có 鷿鷈 là biến thể viết. Bộ 鳥 (chim) là thành phần ý nghĩa. Chữ tạo muộn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "逿", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "辟 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱辟鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "䴙", "Unihan_Traditional (Chữ Phồn thể)": "鷿", "Pinyin_Xie": "pì", "Âm Hán Việt_Xie": "phích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường kết hợp với chữ đề tạo thành từ ghép để chỉ loài chim lặn nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸁', '{"9000": "8002.0", "Chữ Trung Quốc": "鸁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 24 | nét | 鸁 | la | tượng hình | tên loài chim cổ đại | 鸁 là chữ tượng hình độc lập, chỉ tên một loài chim cổ đại. Không phân tích được thành các bộ thủ rõ ràng; chưa có nguồn học thuật về cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"la\": chữ chim hiếm gặp trong cổ thư, chỉ tên loài chim đã thất truyền. | Gương Hán-Việt | \"la\" — không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại dùng chữ này. | Mở khoá kiến thức | Biết chữ 鸁 giúp nhận diện tên chim cổ đại trong văn bản Hán cổ.", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} mà không giải thích cấu tạo. Chữ xuất hiện trong tổ hợp 須鸁 và 過鸁 — tên riêng hoặc tên loài chim. Chưa có nguồn học thuật xác định cấu trúc; chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màu xám; mỏ lết", "Hạng Tần Suất (Jun Da)": "8002.0", "Tần Suất % (Jun Da)": "99.9993390318", "GavinGrover_Once (Chiết tự trực tiếp)": "𣎆 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𣎆鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𣎆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鸁", "Unihan_Traditional (Chữ Phồn thể)": "鸁", "Pinyin_Xie": "luó", "Âm Hán Việt_Xie": "loa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ trong văn ngôn để chỉ con ốc sên hoặc một loài chim nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麞', '{"9000": "8003.0", "Chữ Trung Quốc": "麞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 22 | nét | 麞 | chương | tượng hình | con hoẵng (hươu nhỏ) | 麞 là dạng chữ cổ/dị thể của 獐 (chương — con hoẵng). Wiktionary ghi {{zh-see|獐|v}}, tức đây là dạng biến thể. Chưa phân tích được cấu tạo riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chương\": chữ bộ 鹿 (hươu) — con hoẵng (hươu nhỏ không sừng) sống trong rừng núi cổ đại. | Gương Hán-Việt | \"chương\" — không thông dụng trong tiếng Việt; dạng chính tắc là 獐. | Mở khoá kiến thức | Biết chữ 麞/獐 giúp đọc văn bản cổ về động vật hoang dã và tên địa danh liên quan.", "Tự nguyên_Xie": "Tiểu triện | 麞 là dị thể cổ của 獐 (zhāng), chỉ con hoẵng — một loài hươu nhỏ không có sừng. Chữ 獐 có bộ 犬 (khuyển) + 章 (chương, biểu âm), chỉ loài thú. Dạng 麞 dùng bộ 鹿 (lộc — hươu) thay bộ 犬, thể hiện rõ hơn đây là loài hươu. Chưa có nguồn học thuật chi tiết về sự chuyển biến này. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con chương (giống con hươu)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 章", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿章", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "章", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麞", "Unihan_Traditional (Chữ Phồn thể)": "麞", "Pinyin_Xie": "zhāng", "Âm Hán Việt_Xie": "chương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ chỉ loài thú rừng giống hươu nhưng nhỏ hơn và không có gạc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼏', '{"9000": "8004.0", "Chữ Trung Quốc": "鼏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼎 | Số nét | 14 | nét | 冖 | mịch | biểu nghĩa | vật che phủ | 鼎 | đỉnh | biểu nghĩa | vạc đỉnh | 鼏 = 冖 (mịch, vật che phủ) + 鼎 (đỉnh, chiếc vạc). Wiktionary ghi ls=ic (hội ý): hai bộ kết hợp theo nghĩa — vật dùng để đậy lên miệng đỉnh. Đây là chữ hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mịch\": chữ hội ý — 冖 (nắp) úp lên 鼎 (đỉnh), chính là cái nắp đậy chiếc vạc nghi lễ. | Gương Hán-Việt | \"mịch\" — không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại dùng chữ này. | Mở khoá kiến thức | Biết chữ 鼏 giúp đọc văn bản cổ về đồ nghi lễ đồng thau thời Thương Chu.", "Tự nguyên_Xie": "Kim văn | Theo Wiktionary, 鼏 là chữ hội ý (hội ý/ideogrammic compound): 冖 (vật che, nắp đậy) + 鼎 (đỉnh — chiếc vạc ba chân dùng trong nghi lễ). Kết hợp nghĩa: nắp đậy của chiếc đỉnh. Xuất hiện trong kim văn, dùng trong văn cảnh nghi lễ cúng tế thời cổ đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái nắp đỉnh; cái lồng bàn; che, đậy", "Hạng Tần Suất (Jun Da)": "8004.0", "Tần Suất % (Jun Da)": "99.999341099", "GavinGrover_Once (Chiết tự trực tiếp)": "冖 + 鼎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱冖鼎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鼎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冖", "Unihan_Simplified (Chữ Giản thể)": "鼏", "Unihan_Traditional (Chữ Phồn thể)": "鼏", "Pinyin_Xie": "mì", "Âm Hán Việt_Xie": "mịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ nắp đậy đỉnh vạc hoặc làm động từ với nghĩa che đậy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼜', '{"9000": "8005.0", "Chữ Trung Quốc": "鼜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼓 | Số nét | 22 | nét | 鼜 | thảo | tượng hình | đánh trống ban đêm | 鼜 là chữ độc lập, không phân tích được thành các bộ thủ rõ ràng theo dữ liệu hiện có. Nghĩa: đánh trống vào ban đêm (dùng trong quân đội cổ). Chưa có nguồn học thuật về cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thảo\": chữ cổ chỉ hành động đánh trống vào đêm khuya trong quân trại. | Gương Hán-Việt | \"thảo\" — không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại dùng chữ này. | Mở khoá kiến thức | Biết chữ 鼜 giúp đọc văn bản quân sự và nghi lễ cổ đại liên quan đến trống.", "Tự nguyên_Xie": "Wiktionary ghi nghĩa 鼜 là ''đánh trống vào ban đêm'' (obs-std), phát âm cào/qì trong tiếng Quan thoại hiện đại. Không có chú thích cấu tạo trong nguồn. Chữ thuộc nhóm từ quân sự/nghi lễ cổ đại, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật xác định cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "霼", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鼓 + 蚤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱鼓蚤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蚤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼓", "Unihan_Simplified (Chữ Giản thể)": "鼜", "Unihan_Traditional (Chữ Phồn thể)": "鼜", "Pinyin_Xie": "qì", "Âm Hán Việt_Xie": "thảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ trong cổ văn để chỉ tiếng trống hoặc trống dùng tuần đêm trong quân đội. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼫', '{"9000": "8006.0", "Chữ Trung Quốc": "鼫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼠 | Số nét | 18 | nét | 鼫 | thạch | tượng hình | loài gặm nhấm cổ đại | 鼫 là chữ độc lập không phân tích được thành bộ thủ rõ ràng từ dữ liệu hiện có. Xuất hiện trong tổ hợp 鼫鼠 (loài chuột/sóc đất cổ đại). Chưa có nguồn học thuật về cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thạch\": 鼫 trong 鼫鼠 (thạch thử) — con chuột đất nổi tiếng với thành ngữ ''năm tài mà không tinh tài nào''. | Gương Hán-Việt | \"thạch\" — xuất hiện trong 鼫鼠 (thạch thử), ý nghĩa đã mờ trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết chữ 鼫 giúp hiểu thành ngữ 鼫鼠五技 trong văn học cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không giải thích cấu tạo chữ 鼫. Chữ chủ yếu xuất hiện trong tổ hợp 鼫鼠 — loài gặm nhấm được nhắc đến trong Thi Kinh và Tuân Tử với thành ngữ 鼫鼠五技 (chuột đất năm tài — biết nhiều thứ nhưng chẳng tinh thứ nào). Tiểu triện hiện có. Chưa có nguồn học thuật xác định cấu trúc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con chuột chũi", "Hạng Tần Suất (Jun Da)": "8006.0", "Tần Suất % (Jun Da)": "99.9993431661", "GavinGrover_Once (Chiết tự trực tiếp)": "鼠 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鼠石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "石", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼠", "Unihan_Simplified (Chữ Giản thể)": "鼫", "Unihan_Traditional (Chữ Phồn thể)": "鼫", "Pinyin_Xie": "shí", "Âm Hán Việt_Xie": "thạch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ loài chuột lớn hoặc chuột chũi trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盬', '{"9000": "8012.0", "Chữ Trung Quốc": "盬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 18 | nét | 盬 | cổ | tượng hình | muối tự nhiên, hồ muối | 盬 là chữ độc lập có bộ 鹵 (lỗ — muối) hoặc 盐 liên quan. Wiktionary chỉ ghi {{Han etym}} mà không giải thích cấu tạo. Nghĩa liên quan đến muối tự nhiên, hồ muối không tinh chế.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cổ\": chữ chỉ hồ muối tự nhiên — muối thô chưa tinh chế, dùng trong văn bản kinh tế cổ đại. | Gương Hán-Việt | \"cổ\" — không có từ Hán-Việt thông dụng dùng chữ này trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết chữ 盬 giúp đọc văn bản kinh tế và địa lý cổ đại về muối tự nhiên.", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} không có nội dung. Theo các từ điển học thuật, 盬 chỉ muối tự nhiên hoặc hồ muối (brine pit), phân biệt với muối đã tinh chế. Cũng có nghĩa phụ là làm việc bất cẩn/không chú tâm (trong thơ ca cổ). Chưa có nguồn học thuật chi tiết về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ruộng làm muối; nhàn rỗi", "Hạng Tần Suất (Jun Da)": "8012.0", "Tần Suất % (Jun Da)": "99.9993504011", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "盬", "Unihan_Traditional (Chữ Phồn thể)": "盬", "Pinyin_Xie": "gǔ", "Âm Hán Việt_Xie": "cổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ hồ muối tự nhiên hoặc làm tính từ chỉ sự lỏng lẻo, không bền chắc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祅', '{"9000": "8013.0", "Chữ Trung Quốc": "祅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 8 | nét | 祅 | yêu | tượng hình | tai ương, yêu quái | 祅 có bộ 示 (thị — thần linh, nghi lễ) liên quan. Chữ gần với 祆 (hỏa thần Zoroaster) hoặc 妖 (yêu quái). Không có chú thích cấu tạo chi tiết. Nghĩa: tai ương, điều xui xẻo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yêu\": bộ 示 (thần linh) + nghĩa tai ương — ''yêu'' 妖 (yêu quái), điều xui xẻo từ thế giới siêu nhiên. | Gương Hán-Việt | \"yêu\" — liên hệ với 妖 (yêu quái) trong tiếng Việt. | Mở khoá kiến thức | Biết chữ 祅 giúp đọc văn bản tôn giáo và bói toán cổ đại về tai ương.", "Tự nguyên_Xie": "Không có giải thích cấu tạo trong Wiktionary cho 祅. Chữ mang bộ 示 (thị — thần linh), liên quan đến tai ương hoặc điều xui xẻo từ thế giới siêu nhiên. Âm Hán-Việt ''yêu'' gần với 妖 (yêu quái). Chưa có nguồn học thuật xác định ls code; chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Hỏa giáo", "Hạng Tần Suất (Jun Da)": "8013.0", "Tần Suất % (Jun Da)": "99.9993514347", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 夭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻夭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祅", "Unihan_Traditional (Chữ Phồn thể)": "祅", "Pinyin_Xie": "yāo", "Âm Hán Việt_Xie": "yêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ điềm xấu tai ương hoặc làm tính từ chỉ sự quái dị, tà ác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禭', '{"9000": "8014.0", "Chữ Trung Quốc": "禭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 16 | nét | 禭 | toại | tượng hình | y phục mai táng, vật tùy táng | 禭 có bộ 衣 (y — quần áo) liên quan, nghĩa là áo mai táng hoặc đồ vật chôn theo người chết. Không có chú thích cấu tạo chi tiết trong các nguồn học thuật. Chưa có dữ liệu ls code.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toại\": chữ thuộc lĩnh vực tang lễ — y phục và vật phẩm chôn theo người quá cố. | Gương Hán-Việt | \"toại\" — không có từ Hán-Việt thông dụng dùng chữ này trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết chữ 禭 giúp đọc văn bản tang lễ và khảo cổ học cổ đại.", "Tự nguyên_Xie": "Không có giải thích cấu tạo trong Wiktionary cho 禭. Theo từ điển học thuật, 禭 chỉ y phục hoặc vật phẩm được chôn theo người chết trong tang lễ. Chữ thuộc nhóm từ ngữ tang lễ cổ đại. Chưa có nguồn học thuật xác định cấu trúc; chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vàng mã; tặng quần áo; biếu quần áo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 遂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻遂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "遂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禭", "Unihan_Traditional (Chữ Phồn thể)": "禭", "Pinyin_Xie": "suì", "Âm Hán Việt_Xie": "tuế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc đem quần áo hoặc đồ khâm liệm đến viếng người đã khuất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糱', '{"9000": "8015.0", "Chữ Trung Quốc": "糱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 22 | nét | 糱 | niết | tượng hình | lúa mầm, mạch nha | 糱 có bộ 米 (mễ — gạo, ngũ cốc) liên quan. Wiktionary ghi {{Han etym|糵}} — đây là dị thể của 糵 (niết). Nghĩa: hạt ngũ cốc đã mọc mầm, mạch nha, men. Chưa có chú thích cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niết\": lúa đã mọc mầm — hạt ngũ cốc nảy mầm thành mạch nha, nguyên liệu ủ rượu truyền thống. | Gương Hán-Việt | \"niết\" — không thông dụng trong tiếng Việt; mạch nha/men ủ thường dùng từ thuần Việt. | Mở khoá kiến thức | Biết chữ 糱 giúp đọc văn bản nông nghiệp và ẩm thực học cổ Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym|糵}}, tức 糱 là dị thể của 糵 (niè — mạch nha/yeast). Nghĩa: hạt ngũ cốc đã nảy mầm (grain sprout), mạch nha, hoặc men dùng trong ủ rượu. Âm Middle Chinese: oc=y. Chữ quan trọng trong văn bản nông nghiệp và ẩm thực cổ đại. Chưa có nguồn học thuật chi tiết về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mầm, cây mạ", "Hạng Tần Suất (Jun Da)": "8015.0", "Tần Suất % (Jun Da)": "99.9993545354", "GavinGrover_Once (Chiết tự trực tiếp)": "辥 + 米", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱辥米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "糱", "Unihan_Traditional (Chữ Phồn thể)": "糱", "Pinyin_Xie": "niè", "Âm Hán Việt_Xie": "nghiệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ mầm ngũ cốc đã lên men dùng để ủ rượu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('縂', '{"9000": "8016.0", "Chữ Trung Quốc": "縂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 15 | nét | 縂 | tổng | tượng hình | dị thể cổ của 總 (tổng — tất cả) | 縂 là dị thể cổ của 總 (tổng), có bộ 糸 (mịch — sợi chỉ). Cấu tạo tương tự 總 nhưng dạng viết khác. Không có chú thích cấu tạo riêng trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tổng\": dị thể cổ của 總 — bộ 糸 (sợi chỉ) ''tổng hợp tất cả các sợi lại''. | Gương Hán-Việt | \"tổng\" trong ''tổng thống'', ''tổng hợp'', ''tổng cộng'' — từ rất thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết chữ 縂 (dị thể 總) mở khoá hàng chục từ Hán-Việt dùng ''tổng'': tổng thống, tổng hợp, tổng kết...", "Tự nguyên_Xie": "縂 là dạng cổ/dị thể của 總 (zǒng — tổng cộng, tất cả). Bộ 糸 (mịch — sợi chỉ) biểu nghĩa gốc: bó tất cả các sợi lại với nhau. Nghĩa mở rộng: tất cả, toàn bộ, tổng cộng. Dạng chính tắc trong tiếng Trung hiện đại là 总 (giản thể) hoặc 總 (phồn thể). Chưa có nguồn học thuật chi tiết về sự khác biệt dạng viết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tổng; như \"tổng cộng; tổng sản lượng\" (gdhn)", "Hạng Tần Suất (Jun Da)": "8016.0", "Tần Suất % (Jun Da)": "99.9993555689", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 总", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹总", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "总", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "縂", "Unihan_Traditional (Chữ Phồn thể)": "縂", "Pinyin_Xie": "zǒng", "Âm Hán Việt_Xie": "tổng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Tính từ | 形容词 | Chữ này làm động từ chỉ hành động gom tụ lại hoặc làm phó từ với nghĩa luôn luôn, tổng cộng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠥', '{"9000": "8017.0", "Chữ Trung Quốc": "蠥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 22 | nét | 蠥 | nghiệt | tượng hình | dị thể cổ của 孽 (nghiệt — tai họa, tội lỗi) | 蠥 là dị thể cổ của 孽 (nghiệt), có bộ 蟲 (trùng — sâu bọ) liên quan. Wiktionary ghi là alt form của 孽 và cũng mang nghĩa lo lắng/quan tâm. Chưa có chú thích cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghiệt\": dị thể cổ của 孽 — bộ 蟲 (sâu độc) tai họa, nghiệt chướng như sâu gặm nhấm. | Gương Hán-Việt | \"nghiệt\" trong ''nghiệt ngã'', ''báo nghiệt'' — từ thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết chữ 蠥/孽 giúp hiểu các từ Hán-Việt ''nghiệt chướng'', ''báo nghiệt'', ''tội nghiệt''.", "Tự nguyên_Xie": "Wiktionary ghi 蠥 là dạng cổ (obs-std) của 孽 (niè — tai họa, con ngoài giá thú) và mang nghĩa lo lắng/quan tâm. Âm Middle Chinese mc=y, oc=y. Bộ 蟲 (trùng) trong dạng này gợi ý liên quan đến sâu độc/tai họa. Chưa có nguồn học thuật chi tiết về sự phân kỳ dạng viết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蠥", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "辥 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱辥虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠥", "Unihan_Traditional (Chữ Phồn thể)": "蠥", "Pinyin_Xie": "niè", "Âm Hán Việt_Xie": "nghiệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong văn cổ để chỉ các tai họa do côn trùng hoặc điềm gở gây ra. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軷', '{"9000": "8018.0", "Chữ Trung Quốc": "軷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 12 | nét | 軷 | bạt | tượng hình | lễ tế thần đường trước khi lên đường | 軷 có bộ 車 (xa — xe) liên quan, nghĩa là lễ tế thần đường thực hiện trước khi khởi hành. Không có chú thích cấu tạo chi tiết. Chưa có dữ liệu ls code.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạt\": bộ 車 (xe) — lễ tế thần đường trước khi chiếc xe lên đường, cầu an cho hành trình. | Gương Hán-Việt | \"bạt\" — không có từ Hán-Việt thông dụng dùng chữ này trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết chữ 軷 giúp đọc văn bản nghi lễ và giao thông cổ đại Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi 軷 là ''lễ cúng thần đường trước khi khởi hành'' (sacrifice made to the god of the road prior to journey). Bộ 車 (xa — xe) gợi ý liên quan đến xe cộ và di chuyển. Chữ thuộc nhóm nghi lễ giao thông cổ đại. Chưa có nguồn học thuật chi tiết về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hy sinh", "Hạng Tần Suất (Jun Da)": "8018.0", "Tần Suất % (Jun Da)": "99.9993576361", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 犮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車犮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "軷", "Unihan_Traditional (Chữ Phồn thể)": "軷", "Pinyin_Xie": "bá", "Âm Hán Việt_Xie": "bạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ nghi lễ cúng tế cầu bình an trước khi khởi hành đi xa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄮', '{"9000": "8019.0", "Chữ Trung Quốc": "鄮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 14 | nét | 鄮 | mậu | tượng hình | địa danh, họ người | 鄮 có bộ 阜/邑 (ấp — làng/địa phương, thường viết là 阝 bên phải), nghĩa là tên địa danh. Không có chú thích cấu tạo chi tiết. Chữ chủ yếu dùng làm tên địa danh và họ người.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mậu\": bộ 邑 (ấp — địa phương) — tên một vùng đất cổ ở Chiết Giang, nay ít dùng ngoài nghiên cứu lịch sử. | Gương Hán-Việt | \"mậu\" — không có từ Hán-Việt thông dụng dùng chữ này trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết chữ 鄮 giúp nhận diện địa danh cổ và họ tên trong văn bản lịch sử Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi 鄮 dùng làm tên địa danh (zh-used2|p) và họ người (surname). Bộ 邑 (ấp, 阝phải) chỉ địa danh/làng xã. Âm mào. Vùng 鄮 là một huyện cổ ở Chiết Giang, Trung Quốc. Chưa có nguồn học thuật chi tiết về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "địa danh cổ", "Hạng Tần Suất (Jun Da)": "8019.0", "Tần Suất % (Jun Da)": "99.9993586696", "GavinGrover_Once (Chiết tự trực tiếp)": "貿 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰貿阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄮", "Unihan_Traditional (Chữ Phồn thể)": "鄮", "Pinyin_Xie": "mào", "Âm Hán Việt_Xie": "mậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò danh từ riêng để chỉ địa danh cổ Mậu Huyện thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('釱', '{"9000": "8020.0", "Chữ Trung Quốc": "釱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 釱 | đề | tượng hình | xiềng xích, cùm chân | 釱 có bộ 金 (kim — kim loại), nghĩa là xiềng xích hoặc cùm chân. Không có chú thích cấu tạo chi tiết. Chữ thuộc nhóm hình phạt cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đề\": bộ 金 (sắt) — cùm sắt xiềng chân tù nhân, hình phạt cổ đại. | Gương Hán-Việt | \"đề\" — không có từ Hán-Việt thông dụng dùng chữ này trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết chữ 釱 giúp đọc văn bản pháp luật và hình phạt cổ đại Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi 釱 nghĩa là xiềng xích/cùm chân (shackles, fetters), phát âm dì. Bộ 金 (kim) chỉ vật làm bằng kim loại. Đây là hình cụ bằng kim loại dùng trong hình phạt cổ đại. Cũng có âm đọc thứ hai. Chưa có nguồn học thuật chi tiết về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loại hình cụ như cái cùm chân; mang cùm chân; chốt trục xe", "Hạng Tần Suất (Jun Da)": "8020.0", "Tần Suất % (Jun Da)": "99.9993597032", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 大", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金大", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "大", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "釱", "Unihan_Traditional (Chữ Phồn thể)": "釱", "Pinyin_Xie": "dì", "Âm Hán Việt_Xie": "đại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ cái cùm chân hoặc động từ chỉ việc cùm chân phạm nhân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
